#!/bin/sh
read -r _ _ ZM_NEW_VER <<'ZM_VERSION_EOF'
# Version: 4.98
ZM_VERSION_EOF
set -e

GREEN="\033[1;32m"; CYAN="\033[1;36m"; YELLOW="\033[1;33m"; MAGENTA="\033[1;35m"; BLUE="\033[0;34m"; NC="\033[0m"; DGRAY="\033[38;5;244m"

_zmi_say() { echo -e "${CYAN}==>${NC} $*"; }
_zmi_ok() { echo -e "   ${GREEN}✓${NC} $*"; }
_zmi_step() { echo -e "   → $*"; }
_zmi_warn() { echo -e "   ${YELLOW}!${NC} $*"; }
if command -v apk >/dev/null 2>&1; then PM="apk"; INSTALL="apk add"
else PM="opkg"; INSTALL="opkg install"; fi
_zmi_has() {
	if [ "$PM" = apk ]; then apk info -e "$1" >/dev/null 2>&1
	else opkg list-installed 2>/dev/null | grep -q "^$1 "; fi
}
_zmi_pkg() {
	if _zmi_has "$1"; then _zmi_ok "Пакет $1 уже установлен"; return 0; fi
	_zmi_step "Устанавливаем пакет $1"
	$INSTALL "$1" >/dev/null 2>&1 || true
	if ! _zmi_has "$1"; then
		_zmi_step "Не получилось — обновляем список пакетов и пробуем ещё раз"
		$PM update >/dev/null 2>&1 || true
		$INSTALL "$1" >/dev/null 2>&1 || true
	fi
	if _zmi_has "$1"; then _zmi_ok "Пакет $1 установлен"; return 0; fi
	_zmi_warn "Пакет $1 не установился — проверьте интернет на роутере. $2"
	return 1
}
clear 2>/dev/null || true
echo -e "${MAGENTA}Zapret Manager для LuCI и Web $ZM_NEW_VER — установка${NC}\n"
_zmi_say "Проверяем, что панель сейчас ничем не занята"

for _zm_pid in /tmp/zapret-manager-luci/*.pid; do
	[ -f "$_zm_pid" ] || continue
	_zm_job="$(basename "$_zm_pid" .pid)"
	case "$_zm_job" in versions|sysinfo|*_download|fk-guard) continue ;; esac
	if kill -0 "$(cat "$_zm_pid" 2>/dev/null)" 2>/dev/null && ! grep -q '^__DONE__' "/tmp/zapret-manager-luci/$_zm_job.log" 2>/dev/null; then
		echo -e "${YELLOW}Сейчас в панели идёт операция ($_zm_job) — дождитесь её окончания и запустите установку снова${NC}"
		exit 1
	fi
done

_zm_n=0
while [ -f /tmp/zm_uninstall_panel.sh ] && ps w 2>/dev/null | grep -q '[z]m_uninstall_panel\.sh'; do
	[ "$_zm_n" = 0 ] && _zmi_step "Панель сейчас удаляется — ждём окончания"
	if [ "$_zm_n" -ge 60 ]; then
		echo -e "${YELLOW}Удаление панели не закончилось за минуту — запустите установку чуть позже${NC}"
		exit 1
	fi
	sleep 1; _zm_n=$((_zm_n + 1))
done
_zmi_ok "Можно ставить"
_zmi_say "Убираем файлы прежней версии панели"
if [ -s /tmp/zapret-manager-luci/resolv.conf.zm-bak ]; then
	if [ -e /tmp/resolv.conf ]; then cat /tmp/zapret-manager-luci/resolv.conf.zm-bak > /tmp/resolv.conf 2>/dev/null || true
	else cat /tmp/zapret-manager-luci/resolv.conf.zm-bak > /etc/resolv.conf 2>/dev/null || true; fi
fi
rm -rf \
	/tmp/zapret-manager-luci* \
	/tmp/zm_uninstall_panel.sh \
	/tmp/luci-indexcache* \
	/tmp/luci-modulecache/* 2>/dev/null

_zmi_ok "Готово"
_zmi_say "Записываем файлы панели"
mkdir -p /opt/zapret-manager-luci
chmod 0755 /opt/zapret-manager-luci
_zm_old_ver="$(sed -n 's/^ZM_VERSION="\([0-9][0-9.]*\)"$/\1/p' /opt/zapret-manager-luci/backend.sh 2>/dev/null | head -n 1)"
_zmi_free() { df -kP "$1" 2>/dev/null | awk 'NR == 2 { print $4 + 0; f = 1 } END { if (!f) print 0 }'; }
_zmi_be=/opt/zapret-manager-luci/backend.sh
_zmi_stage="$_zmi_be.zm-new"
rm -f "$_zmi_stage" /tmp/zm-backend.sh.zm-new
[ "$(_zmi_free /tmp)" -gt 4096 ] && _zmi_stage=/tmp/zm-backend.sh.zm-new
sed "s/@ZM_VERSION@/$ZM_NEW_VER/" > "$_zmi_stage" << 'ZM_INSTALLER_EOF'
#!/bin/sh
umask 022
if [ "$1" = zm_watch ]; then
	[ -z "$ZM_WATCH_FORCE" ] && [ -f /opt/zapret-manager-luci/state/watch.off ] && exit 0
	mkdir -p /tmp/zapret-manager-luci 2>/dev/null; : > /tmp/zapret-manager-luci/watch.last 2>/dev/null
	_zw_idle() {
		local d=/tmp/zapret-manager-luci s=/opt/zapret-manager-luci/state e=/etc/zm-steer
		local pl=/usr/libexec/rpcd/zapret-manager want have t v st=0
		pidof rpcd >/dev/null 2>&1 || return 1
		ubus -t 5 list session >/dev/null 2>&1 || return 1
		ubus -t 15 call session access '{"ubus_rpc_session":"00000000000000000000000000000000","scope":"ubus","object":"session","function":"access"}' >/dev/null 2>&1
		[ "$?" = 7 ] && return 1
		if [ -x "$pl" ]; then
			ubus -t 5 list zapret-manager >/dev/null 2>&1 || return 1
			want="$(grep -c 'json_add_object' "$pl" 2>/dev/null)"
			have="$(ubus -v list zapret-manager 2>/dev/null | grep -c '^[[:space:]]*"')"
			if [ "${want:-0}" -gt 0 ] 2>/dev/null && [ "${have:-0}" -gt 0 ] 2>/dev/null && [ "$have" != "$want" ]; then return 1; fi
		fi
		[ -s "$s/strategy_test.backup" ] && return 1
		t="$(awk '$1 == "oom_kill" { print $2; exit }' /proc/vmstat 2>/dev/null)"
		[ -n "$t" ] && [ "$t" != "$(cat "$d/oom.seen" 2>/dev/null || echo 0)" ] && return 1
		[ -f "$d/resolv.conf.zm-bak" ] && return 1
		[ -f "$s/tg.watch" ] && return 1
		if grep -qx 'ru=isp' /opt/zapret-manager-luci/dns_net 2>/dev/null; then
			for t in /tmp/resolv.conf.d/resolv.conf.auto /tmp/resolv.conf.auto; do
				[ -s "$t" ] || continue
				v="$(awk '$1 == "nameserver" && ($2 ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/ || ($2 ~ /^[0-9A-Fa-f:]+$/ && $2 ~ /:.*:/)) && $2 !~ /^(127\.|0\.0\.0\.0$|::1$|[Ff][Ee]80:)/ && !u[$2]++ { print $2 }' "$t" | head -n 4 | tr '\n' ',' | sed 's/,$//')"
				[ -n "$v" ] && ! grep -qxF "ispips=$v" /opt/zapret-manager-luci/dns_net 2>/dev/null && return 1
				break
			done
		fi
		{ [ -e /usr/bin/netshift ] || [ -e /usr/lib/netshift ]; } && return 1
		if command -v steer >/dev/null 2>&1 && grep -qxF -e engine -e 'pkg steer' -e 'net zmwarp' -e 'net zmwarp4' "$e/owned" 2>/dev/null; then
			[ ! -f "$e/stopped" ] && [ -s "$e/sub.txt" ] && grep -qxF steer-spec "$e/owned" 2>/dev/null && return 1
			if [ ! -f "$e/stopped" ] && [ -s "$e/warp.up" ]; then
				[ -f "$d/steer/colo.last" ] || return 1
				t="$(date -r "$d/steer/colo.last" +%s 2>/dev/null || echo 0)"
				[ $(( $(date +%s) - t )) -lt 300 ] || return 1
			fi
		fi
		if grep -qx 'on=1' "$s/adblock/settings" 2>/dev/null; then
			t="$(awk -F= -v now="$(date +%s)" '$1 == "auto" { a = $2 } $1 == "updated" { u = $2 } END { print (a != "0" && u + 0 > 0 && now - u > 93600) ? 1 : 0 }' "$s/adblock/settings" 2>/dev/null)"
			if [ -f "$d/adblock.auto" ] || [ "$t" = 1 ]; then [ -n "$(find "$d/adblock.auto.try" -mmin -180 2>/dev/null)" ] || return 1; fi
			for t in $(sed -n 's/^conf-dir=\([^,]*\).*/\1/p' /var/etc/dnsmasq.conf.* 2>/dev/null | sort -u); do
				[ -s "$t/zm-adblock.conf" ] || return 1
				grep -qx 'stats=1' "$s/adblock/settings" 2>/dev/null && { [ -s "$t/zm-adblock-stats.conf" ] || return 1; }
			done
			if [ -s "$s/adblock/free.txt" ]; then
				t="$(cat /var/run/zm-adblock-free.pid 2>/dev/null)"
				[ -n "$t" ] && kill -0 "$t" 2>/dev/null || return 1
				nft list table inet zm_adblock_free >/dev/null 2>&1 || return 1
				for v in /var/etc/dnsmasq.conf.*; do [ "$v" -nt /var/etc/zm-adblock-free.conf ] && return 1; done
			fi
		elif [ -e /var/run/zm-adblock-free.pid ]; then return 1
		fi
		rm -f /tmp/zm-rpcd-slow /tmp/zm-rpcd-plugin.stamp "$s/fk.watch" "$d/steer.vpnwatch"
		return 0
	}
	_zw_idle && exit 0
fi

CONF="/etc/config/zapret"
ZM_VERSION="@ZM_VERSION@"
ZM_SCRIPT_URL="https://raw.githubusercontent.com/StressOzz/Zapret-Manager/refs/heads/main/ZapretManager_LuCI.sh"
GH_RAW="https://raw.githubusercontent.com"
GH_MAIN="https://github.com"
MT_URL_ITDOG="${GH_RAW}/StressOzz/Zapret-Manager/refs/heads/main/files/MagiTrickle/configAD.yaml"
MT_URL_IH1="${GH_RAW}/StressOzz/Zapret-Manager/refs/heads/main/files/MagiTrickle/config.yaml"
MT_URL_IH2="${GH_RAW}/StressOzz/Zapret-Manager/refs/heads/main/files/MagiTrickle/configOLD.yaml"
EXCLUDE_URL="${GH_RAW}/StressOzz/Zapret-Manager/refs/heads/main/zapret-hosts-user-exclude.txt"
FLOWSEAL_ZIP="${GH_MAIN}/Flowseal/zapret-discord-youtube/archive/refs/heads/main.zip"
FLOWSEAL_FAKE_RAW="${GH_MAIN}/Flowseal/zapret-discord-youtube/raw/refs/heads/main/bin"
STR_URL="${GH_RAW}/StressOzz/Zapret-Manager/refs/heads/main/files/StrYoutube"
ZAPRET_VER="72.20260307"
JOBS_DIR="/tmp/zapret-manager-luci"
ZM_STATE_DIR="/opt/zapret-manager-luci/state"
CRON_FILE="/etc/crontabs/root"
ZM_EV_FILE="$ZM_STATE_DIR/events.log"
ZM_EV_MAX=300
ZM_OOM_FILE="$ZM_STATE_DIR/oom.last"
_zm_ev_lvl() {
	case "$1" in
		*"не отвеча"*|*"не работа"*|*"недоступ"*|*"не запуст"*|*"не заработал"*|*"не скача"*|*"завис"*|*"не хватило памяти"*|*"не получ"*|*"пропал"*|*"перезапуска"*|*"не удалось"*|*"не видит"*|*"не принял"*|*"запускаем заново"*|*"восстанавливаем"*) echo warn ;;
		*"снова "*|*"вернул"*|*"возвращ"*|*"применена"*|*"применён"*|*"применены"*|*"обновлён"*|*"обновлены"*|*"выбрала"*|*"заменён"*) echo ok ;;
		*) echo info ;;
	esac
}
_zm_ev() {
	local m now f="$ZM_EV_FILE" lk="/tmp/zapret-manager-luci/ev.lock" n=0 lv
	m="$(printf '%s' "$1" | tr '\t\r\n\\' '    ' | sed 's/  */ /g; s/^ //; s/ $//')"
	[ -n "$m" ] || return 0
	now="$(date +%s)"; lv="$(_zm_ev_lvl "$m")"
	mkdir -p /tmp/zapret-manager-luci "${f%/*}" 2>/dev/null || return 0
	until mkdir "$lk" 2>/dev/null; do
		n=$((n + 1))
		if [ "$n" -ge 6 ]; then rm -rf "$lk"; mkdir "$lk" 2>/dev/null || return 0; break; fi
		sleep 1
	done
	[ -f "$f" ] || : > "$f"
	awk -F '\t' -v OFS='\t' -v t="$now" -v m="$m" -v l="$lv" -v max="$ZM_EV_MAX" '
		NF >= 4 { a[++n] = $0 }
		END {
			if (n > 0) { split(a[n], p, "\t") }
			if (n > 0 && p[4] == m && t >= p[1] && t - p[1] < 900) a[n] = t OFS (p[2] + 1) OFS p[3] OFS m
			else a[++n] = t OFS 1 OFS l OFS m
			for (i = (n > max ? n - max + 1 : 1); i <= n; i++) print a[i]
		}' "$f" > "$f.zmtmp" 2>/dev/null && mv -f "$f.zmtmp" "$f"
	rm -f "$f.zmtmp"
	rmdir "$lk" 2>/dev/null
	return 0
}
logger() {
	command logger "$@" 2>/dev/null
	case "$1 $2" in
		"-t zapret-manager") shift 2; [ "$1" = -- ] && shift; _zm_ev "$*" ;;
		"-t zm-steer") shift 2; [ "$1" = -- ] && shift; _zm_ev "Steer: $*" ;;
	esac
	return 0
}
zm_events() {
	local f="$ZM_EV_FILE" lim="$1" tot=0
	case "$lim" in ''|*[!0-9]*) lim=100 ;; esac
	[ "$lim" -gt "$ZM_EV_MAX" ] && lim="$ZM_EV_MAX"
	[ "$lim" -lt 1 ] && lim=1
	[ -s "$f" ] && tot="$(grep -c . "$f" 2>/dev/null)"
	printf '{"items":['
	[ -s "$f" ] && tail -n "$lim" "$f" | awk -F '\t' '
		function j(v) { gsub(/\\/, "\\\\", v); gsub(/"/, "\\\"", v); gsub(/[\001-\037]/, " ", v); return v }
		NF >= 4 && $1 ~ /^[0-9]+$/ && $2 ~ /^[0-9]+$/ { r[++n] = sprintf("{\"t\":%s,\"n\":%s,\"l\":\"%s\",\"m\":\"%s\"}", $1, $2, j($3), j($4)) }
		END { for (i = n; i >= 1; i--) printf "%s%s", (i < n ? "," : ""), r[i] }'
	printf '],"total":%s,"now":%s}\n' "${tot:-0}" "$(date +%s)"
}
zm_events_clear() {
	: > "$ZM_EV_FILE" 2>/dev/null
	rm -f "$ZM_OOM_FILE"
	echo '{"ok":true}'
}
_zm_oom_watch() {
	local n seen f=/tmp/zapret-manager-luci/oom.seen k d
	n="$(awk '$1 == "oom_kill" { print $2; exit }' /proc/vmstat 2>/dev/null)"
	case "$n" in ''|*[!0-9]*) return 0 ;; esac
	seen="$(cat "$f" 2>/dev/null)"
	case "$seen" in ''|*[!0-9]*) seen=0 ;; esac
	mkdir -p /tmp/zapret-manager-luci 2>/dev/null
	echo "$n" > "$f"
	[ "$n" -gt "$seen" ] || return 0
	d=$((n - seen))
	k="$(dmesg 2>/dev/null | sed -n 's/.*[Kk]illed process [0-9][0-9]* (\([^)]*\)).*/\1/p' | tail -n "$d" | awk 'NF && !s[$0]++' | head -n 4 | tr '\n' ',' | sed 's/,$//; s/,/, /g')"
	mkdir -p "${ZM_OOM_FILE%/*}" 2>/dev/null
	printf '%s\t%s\t%s\n' "$(date +%s)" "$d" "$k" > "$ZM_OOM_FILE"
	logger -t zapret-manager "Роутеру не хватило памяти — система закрыла ${k:-процесс}$([ "$d" -gt 1 ] && echo " (случаев: $d)")"
}
_zm_oom_json() {
	local at n k
	[ -s "$ZM_OOM_FILE" ] || { echo null; return; }
	IFS='	' read -r at n k < "$ZM_OOM_FILE"
	case "$at" in ''|*[!0-9]*) echo null; return ;; esac
	[ $(( $(date +%s) - at )) -lt 259200 ] || { echo null; return; }
	case "$n" in ''|*[!0-9]*) n=1 ;; esac
	printf '{"at":%s,"n":%s,"procs":"%s","ram_mb":%s,"zram":%s}' "$at" "$n" "$(esc "$k")" "$(awk '/^MemTotal:/ { print int($2 / 1024); exit }' /proc/meminfo 2>/dev/null || echo 0)" "$(_zram_on && echo true || echo false)"
}
ZM_GML_LINE='	ZM_GML="$(awk '\''$1 == "MemTotal:" { if ($2 > 0 && $2 <= 524288) printf "%dMiB", $2 / 2048; exit }'\'' /proc/meminfo 2>/dev/null)"; [ -n "$ZM_GML" ] && procd_set_param env GOMEMLIMIT="$ZM_GML"'
_zm_gml() {
	[ -n "$ZM_GML_ONE" ] || ZM_GML_ONE="$(awk '$1 == "MemTotal:" { m = int($2 / 8192); if (m < 16) m = 16; if (m > 128) m = 128; print m "MiB"; exit }' /proc/meminfo 2>/dev/null)"
	echo "${ZM_GML_ONE:-64MiB}"
}
_zm_gml_patch() {
	local f="$1" t
	[ -f "$f" ] || return 0
	grep -q 'GOMEMLIMIT\|procd_set_param env' "$f" && return 0
	[ "$(grep -c 'procd_set_param command' "$f")" = 1 ] || return 0
	t="$f.zmgml.$$"
	awk -v L="$ZM_GML_LINE" '{ print } !d && /procd_set_param command/ { print L; d = 1 }' "$f" > "$t" && [ -s "$t" ] && cat "$t" > "$f"
	rm -f "$t"
}
ZM_GHP_FILE="$ZM_STATE_DIR/ghproxy"
ZM_GHP_FAIL="$JOBS_DIR/ghproxy.fail"
ZM_GHP_LOG="$JOBS_DIR/ghproxy.log"
ZM_GHP_LIST="gh-proxy.org ghfast.top gh.llkk.cc ghproxy.net"
_zm_ghp_load() {
	[ -n "$ZM_GHP_MODE" ] && return 0
	ZM_GHP_MODE=off
	grep -qE '^mode=(auto|always)$' "$ZM_GHP_FILE" 2>/dev/null && ZM_GHP_MODE=auto
	return 0
}
_zm_gh_host() {
	case "$1" in
		https://raw.githubusercontent.com/*|https://github.com/*|https://codeload.github.com/*|https://objects.githubusercontent.com/*|https://release-assets.githubusercontent.com/*|https://gist.githubusercontent.com/*|https://gist.github.com/*) return 0 ;;
	esac
	return 1
}
_zm_ghp_say() {
	[ -n "$ZM_JOB_LOG" ] && printf '%s\n' "$1" >> "$ZM_JOB_LOG" 2>/dev/null
	mkdir -p "$JOBS_DIR" 2>/dev/null
	{ tail -n 39 "$ZM_GHP_LOG" 2>/dev/null; printf '%s|%s\n' "$(date +%s)" "$(printf '%s' "$1" | sed 's/^[[:space:]]*//')"; } > "$ZM_GHP_LOG.$$" 2>/dev/null && mv -f "$ZM_GHP_LOG.$$" "$ZM_GHP_LOG" 2>/dev/null
	return 0
}
_zm_ghp_why() {
	case "$1:$2" in
		curl:5|curl:6) echo "не нашёлся адрес (DNS)" ;;
		curl:7) echo "не удалось подключиться" ;;
		curl:28) echo "не ответил вовремя" ;;
		curl:35|wget:5) echo "ошибка защищённого соединения" ;;
		curl:52|curl:56|curl:18) echo "соединение оборвалось" ;;
		wget:4) echo "ошибка сети" ;;
		*) return 1 ;;
	esac
}
_zm_ghp_out() {
	local t="$1" a nx=""
	shift
	for a; do
		if [ -n "$nx" ]; then [ "$a" = - ] || printf '%s' "$a"; return 0; fi
		case "$t:$a" in
			curl:-o|curl:--output|wget:-O|wget:-qO|wget:--output-document) nx=1 ;;
			curl:-o?*) [ "${a#-o}" = - ] || printf '%s' "${a#-o}"; return 0 ;;
			wget:-qO?*) [ "${a#-qO}" = - ] || printf '%s' "${a#-qO}"; return 0 ;;
			wget:-O?*) [ "${a#-O}" = - ] || printf '%s' "${a#-O}"; return 0 ;;
		esac
	done
	return 0
}
_zm_ghp_exec() {
	local t="$1" pre="$2" a x=0
	shift 2
	for a; do
		[ "$x" = 0 ] && { set --; x=1; }
		if _zm_gh_host "$a"; then set -- "$@" "$pre$a"; else set -- "$@" "$a"; fi
	done
	command "$t" "$@"
}
_zm_ghp_run() {
	local t="$1" a gh="" rc why out nm m
	shift
	for a; do _zm_gh_host "$a" && { gh="$a"; break; }; done
	[ -n "$gh" ] || { command "$t" "$@"; return; }
	_zm_ghp_load
	command "$t" "$@"; rc=$?
	if [ "$rc" = 0 ]; then [ "$ZM_GHP_MODE" = off ] && rm -f "$ZM_GHP_FAIL" 2>/dev/null; return 0; fi
	why="$(_zm_ghp_why "$t" "$rc")" || return $rc
	if [ "$ZM_GHP_MODE" != auto ] || [ -n "$ZM_GHP_NOMIR" ]; then
		[ "$ZM_GHP_MODE" = off ] && { mkdir -p "$JOBS_DIR" 2>/dev/null; date +%s > "$ZM_GHP_FAIL" 2>/dev/null; }
		return $rc
	fi
	nm="${gh%%\?*}"; nm="${nm##*/}"; [ -n "$nm" ] || nm="$gh"
	out="$(_zm_ghp_out "$t" "$@")"
	if [ -z "$out" ] && [ "$t:$rc" != curl:6 ] && [ "$t:$rc" != curl:7 ]; then
		_zm_ghp_say "   · GitHub: $nm — $why. Через зеркало не повторяем: часть ответа уже получена"
		return $rc
	fi
	_zm_ghp_say "   · GitHub: $nm не скачался напрямую — $why. Пробуем через зеркала"
	for m in $ZM_GHP_LIST; do
		[ -n "$out" ] && [ "$out" != /dev/null ] && rm -f "$out" 2>/dev/null
		_zm_ghp_exec "$t" "https://$m/" "$@"; rc=$?
		if [ "$rc" = 0 ]; then
			if [ -n "$out" ] && [ "$out" != /dev/null ] && ! _zm_dl_sane "$out"; then
				_zm_ghp_say "   · $m: вместо файла пришла страница ошибки"
				rc=1; continue
			fi
			_zm_ghp_say "   ✓ $nm скачан через зеркало $m. Следующие загрузки — снова напрямую"
			return 0
		fi
		why="$(_zm_ghp_why "$t" "$rc")" || why="ошибка $rc"
		_zm_ghp_say "   · $m: не скачалось — $why"
	done
	_zm_ghp_say "   !! $nm не скачался ни напрямую, ни через зеркала ($(echo $ZM_GHP_LIST | sed 's/ /, /g'))"
	[ "$rc" = 0 ] && rc=1
	return $rc
}
_zm_has() { local d IFS=:; for d in ${PATH:-/usr/sbin:/usr/bin:/sbin:/bin}; do [ -n "$d" ] && [ -x "$d/$1" ] && [ ! -d "$d/$1" ] && return 0; done; return 1; }
curl() { _zm_ghp_run curl "$@"; }
wget() { _zm_ghp_run wget "$@"; }
_zm_fetch_ok() {
	[ -s "$1" ] || return 1
	[ -n "$ZM_FETCH_ANY" ] || ! head -c 1024 "$1" | grep -qiE '<(!doctype|html|head|body)' || return 1
	ZM_FETCH_SIZE="$(wc -c < "$1" 2>/dev/null | tr -d ' ')"
	return 0
}
_zm_fetch() {
	_zm_fetch_one "$@" && return 0
	[ -n "$ZM_ARCH_FB" ] || return 1
	case "$1" in *"$ZM_A73"*) ;; *) return 1 ;; esac
	case "$1" in *kmod*|*amneziawg*) return 1 ;; esac
	case "$ZM_FETCH_ERR" in *"(HTTP 404)"*|*"(HTTP 410)"*) ;; *) return 1 ;; esac
	[ "$(_zm_arch)" = "$ZM_A73" ] || return 1
	local a u e="$ZM_FETCH_ERR"
	for a in $ZM_A73_ALTS; do
		u="$(printf '%s' "$1" | sed "s/$ZM_A73/$a/g")"
		if _zm_fetch_one "$u" "$2" "$3" "$4"; then
			ZM_ARCH_USED="$a"
			echo "   · Сборки для $ZM_A73 нет — взята совместимая $a" >&2
			_zm_arch_accept "$a"
			return 0
		fi
		case "$ZM_FETCH_ERR" in *"(HTTP 404)"*|*"(HTTP 410)"*) ;; *) return 1 ;; esac
	done
	ZM_FETCH_ERR="$e"
	return 1
}
_zm_fetch_one() {
	local u="$1" o="$2" tm="${3:-120}" rg="$4" ef code rc e i
	ZM_FETCH_ERR=""; ZM_FETCH_SIZE=0
	ef="$o.zmerr"
	rm -f "$o"
	if _zm_has curl; then
		code="$(curl -fsSL --connect-timeout 10 --max-time "$tm" ${rg:+-r "$rg"} -A "Mozilla/5.0" -o "$o" -w '%{http_code}' "$u" 2>"$ef")"; rc=$?
		code="$(printf '%s' "$code" | tail -c 3)"
		e="$(tail -n 1 "$ef" 2>/dev/null | sed 's/^curl: ([0-9]*) //')"; rm -f "$ef"
		if [ "$rc" = 0 ] && _zm_fetch_ok "$o"; then return 0; fi
		rm -f "$o"
		if [ "$rc" = 22 ]; then
			case "$code" in
				404|410) ZM_FETCH_ERR="файла нет на сервере (HTTP $code)"; return 1 ;;
				403) ZM_FETCH_ERR="сервер отказал в доступе (HTTP 403)" ;;
				429) ZM_FETCH_ERR="сервер просит подождать — слишком много запросов (HTTP 429)" ;;
				5??) ZM_FETCH_ERR="сервер временно не работает (HTTP $code)" ;;
				*) ZM_FETCH_ERR="сервер ответил ошибкой HTTP ${code:-?}" ;;
			esac
		elif [ "$rc" = 0 ]; then ZM_FETCH_ERR="вместо файла пришла веб-страница"
		else ZM_FETCH_ERR="$(_zm_ghp_why curl "$rc" || echo "${e:-curl: ошибка $rc}")"; fi
	fi
	if [ -z "$rg" ] && _zm_has wget; then
		e="$(ZM_GHP_NOMIR=1; wget -T 20 -U "Mozilla/5.0" -O "$o" "$u" 2>&1)"; rc=$?
		if [ "$rc" = 0 ] && _zm_fetch_ok "$o"; then ZM_FETCH_ERR=""; return 0; fi
		rm -f "$o"
		if [ "$rc" = 0 ]; then e="вместо файла пришла веб-страница"
		else e="$(_zm_ghp_why wget "$rc" || printf '%s\n' "$e" | grep -v '^Downloading\|^Connecting\|^Writing\|^Download completed\|^$' | tail -n 1)"; fi
		ZM_FETCH_ERR="${ZM_FETCH_ERR:+$ZM_FETCH_ERR; }wget: ${e:-не скачалось}"
	fi
	[ -n "$ZM_FETCH_ERR" ] || ZM_FETCH_ERR="на роутере нет ни curl, ни wget"
	if _zm_has curl && command -v _st_warp_first >/dev/null 2>&1; then
		i="$(_st_warp_first 2>/dev/null)"
		if [ -n "$i" ] && [ -d "/sys/class/net/$i" ]; then
			if ( ZM_GHP_NOMIR=1; curl -fsSL --interface "$i" --connect-timeout 10 --max-time "$tm" ${rg:+-r "$rg"} -A "Mozilla/5.0" -o "$o" "$u" 2>/dev/null ) && _zm_fetch_ok "$o"; then
				ZM_FETCH_ERR=""
				return 0
			fi
			rm -f "$o"
			ZM_FETCH_ERR="$ZM_FETCH_ERR; через WARP тоже не вышло"
		fi
	fi
	return 1
}
_zm_size_txt() { local b="${1:-0}"; if [ "$b" -lt 1024 ]; then echo "$b Б"; elif [ "$b" -lt 1048576 ]; then echo "$(( (b + 512) / 1024 )) КБ"; else awk -v b="$b" 'BEGIN { printf "%.1f МБ\n", b / 1048576 }'; fi; }
_zm_get() {
	local nm="${3:-${1##*/}}"
	if _zm_fetch "$1" "$2" "${4:-120}"; then echo "   ✓ $nm — $(_zm_size_txt "$ZM_FETCH_SIZE")"; return 0; fi
	echo "   !! $nm — не скачался: $ZM_FETCH_ERR"
	return 1
}
gh_mirrors() { _zm_ghp_load; [ "$ZM_GHP_MODE" = auto ] && echo $ZM_GHP_LIST; return 0; }
MIHOMO_DIR="/etc/mihomo"
MIHOMO_BIN="/usr/bin/mihomo"
MIHOMO_CONF="/etc/mihomo/config.yaml"
MAGITRICKLE_CONF="/etc/magitrickle/state/config.yaml"
MIXOMO_CRON_CMD="/etc/init.d/mihomo restart"
HOSTS_FILE="/etc/hosts"
EXPERT_MODE_FILE="/opt/zapret-manager-luci/expert_mode"
PORTS_UDP="88,1024-2407,2409-4499,4502-19293,19345-49999,50101-65535"
PORTS_TCP="2099,2802,2302,2502,3478-3480,3724,6000-8000,8085,8090,8100,8903,8904,25565,27015-27030,27036-27037,35500-35600,50001,60442"
{ [ -d "$JOBS_DIR" ] && [ -d "$ZM_STATE_DIR" ]; } || mkdir -p "$JOBS_DIR" "$ZM_STATE_DIR" 2>/dev/null

if command -v opkg >/dev/null 2>&1; then
	PKG="opkg"; PKG_ADD="opkg install"; PKG_DEL="opkg remove"; PKG_UPD="opkg update"
	RAZ="ipk"
else
	PKG="apk"; PKG_ADD="apk add --allow-untrusted"; PKG_DEL="apk del"; PKG_UPD="apk update"
	RAZ="apk"
fi

esc() {
	case "$1" in *[!A-Za-z0-9\ ._:/@+=,%-]*) ;; *) printf '%s' "$1"; return 0 ;; esac
	printf '%s' "$1" | tr -d '\000-\010\013\014\016-\037' | sed 's/\\/\\\\/g; s/"/\\"/g; s/\t/\\t/g; s/\r/\\r/g' | tr '\n' ' '
}

esc_ml() {
	printf '%s' "$1" | tr -d '\000-\010\013\014\016-\037' | sed 's/\r$//; s/\\/\\\\/g; s/"/\\"/g; s/\t/\\t/g; s/\r/\\r/g' | sed ':a;N;$!ba;s/\n/\\n/g'
}

_job_running() {
	local pid="$JOBS_DIR/$1.pid"
	[ -f "$pid" ] && kill -0 "$(cat "$pid" 2>/dev/null)" 2>/dev/null || return 1
	! grep -q '^__DONE__' "$JOBS_DIR/$1.log" 2>/dev/null
}

job_status() {
	local name="$1"
	local pid="$JOBS_DIR/$name.pid"
	local log="$JOBS_DIR/$name.log"
	local running="false" done="false" rc=""
	_job_running "$name" && running="true"
	if [ -f "$log" ] && grep -q '^__DONE__' "$log"; then
		done="true"
		rc=$(grep '^__DONE__' "$log" | tail -1 | awk '{print $2}')
	fi
	printf '{"running":%s,"done":%s,"rc":"%s"}\n' "$running" "$done" "$rc"
}

log_tail() {
	local name="$1"
	local log="$JOBS_DIR/$name.log"
	[ -f "$log" ] || { echo '{"lines":""}'; return; }
	printf '{"lines":"%s"}\n' "$(esc_ml "$(tail -n 300 "$log" | grep -v '^__DONE__')")"
}

_confz() {
	if [ "$PKG" = "apk" ]; then echo "/etc/apk/repositories.d/distfeeds.list"
	else echo "/etc/opkg/distfeeds.conf"; fi
}

ZM_MIRROR_STATE="$ZM_STATE_DIR/mirror.state"
_mirror_host() {
	grep -v '^[[:space:]]*#' "$(_confz)" 2>/dev/null | grep -oE 'https?://[^ ]+/(releases|snapshots)/' | head -n1 | sed -E 's#^https?://##; s#/(releases|snapshots)/$##'
}

_mirror_name() {
	local f url
	f="$(_confz)"
	[ -f "$f" ] || { echo "файл не найден"; return; }
	url="$(_mirror_host)"
	[ -n "$url" ] || url=$(head -n1 "$f")
	case "$url" in
		*mirror-03.infra.openwrt.org*) echo "Infra OpenWrt" ;;
		*c3sl.ufpr.br*) echo "Brazil" ;;
		*ustc.edu.cn*) echo "China" ;;
		*tetaneutral.net*) echo "France" ;;
		*garr.it*) echo "Italy" ;;
		*marwan.ma*) echo "Morocco" ;;
		*pixeldeck.net*) echo "USA" ;;
		*rwth-aachen.de*) echo "Germany" ;;
		*downloads.openwrt.org*) echo "default / OpenWrt" ;;
		'') echo "неизвестное" ;;
		*) echo "$url" ;;
	esac
}

_mirror_info() {
	local h how="" ts=""
	h="$(_mirror_host)"
	if [ -s "$ZM_MIRROR_STATE" ] && [ "$(cut -f1 "$ZM_MIRROR_STATE")" = "$h" ]; then
		how="$(cut -f3 "$ZM_MIRROR_STATE")"; ts="$(cut -f2 "$ZM_MIRROR_STATE")"
	fi
	[ "$h" = downloads.openwrt.org ] && how=""
	printf '"mirror":"%s","mirror_host":"%s","mirror_how":"%s","mirror_at":%s' "$(esc "$(_mirror_name)")" "$(esc "$h")" "$(esc "$how")" "${ts:-0}"
}

_cpu_stat() { awk '/^cpu / { t = 0; for (i = 2; i <= NF; i++) t += $i; print t, $5 + $6; exit }' /proc/stat 2>/dev/null; }

_cpu_load() {
	local f="$JOBS_DIR/cpu.stat" now prev="" t1 i1 t2 i2 p
	now="$(_cpu_stat)"
	[ -n "$now" ] || return 0
	if [ -s "$f" ] && [ -z "$(find "$f" -mmin +1 2>/dev/null)" ]; then
		read -r prev 2>/dev/null < "$f"
	fi
	if [ -z "$prev" ]; then
		prev="$now"
		sleep 1
		now="$(_cpu_stat)"
	fi
	set -- $prev $now
	t1=$1; i1=$2; t2=$3; i2=$4
	if [ $((t2 - t1)) -lt 50 ] 2>/dev/null && [ -s "$f.pct" ]; then
		p=""; read -r p 2>/dev/null < "$f.pct"
		[ -n "$p" ] && { echo "$p"; return 0; }
	fi
	[ "$t2" -gt "$t1" ] 2>/dev/null || { echo 0; return 0; }
	echo "$now" > "$f"
	p=$(( (100 * ((t2 - t1) - (i2 - i1)) + (t2 - t1) / 2) / (t2 - t1) ))
	echo "$p" > "$f.pct"
	echo "$p"
}

_cpu_temp() {
	local z t typ best="" v
	for z in /sys/class/thermal/thermal_zone*; do
		[ -r "$z/temp" ] || continue
		t=""; read -r t 2>/dev/null < "$z/temp"
		case "$t" in ''|*[!0-9-]*) continue ;; esac
		typ=""; read -r typ 2>/dev/null < "$z/type"
		case "$typ" in *cpu*|*CPU*|*soc*|*SOC*) best="$t"; break ;; esac
		{ [ -z "$best" ] || [ "$t" -gt "$best" ]; } && best="$t"
	done
	if [ -z "$best" ]; then
		for z in /sys/class/hwmon/hwmon*/temp1_input; do
			[ -r "$z" ] || continue
			t=""; read -r t 2>/dev/null < "$z"
			case "$t" in ''|*[!0-9-]*) continue ;; esac
			best="$t"; break
		done
	fi
	[ -n "$best" ] || return 0
	if [ "$best" -gt 1000 ] 2>/dev/null; then v=$(( (best + 50) / 100 )); echo "$((v / 10)).$((v % 10))"
	else echo "$best"; fi
}

_inet_ping() {
	local h out ms
	for h in ya.ru vk.ru; do
		out=$(ping -4 -c 1 -W 2 "$h" 2>/dev/null)
		ms=$(echo "$out" | sed -n 's/.*time=\([0-9.]*\).*/\1/p' | head -n1)
		[ -n "$ms" ] && { echo "$(date +%s) ok ${ms%%.*}"; return 0; }
	done
	for h in ya.ru vk.ru; do
		ms=$(curl -s -o /dev/null --connect-timeout 4 --max-time 6 -w '%{time_namelookup} %{time_connect}' "http://$h/" 2>/dev/null) || continue
		echo "$(date +%s) ok $(echo "$ms" | awk '{ v = ($2 - $1) * 1000; if (v < 1) v = 1; printf "%d", v }')"
		return 0
	done
	for h in 77.88.8.8 1.1.1.1; do
		ping -4 -c 1 -W 2 "$h" >/dev/null 2>&1 && { echo "$(date +%s) nodns"; return 0; }
	done
	for h in 1.1.1.1 8.8.8.8; do
		curl -s -o /dev/null --connect-timeout 4 --max-time 6 "http://$h/" >/dev/null 2>&1 && { echo "$(date +%s) nodns"; return 0; }
	done
	echo "$(date +%s) fail"
}
_inet_state() {
	local f="$ZM_STATE_DIR/inet" t r ms age
	read -r t r ms 2>/dev/null < "$f"
	age=$(( $(date +%s) - ${t:-0} ))
	if [ "$age" -ge 10 ] || [ "$age" -lt 0 ]; then
		mkdir -p "$ZM_STATE_DIR"
		if mkdir "$f.lock" 2>/dev/null; then
			( _inet_ping > "$f.new" 2>/dev/null && mv -f "$f.new" "$f"; rmdir "$f.lock" ) >/dev/null 2>&1 &
		elif [ -n "$(find "$f.lock" -mmin +1 2>/dev/null)" ]; then
			rmdir "$f.lock" 2>/dev/null
		fi
	fi
	[ -n "$r" ] && [ "$age" -lt 120 ] && echo "$r $ms"
}

ZM_SI_STATIC="$JOBS_DIR/si.static"
_si_static() {
	local f="$ZM_SI_STATIC" line="" model arch owrt target
	if [ -s "$f" ] && [ ! "$(_confz)" -nt "$f" ] && [ ! "$ZM_MIRROR_STATE" -nt "$f" ] && [ -z "$(find "$f" -mmin +10 2>/dev/null)" ]; then
		IFS= read -r line 2>/dev/null < "$f"
		[ -n "$line" ] && { printf '%s\n' "$line"; return 0; }
	fi
	model=$(cat /tmp/sysinfo/model 2>/dev/null)
	arch=$(grep DISTRIB_ARCH /etc/openwrt_release 2>/dev/null | cut -d"'" -f2)
	owrt=$(grep '^DISTRIB_RELEASE=' /etc/openwrt_release 2>/dev/null | cut -d"'" -f2)
	target=$(grep '^DISTRIB_TARGET=' /etc/openwrt_release 2>/dev/null | cut -d"'" -f2)
	line="$(printf '%s,"model":"%s","arch":"%s","openwrt":"%s","target":"%s","hostname":"%s","kernel":"%s"' "$(_mirror_info)" \
		"$(esc "$model")" "$(esc "$arch")" "$(esc "$owrt")" "$(esc "$target")" "$(esc "$(cat /proc/sys/kernel/hostname 2>/dev/null)")" "$(esc "$(uname -r 2>/dev/null)")")"
	printf '%s\n' "$line" > "$f.$$" 2>/dev/null && mv -f "$f.$$" "$f" 2>/dev/null || rm -f "$f.$$"
	printf '%s\n' "$line"
}

system_info() {
	local df_j inet inet_ms
	df_j=$(df -h /tmp / 2>/dev/null | awk 'function c(x) { gsub(/["\\]/, "", x); return x }
		NR == 2 { a = $3; b = $4 } NR == 3 { u = $3; v = $4 }
		END { printf "\"tmp_used\":\"%s\",\"tmp_free\":\"%s\",\"root_used\":\"%s\",\"root_free\":\"%s\"", c(a), c(b), c(u), c(v) }')
	[ -n "$df_j" ] || df_j='"tmp_used":"","tmp_free":"","root_used":"","root_free":""'
	set -- $(_inet_state)
	inet="$1"; inet_ms="$2"
	printf '{%s,%s,"cpu_temp":"%s","cpu_load":"%s","inet":"%s","inet_ms":"%s"}\n' "$(_si_static)" "$df_j" "$(_cpu_temp)" "$(_cpu_load)" "$inet" "$inet_ms"
}

_mon_dev() {
	local f="$JOBS_DIR/mon.dev.$1" d=""
	if [ -s "$f" ] && [ -z "$(find "$f" -mmin +1 2>/dev/null)" ]; then read -r d 2>/dev/null < "$f"; printf '%s' "$d"; return 0; fi
	d="$(ubus -t 2 call "network.interface.$1" status 2>/dev/null | jsonfilter -e '@.l3_device' 2>/dev/null)"
	[ -n "$d" ] || d="$(uci -q get "network.$1.device" 2>/dev/null)"
	case "$d" in *[!A-Za-z0-9_.@-]*) d="" ;; esac
	printf '%s\n' "$d" > "$f" 2>/dev/null
	printf '%s' "$d"
}

_mon_ifs() {
	local f="$JOBS_DIR/mon.ifs" dr o n d
	if [ -s "$f" ] && [ -z "$(find "$f" -mmin +1 2>/dev/null)" ]; then cat "$f"; return 0; fi
	dr="$(awk 'NR > 1 && $2 == "00000000" && $8 == "00000000" { print $7 + 0, $1 }' /proc/net/route 2>/dev/null | sort -n | awk 'NR == 1 { print $2 }')"
	{
		ubus -t 2 call network.interface dump 2>/dev/null | jsonfilter -e '@.interface[@.up=true]' 2>/dev/null | while IFS= read -r o; do
			n="$(jsonfilter -s "$o" -e '@.interface' 2>/dev/null)"
			d="$(jsonfilter -s "$o" -e '@.l3_device' 2>/dev/null)"
			[ -n "$n" ] && [ -n "$d" ] && [ "$n" != loopback ] && [ -d "/sys/class/net/$d" ] || continue
			case "$n$d" in *[!A-Za-z0-9_.@-]*) continue ;; esac
			echo "$n $d"
		done
		[ -n "$dr" ] && echo "$dr $dr"
	} | awk -v dr="$dr" '
		{ l[NR] = $0; nm[NR] = $1; dv[NR] = $2 }
		END {
			for (p = 0; p < 2; p++) for (i = 1; i <= NR; i++) {
				six = (nm[i] ~ /6$/) ? 1 : 0
				if (six != p || seen[dv[i]]++) continue
				print nm[i], dv[i], (dv[i] == dr ? 1 : 0)
			}
		}' > "$f.$$" 2>/dev/null && mv -f "$f.$$" "$f" 2>/dev/null
	cat "$f" 2>/dev/null
}

_mon_fan() {
	local h n v rpm=-1 pwm=-1 st=-1 mx=-1 c t y="${ZM_SYSFS:-/sys}"
	for h in "$y"/class/hwmon/hwmon*; do
		[ -d "$h" ] || continue
		n=""; read -r n 2>/dev/null < "$h/name"
		for v in "$h"/fan[0-9]_input; do
			[ -r "$v" ] || continue
			t=""; read -r t 2>/dev/null < "$v"; case "$t" in ''|*[!0-9]*) ;; *) [ "$rpm" -lt 0 ] && rpm="$t" ;; esac
		done
		case "$n" in *fan*|*FAN*) ;; *) [ -e "$h/fan1_input" ] || continue ;; esac
		for v in "$h"/pwm[0-9]; do
			[ -r "$v" ] || continue
			t=""; read -r t 2>/dev/null < "$v"; case "$t" in ''|*[!0-9]*) ;; *) [ "$pwm" -lt 0 ] && pwm=$(( (t * 100 + 127) / 255 )) ;; esac
		done
	done
	for c in "$y"/class/thermal/cooling_device*; do
		[ -r "$c/type" ] || continue
		t=""; read -r t 2>/dev/null < "$c/type"
		case "$t" in *fan*|*Fan*|*FAN*) ;; *) continue ;; esac
		read -r st 2>/dev/null < "$c/cur_state"; read -r mx 2>/dev/null < "$c/max_state"
		case "$st$mx" in *[!0-9]*|'') st=-1; mx=-1 ;; *) break ;; esac
	done
	[ "$rpm" -ge 0 ] || [ "$pwm" -ge 0 ] || [ "$st" -ge 0 ] || return 0
	printf '{"rpm":%s,"pwm":%s,"st":%s,"mx":%s}' "$rpm" "$pwm" "$st" "$mx"
}

_mon_static() {
	local f="$JOBS_DIR/mon.static" soc="" v c n part cpu="" mx="" line
	if [ -s "$f" ] && [ -z "$(find "$f" -mmin +10 2>/dev/null)" ]; then cat "$f"; return 0; fi
	soc="$( { tr '\000' '\n' < /proc/device-tree/compatible; } 2>/dev/null | tail -n1)"
	case "$soc" in
		*,*)
			v="${soc%%,*}"; c="$(printf '%s' "${soc#*,}" | tr 'a-z' 'A-Z')"
			case "$v" in
				mediatek) v=MediaTek ;; qcom) v=Qualcomm ;; brcm) v=Broadcom ;; ralink) v=Ralink ;; realtek) v=Realtek ;;
				rockchip) v=Rockchip ;; allwinner) v=Allwinner ;; marvell) v=Marvell ;; airoha|econet) v=Airoha ;; amlogic) v=Amlogic ;; nxp|fsl) v=NXP ;;
			esac
			soc="$v $c" ;;
		*) soc="" ;;
	esac
	n="$(grep -c '^processor' /proc/cpuinfo 2>/dev/null)"
	part="$(sed -n 's/^CPU part[[:space:]]*:[[:space:]]*//p' /proc/cpuinfo 2>/dev/null | head -n1)"
	case "$part" in
		0xd03) cpu=Cortex-A53 ;; 0xd04) cpu=Cortex-A35 ;; 0xd05) cpu=Cortex-A55 ;; 0xd07) cpu=Cortex-A57 ;; 0xd08) cpu=Cortex-A72 ;;
		0xd09) cpu=Cortex-A73 ;; 0xd0b) cpu=Cortex-A76 ;; 0xc05) cpu=Cortex-A5 ;; 0xc07) cpu=Cortex-A7 ;; 0xc09) cpu=Cortex-A9 ;; 0xc0f) cpu=Cortex-A15 ;;
	esac
	[ -n "$cpu" ] || cpu="$(sed -En 's/^(cpu model|model name)[[:space:]]*:[[:space:]]*//p' /proc/cpuinfo 2>/dev/null | head -n1)"
	read -r mx 2>/dev/null < /sys/devices/system/cpu/cpu0/cpufreq/cpuinfo_max_freq
	case "$mx" in ''|*[!0-9]*) mx=0 ;; esac
	line="$(printf '"soc":"%s","cpu_model":"%s","ncpu":%s,"fmax":%s,"model":"%s","kernel":"%s","openwrt":"%s"' "$(esc "$soc")" "$(esc "$cpu")" "${n:-1}" "$((mx / 1000))" \
		"$(esc "$(cat /tmp/sysinfo/model 2>/dev/null)")" "$(esc "$(uname -r 2>/dev/null)")" \
		"$(esc "$(sed -n "s/^DISTRIB_RELEASE='\(.*\)'/\1/p" /etc/openwrt_release 2>/dev/null)")")"
	printf '%s\n' "$line" > "$f.$$" 2>/dev/null && mv -f "$f.$$" "$f" 2>/dev/null
	printf '%s\n' "$line"
}

_mon_c() { local t="$1" v; if [ "$t" -gt 1000 ] 2>/dev/null; then v=$(( (t + 50) / 100 )); echo "$((v / 10)).$((v % 10))"; else echo "$t"; fi; }

_mon_tlabel() {
	local n="$1" l="$2" i b
	case "$n" in
		*phy[0-9]*)
			i="$(printf '%s' "$n" | sed 's/.*phy\([0-9]*\).*/\1/')"; b="$(uci -q get "wireless.radio$i.band" 2>/dev/null)"
			case "$b" in 2g) echo "Wi-Fi 2,4 ГГц" ;; 5g) echo "Wi-Fi 5 ГГц" ;; 6g) echo "Wi-Fi 6 ГГц" ;; *) echo "Wi-Fi (phy$i)" ;; esac ;;
		*cpu*|*CPU*|*soc*|*SOC*|*tsens*) echo "Процессор" ;;
		*ddr*|*DDR*) echo "Память" ;;
		*nvme*|*mmc*) echo "Накопитель" ;;
		*ath*|*mt76*|*mt79*|*wifi*|*wlan*) echo "Wi-Fi" ;;
		*) if [ -n "$l" ]; then echo "$n · $l"; else echo "$n"; fi ;;
	esac
}

_mon_temps() {
	local z t typ sep="" h n i lbl seen=" "
	for z in /sys/class/thermal/thermal_zone*; do
		[ -r "$z/temp" ] || continue
		t=""; read -r t 2>/dev/null < "$z/temp"
		case "$t" in ''|*[!0-9-]*) continue ;; esac
		typ=""; read -r typ 2>/dev/null < "$z/type"
		seen="$seen$(printf '%s' "$typ" | tr '-' '_') "
		printf '%s{"id":"%s","label":"%s","c":%s}' "$sep" "$(esc "$typ")" "$(esc "$(_mon_tlabel "$typ")")" "$(_mon_c "$t")"; sep=","
	done
	for h in /sys/class/hwmon/hwmon*; do
		n=""; read -r n 2>/dev/null < "$h/name"
		case "$seen" in *" $(printf '%s' "$n" | tr '-' '_') "*) continue ;; esac
		for i in "$h"/temp*_input; do
			[ -r "$i" ] || continue
			t=""; read -r t 2>/dev/null < "$i"
			case "$t" in ''|*[!0-9-]*) continue ;; esac
			lbl=""; read -r lbl 2>/dev/null < "${i%_input}_label"
			printf '%s{"id":"%s","label":"%s","c":%s}' "$sep" "$(esc "$n")" "$(esc "$(_mon_tlabel "$n" "$lbl")")" "$(_mon_c "$t")"; sep=","
		done
	done
}

monitor_snapshot() {
	local wan lan fl f t ifs fan
	wan="$(_mon_dev wan)"; lan="$(_mon_dev lan)"
	ifs="$(_mon_ifs | tr '\n' ';')"
	fan="$(_mon_fan)"
	fl="/proc/uptime /proc/loadavg /proc/stat /proc/meminfo /proc/net/dev"
	for f in /proc/sys/net/netfilter/nf_conntrack_count /proc/sys/net/netfilter/nf_conntrack_max; do [ -r "$f" ] && fl="$fl $f"; done
	t=""; read -r t 2>/dev/null < /sys/devices/system/cpu/cpu0/cpufreq/scaling_cur_freq
	case "$t" in ''|*[!0-9]*) t=0 ;; esac
	printf '{'
	awk -v wan="$wan" -v lan="$lan" -v ifs="$ifs" '
		BEGIN { k = split(ifs, il, ";"); for (i = 1; i <= k; i++) if (split(il[i], q, " ") >= 2) { ifn[q[2]] = q[1]; ifi[q[2]] = q[3] + 0; ifo[++ifc] = q[2] } }
		FILENAME == "/proc/uptime" { up = $1 + 0 }
		FILENAME == "/proc/loadavg" { ld = ($1 + 0) "," ($2 + 0) "," ($3 + 0); split($4, pr, "/"); run = pr[1] + 0; tot = pr[2] + 0 }
		FILENAME == "/proc/stat" && $1 ~ /^cpu/ {
			s = ""; for (i = 2; i <= 9; i++) s = s (i > 2 ? "," : "") ($i + 0)
			if ($1 == "cpu") all = s; else cores = cores (cores != "" ? "," : "") "[" s "]"
		}
		FILENAME == "/proc/meminfo" { k = $1; sub(/:$/, "", k); m[k] = $2 + 0 }
		FILENAME == "/proc/net/dev" && index($0, ":") {
			l = $0; sub(/^[ \t]+/, "", l); n = substr(l, 1, index(l, ":") - 1); split(substr(l, index(l, ":") + 1), v, " ")
			if (n == wan) w = (v[1] + 0) "," (v[9] + 0)
			if (n == lan) la = (v[1] + 0) "," (v[9] + 0)
			if (n in ifn) ifc_v[n] = (v[1] + 0) "," (v[9] + 0)
		}
		FILENAME ~ /_count$/ { cc = $1 + 0 }
		FILENAME ~ /_max$/ { cm = $1 + 0 }
		END {
			av = ("MemAvailable" in m) ? m["MemAvailable"] : m["MemFree"] + m["Cached"] + m["Buffers"]
			printf "\"t\":%s,\"load\":[%s],\"run\":%d,\"tasks\":%d,\"cpu\":[%s],\"cores\":[%s],", up + 0, (ld != "" ? ld : "0,0,0"), run, tot, all, cores
			printf "\"mem\":{\"total\":%d,\"free\":%d,\"avail\":%d,\"buffers\":%d,\"cached\":%d,\"shmem\":%d,\"sreclaim\":%d,\"swap\":%d,\"swapfree\":%d},", m["MemTotal"], m["MemFree"], av, m["Buffers"], m["Cached"], m["Shmem"], m["SReclaimable"], m["SwapTotal"], m["SwapFree"]
			printf "\"net\":{\"wan\":[%s],\"lan\":[%s],\"wan_dev\":\"%s\",\"lan_dev\":\"%s\",\"ifs\":[", w, la, wan, lan
			for (i = 1; i <= ifc; i++) { d = ifo[i]; if (!(d in ifc_v)) continue; printf "%s{\"n\":\"%s\",\"d\":\"%s\",\"i\":%d,\"c\":[%s]}", (o++ ? "," : ""), ifn[d], d, ifi[d], ifc_v[d] }
			printf "]},\"conn\":[%d,%d]", cc, cm
		}' $fl 2>/dev/null
	df -k / /tmp 2>/dev/null | awk 'NR == 2 { a = $2 + 0; b = $3 + 0 } NR == 3 { c = $2 + 0; d = $3 + 0 } END { printf ",\"flash\":[%d,%d],\"tmp\":[%d,%d]", a, b, c, d }'
	printf ',"fan":%s' "${fan:-null}"
	printf ',"freq":%s,"leases":%s,"temps":[%s],"htop":{"inst":%s,"ttyd":%s,"open":%s},%s}\n' \
		"$((t / 1000))" "$(cat /tmp/dhcp.leases 2>/dev/null | grep -c .)" "$(_mon_temps)" \
		"$([ -x /usr/bin/htop ] && echo true || echo false)" "$([ -x /usr/bin/ttyd ] && echo true || echo false)" \
		"$([ -s "$JOBS_DIR/htop.pid" ] && kill -0 "$(cat "$JOBS_DIR/htop.pid" 2>/dev/null)" 2>/dev/null && echo true || echo false)" "$(_mon_static)"
}

monitor_procs() {
	local tot
	tot="$(awk '$1 == "cpu" { t = 0; for (i = 2; i <= NF; i++) t += $i; printf "%.0f", t; exit }' /proc/stat 2>/dev/null)"
	printf '{"total":%s,"p":[' "${tot:-0}"
	{ ps w 2>/dev/null; echo '@@ZM@@'; cat /proc/[0-9]*/stat 2>/dev/null; } | awk '
		function j(s,    o, i, c, n) { o = ""; n = length(s); for (i = 1; i <= n; i++) { c = substr(s, i, 1); if (c == "\\") o = o "\\\\"; else if (c == "\"") o = o "\\\""; else if (c < " ") o = o " "; else o = o c } return o }
		!body && $0 == "@@ZM@@" { body = 1; next }
		!body && !hdr { hdr = 1; ci = index($0, "COMMAND"); next }
		!body { if ($1 ~ /^[0-9]+$/) { u[$1] = $2; c = ci ? substr($0, ci) : ""; sub(/^\{[^}]*\} /, "", c); cmd[$1] = c }; next }
		{
			l = $0; a = index(l, "("); b = 0
			for (i = length(l); i > a; i--) if (substr(l, i, 1) == ")") { b = i; break }
			if (!a || !b) next
			p = substr(l, 1, a - 2) + 0; nm = substr(l, a + 1, b - a - 1)
			split(substr(l, b + 2), f, " ")
			printf "%s[%d,%d,\"%s\",\"%s\",%.0f,%.0f,%d,\"%s\",\"%s\"]", (n++ ? "," : ""), p, f[2], j(nm), f[1], f[12] + f[13], f[22] * 4, f[18], j(u[p]), j(substr(cmd[p], 1, 240))
		}'
	printf ']}\n'
}

case "$1" in
	system_info) system_info; exit ;;
	monitor)       monitor_snapshot; exit ;;
	monitor_procs) monitor_procs; exit ;;
	job_status)  job_status "$2"; exit ;;
	log_tail)    log_tail "$2"; exit ;;
esac

INSTALL="_zm_pkg_add"; DELETE="_zm_pkg_del"; UPDATE="_zm_pkg_update"
TG_ARCH=""
_tg_arch_init() {
	[ -n "$TG_ARCH" ] && return 0
	if [ "$PKG" = "opkg" ]; then TG_ARCH="$(opkg print-architecture 2>/dev/null | awk '{print $2}' | tail -n1)"
	else TG_ARCH="$(apk --print-arch 2>/dev/null)"; fi
}

ZM_A73="aarch64_cortex-a73"
ZM_A73_ALTS="aarch64_cortex-a53 aarch64_generic"
_zm_arch() { awk -F\' '/DISTRIB_ARCH/ {print $2}' /etc/openwrt_release 2>/dev/null; }
_zm_arch_alts() {
	echo "$1"
	[ "$1" = "$ZM_A73" ] && printf '%s\n' $ZM_A73_ALTS
	return 0
}
_zm_arch_accept() {
	local a="$1" c="${ZM_OPKG_CONF:-/etc/opkg.conf}" f="${ZM_APK_ARCH:-/etc/apk/arch}" n
	case " $ZM_A73_ALTS " in *" $a "*) ;; *) return 0 ;; esac
	[ "$(_zm_arch)" = "$ZM_A73" ] || return 0
	if [ "$PKG" = apk ]; then
		[ -d "${f%/*}" ] || return 0
		if [ ! -s "$f" ]; then
			n="$(apk --print-arch 2>/dev/null)"
			[ -n "$n" ] || return 0
			echo "$n" > "$f" || return 1
		fi
		grep -qx "$a" "$f" && return 0
		{ [ -z "$(tail -c 1 "$f")" ] || echo; echo "$a"; } >> "$f" || return 1
	else
		[ -f "$c" ] || return 0
		if ! grep -q '^[[:space:]]*arch[[:space:]]' "$c"; then
			n="$(opkg print-architecture 2>/dev/null | awk '$1 == "arch" && NF >= 3 { print "arch " $2 " " $3 }')"
			case "$n" in *"$ZM_A73"*) ;; *) return 0 ;; esac
			{ [ -z "$(tail -c 1 "$c")" ] || echo; printf '%s\n' "$n"; } >> "$c" || return 1
		fi
		grep -qE "^[[:space:]]*arch[[:space:]]+$a([[:space:]]|\$)" "$c" && return 0
		{ [ -z "$(tail -c 1 "$c")" ] || echo; echo "arch $a 5"; } >> "$c" || return 1
	fi
	echo "   · Разрешили ставить пакеты $a — на $ZM_A73 они работают (тот же набор команд ARMv8.0)" >&2
	logger -t zapret-manager "Разрешены пакеты $a (совместимы с $ZM_A73)"
	return 0
}

ZM_NL='
'
_zm_re() { case "$1" in *"$ZM_NL"*) return 1 ;; esac; printf '%s\n' "$1" | grep -qE -- "$2"; }

ZM_TMO=""
_zm_tmo_ok() {
	[ -n "$ZM_TMO" ] || { if timeout 1 true >/dev/null 2>&1; then ZM_TMO=1; else ZM_TMO=0; fi; }
	[ "$ZM_TMO" = 1 ]
}
_zm_tmo() {
	local s="$1" p w rc
	shift
	case "$(type "$1" 2>/dev/null)" in *function*) ;; *) if _zm_tmo_ok; then timeout "$s" "$@"; return; fi ;; esac
	case "$s" in ''|*[!0-9]*) s=60 ;; esac
	{ "$@" <&3 3<&- & } 3<&0
	p=$!
	( i=0
	  while [ "$i" -lt "$s" ] && kill -0 "$p" 2>/dev/null; do sleep 1; i=$((i + 1)); done
	  if kill -0 "$p" 2>/dev/null; then kill "$p" 2>/dev/null; sleep 1; kill -9 "$p" 2>/dev/null; fi ) >/dev/null 2>&1 </dev/null &
	w=$!
	wait "$p" 2>/dev/null; rc=$?
	wait "$w" 2>/dev/null
	case "$rc" in 137|143) rc=124 ;; esac
	return $rc
}

ZM_JESC_AWK='function jesc(s,    o, i, c, n) {
	o = ""; n = length(s)
	for (i = 1; i <= n; i++) {
		c = substr(s, i, 1)
		if (c == "\\") o = o "\\\\"
		else if (c == "\"") o = o "\\\""
		else if (c == "\t") o = o "\\t"
		else if (c != "\r") o = o c
	}
	return o
}
'

_zm_zone_sec() {
	local z
	for z in $(uci -q -X show firewall | sed -n "s/^firewall\.\([^.=]*\)=zone\$/\1/p"); do
		[ "$(uci -q get "firewall.$z.name")" = "$1" ] && { echo "$z"; return 0; }
	done
	return 1
}
_zm_zone_of_net() {
	local z
	for z in $(uci -q -X show firewall | sed -n "s/^firewall\.\([^.=]*\)=zone\$/\1/p"); do
		case " $(uci -q get "firewall.$z.network") " in *" $1 "*) uci -q get "firewall.$z.name"; return 0 ;; esac
	done
	return 1
}
_zm_lan_zone() {
	local c="$JOBS_DIR/lanzone" v=""
	if [ -s "$c" ] && { [ ! -e /etc/config/firewall ] || [ "$c" -nt /etc/config/firewall ]; }; then read -r v < "$c"; [ -n "$v" ] && { echo "$v"; return 0; }; fi
	v="$(_zm_lan_zone_find)"
	[ -n "$v" ] && { printf '%s\n' "$v" > "$c.$$" 2>/dev/null && mv -f "$c.$$" "$c" 2>/dev/null; }
	echo "${v:-lan}"
}
_zm_lan_zone_find() {
	local f w
	_zm_zone_of_net lan && return 0
	_zm_zone_sec lan >/dev/null && { echo lan; return 0; }
	w="$(_zm_wan_zone)"
	for f in $(uci -q -X show firewall | sed -n "s/^firewall\.\([^.=]*\)=forwarding\$/\1/p"); do
		[ "$(uci -q get "firewall.$f.dest")" = "$w" ] && { uci -q get "firewall.$f.src"; return 0; }
	done
	echo lan
}
_zm_wan_zone() { _zm_zone_of_net wan || echo wan; }
_zm_lan_nets() {
	local s n=""
	s="$(_zm_zone_sec "$(_zm_lan_zone)")" && n="$(uci -q get "firewall.$s.network")"
	echo "${n:-lan}"
}
_zm_lan_devs() {
	local s n d out=""
	for n in $(_zm_lan_nets); do
		d="$(ifstatus "$n" 2>/dev/null | jsonfilter -e '@.l3_device' 2>/dev/null)"
		[ -n "$d" ] || d="$(ifstatus "$n" 2>/dev/null | jsonfilter -e '@.device' 2>/dev/null)"
		[ -n "$d" ] || d="$(uci -q get "network.$n.device")"
		[ -n "$d" ] && [ -d "/sys/class/net/$d" ] || continue
		case " $out " in *" $d "*) ;; *) out="$out $d" ;; esac
	done
	if s="$(_zm_zone_sec "$(_zm_lan_zone)")"; then
		for d in $(uci -q get "firewall.$s.device"); do
			[ -d "/sys/class/net/$d" ] || continue
			case " $out " in *" $d "*) ;; *) out="$out $d" ;; esac
		done
	fi
	[ -n "$out" ] || out="br-lan"
	echo $out
}
_zm_lan_ip() {
	local n ip d
	ip="$(ifstatus lan 2>/dev/null | jsonfilter -e "@['ipv4-address'][0].address" 2>/dev/null)"
	[ -n "$ip" ] && { echo "$ip"; return 0; }
	for n in $(_zm_lan_nets); do
		[ "$n" = lan ] && continue
		ip="$(ifstatus "$n" 2>/dev/null | jsonfilter -e "@['ipv4-address'][0].address" 2>/dev/null)"
		[ -n "$ip" ] && { echo "$ip"; return 0; }
	done
	ip="$(uci -q get network.lan.ipaddr 2>/dev/null | awk '{ print $1 }' | cut -d/ -f1)"
	[ -n "$ip" ] && { echo "$ip"; return 0; }
	for d in $(_zm_lan_devs); do
		ip="$(ip -4 -o addr show dev "$d" 2>/dev/null | awk '{ print $4; exit }' | cut -d/ -f1)"
		[ -n "$ip" ] && { echo "$ip"; return 0; }
	done
	return 1
}

_pkg_is_installed() {
	if [ "$PKG" = "apk" ]; then apk info -e "$1" >/dev/null 2>&1
	elif [ -f /usr/lib/opkg/status ]; then awk -v p="$1" '$1 == "Package:" { x = ($2 == p) } x && $1 == "Status:" && / (installed|unpacked)$/ { f = 1; exit } END { exit !f }' /usr/lib/opkg/status
	else opkg list-installed 2>/dev/null | grep -q "^$1 "; fi
}
_zm_px_foreign() {
	if [ -x /etc/init.d/tachyon ] || _pkg_is_installed tachyon || _pkg_is_installed luci-app-tachyon; then echo "Tachyon"; return 0; fi
	if [ -x /etc/init.d/forkop ] || _pkg_is_installed forkop || _pkg_is_installed luci-app-forkop; then
		if [ -e /etc/init.d/forkop-support ] || [ -e /usr/share/forkop/mirror-migration.sh ]; then echo "Forkop X"; else echo "Forkop"; fi
		return 0
	fi
	return 1
}
_apk_ver() {
	local v=""
	[ -f /lib/apk/db/installed ] && v="$(awk -v p="$1" '/^P:/ { x = (substr($0, 3) == p) } x && /^V:/ { print substr($0, 3); exit }' /lib/apk/db/installed)"
	[ -n "$v" ] || v="$(apk info -v 2>/dev/null | sed -n "s/^$1-\([0-9][^ ]*\)\$/\1/p" | head -n1)"
	[ -n "$v" ] && printf '%s\n' "$v"
}
_kv_last() {
	local l v=""
	[ -f "$1" ] || return 0
	while IFS= read -r l || [ -n "$l" ]; do case "$l" in "$2="*) v="${l#"$2="}" ;; esac; done < "$1"
	printf '%s' "$v"
}
_opkg_ver() {
	if [ -f /usr/lib/opkg/status ]; then
		awk -v p="$1" 'function out() { if (x && ok && v != "" && !d) { print v; d = 1 } }
			$1 == "Package:" { out(); if (d) exit; x = ($2 == p); v = ""; ok = 0; next }
			x && $1 == "Version:" { v = $2 } x && $1 == "Status:" && / (installed|unpacked)$/ { ok = 1 } END { out() }' /usr/lib/opkg/status
	else opkg list-installed 2>/dev/null | awk -v p="$1" '$1 == p { print $3; exit }'; fi
}

_ensure_deps() {
	local need=""
	_zm_has curl || need="$need curl"
	command -v unzip >/dev/null 2>&1 || need="$need unzip"
	[ -z "$need" ] && return 0
	echo "==> Не хватает программ:$need — устанавливаем"
	$UPDATE
	$INSTALL $need
}

_zm_kids() {
	local f a b c d r
	for f in /proc/[0-9]*/stat; do
		{ read -r a b c d r < "$f"; } 2>/dev/null || continue
		[ "$d" = "$1" ] && echo "$a"
	done
}

_zm_kill_tree() {
	local c
	[ -n "$1" ] || return 0
	kill -STOP "$1" 2>/dev/null
	for c in $(_zm_kids "$1"); do _zm_kill_tree "$c"; done
	kill -9 "$1" 2>/dev/null
}

_zm_pkg_unlock() {
	pidof opkg >/dev/null 2>&1 || rm -f /var/lock/opkg.lock 2>/dev/null
	return 0
}

_zm_dots() {
	local p="$1" tmo="${2:-900}" i=0 o="${ZM_JOB_LOG:-/dev/null}" shown=0
	[ -n "$ZM_IN_WAIT" ] && o=/dev/null
	while kill -0 "$p" 2>/dev/null; do
		sleep 1
		i=$((i + 1))
		if [ "$i" -ge "$tmo" ]; then
			_zm_kill_tree "$p"
			[ "$shown" = 1 ] && echo >> "$o"
			shown=0
			echo "!! Шаг не завершился за $tmo с — прерываем его, чтобы ничего не зависло" >> "${ZM_JOB_LOG:-/dev/null}"
			[ -n "${ZM_TMO_FLAG:-}" ] && : > "$ZM_TMO_FLAG"
			_zm_pkg_unlock
			break
		fi
		if [ "$i" -ge 20 ]; then
			[ "$shown" = 0 ] && { printf 'Подождите ' >> "$o"; shown=1; }
			[ $((i % 5)) = 0 ] && printf '.' >> "$o"
		fi
	done
	[ "$shown" = 1 ] && echo >> "$o"
	return 0
}

_zm_run() {
	local tmo="$1" p rc t="/tmp/zm-run.$$.$RANDOM"
	shift
	( ZM_IN_WAIT=1; export ZM_IN_WAIT; "$@" ) > "$t" 2>&1 &
	p=$!
	_zm_dots "$p" "$tmo"
	wait "$p" 2>/dev/null
	rc=$?
	cat "$t" 2>/dev/null
	rm -f "$t"
	return $rc
}

_zm_pkg_fmt() {
	awk '
		{ sub(/\r$/, "") }
		/^Downloading / { next }
		/^Updated list of available packages in / { n = $0; sub(/.*\//, "", n); print "     · обновлён список: " n; next }
		/^Installing [^ ]+ \(/ { v = $3; gsub(/[()]/, "", v); print "     · ставим " $2 " " v; next }
		/^Upgrading [^ ]+ / { print "     · обновляем " $2; next }
		/^Configuring / { n = $2; sub(/\.$/, "", n); print "     · настраиваем " n; next }
		/^Removing package / { print "     · удаляем " $3; next }
		/^Package .* is up to date/ { print "     · " $2 " уже стоит последней версии"; next }
		/^\([0-9]+\/[0-9]+\) Installing / { v = $4; gsub(/[()]/, "", v); print "     · ставим " $3 " " v; next }
		/^\([0-9]+\/[0-9]+\) Upgrading / { print "     · обновляем " $3; next }
		/^\([0-9]+\/[0-9]+\) (Purging|Deleting) / { print "     · удаляем " $3; next }
		/^OK: [0-9]+ distinct packages available/ { print "     · доступно пакетов: " $2; next }
		/^fetch / { next }
		/ubus call service delete .*Not found/ { next }
		/(write error|[Ww]rite error): [Bb]roken pipe|^[^ ]*: [Bb]roken pipe$/ { next }
		/linuxfw: clear ip6?tables: exec: "ip6?tables": executable file not found/ { next }
		/router: enumerating tailscale0 addresses for cleanup failed/ { next }
		/[Ee]rror|ERROR|Collected errors|^ \* |[Uu]nknown package|not found|No such|unable|cannot|failed|Failed|unsatisfiable|breaks:/ { l = $0; sub(/^[ *]+/, "", l); if (l != "" && !seen[l]++) print "     ! " l; next }
	'
}

_zm_pkg_names() {
	local a out=""
	for a; do
		case "$a" in -*) continue ;; esac
		a="${a##*/}"
		out="$out${out:+, }$a"
	done
	echo "$out"
}

_zm_pkg_update() {
	local try=1 rc t0 bad h
	h="$(_mirror_host)"
	while :; do
		t0="$(date +%s)"
		echo "   → Скачиваем свежий список пакетов из репозитория"
		_zm_run 150 $PKG_UPD > "/tmp/zm-pkg.$$" 2>&1
		rc=$?
		_zm_pkg_fmt < "/tmp/zm-pkg.$$"
		bad=""; [ -n "$h" ] && _mirror_upd_bad "/tmp/zm-pkg.$$" "$h" && bad=1
		rm -f "/tmp/zm-pkg.$$"
		if [ "$rc" = 0 ] && [ -z "$bad" ]; then
			echo "   ✓ Список пакетов обновлён за $(( $(date +%s) - t0 )) с"
			return 0
		fi
		_zm_pkg_unlock
		[ "$try" -ge 2 ] && break
		_zm_dns_ok "$(h="${h:-downloads.openwrt.org}"; echo "${h%%/*}")" || _zm_net_heal
		echo "   ↻ $([ "$rc" = 0 ] && echo "Обновился не полностью" || echo "Не получилось") — пробуем ещё раз"
		try=$((try + 1))
		sleep 3
	done
	if { [ -n "$bad" ] || [ "$rc" != 0 ]; } && [ -n "$h" ]; then
		if [ -n "$bad" ] || ! _mirror_probe "$h" "$(_mirror_feed1)" >/dev/null; then
			_mirror_auto && return 0
		fi
	fi
	if [ "$rc" = 0 ]; then
		echo "   ! Список пакетов обновился не полностью — часть репозиториев не ответила"
		return 0
	fi
	echo "   ✗ Список пакетов не обновился — проверьте интернет и доступ к ${h:-downloads.openwrt.org}"
	return 1
}

_zm_pkg_add() {
	local rc names p miss=""
	names="$(_zm_pkg_names "$@")"
	echo "   → Устанавливаем: $names"
	_zm_run 300 $PKG_ADD "$@" > "/tmp/zm-pkg.$$" 2>&1
	rc=$?
	_zm_pkg_fmt < "/tmp/zm-pkg.$$"
	rm -f "/tmp/zm-pkg.$$"
	_zm_pkg_unlock
	if [ "$rc" = 0 ]; then echo "   ✓ Установлено: $names"
	else
		for p; do case "$p" in -*|*/*|*.ipk|*.apk) continue ;; esac; _pkg_is_installed "$p" || miss="$miss${miss:+, }$p"; done
		echo "   ✗ Не установилось: ${miss:-$names}"
	fi
	return $rc
}

_zm_ca_have() { ls /etc/ssl/certs/*.crt >/dev/null 2>&1; }

_zm_pkg_del() {
	local rc p have="" names ca=0
	_zm_ca_have && ca=1
	for p; do
		case "$p" in -*) have="$have $p"; continue ;; esac
		_pkg_is_installed "$p" && have="$have $p"
	done
	names="$(_zm_pkg_names $have)"
	[ -n "$names" ] || return 0
	echo "   → Удаляем пакеты: $names"
	_zm_run 180 $PKG_DEL $have > "/tmp/zm-pkg.$$" 2>&1
	rc=$?
	_zm_pkg_fmt < "/tmp/zm-pkg.$$"
	rm -f "/tmp/zm-pkg.$$"
	_zm_pkg_unlock
	if [ "$rc" = 0 ]; then echo "   ✓ Удалено: $names"
	else echo "   ✗ Не удалось удалить: $names"; fi
	[ "$ca" = 1 ] && _zm_ca_keep
	return $rc
}

_zm_ca_keep() {
	_zm_ca_have && return 0
	echo "   → Возвращаем корневые сертификаты (ca-bundle) — без них не работает HTTPS"
	_zm_run 180 $PKG_ADD ca-bundle >/dev/null 2>&1 || { _zm_run 150 $PKG_UPD >/dev/null 2>&1; _zm_run 180 $PKG_ADD ca-bundle >/dev/null 2>&1; }
	if _zm_ca_have; then echo "   ✓ Сертификаты на месте"
	else echo "   ! Не удалось поставить ca-bundle — установите его вручную, иначе HTTPS-загрузки не заработают"; fi
	return 0
}

job_start() {
	local name="$1"; shift
	local log="$JOBS_DIR/$name.log"
	local pid="$JOBS_DIR/$name.pid"
	if _job_running "$name"; then
		printf '{"started":true,"job":"%s","already_running":true}\n' "$name"
		return 0
	fi
	: > "$log"
	( ZM_JOB_LOG="$log"; export ZM_JOB_LOG; _bk_auto "$@" >>"$log" 2>&1; "$@" >>"$log" 2>&1; rc=$?; _zm_net_restore >>"$log" 2>&1; [ -n "$(tail -c 1 "$log" 2>/dev/null)" ] && echo >>"$log"; echo "__DONE__ $rc" >>"$log" ) &
	echo $! > "$pid"
	printf '{"started":true,"job":"%s"}\n' "$name"
}

_zm_wait() {
	local p rc t="/tmp/zm-wait.$$.$RANDOM" tmo=600
	shift
	( ZM_IN_WAIT=1; export ZM_IN_WAIT; "$@" ) > "$t.o" 2> "$t.e" &
	p=$!
	_zm_dots "$p" "$tmo"
	wait "$p" 2>/dev/null
	rc=$?
	cat "$t.o"
	[ "$rc" = 0 ] || cat "$t.e" >&2
	rm -f "$t.o" "$t.e"
	return $rc
}

_zm_quiet() {
	local p rc t="/tmp/zm-quiet.$$.$RANDOM" tmo=600
	shift
	( ZM_IN_WAIT=1; export ZM_IN_WAIT; "$@" ) > "$t" 2>&1 &
	p=$!
	_zm_dots "$p" "$tmo"
	wait "$p" 2>/dev/null
	rc=$?
	[ "$rc" = 0 ] || tail -n 8 "$t" | sed 's/^/   /'
	rm -f "$t"
	return $rc
}

_zm_sleep() {
	sleep "$1" &
	_zm_dots $! "$(( $1 + 5 ))"
	wait $! 2>/dev/null
	return 0
}

_zm_cron_drop() {
	local pat="$1" what="$2"
	grep -qiE "$pat" "$CRON_FILE" 2>/dev/null || return 0
	echo "   → Убираем задания $what из расписания (cron)"
	grep -viE "$pat" "$CRON_FILE" > "$CRON_FILE.zm" 2>/dev/null
	if [ $? -le 1 ] && [ -f "$CRON_FILE.zm" ]; then cat "$CRON_FILE.zm" > "$CRON_FILE"; fi
	rm -f "$CRON_FILE.zm"
	/etc/init.d/cron restart >/dev/null 2>&1
	echo "   ✓ Расписание очищено"
}

_zm_dns_scrub() {
	local rx="$1" s v ch=0 sc
	for s in $(uci -q show dhcp | sed -n "s/^dhcp\.\([^.=]*\)=dnsmasq\$/\1/p"); do
		sc=0
		for v in $(uci -q get "dhcp.$s.server"); do
			printf '%s' "$v" | grep -qE "$rx" && { uci -q del_list "dhcp.$s.server=$v"; ch=1; sc=1; }
		done
		if [ "$sc" = 1 ] && [ -z "$(uci -q get "dhcp.$s.server" | tr ' ' '\n' | grep -v '^/')" ] && [ "$(uci -q get "dhcp.$s.noresolv")" = 1 ]; then
			uci -q delete "dhcp.$s.noresolv"
		fi
	done
	[ "$ch" = 1 ] && { uci -q commit dhcp; echo "   ✓ Из настроек DNS роутера убраны оставшиеся ссылки"; }
	return 0
}

_zm_svc_off() {
	[ -x "/etc/init.d/$1" ] || return 0
	echo "   → Останавливаем службу $1 и убираем её из автозапуска"
	_zm_run 60 "/etc/init.d/$1" stop >/dev/null 2>&1
	"/etc/init.d/$1" disable >/dev/null 2>&1
	return 0
}

ZM_RESOLV_BAK="$JOBS_DIR/resolv.conf.zm-bak"

_zm_dns_ok() { nslookup "$1" >/dev/null 2>&1; }

_zm_host_ok() {
	curl -s -o /dev/null --connect-timeout 6 --max-time 12 "https://$1/" >/dev/null 2>&1
	case $? in 0|22|35|47|52|56|60) return 0 ;; esac
	return 1
}

ZM_REBOOT_HINT="$JOBS_DIR/reboot.hint"

_zm_reboot_hint() {
	mkdir -p "$JOBS_DIR"
	printf '%s\n%s\n' "$1" "$(date +%s)" > "$ZM_REBOOT_HINT"
}

_zm_reboot_hint_get() {
	local ts now
	[ -s "$ZM_REBOOT_HINT" ] || return 0
	ts="$(sed -n 2p "$ZM_REBOOT_HINT" 2>/dev/null)"
	now="$(date +%s)"
	case "$ts" in
		''|*[!0-9]*) rm -f "$ZM_REBOOT_HINT"; return 0 ;;
		*) [ $((now - ts)) -gt 120 ] && { rm -f "$ZM_REBOOT_HINT"; return 0; } ;;
	esac
	head -n1 "$ZM_REBOOT_HINT"
}

_zm_inet_ok() {
	nslookup ya.ru 127.0.0.1 >/dev/null 2>&1 || nslookup cloudflare.com 127.0.0.1 >/dev/null 2>&1 || return 1
	_zm_host_ok ya.ru || _zm_host_ok www.cloudflare.com || _zm_host_ok www.google.com
}

_zm_inet_wait() {
	local t=0
	while [ "$t" -lt "$1" ]; do
		_zm_inet_ok && return 0
		sleep 3; t=$((t + 3))
	done
	return 1
}

_zm_ip_ok() {
	ping -4 -c 1 -W 2 77.88.8.8 >/dev/null 2>&1 || ping -4 -c 1 -W 2 1.1.1.1 >/dev/null 2>&1 ||
		curl -s -o /dev/null --connect-timeout 4 --max-time 6 http://1.1.1.1/ >/dev/null 2>&1
}
_zm_net_why() {
	if _zm_ip_ok; then
		echo "   · Связь по IP есть, а имена сайтов роутер не находит — не работает DNS роутера. Откройте вкладку «DNS over HTTPS» (другой сервер или выключить), не поможет — перезагрузите роутер"
	else
		echo "   · Роутер не достаёт до интернета даже по IP-адресу — перезагрузите роутер; не поможет — проверьте кабель и настройки провайдера (Сеть → Интерфейсы → WAN)"
	fi
}

_zm_net_recover() {
	_rb_say "Проверяем интернет и DNS после удаления"
	/etc/init.d/firewall restart >/dev/null 2>&1
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	if _zm_inet_wait 15; then
		echo "   ✓ Интернет и DNS на роутере работают"
		return 0
	fi
	if _zm_ip_ok; then
		_rb_warn "Связь есть, а DNS роутера не отвечает — перезапускаем службы DNS"
		[ -x /etc/init.d/https-dns-proxy ] && /etc/init.d/https-dns-proxy enabled 2>/dev/null && _zm_run 30 /etc/init.d/https-dns-proxy restart >/dev/null 2>&1
		/etc/init.d/dnsmasq restart >/dev/null 2>&1
		if _zm_inet_wait 20; then
			echo "   ✓ После перезапуска DNS интернет на роутере работает"
			return 0
		fi
	fi
	_rb_warn "Интернет не отвечает — перезапускаем сеть (панель может на полминуты потерять связь с роутером)"
	_zm_run 90 /etc/init.d/network restart >/dev/null 2>&1
	sleep 5
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	if _zm_inet_wait 45; then
		echo "   ✓ После перезапуска сети интернет работает"
		return 0
	fi
	_rb_warn "Интернет так и не появился — перезагрузите роутер"
	_zm_net_why
	return 1
}

_zm_after_remove() {
	if _zm_net_recover; then
		_zm_reboot_hint "$1 удалён. Желательно перезагрузить роутер."
		ZM_RB_NOTE="   Желательно перезагрузить роутер — кнопка «Перезагрузить» появилась внизу страницы на 2 минуты"
	else
		_zm_reboot_hint "$1 удалён, но интернет на роутере не отвечает. Перезагрузите роутер."
		ZM_RB_NOTE="!! Перезагрузите роутер — кнопка «Перезагрузить» появилась внизу страницы на 2 минуты"
	fi
}
_zm_rb_note() {
	[ -n "$ZM_RB_NOTE" ] && echo "$ZM_RB_NOTE"
	ZM_RB_NOTE=""
	return 0
}

reboot_hint_clear() {
	rm -f "$ZM_REBOOT_HINT"
	printf '{"ok":true}\n'
}

system_reboot() {
	local j
	j="$(_zm_busy_job)" && { printf '{"error":"%s"}\n' "$(esc "Сейчас идёт операция: $j — дождитесь её окончания")"; return 1; }
	rm -f "$ZM_REBOOT_HINT"
	( sleep 2; sync; reboot ) >/dev/null 2>&1 </dev/null &
	printf '{"ok":true}\n'
}

_zm_if_web() {
	local u
	for u in https://1.1.1.1/cdn-cgi/trace https://www.google.com/generate_204 https://www.cloudflare.com/cdn-cgi/trace; do
		curl -s -o /dev/null --interface "$1" --connect-timeout 4 --max-time 7 "$u" 2>/dev/null && return 0
	done
	return 1
}

_zm_net_own() {
	[ -n "$ZM_JOB_LOG" ] || return 0
	grep -qxF "$ZM_JOB_LOG" "$ZM_RESOLV_BAK.owners" 2>/dev/null || echo "$ZM_JOB_LOG" >> "$ZM_RESOLV_BAK.owners"
}

_zm_net_others() {
	local o
	[ -f "$ZM_RESOLV_BAK.owners" ] || return 1
	while read -r o; do
		[ -n "$o" ] && [ "$o" != "$ZM_JOB_LOG" ] || continue
		_job_running "$(basename "$o" .log)" && return 0
	done < "$ZM_RESOLV_BAK.owners"
	return 1
}

_zm_net_orphan() {
	[ -f "$ZM_RESOLV_BAK" ] || return 1
	if [ -s "$ZM_RESOLV_BAK.owners" ]; then
		_zm_net_others && return 1
		return 0
	fi
	[ -z "$(_zm_busy_job)" ]
}

_zm_net_heal() {
	if [ -f "$ZM_RESOLV_BAK" ]; then _zm_net_own; return 0; fi
	local src=/tmp/resolv.conf
	[ -s "$src" ] || src=/etc/resolv.conf
	[ -s "$src" ] || return 1
	cat "$src" > "$ZM_RESOLV_BAK.new" 2>/dev/null && [ -s "$ZM_RESOLV_BAK.new" ] || { rm -f "$ZM_RESOLV_BAK.new"; return 1; }
	mv -f "$ZM_RESOLV_BAK.new" "$ZM_RESOLV_BAK"
	rm -f "$ZM_RESOLV_BAK.owners"
	_zm_net_own
	printf 'nameserver 1.1.1.1\nnameserver 9.9.9.9\n' > /tmp/resolv.conf 2>/dev/null || printf 'nameserver 1.1.1.1\nnameserver 9.9.9.9\n' > /etc/resolv.conf
	echo "   → DNS роутера не отвечает — на время операции берём 1.1.1.1 и 9.9.9.9"
}

_zm_local_dns_up() {
	pidof dnsmasq >/dev/null 2>&1 && return 0
	netstat -lnu 2>/dev/null | grep -qE '[[:space:]](127\.0\.0\.1|0\.0\.0\.0|::1?|:::?):53[[:space:]]'
}

_zm_net_restore() {
	[ -f "$ZM_RESOLV_BAK" ] || return 0
	if [ "$1" != force ] && [ -n "$ZM_JOB_LOG" ]; then
		local lk="$ZM_RESOLV_BAK.lock" i=0
		while ! mkdir "$lk" 2>/dev/null; do
			i=$((i + 1)); [ "$i" -ge 10 ] && { rmdir "$lk" 2>/dev/null; continue; }
			sleep 1
		done
		if [ -s "$ZM_RESOLV_BAK.owners" ] && ! grep -qxF "$ZM_JOB_LOG" "$ZM_RESOLV_BAK.owners"; then rmdir "$lk"; return 0; fi
		grep -vxF "$ZM_JOB_LOG" "$ZM_RESOLV_BAK.owners" > "$ZM_RESOLV_BAK.o2.$$" 2>/dev/null
		mv -f "$ZM_RESOLV_BAK.o2.$$" "$ZM_RESOLV_BAK.owners"
		if _zm_net_others; then rmdir "$lk"; return 0; fi
		rmdir "$lk"
	fi
	mv -f "$ZM_RESOLV_BAK" "$ZM_RESOLV_BAK.r" 2>/dev/null || return 0
	if [ -s "$ZM_RESOLV_BAK.r" ] && ! grep '^nameserver' "$ZM_RESOLV_BAK.r" | grep -qvE '^nameserver[[:space:]]+(127\.|::1)' && ! _zm_local_dns_up; then
		rm -f "$ZM_RESOLV_BAK.r" "$ZM_RESOLV_BAK.owners"
		echo "   ! На роутере не запущен DNS-сервер — оставляем внешние DNS, иначе роутер останется без интернета по именам"
		return 0
	fi
	if [ -s "$ZM_RESOLV_BAK.r" ]; then
		if [ -e /tmp/resolv.conf ]; then cat "$ZM_RESOLV_BAK.r" > /tmp/resolv.conf; else cat "$ZM_RESOLV_BAK.r" > /etc/resolv.conf; fi
	fi
	rm -f "$ZM_RESOLV_BAK.r" "$ZM_RESOLV_BAK.owners"
	echo "   ✓ Обычный DNS роутера возвращён"
}

_zm_feed_host() {
	local h
	h="$(_mirror_host)"
	h="${h%%/*}"
	echo "${h:-downloads.openwrt.org}"
}

_zm_net_prepare() {
	local h bad=""
	_fk_say "Проверяем доступ к источникам: $*"
	for h in "$@"; do _zm_dns_ok "$h" || bad="$bad $h"; done
	if [ -n "$bad" ]; then
		_zm_net_heal
		for h in $bad; do _zm_dns_ok "$h" || { echo "ОШИБКА: не удаётся узнать адрес $h — проверьте интернет на роутере"; _zm_net_restore; return 1; }; done
	fi
	for h in "$@"; do
		if ! _zm_host_ok "$h"; then
			echo "ОШИБКА: $h не отвечает — возможно, он недоступен у провайдера. Ничего не меняли"
			_zm_net_restore
			return 1
		fi
	done
	echo "   ✓ Источники доступны"
	return 0
}

FK_GUARD_PID="$JOBS_DIR/fk-guard.pid"
_fk_guard_on() { grep -q "option zm_ut_guard '1'" /etc/config/netshift 2>/dev/null; }
_fk_guard_pass() { _fk_up && ! _job_running forkop && _fk_uc guard >/dev/null 2>&1; return 0; }
_fk_guard() {
	local i=0
	_fk_guard_on || { rm -f "$FK_GUARD_PID"; return 0; }
	[ -f "$FK_GUARD_PID" ] && kill -0 "$(cat "$FK_GUARD_PID" 2>/dev/null)" 2>/dev/null && return 0
	mkdir -p "$JOBS_DIR"
	(
		_fk_guard_pass
		while [ "$i" -lt 5 ]; do
			sleep 20
			_fk_guard_on && _fk_ours || break
			_fk_guard_pass
			i=$((i + 1))
		done
		rm -f "$FK_GUARD_PID"
	) >/dev/null 2>&1 </dev/null &
	echo $! > "$FK_GUARD_PID"
	return 0
}

_fk_watch() {
	local f="$ZM_STATE_DIR/fk.watch" n=0 last=0 now wait
	_fk_installed && _fk_enabled || { rm -f "$f"; return 0; }
	_fk_engine_busy && return 0
	if _fk_up; then
		rm -f "$f"
		_job_running forkop || _fk_heal
		_job_running forkop || _fk_zash_ensure quiet
		_job_running forkop || _fk_dns_watch
		_fk_guard
		return 0
	fi
	_job_running forkop && return 0
	[ -n "$(_fk_blocker)" ] && return 0
	{ read -r n last < "$f"; } 2>/dev/null
	n="${n:-0}"; last="${last:-0}"
	now="$(date +%s)"
	wait=$((120 * (1 << (n > 4 ? 4 : n))))
	[ $((now - last)) -lt "$wait" ] && return 0
	logger -t zapret-manager "Forkozz включён, но sing-box или его правила не работают — перезапускаем (попытка $((n + 1)))"
	_fk_sb_alive || ( FK_LOGMARK=""; _fk_say() { :; }; _fk_rs_check recent >/dev/null 2>&1 )
	mkdir -p "$ZM_STATE_DIR"
	echo "$((n + 1)) $now" > "$f"
	_zm_run 180 /etc/init.d/netshift restart >/dev/null 2>&1
	return 0
}

_fk_heal() {
	local s first=1
	for s in $(_fk_uc secnames 2>/dev/null); do
		case "$s" in *[!A-Za-z0-9_]*|'') continue ;; esac
		[ -s "$ZM_STATE_DIR/fk.home.$s" ] && _fk_home_sec "$s" >/dev/null 2>&1 &
		if [ "$(uci -q get netshift."$s".zm_auto_ping)" = 1 ] && [ "$(uci -q get netshift."$s".zm_sub_priority)" != 1 ]; then
			/opt/zapret-manager-luci/backend.sh forkop_ping_burst "$s" >/dev/null 2>&1 &
			_fk_fallback_sec "$s" >/dev/null 2>&1 &
			continue
		fi
		if [ "$(uci -q get netshift."$s".zm_direct_fallback)" = 1 ] || [ "$(uci -q get netshift."$s".zm_sub_priority)" = 1 ]; then
			_fk_fallback_sec "$s" >/dev/null 2>&1 &
			continue
		fi
		if [ "$first" = 1 ]; then _fk_heal_sec "$s" ""; first=0; else _fk_heal_sec "$s" ".$s"; fi
	done
	return 0
}

_fk_ping_burst() {
	local sec="$1" lock="/tmp/zm-fk-pingloop.$1" pid i=0
	case "$sec" in *[!A-Za-z0-9_]*|'') return 1 ;; esac
	if [ -d "$lock" ]; then
		pid="$(cat "$lock/pid" 2>/dev/null)"
		case "$pid" in ''|*[!0-9]*) ;; *) kill -0 "$pid" 2>/dev/null && return 0 ;; esac
		rm -rf "$lock"
	fi
	mkdir "$lock" 2>/dev/null || return 0
	echo "$$" > "$lock/pid"
	trap "rm -rf '$lock'" EXIT
	while [ "$i" -lt 5 ]; do
		sleep 20
		_fk_up || return 0
		[ "$(uci -q get netshift."$sec".zm_auto_ping)" = 1 ] || return 0
		_fk_fallback_sec "$sec" >/dev/null 2>&1
		i=$((i + 1))
	done
	return 0
}

_fk_fallback_sec() (
	local sec="$1" lock="/tmp/zm-fk-fallback.$1.lock" at=0 now pid r to priority
	case "$sec" in *[!A-Za-z0-9_]*|'') exit 1 ;; esac
	now="$(date +%s)"
	if [ -d "$lock" ]; then
		pid="$(cat "$lock/pid" 2>/dev/null)"
		case "$pid" in ''|*[!0-9]*) ;; *) kill -0 "$pid" 2>/dev/null && exit 0 ;; esac
		at="$(cat "$lock/at" 2>/dev/null)"
		case "$at" in ''|*[!0-9]*) at="$(stat -c %Y "$lock" 2>/dev/null)"; at="${at:-$now}" ;; esac
		[ $((now - at)) -gt 600 ] && rm -rf "$lock"
	fi
	mkdir "$lock" 2>/dev/null || exit 0
	echo "$now" > "$lock/at"
	trap 'rm -rf "$lock"' EXIT
	r="$(_fk_uc fallwatch "$sec" 2>/dev/null)"
	if [ "$(printf '%s' "$r" | jsonfilter -e '@.manual' 2>/dev/null)" = true ]; then _fk_heal_sec "$sec" ".$sec"; exit 0; fi
	[ "$(printf '%s' "$r" | jsonfilter -e '@.changed' 2>/dev/null)" = true ] || exit 0
	to="$(printf '%s' "$r" | jsonfilter -e '@.direct' 2>/dev/null)"
	priority="$(printf '%s' "$r" | jsonfilter -e '@.priority' 2>/dev/null)"
	if [ "$to" = true ]; then logger -t zapret-manager "Forkozz: VPN секции $sec недоступны — её правила временно идут напрямую"
	elif [ "$priority" = true ]; then logger -t zapret-manager "Forkozz: секция $sec выбрала первую доступную подписку по заданному порядку"
	else logger -t zapret-manager "Forkozz: VPN секции $sec снова доступен — возвращаем её правила через VPN"; fi
)

_fk_home_sec() (
	local sec="$1" lock="/tmp/zm-fk-home.$1"
	case "$sec" in *[!A-Za-z0-9_]*|'') exit 1 ;; esac
	if [ -d "$lock" ]; then
		[ -n "$(find "$lock" -maxdepth 0 -mmin +5 2>/dev/null)" ] && rm -rf "$lock"
	fi
	mkdir "$lock" 2>/dev/null || exit 0
	trap 'rm -rf "$lock"' EXIT
	_fk_uc home "$sec" >/dev/null 2>&1
)

_fk_heal_sec() {
	local sec="$1" f="$JOBS_DIR/fk.heal$2" r n=0 name to
	r="$(_fk_uc heal "$sec" 2>/dev/null)"
	[ "$(printf '%s' "$r" | jsonfilter -e '@.dead' 2>/dev/null)" = true ] || { rm -f "$f" "$f.hold"; return 0; }
	if [ "$(printf '%s' "$r" | jsonfilter -e '@.hold' 2>/dev/null)" = true ]; then
		name="$(printf '%s' "$r" | jsonfilter -e '@.name' 2>/dev/null)"
		if [ "$(cat "$f.hold" 2>/dev/null)" != "$name" ]; then
			printf '%s\n' "$name" > "$f.hold"
			logger -t zapret-manager "Forkozz: выбранный сервер «$name» не отвечает — держим его, как задано в настройке"
		fi
		return 0
	fi
	_zm_inet_ok || return 0
	n="$(cat "$f" 2>/dev/null)"; n=$(( ${n:-0} + 1 ))
	echo "$n" > "$f"
	[ "$n" -ge 2 ] || return 0
	[ "$n" -gt 2 ] && [ $((n % 15)) -ne 0 ] && return 0
	r="$(_fk_uc heal "$sec" switch 2>/dev/null)"
	if [ "$(printf '%s' "$r" | jsonfilter -e '@.changed' 2>/dev/null)" = true ]; then
		name="$(printf '%s' "$r" | jsonfilter -e '@.name' 2>/dev/null)"
		to="$(printf '%s' "$r" | jsonfilter -e '@.to' 2>/dev/null)"
		if [ "$(printf '%s' "$r" | jsonfilter -e '@.back' 2>/dev/null)" = true ]; then
			logger -t zapret-manager "Forkozz: сервер «$name» не отвечает — переключились на ${to:-автовыбор}, вернёмся на него, когда он ответит"
		else logger -t zapret-manager "Forkozz: сервер «$name» не отвечает — переключились на ${to:-автовыбор}"; fi
		rm -f "$f"
	fi
	return 0
}

_fk_dns_watch() {
	local f="$ZM_STATE_DIR/fk.dnsfo" t cur v best="" tmp="$JOBS_DIR/fk-dnsfo.$$" ok cnt=0 want="" cur_ok=0 l
	[ "$(uci -q get netshift.settings.dns_via_outbound)" = 1 ] && { rm -f "$f"; return 0; }
	case "$(uci -q get netshift.settings.dns_pool_mode)" in fallback|race) rm -f "$f"; return 0 ;; esac
	set -- $(uci -q get netshift.settings.zm_dns_servers)
	[ $# -gt 1 ] || { rm -f "$f"; return 0; }
	t="$(uci -q get netshift.settings.dns_type)"; cur="$(uci -q get netshift.settings.dns_server)"
	mkdir -p "$JOBS_DIR"
	for v in "$@"; do
		ok=0
		_fk_dns_probe "$t" "$v" "$tmp"
		IFS='|' read -r l ok l l < "$tmp" 2>/dev/null
		rm -f "$tmp"
		[ "$ok" = 1 ] && { best="$v"; break; }
	done
	[ -n "$best" ] && [ "$best" != "$cur" ] || { rm -f "$f"; return 0; }
	ok=0
	_fk_dns_probe "$t" "$cur" "$tmp"
	IFS='|' read -r l ok l l < "$tmp" 2>/dev/null
	rm -f "$tmp"
	[ "$ok" = 1 ] && cur_ok=1
	{ read -r want cnt < "$f"; } 2>/dev/null
	[ "$want" = "$best" ] && cnt=$(( ${cnt:-0} + 1 )) || cnt=1
	echo "$best $cnt" > "$f"
	[ "$cnt" -ge 2 ] || return 0
	rm -f "$f"
	uci -q set netshift.settings.dns_server="$best" && uci -q commit netshift
	if [ "$cur_ok" = 1 ]; then logger -t zapret-manager "Forkozz: DNS $best снова отвечает — возвращаемся к нему"
	else logger -t zapret-manager "Forkozz: DNS $cur не отвечает — переключились на $best"; fi
	( _zm_run 180 /usr/bin/netshift reload >/dev/null 2>&1 & )
	return 0
}

ZRAM_OWN="$ZM_STATE_DIR/zram.own"
_zram_on() { grep -q '^/dev/zram' /proc/swaps 2>/dev/null; }
_zram_has() { _pkg_is_installed zram-swap || [ -x /etc/init.d/zram ]; }
zram_status() {
	local ram on=false inst=false en=false own=false sz=0 used=0 algo="" busy=false
	ram="$(awk '$1 == "MemTotal:" { print int($2 / 1024); exit }' /proc/meminfo 2>/dev/null)"
	_zram_on && on=true
	_zram_has && inst=true
	[ -x /etc/init.d/zram ] && /etc/init.d/zram enabled >/dev/null 2>&1 && en=true
	[ -f "$ZRAM_OWN" ] && own=true
	set -- $(awk '$1 ~ /^\/dev\/zram/ { s += $3; u += $4 } END { printf "%d %d", s / 1024, u / 1024 }' /proc/swaps 2>/dev/null)
	sz="${1:-0}"; used="${2:-0}"
	algo="$(sed -n 's/.*\[\([^]]*\)\].*/\1/p' /sys/block/zram0/comp_algorithm 2>/dev/null | head -n1)"
	_job_running zram && busy=true
	printf '{"ram_mb":%s,"on":%s,"installed":%s,"enabled":%s,"own":%s,"size_mb":%s,"used_mb":%s,"algo":"%s","busy":%s,"oom":%s}\n' \
		"${ram:-0}" "$on" "$inst" "$en" "$own" "$sz" "$used" "$(esc "$algo")" "$busy" "$(_zm_oom_json)"
}
do_zram() {
	case "$1" in
		on)
			echo "==> Включаем ZRAM — сжатую подкачку в оперативной памяти"
			if ! _zram_has; then
				_zm_pkg_update || true
				_zm_pkg_add zram-swap || { echo "ОШИБКА: пакет zram-swap не установился — проверьте интернет на роутере и свободное место"; return 1; }
				mkdir -p "$ZM_STATE_DIR"; : > "$ZRAM_OWN"
			else
				echo "   ✓ Пакет zram-swap уже установлен"
			fi
			[ -x /etc/init.d/zram ] || { echo "ОШИБКА: после установки нет службы /etc/init.d/zram — пакет встал не полностью"; return 1; }
			echo "   → Включаем службу zram и её автозапуск"
			/etc/init.d/zram enable >/dev/null 2>&1
			_zram_on || /etc/init.d/zram start >/dev/null 2>&1
			sleep 2
			if ! _zram_on; then
				echo "ОШИБКА: ZRAM не запустился — похоже, в ядре этого роутера нет модуля zram (kmod-zram)"
				return 1
			fi
			echo "   ✓ ZRAM работает: $(awk '$1 ~ /^\/dev\/zram/ { s += $3 } END { printf "%d", s / 1024 }' /proc/swaps) МБ сжатой подкачки"
			logger -t zapret-manager "ZRAM включён — роутеру с малым объёмом памяти проще переживать пики"
			echo "==> Готово"
			;;
		off)
			echo "==> Выключаем ZRAM"
			if [ -x /etc/init.d/zram ]; then
				echo "   → Останавливаем службу zram и убираем её из автозапуска"
				/etc/init.d/zram stop >/dev/null 2>&1
				/etc/init.d/zram disable >/dev/null 2>&1
			fi
			if [ -f "$ZRAM_OWN" ]; then
				_zm_pkg_del zram-swap
				rm -f "$ZRAM_OWN"
			fi
			_zram_on && { echo "ОШИБКА: подкачка ZRAM всё ещё подключена — перезагрузите роутер"; return 1; }
			echo "   ✓ ZRAM выключен"
			echo "==> Готово"
			;;
		*) echo "ОШИБКА: неизвестное действие"; return 1 ;;
	esac
}
zram_action() {
	case "$1" in on|off) job_start zram do_zram "$1" ;; *) echo '{"error":"неизвестное действие"}'; return 1 ;; esac
}

mem_heal() {
	local f p=false low=false
	for f in /etc/init.d/mihomo "$TG_INIT_GO"; do
		[ -f "$f" ] || continue
		[ "$f" = /etc/init.d/mihomo ] && { grep -q 'MIHOMO_BIN=' "$f" || continue; }
		grep -q 'GOMEMLIMIT' "$f" && continue
		_zm_gml_patch "$f"
		grep -q 'GOMEMLIMIT' "$f" && p=true
	done
	[ "$(awk '$1 == "MemTotal:" { print $2; exit }' /proc/meminfo 2>/dev/null || echo 0)" -le 524288 ] 2>/dev/null && low=true
	printf '{"ok":true,"patched":%s,"low":%s}\n' "$p" "$low"
}

zm_watch() {
	rpcd_watch
	_zm_oom_watch
	_job_running backup && return 0
	_test_recover >/dev/null 2>&1
	_zm_net_orphan && _zm_net_restore force >/dev/null 2>&1
	if ! _fk_installed || ! _fk_foreign; then
		_fk_installed && [ ! -d /etc/sing-box ] && mkdir -p /etc/sing-box
		_fk_watch
		_fk_fast_patch
		_fk_mlkem_patch
		_fk_serial_patch
		_fk_listsvia_patch
		_fk_subvia_patch
		_fk_reality_patch
		_fk_rsinit_patch
		_fk_desync_patch
		_fk_fakeip_patch
		_fk_ghdl_patch
		_fk_subck_patch
		_fk_b4_watch
		_fk_ru_watch
		_fk_rs_watch
		if _fk_installed && _fk_enabled && _fk_up && _fk_fip_stale && ! _job_running forkop && [ -z "$(find "$JOBS_DIR/fk.fip.try" -mmin -30 2>/dev/null)" ]; then
			: > "$JOBS_DIR/fk.fip.try"
			logger -t zapret-manager "$(_fk_name): пул Fake IP изменился — перезапускаем"
			job_start forkop do_fk_service apply >/dev/null 2>&1
		fi
	fi
	_ft_zapret_sync
	_fk_installed && ! _fk_foreign && _fk_rl_watch
	_st_colo_guard
	_st_vpn_watch
	_st_secs_vpn_watch
	_tg_watch
	_ab_watch
	_dn_watch
	_zo_doh_follow
	_doh_boot_fill
	_ft_steer_sync
	return 0
}

_zm_job_skip() { case "$1" in versions|sysinfo|*_download|fk-guard) return 0 ;; esac; return 1; }

_zm_cancel_one() {
	local j="$1" pid log="$JOBS_DIR/$1.log"
	pid="$(cat "$JOBS_DIR/$j.pid" 2>/dev/null)"
	[ -n "$pid" ] && _zm_kill_tree "$pid"
	grep -q '^__DONE__' "$log" 2>/dev/null && return 0
	[ -n "$(tail -c 1 "$log" 2>/dev/null)" ] && echo >> "$log"
	echo "!! Операция остановлена вручную — все её процессы завершены" >> "$log"
	echo "__DONE__ 130" >> "$log"
	case "$j" in
		forkop)
			[ -d /usr/lib/netshift.zm-old ] && _fk_restore_old >> "$log" 2>&1
			rm -rf "$JOBS_DIR/netshift-src" ;;
		steer) rm -f "$ST_PHASE_FILE" 2>/dev/null; rmdir "$ST_RUN/cat.lock" 2>/dev/null; _st_warp_pre_clean ;;
		strategy_test) rm -f "$ZA_RUN" ;;
		install_zapret) _nochange_restore zapret >> "$log" 2>&1 ;;
		install_zapret2) _nochange_restore zapret2 >> "$log" 2>&1 ;;
		awg|mixomo_warp) ip link del "$AWG_TEST_IF" >/dev/null 2>&1; rm -f "$AWG_RUN/try.conf" ;;
		backup) rm -rf "$BK_RUN".op.* "$BK_RUN".mk.* "$BK_DIR"/.*.part "$BK_DIR"/.mk.*; rmdir "$BK_RUN.lock" 2>/dev/null; /etc/init.d/cron start >/dev/null 2>&1 ;;
	esac
}

jobs_cancel() {
	local f j list="" sep=""
	for f in "$JOBS_DIR"/*.pid; do
		[ -f "$f" ] || continue
		j="$(basename "$f" .pid)"
		_zm_job_skip "$j" && continue
		[ -n "$1" ] && [ "$1" != "$j" ] && continue
		_job_running "$j" || continue
		_zm_cancel_one "$j"
		list="$list$sep\"$j\""; sep=","
	done
	local busy=""
	for f in "$JOBS_DIR"/*.pid; do
		[ -f "$f" ] || continue
		_job_running "$(basename "$f" .pid)" && { busy=1; break; }
	done
	if [ -z "$busy" ]; then
		for f in /tmp/zm-run.* /tmp/zm-wait.* /tmp/zm-quiet.* /tmp/zm-pkg.*; do
			[ -e "$f" ] || continue
			_zm_tmp_live "$f" && continue
			rm -f "$f" 2>/dev/null
		done
	fi
	_zm_net_orphan && _zm_net_restore force >/dev/null 2>&1
	_zm_pkg_unlock
	printf '{"ok":true,"stopped":[%s]}\n' "$list"
}

_zm_rpcd_kick() {
	local i=0
	/etc/init.d/rpcd reload >/dev/null 2>&1
	while [ "$i" -lt 8 ]; do
		sleep 1; i=$((i + 1))
		if [ -n "$1" ]; then eval "$1" >/dev/null 2>&1 && return 0
		else ubus -t 3 list zapret-manager >/dev/null 2>&1 && return 0; fi
	done
	/etc/init.d/rpcd restart >/dev/null 2>&1
	return 1
}

rpcd_watch() {
	local rc mark="/tmp/zm-rpcd-slow"
	if ! pidof rpcd >/dev/null 2>&1; then
		logger -t zapret-manager "rpcd не запущен — запускаем, чтобы вернуть вход в LuCI"
		/etc/init.d/rpcd restart >/dev/null 2>&1
		return 0
	fi
	if ! ubus -t 5 list session >/dev/null 2>&1; then
		if [ -n "$(find "$mark" -mmin -5 2>/dev/null)" ]; then
			logger -t zapret-manager "rpcd не отвечает второй раз подряд — перезапускаем"
			rm -f "$mark"
			_zm_rpcd_kick 'ubus -t 3 list session'
		else touch "$mark"; fi
		return 0
	fi
	ubus -t 15 call session access '{"ubus_rpc_session":"00000000000000000000000000000000","scope":"ubus","object":"session","function":"access"}' >/dev/null 2>&1
	rc=$?
	if [ "$rc" = 7 ]; then
		if [ -n "$(find "$mark" -mmin -5 2>/dev/null)" ]; then
			logger -t zapret-manager "rpcd завис второй раз подряд — перезапускаем, чтобы вернуть вход в LuCI"
			rm -f "$mark"
			_zm_rpcd_kick 'ubus -t 5 call session access "{\"ubus_rpc_session\":\"00000000000000000000000000000000\",\"scope\":\"ubus\",\"object\":\"session\",\"function\":\"access\"}"'
		else touch "$mark"; fi
		return 0
	fi
	rm -f "$mark"
	_rpcd_plugin_watch
	return 0
}

_rpcd_plugin_watch() {
	local pl=/usr/libexec/rpcd/zapret-manager sig st stamp=/tmp/zm-rpcd-plugin.stamp
	[ -x "$pl" ] || return 0
	_rpcd_plugin_state "$pl" && { rm -f "$stamp"; return 0; }
	sleep 5
	_rpcd_plugin_state "$pl"
	st=$?
	[ "$st" = 0 ] && { rm -f "$stamp"; return 0; }
	sig="$(date -r "$pl" +%s 2>/dev/null)"
	if [ "$st" = 1 ]; then
		case "$(cat "$stamp" 2>/dev/null)" in
			"$sig.x3") return 0 ;;
			"$sig.x2") echo "$sig.x3" > "$stamp" ;;
			"$sig.x1") echo "$sig.x2" > "$stamp" ;;
			*) echo "$sig.x1" > "$stamp" ;;
		esac
		logger -t zapret-manager "rpcd не видит панель (Object not found) — перезапускаем rpcd"
	else
		[ "$(cat "$stamp" 2>/dev/null)" = "$sig.m" ] && return 0
		echo "$sig.m" > "$stamp"
		logger -t zapret-manager "rpcd держит старый список методов панели — перечитываем плагины rpcd"
	fi
	_zm_rpcd_kick '_rpcd_plugin_state /usr/libexec/rpcd/zapret-manager'
	return 0
}

_rpcd_plugin_state() {
	local want have
	ubus -t 5 list zapret-manager >/dev/null 2>&1 || return 1
	want="$(grep -c 'json_add_object' "$1" 2>/dev/null)"
	have="$(ubus -v list zapret-manager 2>/dev/null | grep -c '^[[:space:]]*"')"
	[ "${want:-0}" -gt 0 ] 2>/dev/null || return 0
	[ "${have:-0}" -gt 0 ] 2>/dev/null || return 0
	[ "$have" = "$want" ] && return 0
	return 2
}

ui_theme_set() {
	case "$1" in micro|light|dark|ink|bento|minimal|retro|depth|graphite|oled|matrix|auto) ;; *) echo '{"error":"неизвестная тема"}'; return 1 ;; esac
	mkdir -p "$ZM_STATE_DIR" /www/zm
	printf '%s\n' "$1" > "$ZM_STATE_DIR/ui.theme"
	printf '%s\n' "$1" > /www/zm/theme.txt
	chmod 0644 /www/zm/theme.txt 2>/dev/null
	printf '{"ok":true}\n'
}

UI_NAV_FILE="$ZM_STATE_DIR/ui.nav.hidden"
ui_nav_get() { [ -s "$UI_NAV_FILE" ] || return 0; tr '\n' ' ' < "$UI_NAV_FILE" | sed 's/  */ /g; s/^ //; s/ $//'; }
ui_nav_set() {
	local id out="" n=0
	for id in $(printf '%s' "$1" | tr ',' ' '); do
		printf '%s' "$id" | grep -qE '^[a-z0-9_]{1,32}$' || { echo '{"error":"неверный раздел"}'; return 1; }
		[ "$id" = dashboard ] && continue
		case " $out " in *" $id "*) continue ;; esac
		out="$out $id"; n=$((n + 1))
		[ "$n" -le 64 ] || { echo '{"error":"слишком много разделов"}'; return 1; }
	done
	mkdir -p "$ZM_STATE_DIR"
	if [ -n "$out" ]; then printf '%s\n' $out > "$UI_NAV_FILE"; else rm -f "$UI_NAV_FILE"; fi
	printf '{"ok":true,"hidden":"%s"}\n' "$(ui_nav_get)"
}

ui_flags_get() {
	local f="$ZM_STATE_DIR/ui.flags" out="" sep="" k
	if [ -s "$f" ]; then
		for k in $(grep -E '^[a-z0-9_]{1,48}$' "$f" | sort -u); do out="$out$sep\"$k\":1"; sep=","; done
	fi
	printf '{"flags":{%s}}\n' "$out"
}

ui_flag_set() {
	local f="$ZM_STATE_DIR/ui.flags" k="${1#-}"
	printf '%s' "$k" | grep -qE '^[a-z0-9_]{1,48}$' || { echo '{"error":"неверное имя"}'; return 1; }
	mkdir -p "$ZM_STATE_DIR"
	if [ "$k" != "$1" ]; then
		if grep -qx "$k" "$f" 2>/dev/null; then grep -vx "$k" "$f" > "$f.zm"; mv -f "$f.zm" "$f"; fi
	else
		grep -qx "$k" "$f" 2>/dev/null || echo "$k" >> "$f"
	fi
	printf '{"ok":true}\n'
}

UI_RADIO_FILE="$ZM_STATE_DIR/ui.radio"
ui_radio_get() {
	local st="" vol="" show=""
	[ -s "$UI_RADIO_FILE" ] && read -r st vol show < "$UI_RADIO_FILE"
	printf '%s' "$st" | grep -qE '^[a-z0-9_]{1,32}$' || st=""
	case "$vol" in ''|*[!0-9]*) vol=70 ;; esac
	[ "$vol" -le 100 ] 2>/dev/null || vol=100
	[ "$show" = 0 ] || show=1
	printf '{"station":"%s","volume":%s,"show":%s}\n' "$st" "$vol" "$([ "$show" = 1 ] && echo true || echo false)"
}
ui_radio_set() {
	local st vol show x
	read -r st vol show x <<EOF_ZMR
$1
EOF_ZMR
	printf '%s' "$st" | grep -qE '^[a-z0-9_]{1,32}$' || { echo '{"error":"неверная станция"}'; return 1; }
	case "$vol" in ''|*[!0-9]*) echo '{"error":"неверная громкость"}'; return 1 ;; esac
	[ "$vol" -le 100 ] || { echo '{"error":"неверная громкость"}'; return 1; }
	case "$show" in 0|1) ;; *) echo '{"error":"неверный параметр"}'; return 1 ;; esac
	mkdir -p "$ZM_STATE_DIR"
	printf '%s %s %s\n' "$st" "$vol" "$show" > "$UI_RADIO_FILE.zm" && mv -f "$UI_RADIO_FILE.zm" "$UI_RADIO_FILE"
	ui_radio_get
}

ZM_PEND_DIR="$JOBS_DIR/pend"
ZM_PEND_RKN="/opt/zapret/ipset/.zm-pend-rkn"
_pend_list() {
	printf '%s\n' "$CONF" "$ZO_RKN_FLAG" "$ZO_USER_FLAG" "$ZO_IPID_FLAG" "$ZO_DOH_FLAG" "$ZC_FILE" "$ZC_BAK" "$ZC_AFTER" \
		"$YV_OFF_FLAG" "$DV_OFF_FLAG" "$ZP_OWN" "$ZP_MANUAL" "$ZO_SCRIPT"
}
_pend_on() { [ -f "$ZM_PEND_DIR/on" ]; }
_pend_clear() { rm -rf "$ZM_PEND_DIR"; rm -f "$ZM_PEND_RKN"; }
_pend_begin() {
	local d="$ZM_PEND_DIR"
	_pend_on && return 0
	_pend_clear
	mkdir -p "$d/f" || return 1
	_pend_list | awk '{ print NR "\t" $0 }' | while IFS="$(printf '\t')" read -r i f; do
		[ -e "$f" ] || continue
		cp -p "$f" "$d/f/$i" || exit 1
	done || { _pend_clear; return 1; }
	[ -e "$ZO_RKN_FILE" ] && { ln -f "$ZO_RKN_FILE" "$ZM_PEND_RKN" 2>/dev/null || cp -p "$ZO_RKN_FILE" "$ZM_PEND_RKN" 2>/dev/null; }
	: > "$d/on"
}
_pend_cancel() {
	local d="$ZM_PEND_DIR"
	_pend_on || { _pend_clear; return 0; }
	_pend_list | awk '{ print NR "\t" $0 }' | while IFS="$(printf '\t')" read -r i f; do
		if [ -e "$d/f/$i" ]; then cp -p "$d/f/$i" "$f"; else rm -f "$f"; fi
	done
	if [ -e "$ZM_PEND_RKN" ]; then
		if [ -e "$ZO_RKN_FILE" ] && [ "$ZM_PEND_RKN" -ef "$ZO_RKN_FILE" ]; then rm -f "$ZM_PEND_RKN"
		else mv -f "$ZM_PEND_RKN" "$ZO_RKN_FILE"; fi
	fi
	_pend_clear
}
_pend_same() {
	local d="$ZM_PEND_DIR"
	_pend_on || return 1
	_pend_list | awk '{ print NR "\t" $0 }' | while IFS="$(printf '\t')" read -r i f; do
		if [ -e "$d/f/$i" ]; then cmp -s "$d/f/$i" "$f" || exit 1
		elif [ -e "$f" ]; then exit 1; fi
	done
}
_pend_was() {
	[ -s "$ZM_PEND_DIR/f/1" ] || return 0
	( CONF="$ZM_PEND_DIR/f/1"; ZM_NFQ_BODY=""; ZM_YS=""; ZM_UDP=""; ZM_DOH=""; ZM_RKN=""; ZM_FITS=""; _strat_label ) 2>/dev/null
}
zapret_pending() {
	[ -f "$CONF" ] || { echo '{"error":"Zapret не установлен"}'; return 1; }
	case "$1" in
		apply)
			if _pend_on; then
				_pend_clear
				zapret_restart
				logger -t zapret-manager "Zapret: применены выбранные изменения стратегии — $(_strat_label)"
			fi ;;
		cancel)
			_pend_on && logger -t zapret-manager "Zapret: выбранные изменения стратегии отменены"
			_pend_cancel ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
	status
}

zapret_restart() {
	[ -n "$ZM_NO_RESTART" ] && return 0
	if [ -n "$ZM_DEFER" ]; then : > "$ZM_PEND_DIR/dirty" 2>/dev/null; return 0; fi
	_pend_clear
	[ -s "$ZC_FILE" ] && _zc_drop
	_zp_sync
	_yv_ipid_sync
	_zo_doh_sync
	if [ -n "$(_fake_missing)" ]; then
		if [ -n "$ZM_JOB_LOG" ]; then _fake_ensure; else _zm_run 25 _fake_ensure >/dev/null 2>&1; fi
	fi
	if _zs2_on && [ -n "$(_fake_missing "$ZS2_OPT")" ]; then
		if [ -n "$ZM_JOB_LOG" ]; then _fake_ensure "$ZS2_OPT"; else _zm_run 25 _fake_ensure "$ZS2_OPT" >/dev/null 2>&1; fi
	fi
	_zs2_sync
	chmod -R a+rX /opt/zapret/ipset /opt/zapret/files 2>/dev/null
	[ -x /opt/zapret/sync_config.sh ] && /opt/zapret/sync_config.sh >/dev/null 2>&1
	/etc/init.d/zapret restart >/dev/null 2>&1
}

_strat_label() {
	local s
	s=$(_nfq_names | sed 's/^#[[:space:]]*//; s/[[:space:]]*$//; /^udp443$/d; /^DoH$/d; /^[Nn][Oo][Cc][Hh][Aa][Nn][Gg][Ee]$/d' | tr '\n' ' ' | sed 's/ $//')
	_yv_ipid_on && s="$(printf '%s' "$s" | sed -E 's/(^| )(Yv[0-9]+)( |$)/\1\2z\3/')"
	_udp443_on && s="${s:+$s }QUIC"
	_zo_doh_on && s="${s:+$s }DoH"
	{ _zc_has || [ -s "$ZC_FILE" ]; } && s="${s:+$s }Custom"
	[ -z "$s" ] && _nfq_opt_body | grep -q -- '^[[:space:]]*--' && s="своя"
	_zo_wss_on && s="${s:+$s }wssize"
	printf '%s' "$s"
}

status() {
	local zr="not_installed" zr_running="false" zr_ver=""
	_test_recover
	_pend_on || [ ! -e "$ZM_PEND_RKN" ] || rm -f "$ZM_PEND_RKN"
	if [ -f /etc/init.d/zapret ]; then
		zr="installed"
		zr_ver="$ZAPRET_VER"
		pgrep -f "/opt/zapre[t]/" >/dev/null 2>&1 && zr_running="true"
	fi

	local zr2="not_installed" zr2_running="false" zr2_luci=""
	if [ -f /etc/init.d/zapret2 ]; then
		zr2="installed"
		/etc/init.d/zapret2 status >/dev/null 2>&1 && zr2_running="true"
		zr2_luci="$(_z2_luci_path)"
	fi

	local strat="" fs_marker="" testing=false test_now="" ZM_NFQ_BODY="" zdd="" zdo=false ZM_YS="" ZM_UDP="" ZM_DOH="" ZM_RKN="" ZM_FITS=""
	if [ "$zr" = installed ]; then
		zdd="$(_zo_doh_hosts)"
		[ -n "$zdd" ] && zdo=true
		zdd="${zdd:-$ZO_DOH_DEF}"
	fi
	if [ -f "$CONF" ]; then
		ZM_NFQ_BODY="$(_nfq_opt_body)"
		ZM_YS="$(_yv_ipid_scan)"
		if _udp443_on; then ZM_UDP=1; else ZM_UDP=0; fi
		if _zo_doh_on; then ZM_DOH=1; else ZM_DOH=0; fi
		if _zo_rkn_on; then ZM_RKN=1; else ZM_RKN=0; fi
		if _zo_rkn_fits; then ZM_FITS=1; else ZM_FITS=0; fi
		strat=$(_strat_label)
		fs_marker=$(sed -n '/^# ZMFS:/{s/^# ZMFS://p;q}' "$CONF")
		if [ -s "$TEST_BACKUP" ] && _test_running; then
			testing=true; test_now="$strat"
			strat=$(CONF="$TEST_BACKUP"; ZM_NFQ_BODY=""; ZM_YS=""; ZM_UDP=""; ZM_DOH=""; ZM_RKN=""; ZM_FITS=""; _strat_label)
			fs_marker=$(sed -n '/^# ZMFS:/{s/^# ZMFS://p;q}' "$TEST_BACKUP")
			[ "$test_now" = "$strat" ] && test_now=""
		fi
	fi

	printf '{"pkg":"%s","zapret":"%s","zapret_running":%s,"zapret_version":"%s","zapret2":"%s","zapret2_running":%s,"strategy":"%s","flowseal":"%s","yv_off":%s,"quic_yt":%s,"expert":%s,"rkn":%s,"rkn_on":%s,"rkn_fits":%s,"rkn_count":%s,"wssize":%s,"ulist":%s,"ulist_on":%s,"ulist_count":%s,"testing":%s,"test_now":"%s","ipid":%s,"ipid_want":"%s","yt_tcp":%s,"z2_luci":"%s","zdoh":%s,"zdoh_on":%s,"zdoh_doms":"%s","zdoh_own":%s,"s2":%s,"pending":%s,"pending_was":"%s"}\n' \
		"$PKG" "$zr" "$zr_running" "$(esc "$zr_ver")" "$zr2" "$zr2_running" "$(esc "$strat")" "$(esc "$fs_marker")" \
		"$([ -f /opt/zapret-manager-luci/yv_off ] && echo true || echo false)" \
		"$([ -f "$CONF" ] && _udp443_on && echo true || echo false)" \
		"$([ -f "$EXPERT_MODE_FILE" ] && echo true || echo false)" \
		"$([ -f "$ZO_RKN_FLAG" ] && echo true || echo false)" \
		"$([ -f "$CONF" ] && _zo_rkn_on && echo true || echo false)" \
		"$([ -f "$CONF" ] && { _zo_rkn_fits || _zo_rkn_on; } && echo true || echo false)" \
		"$(awk 'NF { n++ } END { print n + 0 }' "$ZO_RKN_FILE" 2>/dev/null | grep . || echo 0)" \
		"$([ -f "$CONF" ] && _zo_wss_on && echo true || echo false)" \
		"$([ -f "$ZO_USER_FLAG" ] && echo true || echo false)" \
		"$([ -f "$CONF" ] && _zo_user_on && echo true || echo false)" \
		"$(_zo_user_count)" "$testing" "$(esc "$test_now")" \
		"$([ -f "$CONF" ] && _yv_ipid_on && echo true || echo false)" "$(_yv_ipid_want)" \
		"$([ -f "$CONF" ] && [ "${ZM_YS%% *}" -gt 0 ] 2>/dev/null && echo true || echo false)" "$(esc "$zr2_luci")" \
		"$([ -f "$ZO_DOH_FLAG" ] && echo true || echo false)" "$([ -f "$CONF" ] && _zo_doh_on && echo true || echo false)" \
		"$(esc "$zdd")" "$zdo" "$(_zs2_on && echo true || echo false)" \
		"$(_pend_on && echo true || echo false)" "$(_pend_on && esc "$(_pend_was)")"
}
_z2_luci_path() {
	grep -ho '"admin/[A-Za-z0-9_/-]*zapret2[A-Za-z0-9_/-]*"' /usr/share/luci/menu.d/*.json 2>/dev/null | tr -d '"' | grep -v 'zapret-manager' |
		awk '{ print length($0) "\t" $0 }' | sort -n | head -n 1 | cut -f 2
}

_do_install_zapret_core() {
	_ensure_deps
	if [ -f /etc/init.d/zapret2 ] && [ ! -f "$EXPERT_MODE_FILE" ]; then
		echo "ОШИБКА: установлен Zapret2, он несовместим с Zapret — сначала удалите Zapret2"
		return 1
	fi
	local ver="$ZAPRET_VER" arch url tmp ZM_ARCH_FB=1
	echo "==> Ставим Zapret $ver"
	arch="$(awk -F\' '/DISTRIB_ARCH/ {print $2}' /etc/openwrt_release)"
	url="${GH_MAIN}/remittor/zapret-openwrt/releases/download/v${ver}/zapret_v${ver}_${arch}.zip"
	tmp="$JOBS_DIR/install_tmp"; rm -rf "$tmp"; mkdir -p "$tmp"; cd "$tmp" || return 1

	echo "==> Обновляем список пакетов"
	$UPDATE

	if [ -f /etc/init.d/zapret ]; then
		echo "==> Останавливаем текущий Zapret"
		/etc/init.d/zapret stop >/dev/null 2>&1
		for p in $(pgrep -f "/opt/zapre[t]/" 2>/dev/null); do kill -9 "$p" 2>/dev/null; done
	fi

	echo "==> Скачиваем $url"
	local attempt=1 max_attempts=5
	while [ "$attempt" -le "$max_attempts" ]; do
		rm -f zapret.zip
		if ! _zm_fetch "$url" zapret.zip 300; then
			echo "!! Попытка $attempt из $max_attempts: архив не скачался — $ZM_FETCH_ERR"
			case "$ZM_FETCH_ERR" in *"(HTTP 404)"*|*"(HTTP 410)"*) attempt=$max_attempts ;; esac
		fi
		command -v unzip >/dev/null 2>&1 || { echo "==> Устанавливаем unzip"; $INSTALL unzip >&2; }
		if [ -s zapret.zip ] && unzip -tq zapret.zip >/dev/null 2>&1; then
			echo "   ✓ Архив скачан и проверен: $(_zm_size_txt "$(wc -c < zapret.zip | tr -d ' ')")"
			break
		fi
		if [ -s zapret.zip ]; then
			if command -v unzip >/dev/null 2>&1; then echo "!! Попытка $attempt из $max_attempts: архив скачался не целиком ($(wc -c < zapret.zip) байт)"
			else echo "!! Попытка $attempt из $max_attempts: архив скачан, но unzip не установился — проверьте список пакетов"; fi
		fi
		attempt=$((attempt + 1))
	done
	if [ "$attempt" -gt "$max_attempts" ]; then
		echo "ОШИБКА: не удалось скачать целый архив за $max_attempts попыток — проверьте соединение с GitHub"
		return 1
	fi
	unzip -o zapret.zip >/dev/null 2>&1

	echo "==> Устанавливаем пакеты"
	if [ "$PKG" = "apk" ]; then
		for p in apk/zapret*; do
			[ -f "$p" ] || continue
			echo "$p" | grep -q luci && continue
			echo "  - $(basename "$p")"; $INSTALL "$p" >&2 || { echo "ОШИБКА: $p"; return 1; }
		done
		for p in apk/luci*; do
			[ -f "$p" ] || continue
			echo "  - $(basename "$p")"; $INSTALL "$p" >&2
		done
	else
		for p in zapret_*.ipk; do
			[ -f "$p" ] || continue
			echo "  - $(basename "$p")"; $INSTALL "$p" >&2 || { echo "ОШИБКА: $p"; return 1; }
		done
		for p in luci-app-zapret_*.ipk; do
			[ -f "$p" ] || continue
			echo "  - $(basename "$p")"; $INSTALL "$p" >&2
		done
	fi

	_nochange_restore zapret
	echo "==> Добавляем домены в исключения"
	_nochange_fetch /opt/zapret/ipset/zapret-hosts-user-exclude.txt "$EXCLUDE_URL" || echo "!! Список исключений не скачался — оставлен прежний"

	do_add_fake_flow

	echo "==> Включаем автозапуск и custom.d-скрипты"
	/etc/init.d/zapret enable >/dev/null 2>&1
	sed -i "/DISABLE_CUSTOM/s/'1'/'0'/" "$CONF" 2>/dev/null

	cd /; rm -rf "$tmp"
	echo "==> Готово, Zapret установлен ($ver)"
}

do_install_zapret() {
	local rc
	_nochange_save zapret /opt/zapret/ipset "$CONF"
	_do_install_zapret_core; rc=$?
	_nochange_restore zapret
	_zs2_sync
	_ft_zapret_sync
	return $rc
}

do_install_zapret2() {
	local rc
	_nochange_save zapret2 /opt/zapret2/ipset /etc/config/zapret2
	_do_install_zapret2_core; rc=$?
	_nochange_restore zapret2
	_ft_zapret_sync
	return $rc
}

do_install_zapret_full() {
	do_install_zapret || return 1
	[ -f /etc/init.d/zapret ] || return 1

	if _nochange_strategy; then echo "==> Стратегия помечена #nochange — оставляем её как есть"
	else
		_zc_lift
		echo "==> Применяем базовую стратегию v7"
		strategy_set_v v7 >/dev/null
	fi

	if ! _nochange_strategy; then
		echo "==> Настраиваем игровую стратегию Gv1"
		game_set 1 >/dev/null
	fi
	_zc_drop

	echo "==> Готово, Zapret установлен и настроен"
}

do_remove_zapret() {
	local rc=0
	echo "==> Останавливаем Zapret"
	_zm_svc_off zapret
	for p in $(pgrep -f "/opt/zapre[t]/" 2>/dev/null); do kill -9 "$p" 2>/dev/null; done
	nft delete table inet zapret >/dev/null 2>&1
	echo "   ✓ Процессы nfqws остановлены, правила файрвола сняты"
	echo "==> Удаляем пакеты Zapret"
	_zm_pkg_wipe luci-i18n-zapret-ru luci-app-zapret zapret || rc=1
	echo "==> Удаляем файлы, стратегии и списки"
	_zm_wipe /opt/zapret "$CONF" "$CONF-opkg" "$CONF.apk-new" /etc/init.d/zapret /etc/rc.d/*[0-9]zapret /etc/firewall.zapret /etc/hotplug.d/*/*zapret \
		/tmp/zapret /tmp/zapret.* "$YV_OFF_FLAG" "$DV_OFF_FLAG" "$JOBS_DIR/flowseal_strategies.txt" "$JOBS_DIR/youtube_strategies.txt" "$ZO_RKN_FLAG" "$ZO_USER_FLAG" "$ZO_IPID_FLAG" "$ZO_DOH_FLAG" "$ZP_OWN" "$ZP_MANUAL" &&
		echo "   ✓ Файлы удалены, остатков нет" || rc=1
	crontab -l 2>/dev/null | awk '{ l = tolower($0) } l ~ /zapret/ && l !~ /zapret-manager|zapret2/ { next } { print }' | crontab - 2>/dev/null
	sed -i "\\|$ZA_TAG|d; \\|$ZX_AUTO_TAG=|d" "$CRON_FILE" 2>/dev/null
	_ft_zapret_gone
	echo "   ✓ Задания Zapret убраны из расписания"
	_zm_rm_listed zapret || rc=1
	/etc/init.d/firewall reload >/dev/null 2>&1
	_zm_rm_done "$rc" "Zapret"
}
zapret_action() {
	local action="$1"
	case "$action" in
		install)
			if [ ! -f /etc/init.d/zapret ] && [ -f /etc/init.d/zapret2 ] && [ ! -f "$EXPERT_MODE_FILE" ]; then
				echo '{"error":"Стоит Zapret2 — он несовместим с Zapret. Чтобы поставить Zapret, удалите Zapret2."}'; return 1
			fi
			job_start install_zapret do_install_zapret_full ;;
		update)         job_start install_zapret do_install_zapret ;;
		remove)         job_start remove_zapret  do_remove_zapret ;;
		start)          /etc/init.d/zapret start >/dev/null 2>&1; zapret_restart; status ;;
		restart)
			[ -x /etc/init.d/zapret ] || { echo '{"error":"Zapret не установлен"}'; return 1; }
			zapret_restart
			for p in 1 2 3 4 5; do pgrep -f "/opt/zapre[t]/" >/dev/null 2>&1 && break; sleep 1; done
			status ;;
		stop)
			/etc/init.d/zapret stop >/dev/null 2>&1
			for p in $(pgrep -f "/opt/zapre[t]/" 2>/dev/null); do kill -9 "$p" 2>/dev/null; done
			status ;;
		*) echo '{"error":"неизвестное действие"}' ;;
	esac
}

_z2_arch() { awk -F\' '/DISTRIB_ARCH/ {print $2}' /etc/openwrt_release 2>/dev/null; }
_do_install_zapret2_core() {
	local arch
	arch="$(_z2_arch)"
	if [ "$arch" != "aarch64_cortex-a53" ]; then
		echo "ОШИБКА: Zapret2 поддерживает только архитектуру aarch64_cortex-a53 (у вас: $arch)"
		return 1
	fi
	if [ -f /etc/init.d/zapret ] && [ ! -f "$EXPERT_MODE_FILE" ]; then
		echo "ОШИБКА: установлен основной Zapret, он несовместим с Zapret2 — сначала удалите Zapret"
		return 1
	fi
	_ensure_deps

	local base_url raz
	if [ "$PKG" = "apk" ]; then
		base_url="https://packages.routerich.ru/25.12/mediatek/filogic/routerich/"; raz="apk"
	else
		base_url="https://packages.routerich.ru/24.10/mediatek/filogic/routerich/"; raz="ipk"
	fi

	local tmp="$JOBS_DIR/install_z2_tmp"; rm -rf "$tmp"; mkdir -p "$tmp"; cd "$tmp" || return 1

	echo "==> Ищем актуальный пакет Zapret2 в $base_url"
	ZM_FETCH_ANY=1
	_zm_fetch "$base_url" index.html 15 || { ZM_FETCH_ANY=""; echo "ОШИБКА: не удалось получить список пакетов — $ZM_FETCH_ERR"; return 1; }
	ZM_FETCH_ANY=""

	local main_file luci_file
	if [ "$PKG" = "apk" ]; then
		main_file=$(grep -oE 'zapret2-[0-9][^"]*\.apk' index.html | head -n1)
		luci_file=$(grep -oE 'luci-app-zapret2-[0-9][^"]*\.apk' index.html | head -n1)
	else
		main_file=$(grep -oE 'zapret2_[0-9][^"]*_aarch64_cortex-a53\.ipk' index.html | head -n1)
		luci_file=$(grep -oE 'luci-app-zapret2_[0-9][^"]*_all\.ipk' index.html | head -n1)
	fi
	[ -z "$main_file" ] && { echo "ОШИБКА: пакет zapret2 не найден в репозитории"; return 1; }

	echo "==> Скачиваем $main_file"
	_zm_get "${base_url}${main_file}" "$main_file" "" 60 || { echo "ОШИБКА скачивания $main_file"; return 1; }
	if [ -n "$luci_file" ]; then
		echo "==> Скачиваем $luci_file"
		_zm_get "${base_url}${luci_file}" "$luci_file" "" 60
	fi

	echo "==> Обновляем список пакетов"
	$UPDATE

	echo "==> Устанавливаем"
	$INSTALL ./*."$raz" || { echo "ОШИБКА установки"; return 1; }
	_nochange_restore zapret2

	echo "==> Добавляем домены в исключения"
	mkdir -p /opt/zapret2/ipset
	_nochange_fetch /opt/zapret2/ipset/zapret_hosts_user_exclude.txt "$EXCLUDE_URL"

	echo "==> Настраиваем стратегии"
	mkdir -p /opt/zapret2/init.d/openwrt/custom.d
	_nochange_fetch /opt/zapret2/init.d/openwrt/custom.d/50-discord_media.sh \
		"${GH_RAW}/StressOzz/Zapret-Manager/refs/heads/main/files/Zapret2/50-discord_media.sh" \
		|| echo "!! Не удалось загрузить 50-discord_media.sh"
	if _nochange_in /etc/config/zapret2; then echo "   · Стратегия Zapret2 помечена #nochange — оставляем как есть"
	else
		_nochange_fetch /etc/config/zapret2 "${GH_RAW}/StressOzz/Zapret-Manager/refs/heads/main/files/Zapret2/zapret2" || echo "!! Не удалось загрузить zapret2"
	fi
	_nochange_fetch /opt/zapret2/ipset/zapret_hosts_discord.txt "${GH_RAW}/StressOzz/Zapret-Manager/refs/heads/main/files/Zapret2/zapret_hosts_discord.txt" \
		|| echo "!! Не удалось загрузить zapret_hosts_discord.txt"

	echo "==> Запускаем Zapret2"
	/etc/init.d/zapret2 enable >/dev/null 2>&1
	/etc/init.d/zapret2 restart >/dev/null 2>&1

	cd /; rm -rf "$tmp"
	echo "==> Готово, Zapret2 установлен"
}

do_remove_zapret2() {
	local rc=0
	echo "==> Останавливаем Zapret2"
	_zm_svc_off zapret2
	for p in $(pgrep -f "/opt/zapret[2]/" 2>/dev/null); do kill -9 "$p" 2>/dev/null; done
	nft delete table inet zapret2 >/dev/null 2>&1
	echo "   ✓ Процессы остановлены, правила файрвола сняты"
	echo "==> Удаляем пакеты Zapret2"
	_zm_pkg_wipe luci-i18n-zapret2-ru luci-app-zapret2 zapret2 || rc=1
	echo "==> Удаляем файлы и настройки"
	_zm_wipe /etc/config/zapret2 /etc/config/zapret2-opkg /etc/config/zapret2.apk-new /opt/zapret2 /etc/init.d/zapret2 /etc/rc.d/*zapret2 /etc/hotplug.d/*/*zapret2 /tmp/zapret2* &&
		echo "   ✓ Файлы удалены, остатков нет" || rc=1
	_zm_cron_drop 'zapret2' 'Zapret2'
	_zm_rm_listed zapret2 || rc=1
	/etc/init.d/firewall reload >/dev/null 2>&1
	_ft_zapret_gone
	_zm_rm_done "$rc" "Zapret2"
}
zapret2_action() {
	local action="$1"
	case "$action" in
		install|update)
			if [ ! -f /etc/init.d/zapret2 ] && [ -f /etc/init.d/zapret ] && [ ! -f "$EXPERT_MODE_FILE" ]; then
				echo '{"error":"Стоит Zapret — он несовместим с Zapret2. Чтобы поставить Zapret2, удалите Zapret."}'; return 1
			fi
			if [ "$action" = install ] && [ "$(_z2_arch)" != "aarch64_cortex-a53" ]; then
				printf '{"error":"%s"}\n' "$(esc "Zapret2 работает только на роутерах с архитектурой aarch64_cortex-a53, у этого роутера — $(_z2_arch)")"; return 1
			fi
			job_start install_zapret2 do_install_zapret2 ;;
		remove)         job_start remove_zapret2  do_remove_zapret2 ;;
		start)          /etc/init.d/zapret2 start >/dev/null 2>&1; status ;;
		stop)           /etc/init.d/zapret2 stop >/dev/null 2>&1; status ;;
		restart)
			[ -x /etc/init.d/zapret2 ] || { echo '{"error":"Zapret2 не установлен"}'; return 1; }
			/etc/init.d/zapret2 restart >/dev/null 2>&1
			for p in 1 2 3 4 5; do /etc/init.d/zapret2 status >/dev/null 2>&1 && break; sleep 1; done
			status ;;
		*) echo '{"error":"неизвестное действие"}' ;;
	esac
}

