_hosts_block_status() {
	local block="$1" content
	content="$(_hosts_block "$block")" || return 1
	[ -f "$HOSTS_FILE" ] || { echo false; return; }
	printf '%s\n' "$content" | awk -v hf="$HOSTS_FILE" 'function n(s) { gsub(/\r/, "", s); gsub(/[ \t]+/, " ", s); sub(/^ /, "", s); sub(/ $/, "", s); return s }
		BEGIN { while ((getline l < hf) > 0) have[n(l)] = 1; close(hf) }
		{ k = n($0); if (k == "" || (k in seen)) next; seen[k] = 1; total++; if (k in have) found++ }
		END { print (total > 0 && found == total) ? "true" : "false" }'
}
_hosts_drop_lines() {
	local tmp="$HOSTS_FILE.zmtmp" list="$HOSTS_FILE.zmdrop"
	cat > "$list"
	awk -v list="$list" 'function n(s) { gsub(/\r/, "", s); gsub(/[ \t]+/, " ", s); sub(/^ /, "", s); sub(/ $/, "", s); return s }
		BEGIN { while ((getline l < list) > 0) { k = n(l); if (k != "") drop[k] = 1 } close(list) }
		!(n($0) in drop)' "$HOSTS_FILE" > "$tmp" && cat "$tmp" > "$HOSTS_FILE"
	rm -f "$tmp" "$list"
}
_hosts_append() {
	[ -s "$HOSTS_FILE" ] && [ -n "$(tail -c 1 "$HOSTS_FILE" 2>/dev/null)" ] && echo >> "$HOSTS_FILE"
	echo "$1" >> "$HOSTS_FILE"
}

_hosts_add_lines() {
	local list="$HOSTS_FILE.zmadd" add="$HOSTS_FILE.zmnew"
	cat > "$list"
	[ -f "$HOSTS_FILE" ] || : > "$HOSTS_FILE"
	awk -v hf="$HOSTS_FILE" 'function n(s) { gsub(/\r/, "", s); gsub(/[ \t]+/, " ", s); sub(/^ /, "", s); sub(/ $/, "", s); return s }
		BEGIN { while ((getline l < hf) > 0) have[n(l)] = 1; close(hf) }
		{ k = n($0); if (k == "" || (k in have)) next; have[k] = 1; print }' "$list" > "$add"
	if [ -s "$add" ]; then
		[ -s "$HOSTS_FILE" ] && [ -n "$(tail -c 1 "$HOSTS_FILE" 2>/dev/null)" ] && echo >> "$HOSTS_FILE"
		cat "$add" >> "$HOSTS_FILE"
	fi
	rm -f "$list" "$add"
}

_hosts_has_line() {
	awk -v want="$1" 'function n(s) { gsub(/\r/, "", s); gsub(/[ \t]+/, " ", s); sub(/^ /, "", s); sub(/ $/, "", s); return s }
		BEGIN { want = n(want) } n($0) == want { f = 1; exit } END { exit !f }' "$HOSTS_FILE" 2>/dev/null
}

HOSTS_BLOCKS="nalog ntc instagram librusec ai_openai ai_claude ai_gemini ai_aistudio ai_grok ai_copilot ai_deepl ai_elevenlabs ai_windsurf ai_trae ai_manus ai_notion twitch telegram spotify spotifyext rutor rutracker scell roblox githubraw github tapeop finland"
hosts_status() {
	local blocks="$HOSTS_BLOCKS" b
	local geohide=""
	if grep -q '^### dns.malw.link: hosts file' "$HOSTS_FILE" 2>/dev/null; then geohide="malw"
	elif grep -q '^### geohide.ru: hosts file' "$HOSTS_FILE" 2>/dev/null; then
		if grep -q '^# Регион серверов: US$' "$HOSTS_FILE" 2>/dev/null; then geohide="us"
		elif grep -q '^# Регион серверов: EU$' "$HOSTS_FILE" 2>/dev/null; then geohide="eu"
		elif grep -q '^# Регион серверов: RU$' "$HOSTS_FILE" 2>/dev/null; then geohide="ru"
		else geohide="unknown"; fi
	fi
	printf '{"geohide":"%s","items":[' "$(esc "$geohide")"
	for b in $blocks; do echo "@@ZMB $b"; _hosts_block "$b"; done | awk -v hf="$HOSTS_FILE" 'function n(s) { gsub(/\r/, "", s); gsub(/[ \t]+/, " ", s); sub(/^ /, "", s); sub(/ $/, "", s); return s }
		function flush() { if (id == "") return; printf "%s{\"id\":\"%s\",\"enabled\":%s}", (cnt++ ? "," : ""), id, (total > 0 && found == total) ? "true" : "false" }
		BEGIN { while ((getline l < hf) > 0) have[n(l)] = 1; close(hf) }
		/^@@ZMB / { flush(); id = substr($0, 7); total = 0; found = 0; split("", seen); next }
		{ k = n($0); if (k == "" || (k in seen)) next; seen[k] = 1; total++; if (k in have) found++ }
		END { flush() }'
	printf '],"extra":%s}\n' "$(_hosts_extra)"
}

hosts_toggle() {
	local block="$1" content line enabled
	content="$(_hosts_block "$block")" || { echo '{"error":"неизвестный блок"}'; return 1; }
	enabled="$(_hosts_block_status "$block")"
	if [ "$enabled" = "true" ]; then
		printf '%s\n' "$content" | _hosts_drop_lines
	else
		printf '%s\n' "$content" | _hosts_add_lines
	fi
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	printf '{"ok":true,"block":"%s","enabled":%s}\n' "$(esc "$block")" "$([ "$enabled" = "true" ] && echo false || echo true)"
}

hosts_replace_geohide() {
	local region="$1" url tmp
	case "$region" in
		eu) url="${GH_RAW}/Internet-Helper/GeoHideDNS/refs/heads/main/hosts/eu/hosts" ;;
		us) url="${GH_RAW}/Internet-Helper/GeoHideDNS/refs/heads/main/hosts/us/hosts" ;;
		malw) url="${GH_RAW}/ImMALWARE/dns.malw.link/refs/heads/master/hosts" ;;
		*) echo '{"error":"неизвестный регион"}'; return 1 ;;
	esac
	tmp="$JOBS_DIR/geohide_hosts.tmp"
	_zm_fetch "$url" "$tmp" 60
	if [ ! -s "$tmp" ]; then
		rm -f "$tmp"
		printf '{"error":"%s"}\n' "$([ "$region" = malw ] && echo "не удалось скачать hosts dns.malw.link" || echo "не удалось скачать GeoHide hosts")"
		return 1
	fi
	if [ "$(grep -cE '^[[:space:]]*[0-9a-fA-F.:]+[[:space:]]+[A-Za-z0-9]' "$tmp")" -lt 20 ]; then
		rm -f "$tmp"
		echo '{"error":"скачался не файл hosts — попробуйте ещё раз позже"}'
		return 1
	fi
	if ! mv "$tmp" "$HOSTS_FILE" 2>/dev/null; then
		rm -f "$tmp"
		echo '{"error":"не удалось записать /etc/hosts — проверьте свободное место на роутере"}'
		return 1
	fi
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	printf '{"ok":true,"region":"%s"}\n' "$region"
}

hosts_reset() {
	printf '%s\n' "127.0.0.1	localhost" "" "::1	localhost ip6-localhost ip6-loopback" "ff02::1 ip6-allnodes" "ff02::2 ip6-allrouters" > "$HOSTS_FILE"
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	printf '{"ok":true}\n'
}

HOSTS_EDIT_MAX=262144

hosts_file_get() {
	local sz n
	[ -f "$HOSTS_FILE" ] || { echo '{"error":"файл hosts не найден"}'; return 1; }
	sz="$(wc -c < "$HOSTS_FILE" | tr -d ' ')"
	if [ "${sz:-0}" -gt "$HOSTS_EDIT_MAX" ]; then
		n="$(wc -l < "$HOSTS_FILE" | tr -d ' ')"
		printf '{"too_big":true,"size":%s,"lines":%s}\n' "$sz" "${n:-0}"
		return 0
	fi
	printf '{"content":"%s"}\n' "$(esc_ml "$(cat "$HOSTS_FILE")")"
}

hosts_file_set() {
	local content="$1"
	[ -n "$content" ] || { echo '{"error":"пустой файл — сохранение отменено"}'; return 1; }
	[ "$(printf '%s' "$content" | wc -c)" -gt "$HOSTS_EDIT_MAX" ] && { echo '{"error":"файл слишком большой для редактора"}'; return 1; }
	cp "$HOSTS_FILE" "$HOSTS_FILE.zm-bak" 2>/dev/null
	printf '%s' "$content" > "$HOSTS_FILE"
	[ -n "$(tail -c 1 "$HOSTS_FILE" 2>/dev/null)" ] && echo >> "$HOSTS_FILE"
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	printf '{"ok":true}\n'
}

ZM_UP_FILE="$JOBS_DIR/upload.part"
ZM_UP_MAX=4194304
upload_part() {
	local part="$1" sz
	mkdir -p "$JOBS_DIR"
	case "$part" in
		first) : > "$ZM_UP_FILE" ;;
		next) [ -f "$ZM_UP_FILE" ] || { echo '{"error":"загрузка прервалась — сохраните ещё раз"}'; return 1; } ;;
		*) echo '{"error":"неверная часть файла"}'; return 1 ;;
	esac
	printf '%s' "$2" >> "$ZM_UP_FILE"
	sz="$(wc -c < "$ZM_UP_FILE" | tr -d ' ')"
	[ "${sz:-0}" -gt "$ZM_UP_MAX" ] && { rm -f "$ZM_UP_FILE"; echo '{"error":"текст слишком большой"}'; return 1; }
	printf '{"ok":true,"size":%s}\n' "${sz:-0}"
}

_ports_get() { sed -n "s/^[[:space:]]*option $1 '\([^']*\)'.*/\1/p" "$CONF" | head -n1; }
_ports_put() { sed -i "s|^\([[:space:]]*option $1 '\)[^']*'|\1$2'|" "$CONF"; }
_remove_ports_if_present() {
	local option="$1" ports="$2" cur out="" p
	grep -q "^[[:space:]]*option $option '" "$CONF" || return 0
	cur="$(_ports_get "$option")"
	for p in $(echo "$cur" | tr ',' ' '); do
		case ",$ports," in *",$p,"*) continue ;; esac
		out="$out${out:+,}$p"
	done
	[ "$out" = "$cur" ] || _ports_put "$option" "$out"
}

_add_ports_if_missing() {
	local option="$1" ports="$2" cur p
	grep -q "^[[:space:]]*option $option '" "$CONF" || return 0
	cur="$(_ports_get "$option")"
	for p in $(echo "$ports" | tr ',' ' '); do
		case ",$cur," in *",$p,"*) ;; *) cur="$cur${cur:+,}$p" ;; esac
	done
	_ports_put "$option" "$cur"
}

ZP_OWN="$ZM_STATE_DIR/zapret.ports.own"
ZP_MANUAL="$ZM_STATE_DIR/zapret.ports.manual"
ZP_DEF_TCP="80,443"
ZP_DEF_UDP="443"
ZP_MAX=300
ZP_AWK='
function zp_parse(s, lo, hi,   n, m, i, j, k, t, ab, a, b, x, y) {
	n = 0; m = split(s, t, ",")
	for (i = 1; i <= m; i++) {
		k = t[i]; gsub(/[ \t\r\n]/, "", k)
		if (k ~ /^[0-9]+$/) { a = k + 0; b = a }
		else if (k ~ /^[0-9]+-[0-9]+$/) { split(k, ab, "-"); a = ab[1] + 0; b = ab[2] + 0 }
		else continue
		if (a < 1 || b > 65535 || a > b) continue
		n++; lo[n] = a; hi[n] = b
	}
	for (i = 2; i <= n; i++) {
		x = lo[i]; y = hi[i]; j = i - 1
		while (j >= 1 && lo[j] > x) { lo[j + 1] = lo[j]; hi[j + 1] = hi[j]; j-- }
		lo[j + 1] = x; hi[j + 1] = y
	}
	if (n == 0) return 0
	j = 1
	for (i = 2; i <= n; i++) {
		if (lo[i] <= hi[j] + 1) { if (hi[i] > hi[j]) hi[j] = hi[i] }
		else { j++; lo[j] = lo[i]; hi[j] = hi[i] }
	}
	return j
}
function zp_str(lo, hi, n,   i, o) {
	o = ""
	for (i = 1; i <= n; i++) o = o (o == "" ? "" : ",") (lo[i] == hi[i] ? lo[i] : lo[i] "-" hi[i])
	return o
}
function zp_norm(s,   lo, hi, n) { n = zp_parse(s, lo, hi); return zp_str(lo, hi, n) }
function zp_diff(a, b,   al, ah, an, bl, bh, bn, ol, oh, on, i, j, c) {
	an = zp_parse(a, al, ah); bn = zp_parse(b, bl, bh); on = 0
	for (i = 1; i <= an; i++) {
		c = al[i]
		for (j = 1; j <= bn && c <= ah[i]; j++) {
			if (bh[j] < c) continue
			if (bl[j] > ah[i]) break
			if (bl[j] > c) { on++; ol[on] = c; oh[on] = bl[j] - 1 }
			c = bh[j] + 1
		}
		if (c <= ah[i]) { on++; ol[on] = c; oh[on] = ah[i] }
	}
	return zp_str(ol, oh, on)
}
'
_zp_calc() {
	awk -v op="$1" -v a="$2" -v b="$3" "$ZP_AWK"'
		BEGIN { if (op == "norm") print zp_norm(a); else if (op == "diff") print zp_diff(a, b); else print zp_norm(a "," b) }' < /dev/null
}
_zp_clean() {
	printf '%s' "$1" | awk -v max="$ZP_MAX" '
		{ s = s " " $0 }
		END {
			gsub(/[ \t\r\n;]+/, ",", s); n = split(s, t, ","); o = ""; c = 0
			for (i = 1; i <= n; i++) {
				k = t[i]
				if (k == "") continue
				if (k ~ /^[0-9]+$/) { a = k + 0; b = a }
				else if (k ~ /^[0-9]+-[0-9]+$/) { split(k, ab, "-"); a = ab[1] + 0; b = ab[2] + 0 }
				else { print "ERR\t«" k "» — это не порт: нужно число или диапазон через дефис, например 443 или 50000-50100"; exit }
				if (a < 1 || a > 65535 || b < 1 || b > 65535) { print "ERR\t«" k "» — порт должен быть от 1 до 65535"; exit }
				if (a > b) { print "ERR\t«" k "» — в диапазоне первое число должно быть меньше второго"; exit }
				k = (a == b) ? a : a "-" b
				if (k in seen) continue
				seen[k] = 1
				if (++c > max) { print "ERR\tслишком много портов — не больше " max " записей"; exit }
				o = o (o == "" ? "" : ",") k
			}
			print "OK\t" o
		}'
}
_zp_scan() {
	{
		sed -n "/^[[:space:]]*option NFQWS_OPT '[[:space:]]*\$/,/^[[:space:]]*'[[:space:]]*\$/p" "$CONF" 2>/dev/null
		[ -s "$ZC_FILE" ] && { echo "--new"; cat "$ZC_FILE"; }
		_zs2_on && [ -n "$(_zs2_ips)" ] && { echo "--new"; _zs2_opt; }
	} | awk '
		function fl() { if (des && !ht && !hu) { wt = 1; wu = 1 } des = 0; ht = 0; hu = 0 }
		function addp(p, v,   n, i, t) {
			if (v == "" || v ~ /[~*]/) { if (p == "t") wt = 1; else wu = 1; return }
			n = split(v, t, ",")
			for (i = 1; i <= n; i++) {
				if (t[i] == "") continue
				if (p == "t") { if (!(t[i] in st)) { st[t[i]] = 1; ts = ts (ts == "" ? "" : ",") t[i] } }
				else if (!(t[i] in su)) { su[t[i]] = 1; us = us (us == "" ? "" : ",") t[i] }
			}
		}
		{
			l = $0; sub(/^[ \t]+/, "", l); sub(/[ \t\r]+$/, "", l)
			if (l ~ /^option[ \t]+NFQWS_OPT/) { ok = 1; next }
			if (l == "\047" || l == "" || l ~ /^#/) next
			sub(/\047$/, "", l)
			n = split(l, w, /[ \t]+/)
			for (i = 1; i <= n; i++) {
				x = w[i]
				if (pend != "") { addp(pend, x); pend = ""; continue }
				if (x == "--new") fl()
				else if (x ~ /^--filter-tcp=/) { ht = 1; addp("t", substr(x, 14)) }
				else if (x == "--filter-tcp") { ht = 1; pend = "t" }
				else if (x ~ /^--filter-udp=/) { hu = 1; addp("u", substr(x, 14)) }
				else if (x == "--filter-udp") { hu = 1; pend = "u" }
				else if (x ~ /^--dpi-desync/) des = 1
			}
		}
		END { fl(); print ok + 0; print ts; print us; print wt + 0; print wu + 0 }'
}
_zp_load() {
	local r
	r="$(_zp_scan; echo .)"
	ZP_OK="$(printf '%s' "$r" | sed -n 1p)"
	ZP_ST="$(printf '%s' "$r" | sed -n 2p)"
	ZP_SU="$(printf '%s' "$r" | sed -n 3p)"
	ZP_WT="$(printf '%s' "$r" | sed -n 4p)"
	ZP_WU="$(printf '%s' "$r" | sed -n 5p)"
	ZP_CT="$(_ports_get NFQWS_PORTS_TCP)"
	ZP_CU="$(_ports_get NFQWS_PORTS_UDP)"
	[ "$ZP_OK" = 1 ]
}
_zp_own_load() {
	if [ -f "$ZP_OWN" ] && [ ! -f "$ZP_MANUAL" ]; then
		ZP_OT="$(sed -n 's/^tcp=//p' "$ZP_OWN" | head -n1)"
		ZP_OU="$(sed -n 's/^udp=//p' "$ZP_OWN" | head -n1)"
	else
		ZP_OT="$(_zp_calc diff "$ZP_CT" "$ZP_ST")"
		ZP_OU="$(_zp_calc diff "$ZP_CU" "$ZP_SU")"
	fi
}
_zp_own_put() {
	mkdir -p "$ZM_STATE_DIR" || return 1
	printf 'tcp=%s\nudp=%s\n' "$(_zp_calc norm "$1")" "$(_zp_calc norm "$2")" > "$ZP_OWN.t" && mv -f "$ZP_OWN.t" "$ZP_OWN"
}
_zp_put() {
	if grep -q "^[[:space:]]*option $1 '" "$CONF"; then
		_ports_put "$1" "$2"
	else
		awk -v l="	option $1 '$2'" '!d && /^[ \t]*option NFQWS_OPT \047/ { print l; d = 1 } { print }' "$CONF" > "$CONF.zp" && [ -s "$CONF.zp" ] && cat "$CONF.zp" > "$CONF"
		rm -f "$CONF.zp"
	fi
}
_zp_sync() {
	local t u
	ZP_CHANGED=""
	[ -f "$CONF" ] || return 0
	[ -f "$ZP_MANUAL" ] && return 0
	[ -s "$TEST_BACKUP" ] && return 0
	_zp_load || return 0
	if [ ! -f "$ZP_OWN" ]; then
		_zp_own_load
		_zp_own_put "$ZP_OT" "$ZP_OU" || return 0
	fi
	_zp_own_load
	if [ "$ZP_WT" = 0 ]; then
		t="$(_zp_calc union "$ZP_ST" "$ZP_OT")"
		[ -n "$t" ] && [ "$t" != "$(_zp_calc norm "$ZP_CT")" ] && { _zp_put NFQWS_PORTS_TCP "$t"; ZP_CHANGED=1; }
	fi
	if [ "$ZP_WU" = 0 ]; then
		u="$(_zp_calc union "$ZP_SU" "$ZP_OU")"
		[ -n "$u" ] && [ "$u" != "$(_zp_calc norm "$ZP_CU")" ] && { _zp_put NFQWS_PORTS_UDP "$u"; ZP_CHANGED=1; }
	fi
	[ -n "$ZP_CHANGED" ] && logger -t zapret-manager "Zapret: порты сверены со стратегией — TCP ${t:-$ZP_CT}, UDP ${u:-$ZP_CU}"
	return 0
}
_zp_bool() { if [ "$1" = 1 ]; then printf true; else printf false; fi; }
_zp_json() {
	local sync=true ok=false tt="" tu="" nt nu pend=false nc=false testing=false
	[ -f "$ZP_MANUAL" ] && sync=false
	_zp_load && ok=true
	_zp_own_load
	if [ "$ok" = true ]; then
		nt="$(_zp_calc norm "$ZP_CT")"; nu="$(_zp_calc norm "$ZP_CU")"
		[ "$ZP_WT" = 0 ] && tt="$(_zp_calc union "$ZP_ST" "$ZP_OT")"
		[ "$ZP_WU" = 0 ] && tu="$(_zp_calc union "$ZP_SU" "$ZP_OU")"
		[ -n "$tt" ] || tt="$nt"
		[ -n "$tu" ] || tu="$nu"
		[ "$sync" = true ] && { [ "$tt" != "$nt" ] || [ "$tu" != "$nu" ]; } && pend=true
	fi
	_nochange_strategy && nc=true
	[ -s "$TEST_BACKUP" ] && testing=true
	printf '"sync":%s,"opt":%s,"tcp":"%s","udp":"%s","s_tcp":"%s","s_udp":"%s","own_tcp":"%s","own_udp":"%s",' \
		"$sync" "$ok" "$(esc "$ZP_CT")" "$(esc "$ZP_CU")" "$(esc "$ZP_ST")" "$(esc "$ZP_SU")" "$(esc "$(_zp_calc norm "$ZP_OT")")" "$(esc "$(_zp_calc norm "$ZP_OU")")"
	printf '"miss_tcp":"%s","miss_udp":"%s","extra_tcp":"%s","extra_udp":"%s",' \
		"$([ "$ZP_WT" = 1 ] || _zp_calc diff "$ZP_ST" "$ZP_CT")" "$([ "$ZP_WU" = 1 ] || _zp_calc diff "$ZP_SU" "$ZP_CU")" \
		"$([ "$ZP_WT" = 1 ] || _zp_calc diff "$ZP_CT" "$ZP_ST")" "$([ "$ZP_WU" = 1 ] || _zp_calc diff "$ZP_CU" "$ZP_SU")"
	printf '"t_tcp":"%s","t_udp":"%s","wild_tcp":%s,"wild_udp":%s,"pending":%s,"nochange":%s,"testing":%s,"def_tcp":"%s","def_udp":"%s"' \
		"$(esc "$tt")" "$(esc "$tu")" "$(_zp_bool "$ZP_WT")" "$(_zp_bool "$ZP_WU")" "$pend" "$nc" "$testing" "$ZP_DEF_TCP" "$ZP_DEF_UDP"
}
zapret_ports_get() {
	[ -f /etc/init.d/zapret ] && [ -f "$CONF" ] || { echo '{"installed":false}'; return 0; }
	printf '{"installed":true,'; _zp_json; printf '}\n'
}
_zp_up() { pgrep -f "/opt/zapre[t]/" >/dev/null 2>&1; }
zapret_ports_set() {
	local mode="$1" tcp udp r bak was="" ch="" i
	[ -x /etc/init.d/zapret ] || { echo '{"error":"Zapret не установлен"}'; return 1; }
	[ -f "$CONF" ] || { echo '{"error":"конфигурация Zapret не найдена"}'; return 1; }
	case "$mode" in sync|manual) ;; *) echo '{"error":"неизвестный режим"}'; return 1 ;; esac
	[ -s "$TEST_BACKUP" ] && { echo '{"error":"идёт тест стратегий — порты можно поменять, когда он закончится"}'; return 1; }
	r="$(_zp_clean "$2")"
	case "$r" in ERR*) printf '{"error":"TCP: %s"}\n' "$(esc "${r#ERR	}")"; return 1 ;; esac
	tcp="${r#OK	}"
	r="$(_zp_clean "$3")"
	case "$r" in ERR*) printf '{"error":"UDP: %s"}\n' "$(esc "${r#ERR	}")"; return 1 ;; esac
	udp="${r#OK	}"
	_zp_load || { echo '{"error":"в конфигурации не найден блок NFQWS_OPT"}'; return 1; }
	mkdir -p "$ZM_STATE_DIR"
	bak="$ZM_STATE_DIR/zapret.ports.bak"
	cp -f "$CONF" "$bak" || { echo '{"error":"не удалось сохранить копию конфигурации"}'; return 1; }
	[ -f "$ZP_OWN" ] && cp -f "$ZP_OWN" "$bak.own"
	[ -f "$ZP_MANUAL" ] && : > "$bak.man"
	if [ "$mode" = sync ]; then
		_zp_own_put "$tcp" "$udp" || { rm -f "$bak" "$bak.own" "$bak.man"; echo '{"error":"не удалось записать настройки"}'; return 1; }
		rm -f "$ZP_MANUAL"
		_zp_sync
		ch="$ZP_CHANGED"
	else
		[ -n "$tcp$udp" ] || { rm -f "$bak" "$bak.own" "$bak.man"; echo '{"error":"укажите хотя бы один порт TCP или UDP"}'; return 1; }
		: > "$ZP_MANUAL"
		[ "$tcp" = "$ZP_CT" ] || { _zp_put NFQWS_PORTS_TCP "$tcp"; [ "$(_zp_calc norm "$tcp")" = "$(_zp_calc norm "$ZP_CT")" ] || ch=1; }
		[ "$udp" = "$ZP_CU" ] || { _zp_put NFQWS_PORTS_UDP "$udp"; [ "$(_zp_calc norm "$udp")" = "$(_zp_calc norm "$ZP_CU")" ] || ch=1; }
	fi
	if [ -n "$ch" ]; then
		_zp_up && was=1
		zapret_restart
		if [ -n "$was" ]; then
			i=0
			while ! _zp_up && [ "$i" -lt 4 ]; do sleep 1; i=$((i + 1)); done
			if ! _zp_up; then
				cat "$bak" > "$CONF"
				if [ -f "$bak.own" ]; then mv -f "$bak.own" "$ZP_OWN"; else rm -f "$ZP_OWN"; fi
				if [ -f "$bak.man" ]; then : > "$ZP_MANUAL"; else rm -f "$ZP_MANUAL"; fi
				rm -f "$bak" "$bak.own" "$bak.man"
				zapret_restart
				echo '{"error":"Zapret не запустился с этими портами — прежние порты возвращены"}'
				return 1
			fi
		fi
	fi
	rm -f "$bak" "$bak.own" "$bak.man"
	printf '{"ok":true,"installed":true,"changed":%s,' "$([ -n "$ch" ] && echo true || echo false)"; _zp_json; printf '}\n'
}
zapret_ports_migrate() {
	local had=false ch=false ot ou
	[ -f /etc/init.d/zapret ] && [ -f "$CONF" ] || { echo '{"changed":false}'; return 0; }
	[ -f "$ZP_MANUAL" ] && { echo '{"changed":false}'; return 0; }
	[ -s "$TEST_BACKUP" ] && { echo '{"changed":false}'; return 0; }
	_zp_load || { echo '{"changed":false}'; return 0; }
	ot="$ZP_CT"; ou="$ZP_CU"
	[ -f "$ZP_OWN" ] && had=true
	_zp_sync
	if [ -n "$ZP_CHANGED" ]; then
		ch=true
		if _zp_up; then zapret_restart; else [ -x /opt/zapret/sync_config.sh ] && /opt/zapret/sync_config.sh >/dev/null 2>&1; fi
	fi
	printf '{"changed":%s,"captured":%s,"add_tcp":"%s","add_udp":"%s"}\n' "$ch" "$([ "$had" = true ] && echo false || echo true)" \
		"$(_zp_calc diff "$(_ports_get NFQWS_PORTS_TCP)" "$ot")" "$(_zp_calc diff "$(_ports_get NFQWS_PORTS_UDP)" "$ou")"
}

strategy_TCP_common() {
	printf '%s\n' "--new" "--filter-tcp=$PORTS_TCP" "--dpi-desync-any-protocol=1" "--dpi-desync-cutoff=n5" \
		"--dpi-desync=multisplit" "--dpi-desync-split-seqovl=582" "--dpi-desync-split-pos=1" \
		"--dpi-desync-split-seqovl-pattern=/opt/zapret/files/fake/stun.bin"
}

strategy_Gv1() {
	printf '%s\n' "#Gv1" "--new" "--filter-udp=$PORTS_UDP" "--dpi-desync=fake" "--dpi-desync-cutoff=d2" \
		"--dpi-desync-any-protocol=1" "--dpi-desync-fake-unknown-udp=/opt/zapret/files/fake/stun.bin"
}

strategy_Gv() {
	local n="$1"
	printf '%s\n' "#Gv$n" "--new" "--filter-udp=$PORTS_UDP" "--dpi-desync=fake" "--dpi-desync-repeats=10" \
		"--dpi-desync-any-protocol=1" "--dpi-desync-fake-unknown-udp=/opt/zapret/files/fake/stun.bin" "--dpi-desync-cutoff=n$n"
}

_game_rx() {
	printf '%s' "^#Gv[0-9]+(Xtreme)?\$|^--filter-(udp|tcp)=($PORTS_UDP|$PORTS_TCP|80,88,444-65535)\$"
}

_game_active() {
	[ -f "$CONF" ] || return 1
	sed -n "/^[[:space:]]*option NFQWS_OPT '\$/,\$p" "$CONF" | grep -qE "$(_game_rx)"
}

_game_xtreme_undo_opts() {
	local xfile="/opt/zapret/tmp/GvXtreme" old_tcp_opt old_udp_opt
	grep -q "^#Gv[0-9]\+Xtreme\$" "$CONF" || { rm -f "$xfile"; return 0; }
	if [ -f "$xfile" ]; then
		old_tcp_opt=$(sed -n '4p' "$xfile")
		old_udp_opt=$(sed -n '5p' "$xfile")
		[ -n "$old_tcp_opt" ] && sed -i "s|^[[:space:]]*option NFQWS_PORTS_TCP .*|$old_tcp_opt|" "$CONF"
		[ -n "$old_udp_opt" ] && sed -i "s|^[[:space:]]*option NFQWS_PORTS_UDP .*|$old_udp_opt|" "$CONF"
	fi
	rm -f "$xfile"
}

game_status() {
	local current="" xtreme="false" fake="" active="false"
	if [ -f "$CONF" ]; then
		current=$(grep -oE '^#Gv[1-4](Xtreme)?$' "$CONF" | head -n1 | sed 's/^#//; s/Xtreme$//')
		grep -q "^#Gv[0-9]\+Xtreme\$" "$CONF" && xtreme="true"
		fake=$(grep -m1 -- '--dpi-desync-fake-unknown-udp=' "$CONF" | sed 's|.*fake/||')
		_game_active && active="true"
	fi
	printf '{"current":"%s","xtreme":%s,"fake":"%s","active":%s}\n' "$(esc "$current")" "$xtreme" "$(esc "$fake")" "$active"
}

game_set() {
	local choice="$1" current="" rc
	_zm_re "$choice" '^([1-4]|off)$' || { echo '{"error":"некорректный номер Gv"}'; return 1; }
	[ -f "$CONF" ] || { echo '{"error":"Zapret не установлен"}'; return 1; }
	current=$(grep -oE '^#Gv[1-4](Xtreme)?$' "$CONF" | head -n1 | sed 's/^#//; s/Xtreme$//')

	if [ "$choice" = off ]; then
		_game_active || { printf '{"ok":true,"game":"none","removed":false}\n'; return 0; }
		cp "$CONF" "$CONF.gvbak"
		_game_xtreme_undo_opts
		_nfq_drop_profiles "$(_game_rx)"
		rc=$?
		case $rc in
			0|3)
				rm -f "$CONF.gvbak"
				_remove_ports_if_present NFQWS_PORTS_UDP "$PORTS_UDP"
				_remove_ports_if_present NFQWS_PORTS_TCP "$PORTS_TCP"
				zapret_restart
				printf '{"ok":true,"game":"none","removed":true}\n' ;;
			*)
				mv -f "$CONF.gvbak" "$CONF"
				echo '{"error":"блок стратегий Zapret (NFQWS_OPT) записан не так, как его пишет панель, — игровая часть не тронута"}'; return 1 ;;
		esac
		return 0
	fi

	[ "$current" = "Gv$choice" ] && { printf '{"ok":true,"game":"Gv%s"}\n' "$choice"; return 0; }

	cp "$CONF" "$CONF.gvbak"
	_game_xtreme_undo_opts
	_nfq_drop_profiles "$(_game_rx)"
	case $? in
		0|3) rm -f "$CONF.gvbak" ;;
		*) mv -f "$CONF.gvbak" "$CONF"
			echo '{"error":"блок стратегий Zapret (NFQWS_OPT) записан не так, как его пишет панель, — игровая часть не тронута"}'; return 1 ;;
	esac

	local last_quote strat
	last_quote=$(grep -n "^[[:space:]]*'[[:space:]]*\$" "$CONF" | tail -n1 | cut -d: -f1)
	[ -n "$last_quote" ] && sed -i "${last_quote},\$d" "$CONF"
	if [ "$choice" = "1" ]; then strat="$(strategy_Gv1; strategy_TCP_common)"; else strat="$(strategy_Gv "$choice"; strategy_TCP_common)"; fi
	echo "$strat" | sed '/^$/d' >> "$CONF"
	echo "'" >> "$CONF"
	_add_ports_if_missing NFQWS_PORTS_UDP "$PORTS_UDP"
	_add_ports_if_missing NFQWS_PORTS_TCP "$PORTS_TCP"
	zapret_restart
	printf '{"ok":true,"game":"Gv%s"}\n' "$choice"
}

game_set_fake() {
	local file="$1"
	case "$file" in
		stun.bin|stun2.bin|quic_initial_4pda_to.bin|quic_initial_tencent_com.bin|tls_clienthello_sochi_park.bin|quic_initial_www_google_com.bin|quic_initial_steamcommunity_com.bin|quic_initial_5ka_ru.bin|quic_initial_rutube_ru.bin) ;;
		*) echo '{"error":"неизвестный fake-файл"}'; return 1 ;;
	esac
	[ -f "$CONF" ] || { echo '{"error":"Zapret не установлен"}'; return 1; }
	grep -q -- '--dpi-desync-fake-unknown-udp=' "$CONF" || { echo '{"error":"игровая стратегия не установлена"}'; return 1; }
	awk -v new="$file" 'BEGIN{done=0} !done && /--dpi-desync-fake-unknown-udp=/{sub(/\/opt\/zapret\/files\/fake\/[^ ]+/, "/opt/zapret/files/fake/" new); done=1} {print}' "$CONF" > "$CONF.tmp" && mv "$CONF.tmp" "$CONF"
	zapret_restart
	printf '{"ok":true,"fake":"%s"}\n' "$(esc "$file")"
}

game_toggle_xtreme() {
	[ -f "$CONF" ] || { echo '{"error":"Zapret не установлен"}'; return 1; }
	local xfile="/opt/zapret/tmp/GvXtreme"
	local xports="80,88,444-65535"
	local xnfqws="80,88,443-65535"
	mkdir -p "$(dirname "$xfile")"

	if grep -q "^#Gv[0-9]\+Xtreme\$" "$CONF"; then
		[ -f "$xfile" ] || { echo '{"error":"файл восстановления отсутствует"}'; return 1; }
		local old_gv old_udp old_tcp old_tcp_opt old_udp_opt
		old_gv=$(sed -n '1p' "$xfile")
		old_udp=$(sed -n '2p' "$xfile")
		old_tcp=$(sed -n '3p' "$xfile")
		old_tcp_opt=$(sed -n '4p' "$xfile")
		old_udp_opt=$(sed -n '5p' "$xfile")
		awk -v gv="$old_gv" -v udp="$old_udp" -v tcp="$old_tcp" '
			/^#Gv[0-9]+Xtreme$/ { print gv; restore = 1; next }
			restore && /^--filter-udp=/ { print udp; next }
			restore && /^--filter-tcp=/ { print tcp; restore = 0; next }
			{ print }
		' "$CONF" > "$CONF.tmp" && mv "$CONF.tmp" "$CONF"
		[ -n "$old_tcp_opt" ] && sed -i "s|^[[:space:]]*option NFQWS_PORTS_TCP .*|$old_tcp_opt|" "$CONF"
		[ -n "$old_udp_opt" ] && sed -i "s|^[[:space:]]*option NFQWS_PORTS_UDP .*|$old_udp_opt|" "$CONF"
		rm -f "$xfile"
		zapret_restart
		printf '{"ok":true,"xtreme":false}\n'
		return
	fi

	grep -q "^#Gv[0-9]\+\$" "$CONF" || { echo '{"error":"игровая стратегия не установлена"}'; return 1; }
	awk '
		/^#Gv[0-9]+$/ { gv = $0; found = 1; next }
		found && /^--filter-udp=/ { udp = $0 }
		found && /^--filter-tcp=/ { tcp = $0 }
		/^[ \t]*option NFQWS_PORTS_TCP / { tcp_option = $0 }
		/^[ \t]*option NFQWS_PORTS_UDP / { udp_option = $0 }
		END { print gv; print udp; print tcp; print tcp_option; print udp_option }
	' "$CONF" > "$xfile"
	sed -i -e "s|^[[:space:]]*option NFQWS_PORTS_TCP .*|	option NFQWS_PORTS_TCP '$xnfqws'|" \
		-e "s|^[[:space:]]*option NFQWS_PORTS_UDP .*|	option NFQWS_PORTS_UDP '$xnfqws'|" "$CONF"
	sed -i "s/^#\(Gv[0-9]\+\)\$/#\1Xtreme/" "$CONF"
	awk -v ports="$xports" '
		/^#Gv[0-9]+Xtreme$/ { gv = 1; print; next }
		gv && /^--filter-udp=/ { print "--filter-udp=" ports; next }
		gv && /^--filter-tcp=/ { print "--filter-tcp=" ports; gv = 0; next }
		{ print }
	' "$CONF" > "$CONF.tmp" && mv "$CONF.tmp" "$CONF"
	zapret_restart
	printf '{"ok":true,"xtreme":true}\n'
}

_quic_blocked() {
	uci show firewall 2>/dev/null | grep -q "name='Block_UDP_80'" \
		&& uci show firewall 2>/dev/null | grep -q "name='Block_UDP_443'" \
		&& echo true || echo false
}

ZM_V6_OPT_RX="^[[:space:]]*option[[:space:]]+DISABLE_IPV6[[:space:]]+['\"]?"
_ipv6_enabled_in_zapret() {
	[ -f "$CONF" ] && grep -Eq "${ZM_V6_OPT_RX}0['\"]?[[:space:]]*\$" "$CONF" && echo true || echo false
}
_zapret_v6_set() {
	if grep -Eq "${ZM_V6_OPT_RX}[^[:space:]]*[[:space:]]*\$" "$CONF"; then
		sed -i -E "s/${ZM_V6_OPT_RX}[^[:space:]]*[[:space:]]*\$/\toption DISABLE_IPV6 '$1'/" "$CONF"
	else
		sed -i "/^[[:space:]]*config[[:space:]]\{1,\}main[[:space:]]\{1,\}'\{0,1\}config'\{0,1\}[[:space:]]*\$/a\\	option DISABLE_IPV6 '$1'" "$CONF"
	fi
}

FW4_TPL="/usr/share/firewall4/templates/ruleset.uc"
_fw4_offload_set() {
	local st="$1" zf="$2" t="$FW4_TPL.zm.$$"
	[ -f "$FW4_TPL" ] || return 2
	awk -v st="$st" -v zf="$zf" '
		BEGIN { re = "^[ \t]*meta l4proto [{] tcp, udp [}] (ct mark and 0x0ff00000 == 0x0 )?(ct original packets ge 30 )?flow offload @ft;$" }
		!done && $0 ~ re {
			ind = $0; sub(/meta l4proto.*$/, "", ind)
			hs = index($0, "ct mark and 0x0ff00000 == 0x0 ") > 0; hz = index($0, "ct original packets ge 30 ") > 0
			if (st == "1") hs = 1; else if (st == "0") hs = 0
			if (zf == "1") hz = 1; else if (zf == "0") hz = 0
			n = ind "meta l4proto { tcp, udp } " (hs ? "ct mark and 0x0ff00000 == 0x0 " : "") (hz ? "ct original packets ge 30 " : "") "flow offload @ft;"
			if (n != $0) ch = 1
			print n; done = 1; next
		}
		{ print }
		END { exit done ? (ch ? 0 : 1) : 2 }' "$FW4_TPL" > "$t"
	case $? in
		0) cat "$t" > "$FW4_TPL"; rm -f "$t"; return 0 ;;
		1) rm -f "$t"; return 1 ;;
		*) rm -f "$t"; return 2 ;;
	esac
}

_fw4_offload_on() { [ "$(uci -q get firewall.@defaults[0].flow_offloading)" = 1 ]; }
_fw4_offload_mode() {
	if [ "$(uci -q get firewall.@defaults[0].flow_offloading_hw)" = 1 ] && [ "$(uci -q get firewall.@defaults[0].flow_offloading)" = 1 ]; then echo hw
	elif [ "$(uci -q get firewall.@defaults[0].flow_offloading)" = 1 ]; then echo sw
	else echo off; fi
}
FT_STEER_OFF="$ZM_STATE_DIR/ft.steer.off"
_ft_steer_applied() { grep -q 'ct mark and 0x0ff00000 == 0x0 .*flow offload @ft;' "$FW4_TPL" 2>/dev/null; }

FT_ZAPRET_OFF="$ZM_STATE_DIR/ft.zapret.off"
_ft_zapret_sync() {
	[ -f "$FW4_TPL" ] && [ ! -f "$FT_ZAPRET_OFF" ] && _fw4_offload_on || return 0
	[ -x /etc/init.d/zapret ] || [ -x /etc/init.d/zapret2 ] || return 0
	[ "$(_flow_offloading_fix_applied)" = true ] && return 0
	_fw4_offload_set keep 1 || return 0
	logger -t zapret-manager "Flow Offloading: включён — поправка для Zapret применена сама"
	/etc/init.d/firewall reload >/dev/null 2>&1
	return 0
}
_ft_zapret_gone() {
	[ -x /etc/init.d/zapret ] || [ -x /etc/init.d/zapret2 ] && return 0
	rm -f "$FT_ZAPRET_OFF"
	[ "$(_flow_offloading_fix_applied)" = true ] || return 0
	_fw4_offload_set keep 0 || return 0
	echo "   ✓ Поправка Flow Offloading для Zapret убрана — Zapret на роутере больше нет"
	_fw4_offload_on && /etc/init.d/firewall reload >/dev/null 2>&1
	return 0
}
_ft_steer_sync() {
	local want=0
	[ -f "$FW4_TPL" ] || return 0
	if stl_present && [ ! -f "$FT_STEER_OFF" ]; then
		_ft_steer_applied && return 0
		_fw4_offload_on || return 0
		want=1
	else
		_ft_steer_applied || return 0
	fi
	_fw4_offload_set "$want" keep || return 0
	logger -t zapret-manager "Flow Offloading: соединения Steer $([ "$want" = 1 ] && echo "исключены из выгрузки потоков" || echo "снова выгружаются")"
	_fw4_offload_on && /etc/init.d/firewall reload >/dev/null 2>&1
	return 0
}

system_toggle_steer_offload_fix() {
	local w
	[ -f "$FW4_TPL" ] || { echo '{"error":"шаблон firewall4 не найден"}'; return 1; }
	w="$(_zm_want "$1")"
	if [ -n "$w" ] && [ "$(_ft_steer_applied && echo true || echo false)" = "$w" ]; then
		[ "$w" = true ] && rm -f "$FT_STEER_OFF"
		printf '{"ok":true,"steer_offload_fix":%s}\n' "$w"; return 0
	fi
	if _ft_steer_applied; then
		if _fw4_offload_on; then mkdir -p "$ZM_STATE_DIR"; : > "$FT_STEER_OFF"; fi
		_fw4_offload_set 0 keep
		logger -t zapret-manager "Flow Offloading: поправка для Steer отключена вручную"
	else
		stl_present || { echo '{"error":"Steer не установлен — поправка для него не нужна"}'; return 1; }
		rm -f "$FT_STEER_OFF"
		_fw4_offload_set 1 keep
		_ft_steer_applied || { echo '{"error":"в шаблоне firewall4 нет ожидаемой строки flow offload — поправка не применилась, ничего не изменено"}'; return 1; }
		logger -t zapret-manager "Flow Offloading: поправка для Steer применена"
	fi
	_fw4_offload_on && /etc/init.d/firewall reload >/dev/null 2>&1
	printf '{"ok":true,"steer_offload_fix":%s}\n' "$(_ft_steer_applied && echo true || echo false)"
}

_flow_offloading_fix_applied() {
	grep -q 'ct original packets ge 30 flow offload @ft;' /usr/share/firewall4/templates/ruleset.uc 2>/dev/null \
		&& echo true || echo false
}

_expert_mode() { [ -f "$EXPERT_MODE_FILE" ] && echo true || echo false; }

system_status() {
	printf '{"quic_blocked":%s,"ipv6_enabled":%s,"flow_offloading_fix":%s,"flow_mode":"%s","fw4_tpl":%s,"steer_installed":%s,"steer_offload_fix":%s,"steer_offload_off":%s,"zapret_fix_off":%s,"zapret_installed":%s,"watch_off":%s,"expert_mode":%s,"pkg":"%s",%s}\n' \
		"$(_quic_blocked)" "$(_ipv6_enabled_in_zapret)" "$(_flow_offloading_fix_applied)" "$(_fw4_offload_mode)" "$([ -f "$FW4_TPL" ] && echo true || echo false)" \
		"$(stl_present && echo true || echo false)" "$(_ft_steer_applied && echo true || echo false)" "$([ -f "$FT_STEER_OFF" ] && echo true || echo false)" \
		"$([ -f "$FT_ZAPRET_OFF" ] && echo true || echo false)" "$([ -x /etc/init.d/zapret ] || [ -x /etc/init.d/zapret2 ] && echo true || echo false)" "$([ -f "$WATCH_OFF" ] && echo true || echo false)" \
		"$(_expert_mode)" "$PKG" "$(_zt_json)"
}

ZM_V6_ADDRS="2001:4860:4860::8888 2606:4700:4700::1111 2a02:6b8::feed:0ff"
ZM_V6_STATE="$JOBS_DIR/v6.state"
_zm_v6_ms() {
	local a t
	for a in "$@"; do
		t="$(ping -6 -c1 -W2 "$a" 2>/dev/null | sed -n 's/.*time=\([0-9.]*\).*/\1/p' | head -n1)"
		[ -n "$t" ] && { echo "$t"; return 0; }
	done
	return 1
}
_zm_v6_dns() {
	nslookup google.com 127.0.0.1 2>/dev/null | awk '/^Name:/ { f = 1 } f && /^Address/ && /:[0-9A-Fa-f]*:/ { ok = 1 } END { exit !ok }'
}
_zm_v6_reach() {
	local a t
	for a in google.com $ZM_V6_ADDRS; do
		t="$(_zm_v6_ms "$a")" && { echo "$t $a"; return 0; }
	done
	return 1
}
_zm_v6_state_of() {
	[ -n "$1" ] || { echo dead; return; }
	if [ "${1#* }" = google.com ] || _zm_v6_dns; then echo live; else echo nodns; fi
}
_zm_v6_save() { mkdir -p "$JOBS_DIR"; echo "$1" > "$ZM_V6_STATE"; }
_zm_v6_probe() {
	_zm_v6_state_of "$(_zm_v6_reach)"
}
_zm_v6_cached() {
	local f="$ZM_V6_STATE"
	if [ ! -s "$f" ] || [ -n "$(find "$f" -mmin +10 2>/dev/null)" ]; then
		if mkdir "$f.lock" 2>/dev/null; then
			( _zm_v6_probe > "$f.new" 2>/dev/null; [ -s "$f.new" ] && mv -f "$f.new" "$f"; rmdir "$f.lock" ) >/dev/null 2>&1 </dev/null &
		elif [ -n "$(find "$f.lock" -mmin +2 2>/dev/null)" ]; then
			rmdir "$f.lock" 2>/dev/null
		fi
	fi
	cat "$f" 2>/dev/null
}

system_check_connectivity() {
	local t4 t6 r dns=true st
	t4=$(ping -4 -c1 -W2 google.com 2>/dev/null | grep 'time=' | sed -E 's/.*time=([0-9.]+).*/\1/')
	r="$(_zm_v6_reach)"; t6="${r%% *}"
	st="$(_zm_v6_state_of "$r")"
	[ "$st" = nodns ] && dns=false
	_zm_v6_save "$st"
	printf '{"ipv4_ok":%s,"ipv4_ms":"%s","ipv6_ok":%s,"ipv6_ms":"%s","ipv6_dns":%s}\n' \
		"$([ -n "$t4" ] && echo true || echo false)" "$(esc "$t4")" \
		"$([ -n "$t6" ] && echo true || echo false)" "$(esc "$t6")" "$dns"
}

_zm_want() { case "$1" in on) echo true ;; off) echo false ;; *) echo "" ;; esac; }
system_toggle_quic() {
	local w
	w="$(_zm_want "$1")"
	if [ -n "$w" ] && [ "$(_quic_blocked)" = "$w" ]; then printf '{"ok":true,"quic_blocked":%s}\n' "$w"; return 0; fi
	_sys_quic_flip
}
_sys_quic_flip() {
	if [ "$(_quic_blocked)" = "true" ]; then
		local rule idx
		for rule in Block_UDP_80 Block_UDP_443; do
			while true; do
				idx=$(uci show firewall | grep "name='$rule'" | cut -d. -f2 | cut -d= -f1 | head -n1)
				[ -z "$idx" ] && break
				uci -q delete "firewall.$idx" >/dev/null 2>&1 || break
			done
		done
		uci commit firewall >/dev/null 2>&1
		/etc/init.d/firewall restart >/dev/null 2>&1
		printf '{"ok":true,"quic_blocked":false}\n'
		return
	fi
	local lz wz
	lz="$(_zm_lan_zone)"; wz="$(_zm_wan_zone)"
	uci add firewall rule >/dev/null 2>&1
	uci set firewall.@rule[-1].name='Block_UDP_80' >/dev/null 2>&1
	uci add_list firewall.@rule[-1].proto='udp' >/dev/null 2>&1
	uci set "firewall.@rule[-1].src=$lz" >/dev/null 2>&1
	uci set "firewall.@rule[-1].dest=$wz" >/dev/null 2>&1
	uci set firewall.@rule[-1].dest_port='80' >/dev/null 2>&1
	uci set firewall.@rule[-1].target='REJECT' >/dev/null 2>&1
	uci add firewall rule >/dev/null 2>&1
	uci set firewall.@rule[-1].name='Block_UDP_443' >/dev/null 2>&1
	uci add_list firewall.@rule[-1].proto='udp' >/dev/null 2>&1
	uci set "firewall.@rule[-1].src=$lz" >/dev/null 2>&1
	uci set "firewall.@rule[-1].dest=$wz" >/dev/null 2>&1
	uci set firewall.@rule[-1].dest_port='443' >/dev/null 2>&1
	uci set firewall.@rule[-1].target='REJECT' >/dev/null 2>&1
	uci commit firewall >/dev/null 2>&1
	/etc/init.d/firewall restart >/dev/null 2>&1
	printf '{"ok":true,"quic_blocked":true}\n'
}

system_toggle_ipv6() {
	local w
	[ -f "$CONF" ] || { echo '{"error":"Zapret не установлен"}'; return 1; }
	w="$(_zm_want "$1")"
	if [ -n "$w" ] && [ "$(_ipv6_enabled_in_zapret)" = "$w" ]; then printf '{"ok":true,"ipv6_enabled":%s}\n' "$w"; return 0; fi
	_sys_ipv6_flip
}
_sys_ipv6_flip() {
	local r
	if [ "$(_ipv6_enabled_in_zapret)" = true ]; then
		_zapret_v6_set 1
		[ "$(_ipv6_enabled_in_zapret)" = false ] || { echo '{"error":"не удалось изменить настройку DISABLE_IPV6 в конфиге Zapret — ничего не изменено"}'; return 1; }
		zapret_restart
		printf '{"ok":true,"ipv6_enabled":false}\n'
		return
	fi
	if ! r="$(_zm_v6_reach)"; then
		_zm_v6_save dead
		echo '{"error":"IPv6 на роутере сейчас не работает: не ответили ни google.com, ни DNS Google, Cloudflare и Яндекса по IPv6. Включать его в Zapret не нужно"}'
		return 1
	fi
	_zm_v6_save "$(_zm_v6_state_of "$r")"
	_zapret_v6_set 0
	[ "$(_ipv6_enabled_in_zapret)" = true ] || { echo '{"error":"не удалось изменить настройку DISABLE_IPV6 в конфиге Zapret — ничего не изменено"}'; return 1; }
	zapret_restart
	printf '{"ok":true,"ipv6_enabled":true}\n'
}

system_toggle_flow_offloading_fix() {
	local template="/usr/share/firewall4/templates/ruleset.uc" w
	[ -f "$template" ] || { echo '{"error":"шаблон firewall4 не найден"}'; return 1; }
	w="$(_zm_want "$1")"
	if [ -n "$w" ] && [ "$(_flow_offloading_fix_applied)" = "$w" ]; then
		[ "$w" = true ] && rm -f "$FT_ZAPRET_OFF"
		printf '{"ok":true,"flow_offloading_fix":%s}\n' "$w"; return 0
	fi
	if grep -q 'ct original packets ge 30 flow offload @ft;' "$template"; then
		if _fw4_offload_on; then mkdir -p "$ZM_STATE_DIR"; : > "$FT_ZAPRET_OFF"; fi
		_fw4_offload_set keep 0
		fw4 restart >/dev/null 2>&1
		printf '{"ok":true,"flow_offloading_fix":false}\n'
		return
	fi
	rm -f "$FT_ZAPRET_OFF"
	_fw4_offload_set keep 1
	if ! grep -q 'ct original packets ge 30 flow offload @ft;' "$template"; then
		echo '{"error":"в шаблоне firewall4 нет ожидаемой строки flow offload — исправление не применилось, ничего не изменено"}'
		return 1
	fi
	fw4 restart >/dev/null 2>&1
	printf '{"ok":true,"flow_offloading_fix":true}\n'
}


ZM_FLASH_PATHS="/opt/zapret-manager-luci /usr/libexec/rpcd/zapret-manager /usr/share/rpcd/acl.d/luci-app-zapret-manager.json /usr/share/luci/menu.d/luci-app-zapret-manager.json /www/luci-static/resources/view/zapret-manager /www/luci-static/resources/zapret-manager /www/luci-static/resources/bytetube /www/luci-static/resources/view/bytetube /www/zm /www/zm-webui.html /usr/share/zm-redbtn"

_zm_kb() {
	[ $# -gt 0 ] || { echo 0; return 0; }
	du -sk "$@" 2>/dev/null | awk '{ s += $1 } END { print s + 0 }'
}

_zm_aged() {
	[ -e "$1" ] || [ -L "$1" ] || return 1
	[ "${2:-0}" -gt 0 ] || return 0
	[ -n "$(find "$1" -maxdepth 0 -mmin +"$2" 2>/dev/null)" ]
}

_zm_engine_refs() {
	local f
	for f in "$STL_ETC"/*.json "$STL_ETC"/*.yaml "$STL_ETC"/*.yml $( [ "$1" = engine ] || echo "$STL_KEEP $ST_DIR/model.svc $STL_TMP/spec.prev $ST_RUN/model" ); do
		[ -s "$f" ] && sed 's|\\/|/|g' "$f"
	done | tr '",[]{} \t\r' '\n\n\n\n\n\n\n\n\n' | sed "s/^'//; s/'\$//" | grep '^/' | sort -u
}

_zm_junk() {
	local refs="$JOBS_DIR/cleanup.refs.$$"
	mkdir -p "$JOBS_DIR"
	_zm_engine_refs > "$refs" 2>/dev/null
	if [ -s "$refs" ]; then
		_zm_junk_raw "$1" | awk -v refs="$refs" 'BEGIN { while ((getline l < refs) > 0) r[++n] = l; close(refs) } { for (i = 1; i <= n; i++) if (r[i] == $0 || index(r[i], $0 "/") == 1) next; print }'
	else
		_zm_junk_raw "$1"
	fi
	rm -f "$refs"
	return 0
}

_zm_tmp_live() {
	local p="${1##*/}"
	p="${p#*.}"; p="${p%%.*}"
	case "$p" in ''|*[!0-9]*) return 1 ;; esac
	[ "$p" != "$$" ] && [ -d "/proc/$p" ]
}

_zm_junk_raw() {
	local age=0 f n d foreign busy=""
	foreign="$(_st_blocker 2>/dev/null)"
	_zm_busy_job >/dev/null 2>&1 && busy=1
	for f in /tmp/zm-run.* /tmp/zm-wait.* /tmp/zm-quiet.* /tmp/zm-pkg.* /tmp/ytb-ct.* /tmp/ytb-diag.* /tmp/ytb-ins.* /tmp/ytb-dl /tmp/zm-zash /tmp/netshift-sbext.* /tmp/netshift-sblite.* \
		/tmp/mihomo.gz /tmp/zashboard.zip /tmp/zashboard /tmp/metacubexd.tgz /tmp/metacubexd /tmp/tg-ws-proxy.ipk /tmp/tg-ws-proxy.apk /tmp/zm_uninstall_panel.sh /tmp/zm-backup-*.tar.gz \
		"$JOBS_DIR"/install_tmp "$JOBS_DIR"/install_z2_tmp "$JOBS_DIR"/flowseal.zip "$JOBS_DIR"/flowseal_src "$JOBS_DIR"/tg-ws-proxy-rs.tar.gz \
		"$JOBS_DIR"/netshift-src "$JOBS_DIR"/zm_head.* "$JOBS_DIR"/steer-list.* "$JOBS_DIR"/tgws_install.* \
		"$JOBS_DIR"/geohide_hosts.tmp "$JOBS_DIR"/cleanup.* "$ST_RUN"/*.src "$ST_RUN"/cat.flat "$BK_DIR"/.*.part "$BK_DIR"/.mk.* "$JOBS_DIR"/bk.upload* \
		/opt/zapret-manager-luci/*.zm-new /www/luci-static/resources/zapret-manager/*.zm-new "$ZM_STATE_DIR"/*.tmp "$ST_DIR"/*.tmp "$ST_DIR"/lists/*.tmp \
		"$ST_USER_DIR"/*.tmp "$ST_USER_DIR"/*.tmp.* "$ST_SEC_DIR"/*/custom.*.tmp "$HOSTS_FILE.zmtmp" "$HOSTS_FILE.zmdrop"; do
		[ "$f" = "$JOBS_DIR/cleanup.$$" ] || [ "$f" = "$JOBS_DIR/cleanup.refs.$$" ] && continue
		_zm_tmp_live "$f" && continue
		if [ -n "$busy" ]; then case "$f" in *.zm-new|/tmp/zm_uninstall_panel.sh) ;; *) continue ;; esac; fi
		_zm_aged "$f" "$age" && echo "$f"
	done
	[ "$1" = install ] || { [ -e /tmp/zm_update_install.log ] && echo /tmp/zm_update_install.log; }
	[ -f "$TG_BIN_RS" ] && [ ! -e "$TG_INIT_RS" ] && [ ! -s "$TG_VER_RS_FILE" ] && echo "$TG_BIN_RS"
	[ -f "$TG_BIN_GO" ] && [ ! -e "$TG_INIT_GO" ] && [ ! -s "$TG_VER_GO_FILE" ] && echo "$TG_BIN_GO"
	[ -e "$ZM_UP_FILE" ] && echo "$ZM_UP_FILE"
	for f in /tmp/zm-rpc.*; do _zm_tmp_live "$f" && continue; _zm_aged "$f" 10 && echo "$f"; done
	if ! _job_running strategy_test; then
		for f in "$JOBS_DIR"/strategy_test/results_*.txt "$JOBS_DIR"/strategy_test/detail_*.txt "$JOBS_DIR"/strategy_test/log_*.txt "$JOBS_DIR"/strategy_test/urls.txt \
			"$JOBS_DIR"/strategy_test/candidates.txt "$JOBS_DIR"/strategy_test/block.txt "$JOBS_DIR"/strategy_test/sort.* "$JOBS_DIR"/strategy_test/ok.* "$JOBS_DIR"/strategy_test/pids.*; do
			[ -e "$f" ] && echo "$f"
		done
	fi
	n="$(cat /tmp/bytetube-test/job.pid 2>/dev/null)"
	case "$n" in ''|*[!0-9]*) n="" ;; esac
	if [ -z "$n" ] || ! kill -0 "$n" 2>/dev/null; then
		for f in /tmp/bytetube-test/results.txt /tmp/bytetube-test/results.raw /tmp/bytetube-test/job.log /tmp/bytetube-test/job.pid /tmp/bytetube-test/stop; do
			[ -e "$f" ] && echo "$f"
		done
	fi
	for f in "$JOBS_DIR"/*.pid; do
		[ -f "$f" ] || continue
		n="$(basename "$f" .pid)"
		_job_running "$n" || [ -f "$JOBS_DIR/$n.log" ] || echo "$f"
	done
	for f in "$JOBS_DIR"/install_z* "$JOBS_DIR"/sysinfo.json "$JOBS_DIR"/sysinfo.res "$JOBS_DIR"/sysinfo.urls "$JOBS_DIR"/tzdet.* "$JOBS_DIR"/excl_arp_tmp \
		"$JOBS_DIR"/yv_* "$JOBS_DIR"/nfq_drop_old "$JOBS_DIR"/nfq_drop_new "$JOBS_DIR"/steer.hide.in "$JOBS_DIR"/mixomo.hide.in "$JOBS_DIR"/forkop-svc.out "$JOBS_DIR"/forkop-lists.out \
		"$ST_RUN"/dl.* "$ST_RUN"/used.* "$ST_RUN"/srs.*.done "$ST_RUN"/lists.json "$ZM_STATE_DIR"/latest.* "$ZM_STATE_DIR"/versions.json "$ZM_STATE_DIR"/steer.latest; do
		case "$f" in "$JOBS_DIR"/sysinfo.*) _job_running sysinfo && continue ;; esac
		if [ -n "$busy" ]; then case "$f" in "$JOBS_DIR"/*) continue ;; esac; fi
		[ -e "$f" ] && echo "$f"
	done
	for f in "$JOBS_DIR"/*.log; do
		[ -f "$f" ] || continue
		n="$(basename "$f" .log)"
		_job_running "$n" && continue
		echo "$f"
		[ -f "$JOBS_DIR/$n.pid" ] && echo "$JOBS_DIR/$n.pid"
	done
	if [ -d "$ZM_LISTS_DIR" ]; then
		for f in "$ZM_LISTS_DIR"/.*; do
			[ -f "$f" ] || continue
			[ -n "$busy" ] && continue
			echo "$f"
		done
		if [ -s "$RB_SHARE/services.conf" ] && [ -z "$foreign" ]; then
			d=" $(grep -v '^#' "$RB_SHARE/services.conf" | cut -d'|' -f3,4 | tr ',|\n' '   ') "
			for f in "$ZM_LISTS_DIR"/*.lst; do
				[ -f "$f" ] || continue
				case "$d" in *" ${f##*/} "*) ;; *) echo "$f" ;; esac
			done
		fi
	fi
	if [ -d "$ST_DIR/lists" ] && [ -s "$RB_SHARE/services.conf" ] && [ -z "$foreign" ] && ! _st_running; then
		ls "$ST_DIR/lists" 2>/dev/null | awk -F'|' -v sel="$ST_SEL" -v conf="$RB_SHARE/services.conf" -v rem="$ST_CAT_SVC" -v dir="$ST_DIR/lists" '
			function load(file,    l, a, c, m, i) { while ((getline l < file) > 0) { if (l ~ /^#/) continue; split(l, a, "|"); if (!(a[1] in on)) continue; m = split(a[8], c, ","); for (i = 1; i <= m; i++) if (c[i] != "") keep[c[i]] = 1 } close(file) }
			BEGIN { while ((getline l < sel) > 0) if (l != "") { on[l] = 1; keep[l] = 1 } close(sel); load(conf); load(rem) }
			{ n = $0; sub(/\..*$/, "", n); if (n == "" || (n in keep)) next; print dir "/" $0 }' | while IFS= read -r f; do
			echo "$f"
		done
	fi
	return 0
}

_zm_refs_missing() {
	local f
	stl_present || return 0
	_zm_engine_refs engine 2>/dev/null | grep -E "^($ZM_LISTS_DIR|$ST_DIR/lists)/" | while IFS= read -r f; do
		[ -e "$f" ] || echo "$f"
	done
}

zm_refs_heal() {
	local f b id set n=0 m=0 left="" miss eng=""
	miss="$(_zm_refs_missing)"
	if [ "$1" = check ] || [ -z "$miss" ]; then
		printf '{"ok":true,"missing":%s,"restored":0,"left":0,"files":""}\n' "$(printf '%s' "$miss" | grep -c .)"
		return 0
	fi
	if _st_running; then
		echo '{"error":"идёт операция Steer — списки проверим после неё"}'
		return 1
	fi
	mkdir -p "$ST_RUN"
	for f in $miss; do
		m=$((m + 1))
		b="${f##*/}"
		case "$b" in *[!A-Za-z0-9._-]*|.*) left="$left $f"; continue ;; esac
		case "$f" in
			"$ZM_LISTS_DIR"/*.lst)
				_rb_list_get "$b" >/dev/null 2>&1 ;;
			"$ST_DIR"/lists/*.base.dom)
				id="${b%.base.dom}"
				case "$id" in ''|*[!A-Za-z0-9_-]*) ;; *)
					mkdir -p "$ST_DIR/lists"
					printf '%s,%s\n' "$(_rb_svc_field "$id" 5)" "$(_rb_svc_field "$id" 6)" | tr ',' '\n' | grep -E '^[a-z0-9.-]+\.[a-z]+$' | awk '!s[$0]++' > "$f.tmp"
					if [ -s "$f.tmp" ]; then mv -f "$f.tmp" "$f"; else rm -f "$f.tmp"; fi ;;
				esac ;;
			"$ST_DIR"/lists/*.srs|"$ST_DIR"/lists/*.dom|"$ST_DIR"/lists/*.pfx)
				set="${b%.*}"
				case "$set" in ''|*[!A-Za-z0-9_-]*) ;; *)
					rm -f "$ST_RUN/srs.$set.done" "$ST_RUN/dl.$set"
					_st_srs_get "$set" >/dev/null 2>&1
					rm -f "$ST_RUN/srs.$set.done" "$ST_RUN/dl.$set" "$ST_RUN/$set.src" ;;
				esac ;;
		esac
		if [ -e "$f" ]; then n=$((n + 1)); else left="$left $f"; fi
	done
	if [ "$n" -gt 0 ]; then
		if stl_running; then
			_stl_t 60 steer reload >/dev/null 2>&1
			eng=running
		elif [ -z "$(_st_blocker)" ] && _st_owns "steer-spec" && [ ! -f "$ST_OFF" ]; then
			if _zm_run 120 stl_restart >/dev/null 2>&1; then eng=started; else eng=stopped; fi
		else
			eng=stopped
		fi
	fi
	printf '{"ok":true,"missing":%s,"restored":%s,"left":%s,"engine":"%s","files":"%s"}\n' "$m" "$n" "$((m - n))" "$eng" "$(esc "$(echo $left)")"
}

_zm_mem_kb() { awk '/^MemAvailable:/ { print $2; f = 1; exit } /^MemFree:/ { m = $2 } END { if (!f) print m + 0 }' /proc/meminfo 2>/dev/null; }
_zm_df_kb() { df -kP "$1" 2>/dev/null | awk 'NR == 2 { print $4 + 0; f = 1 } END { if (!f) print 0 }'; }

_zm_fs_packs() {
	case "$(awk '$2 == "/overlay" { t = $3 } END { print t }' /proc/mounts 2>/dev/null)" in jffs2|ubifs) return 0 ;; esac
	return 1
}
_zm_mb() { awk -v k="$1" 'BEGIN { v = k / 1024; if (v < 10) printf "%.1f", v; else printf "%d", v + 0.5 }' | sed 's/\.0$//; s/\./,/'; }
_zm_bin_put() {
	local need have old=0 min keep=""
	need=$(( ($(wc -c < "$1" 2>/dev/null || echo 0) + 1023) / 1024 ))
	[ -f "$2" ] && old=$(( ($(wc -c < "$2" 2>/dev/null || echo 0) + 1023) / 1024 ))
	have="$(_zm_df_kb "${2%/*}")"
	min=$((need + 128))
	_zm_fs_packs && min=$((need / 3 + 64))
	if [ "$have" -gt 0 ] && [ $((have + old)) -lt "$min" ]; then
		echo "ОШИБКА: не хватает места на флеше: программе нужно $(_zm_mb "$need") МБ$(_zm_fs_packs && echo ", на флеше займёт примерно вдвое меньше"), свободно $(_zm_mb $((have + old))) МБ. Освободите место (удалите ненужные компоненты в разделе «Система») и попробуйте снова"
		return 1
	fi
	if [ -f "$2" ]; then
		mkdir -p "$JOBS_DIR"
		cp -p "$2" "$JOBS_DIR/zm-bin.keep" 2>/dev/null && keep=1
	fi
	rm -f "$2"
	if ! cp "$1" "$2" 2>/dev/null || ! chmod +x "$2"; then
		rm -f "$2"
		if [ -n "$keep" ] && cp -p "$JOBS_DIR/zm-bin.keep" "$2" 2>/dev/null; then
			echo "ОШИБКА: новая версия не поместилась на флеш (свободно $(_zm_mb $((have + old))) МБ, программа $(_zm_mb "$need") МБ) — прежняя версия возвращена"
		else
			rm -f "$2"
			echo "ОШИБКА: программа не поместилась на флеш: нужно $(_zm_mb "$need") МБ$(_zm_fs_packs && echo " (на флеше файлы сжимаются)"), свободно $(_zm_mb $((have + old))) МБ. Недописанный файл удалён — освободите место и попробуйте снова"
		fi
		rm -f "$JOBS_DIR/zm-bin.keep"
		return 1
	fi
	rm -f "$JOBS_DIR/zm-bin.keep"
	return 0
}

_zm_usage_json() {
	local list="$JOBS_DIR/cleanup.$$" jk=0 jn=0
	mkdir -p "$JOBS_DIR"
	_zm_junk "$1" > "$list" 2>/dev/null
	if [ -s "$list" ]; then
		jn="$(grep -c . "$list")"
		jk="$(_zm_kb $(cat "$list"))"
	fi
	rm -f "$list"
	printf '"flash_kb":%s,"lists_kb":%s,"tmp_kb":%s,"junk_kb":%s,"junk_n":%s,"flash_free_kb":%s,"tmp_free_kb":%s,"mem_free_kb":%s' \
		"$(_zm_kb $ZM_FLASH_PATHS)" "$(_zm_kb "$ST_DIR/lists" "$ZM_LISTS_DIR")" "$(_zm_kb "$JOBS_DIR")" "${jk:-0}" "${jn:-0}" \
		"$(_zm_df_kb /opt/zapret-manager-luci)" "$(_zm_df_kb /tmp)" "$(_zm_mem_kb)"
}

zm_cleanup() {
	local mode="$1" j f k n=0 tk=0 fk=0 m0 m1 list="$JOBS_DIR/cleanup.$$" w=0
	if [ "$mode" = postupd ]; then
		while { [ -f /tmp/zm_update_install.sh ] || _zm_busy_job >/dev/null 2>&1 || _au_live; } && [ "$w" -lt 600 ]; do sleep 15; w=$((w + 15)); done
		mode=auto
	fi
	if [ "$mode" != install ]; then
		if _au_live; then
			echo '{"error":"идёт автообновление панели и компонентов — очистка запустится после него"}'
			return 1
		fi
		if j="$(_zm_busy_job)"; then
			printf '{"error":"%s"}\n' "$(esc "идёт операция «$j» — дождитесь её окончания и запустите очистку")"
			return 1
		fi
		if [ -f /tmp/zm_update_install.sh ]; then
			echo '{"error":"идёт обновление панели — дождитесь его окончания"}'
			return 1
		fi
	fi
	mkdir -p "$JOBS_DIR"
	m0="$(_zm_mem_kb)"
	_zm_junk "$mode" > "$list" 2>/dev/null
	while IFS= read -r f; do
		case "$f" in
			/tmp/zm_update_install.sh) continue ;;
			/tmp/zm[-_]*|/tmp/ytb-*|/tmp/bytetube-test/?*|/tmp/netshift-sbext.*|/tmp/netshift-sblite.*|/tmp/mihomo.gz|/tmp/zashboard|/tmp/zashboard.zip|/tmp/metacubexd|/tmp/metacubexd.tgz|/tmp/tg-ws-proxy.ipk|/tmp/tg-ws-proxy.apk) ;;
			/tmp/zapret-manager-luci/?*|/opt/zapret-manager-luci/?*|/etc/zm-steer/?*|/etc/hosts.zmtmp|/etc/hosts.zmdrop) ;;
			/www/luci-static/resources/zapret-manager/?*|/www/luci-static/resources/view/zapret-manager/?*) ;;
			"$TG_BIN_RS"|"$TG_BIN_GO") ;;
			*) continue ;;
		esac
		case "$f" in */../*|*/..) continue ;; esac
		[ -e "$f" ] || [ -L "$f" ] || continue
		k="$(_zm_kb "$f")"
		rm -rf "$f" 2>/dev/null
		[ -e "$f" ] && continue
		n=$((n + 1))
		case "$f" in /tmp/*) tk=$((tk + k)) ;; *) fk=$((fk + k)) ;; esac
	done < "$list"
	rm -f "$list"
	for f in "$ZM_STATE_DIR"/*.lock; do
		[ -d "$f" ] && _zm_aged "$f" 5 && rmdir "$f" 2>/dev/null
	done
	_st_running || rm -f "$ST_RUN"/dl.* "$ST_RUN"/used.* "$ST_RUN"/srs.*.done 2>/dev/null
	rmdir "$ST_DIR/lists" "$ZM_LISTS_DIR" 2>/dev/null
	rm -f /tmp/luci-indexcache* /tmp/luci-modulecache/* 2>/dev/null
	if [ "$mode" != install ]; then
		sync
		echo 3 > /proc/sys/vm/drop_caches 2>/dev/null
	fi
	m1="$(_zm_mem_kb)"
	k=$(( ${m1:-0} - ${m0:-0} )); [ "$k" -gt 0 ] || k=0
	if [ "$mode" = auto ]; then mkdir -p "$ZM_STATE_DIR"; echo "$(date +%s) $n $((fk + tk)) $k" > "$ZM_AC_LAST"; fi
	printf '{"ok":true,"removed":%s,"freed_flash_kb":%s,"freed_tmp_kb":%s,"freed_mem_kb":%s,"refs_missing":%s,%s}\n' "$n" "$fk" "$tk" "$k" "$(_zm_refs_missing | grep -c .)" "$(_zm_usage_json "$mode")"
}

ZM_AC_FILE="$ZM_STATE_DIR/autoclean"
ZM_AC_UPD="$ZM_STATE_DIR/autoclean.upd"
ZM_AC_LAST="$ZM_STATE_DIR/autoclean.last"
ZM_AC_TAG="# zm-autoclean"
ZM_AC_CMD="/opt/zapret-manager-luci/backend.sh zm_cleanup auto >/dev/null 2>&1"
_zm_ac_hours() { case "$(cat "$ZM_AC_FILE" 2>/dev/null)" in 3) echo 3 ;; 6) echo 6 ;; 12) echo 12 ;; 24) echo 24 ;; *) echo 0 ;; esac; }
_zm_ac_spec() { case "$(_zm_ac_hours)" in 3|6|12) echo "41 */$(_zm_ac_hours) * * *" ;; 24) echo "41 4 * * *" ;; esac; }
_zm_ac_cron() {
	local spec want have
	spec="$(_zm_ac_spec)"
	want="${spec:+$spec $ZM_AC_CMD $ZM_AC_TAG}"
	have="$(grep -F "$ZM_AC_TAG" "$CRON_FILE" 2>/dev/null)"
	[ "$have" = "$want" ] && return 0
	mkdir -p "$(dirname "$CRON_FILE")"
	touch "$CRON_FILE"
	sed -i "\\|$ZM_AC_TAG|d" "$CRON_FILE"
	[ -n "$want" ] && echo "$want" >> "$CRON_FILE"
	/etc/init.d/cron enable >/dev/null 2>&1
	/etc/init.d/cron restart >/dev/null 2>&1
	return 0
}
gh_proxy() {
	local mo f=0 sep=""
	case "$1" in
		get|'') ;;
		set)
			mo="${2%%|*}"
			case "$mo" in off|auto) ;; *) echo '{"error":"неизвестный режим"}'; return 1 ;; esac
			mkdir -p "$ZM_STATE_DIR"
			if [ "$mo" = auto ]; then echo 'mode=auto' > "$ZM_GHP_FILE"; else rm -f "$ZM_GHP_FILE"; fi
			rm -f "$ZM_GHP_FAIL"
			ZM_GHP_MODE="" ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
	_zm_ghp_load
	[ -s "$ZM_GHP_FAIL" ] && read -r f < "$ZM_GHP_FAIL"
	case "$f" in ''|*[!0-9]*) f=0 ;; esac
	printf '{"ok":true,"mode":"%s","list":"%s","fail_at":%s,"now":%s,"log":[' "$ZM_GHP_MODE" "$ZM_GHP_LIST" "$f" "$(date +%s)"
	[ -s "$ZM_GHP_LOG" ] && tail -n 15 "$ZM_GHP_LOG" | while IFS='|' read -r t m; do
		case "$t" in ''|*[!0-9]*) continue ;; esac
		printf '%s{"t":%s,"m":"%s"}' "$sep" "$t" "$(esc "$m")"; sep=","
	done
	printf ']}\n'
}
_zm_ghp_warn() {
	local f=0
	_zm_ghp_load
	[ "$ZM_GHP_MODE" = off ] && [ -s "$ZM_GHP_FAIL" ] || return 1
	read -r f < "$ZM_GHP_FAIL"
	case "$f" in ''|*[!0-9]*) return 1 ;; esac
	[ $(( $(date +%s) - f )) -lt 1800 ]
}

zm_autoclean() {
	case "$1" in
		get|'') ;;
		sync) _zm_ac_cron ;;
		0|off) rm -f "$ZM_AC_FILE"; _zm_ac_cron ;;
		3|6|12|24) mkdir -p "$ZM_STATE_DIR"; echo "$1" > "$ZM_AC_FILE"; _zm_ac_cron ;;
		upd:on) mkdir -p "$ZM_STATE_DIR"; : > "$ZM_AC_UPD" ;;
		upd:off) rm -f "$ZM_AC_UPD" ;;
		*) echo '{"error":"выберите интервал: 3, 6, 12 или 24 часа"}'; return 1 ;;
	esac
	local t=0 n=0 fr=0 mem=0
	[ -s "$ZM_AC_LAST" ] && read -r t n fr mem < "$ZM_AC_LAST"
	case "$t$n$fr$mem" in *[!0-9]*) t=0; n=0; fr=0; mem=0 ;; esac
	printf '{"ok":true,"hours":%s,"after_update":%s,"cron":%s,"last":%s,"last_removed":%s,"last_freed_kb":%s,"last_mem_kb":%s,"now":%s}\n' "$(_zm_ac_hours)" "$([ -f "$ZM_AC_UPD" ] && echo true || echo false)" \
		"$(grep -qF "$ZM_AC_TAG" "$CRON_FILE" 2>/dev/null && echo true || echo false)" "${t:-0}" "${n:-0}" "${fr:-0}" "${mem:-0}" "$(date +%s)"
}

system_uninstall_panel() {
	local script="/tmp/zm_uninstall_panel.sh" j
	if [ -z "$ZM_PG_SELF" ] && j="$(_zm_busy_job)"; then
		printf '{"error":"%s"}\n' "$(esc "идёт операция «$j» — дождитесь её окончания и удалите панель")"
		return 1
	fi
	cat > "$script" << 'ZM_UNINSTALL_EOF'
sleep 1
/opt/zapret-manager-luci/backend.sh dns_net_gone >/dev/null 2>&1
if [ -z "$ZM_SAVE" ] && [ -f /opt/zapret/init.d/openwrt/custom.d/30-zm-section2.sh ]; then
	rm -f /opt/zapret/init.d/openwrt/custom.d/30-zm-section2.sh
	pgrep -f "/opt/zapre[t]/" >/dev/null 2>&1 && /etc/init.d/zapret restart >/dev/null 2>&1
fi
if [ -s /tmp/zapret-manager-luci/resolv.conf.zm-bak ]; then
	if [ -e /tmp/resolv.conf ]; then cat /tmp/zapret-manager-luci/resolv.conf.zm-bak > /tmp/resolv.conf 2>/dev/null || true
	else cat /tmp/zapret-manager-luci/resolv.conf.zm-bak > /etc/resolv.conf 2>/dev/null || true; fi
fi
if [ -s /opt/zapret-manager-luci/state/adblock/logfacility.saved ]; then
	while IFS='|' read -r zm_s zm_v; do
		[ -n "$zm_s" ] && [ -n "$zm_v" ] && uci -q get "dhcp.$zm_s" >/dev/null && [ -z "$(uci -q get "dhcp.$zm_s.logfacility")" ] && uci -q set "dhcp.$zm_s.logfacility=$zm_v" && zm_dns=1
	done < /opt/zapret-manager-luci/state/adblock/logfacility.saved
	[ -n "$zm_dns" ] && uci -q commit dhcp
fi
for zm_d in $(sed -n 's/^conf-dir=\([^,]*\).*/\1/p' /var/etc/dnsmasq.conf.* 2>/dev/null | sort -u) /tmp/dnsmasq.d /tmp/dnsmasq.*.d; do
	if [ -f "$zm_d/zm-adblock.conf" ]; then rm -f "$zm_d/zm-adblock.conf"; zm_dns=1; fi
	if [ -f "$zm_d/zm-adblock-stats.conf" ]; then rm -f "$zm_d/zm-adblock-stats.conf"; zm_dns=1; fi
done
nft delete table inet zm_adblock_free >/dev/null 2>&1
[ -s /var/run/zm-adblock-free.pid ] && kill "$(cat /var/run/zm-adblock-free.pid)" 2>/dev/null
rm -f /var/run/zm-adblock-free.pid /var/etc/zm-adblock-free.conf /var/etc/zm-adblock-free.conf.macs
[ -n "$zm_dns" ] && /etc/init.d/dnsmasq restart >/dev/null 2>&1
[ -s /tmp/zapret-manager-luci/htop.pid ] && kill "$(cat /tmp/zapret-manager-luci/htop.pid)" 2>/dev/null
[ -s /tmp/zapret-manager-luci/autoupd.lock/pid ] && kill "$(cat /tmp/zapret-manager-luci/autoupd.lock/pid)" 2>/dev/null
[ -z "$ZM_SAVE" ] && /opt/zapret-manager-luci/backend.sh htop_gone >/dev/null 2>&1
ZM_OPT="/opt/zapret-manager-luci"
if [ -n "$ZM_SAVE" ] && [ -d "$ZM_OPT/state" ]; then
	grep -F '/opt/zapret-manager-luci/backend.sh' /etc/crontabs/root 2>/dev/null | grep -v '# zm-rpcd-watch$' > "$ZM_OPT/state/cron.saved"
	[ -s "$ZM_OPT/state/cron.saved" ] || rm -f "$ZM_OPT/state/cron.saved"
	rm -rf "$ZM_OPT"/state/*.lock "$ZM_OPT"/state/inet "$ZM_OPT"/state/inet.new 2>/dev/null
fi
ZM_KEEP="$(cat /etc/steer/*.json /etc/steer/*.yaml /etc/steer/*.yml 2>/dev/null | sed 's|\\/|/|g' | tr '",[]{} \t\r' '\n\n\n\n\n\n\n\n\n' | sed "s/^'//; s/'\$//" | grep "^$ZM_OPT/lists/" | sort -u)"
if [ -n "$ZM_KEEP" ] || { [ -n "$ZM_SAVE" ] && { [ -d "$ZM_OPT/state" ] || [ -d "$ZM_OPT/backups" ]; }; }; then
	find "$ZM_OPT" \( -type f -o -type l \) 2>/dev/null | while IFS= read -r zm_f; do
		case "$zm_f" in "$ZM_OPT"/state/*|"$ZM_OPT"/backups/*) [ -n "$ZM_SAVE" ] && continue ;; esac
		printf '%s\n' "$ZM_KEEP" | grep -qxF "$zm_f" || rm -f "$zm_f"
	done
	find "$ZM_OPT" -depth -type d -exec rmdir {} \; 2>/dev/null
	ZM_OPT=""
fi
ZM_PATHS="$ZM_OPT /usr/libexec/rpcd/zapret-manager \
	/usr/share/luci/menu.d/luci-app-zapret-manager.json \
	/usr/share/rpcd/acl.d/luci-app-zapret-manager.json \
	/www/luci-static/resources/view/zapret-manager \
	/www/luci-static/resources/zapret-manager \
	/www/luci-static/resources/bytetube \
	/www/luci-static/resources/view/bytetube \
	/tmp/zapret-manager-luci /tmp/luci-indexcache* /tmp/luci-modulecache/* \
	/tmp/zm-run.* /tmp/zm-wait.* /tmp/zm-quiet.* /tmp/zm-pkg.* /tmp/zm-rpc.* /tmp/zm_update_install.log \
	/tmp/zm-rpcd-plugin.stamp /tmp/zm-rpcd-slow /tmp/zm-zash /tmp/zm-doh-failover.* /tmp/zm-doh.* /tmp/zm-dohfo.* \
	/tmp/zm-adblock-stats /tmp/zm-fk-* /tmp/zm-backup-*.tar.gz /var/run/dnsmasq/zm-queries.log \
	/etc/hosts.zmtmp /etc/hosts.zmdrop /etc/hosts.zm-bak \
	/www/zm /www/zm-webui.html /etc/zm-warp-own.conf /usr/bin/zmw /usr/bin/zms"
zm_try=0
while :; do
	rm -rf $ZM_PATHS 2>/dev/null
	zm_left=0
	for zm_f in $ZM_PATHS; do [ -e "$zm_f" ] || [ -L "$zm_f" ] && zm_left=1; done
	[ "$zm_left" = 0 ] && break
	[ "$zm_try" -ge 4 ] && break
	zm_try=$((zm_try + 1))
	sleep 1
done
[ -s /etc/zm-steer/owned ] || rm -rf /usr/share/zm-redbtn
[ -z "$ZM_SAVE" ] && [ ! -s /etc/zm-steer/owned ] && rm -rf /etc/zm-steer
[ -z "$ZM_SAVE" ] && rm -f /lib/upgrade/keep.d/zapret-manager
if grep -q '/opt/zapret-manager-luci/backend.sh' /etc/crontabs/root 2>/dev/null; then
	sed -i '\#/opt/zapret-manager-luci/backend.sh#d' /etc/crontabs/root
	/etc/init.d/cron restart >/dev/null 2>&1
fi
uci -q delete uhttpd.zmweb && uci -q commit uhttpd
/etc/init.d/rpcd restart >/dev/null 2>&1
/etc/init.d/uhttpd restart >/dev/null 2>&1
rm -f "$0"
ZM_UNINSTALL_EOF
	[ "$1" = wipe ] || sed -i '1i ZM_SAVE=1' "$script"
	[ -n "$ZM_PG_SELF" ] && sed -i '1s/^sleep 1$/sleep 8/' "$script"
	chmod 0755 "$script"
	( sh "$script" >/dev/null 2>&1 & )
	printf '{"ok":true,"kept":%s}\n' "$([ "$1" = wipe ] && echo false || echo true)"
}

PG_ORDER="steer forkozz mixomo awg bytetube zapret zapret2 tgproxy stgws tailscale terminal htop adblock doh dnsnet hosts panel"
_pg_title() {
	case "$1" in
		zapret) echo "Zapret" ;; zapret2) echo "Zapret2" ;; bytetube) echo "ByeTube (ByeDPI, hev-socks5-tunnel)" ;;
		steer) echo "Steer (ядро steer, WARP, подписки)" ;; forkozz) echo "Forkozz (netshift, sing-box)" ;;
		mixomo) echo "Mixomo (Mihomo, MagiTrickle)" ;; awg) echo "AmneziaWG" ;;
		tgproxy) echo "TG WS Proxy (MTProto, SOCKS5, Rust)" ;; stgws) echo "sTGWS" ;; tailscale) echo "Tailscale (телефон через роутер)" ;; terminal) echo "Терминал (ttyd)" ;; htop) echo "htop (Монитор ресурсов)" ;;
		adblock) echo "Блокировка рекламы" ;; doh) echo "DNS over HTTPS (https-dns-proxy)" ;;
		dnsnet) echo "Браузеры и российские сайты (записи DNS)" ;; hosts) echo "Записи панели в hosts" ;;
		panel) echo "Zapret Manager (LuCI, Web UI, настройки, zms и zmw)" ;;
	esac
}
_pg_group() {
	case "$1" in
		zapret|zapret2|bytetube) echo block ;; steer|forkozz|mixomo|awg|tgproxy|stgws|tailscale) echo vpn ;;
		adblock|doh|dnsnet|hosts) echo dns ;; terminal|htop) echo tools ;; panel) echo panel ;;
	esac
}
_pg_inst() {
	case "$1" in
		zapret) [ -f /etc/init.d/zapret ] || _pg_pkg zapret ;;
		zapret2) [ -f /etc/init.d/zapret2 ] || _pg_pkg zapret2 ;;
		bytetube) [ -x /usr/bin/bytetube ] ;;
		steer) [ -s "$ST_OWNED" ] ;;
		forkozz) _fk_ours ;;
		mixomo) _mx_installed || [ -x /etc/init.d/magitrickle ] ;;
		awg) _awg_installed ;;
		tgproxy) [ -x /etc/init.d/tg-ws-proxy ] || [ -x "$TG_BIN_GO" ] || [ -x "$TG_BIN_RS" ] ;;
		stgws) [ -x /etc/init.d/tgws ] || _pg_pkg tgws ;;
		tailscale) _tsc_installed || _pg_pkg tailscale ;;
		terminal) _term_installed ;;
		htop) [ -x /usr/bin/htop ] || _pg_pkg htop ;;
		adblock) _ab_on ;;
		doh) _doh_pkg ;;
		dnsnet) [ -s "$DN_OWN" ] ;;
		hosts) _pg_hosts_has ;;
		panel) return 0 ;;
		*) return 1 ;;
	esac
}
_pg_st_dir() {
	if [ ! -s "$ST_OWNED" ] && _fk_installed && [ -z "$(ls -A "$ST_DIR" 2>/dev/null | grep -vxE 'services\.remote|catalog\.(idx|meta|url|off|err)')" ]; then return 0; fi
	echo "$ST_DIR"
}
