	mkdir -p /usr/libexec/bytetube
	cat > /usr/libexec/bytetube/common.sh <<'YTB_FILE_END_7f3a9c'
#!/bin/sh

TUN=ytb0
MARK=0x10000
MASK=0x10000
TABLE=89
PREF=8900
NFT_TABLE=bytetube

dnsmasq_confdirs() {
	local d
	d=$(sed -n 's/^conf-dir=\([^,]*\).*/\1/p' /var/etc/dnsmasq.conf.* 2>/dev/null | sort -u)
	[ -n "$d" ] || d=/tmp/dnsmasq.d
	echo "$d"
}
dnsmasq_confdir() { dnsmasq_confdirs | head -n 1; }

dnsmasq_has_nftset() {
	dnsmasq --version 2>/dev/null | grep -Eq '(^| )nftset( |$)'
}

find_byedpi() {
	local b
	for b in /usr/bin/ciadpi /usr/bin/byedpi; do
		[ -x "$b" ] && { echo "$b"; return 0; }
	done
	command -v ciadpi
}

byedpi_opts_clean() {
	printf '%s' "$1" | tr -d "\"'" | tr '\n\r\t' '   ' | sed 's/^ *//; s/ *$//; s/  */ /g'
}

v6_kernel_ok() {
	local p="${YTB_PROC:-/proc}"
	[ -f "$p/net/if_inet6" ] || return 1
	[ "$(cat "$p/sys/net/ipv6/conf/all/disable_ipv6" 2>/dev/null)" = 1 ] && return 1
	[ "$(cat "$p/sys/net/ipv6/conf/default/disable_ipv6" 2>/dev/null)" = 1 ] && return 1
	return 0
}
YTB_FILE_END_7f3a9c
