bytetube_sync() {
	local f a b
	[ -x /usr/bin/bytetube ] && [ -x /etc/init.d/bytetube ] || { echo '{"installed":false}'; return 0; }
	f="/etc/init.d/bytetube /usr/bin/bytetube /usr/libexec/bytetube/common.sh /usr/libexec/bytetube/net.sh /usr/libexec/bytetube/route-up.sh"
	a="$(cat $f 2>/dev/null | md5sum)"
	_bytetube_install_payload >/dev/null 2>&1
	b="$(cat $f 2>/dev/null | md5sum)"
	[ "$a" = "$b" ] && { echo '{"installed":true,"changed":false}'; return 0; }
	if [ "$(uci -q get bytetube.main.enabled)" = 1 ]; then
		/etc/init.d/bytetube restart >/dev/null 2>&1
		echo '{"installed":true,"changed":true,"restarted":true}'
	else
		echo '{"installed":true,"changed":true,"restarted":false}'
	fi
}

do_bytetube_install() {
	NEW_BYEDPI=0
	NEW_HEV=0
	command -v fw4 >/dev/null 2>&1 || { echo "ОШИБКА: нужен firewall4 (OpenWrt 22.03+); hev-socks5-tunnel в пакетах — с 24.10"; return 1; }
	command -v nft >/dev/null 2>&1 || { echo "ОШИБКА: не найден nft"; return 1; }
	if ip rule add pref 8999 fwmark 0x10000/0x10000 lookup 89 2>/dev/null; then
		ip rule del pref 8999 2>/dev/null
	else
		echo "ОШИБКА: ваш ip не поддерживает fwmark с маской. Установите ip-full (замените ip-tiny на ip-full) и попробуйте снова"
		return 1
	fi

	_ensure_deps
	echo "==> Обновляем список пакетов"
	$UPDATE >&2

	if ! _pkg_is_installed kmod-tun; then
		echo "==> Ставим kmod-tun"
		$INSTALL kmod-tun >&2 || { echo "ОШИБКА: kmod-tun не установлен"; return 1; }
	fi
	_bytetube_ensure_dnsmasq_full || return 1

	if ! _pkg_is_installed hev-socks5-tunnel; then
		echo "==> Ставим hev-socks5-tunnel"
		$INSTALL hev-socks5-tunnel >&2 || { echo "ОШИБКА: hev-socks5-tunnel не найден в репозитории (есть в feeds OpenWrt 24.10+)"; return 1; }
		NEW_HEV=1
	fi
	_bytetube_install_byedpi || return 1

	for p in ca-bundle curl; do
		_pkg_is_installed "$p" || $INSTALL "$p" >&2 || echo "!! не удалось поставить $p — тест стратегий работать не будет (остальное — да)"
	done

	if [ "$NEW_BYEDPI" = 1 ] && [ -x /etc/init.d/byedpi ]; then
		/etc/init.d/byedpi stop >/dev/null 2>&1; /etc/init.d/byedpi disable >/dev/null 2>&1
	fi
	if [ "$NEW_HEV" = 1 ] && [ -x /etc/init.d/hev-socks5-tunnel ]; then
		/etc/init.d/hev-socks5-tunnel stop >/dev/null 2>&1; /etc/init.d/hev-socks5-tunnel disable >/dev/null 2>&1
	fi

	echo "==> Устанавливаем ByeTube (сервис)"
	_bytetube_install_payload
	rm -rf /tmp/luci-indexcache* /tmp/luci-modulecache
	/etc/init.d/rpcd reload >/dev/null 2>&1

	/etc/init.d/bytetube enable >/dev/null 2>&1
	echo "==> Запускаем"
	/etc/init.d/bytetube restart >/dev/null 2>&1
	sleep 4
	nslookup youtube.com 127.0.0.1 >/dev/null 2>&1
	sleep 1

	local ST
	ST=$(/usr/bin/bytetube status 2>/dev/null)
	_bt_show() {
		if [ "$(jsonfilter -s "$ST" -e "@.$1" 2>/dev/null)" = "true" ]; then
			echo "  [ok] $2"
		else
			echo "  [--] $2"
		fi
	}
	echo
	echo "==> Состояние:"
	_bt_show byedpi "ByeDPI (ciadpi)"
	_bt_show hev    "hev-socks5-tunnel"
	_bt_show tun    "интерфейс ytb0"
	_bt_show nft    "правила nftables"
	_bt_show route  "policy routing"
	_bt_show dns    "dnsmasq -> nftset"
	_bt_show fw     "firewall forward"
	echo "==> Готово, ByeTube установлен"
}

do_bytetube_uninstall() {
	echo "==> Останавливаем ByeTube"
	[ -x /usr/bin/bytetube ] && /usr/bin/bytetube test stop >/dev/null 2>&1
	_zm_svc_off bytetube
	echo "==> Снимаем правила файрвола и DNS ByeTube"
	if [ -x /usr/libexec/bytetube/net.sh ]; then
		/usr/libexec/bytetube/net.sh purge >/dev/null 2>&1
		. /usr/libexec/bytetube/common.sh
		for d in $(dnsmasq_confdirs 2>/dev/null || dnsmasq_confdir); do rm -f "$d/bytetube.conf"; done
	fi
	echo "==> Удаляем файлы и настройки ByeTube"
	local rc=0
	_zm_wipe /etc/config/bytetube /etc/init.d/bytetube /etc/rc.d/*bytetube /etc/hotplug.d/firewall/90-bytetube \
		/usr/bin/bytetube /usr/libexec/bytetube /usr/share/bytetube \
		/usr/share/nftables.d/chain-pre/forward/50-bytetube.nft \
		/var/etc/bytetube /var/run/bytetube.started /tmp/bytetube-test \
		/etc/bytetube /lib/upgrade/keep.d/bytetube || rc=1
	_zm_cron_drop 'bytetube' "ByeTube"
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	/etc/init.d/firewall reload >/dev/null 2>&1
	rm -rf /tmp/luci-indexcache* /tmp/luci-modulecache
	/etc/init.d/rpcd reload >/dev/null 2>&1
	[ "$ZM_NO_AFTER" = 1 ] && return "$rc"
	_zm_after_remove "ByeTube"
	_zm_rm_done "$rc" "ByeTube"
}
do_bytetube_purge() {
	local rc=0
	ZM_NO_AFTER=1 do_bytetube_uninstall || rc=1
	echo "==> Удаляем пакет byedpi"
	_zm_svc_off byedpi
	killall ciadpi >/dev/null 2>&1
	_zm_pkg_purge byedpi || rc=1
	if _mx_installed; then
		echo "==> hev-socks5-tunnel используется Mixomo — пакет оставляем"
	else
		echo "==> Удаляем пакет hev-socks5-tunnel"
		_zm_svc_off hev-socks5-tunnel
		_zm_pkg_purge hev-socks5-tunnel || rc=1
	fi
	_zm_rm_listed bytetube && echo "   ✓ Файлы ByeTube, byedpi$(_mx_installed || echo " и hev-socks5-tunnel") удалены" || rc=1
	_zm_after_remove "ByeTube"
	if [ "$rc" = 0 ]; then echo "==> Готово: ByeTube удалён полностью, остатков нет"; _zm_rb_note; return 0; fi
	ZM_RB_NOTE=""
	echo "ОШИБКА: ByeTube удалён не полностью — что осталось, написано выше. Перезагрузите роутер и нажмите «Удалить» ещё раз"
	return 1
}
bytetube_action() {
	local action="$1"
	case "$action" in
		install|update)
			if ! _bt_installed && _mx_installed; then
				echo '{"error":"Стоит Mixomo — он тоже использует hev-socks5-tunnel. Чтобы поставить ByeTube, удалите Mixomo."}'
				return 1
			fi
			job_start bytetube_install do_bytetube_install ;;
		remove)         job_start bytetube_remove do_bytetube_uninstall ;;
		purge)          job_start bytetube_remove do_bytetube_purge ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
}

_doh_file="/etc/config/https-dns-proxy"

_doh_pkg() { _pkg_is_installed https-dns-proxy; }
_doh_steer_active() { grep -qx 'steer-spec' /etc/zm-steer/owned 2>/dev/null && [ ! -f /etc/zm-steer/stopped ]; }

DOH_FORCE_MODE_FILE="/opt/zapret-manager-luci/doh_force"
_doh_force_mode() {
	local m
	m="$(cat "$DOH_FORCE_MODE_FILE" 2>/dev/null)"
	case "$m" in off) echo off ;; *) echo auto ;; esac
}
_doh_force_want() {
	if [ "$(_doh_force_mode)" = off ]; then echo 0; else echo 1; fi
}
_doh_main_text() {
	local n
	echo "config main 'config'"
	echo "	option dnsmasq_config_update '*'"
	echo "	option force_dns '$1'"
	echo "	option notrack_dns '1'"
	echo "	list force_dns_port '53'"
	echo "	list force_dns_port '853'"
	for n in $(_zm_lan_nets); do echo "	list force_dns_src_interface '$n'"; done
	echo "	option procd_trigger_wan6 '0'"
	echo "	option heartbeat_domain 'heartbeat.mossdef.org'"
	echo "	option heartbeat_sleep_timeout '10'"
	echo "	option heartbeat_wait_timeout '10'"
	echo "	option user 'nobody'"
	echo "	option group 'nogroup'"
	echo "	option listen_addr '127.0.0.1'"
	echo "	option force_ip_family 'auto'"
	if [ "$1" = 1 ]; then
		echo "	option canary_domains_icloud '1'"
		echo "	option canary_domains_mozilla '1'"
	fi
}
_doh_other_sections() {
	awk '/^config[ \t]/ { skip = ($2 == "main") } !skip' "$_doh_file" 2>/dev/null | sed -e :a -e '/^\n*$/{$d;N;ba' -e '}' | sed '/./,$!d'
}
_doh_force_apply() {
	local want new cur rest
	[ -f "$_doh_file" ] || return 0
	want="$(_doh_force_want)"
	new="$(_doh_main_text "$want")"
	cur="$(awk '/^config[ \t]/ { on = ($2 == "main") } on' "$_doh_file" | sed '/^[[:space:]]*$/d')"
	[ "$cur" = "$new" ] && return 0
	rest="$(_doh_other_sections)"
	{ printf '%s\n' "$new"; [ -n "$rest" ] && printf '\n%s\n' "$rest"; } > "$_doh_file.zmtmp" && mv -f "$_doh_file.zmtmp" "$_doh_file"
	/etc/init.d/https-dns-proxy running >/dev/null 2>&1 && /etc/init.d/https-dns-proxy restart >/dev/null 2>&1
	return 0
}

_dnsm_present() { [ -x /usr/bin/dns-manager ] || [ -x /usr/libexec/rpcd/dns_manager ]; }
_dnsm_guard() {
	_dnsm_present || return 0
	echo '{"error":"DNS на роутере настраивает DNS Manager — меняйте настройки в нём, панель их не трогает"}'
	return 1
}

doh_force_set() {
	_dnsm_guard || return 1
	case "$1" in auto|off) ;; on) set -- auto ;; *) echo '{"error":"неизвестный режим"}'; return 1 ;; esac
	if [ ! -f "$_doh_file" ] || [ ! -x /etc/init.d/https-dns-proxy ]; then
		echo '{"error":"DNS over HTTPS не установлен — сначала нажмите «Установить DNS over HTTPS»"}'
		return 1
	fi
	mkdir -p "$(dirname "$DOH_FORCE_MODE_FILE")"
	if [ "$1" = auto ]; then rm -f "$DOH_FORCE_MODE_FILE"; else echo "$1" > "$DOH_FORCE_MODE_FILE"; fi
	_doh_force_apply
	printf '{"ok":true,"mode":"%s","force_dns":%s}\n' "$1" "$([ "$(_doh_force_want)" = 1 ] && echo true || echo false)"
}

do_doh_install() {
	local installed
	_fk_installed && { echo "ОШИБКА: стоит $(_fk_name) — он сам шифрует DNS. Удалите $(_fk_name), чтобы поставить DoH"; return 1; }
	if ! _pkg_is_installed https-dns-proxy && [ -n "$(_zm_px_foreign)" ]; then echo "ОШИБКА: стоит $(_zm_px_foreign) — он сам ведёт DNS роутера и не уживается с https-dns-proxy. DNS шифруйте в нём"; return 1; fi
	installed=$(doh_status | grep -o '"installed":[a-z]*' | cut -d: -f2)
	if [ "$installed" = "true" ]; then
		echo "==> DNS over HTTPS уже установлен"
		return 0
	fi
	if _doh_pkg; then
		echo "==> Пакет https-dns-proxy уже стоит — включаем службу"
		/etc/init.d/https-dns-proxy enable >/dev/null 2>&1
		_doh_force_apply
		echo "==> Готово — выберите сервер ниже"
		return 0
	fi
	_ensure_deps
	echo "==> Обновляем список пакетов"
	$UPDATE >&2
	echo "==> Устанавливаем https-dns-proxy и luci-app-https-dns-proxy"
	$INSTALL https-dns-proxy luci-app-https-dns-proxy >&2 || { echo "ОШИБКА установки"; return 1; }
	_doh_force_apply
	local p r
	for p in quad9 cloudflare google; do
		echo "==> Включаем DNS через $(_doh_name "$p")"
		if r="$(_doh_apply "$p")"; then
			_doh_fo_put pref "$p"; _doh_fo_put active "$p"; rm -f "$DOH_FO_STATE"
			echo "   ✓ DNS роутера идёт через $(_doh_name "$p")"
			break
		fi
		echo "   ! $(printf '%s' "$r" | sed -n 's/.*"error":"\([^"]*\)".*/\1/p')"
	done
	_zo_doh_follow
	echo "==> Готово, DNS over HTTPS установлен — сервер можно сменить ниже"
}

do_doh_remove() {
	local r rc=0
	rm -f "$DOH_STOP"
	echo "==> Останавливаем DNS over HTTPS — dnsmasq возвращается к прежним серверам"
	_zm_svc_off https-dns-proxy
	killall https-dns-proxy >/dev/null 2>&1
	echo "==> Удаляем пакеты"
	_zm_pkg_wipe luci-i18n-https-dns-proxy-ru luci-app-https-dns-proxy https-dns-proxy || rc=1
	echo "==> Удаляем настройки и правила перехвата DNS"
	_zm_wipe /etc/config/https-dns-proxy /etc/config/https-dns-proxy-opkg /etc/config/https-dns-proxy.apk-new /etc/init.d/https-dns-proxy /etc/rc.d/*https-dns-proxy "$DOH_FORCE_MODE_FILE" "$DOH_BOOT_FILE" "$DOH_FO_FILE" "$DOH_FO_STATE" "$DOH_FO_EVENTS" "$DOH_OWN_FILE" "$_doh_file.zm-prev" /tmp/zm-doh-failover.lock || rc=1
	_doh_fo_cron off
	_zm_dns_scrub '^127\.0\.0\.1#50[0-9][0-9]$'
	for r in $(uci -q -X show firewall | sed -n "s/^firewall\.\([^.=]*\)\.name='[^']*[Hh]ttps[-_ ]dns[-_ ]proxy[^']*'\$/\1/p" | sort -u); do uci -q delete "firewall.$r"; done
	uci -q commit firewall
	/etc/init.d/firewall reload >/dev/null 2>&1
	_zm_cron_drop 'https-dns-proxy' "DoH"
	_zm_rm_listed doh || rc=1
	if [ "$(_dn_get ru off)" != off ]; then
		echo "==> Российские сайты снова идут через обычный DNS роутера"
		_dn_put ru off
		_dn_apply norestart
	fi
	echo "==> Перезапускаем DNS роутера"
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	_zo_doh_follow
	_zm_rm_done "$rc" "DNS over HTTPS"
}
doh_remove() {
	_dnsm_guard || return 1
	job_start doh_remove do_doh_remove
}

doh_install() {
	_dnsm_guard || return 1
	job_start doh_install do_doh_install
}

_doh_provider_of() {
	case "$1" in
		https://cloudflare-dns.com/*|https://1.1.1.1/*|https://1.0.0.1/*) echo cloudflare ;;
		https://dns.google/*|https://8.8.8.8/*|https://8.8.4.4/*) echo google ;;
		https://security.cloudflare-dns.com/*) echo cloudflare_sec ;;
		https://family.cloudflare-dns.com/*) echo cloudflare_fam ;;
		https://dns.quad9.net/*) echo quad9 ;;
		https://dns10.quad9.net/*) echo quad9_open ;;
		https://xbox-dns.ru/*) echo xbox ;;
		https://dns.comss.one/*) echo comss ;;
		https://dns.dns-ai.ru/*) echo dnsai ;;
		https://sync.bezmezhau.com/*) echo bezmezhau ;;
		https://common.dot.dns.yandex.net/*) echo yandex ;;
		https://family.dot.dns.yandex.net/*) echo yandex_family ;;
		https://safe.dot.dns.yandex.net/*) echo yandex_safe ;;
		https://eu.geohide.ru/*) echo geohide_eu ;;
		https://us.geohide.ru/*) echo geohide_us ;;
		https://dns.malw.link/*) echo malw ;;
		https://dns.zapret.moe/*) echo zapretmoe ;;
		https://d.webshiftvpn.ru/*) echo webshift ;;
		https://dns.dagami.ru/*) echo dagami ;;
		https://freedns.controld.com/p0) echo controld ;;
		https://freedns.controld.com/p1) echo controld_sec ;;
		https://freedns.controld.com/family) echo controld_fam ;;
		https://unfiltered.joindns4.eu/*) echo dns4eu ;;
		https://protective.joindns4.eu/*) echo dns4eu_sec ;;
		https://child.joindns4.eu/*) echo dns4eu_fam ;;
		*) echo "" ;;
	esac
}

_hosts_extra() {
	[ -s "$HOSTS_FILE" ] || { echo false; return; }
	awk -v me="$(uci -q get system.@system[0].hostname 2>/dev/null)" '
		BEGIN { split("localhost localhost.localdomain ip6-localhost ip6-loopback ip6-localnet ip6-mcastprefix ip6-allnodes ip6-allrouters ip6-allhosts broadcasthost", a, " "); for (i in a) ok[a[i]] = 1; r = "false" }
		{ sub(/#.*/, ""); if (NF < 2) next
		  for (i = 2; i <= NF; i++) { n = tolower($i); if (n in ok || n == tolower(me) || n ~ /\.lan$/) continue; r = "true"; exit } }
		END { print r }' "$HOSTS_FILE" 2>/dev/null || echo false
}

doh_power() {
	local cur
	_dnsm_guard || return 1
	{ [ -f "$_doh_file" ] && [ -x /etc/init.d/https-dns-proxy ]; } || { echo '{"error":"DNS over HTTPS не установлен"}'; return 1; }
	cur="$(_doh_cur_id)"
	case "$1" in
		off)
			mkdir -p "$(dirname "$DOH_STOP")"; : > "$DOH_STOP"
			/etc/init.d/https-dns-proxy stop >/dev/null 2>&1
			/etc/init.d/https-dns-proxy disable >/dev/null 2>&1
			/etc/init.d/dnsmasq restart >/dev/null 2>&1
			rm -f "$DOH_FO_STATE"
			_doh_fo_event "DoH остановлен кнопкой — DNS идёт через обычные серверы, пока не нажмёте «Запустить»"
			_zo_doh_follow
			_ab_dns_bg
			if /etc/init.d/https-dns-proxy running >/dev/null 2>&1; then echo '{"error":"служба https-dns-proxy не остановилась — смотрите журнал роутера"}'; return 1; fi
			printf '{"ok":true,"stopped":true}\n' ;;
		on)
			rm -f "$DOH_STOP" "$DOH_FO_STATE"
			/etc/init.d/https-dns-proxy enable >/dev/null 2>&1
			_zm_run 30 /etc/init.d/https-dns-proxy restart >/dev/null 2>&1
			/etc/init.d/dnsmasq restart >/dev/null 2>&1
			_zo_doh_follow
			_ab_dns_bg
			if _doh_wait_real 5053 10; then
				_doh_fo_event "DoH запущен кнопкой — DNS снова идёт через ${cur:+$(_doh_name "$cur")}"
				printf '{"ok":true,"stopped":false}\n'
			elif /etc/init.d/https-dns-proxy running >/dev/null 2>&1; then
				_doh_fo_event "DoH запущен кнопкой, но ${cur:+$(_doh_name "$cur")} пока не отвечает"
				printf '{"ok":true,"stopped":false,"warn":"%s"}\n' "$(esc "Служба запущена, но сервер ${cur:+$(_doh_name "$cur") }пока не отвечает — проверьте его или выберите другой")"
			else
				echo '{"error":"служба https-dns-proxy не запустилась — смотрите журнал роутера"}'; return 1
			fi ;;
		*) echo '{"error":"неизвестный режим"}'; return 1 ;;
	esac
}

doh_status() {
	local installed="false" current="" running=false force=false list="" sep="" i url port prov n=0 provs=""
	_doh_legacy_fix
	_doh_pkg && installed="true"
	[ "$installed" = true ] && _doh_boot_fill
	[ "$installed" = true ] && _doh_fo_on && ! grep -qF "$DOH_FO_CRON" "$CRON_FILE" 2>/dev/null && _doh_fo_cron on
	if [ -f "$_doh_file" ]; then
		i=0
		while url="$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].resolver_url")"; do
			port="$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].listen_port")"
			[ -n "$port" ] || port=$((5053 + i))
			prov="$(_doh_provider_of "$url")"
			list="$list$sep{\"url\":\"$(esc "$url")\",\"port\":\"$(esc "$port")\",\"provider\":\"$prov\",\"bootstrap\":\"$(esc "$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].bootstrap_dns")")\",\"boot_auto\":\"$(esc "$(_doh_boot_auto "$prov" "$url")")\",\"boot_dead\":$(grep -qxF "$url" "$DOH_BOOT_SKIP" 2>/dev/null && echo true || echo false)}"
			sep=","; n=$((n + 1)); provs="$prov"
			i=$((i + 1))
			[ "$i" -gt 16 ] && break
		done
		[ "$n" = 1 ] && current="$provs"
		[ "$(uci -q get https-dns-proxy.config.force_dns)" != "0" ] && force=true
	fi
	/etc/init.d/https-dns-proxy running >/dev/null 2>&1 && running=true
	[ -f "$DOH_STOP" ] && ! _doh_pkg && rm -f "$DOH_STOP"
	printf '{"name":"%s","installed":%s,"stopped":%s,"current":"%s","running":%s,"force_dns":%s,"force_mode":"%s","resolvers":[%s],"steer_active":%s,"steer_installed":%s,"forkozz":%s,"fk_name":"%s","bootstrap_custom":"%s","luci_boots":[%s],"hosts_extra":%s,"failover":%s,"dnsm":%s,"net":%s,"own":[%s],"zapret_doh":"%s"}\n' \
		"$(c="$(_doh_cur_id)"; [ -n "$c" ] && esc "$(_doh_name "$c")")" "$installed" "$([ -f "$DOH_STOP" ] && echo true || echo false)" "$(esc "$current")" "$running" "$force" "$(_doh_force_mode)" "$list" \
		"$(_doh_steer_active && echo true || echo false)" \
		"$(grep -qx 'engine' /etc/zm-steer/owned 2>/dev/null && stl_present && echo true || echo false)" \
		"$(_fk_installed && echo true || echo false)" "$(_fk_name)" "$(esc "$(cat "$DOH_BOOT_FILE" 2>/dev/null)")" "$(_doh_luci_list | awk -F'\t' '{ printf "%s{\"t\":\"%s\",\"b\":\"%s\"}", (NR > 1 ? "," : ""), $1, $2 }')" "$(_hosts_extra)" "$(_doh_fo_json)" \
		"$(_dnsm_present && echo true || echo false)" "$(_dn_json)" "$(_doh_own_json)" \
		"$(if [ ! -x /etc/init.d/zapret ] || [ ! -f "$CONF" ]; then echo none; elif [ -f "$ZO_DOH_FLAG" ]; then echo on; else echo off; fi)"
}

DOH_BOOT_FILE="/opt/zapret-manager-luci/doh_bootstrap"
DOH_BOOT_DEF="1.1.1.1,1.0.0.1,8.8.8.8,8.8.4.4"
DOH_LUCI_PROV="/usr/share/https-dns-proxy/providers"

_doh_boot_of() {
	case "$1" in
		cloudflare) echo "1.1.1.1,1.0.0.1,2606:4700:4700::1111,2606:4700:4700::1001" ;;
		google) echo "8.8.8.8,8.8.4.4,2001:4860:4860::8888,2001:4860:4860::8844" ;;
		cloudflare_sec) echo "1.1.1.2,1.0.0.2,2606:4700:4700::1112,2606:4700:4700::1002" ;;
		cloudflare_fam) echo "1.1.1.3,1.0.0.3,2606:4700:4700::1113,2606:4700:4700::1003" ;;
		quad9) echo "9.9.9.9,149.112.112.112,2620:fe::fe,2620:fe::9" ;;
		quad9_open) echo "9.9.9.10,149.112.112.10,2620:fe::10,2620:fe::fe:10" ;;
		yandex) echo "77.88.8.8,77.88.8.1" ;;
		yandex_family) echo "77.88.8.7,77.88.8.3" ;;
		yandex_safe) echo "77.88.8.88,77.88.8.2" ;;
		controld) echo "76.76.2.0,76.76.10.0" ;;
		controld_sec) echo "76.76.2.1,76.76.10.1" ;;
		controld_fam) echo "76.76.2.4,76.76.10.4" ;;
		dns4eu) echo "86.54.11.100,86.54.11.200" ;;
		dns4eu_sec) echo "86.54.11.1,86.54.11.201" ;;
		dns4eu_fam) echo "86.54.11.12,86.54.11.212" ;;
	esac
}

DOH_LUCI_JSON="/usr/share/https-dns-proxy/providers.json"
_doh_luci_list() {
	local c=/tmp/zm-doh-luciprov.tsv src
	if [ -s "$DOH_LUCI_JSON" ]; then src="$DOH_LUCI_JSON"
	elif ls "$DOH_LUCI_PROV"/*.json >/dev/null 2>&1; then src="$DOH_LUCI_PROV"
	else return 0; fi
	if [ -f "$c" ] && [ "$c" -nt "$src" ] && [ -n "$(find "$c" -mmin -60 2>/dev/null)" ]; then cat "$c"; return 0; fi
	if [ "$src" = "$DOH_LUCI_JSON" ]; then set -- "$src"; else set -- "$src"/*.json; fi
	awk '
		function flush() {
			gsub(/[ \t]/, "", b)
			if (t ~ /^https:\/\/[^ \t\\]*$/ && b ~ /^[0-9A-Fa-f.:,]+$/) print t "\t" b
			t = ""; b = ""
		}
		FNR == 1 { d = 0; key = ""; want = 0 }
		{
			ln = $0; n = length(ln); i = 1
			while (i <= n) {
				c = substr(ln, i, 1)
				if (c == "\"") {
					r = substr(ln, i + 1)
					if (!match(r, /^([^"\\]|\\.)*"/)) break
					v = substr(r, 1, RLENGTH - 1); i += RLENGTH + 1
					if (d != 1) continue
					if (want) { if (key == "template") t = v; else b = v; want = 0; key = ""; continue }
					r = substr(ln, i)
					if (match(r, /^[ \t\r]*:/)) { key = v; i += RLENGTH; want = (key == "template" || key == "bootstrap_dns") }
					continue
				}
				if (c == "{") { d++; if (d == 1) { t = ""; b = "" } }
				else if (c == "}") { d--; if (d == 0) flush() }
				if (c != " " && c != "\t" && c != "\r") want = 0
				i++
			}
		}
	' "$@" 2>/dev/null > "$c.$$" && mv -f "$c.$$" "$c"
	cat "$c" 2>/dev/null
}

_doh_luci_boot() {
	local u="$1" t b pre suf mid
	[ -n "$u" ] || return 0
	_doh_luci_list | while IFS='	' read -r t b; do
		case "$t" in
			*"{option}"*)
				pre="${t%%\{option\}*}"; suf="${t#*\{option\}}"
				case "$u" in "$pre"*"$suf") ;; *) continue ;; esac
				mid="${u#"$pre"}"; mid="${mid%"$suf"}"
				case "$mid" in */*|*'?'*|*'#'*) continue ;; esac ;;
			*) [ "$u" = "$t" ] || continue ;;
		esac
		echo "$b"; break
	done
}

_doh_boot_auto() {
	local u="$2" b
	[ -n "$u" ] || u="$(_doh_url_of "$1" 2>/dev/null)"
	b="$(_doh_boot_of "$1")"
	[ -n "$b" ] || b="$(_doh_boot_of "$(_doh_provider_of "$u")")"
	[ -n "$b" ] || b="$(_doh_luci_boot "$u")"
	echo "$b"
}

_doh_url_host() { local h="${1#*://}"; h="${h%%/*}"; echo "${h%%:*}"; }

_doh_boot_live() {
	local host b d k=0 out="" pids=""
	host="$(_doh_url_host "$1")"
	case "$host" in *[!0-9.]*) ;; *) echo "$2"; return 0 ;; esac
	[ -n "$2" ] || return 0
	d="/tmp/zm-dohbl.$$.$(date +%s)"; mkdir -p "$d"
	for b in $(printf '%s' "$2" | tr ',' ' '); do
		k=$((k + 1)); [ "$k" -gt 8 ] && break
		( _doh_t 4 nslookup -type=a "$host" "$b" 2>/dev/null | awk '
			/^Name:/ { f = 1 }
			f && /^Address/ { for (i = 2; i <= NF; i++) if ($i ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/) { print "ok"; exit } }' > "$d/$k" ) &
		pids="$pids $!"
	done
	wait $pids
	k=0
	for b in $(printf '%s' "$2" | tr ',' ' '); do
		k=$((k + 1)); [ "$k" -gt 8 ] && break
		[ -s "$d/$k" ] && out="$out${out:+,}$b"
	done
	rm -rf "$d"
	echo "$out"
}

_doh_boot_want() {
	local b=""
	[ -s "$DOH_BOOT_FILE" ] && b="$(head -n1 "$DOH_BOOT_FILE")"
	[ -n "$b" ] || b="$(_doh_boot_auto "$1" "$2")"
	echo "$b"
}

DOH_BOOT_449="1.1.1.1,1.0.0.1,2606:4700:4700::1111,2606:4700:4700::1001,8.8.8.8,8.8.4.4,2001:4860:4860::8888,2001:4860:4860::8844"
DOH_BOOT_SKIP="/tmp/zm-doh-bootfill.skip"
_doh_boot_stale() {
	[ "$(_doh_provider_of "$1")" = comss ] || return 1
	case "$(printf '%s' "$2" | tr -d ' ')" in 83.220.169.155|83.220.169.155,212.109.195.93|212.109.195.93,83.220.169.155|94.250.253.55|94.250.253.55,212.109.195.93|212.109.195.93,94.250.253.55) return 0 ;; esac
	return 1
}
DOH_BOOT_KEEP="/tmp/zm-doh-bootfill.keep"
_doh_boot_fill() {
	local i=0 url cur want luci need="" ch="" lk=/tmp/zm-doh-bootfill.lock
	[ -f "$_doh_file" ] && _doh_pkg || return 0
	_dnsm_present && return 0
	[ -s "$DOH_BOOT_FILE" ] && return 0
	rm -f "$ZM_STATE_DIR/doh.bootfill.skip"
	[ -n "$(find "$DOH_BOOT_SKIP" -mmin +1440 2>/dev/null)" ] && rm -f "$DOH_BOOT_SKIP"
	[ -n "$(find "$DOH_BOOT_KEEP" -mmin +1440 2>/dev/null)" ] && rm -f "$DOH_BOOT_KEEP"
	[ -d "$lk" ] && { [ -n "$(find "$lk" -maxdepth 0 -mmin +3 2>/dev/null)" ] || return 0; rmdir "$lk" 2>/dev/null; }
	while url="$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].resolver_url")"; do
		cur="$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].bootstrap_dns")"
		luci="$(_doh_luci_boot "$url")"
		if [ -z "$cur" ] || [ "$cur" = "$DOH_BOOT_449" ] || { [ -n "$luci" ] && [ "$cur" = "$luci" ]; } || _doh_boot_stale "$url" "$cur"; then
			want="$(_doh_boot_auto "$(_doh_provider_of "$url")" "$url")"
			if [ "$want" != "$cur" ] && ! grep -qxF "$url" "$DOH_BOOT_SKIP" "$DOH_BOOT_KEEP" 2>/dev/null; then
				if [ -n "$want" ] || _doh_boot_stale "$url" "$cur"; then need="$need $i"
				elif [ "$cur" = "$DOH_BOOT_449" ]; then
					uci -q delete "https-dns-proxy.@https-dns-proxy[$i].bootstrap_dns"; ch=1
				fi
			fi
		fi
		i=$((i + 1)); [ "$i" -gt 16 ] && break
	done
	[ -n "$ch" ] && uci -q commit https-dns-proxy
	[ -n "$need" ] || return 0
	mkdir "$lk" 2>/dev/null || return 0
	(
		ch=""; rs=""; port=""; urls=""
		cp -p "$_doh_file" "$_doh_file.zm-bootfill" 2>/dev/null
		for i in $need; do
			url="$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].resolver_url")" || continue
			cur="$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].bootstrap_dns")"
			if [ -n "$cur" ] && [ "$cur" != "$DOH_BOOT_449" ] && ! _doh_boot_stale "$url" "$cur" && [ -n "$(_doh_boot_live "$url" "$cur")" ]; then
				echo "$url" >> "$DOH_BOOT_KEEP"; continue
			fi
			want="$(_doh_boot_live "$url" "$(_doh_boot_auto "$(_doh_provider_of "$url")" "$url")")"
			[ -n "$want" ] && [ "$want" = "$cur" ] && continue
			if [ -n "$want" ]; then uci -q set "https-dns-proxy.@https-dns-proxy[$i].bootstrap_dns=$want"
			else
				echo "$url" >> "$DOH_BOOT_SKIP"
				[ -n "$cur" ] || continue
				uci -q delete "https-dns-proxy.@https-dns-proxy[$i].bootstrap_dns"
			fi
			ch=1; urls="$urls$url
"
			[ "${want:-$DOH_BOOT_449}" = "${cur:-$DOH_BOOT_449}" ] || rs=1
			[ -n "$port" ] || port="$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].listen_port")"; [ -n "$port" ] || port=$((5053 + i))
		done
		if [ -n "$ch" ]; then
			uci -q commit https-dns-proxy
			logger -t zapret-manager "DoH: Bootstrap DNS приведён к рабочим адресам провайдера"
			if [ -n "$rs" ] && [ ! -f "$DOH_STOP" ] && /etc/init.d/https-dns-proxy running >/dev/null 2>&1; then
				_zm_run 30 /etc/init.d/https-dns-proxy restart >/dev/null 2>&1
				if ! _doh_wait_local "$port" && ! { sleep 3; _doh_wait_local "$port"; }; then
					mv -f "$_doh_file.zm-bootfill" "$_doh_file"
					printf '%s' "$urls" >> "$DOH_BOOT_SKIP"
					_zm_run 30 /etc/init.d/https-dns-proxy restart >/dev/null 2>&1
					logger -t zapret-manager "DoH: с новым Bootstrap DNS DNS не заработал — вернули прежние настройки"
				fi
			fi
		fi
		rm -f "$_doh_file.zm-bootfill"
		rmdir "$lk" 2>/dev/null
	) >/dev/null 2>&1 &
	return 0
}

_doh_ip_ok() {
	case "$1" in *"$ZM_NL"*) return 1 ;; esac
	printf '%s' "$1" | grep -qE '^([0-9]{1,3}\.){3}[0-9]{1,3}$' && {
		local IFS=. o
		for o in $1; do [ "$o" -le 255 ] 2>/dev/null || return 1; done
		return 0
	}
	printf '%s' "$1" | grep -qE '^[0-9A-Fa-f:]+$' && printf '%s' "$1" | grep -q ':.*:'
}

doh_bootstrap_set() {
	local v="$1" ip out="" n=0 i url b
	_dnsm_guard || return 1
	case "$v" in *[*?\[]*) echo '{"error":"укажите IP-адреса через запятую, например 77.88.8.8, 1.1.1.1"}'; return 1 ;; esac
	for ip in $(printf '%s' "$v" | tr ',;' '  '); do
		_doh_ip_ok "$ip" || { printf '{"error":"%s"}\n' "$(esc "«$ip» — не IP-адрес. Укажите IP через запятую, например 77.88.8.8, 1.1.1.1")"; return 1; }
		case ",$out," in *",$ip,"*) continue ;; esac
		out="$out${out:+,}$ip"; n=$((n + 1))
	done
	[ "$n" -le 6 ] || { echo '{"error":"укажите не больше 6 адресов"}'; return 1; }
	mkdir -p "$(dirname "$DOH_BOOT_FILE")"
	if [ -n "$out" ]; then printf '%s\n' "$out" > "$DOH_BOOT_FILE"; else rm -f "$DOH_BOOT_FILE"; fi
	if [ -f "$_doh_file" ] && _doh_pkg; then
		i=0
		while url="$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].resolver_url")"; do
			b="$out"
			[ -n "$b" ] || b="$(_doh_boot_live "$url" "$(_doh_boot_auto "$(_doh_provider_of "$url")" "$url")")"
			if [ -n "$b" ]; then uci -q set "https-dns-proxy.@https-dns-proxy[$i].bootstrap_dns=$b"
			else uci -q delete "https-dns-proxy.@https-dns-proxy[$i].bootstrap_dns"; fi
			i=$((i + 1)); [ "$i" -gt 16 ] && break
		done
		uci -q commit https-dns-proxy
		if [ ! -f "$DOH_STOP" ]; then
			_zm_run 30 /etc/init.d/https-dns-proxy restart >/dev/null 2>&1
			/etc/init.d/dnsmasq restart >/dev/null 2>&1
		fi
	fi
	printf '{"ok":true,"bootstrap":"%s"}\n' "$(esc "$out")"
}

_doh_url_of() {
	case "$1" in
		cloudflare)    echo "https://cloudflare-dns.com/dns-query" ;;
		google)        echo "https://dns.google/dns-query" ;;
		cloudflare_sec) echo "https://security.cloudflare-dns.com/dns-query" ;;
		cloudflare_fam) echo "https://family.cloudflare-dns.com/dns-query" ;;
		quad9)         echo "https://dns.quad9.net/dns-query" ;;
		quad9_open)    echo "https://dns10.quad9.net/dns-query" ;;
		yandex)        echo "https://common.dot.dns.yandex.net/dns-query" ;;
		xbox)          echo "https://xbox-dns.ru/dns-query" ;;
		comss)         echo "https://dns.comss.one/dns-query" ;;
		dnsai)         echo "https://dns.dns-ai.ru/dns-query" ;;
		bezmezhau)     echo "https://sync.bezmezhau.com/dns-query" ;;
		yandex_family) echo "https://family.dot.dns.yandex.net/dns-query" ;;
		yandex_safe)   echo "https://safe.dot.dns.yandex.net/dns-query" ;;
		geohide_eu)    echo "https://eu.geohide.ru/dns-query" ;;
		geohide_us)    echo "https://us.geohide.ru/dns-query" ;;
		malw)          echo "https://dns.malw.link/dns-query" ;;
		zapretmoe)     echo "https://dns.zapret.moe/dns-query" ;;
		webshift)      echo "https://d.webshiftvpn.ru/dns-query" ;;
		dagami)        echo "https://dns.dagami.ru/dns-query" ;;
		controld)      echo "https://freedns.controld.com/p0" ;;
		controld_sec)  echo "https://freedns.controld.com/p1" ;;
		controld_fam)  echo "https://freedns.controld.com/family" ;;
		dns4eu)        echo "https://unfiltered.joindns4.eu/dns-query" ;;
		dns4eu_sec)    echo "https://protective.joindns4.eu/dns-query" ;;
		dns4eu_fam)    echo "https://child.joindns4.eu/dns-query" ;;
		https://*)
			printf '%s' "$1" | grep -qE '^https://[A-Za-z0-9.-]+\.[A-Za-z0-9-]+(:[0-9]{1,5})?(/[A-Za-z0-9._~%/+=&?-]*)?$' || return 1
			[ "${#1}" -le 200 ] || return 1
			echo "$1" ;;
		*) return 1 ;;
	esac
}

_doh_boots_for() {
	local b
	b="$(_doh_boot_want "$1")"
	echo "${b:-$DOH_BOOT_DEF}"
}

_doh_t() {
	local s="$1"
	shift
	_zm_tmo "$s" "$@"
}

_doh_boot_pick() {
	local b f="" s="" t=""
	for b in $(printf '%s' "$1" | tr ',' ' '); do
		case "$b" in *:*) continue ;; esac
		if [ -z "$f" ]; then f="$b"
		elif [ -z "$s" ] && [ "${b%%.*}" != "${f%%.*}" ]; then s="$b"
		elif [ -z "$t" ]; then t="$b"; fi
	done
	echo $f ${s:-$t}
}

_doh_host_ips() {
	local host="$1" b ips n=0
	case "$host" in *[!0-9.]*) ;; *) echo "$host"; return 0 ;; esac
	for b in $(_doh_boot_pick "$2"); do
		[ "$n" -ge 2 ] && break
		n=$((n + 1))
		ips="$(_doh_t 3 nslookup -type=a "$host" "$b" 2>/dev/null | awk '
			/^Name:/ { f = 1 }
			f && /^Address/ { for (i = 2; i <= NF; i++) if ($i ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/) { print $i; break } }' | head -n 3 | tr '\n' ',')"
		[ -n "$ips" ] && { echo "${ips%,}"; return 0; }
	done
	return 1
}

_doh_wire() {
	[ -s "$1" ] || { echo bad; return; }
	if ! command -v hexdump >/dev/null 2>&1 && ! command -v od >/dev/null 2>&1; then
		[ "$(wc -c < "$1")" -ge 12 ] && echo ok || echo bad
		return
	fi
	{ hexdump -v -e '1/1 "%02x "' "$1" 2>/dev/null || od -An -v -tx1 "$1" 2>/dev/null; } | awk -v ID="$2" -v NX="$3" '
		function hx(s) { return (index(H, substr(s, 1, 1)) - 1) * 16 + index(H, substr(s, 2, 1)) - 1 }
		function nm(p,   l) { while (p <= n) { l = b[p]; if (l == 0) return p + 1; if (l >= 192) return p + 2; p += l + 1 } return n + 1 }
		BEGIN { H = "0123456789abcdef" }
		{ for (i = 1; i <= NF; i++) b[++n] = hx(tolower($i)) }
		END {
			if (n < 12 || b[1] * 256 + b[2] != ID || b[3] < 128) { print "bad"; exit }
			rc = b[4] % 16; qd = b[5] * 256 + b[6]; an = b[7] * 256 + b[8]
			if (NX) { print (rc == 0 || rc == 3) ? "ok" : "rcode"; exit }
			if (rc != 0) { print "rcode"; exit }
			if (an == 0) { print "empty"; exit }
			p = 13
			for (i = 0; i < qd; i++) p = nm(p) + 4
			a = 0; z = 0
			for (i = 0; i < an && p + 10 <= n; i++) {
				p = nm(p); t = b[p] * 256 + b[p + 1]; l = b[p + 8] * 256 + b[p + 9]; p += 10
				if (t == 1 && l == 4) { a++; if (b[p] == 0 || b[p] == 127) z++ }
				p += l
			}
			print (a && a == z) ? "sink" : "ok"
		}'
}

_doh_fail_of() {
	case "$1" in
		6) echo resolve ;;
		7) echo connect ;;
		28) if [ "$2" = 0 ]; then echo timeout; elif [ "$3" = 0 ]; then echo tlsblock; else echo slow; fi ;;
		35|56) if [ "$2" != 0 ] && [ "$3" = 0 ]; then echo tlsblock; else echo connect; fi ;;
		51|53|58|59|60|77|83|90|91) echo tls ;;
		*) echo connect ;;
	esac
}

_doh_rank() {
	case "$1" in
		resolve) echo 1 ;; connect) echo 2 ;; timeout) echo 3 ;; tlsblock) echo 4 ;; tls) echo 5 ;; slow) echo 6 ;;
		http_*) echo 7 ;; bad) echo 8 ;; rcode|empty) echo 9 ;; sink) echo 10 ;; *) echo 0 ;;
	esac
}

_doh_pos() { awk -v t="$1" 'BEGIN { gsub(/,/, ".", t); print (t + 0 > 0) ? 1 : 0 }'; }
_doh_ms() { awk -v t="$1" 'BEGIN { gsub(/,/, ".", t); v = t * 1000; if (v < 1) v = 1; printf "%d", v + 0.5 }'; }

_doh_probe() {
	local url="$1" t="${3:-/tmp/zm-doh.$$}" rest hp host port ips ip res w rc l1 l2 r="" best="" k n=0 lab
	local code1 tc1 ta1 tt1 ct1 ec1 code2 tt2 ct2 ec2 W='%{http_code}|%{time_connect}|%{time_appconnect}|%{time_total}|%{content_type}|%{exitcode}\n'
	rest="${url#*://}"; hp="${rest%%/*}"
	case "$hp" in
		*:*) host="${hp%%:*}"; port="${hp##*:}" ;;
		*) host="$hp"; case "$url" in http://*) port=80 ;; *) port=443 ;; esac ;;
	esac
	lab="$(printf '%08d' $(( ($$ * 7919 + $(date +%s)) % 100000000 )))"
	printf '\053\147\001\000\000\001\000\000\000\000\000\000\012zm%s\007example\003com\000\000\001\000\001' "$lab" > "$t.q1"
	printf '\022\064\001\000\000\001\000\000\000\000\000\000\007example\003com\000\000\001\000\001' > "$t.q2"
	ips="$(_doh_host_ips "$host" "$2")"
	case "$host" in *[!0-9.]*) ;; *) ips="" ;; esac
	for ip in $(printf '%s' "${ips:--}" | tr ',' ' '); do
		[ "$n" -ge 2 ] && break
		n=$((n + 1))
		res=""; [ "$ip" = - ] || res="--resolve $host:$port:$ip"
		rm -f "$t.b1" "$t.b2"
		w="$(curl -q --fail-early --noproxy '*' -s --connect-timeout 3 --max-time 4 $res \
			-H 'Content-Type: application/dns-message' -H 'Accept: application/dns-message' \
			--data-binary "@$t.q1" -o "$t.b1" -w "$W" "$url" --next --noproxy '*' -s --connect-timeout 3 --max-time 4 $res \
			-H 'Content-Type: application/dns-message' -H 'Accept: application/dns-message' \
			--data-binary "@$t.q2" -o "$t.b2" -w "$W" "$url" 2>/dev/null)"
		rc=$?
		l1="$(printf '%s\n' "$w" | sed -n 1p)"; l2="$(printf '%s\n' "$w" | sed -n 2p)"
		IFS='|' read -r code1 tc1 ta1 tt1 ct1 ec1 <<EOF
$l1
EOF
		IFS='|' read -r code2 _ _ tt2 ct2 ec2 <<EOF
$l2
EOF
		case "$ec1" in ''|*[!0-9]*) ec1="$rc" ;; esac
		if [ -z "$l1" ] || [ "${code1:-000}" = 000 ]; then
			[ "$ec1" = 0 ] && ec1="$rc"
			r="$(_doh_fail_of "$ec1" "$(_doh_pos "$tc1")" "$(_doh_pos "$ta1")")"
		elif [ "$code1" != 200 ]; then r="http_$code1"
		else
			case "$(printf '%s' "$ct1" | tr 'A-Z' 'a-z')" in *application/dns-message*) r="$(_doh_wire "$t.b1" 11111 1)" ;; *) r=bad ;; esac
			if [ "$r" = ok ]; then
				case "$ec2" in ''|*[!0-9]*) ec2="$rc" ;; esac
				if [ -z "$l2" ] || [ "${code2:-000}" = 000 ]; then r="$(_doh_fail_of "${ec2:-28}" 1 1)"
				elif [ "$code2" != 200 ]; then r="http_$code2"
				else
					case "$(printf '%s' "$ct2" | tr 'A-Z' 'a-z')" in *application/dns-message*) r="$(_doh_wire "$t.b2" 4660)" ;; *) r=bad ;; esac
				fi
			fi
			[ "$r" = ok ] && { best="ok $(_doh_ms "$tt2") $(_doh_ms "$ta1") $ip"; break; }
		fi
		[ -z "$k" ] || [ "$(_doh_rank "$r")" -gt "$(_doh_rank "$k")" ] && k="$r"
	done
	rm -f "$t.q1" "$t.q2" "$t.b1" "$t.b2"
	[ -n "$best" ] && { echo "$best"; return 0; }
	echo "fail ${k:-connect}"
}

_doh_err_text() {
	case "$1" in
		resolve) echo "не удалось узнать адрес сервера" ;;
		timeout) echo "сервер не отвечает — соединение не устанавливается" ;;
		tlsblock) echo "соединение обрывается на шифровании — похоже, провайдер блокирует DoH" ;;
		tls) echo "сертификат сервера не прошёл проверку" ;;
		slow) echo "сервер не ответил на DNS-запрос за 4 секунды" ;;
		connect) echo "сервер недоступен" ;;
		http_*) echo "сервер ответил ошибкой ${1#http_}" ;;
		rcode|empty) echo "сервер ответил, но адрес сайта не выдал" ;;
		sink) echo "сервер вместо адреса отдаёт заглушку 0.0.0.0" ;;
		*) echo "ответ сервера не похож на DNS" ;;
	esac
}

_doh_res_json() {
	case "$1" in
		"ok "*) set -- $1; printf '"ok":true,"ms":%s,"conn":%s,"ip":"%s"' "$2" "${3:-0}" "$(esc "$([ "${4:--}" = - ] || echo "$4")")" ;;
		*) printf '"ok":false,"err":"%s","why":"%s"' "$(esc "$(_doh_err_text "${1#fail }")")" "$(esc "${1#fail }")" ;;
	esac
}

doh_probe() {
	local url
	url="$(_doh_url_of "$1")" || { echo '{"error":"адрес сервера не подходит — нужна ссылка вида https://…/dns-query"}'; return 1; }
	printf '{%s}\n' "$(_doh_res_json "$(_doh_probe "$url" "$(_doh_boots_for "$1")")")"
}

_doh_ns_q() {
	local rc
	DOH_NS_OUT="$(_doh_t 7 nslookup -type=a "$1" "127.0.0.1:$2" 2>&1)"; rc=$?
	case "$DOH_NS_OUT" in *SERVFAIL*|*REFUSED*|*[Rr]efused*|*"timed out"*|*"no servers"*|*"Parse error"*) return 1 ;; esac
	case "$DOH_NS_OUT" in *NXDOMAIN*) return 0 ;; esac
	[ "$rc" = 0 ] || return 1
	case "$DOH_NS_OUT" in *"Server:"*) ;; *) return 1 ;; esac
	case "$DOH_NS_OUT" in *"No answer"*) case "$DOH_NS_OUT" in *"answer:"*) return 0 ;; esac; return 1 ;; esac
	return 0
}

_doh_local_ok() {
	local port="${1:-5053}" o
	_doh_t 3 nslookup -type=a example.com "127.0.0.1:$port" >/dev/null 2>&1 && return 0
	o="$(_doh_t 3 nslookup -type=a "zm$$-$(date +%s).example.com" 127.0.0.1 2>&1)" && return 0
	printf '%s' "$o" | grep -qi 'NXDOMAIN'
}

_doh_live() {
	local o n
	n="zm$(printf '%08d' $(( ($$ * 7919 + $(date +%s)) % 100000000 ))).example.com"
	_doh_ns_q "$n" "${1:-5053}" && return 0
	o="$DOH_NS_OUT"
	case "$o" in
		*SERVFAIL*|*REFUSED*|*[Rr]efused*|*"timed out"*|*"no servers"*) return 1 ;;
	esac
	_doh_local_ok "$1"
}

_doh_live_real() {
	local o n port="${1:-5053}"
	n="zm$(printf '%08d' $(( ($$ * 7919 + $(date +%s)) % 100000000 ))).example.com"
	_doh_ns_q "$n" "$port" || return 1
	_doh_ns_q example.com "$port" || return 1
	case "$DOH_NS_OUT" in *"Name:"*) return 0 ;; esac
	return 1
}
_doh_wait_real() {
	local t0
	t0="$(date +%s)"
	while :; do
		sleep 1
		_doh_live_real "$1" && return 0
		[ $(( $(date +%s) - t0 )) -ge "${2:-10}" ] && return 1
	done
}

_doh_wait_local() {
	local t0 port="$1"
	t0="$(date +%s)"
	while :; do
		sleep 1
		_doh_local_ok "$port" && return 0
		[ $(( $(date +%s) - t0 )) -ge 8 ] && return 1
	done
}

doh_check() {
	local url port boots loc=false r pp t="/tmp/zm-doh.$$"
	url="$(uci -q get 'https-dns-proxy.@https-dns-proxy[0].resolver_url')"
	if [ -z "$url" ] || ! /etc/init.d/https-dns-proxy running >/dev/null 2>&1; then
		echo '{"skip":true}'
		return 0
	fi
	port="$(uci -q get 'https-dns-proxy.@https-dns-proxy[0].listen_port')"
	boots="$(uci -q get 'https-dns-proxy.@https-dns-proxy[0].bootstrap_dns')"
	[ -n "$boots" ] || boots="$(_doh_boots_for "$(_doh_provider_of "$url")")"
	_doh_probe "$url" "$boots" "$t" > "$t.r" 2>/dev/null &
	pp=$!
	{ _doh_live "${port:-5053}" || { sleep 1; _doh_live "${port:-5053}"; }; } && loc=true
	wait "$pp" 2>/dev/null
	r="$(cat "$t.r" 2>/dev/null)"
	rm -f "$t.r"
	printf '{"local":%s,%s}\n' "$loc" "$(_doh_res_json "${r:-fail connect}")"
}

doh_set() {
	local provider="$1" r
	_dnsm_guard || return 1
	_doh_url_of "$provider" >/dev/null || { echo '{"error":"адрес сервера не подходит — нужна ссылка вида https://…/dns-query"}'; return 1; }
	local installed; installed=$(doh_status | grep -o '"installed":[a-z]*' | cut -d: -f2)
	if [ "$installed" != "true" ]; then
		echo '{"error":"DNS over HTTPS не установлен — сначала нажмите «Установить DNS over HTTPS»"}'
		return 1
	fi
	if [ "$(_doh_cur_id)" = "$provider" ] && [ "$(_doh_fo_get pref "")" != "$provider" ] && [ "$(_doh_st_get mode normal)" != direct ] \
		&& /etc/init.d/https-dns-proxy running >/dev/null 2>&1 && _doh_live 5053; then
		_doh_fo_put pref "$provider"
		_doh_fo_put active "$provider"
		rm -f "$DOH_FO_STATE"
		_doh_fo_event "$(_doh_name "$provider") теперь основной сервер — DNS уже идёт через него"
		_zo_doh_follow
		printf '{"ok":true,"provider":"%s","kept":true}\n' "$(esc "$provider")"
		return 0
	fi
	ZO_DOH_PLAN="$(_doh_url_of "$provider")"
	_zo_doh_follow
	ZO_DOH_PLAN=""
	r="$(_doh_apply "$provider")" || { printf '%s\n' "$r"; _zo_doh_follow; return 1; }
	_doh_fo_put pref "$provider"
	_doh_fo_put active "$provider"
	rm -f "$DOH_FO_STATE"
	_ab_dns_bg
	printf '%s\n' "$r"
}

_doh_write() {
	{
		_doh_main_text "$3"
		echo ""
		echo "config https-dns-proxy"
		echo "	option resolver_url '$1'"
		[ -n "$2" ] && echo "	option bootstrap_dns '$2'"
		echo "	option listen_port '5053'"
	} > "$_doh_file.zmtmp" && mv -f "$_doh_file.zmtmp" "$_doh_file"
}

_doh_apply() {
	local provider="$1" url bootstrap="" auto="" live n prev="" force note=""
	url="$(_doh_url_of "$provider")" || { echo '{"error":"адрес сервера не подходит — нужна ссылка вида https://…/dns-query"}'; return 1; }
	if [ -s "$DOH_BOOT_FILE" ]; then bootstrap="$(head -n1 "$DOH_BOOT_FILE")"
	else
		auto="$(_doh_boot_auto "$provider" "$url")"
		if [ -n "$auto" ]; then
			live="$(_doh_boot_live "$url" "$auto")"
			if [ -z "$live" ]; then note="адреса $(echo "$auto" | sed 's/,/, /g') не отвечают — Bootstrap DNS не задан, https-dns-proxy использует встроенные"
			elif [ "$live" != "$auto" ]; then note="часть адресов не отвечает — оставили рабочие"; fi
			bootstrap="$live"
		fi
	fi
	force="$(_doh_force_want)"
	[ -f "$_doh_file" ] && cp -p "$_doh_file" "$_doh_file.zm-prev" 2>/dev/null && prev=1
	_doh_write "$url" "$bootstrap" "$force"
	if [ -f "$DOH_STOP" ]; then
		rm -f "$_doh_file.zm-prev"
		printf '{"ok":true,"provider":"%s","stopped":true,"bootstrap":"%s","boot_note":"%s"}\n' "$(esc "$provider")" "$(esc "$bootstrap")" "$(esc "$note")"
		return 0
	fi
	/etc/init.d/https-dns-proxy enable >/dev/null 2>&1
	/etc/init.d/https-dns-proxy reload >/dev/null 2>&1
	/etc/init.d/https-dns-proxy restart >/dev/null 2>&1
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	n=0
	_doh_wait_local 5053 && n=1
	if [ "$n" = 0 ] && [ -n "$auto" ] && [ -n "$bootstrap" ]; then
		_doh_write "$url" "" "$force"
		/etc/init.d/https-dns-proxy restart >/dev/null 2>&1
		if _doh_wait_local 5053; then
			n=1
			note="через адреса $(echo "$bootstrap" | sed 's/,/, /g') DNS не заработал — Bootstrap DNS не задан, https-dns-proxy использует встроенные"
			bootstrap=""
			logger -t zapret-manager "DoH: $(_doh_name "$provider") — $note"
		fi
	fi
	if [ "$n" = 0 ]; then
		if [ -n "$prev" ]; then
			mv -f "$_doh_file.zm-prev" "$_doh_file"
			/etc/init.d/https-dns-proxy restart >/dev/null 2>&1
			/etc/init.d/dnsmasq restart >/dev/null 2>&1
			echo '{"error":"Через этот сервер DNS на роутере не заработал — вернули прежние настройки"}'
		else
			/etc/init.d/https-dns-proxy stop >/dev/null 2>&1
			/etc/init.d/dnsmasq restart >/dev/null 2>&1
			echo '{"error":"Через этот сервер DNS на роутере не заработал — DoH остановлен, DNS идёт через обычные серверы. Выберите другой сервер"}'
		fi
		return 1
	fi
	rm -f "$_doh_file.zm-prev"
	if [ -f "$DOH_BOOT_SKIP" ]; then grep -vxF "$url" "$DOH_BOOT_SKIP" > "$DOH_BOOT_SKIP.$$"; mv -f "$DOH_BOOT_SKIP.$$" "$DOH_BOOT_SKIP"; fi
	[ -n "$auto" ] && [ -z "$bootstrap" ] && echo "$url" >> "$DOH_BOOT_SKIP"
	printf '{"ok":true,"provider":"%s","bootstrap":"%s","boot_note":"%s"}\n' "$(esc "$provider")" "$(esc "$bootstrap")" "$(esc "$note")"
}

DOH_FO_FILE="/opt/zapret-manager-luci/doh_failover"
DOH_STOP="/opt/zapret-manager-luci/state/doh.stopped"
DOH_FO_STATE="/tmp/zm-doh-failover.state"
DOH_FO_EVENTS="/tmp/zm-doh-failover.events"
DOH_FO_CRON="# zm-dohwatch"
_doh_fo_get() { local v; v="$(_kv_last "$DOH_FO_FILE" "$1")"; echo "${v:-$2}"; }
_doh_fo_put() {
	mkdir -p "$(dirname "$DOH_FO_FILE")"
	{ grep -v "^$1=" "$DOH_FO_FILE" 2>/dev/null; echo "$1=$2"; } > "$DOH_FO_FILE.zm.$$" && mv -f "$DOH_FO_FILE.zm.$$" "$DOH_FO_FILE"
}
_doh_st_get() { local v; v="$(_kv_last "$DOH_FO_STATE" "$1")"; echo "${v:-$2}"; }
_doh_st_put() {
	local k v
	[ -f "$DOH_FO_STATE" ] || : > "$DOH_FO_STATE"
	while [ $# -ge 2 ]; do
		k="$1"; v="$2"; shift 2
		{ grep -v "^$k=" "$DOH_FO_STATE"; echo "$k=$v"; } > "$DOH_FO_STATE.zm.$$" && mv -f "$DOH_FO_STATE.zm.$$" "$DOH_FO_STATE"
	done
}
_doh_fo_event() {
	logger -t zapret-manager "DoH: $1"
	{ tail -n 9 "$DOH_FO_EVENTS" 2>/dev/null; printf '%s|%s\n' "$(date +%s)" "$1"; } > "$DOH_FO_EVENTS.zm" && mv -f "$DOH_FO_EVENTS.zm" "$DOH_FO_EVENTS"
}
DOH_LK="/tmp/zm-doh-failover.lock"
_doh_locked() {
	local rc w=0
	while ! mkdir "$DOH_LK" 2>/dev/null; do
		if [ -n "$(find "$DOH_LK" -maxdepth 0 -mmin +5 2>/dev/null)" ]; then rmdir "$DOH_LK" 2>/dev/null; continue; fi
		[ "$w" -ge 20 ] && { echo '{"error":"Сейчас DNS проверяет автопереключение — повторите через минуту"}'; return 1; }
		sleep 1; w=$((w + 1))
	done
	"$@"; rc=$?
	rmdir "$DOH_LK" 2>/dev/null
	return $rc
}
_doh_fo_on() { [ "$(_doh_fo_get fo 0)" = 1 ] || [ "$(_doh_fo_get direct 0)" = 1 ]; }
_doh_name() {
	case "$1" in
		google) echo Google ;; cloudflare) echo Cloudflare ;; quad9) echo "Quad9 · Защита от угроз" ;; xbox) echo XBOX ;; comss) echo Comss ;; dnsai) echo DNS-AI ;; bezmezhau) echo Bezmezhau ;;
		cloudflare_sec) echo "Cloudflare · Защита от угроз" ;; cloudflare_fam) echo "Cloudflare · Семейный фильтр" ;; quad9_open) echo "Quad9 · Без фильтрации" ;;
		controld_sec) echo "Control D · Защита от угроз" ;; controld_fam) echo "Control D · Семейный фильтр" ;; dns4eu_sec) echo "DNS4EU · Защита от угроз" ;; dns4eu_fam) echo "DNS4EU · Семейный фильтр" ;;
		yandex) echo "Яндекс" ;; yandex_family) echo "Яндекс · Семейный фильтр" ;; yandex_safe) echo "Яндекс · Защита от угроз" ;; geohide_eu) echo "GeoHide EU" ;;
		geohide_us) echo "GeoHide US" ;; malw) echo MALW ;; zapretmoe) echo zapret.moe ;; webshift) echo WebShift ;; dagami) echo Dagami ;;
		controld) echo "Control D" ;; dns4eu) echo DNS4EU ;;
		https://*) _doh_own_title "$1" | grep . || printf '%s' "$1" | sed 's#^https://\([^/]*\).*#\1#' ;; *) echo "$1" ;;
	esac
}
_doh_cur_id() {
	local u p
	[ -n "$(uci -q get 'https-dns-proxy.@https-dns-proxy[1].resolver_url')" ] && return 0
	u="$(uci -q get 'https-dns-proxy.@https-dns-proxy[0].resolver_url')"
	[ -n "$u" ] || return 0
	p="$(_doh_provider_of "$u")"
	echo "${p:-$u}"
}
_doh_bad_key() { printf 'bad%s' "$(printf '%s' "$1" | md5sum | cut -c1-10)"; }
_doh_bad_wait() {
	local v n w=600
	v="$(_doh_st_get "$(_doh_bad_key "$1")" "")"; n="${v#*:}"
	case "$n" in ''|*[!0-9]*) echo 0; return ;; esac
	while [ "$n" -gt 1 ] && [ "$w" -lt 7200 ]; do w=$((w * 2)); n=$((n - 1)); done
	[ "$w" -gt 7200 ] && w=7200
	echo "$w"
}
_doh_bad_skip() {
	local v t w
	v="$(_doh_st_get "$(_doh_bad_key "$1")" "")"; [ -n "$v" ] || return 1
	t="${v%%:*}"; w="$(_doh_bad_wait "$1")"
	case "$t" in ''|*[!0-9]*) return 1 ;; esac
	[ $(( $(date +%s) - t )) -lt "$w" ]
}
_doh_bad_mark() {
	local v n
	v="$(_doh_st_get "$(_doh_bad_key "$1")" "")"; n="${v#*:}"
	case "$n" in ''|*[!0-9]*) n=0 ;; esac
	_doh_st_put "$(_doh_bad_key "$1")" "$(date +%s):$((n + 1))"
}
_doh_bad_clear() { [ -f "$DOH_FO_STATE" ] && grep -q "^$(_doh_bad_key "$1")=" "$DOH_FO_STATE" && _doh_st_put "$(_doh_bad_key "$1")" ""; return 0; }
_doh_ok() { case "$(_doh_probe "$(_doh_url_of "$1")" "$(_doh_boots_for "$1")" "/tmp/zm-dohfo.$$")" in "ok "*) return 0 ;; esac; return 1; }
_doh_cur_alive() {
	local port lf
	port="$(uci -q get 'https-dns-proxy.@https-dns-proxy[0].listen_port')"; port="${port:-5053}"
	_doh_live_real "$port" && { _doh_st_put lfail 0; return 0; }
	sleep 2
	_doh_live_real "$port" && { _doh_st_put lfail 0; return 0; }
	_doh_ok "$1" || return 1
	lf="$(_doh_st_get lfail 0)"; case "$lf" in ''|*[!0-9]*) lf=0 ;; esac
	lf=$((lf + 1)); _doh_st_put lfail "$lf"
	if [ "$lf" = 1 ] || [ "$lf" = 3 ]; then
		_zm_run 30 /etc/init.d/https-dns-proxy restart >/dev/null 2>&1
		_doh_wait_real "$port" 10 && { _doh_st_put lfail 0; _doh_fo_event "$(_doh_name "$1") отвечает, а DNS на роутере завис — перезапустили https-dns-proxy"; return 0; }
	fi
	[ "$lf" -ge 3 ] && return 1
	return 0
}
_doh_fo_chain() {
	local id
	_doh_fo_get chain "" | tr ',' '\n' | while IFS= read -r id; do
		[ -n "$id" ] && _doh_url_of "$id" >/dev/null && echo "$id"
	done
	return 0
}
_doh_fo_pool() {
	local pref="$1" skip="$2" id
	for id in $(_doh_fo_chain "$pref"); do [ "$id" = "$skip" ] || [ "$id" = "$pref" ] || echo "$id"; done
}
doh_watch() {
	local lk="/tmp/zm-doh-failover.lock" cur pref mode fails okc c run=0 t flap="" since
	_doh_fo_on || { _doh_fo_cron off; return 0; }
	[ -f "$DOH_STOP" ] && return 0
	[ -f "$_doh_file" ] && _doh_pkg || return 0
	_fk_installed && return 0
	_dnsm_present && return 0
	_doh_legacy_fix
	_doh_boot_fill
	mkdir "$lk" 2>/dev/null || { [ -n "$(find "$lk" -maxdepth 0 -mmin +5 2>/dev/null)" ] && rmdir "$lk" 2>/dev/null; return 0; }
	mode="$(_doh_st_get mode normal)"
	/etc/init.d/https-dns-proxy running >/dev/null 2>&1 && run=1
	cur="$(_doh_cur_id)"
	if [ -z "$cur" ]; then rmdir "$lk" 2>/dev/null; return 0; fi
	pref="$(_doh_fo_get pref "")"
	[ -n "$pref" ] && _doh_url_of "$pref" >/dev/null || { pref="$cur"; _doh_fo_put pref "$pref"; }
	t="$(_doh_fo_get active "")"
	if [ -n "$t" ] && [ "$t" != "$cur" ]; then pref="$cur"; _doh_fo_put pref "$cur"; rm -f "$DOH_FO_STATE"; mode=normal; fi
	_doh_fo_put active "$cur"
	if [ "$mode" = direct ]; then
		for c in "$pref" $([ "$(_doh_fo_get fo 0)" = 1 ] && _doh_fo_pool "$pref" ""); do
			_doh_bad_skip "$c" && continue
			_doh_ok "$c" || continue
			[ "$c" = "$cur" ] || _doh_apply "$c" >/dev/null 2>&1 || { _doh_bad_mark "$c"; continue; }
			_doh_bad_clear "$c"
			_doh_fo_put active "$c"
			/etc/init.d/https-dns-proxy start >/dev/null 2>&1
			t=0; while ! _doh_local_ok 5053 && [ "$t" -lt 8 ]; do sleep 1; t=$((t + 1)); done
			_doh_st_put mode "$([ "$c" = "$pref" ] && echo normal || echo backup)" fails 0 okc 0 since "$(date +%s)"
			_doh_fo_event "$(_doh_name "$c") отвечает — DNS снова идёт через DoH"
			break
		done
		rmdir "$lk" 2>/dev/null
		return 0
	fi
	if [ "$run" != 1 ]; then
		/etc/init.d/https-dns-proxy enabled >/dev/null 2>&1 || { rmdir "$lk" 2>/dev/null; return 0; }
		_zm_run 30 /etc/init.d/https-dns-proxy start >/dev/null 2>&1
		if _doh_wait_real 5053 10 && /etc/init.d/https-dns-proxy running >/dev/null 2>&1; then
			_doh_st_put fails 0
			_doh_fo_event "служба https-dns-proxy остановилась — запустили её снова, DNS идёт через $(_doh_name "$cur")"
			rmdir "$lk" 2>/dev/null
			return 0
		fi
	fi
	fails="$(_doh_st_get fails 0)"; okc="$(_doh_st_get okc 0)"
	if [ "$cur" != "$pref" ] && [ "$(_doh_fo_get fo 0)" = 1 ] && ! _doh_bad_skip "$pref"; then
		if _doh_ok "$pref"; then okc=$((okc + 1)); else okc=0; fi
		if [ "$okc" -ge 2 ]; then
			if _doh_apply "$pref" >/dev/null 2>&1; then
				_doh_fo_put active "$pref"
				_doh_st_put mode normal fails 0 okc 0 since "$(date +%s)"
				_doh_fo_event "$(_doh_name "$pref") снова отвечает — вернулись на него с $(_doh_name "$cur")"
				rmdir "$lk" 2>/dev/null
				return 0
			fi
			_doh_bad_mark "$pref"; okc=0
			_doh_fo_event "$(_doh_name "$pref") отвечает, но DNS роутера через него не заработал — остаёмся на $(_doh_name "$cur"), снова попробуем через $(( $(_doh_bad_wait "$pref") / 60 )) мин"
		fi
		_doh_st_put okc "$okc"
	fi
	since="$(_doh_st_get since 0)"; case "$since" in ''|*[!0-9]*) since=0 ;; esac
	if /etc/init.d/https-dns-proxy running >/dev/null 2>&1 && _doh_cur_alive "$cur" "$fails"; then
		_doh_st_put fails 0
		[ "$cur" = "$pref" ] && [ $(( $(date +%s) - since )) -ge 3600 ] && _doh_bad_clear "$pref"
		rmdir "$lk" 2>/dev/null
		return 0
	fi
	fails=$((fails + 1)); _doh_st_put fails "$fails"
	[ "$fails" -ge 2 ] || { rmdir "$lk" 2>/dev/null; return 0; }
	[ "$cur" = "$pref" ] && [ "$since" -gt 0 ] && [ $(( $(date +%s) - since )) -lt 1800 ] && flap=1
	if [ "$(_doh_fo_get fo 0)" = 1 ]; then
		for c in $([ "$cur" != "$pref" ] && echo "$pref") $(_doh_fo_pool "$pref" "$cur"); do
			_doh_bad_skip "$c" && continue
			_doh_ok "$c" || continue
			_doh_apply "$c" >/dev/null 2>&1 || { _doh_bad_mark "$c"; continue; }
			_doh_bad_clear "$c"
			_doh_fo_put active "$c"
			_doh_st_put mode "$([ "$c" = "$pref" ] && echo normal || echo backup)" fails 0 okc 0 since "$(date +%s)"
			if [ -n "$flap" ]; then
				_doh_bad_mark "$pref"
				_doh_fo_event "$(_doh_name "$cur") снова перестал отвечать вскоре после возврата — DNS переключён на $(_doh_name "$c"), к $(_doh_name "$pref") вернёмся не раньше чем через $(( $(_doh_bad_wait "$pref") / 60 )) мин"
			else
				_doh_fo_event "$(_doh_name "$cur") не отвечает — DNS переключён на $(_doh_name "$c")"
			fi
			rmdir "$lk" 2>/dev/null
			return 0
		done
	fi
	if [ "$(_doh_fo_get direct 0)" = 1 ]; then
		/etc/init.d/https-dns-proxy stop >/dev/null 2>&1
		/etc/init.d/dnsmasq restart >/dev/null 2>&1
		_doh_st_put mode direct fails 0 okc 0 since "$(date +%s)"
		_doh_fo_event "не отвечает ни один сервер — DNS временно идёт без DoH, через обычные серверы"
	elif [ "$fails" = 2 ]; then
		_doh_fo_event "$(_doh_name "$cur") не отвечает, запасные из цепочки тоже — DoH не выключаем, ждём, когда какой-нибудь ответит"
	fi
	rmdir "$lk" 2>/dev/null
	return 0
}
_doh_fo_cron() {
	local line="*/2 * * * * /opt/zapret-manager-luci/backend.sh doh_watch >/dev/null 2>&1 $DOH_FO_CRON"
	if [ "$1" = on ]; then
		grep -qxF "$line" "$CRON_FILE" 2>/dev/null && return 0
		mkdir -p "$(dirname "$CRON_FILE")"; touch "$CRON_FILE"
		grep -vF "$DOH_FO_CRON" "$CRON_FILE" > "$CRON_FILE.zm" 2>/dev/null; cat "$CRON_FILE.zm" > "$CRON_FILE"; rm -f "$CRON_FILE.zm"
		echo "$line" >> "$CRON_FILE"
	else
		grep -qF "$DOH_FO_CRON" "$CRON_FILE" 2>/dev/null || return 0
		grep -vF "$DOH_FO_CRON" "$CRON_FILE" > "$CRON_FILE.zm" 2>/dev/null; cat "$CRON_FILE.zm" > "$CRON_FILE"; rm -f "$CRON_FILE.zm"
	fi
	/etc/init.d/cron restart >/dev/null 2>&1
	return 0
}
_doh_fo_json() {
	local ev ch="" id sep="" pref
	pref="$(_doh_fo_get pref "")"; [ -n "$pref" ] || pref="$(_doh_cur_id)"
	for id in $(_doh_fo_chain "$pref"); do ch="$ch$sep\"$(esc "$id")\""; sep=","; done
	ev="$(awk -F'|' 'BEGIN { s = "" } NF >= 2 { m = $0; sub(/^[^|]*\|/, "", m); gsub(/["\\]/, "", m); printf "%s{\"at\":%d,\"text\":\"%s\"}", s, $1, m; s = "," }' "$DOH_FO_EVENTS" 2>/dev/null)"
	printf '{"fo":%s,"direct":%s,"pref":"%s","chain":[%s],"mode":"%s","since":%s,"fails":%s,"events":[%s]}' \
		"$([ "$(_doh_fo_get fo 0)" = 1 ] && echo true || echo false)" "$([ "$(_doh_fo_get direct 0)" = 1 ] && echo true || echo false)" \
		"$(esc "$(_doh_fo_get pref "")")" "$ch" \
		"$(esc "$(_doh_st_get mode normal)")" "$(_doh_st_get since 0)" "$(_doh_st_get fails 0 | tr -cd 0-9)" "$ev"
}
doh_failover_set() {
	local kv k v fo direct chain="" setch="" id n=0 pref bad=""
	_dnsm_guard || return 1
	fo="$(_doh_fo_get fo 0)"; direct="$(_doh_fo_get direct 0)"
	pref="$(_doh_fo_get pref "")"; [ -n "$pref" ] || pref="$(_doh_cur_id)"
	set -f
	for kv in $(printf '%s' "$1" | tr -c 'A-Za-z0-9._~%/+=&?:,-' ' '); do
		k="${kv%%=*}"; v="${kv#*=}"
		case "$k" in
			fo) [ "$v" = 1 ] && fo=1 || fo=0 ;;
			direct) [ "$v" = 1 ] && direct=1 || direct=0 ;;
			chain)
				setch=1
				for id in $(printf '%s' "$v" | tr ',' ' '); do
					_doh_url_of "$id" >/dev/null || { bad="$id"; continue; }
					[ "$id" = "$pref" ] && continue
					case ",$chain," in *",$id,"*) continue ;; esac
					[ "$n" -ge 3 ] && break
					chain="$chain${chain:+,}$id"; n=$((n + 1))
				done ;;
		esac
	done
	set +f
	[ -z "$bad" ] || { printf '{"error":"Адрес запасного сервера не подходит: %s"}\n' "$(esc "$bad")"; return 1; }
	_doh_fo_put fo "$fo"; _doh_fo_put direct "$direct"
	[ -n "$setch" ] && _doh_fo_put chain "$chain"
	[ -n "$(_doh_fo_get pref "")" ] || { v="$(_doh_cur_id)"; [ -n "$v" ] && _doh_fo_put pref "$v"; }
	if [ "$fo" = 1 ] || [ "$direct" = 1 ]; then _doh_fo_cron on
	else
		_doh_fo_cron off
		if [ "$(_doh_st_get mode normal)" = direct ] && [ ! -f "$DOH_STOP" ]; then
			/etc/init.d/https-dns-proxy start >/dev/null 2>&1
			_doh_fo_event "автопереключение выключено — DNS снова идёт через DoH"
		fi
		v="$(_doh_cur_id)"; pref="$(_doh_fo_get pref "")"
		if [ -n "$v" ] && [ -n "$pref" ] && [ "$v" != "$pref" ] && _doh_ok "$pref" && _doh_apply "$pref" >/dev/null 2>&1; then
			_doh_fo_put active "$pref"
			_doh_fo_event "автопереключение выключено — вернулись на основной $(_doh_name "$pref")"
		fi
		rm -f "$DOH_FO_STATE"
	fi
	_zo_doh_follow
	printf '%s\n' "$(_doh_fo_json)"
}

DOH_OWN_FILE="/opt/zapret-manager-luci/doh_own"
DOH_OWN_MAX=12
_doh_own_urls() { cut -f1 "$DOH_OWN_FILE" 2>/dev/null | grep '^https://'; }
_doh_own_has() { _doh_own_urls | grep -qxF "$1"; }
_doh_own_title() { [ -s "$DOH_OWN_FILE" ] && ZM_U="$1" awk -F'\t' '$1 == ENVIRON["ZM_U"] { print $2; exit }' "$DOH_OWN_FILE"; }
_doh_own_json() {
	[ -s "$DOH_OWN_FILE" ] || return 0
	awk -F'\t' '$1 ~ /^https:\/\// { n2 = $2; gsub(/["\\]/, "", n2); printf "%s{\"url\":\"%s\",\"name\":\"%s\"}", (n++ ? "," : ""), $1, n2 }' "$DOH_OWN_FILE"
}
_doh_own_put() {
	mkdir -p "$(dirname "$DOH_OWN_FILE")"
	touch "$DOH_OWN_FILE"
	ZM_U="$1" ZM_N="$2" awk -F'\t' 'BEGIN { OFS = "\t" } $1 == ENVIRON["ZM_U"] { print $1, ENVIRON["ZM_N"]; f = 1; next } NF { print } END { if (!f) print ENVIRON["ZM_U"], ENVIRON["ZM_N"] }' \
		"$DOH_OWN_FILE" > "$DOH_OWN_FILE.zm" && mv -f "$DOH_OWN_FILE.zm" "$DOH_OWN_FILE"
}
_doh_own_drop() {
	[ -f "$DOH_OWN_FILE" ] || return 0
	ZM_U="$1" awk -F'\t' '$1 != ENVIRON["ZM_U"] && NF' "$DOH_OWN_FILE" > "$DOH_OWN_FILE.zm" && mv -f "$DOH_OWN_FILE.zm" "$DOH_OWN_FILE"
	[ -s "$DOH_OWN_FILE" ] || rm -f "$DOH_OWN_FILE"
}
_doh_legacy_url() {
	case "$1" in
		comss_ru) echo "https://dns.comss.ru/dns-query	Comss RU" ;;
		mafioznik) echo "https://dns.mafioznik.com/dns-query	Mafioznik" ;;
		astracat) echo "https://dns.astrakat.ru/dns-query	AstraCat" ;;
		adguard) echo "https://unfiltered.adguard-dns.com/dns-query	AdGuard" ;;
	esac
}
_dns_preset_map() {
	case "$1" in
		https://dns.bezmezhau.com/*) echo "https://sync.bezmezhau.com/dns-query" ;;
		dns.bezmezhau.com) echo "sync.bezmezhau.com" ;;
		https://geohide.ru/*|https://dns.geohide.ru/*) echo "https://dns.comss.one/dns-query" ;;
		*) echo "$1" ;;
	esac
}
_doh_preset_migrate() {
	local i=0 url new id ch="" multi="" r
	[ -f "$_doh_file" ] && _doh_pkg || return 1
	_dnsm_present && return 1
	if [ -f "$DOH_FO_FILE" ] && grep -qE '^(pref|active|chain)=(.*,)?geohide_ru(,|$)' "$DOH_FO_FILE"; then
		sed -i -E '/^(pref|active|chain)=/ s#(=|,)geohide_ru(,|$)#\1comss\2#g' "$DOH_FO_FILE"
		r="$(_doh_fo_get chain "" | tr ',' '\n' | awk 'NF && !s[$0]++' | tr '\n' ',')"
		[ -n "$r" ] && _doh_fo_put chain "${r%,}"
		ch=1
	fi
	[ -n "$(uci -q get 'https-dns-proxy.@https-dns-proxy[1].resolver_url')" ] && multi=1
	while url="$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].resolver_url")"; do
		new="$(_dns_preset_map "$url")"
		if [ "$new" != "$url" ]; then
			id="$(_doh_provider_of "$new")"
			if [ -z "$multi" ]; then
				if r="$(_doh_apply "$id")"; then
					_doh_fo_put pref "$id"; _doh_fo_put active "$id"
					logger -t zapret-manager "DoH: $(printf '%s' "$url" | sed 's#^https://\([^/]*\).*#\1#') больше не работает — DNS переведён на $(_doh_name "$id")"
					ch=1
				fi
				break
			fi
			uci -q set "https-dns-proxy.@https-dns-proxy[$i].resolver_url=$new"
			ch=2
		fi
		i=$((i + 1)); [ "$i" -gt 16 ] && break
	done
	if [ "$ch" = 2 ]; then
		uci -q commit https-dns-proxy
		[ -f "$DOH_STOP" ] || /etc/init.d/https-dns-proxy restart >/dev/null 2>&1
		logger -t zapret-manager "DoH: адреса Bezmezhau и GeoHide RU обновлены"
	fi
	[ -n "$ch" ]
}
_fk_dns_migrate() {
	local l v n="" ch="" cur
	[ -f /etc/config/netshift ] || return 1
	l="$(uci -q get netshift.settings.zm_dns_servers)"
	for v in $l; do
		v="$(_dns_preset_map "$v")"
		case " $n " in *" $v "*) continue ;; esac
		n="${n:+$n }$v"
	done
	if [ "$n" != "$l" ]; then
		uci -q delete netshift.settings.zm_dns_servers
		for v in $n; do uci -q add_list "netshift.settings.zm_dns_servers=$v"; done
		ch=1
	fi
	cur="$(uci -q get netshift.settings.dns_server)"
	v="$(_dns_preset_map "$cur")"
	[ "$v" != "$cur" ] && { uci -q set "netshift.settings.dns_server=$v"; ch=1; }
	case "$(uci -q get netshift.settings.dns_type):$n" in
		doh:https://dns.comss.one/dns-query|dot:dns.comss.one)
			l="$(uci -q get netshift.settings.zm_bootstrap | tr ' ' '\n' | sort | tr '\n' ' ')"
			if [ "$l" = "212.109.195.93 94.250.253.55 " ]; then
				uci -q delete netshift.settings.zm_bootstrap
				uci -q add_list netshift.settings.zm_bootstrap=77.88.8.8
				uci -q add_list netshift.settings.zm_bootstrap=9.9.9.9
				uci -q set netshift.settings.bootstrap_dns_server=77.88.8.8
				ch=1
			fi ;;
	esac
	[ -n "$ch" ] || return 1
	uci -q commit netshift
	logger -t zapret-manager "$(_fk_name): адреса DNS Comss, Bezmezhau и GeoHide RU обновлены"
	return 0
}
_hosts_geo_migrate() {
	grep -q '^### geohide.ru: hosts file' "$HOSTS_FILE" 2>/dev/null || return 1
	grep -q '^# Регион серверов: RU$' "$HOSTS_FILE" 2>/dev/null || return 1
	case "$(hosts_replace_geohide eu 2>/dev/null)" in
		*'"ok":true'*) logger -t zapret-manager "Hosts: GeoHide RU больше не работает — список заменён на GeoHide EU"; return 0 ;;
	esac
	logger -t zapret-manager "Hosts: GeoHide RU больше не работает, а GeoHide EU не скачался — выберите другой список в разделе Hosts"
	return 1
}
dns_presets_migrate() {
	local d=false f=false h=false
	_hosts_geo_migrate && h=true
	_doh_preset_migrate && d=true
	if _fk_dns_migrate; then
		f=true
		_fk_enabled && _fk_up && ! _job_running forkop && job_start forkop do_fk_service apply >/dev/null 2>&1
	fi
	printf '{"doh":%s,"forkozz":%s,"hosts":%s}\n' "$d" "$f" "$h"
}
_doh_legacy_fix() {
	local id l u cur
	cur="$(uci -q get 'https-dns-proxy.@https-dns-proxy[0].resolver_url')"
	case "$cur" in https://dns.bezmezhau.com/*|https://geohide.ru/*|https://dns.geohide.ru/*) _doh_preset_migrate >/dev/null 2>&1; cur="$(uci -q get 'https-dns-proxy.@https-dns-proxy[0].resolver_url')" ;; esac
	case "$cur" in https://dns.comss.ru/*|https://dns.mafioznik.com/*|https://dns.astrakat.ru/*|https://unfiltered.adguard-dns.com/*) ;;
		*) grep -qE '^(pref|active|chain)=(.*,)?(comss_ru|mafioznik|astracat|adguard)(,|$)' "$DOH_FO_FILE" 2>/dev/null || return 0 ;;
	esac
	for id in comss_ru mafioznik astracat adguard; do
		l="$(_doh_legacy_url "$id")"; u="${l%%	*}"
		if grep -qE "^(pref|active|chain)=(.*,)?$id(,|\$)" "$DOH_FO_FILE" 2>/dev/null; then
			sed -i -E "/^(pref|active|chain)=/ s#(=|,)$id(,|\$)#\1$u\2#g" "$DOH_FO_FILE"
		elif [ "$cur" != "$u" ]; then
			continue
		fi
		_doh_own_has "$u" || _doh_own_put "$u" "${l#*	}"
	done
	return 0
}
doh_own_set() {
	local act rest url name cur pref ch
	_dnsm_guard || return 1
	_doh_legacy_fix
	act="${1%% *}"; rest="${1#"$act"}"; rest="${rest# }"
	url="${rest%% *}"; name="${rest#"$url"}"
	name="$(printf '%s' "$name" | tr -d '\000-\037\177"\\<>' | sed 's/[[:space:]][[:space:]]*/ /g; s/^ //; s/ $//')"
	case "$act" in
		add)
			case "$url" in https://*) ;; *) url="" ;; esac
			[ -n "$url" ] && _doh_url_of "$url" >/dev/null || { echo '{"error":"Адрес не подходит — нужна ссылка вида https://dns.example.com/dns-query"}'; return 1; }
			[ -z "$(_doh_provider_of "$url")" ] || { printf '{"error":"Этот сервер уже есть в списке — %s"}\n' "$(esc "$(_doh_name "$(_doh_provider_of "$url")")")"; return 1; }
			[ "${#name}" -le 96 ] || { echo '{"error":"Название слишком длинное — не больше 32 букв"}'; return 1; }
			if ! _doh_own_has "$url" && [ "$(_doh_own_urls | wc -l)" -ge "$DOH_OWN_MAX" ]; then
				printf '{"error":"В списке «Свои» уже %s серверов — уберите ненужный"}\n' "$DOH_OWN_MAX"; return 1
			fi
			_doh_own_put "$url" "$name" ;;
		del)
			case "$url" in https://*) ;; *) echo '{"error":"Нет такого сервера"}'; return 1 ;; esac
			cur="$(_doh_cur_id)"
			[ "$cur" != "$url" ] || { echo '{"error":"Сейчас DNS идёт через этот сервер — сначала выберите другой"}'; return 1; }
			pref="$(_doh_fo_get pref "")"
			if [ "$pref" = "$url" ] && _doh_fo_on; then
				echo '{"error":"Это основной сервер цепочки «Если сервер перестал отвечать» — сначала выберите другой"}'; return 1
			fi
			_doh_own_drop "$url"
			if grep -q '^chain=' "$DOH_FO_FILE" 2>/dev/null; then
				ch="$(_doh_fo_get chain "" | tr ',' '\n' | grep -vxF "$url" | grep . | tr '\n' ',')"
				_doh_fo_put chain "${ch%,}"
			fi
			_zo_doh_follow ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
	printf '{"ok":true,"own":[%s],"failover":%s}\n' "$(_doh_own_json)" "$(_doh_fo_json)"
}

DN_FILE="/opt/zapret-manager-luci/dns_net"
DN_OWN="/opt/zapret-manager-luci/dns_net.owned"
DN_CANARY="use-application-dns.net mask.icloud.com mask-h2.icloud.com"
DN_RU_ZONES="ru su xn--p1ai"
DN_YANDEX="77.88.8.8 77.88.8.1"
_dn_get() { local v; v="$(_kv_last "$DN_FILE" "$1")"; echo "${v:-$2}"; }
_dn_put() {
	mkdir -p "$(dirname "$DN_FILE")"
	{ grep -v "^$1=" "$DN_FILE" 2>/dev/null; echo "$1=$2"; } > "$DN_FILE.zm.$$" && mv -f "$DN_FILE.zm.$$" "$DN_FILE"
}
_dn_secs() { uci -q -X show dhcp 2>/dev/null | sed -n "s/^dhcp\.\([A-Za-z0-9_]*\)=dnsmasq\$/\1/p"; }
_dn_isp() {
	local f
	for f in /tmp/resolv.conf.d/resolv.conf.auto /tmp/resolv.conf.auto; do
		[ -s "$f" ] || continue
		awk '$1 == "nameserver" && ($2 ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/ || ($2 ~ /^[0-9A-Fa-f:]+$/ && $2 ~ /:.*:/)) && $2 !~ /^(127\.|0\.0\.0\.0$|::1$|[Ff][Ee]80:)/ && !u[$2]++ { print $2 }' "$f" | head -n 4 | tr '\n' ',' | sed 's/,$//'
		return 0
	done
}
_dn_ru_ips() {
	case "$(_dn_get ru off)" in
		yandex) echo "$DN_YANDEX" ;;
		isp) _dn_get ispips "" | tr ',' ' ' ;;
	esac
}
_dn_has() { uci -q get "dhcp.$1.$2" 2>/dev/null | tr ' ' '\n' | grep -qxF "$3"; }
_dn_add() {
	_dn_has "$1" "$2" "$3" && return 0
	uci -q add_list "dhcp.$1.$2=$3" && echo "$1 $2 $3" >> "$DN_OWN"
}
_dn_drop() {
	local sec opt val keep="$DN_OWN.keep"
	[ -s "$DN_OWN" ] || { rm -f "$DN_OWN"; return 0; }
	: > "$keep"
	while read -r sec opt val; do
		[ -n "$val" ] || continue
		if [ "$1" = all ] || { [ "$1" = canary ] && [ "$opt" = address ]; } || { [ "$1" = ru ] && [ "$opt" = server ]; }; then
			uci -q del_list "dhcp.$sec.$opt=$val"
		else
			echo "$sec $opt $val" >> "$keep"
		fi
	done < "$DN_OWN"
	if [ -s "$keep" ]; then mv -f "$keep" "$DN_OWN"; else rm -f "$keep" "$DN_OWN"; fi
}
_dn_snap() { uci -q -X show dhcp 2>/dev/null | grep -E '^dhcp\.[^.]*\.(address|server)='; }
_dn_apply() {
	local before sec d ip ips
	before="$(_dn_snap)"
	_dn_drop all
	ips="$(_dn_ru_ips)"
	for sec in $(_dn_secs); do
		if [ "$(_dn_get canary 0)" = 1 ]; then
			for d in $DN_CANARY; do _dn_add "$sec" address "/$d/"; done
		fi
		for d in $DN_RU_ZONES; do
			for ip in $ips; do _dn_add "$sec" server "/$d/$ip"; done
		done
	done
	[ "$before" = "$(_dn_snap)" ] && { uci -q commit dhcp; return 0; }
	uci -q commit dhcp
	[ "$1" = norestart ] || /etc/init.d/dnsmasq restart >/dev/null 2>&1
	return 0
}
_dn_json() {
	local doh=false
	uci -q -X show dhcp 2>/dev/null | grep -E '^dhcp\.[^.]*\.server=' | grep -qF "'/use-application-dns.net/'" && doh=true
	printf '{"canary":%s,"canary_doh":%s,"ru":"%s","ru_ips":"%s","isp":"%s"}' \
		"$([ "$(_dn_get canary 0)" = 1 ] && echo true || echo false)" "$doh" "$(esc "$(_dn_get ru off)")" \
		"$(esc "$(_dn_ru_ips | tr ' ' ',')")" "$(esc "$(_dn_isp)")"
}
dns_net_set() {
	local kv k v canary ru ips
	_dnsm_guard || return 1
	canary="$(_dn_get canary 0)"; ru="$(_dn_get ru off)"
	for kv in $(printf '%s' "$1" | tr -c 'A-Za-z0-9=_-' ' '); do
		k="${kv%%=*}"; v="${kv#*=}"
		case "$k" in
			canary) if [ "$v" = 1 ]; then canary=1; else canary=0; fi ;;
			ru) case "$v" in off|yandex|isp) ru="$v" ;; *) echo '{"error":"неизвестный режим для российских сайтов"}'; return 1 ;; esac ;;
		esac
	done
	if [ "$ru" != off ] && [ "$ru" != "$(_dn_get ru off)" ] && _fk_installed; then
		printf '{"error":"Стоит %s — он сам решает, куда идут запросы DNS. Российские сайты оставлены как есть"}\n' "$(_fk_name)"
		return 1
	fi
	if [ "$ru" = isp ]; then
		ips="$(_dn_isp)"
		[ -n "$ips" ] || { echo '{"error":"Провайдер не выдал роутеру адреса DNS — выберите Яндекс DNS"}'; return 1; }
		_dn_put ispips "$ips"
	fi
	_dn_put canary "$canary"
	_dn_put ru "$ru"
	_dn_apply
	printf '{"ok":true,"net":%s}\n' "$(_dn_json)"
}
_dn_watch() {
	local now
	[ "$(_dn_get ru off)" = isp ] || return 0
	_dnsm_present && return 0
	now="$(_dn_isp)"
	[ -n "$now" ] && [ "$now" != "$(_dn_get ispips "")" ] || return 0
	_dn_put ispips "$now"
	_dn_apply
	logger -t zapret-manager "Российские сайты: DNS провайдера сменился — теперь $(printf '%s' "$now" | sed 's/,/, /g')"
}
dns_net_gone() {
	[ -s "$DN_OWN" ] || { rm -f "$DN_FILE" "$DN_OWN"; return 0; }
	_dn_drop all
	uci -q commit dhcp
	rm -f "$DN_FILE" "$DN_OWN"
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	return 0
}

