_rb_list_src() {
	case "$1" in
		svc_youtube.lst) echo "$ZM_LISTS_ITD/Services/youtube.lst" ;;
		svc_telegram.lst) echo "$ZM_LISTS_ITD/Services/telegram.lst" ;;
