_stl_say() { echo "==> $*"; }
_st_onfail() { [ "$(cat /etc/zm-steer/onfail 2>/dev/null)" = drop ] && echo drop || echo direct; }
_st_dnsmode() { [ "$(cat /etc/zm-steer/dns.mode 2>/dev/null)" = router ] && echo router || echo tun; }
_st_realip() { [ "$(cat /etc/zm-steer/realip.mode 2>/dev/null)" = off ] && echo off || echo on; }
_st_cttl() { local v; v="$(cat /etc/zm-steer/dns.ttlmin 2>/dev/null)"; case "$v" in 300|900|3600) echo "$v" ;; *) echo 0 ;; esac; }
_st_dnsopt_save() {
	mkdir -p /etc/zm-steer
	rm -f /etc/zm-steer/realip
	case "$1" in
		cttl) if [ "$2" = 0 ]; then rm -f /etc/zm-steer/dns.ttlmin; else echo "$2" > /etc/zm-steer/dns.ttlmin; fi ;;
		dnsmode) if [ "$2" = router ]; then echo router > /etc/zm-steer/dns.mode; else rm -f /etc/zm-steer/dns.mode; fi ;;
		realip) if [ "$2" = off ]; then echo off > /etc/zm-steer/realip.mode; else rm -f /etc/zm-steer/realip.mode; fi ;;
	esac
}
_stl_t() { _zm_tmo "$@"; }
_stl_out() { case "$1" in vpn) echo "$STL_VPN_OUT" ;; iface) echo "zm_if${ST_SEC#s}" ;; *) echo "$STL_WARP_OUT" ;; esac; }
_stl_js() { printf '"%s"' "$(esc "$1")"; }
_stl_ident() {
	local n
	n="$(printf '%s' "$1" | tr -c 'A-Za-z0-9_.-' '_')"
	case "$n" in ''|all|lan|[-.]*) n="z$n" ;; esac
	[ "${#n}" -le 31 ] || n="$(printf '%s' "$n" | cut -c1-26)-$(printf '%s' "$1" | md5sum | cut -c1-4)"
	printf '%s' "$n"
}
_stl_label() {
	local n
	n="$(printf '%s' "$1" | tr -d '"\\\000-\037')"
	[ -n "$n" ] && [ "$(printf '%s' "$n" | wc -c)" -le 31 ] && { printf '%s' "$n"; return; }
	_stl_ident "$2"
}
_stl_ver_ok() { _zm_re "$1" '^[0-9]+\.[0-9]+\.[0-9]+$' && [ "${1%%.*}" -ge 2 ]; }

stl_present() { command -v steer >/dev/null 2>&1; }
stl_version() { steer --version 2>/dev/null | awk 'NR == 1 { print $2 }'; }
stl_v2() { _stl_ver_ok "$(stl_version)"; }
stl_has() {
	stl_v2 || return 1
	case "$1" in
		vpn|vless) [ -x "$STL_SBIN/steer-vless" ] ;;
		hy2|hysteria2) [ -x "$STL_SBIN/steer-hysteria2" ] ;;
		proxy) [ -x "$STL_SBIN/steer-proxy" ] ;;
		*) return 1 ;;
	esac
}
stl_busy_by() {
	local i=/etc/init.d/sing-box b by=""
	grep -q steer-box-connector "$i" 2>/dev/null || return 1
	for b in podkop; do [ -e "${i%/*}/$b" ] && by="${by:+$by, }$b"; done
	echo "${by:-steer-box-connector}"
}
_stl_mods_present() { local m; for m in $STL_MODS; do [ -x "$STL_SBIN/steer-$m" ] && printf '%s ' "$m"; done; }

_stl_rel() {
	local f="$STL_TMP/version.json" u
	mkdir -p "$STL_TMP"
	[ -s "$f" ] && [ -z "$(find "$f" -mmin +60 2>/dev/null)" ] && { echo "$f"; return 0; }
	for u in $STL_REL_URLS; do
		_zm_fetch "$u" "$f.tmp" 20 || continue
		[ "$(jsonfilter -i "$f.tmp" -e '@.schema' 2>/dev/null)" = 1 ] || continue
		mv -f "$f.tmp" "$f"; echo "$f"; return 0
	done
	rm -f "$f.tmp"
	[ -s "$f" ] && { echo "$f"; return 0; }
	return 1
}

stl_latest() {
	local v="" f u
	if [ -z "$ZM_VER_FORCE" ] && [ -s "$STL_CACHE" ] && [ -z "$(find "$STL_CACHE" -mmin +360 2>/dev/null)" ]; then cat "$STL_CACHE"; return 0; fi
	f="$(_stl_rel)" && v="$(jsonfilter -i "$f" -e '@.products.steer.stable' 2>/dev/null)"
	if ! _stl_ver_ok "$v"; then
		for u in $STL_PKG_URLS; do
			case "$u" in *@V@*) continue ;; esac
			v="$(curl -fsSL --connect-timeout 6 --max-time 12 "$u/VERSION" 2>/dev/null | tr -d '[:space:]')"
			_stl_ver_ok "$v" && break
			v=""
		done
	fi
	if _stl_ver_ok "$v"; then
		mkdir -p "$(dirname "$STL_CACHE")"; echo "$v" > "$STL_CACHE"; echo "$v"
	elif [ -s "$STL_CACHE" ]; then cat "$STL_CACHE"
	else echo "$STL_MIN"; fi
}

_stl_fetch() {
	local ver="$1" file="$2" out="$3" f sum="" u urls=""
	if f="$(_stl_rel)"; then
		urls="$(jsonfilter -i "$f" -e "@.products.steer.versions[@.version='$ver'].assets[@.name='$file'].urls[*]" 2>/dev/null | grep -E '^https://[A-Za-z0-9._~:/%+@=-]+$')"
		sum="$(jsonfilter -i "$f" -e "@.products.steer.versions[@.version='$ver'].assets[@.name='$file'].sha256" 2>/dev/null)"
	fi
	for u in $urls $(echo "$STL_PKG_URLS" | sed "s/@V@/$ver/g"); do
		case "$u" in */"$file") ;; *) u="$u/$file" ;; esac
		_rb_fetch_pkg "$u" "$out" >&2 || continue
		[ -z "$sum" ] || [ "$(sha256sum "$out" | cut -d' ' -f1)" = "$sum" ] && return 0
		echo "   у файла не та контрольная сумма: $u" >&2
		rm -f "$out"
	done
	return 1
}

stl_engine_install() {
	local ver="$1" arch m p n f mods="" pkgs files="" old="" back="" legacy="" keep="$STL_TMP/spec.keep" was_on="" rc
	shift
	_stl_ver_ok "$ver" || { echo "ОШИБКА: версия ядра steer $ver — нужна 2.0.0 или новее"; return 1; }
	arch="$(_rb_arch)"
	[ -n "$arch" ] || { echo "ОШИБКА: не удалось определить архитектуру роутера"; return 1; }
	for m in "$@"; do case "$m" in vpn) mods="$mods vless" ;; hy2) mods="$mods hysteria2" ;; proxy) mods="$mods proxy" ;; esac; done
	if stl_present && ! stl_v2; then
		for n in steer steer-extended libsteer libsteer-wolfssl; do _pkg_is_installed "$n" && legacy="$legacy $n"; done
		case " $legacy " in *" steer-extended "*) mods="$mods vless" ;; esac
	fi
	mods="$(for m in $mods $(_stl_mods_present); do echo "$m"; done | awk '!s[$0]++' | tr '\n' ' ')"
	pkgs="steer-core$(for m in $mods; do printf ' steer-%s' "$m"; done)"
	stl_v2 && _pkg_is_installed steer-extended && pkgs="$pkgs steer-extended"
	if [ -n "$STL_MODS_ONLY" ] && stl_v2 && [ "$(stl_version)" = "$ver" ]; then
		pkgs="$(for p in $pkgs; do _pkg_is_installed "$p" || printf '%s ' "$p"; done)"
		pkgs="$(echo $pkgs)"
		[ -n "$pkgs" ] || { _stl_say "Нужные модули ядра steer уже стоят"; STL_NEW=""; STL_PKGS=""; return 0; }
	fi
	STL_NEW=""; STL_PKGS="$pkgs"
	for p in $pkgs; do _pkg_is_installed "$p" || STL_NEW="$STL_NEW $p"; done
	mkdir -p "$STL_TMP"
	local pa a
	for p in $pkgs; do
		pa=""
		for a in $(_zm_arch_alts "$arch"); do
			f="$STL_TMP/$p-$ver-1_$a.$RAZ"
			_stl_fetch "$ver" "$p-$ver-1_$a.$RAZ" "$f" && { pa="$a"; break; }
		done
		[ -n "$pa" ] || { rm -f $files; echo "ОШИБКА: не скачался пакет $p $ver для $arch"; return 1; }
		if [ "$pa" != "$arch" ]; then
			_stl_say "Сборки $p для $arch нет — берём совместимую $pa"
			_zm_arch_accept "$pa"
		fi
		files="$files $f"
	done
	stl_enabled && was_on=1
	case " $pkgs " in *" steer-core "*) _stl_say "Ставим ядро steer $ver: $(echo $pkgs | sed 's/ /, /g')" ;; *) _stl_say "Ставим к ядру steer $ver: $(echo $pkgs | sed 's/ /, /g')" ;; esac
	$UPDATE >&2
	[ -s "$STL_SPEC" ] && cp -f "$STL_SPEC" "$keep"
	if [ -n "$STL_REINSTALL" ] && [ -z "$legacy" ]; then
		"$STL_INIT" stop >/dev/null 2>&1
		if [ "$PKG" = apk ]; then
			n=""; for p in $pkgs; do _pkg_is_installed "$p" && n="$n $p"; done
			[ -n "$n" ] && $DELETE $n >&2
			$INSTALL $files >&2; rc=$?
			[ "$rc" = 0 ] || { $INSTALL $files >&2; rc=$?; }
		else
			$INSTALL --force-reinstall $files >&2; rc=$?
		fi
	elif [ "$PKG" = apk ]; then
		for n in $legacy; do if [ "$n" = steer ]; then apk add steer >/dev/null 2>&1; else old="$old !$n"; fi; done
		$INSTALL $files $old >&2; rc=$?
		[ "$rc" = 0 ] && for n in $legacy; do apk del "$n" >/dev/null 2>&1; done
	else
		if [ -n "$legacy" ]; then
			old="$(stl_version)"; back=""
			for n in $legacy; do
				f="$STL_TMP/$n-$old-1_$arch.$RAZ"
				_pkg_is_installed "$n" && case "$n" in steer|steer-extended) _stl_fetch "$old" "$n-$old-1_$arch.$RAZ" "$f" && back="$back $f" ;; esac
			done
			if [ -z "$back" ]; then
				rm -f $files "$keep"
				echo "ОШИБКА: не скачался пакет прежнего ядра steer $old для возврата — прежнее ядро оставлено"
				return 1
			fi
			_stl_say "Снимаем прежнее ядро steer $old — оно мешает новому"
			"$STL_INIT" stop >/dev/null 2>&1
			$DELETE $legacy >&2
		fi
		$INSTALL $files >&2; rc=$?
		if [ "$rc" != 0 ] && [ -n "$legacy" ]; then
			_stl_say "Новое ядро не встало — возвращаем прежнее ядро steer $old"
			$INSTALL $back >&2
		fi
		[ -n "$legacy" ] && rm -f $back
	fi
	rm -f $files
	[ -s "$keep" ] && [ ! -s "$STL_SPEC" ] && { mkdir -p "$STL_ETC"; cp -f "$keep" "$STL_SPEC"; }
	rm -f "$keep"
	if [ "$rc" != 0 ] || ! stl_v2; then
		[ -n "$legacy" ] && ! stl_present && echo "!! Прежнее ядро steer снято, а новое не встало — нажмите установку ещё раз, когда появится интернет"
		[ -n "$was_on" ] && stl_present && stl_restart >/dev/null 2>&1
		echo "ОШИБКА: ядро steer $ver не установилось"
		return 1
	fi
	if [ -n "$was_on" ]; then stl_restart >/dev/null 2>&1; else stl_stop; fi
	_stl_say "Ядро steer $(stl_version) установлено$( [ -n "$mods" ] && printf ', модули: %s' "$(echo $mods | sed 's/ /, /g')")"
	return 0
}

stl_engine_remove() {
	local p mods="" core=""
	stl_stop
	for p in "$@"; do case "$p" in steer-core|steer|steer-extended|libsteer|libsteer-wolfssl) core="$core $p" ;; *) mods="$mods $p" ;; esac; done
	[ -n "$mods$core" ] || return 0
	_stl_say "Удаляем ядро steer"
	local rc=0
	[ -n "$mods" ] && { _zm_pkg_wipe $mods >&2 || rc=1; }
	[ -n "$core" ] && { _zm_pkg_wipe $core >&2 || rc=1; }
	return $rc
}

stl_pkgs_installed() {
	local p m
	for p in $(for m in $STL_MODS; do echo "steer-$m"; done) steer-extended steer-core steer libsteer libsteer-wolfssl; do
		_pkg_is_installed "$p" && printf '%s ' "$p"
	done
}

stl_leftovers() {
	stl_present && return 0
	local t m n=0
	for t in "inet steer" "ip steer" "ip6 steer" "inet steer_obfs"; do nft delete table $t >/dev/null 2>&1 && n=$((n + 1)); done
	for t in $(awk '{print $3}' "$STL_STATE/registry" 2>/dev/null); do ip route flush table "$t" >/dev/null 2>&1; done
	for m in $(awk '{print $2}' "$STL_STATE/registry" 2>/dev/null); do
		while ip rule del fwmark "0x$m/0x0ff00000" >/dev/null 2>&1; do n=$((n + 1)); done
		while ip rule del fwmark "0x$m" >/dev/null 2>&1; do n=$((n + 1)); done
	done
	killall steerd >/dev/null 2>&1
	rm -rf "$STL_STATE"
	rm -f "$STL_SOCK"
	rmdir "$STL_ETC" 2>/dev/null
	[ "$n" -gt 0 ] && echo "   ✓ Убраны оставшиеся правила ядра steer: $n"
	return 0
}

stl_spec_whose() {
	[ -s "$STL_YAML" ] && { echo foreign; return; }
	[ -s "$STL_SPEC" ] || { echo none; return; }
	grep -qE '"(zm_(warp[0-9]*|vpn[0-9]*|if[0-9]*|direct)|zmv[0-9]*_[A-Za-z0-9]+)"' "$STL_SPEC" && { echo zm; return; }
	tr '\n\r' '  ' < "$STL_SPEC" | grep -q '"\(channels\|rules\)"[[:space:]]*:[[:space:]]*\[[[:space:]]*{' && { echo foreign; return; }
	echo none
}
stl_spec_restore() { if [ -s "$STL_KEEP" ]; then mv -f "$STL_KEEP" "$STL_SPEC"; else rm -f "$STL_SPEC"; fi; }
stl_rules() { grep -o '"out":' "$STL_SPEC" 2>/dev/null | wc -l | tr -d ' '; }

_stl_rule() {
	[ -n "$lid" ] && [ -n "$srs$dom$pfx" ] && [ -n "$out" ] || return 0
	body=""
	[ -n "$srs" ] && body="\"srs\":[$srs]"
	[ -n "$dom" ] && body="$body${body:+,}\"domains_file\":[$dom]"
	[ -n "$pfx" ] && body="$body${body:+,}\"prefixes_file\":[$pfx]"
	lists="$lists${lists:+,}$(_stl_js "$lid"):{$body}"
	x=""
	[ "$(_st_realip)" = on ] && x=',"resolve":"realip"'
	[ -z "$ZM_STL_NODNS" ] && [ "$(_st_dnsmode)" = tun ] && { x="$x,\"dns\":\"zm_tun$dnt\""; _stl_dns_need "$dnt" "$out"; }
	local r="" top=""
	[ -n "$cu" ] && [ -z "$ZM_STL_NOFAM" ] && { top=1; x="$x,\"family\":\"4\""; }
	if [ -n "$sfm$sfa" ]; then
		[ -n "$sfm" ] && r="{\"name\":$(_stl_js "$(_stl_ident "${lid}~m")"),\"for\":[$sfm],\"to\":$(_stl_js "$lid"),\"out\":\"$out\"$x}"
		[ -n "$sfa" ] && r="$r${r:+,}{\"name\":$(_stl_js "$(_stl_ident "${lid}~a")"),\"for\":[$sfa],\"to\":$(_stl_js "$lid"),\"out\":\"$out\"$x}"
	else
		r="{\"name\":$(_stl_js "$lab"),\"to\":$(_stl_js "$lid"),\"out\":\"$out\"$x}"
	fi
	if [ -n "$top" ]; then crules="$crules${crules:+,}$r"; else rules="$rules${rules:+,}$r"; fi
}
_stl_dns_need() { case " $dnsn " in *" $1:$2 "*) ;; *) dnsn="$dnsn $1:$2" ;; esac; }

_stl_tun_json() {
	local o m n
	o="$(_stl_js "$1"):{\"kind\":\"tunnel\",\"protocol\":\"$2\",\"device\":\"$6\",\"subscription\":$(_stl_js "$3")"
	n="$(printf '%s' "$4" | tr -cd '0-9,' | sed 's/,,*/,/g; s/^,//; s/,$//')"
	[ "$4" != - ] && [ -n "$n" ] && o="$o,\"nodes\":[$n]"
	m=""; [ "$5" = - ] || m="$(printf '%s' "$5" | tr '|,' '\n\n' | sed 's/^[[:space:]]*//; s/[[:space:]]*$//' | grep . | awk '!s[tolower($0)]++' | while IFS= read -r n; do printf ',%s' "$(_stl_js "$n")"; done | sed 's/^,//')"
	[ -n "$m" ] && o="$o,\"exclude_name\":[$m]"
	printf '%s' "$o"
}
_stl_vpn_outs() {
	local tab k p b c d n o="" m=""
	tab="$(printf '\t')"
	n="$(grep -c "^tun$tab" "$1")"
	while IFS="$tab" read -r k p b c; do
		[ "$k" = tun ] || continue
		case " $STL_VPN_PROTOS " in *" $p "*) ;; *) continue ;; esac
		if [ "$n" -le 1 ]; then
			o="$(_stl_tun_json "$STL_VPN_OUT" "$p" "$2" "$b" "$c" "$STL_VPN_DEV"),\"on_fail\":\"$(_st_onfail)\"}"
		else
			d="$(_stl_member "$p")"
			o="$o,$(_stl_tun_json "$d" "$p" "$2" "$b" "$c" "$d")}"
			m="$m${m:+,}\"$d\""
		fi
	done < "$1"
	[ "$n" -le 1 ] || o="\"$STL_VPN_OUT\":{\"kind\":\"group\",\"pick\":\"order\",\"members\":[$m],\"ipv6\":\"off\",\"on_fail\":\"$(_st_onfail)\"}$o"
	printf '%s' "$o"
}
_stl_sec_vpn_outs() {
	local t="$STL_TMP/secvpn.$$" r
	awk -F'\t' -v s="$2" 'BEGIN { OFS = "\t" } $1 == "stun" && $2 == s { $1 = "tun"; $2 = ""; sub(/^tun\t\t/, "tun\t"); print }' "$1" > "$t"
	r="$(STL_VPN_OUT="zm_vpn${2#s}"; STL_VPN_DEV="zm_vpn${2#s}"; STL_VPN_PFX="zmv${2#s}"; _stl_vpn_outs "$t" "$3")"
	rm -f "$t"
	printf '%s' "$r"
}
_stl_client() {
	STL_CID="$(_stl_ident "d_$1")"
	case "$clients" in *"\"$STL_CID\":"*) ;; *)
		case "$1" in *:*) clients="$clients${clients:+,}\"$STL_CID\":{\"mac\":[$(_stl_js "$1")]}" ;; *) clients="$clients${clients:+,}\"$STL_CID\":{\"addr\":[$(_stl_js "$1")]}" ;; esac ;;
	esac
}

_stl_spec() {
	local tab k a b c d m lists="" rules="" outs="" lan="" lid="" lab="" srs="" dom="" pfx=""
	local clients="" drules="" cid dout byp="" xd="" xp="" xc="" xr="" x="" dnsj="" dnsn="" dnt=""
	local body wp=latency main="" mout="" out="" sec="" sfm="" sfa="" so="" t u dvs="" STL_CID="" mf="$1" mif="" cu="" crules=""
	tab="$(printf '\t')"
	mkdir -p "$STL_TMP"
	while IFS="$tab" read -r k a b c; do
		case "$k" in
			main) main="$a" ;;
			mif) mif="$a" ;;
			vpn) [ -n "$main" ] || main=vpn ;;
			wpick) [ "$a" = order ] && wp=order ;;
		esac
	done < "$mf"
	[ -n "$main" ] || main=warp
	case "$main" in vpn) mout="$STL_VPN_OUT" ;; warp) mout="$STL_WARP_OUT" ;; iface) mout="zm_if" ;; *) mout="" ;; esac
	if [ "$main" = iface ]; then
		if printf '%s' "$mif" | grep -qE '^[A-Za-z0-9_.-]{1,15}$'; then outs="\"zm_if\":{\"kind\":\"interface\",\"device\":$(_stl_js "$mif"),\"ipv6\":\"off\",\"on_fail\":\"$(_st_onfail)\"}"
		else mout=""; fi
	fi
	while IFS="$tab" read -r k a b c; do
		case "$k" in
			so)
				case "$b" in
					vpn) t="$(_stl_sec_vpn_outs "$mf" "$a" "$c")"; [ -n "$t" ] && { outs="$outs${outs:+,}$t"; so="$so $a:zm_vpn${a#s}"; } ;;
					iface)
						printf '%s' "$c" | grep -qE '^[A-Za-z0-9_.-]{1,15}$' || continue
						outs="$outs${outs:+,}\"zm_if${a#s}\":{\"kind\":\"interface\",\"device\":$(_stl_js "$c"),\"ipv6\":\"off\",\"on_fail\":\"$(_st_onfail)\"}"
						so="$so $a:zm_if${a#s}" ;;
					warp) so="$so $a:$STL_WARP_OUT" ;;
				esac ;;
		esac
	done < "$mf"
	out="$mout"
	while IFS="$tab" read -r k a b c; do
		case "$k" in
			lan) lan="$(printf '%s\n' "$a" "$b" "$c" | tr "$tab" '\n' | grep . | while read -r d; do printf ',%s' "$(_stl_js "$d")"; done | sed 's/^,//')" ;;
			warp)
				set -- $(printf '%s\t%s\t%s' "$a" "$b" "$c" | tr "$tab" ' ')
				if [ $# = 1 ]; then
					t="\"$STL_WARP_OUT\":{\"kind\":\"interface\",\"device\":$(_stl_js "$1"),\"ipv6\":\"off\",\"on_fail\":\"$(_st_onfail)\"}"
				else
					m=""; u=""; for d; do m="$m${m:+,}$(_stl_js "$d")"; u="$u,$(_stl_js "$d"):{\"kind\":\"interface\",\"device\":$(_stl_js "$d"),\"ipv6\":\"off\"}"; done
					d=""; [ "$wp" = latency ] && d=',"tolerance":200,"interval":600'
					t="\"$STL_WARP_OUT\":{\"kind\":\"group\",\"pick\":\"$wp\"$d,\"members\":[$m],\"ipv6\":\"off\",\"on_fail\":\"$(_st_onfail)\"}$u"
				fi
				outs="$t${outs:+,}$outs" ;;
			vpn) [ "$main" = vpn ] && { t="$(_stl_vpn_outs "$mf" "$a")"; [ -n "$t" ] && outs="$t${outs:+,}$outs"; } ;;
			sec)
				_stl_rule; lid=""; srs=""; dom=""; pfx=""; cu=""
				sec="$a"; out=""; dnt="${a#s}"; sfm=""; sfa=""
				for t in $so; do [ "${t%%:*}" = "$a" ] && out="${t#*:}"; done
				[ -n "$out" ] || continue
				if [ "$out" = "$mout" ]; then dnt=""; elif [ "$out" = "$STL_WARP_OUT" ]; then dnt=w; fi
				while IFS="$tab" read -r u d m x; do
					[ "$u" = sdev ] && [ "$d" = "$a" ] && [ "$m" = only ] || continue
					_stl_client "$x"
					case "$x" in *:*) sfm="$sfm${sfm:+,}\"$STL_CID\"" ;; *) sfa="$sfa${sfa:+,}\"$STL_CID\"" ;; esac
				done < "$mf"
				x="" ;;
			svc) _stl_rule; lid="$(_stl_ident "${sec:+${sec}_}$a")"; lab="$(_stl_label "$b${sec:+ · ${sec#s}}" "${sec:+${sec}_}$a")"; srs=""; dom=""; pfx=""; cu=""; [ "$a" = custom ] && cu=1 ;;
			srs) srs="$srs${srs:+,}$(_stl_js "$a")" ;;
			dom) dom="$dom${dom:+,}$(_stl_js "$a")" ;;
			pfx) pfx="$pfx${pfx:+,}$(_stl_js "$a")" ;;
			xdom) xd="$xd${xd:+,}$(_stl_js "$a")" ;;
			xpfx) xp="$xp${xp:+,}$(_stl_js "$a")" ;;
			dev)
				if [ "$a" = byp ]; then dout="$ST_DIRECT_OUT"; byp=1; else dout="$mout"; fi
				[ -n "$dout" ] || continue
				case " $dvs " in *" $b "*) continue ;; esac
				dvs="$dvs $b"
				_stl_client "$b"
				[ "$a" = byp ] || xc="$xc $STL_CID"
				drules="$drules${drules:+,}{\"name\":$(_stl_js "$(_stl_ident "${a}_$b")"),\"for\":[\"$STL_CID\"],\"to\":\"all\",\"out\":\"$dout\",\"scope\":\"device\"}" ;;
			sdev)
				[ "$b" = all ] || continue
				dout=""; for t in $so; do [ "${t%%:*}" = "$a" ] && dout="${t#*:}"; done
				[ -n "$dout" ] || continue
				case " $dvs " in *" $c "*) continue ;; esac
				dvs="$dvs $c"
				_stl_client "$c"
				xc="$xc $STL_CID"
				drules="$drules${drules:+,}{\"name\":$(_stl_js "$(_stl_ident "${a}_all_$c")"),\"for\":[\"$STL_CID\"],\"to\":\"all\",\"out\":\"$dout\",\"scope\":\"device\"}" ;;
		esac
	done < "$mf"
	_stl_rule
	[ -n "$crules" ] && rules="$crules${rules:+,}$rules"
	[ -n "$rules$drules" ] || return 1
	if [ -n "$xd$xp" ]; then
		body=""
		[ -n "$xd" ] && body="\"domains_file\":[$xd]"
		[ -n "$xp" ] && body="$body${body:+,}\"prefixes_file\":[$xp]"
		lists="\"$ST_EXCL_LIST\":{$body}${lists:+,}$lists"
		rules="{\"name\":\"Исключения\",\"to\":\"$ST_EXCL_LIST\",\"out\":\"$ST_DIRECT_OUT\",\"resolve\":\"realip\"}${rules:+,}$rules"
		for cid in $(printf '%s\n' $xc | awk '!s[$0]++'); do
			xr="$xr${xr:+,}{\"name\":$(_stl_js "$(_stl_ident "x_$cid")"),\"for\":[\"$cid\"],\"to\":\"$ST_EXCL_LIST\",\"out\":\"$ST_DIRECT_OUT\",\"scope\":\"device\",\"resolve\":\"realip\"}"
		done
		[ -n "$xr" ] && drules="$xr${drules:+,}$drules"
		byp=1
	fi
	[ -n "$byp" ] && outs="$outs${outs:+,}\"$ST_DIRECT_OUT\":{\"kind\":\"direct\"}"
	[ -n "$drules" ] && [ -n "$rules" ] && drules="$drules,"
	rules="$drules$rules"
	[ -n "$clients" ] && clients="\"clients\":{$clients},"
	if [ -n "$dnsn" ]; then
		dnsj=""
		for t in $dnsn; do
			u="zm_tun${t%%:*}"; d="${t#*:}"
			dnsj="$dnsj${dnsj:+,}\"$u\":{\"servers\":[\"${u}_cf\",\"${u}_gg\",\"zm_dir_ya\"],\"mode\":\"failover\"},"
			dnsj="$dnsj\"${u}_cf\":{\"url\":\"https://cloudflare-dns.com/dns-query\",\"ips\":[\"1.1.1.1\",\"1.0.0.1\"],\"out\":\"$d\"},"
			dnsj="$dnsj\"${u}_gg\":{\"url\":\"https://dns.google/dns-query\",\"ips\":[\"8.8.8.8\",\"8.8.4.4\"],\"out\":\"$d\"}"
		done
		dnsj="\"dns\":{\"upstreams\":{$dnsj,\"zm_dir_ya\":{\"url\":\"https://common.dot.dns.yandex.net/dns-query\",\"ips\":[\"77.88.8.8\",\"77.88.8.1\"]}}},"
	fi
	t="$(_st_cttl)"
	if [ "$t" != 0 ] && [ -z "$ZM_STL_NOCTTL" ]; then
		if [ -n "$dnsj" ]; then dnsj="\"dns\":{\"cache_ttl\":{\"min\":$t},${dnsj#\"dns\":\{}"
		else dnsj="\"dns\":{\"cache_ttl\":{\"min\":$t}},"; fi
	fi
	printf '{"version":2,%s"lan":{"devices":[%s]},%s"lists":{%s},"outputs":{%s},"rules":[%s]}\n' "$dnsj" "${lan:-\"br-lan\"}" "$clients" "$lists" "$outs" "$rules"
}

_stl_check() {
	local r c
	if stl_running && [ -S "$STL_SOCK" ]; then
		r="$(_stl_t 150 steer ctl check < "$1" 2>/dev/null)"
		c="$(printf '%s' "$r" | jsonfilter -e '@.code' 2>/dev/null)"
		case "$c" in
			0) return 0 ;;
			[1-9]*) printf '%s' "$r" | jsonfilter -e '@.stderr' 2>/dev/null; return 1 ;;
		esac
	fi
	_stl_t 150 steer apply --dry-run --spec "$1" 2>&1 >/dev/null
}

stl_apply() {
	local new="$STL_SPEC.zm.$$" prev="$STL_TMP/spec.prev" err w=0 ZM_STL_NOFAM=""
	mkdir -p "$STL_ETC" "$STL_TMP"
	_stl_spec "$1" > "$new" || { rm -f "$new"; echo "ОШИБКА: в настройке нет ни одного списка"; return 1; }
	_stl_say "Проверяем правила: $(grep -o '"out":' "$new" | wc -l | tr -d ' ')"
	local ck=0 noct=""
	err="$(_stl_check "$new")" && ck=1
	if [ "$ck" = 0 ] && grep -q '"family":"4"' "$new" && printf '%s' "$err" | grep -q 'family'; then
		ZM_STL_NOFAM=1
		_stl_spec "$1" > "$new" && err="$(_stl_check "$new")" && ck=1
		[ "$ck" = 1 ] && _stl_say "Ядро steer старое — «Свой список» секции не главнее сервисов остальных секций. Обновите ядро steer"
	fi
	[ "$ck" = 0 ] && grep -q '"cache_ttl"' "$new" && noct=1
	if [ -n "$noct" ] && ( ZM_STL_NOCTTL=1; _stl_spec "$1" ) > "$new" && err="$(_stl_check "$new")"; then
		ck=1
		_stl_say "Ядро steer не знает настройку «Помнить адреса сервисов» — правила применены без неё. Обновите ядро steer"
	fi
	if [ "$ck" = 0 ]; then
		if grep -q '"zm_tun' "$new" && ( ZM_STL_NODNS=1; [ -n "$noct" ] && ZM_STL_NOCTTL=1; _stl_spec "$1" ) > "$new" && err="$(_stl_check "$new")"; then
			_stl_say "Ядро steer не умеет DNS через туннель — правила применены без него. Обновите ядро steer, чтобы адреса сервисов узнавались через туннель"
		else
			rm -f "$new"
			echo "ОШИБКА: ядро steer отвергло настройку"
			printf '%s\n' "$err" | tail -n 5 | _st_outs_text
			return 1
		fi
	fi
	[ "$(stl_spec_whose)" = none ] && [ -s "$STL_SPEC" ] && [ ! -f "$STL_KEEP" ] && cp -f "$STL_SPEC" "$STL_KEEP"
	rm -f "$prev"; [ -s "$STL_SPEC" ] && cp -f "$STL_SPEC" "$prev"
	mv -f "$new" "$STL_SPEC"
	"$STL_INIT" enable >/dev/null 2>&1
	if stl_running; then
		if ! err="$(_stl_t 300 steer apply 2>&1 >/dev/null)"; then
			if [ -s "$prev" ]; then mv -f "$prev" "$STL_SPEC"; else rm -f "$STL_SPEC"; fi
			echo "ОШИБКА: ядро steer не применило правила — остались прежние"
			printf '%s\n' "$err" | tail -n 5 | _st_outs_text
			return 1
		fi
		rm -f "$prev"
		_stl_say "Правила Steer применены — ядро тронуло только изменившееся"
		return 0
	fi
	rm -f "$prev"
	"$STL_INIT" start >/dev/null 2>&1
	while [ "$w" -lt 10 ] && ! stl_running; do sleep 1; w=$((w + 1)); done
	stl_running || { echo "ОШИБКА: служба steer не запустилась — загляните в системный журнал"; return 1; }
	_stl_say "Правила Steer применены"
}

stl_running() { [ -x "$STL_INIT" ] && "$STL_INIT" running >/dev/null 2>&1; }
stl_enabled() { [ -x "$STL_INIT" ] && "$STL_INIT" enabled >/dev/null 2>&1; }
stl_restart() {
	[ -x "$STL_INIT" ] || return 1
	"$STL_INIT" enable >/dev/null 2>&1
	"$STL_INIT" restart >/dev/null 2>&1
	sleep 1
	stl_running
}
stl_stop() { [ -x "$STL_INIT" ] || return 0; "$STL_INIT" stop >/dev/null 2>&1; "$STL_INIT" disable >/dev/null 2>&1; return 0; }
stl_reload() { stl_running || return 0; _stl_t 120 steer reload >/dev/null 2>&1; }

stl_state() {
	local o j m
	o="$(_stl_out "$1")"
	STL_UP=false; STL_FAILED=false; STL_DEV=""; STL_PSTATE=""; STL_PNODE=""; STL_PTOTAL=""; STL_NODE=""; STL_NWHY=""
	STL_KIND=""; STL_SEL=""; STL_PROTO=""; STL_PIDX=""
	stl_present || return 1
	if [ -n "$ZM_STL_CACHE" ] && [ -n "$STL_ST_J" ]; then j="$STL_ST_J"; else j="$(_stl_t 10 steer status 2>/dev/null)"; fi
	case "$j" in '{'*) ;; *) return 1 ;; esac
	eval "$(printf '%s' "$j" | jsonfilter -e "STL_KIND=@.outputs.$o.kind" -e "STL_SEL=@.outputs.$o.group.selected" \
		-e "STL_UP=@.outputs.$o.up" -e "STL_FAILED=@.outputs.$o.failed" -e "STL_DEV=@.outputs.$o.device" \
		-e "STL_PSTATE=@.outputs.$o.probe.state" -e "STL_PNODE=@.outputs.$o.probe.node" -e "STL_PTOTAL=@.outputs.$o.probe.total" \
		-e "STL_NWHY=@.outputs.$o.node_down.why" 2>/dev/null)"
	case "$STL_UP" in 1|true) STL_UP=true ;; *) STL_UP=false ;; esac
	case "$STL_FAILED" in 1|true) STL_FAILED=true ;; *) STL_FAILED=false ;; esac
	if [ "$1" = vpn ]; then
		m="$o"
		[ "$STL_KIND" = group ] && printf '%s' "$STL_SEL" | grep -qE "^${STL_VPN_PFX}_[a-z0-9]+\$" && m="$STL_SEL"
		local n1="" n2="" n3="" i1="" i2="" w2=""
		eval "$(printf '%s' "$j" | jsonfilter -e "STL_PROTO=@.outputs.$m.kind" -e "n1=@.outputs.$m.vless.node" -e "n2=@.outputs.$m.proxy.node" \
			-e "n3=@.outputs.$m.hysteria2.node" -e "i1=@.outputs.$m.vless.active[0].index" -e "i2=@.outputs.$m.proxy.active[0].index" \
			-e "w2=@.outputs.$m.node_down.why" 2>/dev/null)"
		STL_NODE="${n1:-${n2:-$n3}}"; STL_PIDX="${i1:-$i2}"
		[ -z "$STL_NWHY" ] && [ "$m" != "$o" ] && STL_NWHY="$w2"
		[ "$STL_KIND" = group ] && [ "$STL_FAILED" = true ] && [ -z "$STL_PSTATE" ] && { STL_PSTATE=failed; STL_PTOTAL=0; }
	fi
	[ "$STL_UP" = true ] && STL_NWHY=""
	printf '%s' "$STL_DEV" | grep -qE '^[A-Za-z0-9_.-]+$' || STL_DEV=""
	case "$STL_PSTATE" in probing|failed|no_such_node) ;; *) STL_PSTATE="" ;; esac
	case "$STL_PNODE" in ''|*[!0-9]*) STL_PNODE=0 ;; esac
	case "$STL_PTOTAL" in ''|*[!0-9]*) STL_PTOTAL=0 ;; esac
	case "$STL_PIDX" in *[!0-9]*) STL_PIDX="" ;; esac
	return 0
}

stl_diag() {
	local d
	d="$(_stl_t 30 steer diag 2>/dev/null | tr '\n' ' ')"
	case "$d" in '{'*'}'*) printf '%s' "$d" ;; *) echo null ;; esac
}
_stl_diag_tsv() {
	local n i=0
	n="$(jsonfilter -i "$1" -e '@.checks[*].id' 2>/dev/null | wc -l)"
	while [ "$i" -lt "$n" ]; do
		printf '%s\t%s\t%s\n' "$(jsonfilter -i "$1" -e "@.checks[$i].verdict" 2>/dev/null)" \
			"$(jsonfilter -i "$1" -e "@.checks[$i].what" 2>/dev/null)" "$(jsonfilter -i "$1" -e "@.checks[$i].why" 2>/dev/null)"
		i=$((i + 1))
	done
}
stl_diag_lines() {
	local f="$STL_TMP/stl-diag.json"
	mkdir -p "$STL_TMP"
	_stl_t 30 steer diag > "$f" 2>/dev/null
	_stl_diag_tsv "$f"
	rm -f "$f"
}

_st_diag_map() {
	local s many="" st
	[ -n "$(_st_secs)" ] && many=1
	for s in main $(_st_secs); do
		if [ "$s" = main ]; then
			if _st_sec_off main; then st=off; elif _st_sec_with main _st_work_main; then st=work; else st=idle; fi
			printf '%s\t%s\t%s\t%s\n' main "${many:+Секция «$(_st_sec_name main)»}" "$st" "$(_st_main_iface)"
		else
			if _st_sec_off "$s"; then st=off; elif _st_sec_work "$s"; then st=work; else st=idle; fi
			printf '%s\t%s\t%s\t%s\n' "$s" "Секция «$(_st_sec_name "$s")»" "$st" "$(_st_sec_iface "$s")"
		fi
	done
}
ZM_ST_DIAG_AWK='
function secof(o) {
	if (o == "zm_vpn" || o == "zm_if" || o ~ /^zmv_/) return "main"
	if (o ~ /^zm_(vpn|if)[2-9]$/) return "s" substr(o, length(o), 1)
	if (o ~ /^zmv[2-9]_/) return "s" substr(o, 4, 1)
	return ""
}
function tipof(r,   c) {
	if (r ~ /вместо 101/) {
		c = r; sub(/^[^0-9]*/, "", c); c = substr(c, 1, 3) + 0
		if (c == 400 || c == 404) return "Сервер не знает такого адреса подключения — в ссылке неверный path или host"
		if (c == 403) return "Сервер или CDN перед ним не пускает — проверьте host и sni в ссылке или возьмите другой узел"
		if (c >= 500) return "Сервер узла (или CDN перед ним) не смог принять подключение — обычно в ссылке неверный path или host, реже сбой у поставщика"
		return "Сервер не принял подключение WebSocket — проверьте path и host в ссылке"
	}
	if (r ~ /Upgrade|Sec-WebSocket|кадр WebSocket/) return "По ссылке отвечает не VPN-сервер, а что-то другое (сайт-заглушка, прокси) — проверьте path, host и порт"
	if (r ~ /не разрешил/) return "Адрес сервера из ссылки не находится — проверьте адрес в ссылке и DNS роутера"
	if (r ~ /TCP не соединился|нет сокета/) return "До сервера не достучаться: он выключен, сменил порт или его блокирует провайдер"
	if (r ~ /ClientHello|таймаут|не ответил за|узел не ответил/) return "Сервер молчит — так выглядит блокировка по имени сайта (SNI) или лежащий узел; попробуйте другой узел"
	if (r ~ /не признал ключ|UUID|отверг авторизацию|отказал в авторизации|авторизации негоден|pbk или sid/) return "Сервер не принял ключ или пароль из ссылки — ссылка устарела: обновите подписку или ссылку"
	if (r ~ /подлинност|сертификат|pinSHA256/) return "Сертификат сервера не прошёл проверку — в ссылке неверный sni, или соединение подменяют"
	if (r ~ /ECH/) return "Ключ ECH в ссылке устарел — обновите ссылку или подписку"
	if (r ~ /VLESS encryption/) return "Строка encryption в ссылке не совпадает с сервером — обновите ссылку"
	if (r ~ /HTTP\/2|HTTP\/1\.1|gRPC/) return "Сервер не поддерживает транспорт из ссылки (ws, grpc, xhttp) — проверьте тип транспорта"
	if (r ~ /QUIC не открылся/) return "Подключение по QUIC (UDP) не открылось — проверьте порт и sni в ссылке; иногда провайдер режет UDP"
	if (r ~ /соединения не открываются/) return "Узел отвечает на проверку, но настоящие соединения не держит — выберите другой узел"
	if (r ~ /закрыл соединение|TLS закрыт|обрыв|поток закрыт|GOAWAY|не прислал данных|ответа нет|ответ не по протоколу|соединение закрыто/) return "Сервер обрывает соединение — узел перегружен или не пускает с этого адреса; попробуйте другой узел"
	return "Узел не отвечает — выберите другой узел или проверьте ссылку"
}
BEGIN {
	FS = "\t"; OFS = U
	while ((getline l < M) > 0) { split(l, a, "\t"); LB[a[1]] = a[2]; ST[a[1]] = a[3]; IF[a[1]] = a[4] }
	close(M)
	T = "(zm_vpn[2-9]?|zmv[2-9]?_[A-Za-z0-9]+|zm_warp[0-9]*|zmwarp[0-9]*)"
}
{
	v = $1; w = $2; y = $3; v0 = v; tip = ""; note = ""; s = ""; lab = ""
	if (w ~ /^выход [A-Za-z0-9_.-]+/) {
		o = w; sub(/^выход /, "", o); rest = o; sub(/[: ].*$/, "", o)
		rest = substr(rest, length(o) + 1); sub(/^:? */, "", rest)
		s = secof(o)
		if (s != "") {
			k = (o ~ /^zm_if/) ? "туннель" (IF[s] != "" ? " " IF[s] : "") : "VPN"
			lab = (LB[s] != "" ? LB[s] " · " : "") k
		} else if (o ~ /^zm_warp/) lab = "WARP"
		else if (o == "zm_direct") lab = "Мимо Steer"
		if (lab != "") {
			sub("^устройство " T " в зоне, NAT есть$", "туннель подключён, NAT есть", rest)
			sub("^устройство " T " в зоне$", "туннель подключён", rest)
			sub("^устройства " T " нет$", "туннель не поднят", rest)
			sub("^устройство " T " выключено$", "туннель выключен", rest)
			sub("^" T " вне зоны фаервола$", "туннель вне зоны фаервола", rest)
			sub("^у " T " нет masquerade", "у туннеля нет masquerade", rest)
			sub("^" T " не отвечает", "туннель не отвечает", rest)
			cl = ""
			if (match(rest, /, трафик канала /)) {
				cl = substr(rest, RSTART + RLENGTH); rest = substr(rest, 1, RSTART - 1)
				if (cl == "идёт напрямую") cl = "сервисы идут напрямую"
				else if (cl == "остановлен") cl = "сервисы остановлены"
				else if (cl == "идёт через обход") cl = "сервисы идут через обход блокировок"
			}
			if (rest ~ /^узел перестал отвечать/) {
				rest = "узел не отвечает"
				r = y; sub(/; выход вернётся сам, когда узел ответит$/, "", r); sub(/ \(проверьте path и host\)$/, "", r)
				if (r == "узел не отвечает") r = ""
				y = r; tip = tipof(r)
			} else if (rest ~ /^туннель не отвечает/) {
				y = "проверьте туннель и его сервер"
				tip = "Туннель есть, но трафик через него не проходит — обычно не отвечает сервер туннеля"
			} else if (rest == "туннель не поднят") sub(/^туннель не поднят — /, "", y)
			if (s != "" && ST[s] != "" && ST[s] != "work") cl = ""
			w = lab ": " rest (cl != "" ? ", " cl : "")
		}
	} else if (w ~ /^канал s[2-9]_/) {
		c = w; sub(/^канал /, "", c); s = substr(c, 1, 2); sub(/^s[2-9]_/, "", c); sub(/:.*$/, "", c)
		t = w; sub(/^канал s[2-9]_[^:]*/, "", t)
		if (LB[s] != "") w = LB[s] " · список «" c "»" t
		s = ""
	}
	if (v == "fail" && s != "" && ST[s] != "" && ST[s] != "work") {
		v = "warn"
		note = ST[s] == "off" ? "Секция выключена — на работу это сейчас не влияет" : "В секции ничего не выбрано — на работу это сейчас не влияет"
		if (LB[s] == "") note = ST[s] == "off" ? "Steer выключен — на работу это сейчас не влияет" : "Сервисы не выбраны — на работу это сейчас не влияет"
	} else if (v == "fail" && tip != "" && s != "") tip = tip ". Как только он ответит, всё заработает само"
	print v, w, y, tip, note, v0, $2
}'
_st_diag_human() {
	local m="$ST_RUN/diag.map.$$"
	mkdir -p "$ST_RUN"
	_st_diag_map > "$m" 2>/dev/null
	awk -v M="$m" -v U="$(printf '\037')" "$ZM_ST_DIAG_AWK"
	rm -f "$m"
}
_st_outs_text() {
	local m="$ST_RUN/diag.map.$$"
	mkdir -p "$ST_RUN"
	_st_diag_map > "$m" 2>/dev/null
	awk -v M="$m" '
	function secof(o) {
		if (o == "zm_vpn" || o == "zm_if" || o ~ /^zmv_/) return "main"
		if (o ~ /^zm_(vpn|if)[2-9]$/) return "s" substr(o, length(o), 1)
		if (o ~ /^zmv[2-9]_/) return "s" substr(o, 4, 1)
		return ""
	}
	BEGIN { while ((getline l < M) > 0) { split(l, a, "\t"); LB[a[1]] = a[2]; IF[a[1]] = a[4] } close(M) }
	{
		out = ""; t = $0
		while (match(t, /выход (zm_vpn[2-9]?|zm_if[2-9]?|zmv[2-9]?_[A-Za-z0-9]+|zm_warp[0-9]*|zm_direct)/)) {
			o = substr(t, RSTART, RLENGTH); sub(/^выход /, "", o); s = secof(o)
			if (s != "") lab = (LB[s] != "" ? LB[s] " · " : "") ((o ~ /^zm_if/) ? "туннель" (IF[s] != "" ? " " IF[s] : "") : "VPN")
			else lab = (o == "zm_direct") ? "Мимо Steer" : "WARP"
			out = out substr(t, 1, RSTART - 1) lab; t = substr(t, RSTART + RLENGTH)
		}
		print out t
	}'
	rm -f "$m"
}
_st_diag_what() { printf 'fail\t%s\t\n' "$1" | _st_diag_human | awk -F"$(printf '\037')" '{ print $2 }'; }
_st_diag_hjson() {
	_st_diag_human | awk -F"$(printf '\037')" "$ZM_JESC_AWK"'
		$1 ~ /^(ok|warn|fail)$/ { printf "%s{\"v\":\"%s\",\"what\":\"%s\",\"why\":\"%s\",\"tip\":\"%s\",\"note\":\"%s\"}", (n++ ? "," : ""), $1, jesc($2), jesc($3), jesc($4), jesc($5) }'
}

_stl_explain_run() {
	local t="" x="$STL_ETC/.zm-explain.$$.json"
	if [ -s "$STL_SPEC" ] && grep -q '"scope":"device"' "$STL_SPEC" 2>/dev/null; then
		sed 's/"scope":"device"/"scope":"device","enabled":false/g' "$STL_SPEC" > "$x" 2>/dev/null && t="$(_stl_t 20 steer explain --spec "$x" "$1" 2>&1)"
		rm -f "$x"
		case "$t" in *' -> '*) printf '%s\n' "$t"; return 0 ;; esac
	fi
	_stl_t 20 steer explain "$1" 2>&1
}

stl_explain() {
	local t line
	STL_X_VERDICT=unknown; STL_X_OUT=""; STL_X_DEV=""; STL_X_SET=""; STL_X_ADDR=""; STL_X_FAKE=false
	t="$(_stl_explain_run "$1")"
	STL_X_TEXT="$t"
	line="$(printf '%s\n' "$t" | grep -m1 -- '-> output "')"
	STL_X_ADDR="$(printf '%s\n' "$t" | head -n1 | sed -n 's/^[^ ]* -> \([0-9a-fA-F.:]*\) (.*/\1/p')"
	printf '%s\n' "$t" | head -n1 | grep -q 'fake-IP' && STL_X_FAKE=true
	if [ -n "$line" ]; then
		STL_X_OUT="$(printf '%s' "$line" | sed -n 's/.*-> output "\([^"]*\)".*/\1/p')"
		STL_X_SET="$(printf '%s' "$line" | sed -n 's/.*"\([^"]*\)" -> output ".*/\1/p')"
		STL_X_DEV="$(printf '%s' "$line" | sed -n 's/.*-> dev \([^ ]*\).*/\1/p')"
		case "$STL_X_OUT" in "$STL_WARP_OUT") STL_X_VERDICT=warp ;; zm_vpn|zm_vpn[2-9]|zmv_*|zmv[2-9]_*) STL_X_VERDICT=vpn ;; zm_if|zm_if[2-9]) STL_X_VERDICT=iface ;; "$ST_DIRECT_OUT") STL_X_VERDICT=direct ;; *) STL_X_VERDICT=other ;; esac
		[ -z "$STL_X_DEV" ] && printf '%s' "$line" | grep -q -- '-> direct' && STL_X_VERDICT=direct
	elif printf '%s' "$t" | grep -q 'no channel matches'; then STL_X_VERDICT=direct
	elif printf '%s' "$t" | grep -q 'резолвер ответил, но адреса не дал'; then STL_X_VERDICT=noaddr
	elif printf '%s' "$t" | grep -q 'резолвер steer не ответил'; then STL_X_VERDICT=nodns
	elif printf '%s' "$t" | grep -q 'нет ни одного правила по доменам'; then STL_X_VERDICT=nodomains; fi
}
ZM_ROUTE_PROBES='www static cdn api m' 

stl_sub_fetch() {
	local r
	STL_SUB_URL=""; STL_SUB_TITLE=""; STL_SUB_WARN=""; STL_SUB_ERR=""
	rm -f "$2"
	r="$(steer sub-fetch "$1" --out "$2" --info "$3" 2>/dev/null)"
	if [ "$(printf '%s' "$r" | jsonfilter -e '@.ok' 2>/dev/null)" != true ] || [ ! -s "$2" ]; then
		rm -f "$2"
		STL_SUB_ERR="$(printf '%s' "$r" | jsonfilter -e '@.error' 2>/dev/null)"
		return 1
	fi
	STL_SUB_URL="$(printf '%s' "$r" | jsonfilter -e '@.url' 2>/dev/null)"
	STL_SUB_TITLE="$(printf '%s' "$r" | jsonfilter -e '@.title' 2>/dev/null)"
	STL_SUB_WARN="$(printf '%s' "$r" | jsonfilter -e '@.warn' 2>/dev/null)"
	return 0
}
STL_VPN_PROTOS="vless hysteria2 trojan shadowsocks socks http vmess"
STL_VPN_DEVS="zm_vpn zmv_vless zmv_hy2 zmv_trojan zmv_ss zmv_socks zmv_http zmv_vmess"
STL_LINK_RE='^(vless|vmess|trojan|ss|socks|socks4|socks4a|socks5|http|https|hysteria2|hy2)://'
_stl_mod_of() { case "$1" in vless) echo vless ;; hysteria2) echo hysteria2 ;; *) echo proxy ;; esac; }
_stl_member() { case "$1" in hysteria2) echo "${2:-$STL_VPN_PFX}_hy2" ;; shadowsocks) echo "${2:-$STL_VPN_PFX}_ss" ;; *) echo "${2:-$STL_VPN_PFX}_$1" ;; esac; }

stl_sub_norm() {
	rm -f "$2" "$2.map"
	LC_ALL=C awk -v OUT="$2" -v MAP="$2.map" '
BEGIN { A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"; for (i = 1; i <= 64; i++) B64[substr(A, i, 1)] = i - 1 }
function b64d(s,    o, ch, i, n, v, w, x, y, k) {
	gsub(/[ \t\r\n=]/, "", s); gsub(/-/, "+", s); gsub(/_/, "/", s)
	if (s ~ /[^A-Za-z0-9+\/]/) return ""
	o = ""; ch = ""; k = 0; n = length(s)
	for (i = 1; i + 3 <= n; i += 4) {
		v = B64[substr(s, i, 1)] * 262144 + B64[substr(s, i + 1, 1)] * 4096 + B64[substr(s, i + 2, 1)] * 64 + B64[substr(s, i + 3, 1)]
		w = int(v / 65536); x = int(v / 256) % 256; y = v % 256
		ch = ch sprintf("%c%c%c", w, x, y)
		if (++k >= 128) { o = o ch; ch = ""; k = 0 }
	}
	if (n - i == 2) { v = B64[substr(s, i, 1)] * 262144 + B64[substr(s, i + 1, 1)] * 4096 + B64[substr(s, i + 2, 1)] * 64; ch = ch sprintf("%c%c", int(v / 65536), int(v / 256) % 256) }
	else if (n - i == 1) { v = B64[substr(s, i, 1)] * 262144 + B64[substr(s, i + 1, 1)] * 4096; ch = ch sprintf("%c", int(v / 65536)) }
	return o ch
}
function hexv(h) { return index("0123456789abcdef", tolower(h)) - 1 }
function frag(s,    o, i, n, a, b, v) {
	o = ""; n = length(s)
	for (i = 1; i <= n; i++) {
		if (substr(s, i, 1) == "%" && i + 2 <= n) {
			a = hexv(substr(s, i + 1, 1)); b = hexv(substr(s, i + 2, 1))
			if (a >= 8 && b >= 0) { v = a * 16 + b; o = o sprintf("%c", v); i += 2; continue }
		}
		o = o substr(s, i, 1)
	}
	return o
}
function fam(sc) {
	sc = tolower(sc)
	if (sc == "vless") return "vless"
	if (sc == "hysteria2" || sc == "hy2") return "hysteria2"
	if (sc == "trojan") return "trojan"
	if (sc == "ss") return "shadowsocks"
	if (sc ~ /^socks/) return "socks"
	if (sc == "http" || sc == "https") return "http"
	if (sc == "vmess") return "vmess"
	return ""
}
function jfield(j, k,    r) {
	if (match(j, "\"" k "\"[ \t]*:[ \t]*\"[^\"]*\"")) { r = substr(j, RSTART, RLENGTH); sub(/^"[^"]*"[ \t]*:[ \t]*"/, "", r); sub(/"$/, "", r); return r }
	if (match(j, "\"" k "\"[ \t]*:[ \t]*[0-9]+")) { r = substr(j, RSTART, RLENGTH); sub(/^.*:[ \t]*/, "", r); return r }
	return ""
}
function hostport(l, f,    r, j, t) {
	H = ""; P = ""
	r = l; sub(/^[A-Za-z0-9]+:\/\//, "", r)
	if (f == "vmess") { sub(/#.*/, "", r); j = b64d(r); H = jfield(j, "add"); P = jfield(j, "port"); return }
	if (f == "shadowsocks") { t = r; sub(/[?#].*$/, "", t); if (index(t, "@") == 0) { j = b64d(t); if (index(j, "@")) { sub(/^.*@/, "", j); r = j } } }
	sub(/[\/?#].*$/, "", r)
	sub(/^.*@/, "", r)
	if (r ~ /^\[/) { H = r; sub(/\].*$/, "", H); sub(/^\[/, "", H); P = r; sub(/^.*\]:?/, "", P); return }
	H = r; sub(/:.*$/, "", H); P = r; if (index(P, ":")) sub(/^[^:]*:/, "", P); else P = ""
}
{ buf = buf $0 "\n" }
END {
	gsub(/\r/, "", buf)
	t = buf; sub(/^[ \t\n]+/, "", t)
	if (t ~ /^[\{\[]/) { printf "%s", buf > OUT; printf "" > MAP; exit 0 }
	if (!index(buf, "://")) { d = b64d(buf); if (index(d, "://")) buf = d }
	gsub(/\r/, "", buf)
	n = split(buf, L, "\n"); ln = 0
	for (i = 1; i <= n; i++) {
		l = L[i]; gsub(/^[ \t]+|[ \t]+$/, "", l)
		if (l == "") continue
		if (match(l, /^[A-Za-z0-9]+:\/\//)) {
			sc = substr(l, 1, RLENGTH - 3)
			h = index(l, "#")
			if (h) l = substr(l, 1, h) frag(substr(l, h + 1))
			gsub(/[\t]/, " ", l)
			print l > OUT; ln++
			f = fam(sc)
			if (f != "") { hostport(l, f); printf "%d\t%s\t%s\t%s\n", ln, f, tolower(H), P > MAP }
		} else { print l > OUT; ln++ }
	}
	printf "" > MAP
}
' "$1" 2>/dev/null
	[ -s "$2" ]
}

stl_sub_mods() {
	local m="vpn"
	if head -c 256 "$1" 2>/dev/null | tr -d ' \t\r\n' | grep -q '^[[{]'; then
		grep -qiE '"(protocol|type)"[[:space:]]*:[[:space:]]*"(hysteria2?|hy2)"' "$1" && m="$m hy2"
		grep -qiE '"(protocol|type)"[[:space:]]*:[[:space:]]*"(trojan|shadowsocks|socks|http|vmess)"' "$1" && m="$m proxy"
	else
		grep -qiE '^(hysteria2|hy2)://' "$1" && m="$m hy2"
		grep -qiE '^(trojan|ss|socks4a?|socks5?|https?|vmess)://' "$1" && m="$m proxy"
	fi
	echo "$m"
}

stl_sub_nodes() {
	local m
	{ for m in vless hysteria2 proxy; do
		[ -x "$STL_SBIN/steer-$m" ] || continue
		printf '@%s\t' "$m"; _stl_t 30 steer "$m-nodes" "$1" 2>/dev/null | tr '\n\t' '  '; echo
	done; } | LC_ALL=C awk -v MAP="$1.map" -v META="$3" '
function junesc(s,    o, i, n, c, d) {
	o = ""; n = length(s)
	for (i = 1; i <= n; i++) {
		c = substr(s, i, 1)
		if (c == "\\" && i < n) {
			d = substr(s, ++i, 1)
			if (d == "u") { i += 4; o = o " " }
			else if (d == "n" || d == "t" || d == "r" || d == "b" || d == "f") o = o " "
			else o = o d
		} else o = o c
	}
	gsub(/\t/, " ", o)
	return o
}
function sfield(ch, k,    r) {
	if (match(ch, "\"" k "\":\"([^\"\\\\]|\\\\.)*\"")) { r = substr(ch, RSTART + length(k) + 4, RLENGTH - length(k) - 5); return junesc(r) }
	return ""
}
function nfield(ch, k,    r) {
	if (match(ch, "\"" k "\":-?[0-9]+")) { r = substr(ch, RSTART + length(k) + 3, RLENGTH - length(k) - 3); return r + 0 }
	return -1
}
function bfield(ch, k) { return (index(ch, "\"" k "\":true") ? 1 : 0) }
BEGIN {
	FS = "\t"
	if (MAP != "") while ((getline l < MAP) > 0) { split(l, a, "\t"); key = a[2] "|" a[3] "|" a[4]; Q[key] = Q[key] (Q[key] == "" ? "" : " ") a[1] }
	seq = 0; usable = 0; skipped = 0; reasons = ""
}
{
	mod = substr($1, 2); j = $0; sub(/^[^\t]*\t/, "", j)
	if (match(j, /"usable":[0-9]+/)) usable += substr(j, RSTART + 9, RLENGTH - 9)
	if (match(j, /"skipped":[0-9]+/)) skipped += substr(j, RSTART + 10, RLENGTH - 10)
	r = j
	while (match(r, /"reason":"([^"\\]|\\.)*"/)) {
		x = substr(r, RSTART + 10, RLENGTH - 11); r = substr(r, RSTART + RLENGTH)
		if (!(x in RS_)) { RS_[x] = 1; reasons = reasons (reasons == "" ? "" : ",") "{\"reason\":\"" x "\"}" }
	}
	p = index(j, "\"nodes\":["); if (!p) next
	j = substr(j, p + 9)
	q = index(j, "],\"skipped_reasons\""); if (q) j = substr(j, 1, q - 1)
	n = split(j, C, /\{"index":/)
	for (i = 2; i <= n; i++) {
		ch = "{\"index\":" C[i]
		fidx = nfield(ch, "index"); name = sfield(ch, "name"); host = tolower(sfield(ch, "host")); port = nfield(ch, "port")
		ty = sfield(ch, "type"); sec = sfield(ch, "security"); vis = bfield(ch, "vision")
		if (mod == "vless") { proto = "vless"; tr = ty }
		else if (mod == "hysteria2") { proto = "hysteria2"; tr = "quic" }
		else { proto = ty; tr = sfield(ch, "transport") }
		if (proto == "") continue
		pidx = (mod == "proxy") ? PC[proto]++ : fidx
		key = proto "|" host "|" port; pos = ""
		if (Q[key] != "") { pos = Q[key]; sub(/ .*/, "", pos); if (index(Q[key], " ")) sub(/^[^ ]* /, "", Q[key]); else Q[key] = "" }
		if (pos == "") pos = 100000 + seq
		seq++
		if (name == "") name = host ":" port
		printf "%d\t%s\t%d\t%d\t%s\t%s\t%s\t%d\n", pos, proto, pidx, fidx, name, tr, sec, vis
	}
}
END { if (META != "") printf "usable=%d\nskipped=%d\nreasons=[%s]\n", usable, skipped, reasons > META }
' | sort -n -k1,1 | LC_ALL=C awk -F'\t' 'BEGIN { OFS = "\t" }
		{ k = $5; c = ++D[k]; if (c > 1) k = k " (" c ")"; while (k in U) { c++; k = $5 " (" c ")" } U[k] = 1
		  print NR - 1, $2, $3, $4, k, $6, $7, $8 }' > "$2"
}
stl_sub_check() {
	local t="$STL_TMP/subcheck.$$"
	mkdir -p "$STL_TMP"
	stl_sub_nodes "$1" "$t" "$t.meta"
	STL_SUB_USABLE="$(grep -c . "$t" 2>/dev/null)"
	STL_SUB_WHY="$(sed -n 's/^reasons=//p' "$t.meta" 2>/dev/null | grep -o '"reason":"[^"]*"' | sed 's/^"reason":"//; s/"$//' | head -n 3)"
	STL_SUB_PROTOS="$(cut -f2 "$t" 2>/dev/null | awk '!s[$0]++' | tr '\n' ' ')"
	rm -f "$t" "$t.meta"
	[ "${STL_SUB_USABLE:-0}" -gt 0 ] 2>/dev/null
}
stl_probe() {
	local j
	j="$(_stl_t 40 steer "$2-probe" "$1" --node "$3" --timeout 8 2>/dev/null | tr '\n' ' ')"
	case "$j" in '{'*) printf '%s' "$j" ;; *) return 1 ;; esac
}


_st_phase() { printf '%s\n' "$1" > "$ST_PHASE_FILE"; }
_st_stopped() { [ -f "$ST_STOP_FLAG" ]; }
_st_own() { mkdir -p "$ST_DIR"; grep -qxF "$1" "$ST_OWNED" 2>/dev/null || echo "$1" >> "$ST_OWNED"; }
_st_owns() { grep -qxF "$1" "$ST_OWNED" 2>/dev/null; }
_st_running() { _job_alive steer; }
_st_installed() { stl_present && { _st_owns "engine" || _st_owns "pkg steer" || _st_owns "net zmwarp" || _st_owns "net $ST_OWN_IF"; }; }
_st_warp_on() {
	if _st_warp_ext; then [ "$(uci -q get "network.$ST_WARP_IF.proto")" = amneziawg ]; else _st_owns "net $ST_WARP_IF" && [ -s "$ST_WARP_CONF" ]; fi
}
_st_warp_own() { case "$ST_MODE_RAW" in own|iface:?*) return 0 ;; esac; return 1; }
_st_warp_ownconf() { [ "$ST_MODE_RAW" = own ]; }
_st_warp_ext() { case "$ST_MODE_RAW" in iface:?*) return 0 ;; esac; return 1; }
_st_ext_if() { case "$ST_MODE_RAW" in iface:?*) printf '%s\n' "${ST_MODE_RAW#iface:}" ;; esac; }
_st_uses_if() { [ -n "$1" ] && _st_installed || return 1; { _st_warp_ext && [ "$(_st_ext_if)" = "$1" ]; } || { [ "$(cat "$ST_DIR/exit" 2>/dev/null)" = iface ] && [ "$(_st_main_iface)" = "$1" ]; } || _st_sec_has_if "$1"; }
_st_sec_has_if() { local s; for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = iface ] && [ "$(_st_sec_iface "$s")" = "$1" ] && return 0; done; return 1; }
_st_warp_modename() { if _st_warp_ext; then echo iface; elif _st_warp_ownconf; then echo own; else echo auto; fi; }
_st_wnet() { _st_owns "net $1" || { _st_warp_ext && [ "$1" = "$ST_WIF1" ]; }; }
_st_wpeer() { if [ -n "$(uci -q get "network.${1}_peer")" ]; then echo "${1}_peer"; else _awg_peer_sec "$1"; fi; }
_st_sec_off() {
	case "${1:-main}" in
		main) [ -f "$ST_SEC_DIR/main.off" ] && [ -s "$ST_SEC_LIST" ] ;;
		*) [ -f "$ST_SEC_DIR/$1/off" ] ;;
	esac
}
_st_sel() { _st_sec_off "$ST_SEC" && return 0; _st_sel_raw; }
_st_sel_raw() { [ -s "$ST_SEL" ] || return 0; local id; for id in $(cat "$ST_SEL"); do _rb_routable "$id" || continue; [ "$id" = custom ] && [ ! -s "$ST_CUSTOM.lst" ] && [ ! -s "$ST_CUSTOM.pfx" ] && continue; echo "$id"; done; }

ST_DEVS="$ST_DIR/devices"
ST_DIRECT_OUT="zm_direct"
_st_dev_key() {
	local k
	k="$(printf '%s' "$1" | tr 'A-F' 'a-f' | tr -d ' \t\r\n')"
	case "$k" in
		[0-9a-f][0-9a-f]:[0-9a-f][0-9a-f]:[0-9a-f][0-9a-f]:[0-9a-f][0-9a-f]:[0-9a-f][0-9a-f]:[0-9a-f][0-9a-f]) [ "$k" = 00:00:00:00:00:00 ] && return 1; printf '%s' "$k" ;;
		*.*.*.*) printf '%s' "$k" | grep -qE '^(25[0-5]|2[0-4][0-9]|1?[0-9]?[0-9])(\.(25[0-5]|2[0-4][0-9]|1?[0-9]?[0-9])){3}$' || return 1; printf '%s' "$k" ;;
		*) return 1 ;;
	esac
}
_st_devs_all() { _st_sec_off "$ST_SEC" && return 1; grep -q "^all	" "$ST_DEVS" 2>/dev/null; }
_st_devs_n() { local n; n="$(grep -c "^$1	" "$ST_DEVS" 2>/dev/null)"; echo "${n:-0}"; }
_st_work() { [ -n "$(_st_sel)" ] || _st_devs_all || { [ -z "$ST_SEC" ] && _st_secs_work; }; }
_st_work_main() { [ -n "$(_st_sel)" ] || _st_devs_all; }
ST_EXCL_LIST="zm_excl"
_st_excl_model() {
	[ -s "$ST_DIR/user/exclude.lst" ] && printf 'xdom\t%s\n' "$ST_DIR/user/exclude.lst"
	[ -s "$ST_DIR/user/exclude.pfx" ] && printf 'xpfx\t%s\n' "$ST_DIR/user/exclude.pfx"
	return 0
}
do_steer_excl() {
	local rc nd np
	_st_phase rules
	rm -f "$ST_STOP_FLAG"
	nd="$(cat "$ST_DIR/user/exclude.lst" 2>/dev/null | grep -c .)"; np="$(cat "$ST_DIR/user/exclude.pfx" 2>/dev/null | grep -c .)"
	_rb_say "Исключения: доменов $nd, IP и подсетей $np"
	if _st_owns "steer-spec" && _st_work; then
		if _st_use_vpn; then _st_spec_quick; else _st_spec_quick_warp; fi
		rc=$?
		if [ "$rc" = 0 ]; then _rb_say "Готово: исключения применены, списки сервисов не перекачивались"; return 0; fi
		[ "$rc" = 1 ] && return 1
	fi
	do_steer_apply
}
_st_dev_model() {
	[ -s "$ST_DEVS" ] || return 0
	awk -F'\t' '($1 == "all" || $1 == "byp") && $2 != "" && !s[$2]++ { printf "dev\t%s\t%s\t%s\n", $1, $2, $3 }' "$ST_DEVS"
}
_st_devs_json() {
	[ -s "$ST_DEVS" ] || return 0
	awk -F'\t' -v q='"' 'function j(v,  o, i, c) { o = ""; for (i = 1; i <= length(v); i++) { c = substr(v, i, 1); if (c == "\\" || c == q) o = o "\\" c; else if (c ~ /[\t\r\n]/) o = o " "; else o = o c } return o }
		($1 == "all" || $1 == "byp" || $1 == "only") && $2 != "" { printf "%s{\"mode\":\"%s\",\"key\":\"%s\",\"name\":\"%s\"}", (n++ ? "," : ""), $1, j($2), j($3) }' "$ST_DEVS"
}
steer_devices() {
	local lan t="$ST_RUN/devs.$$"
	mkdir -p "$ST_RUN"
	lan=" $(_st_lan_devs) "
	{
		[ -f /tmp/dhcp.leases ] && awk '{ print "L", tolower($2), $3, $4 }' /tmp/dhcp.leases
		uci -q -X show dhcp 2>/dev/null | awk -F= '
			/^dhcp\.[^.]*=host$/ { split($1, a, "."); h[a[2]] = 1; next }
			/^dhcp\.[^.]*\.(mac|ip|name)=/ { split($1, a, "."); v = $2; gsub(/\x27/, "", v); x[a[2], a[3]] = v }
			END { for (k in h) if (x[k, "mac"] != "") { split(x[k, "mac"], m, " "); print "S", tolower(m[1]), (x[k, "ip"] == "" ? "-" : x[k, "ip"]), (x[k, "name"] == "" ? "*" : x[k, "name"]) } }'
		[ -f /proc/net/arp ] && awk -v lan="$lan" 'NR > 1 && $3 != "0x0" && index(lan, " " $6 " ") { print "A", tolower($4), $1, "*" }' /proc/net/arp
	} > "$t" 2>/dev/null
	awk -v q='"' 'function j(v,  o, i, c) { o = ""; for (i = 1; i <= length(v); i++) { c = substr(v, i, 1); if (c == "\\" || c == q) o = o "\\" c; else if (c ~ /[\t\r\n]/) o = o " "; else o = o c } return o }
		$2 !~ /^[0-9a-f][0-9a-f](:[0-9a-f][0-9a-f]){5}$/ || $2 == "00:00:00:00:00:00" { next }
		$3 != "-" && $3 !~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/ { $3 = "-" }
		{ m = $2; if (!(m in seen)) { seen[m] = 1; ord[++n] = m }
		  if ($3 != "-" && (ip[m] == "" || $1 == "L")) ip[m] = $3
		  if ($4 != "*" && $4 != "" && (nm[m] == "" || $1 == "S")) nm[m] = $4 }
		END { printf "{\"devices\":["; for (i = 1; i <= n; i++) { m = ord[i]; printf "%s{\"mac\":\"%s\",\"ip\":\"%s\",\"name\":\"%s\"}", (i > 1 ? "," : ""), m, ip[m], j(nm[m]) }; printf "]}\n" }' "$t"
	rm -f "$t"
}
_st_devs_save() {
	local t="$ST_DEVS.tmp" m k n line
	mkdir -p "$ST_VDIR"
	: > "$t"
	printf '%s\n' "$1" | tr -d '\r' | while IFS= read -r line; do
		[ -n "$line" ] || continue
		m="${line%%|*}"; line="${line#*|}"; k="${line%%|*}"; n="${line#*|}"; [ "$n" = "$line" ] && n=""
		if [ -n "$ST_SEC" ]; then case "$m" in all|only) ;; *) continue ;; esac
		else case "$m" in all|byp) ;; *) continue ;; esac; fi
		k="$(_st_dev_key "$k")" || continue
		n="$(printf '%s' "$n" | tr -d '\t"\\' | cut -c1-48)"
		grep -q "	$k	" "$t" 2>/dev/null && continue
		printf '%s\t%s\t%s\t\n' "$m" "$k" "$n" >> "$t"
	done
	sed -i 's/\t$//' "$t"
	if [ -s "$t" ]; then mv -f "$t" "$ST_DEVS"; else rm -f "$t" "$ST_DEVS"; fi
	return 0
}
do_steer_devs() {
	local rc
	_st_phase rules
	rm -f "$ST_STOP_FLAG"
	if [ -n "$ST_SEC" ]; then _rb_say "Секция «$(_st_sec_name "$ST_SEC")», устройства: весь трафик через секцию — $(_st_devs_n all), правила секции только для — $(_st_devs_n only)"
	else _rb_say "Устройства: весь трафик через туннель — $(_st_devs_n all), мимо Steer — $(_st_devs_n byp)"; fi
	if _st_owns "steer-spec" && _st_work; then
		if _st_use_vpn; then _st_spec_quick; else _st_spec_quick_warp; fi
		rc=$?
		if [ "$rc" = 0 ]; then _rb_say "Готово: правила устройств применены, списки сервисов не перекачивались"; return 0; fi
		[ "$rc" = 1 ] && return 1
	fi
	do_steer_apply
}

[ -d "$ST_RUN" ] || mkdir -p "$ST_RUN" 2>/dev/null

_st_splify2_pkg() { grep -qx 'P:luci-app-splify2' /lib/apk/db/installed 2>/dev/null || [ -f /usr/lib/opkg/info/luci-app-splify2.control ]; }
_st_splify2() {
	[ -x /usr/libexec/rpcd/splify2 ] || return 1
	_st_splify2_pkg || [ -f /www/luci-static/resources/view/splify2/home.js ]
}

_st_blocker() {
	local b
	if _st_splify2 && [ "$(stl_spec_whose)" != zm ]; then echo splify2; return; fi
	if b="$(stl_busy_by)"; then echo "Ядро steer ведёт $b — Zapret Manager его не трогает."; return; fi
	if _st_spec_foreign; then echo steer; return; fi
	echo ""
}

_st_spec_foreign() {
	case "$(stl_spec_whose)" in
		foreign) return 0 ;;
		zm) _st_owns "steer-spec" || _st_own "steer-spec" ;;
	esac
	return 1
}

_rb_arch() { awk -F\' '/DISTRIB_ARCH/ {print $2}' /etc/openwrt_release; }
_rb_release() { awk -F\' '/DISTRIB_RELEASE/ {print $2}' /etc/openwrt_release; }

_rb_fetch_pkg() {
	_zm_fetch "$1" "$2" 120 && return 0
	echo "   не скачалось: $1 — $ZM_FETCH_ERR"
	rm -f "$2"; return 1
}

_st_ver_lt() {
	awk -v a="$1" -v b="$2" 'BEGIN { n = split(a, x, "."); m = split(b, y, "."); k = n > m ? n : m
		for (i = 1; i <= k; i++) { if (x[i] + 0 < y[i] + 0) exit 0; if (x[i] + 0 > y[i] + 0) exit 1 }
		exit 1 }'
}

_st_vpn_ok() { stl_has vpn || { stl_present && ! stl_v2; }; }

_st_install_steer() {
	local want cur feat="$*" p
	cur="$(stl_version)"
	if [ -n "$STL_MODS_ONLY" ] && stl_v2; then want="$cur"; else want="$(stl_latest)"; fi
	stl_v2 && _st_ver_lt "$want" "$cur" && want="$cur"
	[ -z "$feat" ] && [ -s "$ST_SUB" ] && feat="$(_st_sub_feats)"
	if stl_v2 && [ "$cur" = "$want" ] && _st_feats_ok $feat; then
		_rb_say "Ядро steer уже последней версии: $cur"
		return 0
	fi
	if stl_present && ! stl_v2; then _rb_say "Ядро steer $cur — переводим на $want"
	elif stl_present && [ "$cur" != "$want" ]; then _rb_say "Ядро steer $cur — обновляем до $want"
	elif stl_v2; then _rb_say "Ставим модули ядра steer $cur для протоколов подписки — само ядро не трогаем"; fi
	if ! stl_engine_install "$want" $feat; then
		[ -n "$STL_MODS_ONLY" ] && stl_v2 && p="$(stl_latest)" && [ "$p" != "$want" ] || return 1
		_rb_say "Модулей для ядра steer $cur на сервере уже нет — обновляем ядро до $p вместе с модулями"
		STL_MODS_ONLY="" stl_engine_install "$p" $feat || return 1
	fi
	if _st_owns "pkg steer" || _st_owns "pkg steer-extended"; then
		sed -i '/^pkg steer$/d; /^pkg steer-extended$/d' "$ST_OWNED"
		STL_NEW="$STL_PKGS"
	fi
	for p in $STL_NEW; do _st_own "pkg $p"; done
	_rb_rpcd_ensure
	return 0
}
_st_sub_feats() { if [ -s "$ST_SUB" ]; then stl_sub_mods "$ST_SUB"; else echo vpn; fi; }
_st_feats_ok() { local f; for f; do stl_has "$f" || return 1; done; return 0; }

_st_awg_loaded() { grep -q '^amneziawg ' /proc/modules 2>/dev/null || [ -d /sys/module/amneziawg ]; }

_awg_board() { ubus call system board 2>/dev/null | jsonfilter -e "$1" 2>/dev/null; }
_awg_rel_ver() { local v; v="$(_awg_board '@.release.version')"; [ -n "$v" ] || v="$(_rb_release)"; echo "$v"; }
_awg_rel_arch() {
	local a; a="$(_awg_board '@.release.arch')"
	[ -n "$a" ] || a="$(_rb_arch)"
	[ -n "$a" ] || a="$(opkg print-architecture 2>/dev/null | awk 'BEGIN { m = 0 } $3 > m { m = $3; a = $2 } END { print a }')"
	[ -n "$a" ] || a="$(apk --print-arch 2>/dev/null)"
	echo "$a"
}
_awg_rel_target() { local t; t="$(_awg_board '@.release.target')"; [ -n "$t" ] || t="$(awk -F\' '/DISTRIB_TARGET/ {print $2}' /etc/openwrt_release)"; echo "$t"; }
_awg_luci_pkg() {
	local v="$1" ma mi pa
	ma="$(echo "$v" | cut -d. -f1)"; mi="$(echo "$v" | cut -d. -f2)"; pa="$(echo "$v" | cut -d. -f3 | sed 's/[^0-9].*//')"
	case "$ma.$mi.$pa" in *[!0-9.]*|*..*|.*|*.) echo luci-app-amneziawg; return ;; esac
	if [ "$ma" -gt 24 ] || { [ "$ma" -eq 24 ] && [ "$mi" -gt 10 ]; } || { [ "$ma" -eq 24 ] && [ "$mi" -eq 10 ] && [ "$pa" -ge 3 ]; } ||
	   { [ "$ma" -eq 23 ] && [ "$mi" -eq 5 ] && [ "$pa" -ge 6 ]; }; then
		echo luci-proto-amneziawg
	else
		echo luci-app-amneziawg
	fi
}
_awg_legacy_feeds() {
	local f
	for f in /etc/opkg/customfeeds.conf /etc/apk/repositories /etc/apk/repositories.d/*.list; do
		[ -f "$f" ] && grep -qF 'slava-shchipunov.github.io/awg-openwrt' "$f" || continue
		_rb_say "Убираем старый фид awg-openwrt из $f — его ключ конфликтует с пакетами 2Grey"
		sed '\|slava-shchipunov\.github\.io/awg-openwrt|d' "$f" > "$f.zmtmp" && cat "$f.zmtmp" > "$f"
		rm -f "$f.zmtmp"
	done
}
_awg_fetch() {
	local e
	for e in "$RAZ" "$([ "$RAZ" = apk ] && echo ipk || echo apk)"; do
		if _rb_fetch_pkg "$1/$2$3.$e" "$ST_RUN/$2.$e" >&2; then echo "$ST_RUN/$2.$e"; return 0; fi
	done
	return 1
}

AWG_KMOD_MANUAL="/etc/zm-awg/kmod-manual"
_awg_kmod_pin_bad() {
	local out
	AWG_KPIN=""; AWG_KMV=""
	if [ "$PKG" = apk ]; then
		out="$(apk add --simulate --allow-untrusted "$1" 2>&1)" && return 1
		AWG_KPIN="$(printf '%s\n' "$out" | sed -n 's/.*kmod-amneziawg-[^[]*\[kernel=\([^]]*\)\].*/\1/p' | head -n1)"
		AWG_KMV="$(printf '%s\n' "$out" | sed -n 's/.*kmod-amneziawg-\([^[ ]*\)\[kernel=.*/\1/p' | head -n1)"
	else
		out="$(opkg install --noaction "$1" 2>&1)"
		AWG_KPIN="$(printf '%s\n' "$out" | sed -n 's/.*\*[[:space:]]*kernel (= *\([^)]*\)).*/\1/p' | head -n1)"
	fi
	[ -n "$AWG_KPIN" ]
}
_awg_kmod_have() {
	_pkg_is_installed kmod-amneziawg && return 0
	[ -s "$AWG_KMOD_MANUAL" ] && [ -f "/lib/modules/$(uname -r)/amneziawg.ko" ]
}
_awg_kmod_ver() {
	if [ -s "$AWG_KMOD_MANUAL" ] && [ -f "/lib/modules/$(uname -r)/amneziawg.ko" ]; then
		awk '{ print $1; exit }' "$AWG_KMOD_MANUAL"
	else
		_awg_pkg_ver kmod-amneziawg
	fi
}
_awg_kmod_manual_rm() {
	[ -f "$AWG_KMOD_MANUAL" ] || return 0
	rm -f "/lib/modules/$(uname -r)/amneziawg.ko" "$AWG_KMOD_MANUAL"
}
_awg_kmod_manual() {
	local f="$1" d="$ST_RUN/kx" ko dir kv cur
	kv="$(uname -r)"; cur="$(_awg_pkg_ver kernel)"
	_rb_warn "Ядро прошивки ($cur) собрано не так, как в официальной OpenWrt (модулю нужно $AWG_KPIN) — пакетный менеджер не даёт поставить модуль"
	_rb_say "Ставим модуль ядра в обход этой проверки"
	if [ "$PKG" != apk ]; then
		$INSTALL --force-depends "$f"
		return
	fi
	rm -rf "$d"; mkdir -p "$d"
	if ! apk extract --allow-untrusted --destination "$d" "$f" >/dev/null 2>&1; then
		echo "   ✗ apk не смог распаковать пакет модуля"
		rm -rf "$d"; return 1
	fi
	ko="$(find "$d/lib/modules" -name amneziawg.ko 2>/dev/null | head -n1)"
	if [ -z "$ko" ]; then
		echo "   ✗ в пакете нет amneziawg.ko"
		rm -rf "$d"; return 1
	fi
	dir="${ko#"$d"/lib/modules/}"; dir="${dir%%/*}"
	if [ "$dir" != "$kv" ]; then
		echo "   ✗ модуль собран для ядра $dir, а у роутера ядро $kv"
		rm -rf "$d"; return 2
	fi
	if ! mkdir -p "/lib/modules/$kv" || ! cp "$ko" "/lib/modules/$kv/amneziawg.ko"; then
		echo "   ✗ не удалось записать модуль в /lib/modules/$kv — мало места на флеше?"
		rm -f "/lib/modules/$kv/amneziawg.ko"; rm -rf "$d"; return 1
	fi
	rm -rf "$d"
	mkdir -p "${AWG_KMOD_MANUAL%/*}"
	echo "${AWG_KMV:-?} $kv" > "$AWG_KMOD_MANUAL"
	_pkg_is_installed kmod-amneziawg || _zm_run 120 apk add --force-non-repository --virtual kmod-amneziawg >/dev/null 2>&1 ||
		{ echo "   ✗ apk не принял отметку о модуле — amneziawg-tools не встанет"; return 1; }
	echo "   ✓ Модуль положен в /lib/modules/$kv"
	return 0
}

_awg_kmod_load() {
	local kv ko dir out dm need p free msg
	_st_awg_loaded && return 0
	_rb_say "Загружаем модуль ядра"
	modprobe amneziawg >/dev/null 2>&1
	_st_awg_loaded && return 0
	kv="$(uname -r)"
	ko="$(find /lib/modules -name 'amneziawg.ko' 2>/dev/null | head -n1)"
	if [ -z "$ko" ]; then
		echo "ОШИБКА: файла модуля amneziawg.ko нет — пакет kmod-amneziawg встал не полностью"
		free="$(df -k /overlay 2>/dev/null | awk 'NR==2 {print $4}')"
		[ -n "$free" ] && [ "$free" -lt 2048 ] && echo "!! На флеше свободно всего $((free / 1024)) МБ — освободите место"
		echo "!! Нажмите «Переустановить»"
		return 1
	fi
	dir="${ko#/lib/modules/}"; dir="${dir%%/*}"
	if [ "$dir" != "$kv" ]; then
		echo "ОШИБКА: модуль собран для ядра $dir, а у роутера ядро $kv"
		echo "!! Прошивка отличается от официальной OpenWrt $(_awg_rel_ver) — готовый модуль к ней не подходит. Поставьте официальную прошивку этой версии"
		return 1
	fi
	for p in kmod-udptunnel4 kmod-udptunnel6 kmod-crypto-lib-chacha20poly1305 kmod-crypto-lib-curve25519; do
		_pkg_is_installed "$p" || need="$need $p"
	done
	if [ -n "$need" ]; then
		_rb_say "Не хватает модулей ядра:$need — ставим"
		$INSTALL $need
		modprobe amneziawg >/dev/null 2>&1
		_st_awg_loaded && return 0
	fi
	for p in udp_tunnel ip6_udp_tunnel libchacha20poly1305 libcurve25519 libcurve25519-generic; do modprobe "$p" >/dev/null 2>&1; done
	out="$(insmod "$ko" 2>&1)"
	_st_awg_loaded && return 0
	dm="$(dmesg 2>/dev/null | grep -i 'amneziawg' | tail -n 3)"
	case "$out $dm" in
		*[Uu]nknown\ symbol*) msg="модулю не хватает функций ядра — в этой прошивке нет нужных модулей" ;;
		*magic*|*[Ii]nvalid\ module\ format*|*disagrees*|*[Ee]xec\ format*) msg="модуль не подходит к ядру этой прошивки" ;;
		*) msg="ядро не приняло модуль" ;;
	esac
	echo "ОШИБКА: $msg"
	[ -n "$out" ] && echo "   insmod: $out"
	[ -n "$dm" ] && printf '%s\n' "$dm" | sed 's/^/   ядро: /'
	echo "!! Ядро $kv, OpenWrt $(_awg_rel_ver), $(_awg_rel_target). Перезагрузка не поможет — нужна официальная прошивка OpenWrt этой версии"
	return 1
}

_st_install_awg() {
	local mode="$1"
	if [ "$mode" != update ] && _st_awg_loaded && command -v awg >/dev/null 2>&1 && _awg_proto_ok; then return 0; fi
	local rel arch tgt sub post luci old_luci base bases m p f ok=0 was_loaded=0 kver0 kver1 need="" force="" why="" mrc
	_st_awg_loaded && was_loaded=1
	kver0="$(_awg_kmod_ver)"
	_awg_kmod_have || need=" kmod-amneziawg"
	[ "$mode" = update ] && need=" kmod-amneziawg"
	if [ "$mode" = update ] || ! _pkg_is_installed amneziawg-tools || ! command -v awg >/dev/null 2>&1; then need="$need amneziawg-tools"; fi
	if [ -n "$need" ]; then
		rel="$(_awg_rel_ver)"; arch="$(_awg_rel_arch)"; tgt="$(_awg_rel_target)"
		sub="${tgt#*/}"; tgt="${tgt%%/*}"
		[ -n "$rel" ] && [ -n "$arch" ] && [ -n "$tgt" ] && [ -n "$sub" ] || { echo "ОШИБКА: не удалось определить версию, архитектуру или цель OpenWrt"; return 1; }
		post="_v${rel}_${arch}_${tgt}_${sub}"
		luci="$(_awg_luci_pkg "$rel")"
		old_luci=luci-app-amneziawg; [ "$luci" = luci-app-amneziawg ] && old_luci=luci-proto-amneziawg
		{ [ "$mode" = update ] || ! _pkg_is_installed "$luci"; } && need="$need $luci"
		[ "$mode" = update ] && [ "$PKG" = opkg ] && force="--force-reinstall"
		_rb_say "Устанавливаем AmneziaWG для OpenWrt $rel ($arch)"
		mkdir -p "$ST_RUN"
		_awg_legacy_feeds
		_rb_say "Обновляем список пакетов"
		$UPDATE || _rb_warn "Список пакетов обновился не полностью — продолжаем"
		bases=""
		for m in $ST_AWG_MIRRORS; do bases="$bases $m/v$rel"; done
		bases="$bases $ST_AWG_MIRROR_FLAT/$rel"
		for base in $bases; do
			ok=1
			for p in $need; do
				_rb_say "Скачиваем $p"
				if f="$(_awg_fetch "$base" "$p" "$post")"; then
					if [ "$p" = "$luci" ] && _pkg_is_installed "$old_luci"; then
						_rb_say "$old_luci конфликтует с $luci — снимаем"
						$DELETE "$old_luci" >&2
					fi
					_rb_say "Ставим $p"
					if [ "$p" = kmod-amneziawg ] && _awg_kmod_pin_bad "$f"; then
						_awg_kmod_manual "$f"; mrc=$?
						if [ "$mrc" = 0 ]; then
							[ "${ST_AWG_OWN:-1}" = 1 ] && _st_own "pkg $p"
						else
							ok=0
							[ "$mrc" = 2 ] && why=kver
							[ "$why" = kver ] || why=pin
						fi
					elif $INSTALL $force "$f"; then
						[ "$p" = kmod-amneziawg ] && rm -f "$AWG_KMOD_MANUAL"
						[ "${ST_AWG_OWN:-1}" = 1 ] && _st_own "pkg $p"
					elif [ "$p" != "$luci" ]; then
						ok=0
					else
						_rb_warn "$p не встал — туннели работают, но не видны в LuCI"
					fi
					rm -f "$f"
				elif [ "$p" = "$luci" ]; then
					_rb_warn "$p для этой версии нет — это не мешает"
				else
					ok=0
				fi
				[ "$ok" = 1 ] || break
			done
			if [ "$ok" = 1 ]; then
				if ! _pkg_is_installed luci-i18n-amneziawg-ru && f="$(_awg_fetch "$base" luci-i18n-amneziawg-ru "$post" 2>/dev/null)"; then
					$INSTALL "$f" >&2 && { [ "${ST_AWG_OWN:-1}" = 1 ] && _st_own "pkg luci-i18n-amneziawg-ru"; }
					rm -f "$f"
				fi
				break
			fi
			[ -n "$why" ] && break
			_rb_warn "Здесь нет всех пакетов — пробуем другой источник"
		done
		_rb_rpcd_ensure
		if [ "$ok" != 1 ]; then
			case "$why" in
				kver)
					echo "ОШИБКА: готовый модуль AmneziaWG собран под ядро официальной OpenWrt $rel, а у роутера ядро $(uname -r)"
					echo "!! Прошивка не официальная (${tgt}/${sub}). Поставьте официальную OpenWrt $rel или прошивку со встроенным AmneziaWG" ;;
				pin)
					echo "ОШИБКА: ядро прошивки ($(_awg_pkg_ver kernel)) отличается от официальной OpenWrt $rel — модуль AmneziaWG поставить не удалось"
					echo "!! Поставьте официальную OpenWrt $rel (${tgt}/${sub}) или прошивку со встроенным AmneziaWG" ;;
				*)
					echo "ОШИБКА: для OpenWrt $rel ($arch, ${tgt}/${sub}) нет готовых пакетов AmneziaWG" ;;
			esac
			return 1
		fi
	fi
	kver1="$(_awg_kmod_ver)"
	if [ "$was_loaded" = 1 ] && [ -n "$kver0" ] && [ "$kver0" != "$kver1" ]; then
		if [ -z "$(awg show interfaces 2>/dev/null)" ] && rmmod amneziawg >/dev/null 2>&1; then
			_rb_say "Модуль ядра AmneziaWG перезагружен ($kver0 → $kver1)"
		else
			_rb_warn "Модуль ядра обновлён ($kver0 → $kver1) — заработает после перезагрузки роутера"
		fi
	fi
	command -v awg >/dev/null 2>&1 || { echo "ОШИБКА: утилита awg не установилась — нажмите «Переустановить»"; return 1; }
	_awg_kmod_load || return 1
	if ! _awg_proto_ok; then
		_rb_say "Перезапускаем сеть — страница может ненадолго пропасть"
		/etc/init.d/network restart >/dev/null 2>&1
		_zm_sleep 8
		_rb_rpcd_ensure
	fi
	return 0
}

_st_warp_field() { sed -n "s/^[[:space:]]*$1[[:space:]]*=[[:space:]]*//p" "$ST_WARP_CONF" | head -n1; }

ST_WARP_API="https://api.cloudflareclient.com/v0a2158/reg https://api.cloudflareclient.com/v0a1922/reg"

_st_warp_conf_write() {
	mkdir -p "$ST_DIR"
	printf '%s\n' \
		"[Interface]" "PrivateKey = $1" "Address = ${3}${4:+, $4}" "MTU = 1280" \
		"S1 = $MIXOMO_AWG_S1" "S2 = $MIXOMO_AWG_S2" "Jc = $MIXOMO_AWG_JC" "Jmin = $MIXOMO_AWG_JMIN" "Jmax = $MIXOMO_AWG_JMAX" \
		"H1 = $MIXOMO_AWG_H1" "H2 = $MIXOMO_AWG_H2" "H3 = $MIXOMO_AWG_H3" "H4 = $MIXOMO_AWG_H4" "I1 = $MIXOMO_AWG_I1" "" \
		"[Peer]" "PublicKey = $2" "AllowedIPs = 0.0.0.0/0" "Endpoint = engage.cloudflareclient.com:4500" "PersistentKeepalive = 25" \
		> "$ST_WARP_CONF"
	chmod 600 "$ST_WARP_CONF"
}

_st_warp_register() {
	[ -s "$ST_WARP_CONF" ] && [ -n "$(_st_warp_field PrivateKey)" ] && return 0
	mkdir -p "$ST_DIR" "$ST_RUN"
	_awg_keys_get || { echo "ОШИБКА: ключи WARP не получены — ни один источник не ответил"; return 1; }
	_st_warp_conf_write "$G_PRIV" "$G_PEER" "$G_V4" "$G_V6"
	_rb_say "Ключи WARP получены"
}

_st_warp_iface_write() {
	local priv addr peer
	priv="$(_st_warp_field PrivateKey)"
	addr="$(_st_warp_field Address | tr ',' '\n' | sed 's/[[:space:]]//g' | grep -v ':' | head -n1)"
	peer="$(_st_warp_field PublicKey)"
	case "$addr" in */*) ;; *) addr="$addr/32" ;; esac
	uci -q delete "network.$ST_WARP_IF"
	uci -q delete "network.${ST_WARP_IF}_peer"
	_st_peers_drop "$ST_WARP_IF"
	uci set "network.$ST_WARP_IF=interface"
	uci set "network.$ST_WARP_IF.proto=amneziawg"
	uci set "network.$ST_WARP_IF.private_key=$priv"
	uci add_list "network.$ST_WARP_IF.addresses=$addr"
	uci set "network.$ST_WARP_IF.mtu=1280"
	uci set "network.$ST_WARP_IF.awg_jc=$MIXOMO_AWG_JC"
	uci set "network.$ST_WARP_IF.awg_jmin=$MIXOMO_AWG_JMIN"
	uci set "network.$ST_WARP_IF.awg_jmax=$MIXOMO_AWG_JMAX"
	uci set "network.$ST_WARP_IF.awg_s1=$MIXOMO_AWG_S1"
	uci set "network.$ST_WARP_IF.awg_s2=$MIXOMO_AWG_S2"
	uci set "network.$ST_WARP_IF.awg_h1=$MIXOMO_AWG_H1"
	uci set "network.$ST_WARP_IF.awg_h2=$MIXOMO_AWG_H2"
	uci set "network.$ST_WARP_IF.awg_h3=$MIXOMO_AWG_H3"
	uci set "network.$ST_WARP_IF.awg_h4=$MIXOMO_AWG_H4"
	uci set "network.$ST_WARP_IF.awg_i1=$MIXOMO_AWG_I1"
	uci set "network.${ST_WARP_IF}_peer=amneziawg_$ST_WARP_IF"
	uci set "network.${ST_WARP_IF}_peer.description=WARP ${ST_WARP_IF#zmwarp}"
	uci set "network.${ST_WARP_IF}_peer.public_key=$peer"
	uci add_list "network.${ST_WARP_IF}_peer.allowed_ips=0.0.0.0/0"
	uci set "network.${ST_WARP_IF}_peer.route_allowed_ips=0"
	uci set "network.${ST_WARP_IF}_peer.persistent_keepalive=25"
	uci set "network.${ST_WARP_IF}_peer.endpoint_host=$1"
	uci set "network.${ST_WARP_IF}_peer.endpoint_port=$2"
	uci commit network
	_st_own "net $ST_WARP_IF"
}

_st_warp_zone() {
	local want i
	want="$({ for i in $(_st_wifs_every); do { _st_owns "net $i" || _st_wifs_all | grep -qx "$i"; } && echo "$i"; done; _st_ext_zoneless && echo "$ST_WIF1"; _st_secs_zoneless; } | awk '!x[$0]++' | tr '\n' ' ' | sed 's/ $//')"
	if [ "$(uci -q get "firewall.$ST_WARP_ZONE")" = "zone" ] && [ "$(uci -q get "firewall.$ST_WARP_ZONE.network")" != "$want" ]; then
		uci -q delete "firewall.$ST_WARP_ZONE.network"
		for i in $want; do uci add_list "firewall.$ST_WARP_ZONE.network=$i"; done
		uci commit firewall
		/etc/init.d/firewall reload >/dev/null 2>&1
	fi
	if [ "$(uci -q get "firewall.$ST_WARP_ZONE")" != "zone" ]; then
		uci set "firewall.$ST_WARP_ZONE=zone"
		uci set "firewall.$ST_WARP_ZONE.name=$ST_WARP_ZONE"
		for i in $want; do uci add_list "firewall.$ST_WARP_ZONE.network=$i"; done
		uci set "firewall.$ST_WARP_ZONE.input=REJECT"
		uci set "firewall.$ST_WARP_ZONE.output=ACCEPT"
		uci set "firewall.$ST_WARP_ZONE.forward=REJECT"
		uci set "firewall.$ST_WARP_ZONE.masq=1"
		uci set "firewall.$ST_WARP_ZONE.mtu_fix=1"
		uci set "firewall.${ST_WARP_ZONE}_fwd=forwarding"
		uci set "firewall.${ST_WARP_ZONE}_fwd.src=$(_zm_lan_zone)"
		uci set "firewall.${ST_WARP_ZONE}_fwd.dest=$ST_WARP_ZONE"
		uci commit firewall
		_st_own "fw $ST_WARP_ZONE"
		/etc/init.d/firewall reload >/dev/null 2>&1
	fi
	_zm_fwd_fix "${ST_WARP_ZONE}_fwd"
}

ST_EXT_FWD="zmwarp_ext"
_st_secs_zoneless() { local i z; for i in $(_st_tun_ifaces); do z="$(_zm_zone_of_net "$i")"; { [ -z "$z" ] || [ "$z" = "$ST_WARP_ZONE" ]; } && echo "$i"; done; }
_st_fwd_has() {
	local f
	for f in $(uci -q -X show firewall | sed -n "s/^firewall\.\([^.=]*\)=forwarding\$/\1/p"); do
		[ "$f" = "$3" ] && continue
		[ "$(uci -q get "firewall.$f.src")" = "$1" ] && [ "$(uci -q get "firewall.$f.dest")" = "$2" ] && return 0
	done
	return 1
}
_st_secs_fw() {
	local i z lz s r keep="" ch=0 zl=""
	lz="$(_zm_lan_zone)"
	_st_tun_hook
	for i in $(_st_tun_ifaces); do
		z="$(_zm_zone_of_net "$i")"
		if [ -z "$z" ] || [ "$z" = "$ST_WARP_ZONE" ]; then zl=1; continue; fi
		s="$(_st_zone_sec "$z")"
		if [ "$z" = "$lz" ]; then
			[ -n "$s" ] && [ "$(uci -q get "firewall.$s.masq")" != 1 ] && _rb_warn "$i стоит в зоне локальной сети «$z» без маскарадинга (NAT) — сайты через него не откроются. Уберите $i из этой зоны (Сеть → Межсетевой экран)"
			continue
		fi
		r="zmsec_$i"
		if ! _st_fwd_has "$lz" "$z" "$r"; then
			keep="$keep $r"
			if [ "$(uci -q get "firewall.$r.dest")" != "$z" ] || [ "$(uci -q get "firewall.$r.src")" != "$lz" ]; then
				uci -q delete "firewall.$r"
				uci set "firewall.$r=forwarding"
				uci set "firewall.$r.src=$lz"
				uci set "firewall.$r.dest=$z"
				_st_own "fw $r"
				ch=1
				_rb_say "Разрешаем устройствам сети ходить в зону «$z» интерфейса $i"
			fi
		fi
		[ -n "$s" ] && [ "$(uci -q get "firewall.$s.masq")" != 1 ] && _rb_warn "В зоне «$z» выключен маскарадинг (NAT) — без него сайты через $i не откроются. Включите его в Сеть → Межсетевой экран"
	done
	for r in $(sed -n 's/^fw \(zmsec_[A-Za-z0-9_]*\)$/\1/p' "$ST_OWNED" 2>/dev/null); do
		case " $keep " in *" $r "*) continue ;; esac
		uci -q delete "firewall.$r"
		sed -i "\\|^fw $r\$|d" "$ST_OWNED" 2>/dev/null
		ch=1
	done
	[ "$ch" = 1 ] && { uci commit firewall; /etc/init.d/firewall reload >/dev/null 2>&1; }
	if [ -n "$zl" ] || [ "$(uci -q get "firewall.$ST_WARP_ZONE")" = zone ]; then _st_warp_zone; fi
	_st_lan_fw
	return 0
}
_st_ext_zoneless() {
	local z
	_st_warp_ext || return 1
	z="$(_zm_zone_of_net "$ST_WIF1")"
	[ -z "$z" ] || [ "$z" = "$ST_WARP_ZONE" ]
}
_st_zone_sec() { local z; for z in $(uci -q -X show firewall | sed -n "s/^firewall\.\([^.=]*\)=zone\$/\1/p"); do [ "$(uci -q get "firewall.$z.name")" = "$1" ] && { echo "$z"; return 0; }; done; return 1; }
_st_ext_fwd() {
	local i="$ST_WIF1" z s lz f has=""
	_st_warp_ext || return 0
	z="$(_zm_zone_of_net "$i")"
	if [ -z "$z" ] || [ "$z" = "$ST_WARP_ZONE" ]; then _st_ext_release_fwd; return 0; fi
	lz="$(_zm_lan_zone)"
	s="$(_st_zone_sec "$z")"
	if [ "$z" = "$lz" ]; then
		_st_ext_release_fwd
		[ -n "$s" ] && [ "$(uci -q get "firewall.$s.masq")" != 1 ] && _rb_warn "$i стоит в зоне локальной сети «$z» без маскарадинга (NAT) — сайты через него не откроются. Уберите $i из этой зоны (Сеть → Межсетевой экран), Steer сам добавит его в свою зону"
		return 0
	fi
	for f in $(uci -q -X show firewall | sed -n "s/^firewall\.\([^.=]*\)=forwarding\$/\1/p"); do
		[ "$f" = "$ST_EXT_FWD" ] && continue
		[ "$(uci -q get "firewall.$f.src")" = "$lz" ] && [ "$(uci -q get "firewall.$f.dest")" = "$z" ] && has=1
	done
	if [ -n "$has" ]; then
		_st_ext_release_fwd
	elif [ "$(uci -q get "firewall.$ST_EXT_FWD.dest")" != "$z" ] || [ "$(uci -q get "firewall.$ST_EXT_FWD.src")" != "$lz" ]; then
		uci -q delete "firewall.$ST_EXT_FWD"
		uci set "firewall.$ST_EXT_FWD=forwarding"
		uci set "firewall.$ST_EXT_FWD.src=$lz"
		uci set "firewall.$ST_EXT_FWD.dest=$z"
		uci commit firewall
		_st_own "fw $ST_EXT_FWD"
		/etc/init.d/firewall reload >/dev/null 2>&1
		_rb_say "Разрешаем устройствам сети ходить в зону «$z» интерфейса $i"
	fi
	[ -n "$s" ] && [ "$(uci -q get "firewall.$s.masq")" != 1 ] && _rb_warn "В зоне «$z» выключен маскарадинг (NAT) — без него сайты через $i не откроются. Включите его в Сеть → Межсетевой экран"
	return 0
}
_st_ext_release_fwd() {
	[ "$(uci -q get "firewall.$ST_EXT_FWD")" = forwarding ] && _st_owns "fw $ST_EXT_FWD" || return 0
	uci -q delete "firewall.$ST_EXT_FWD"
	uci commit firewall
	sed -i "\|^fw $ST_EXT_FWD\$|d" "$ST_OWNED" 2>/dev/null
	/etc/init.d/firewall reload >/dev/null 2>&1
	return 0
}
_st_ext_leave() {
	local i
	_st_warp_ext || return 0
	i="$(_st_ext_if)"
	_st_ext_release_fwd
	_rb_say "Интерфейс $i больше не используется Steer — он остаётся на вкладке AmneziaWG как был"
}

_zm_fwd_fix() {
	local lz
	[ "$(uci -q get "firewall.$1")" = forwarding ] || return 0
	lz="$(_zm_lan_zone)"
	[ "$(uci -q get "firewall.$1.src")" = "$lz" ] && return 0
	uci set "firewall.$1.src=$lz"
	uci commit firewall
	/etc/init.d/firewall reload >/dev/null 2>&1
}

_st_peers_drop() {
	local p
	for p in $(uci -q -X show network | sed -n "s/^network\.\([^.=]*\)=amneziawg_$1\$/\1/p"); do uci -q delete "network.$p"; done
}

_st_warp_is_ru() { case " $ST_RU_COLOS " in *" $1 "*) return 0 ;; esac; [ "$2" = RU ] && return 0; return 1; }
_st_if_ru() {
	local g
	_st_warp_is_ru "$2" && return 0
	g="$(awk -v i="$1" -v c="$2" '$1 == i && ($2 == c || c == "" || c == "?") { print $4; exit }' "$ST_WARP_GEO" 2>/dev/null)"
	[ "$g" = RU ]
}

_st_wif() { [ "$1" = 1 ] && echo "$ST_WIF1" || echo "zmwarp$1"; }
_st_wconf() { [ "$1" = 1 ] && echo "$ST_WCONF1" || echo "$ST_DIR/warp$1.conf"; }
_st_with() {
	local n="$1" oi="$ST_WARP_IF" oc="$ST_WARP_CONF" rc
	shift
	ST_WARP_IF="$(_st_wif "$n")"; ST_WARP_CONF="$(_st_wconf "$n")"
	"$@"; rc=$?
	ST_WARP_IF="$oi"; ST_WARP_CONF="$oc"
	return $rc
}
_st_wifs_all() { local n=1; while [ "$n" -le "$ST_WARP_N" ]; do _st_wif "$n"; n=$((n + 1)); done; }
_st_wifs_auto() { echo zmwarp; local n=2; while [ "$n" -le "$ST_WARP_MAX" ]; do echo "zmwarp$n"; n=$((n + 1)); done; }
_st_wifs_every() { _st_wifs_auto; echo "$ST_OWN_IF"; }
_st_warp_first() {
	local i
	[ -s "$ST_WARP_UP" ] && while read -r i _; do [ -d "/sys/class/net/$i" ] && { echo "$i"; return 0; }; done < "$ST_WARP_UP"
	echo "$ST_WARP_IF"
}

ST_WARP_POOLS="188.114.96. 188.114.97. 188.114.98. 188.114.99. 162.159.192. 162.159.193. 162.159.195. 8.34.70. 8.34.146. 8.39.214. 8.39.204. 8.6.112. 8.35.211. 8.39.125. 8.47.69."
ST_WARP_PORTS="2408 500 1701 4500"
ST_WARP_PORTS_EXT="854 859 864 878 880 890 891 894 903 908 928 934 939 942 943 945 946 955 968 987 988 1002 1010 1014 1018 1070 1074 1180 1387 1843 2371 2506 3138 3476 3581 3854 4177 4198 4233 5279 5956 7103 7152 7156 7281 7559 8319 8742 8854 8886"
ST_WARP_RAND=10
ST_WARP_HS_WAIT=8
ST_WARP_BURST=10
ST_WARP_TORN=3

_st_warp_link() {
	local dev="$1" peer="$2" push w=0 hs
	awg set "$dev" peer "$peer" remove 2>/dev/null
	awg set "$dev" peer "$peer" endpoint "$3:$4" allowed-ips 0.0.0.0/0 persistent-keepalive 25 2>/dev/null || return 1
	ping -I "$dev" -c 1 -W 2 1.1.1.1 >/dev/null 2>&1 &
	push=$!
	while [ "$w" -lt $((ST_WARP_HS_WAIT * 4)) ]; do
		hs=$(awg show "$dev" latest-handshakes 2>/dev/null | awk '{print $2; exit}')
		if [ "${hs:-0}" -gt 0 ] 2>/dev/null; then wait "$push" 2>/dev/null; return 0; fi
		w=$((w + 1))
		sleep 0.25 2>/dev/null || sleep 1
	done
	kill "$push" 2>/dev/null; wait "$push" 2>/dev/null
	return 1
}

_st_warp_probe() {
	local out
	out=$(ping -I "$1" -c "$ST_WARP_BURST" -i 0.2 -W 2 -w 8 1.1.1.1 2>/dev/null)
	case "$out" in *"packet loss"*) ;; *) out=$(ping -I "$1" -c 5 -W 2 -w 10 1.1.1.1 2>/dev/null) ;; esac
	case "$out" in *" 100% packet loss"*|'') out=$(ping -I "$1" -c "$ST_WARP_BURST" -i 0.2 -W 2 -w 8 8.8.8.8 2>/dev/null) ;; esac
	printf '%s\n' "$out" | awk -v t="$ST_WARP_TORN" '
		/seq=[0-9]/ { s = $0; sub(/.*seq=/, "", s); sub(/[^0-9].*/, "", s); s += 0; if (!got++ || s > hi) hi = s }
		/packets transmitted/ { tx = $1 + 0 }
		/packet loss/ { l = $0; sub(/%.*/, "", l); sub(/.*[^0-9]/, "", l); loss = l + 0; have = 1 }
		/min\/avg/ { v = $0; sub(/.*= */, "", v); split(v, a, "/"); rtt = int(a[2]) }
		END {
			if (!have) loss = 100
			torn = (got > 0 && tx > 0 && tx - 1 - hi >= t) ? 1 : 0
			printf "%d %d %d\n", loss, (got > 0 && rtt > 0 ? rtt : (got > 0 ? 1 : 99999)), torn
		}'
}

_cf_meta() {
	local j c s k t
	j=$(curl -s ${1:+--interface "$1"} --connect-timeout 4 --max-time 8 -H 'Referer: https://speed.cloudflare.com' https://speed.cloudflare.com/meta 2>/dev/null)
	case "$j" in *'"colo"'*) ;; *) return 1 ;; esac
	c="$(jsonfilter -s "$j" -e '@.colo.iata' 2>/dev/null)"
	[ -n "$c" ] || c="$(jsonfilter -s "$j" -e '@.colo' 2>/dev/null | grep -E '^[A-Z]{3}$')"
	[ -n "$c" ] || return 1
	s="$(jsonfilter -s "$j" -e '@.country' 2>/dev/null)"
	k="$(jsonfilter -s "$j" -e '@.colo.cca2' 2>/dev/null)"
	t="$(jsonfilter -s "$j" -e '@.colo.city' 2>/dev/null | tr -d '"\\\t\r\n')"
	echo "$c ${s:--} ${k:--} ${t:--}"
}

_st_warp_geo() {
	local i m
	mkdir -p "$ST_DIR"
	for i in "$@"; do
		[ -d "/sys/class/net/$i" ] || continue
		m="$(_cf_meta "$i")" || continue
		{ grep -v "^$i " "$ST_WARP_GEO" 2>/dev/null; echo "$i $m"; } > "$ST_WARP_GEO.tmp" && mv "$ST_WARP_GEO.tmp" "$ST_WARP_GEO"
	done
	return 0
}
_st_geo_get() { awk -v i="$1" '$1 == i { $1 = ""; sub(/^ /, ""); print; exit }' "$ST_WARP_GEO" 2>/dev/null; }
_st_geo_line() {
	local i c out="" g
	while read -r i c; do
		[ -n "$i" ] || continue
		g="$(_st_geo_get "$i")"
		set -- $g
		[ "$1" = "$c" ] && [ -n "$2" ] && [ "$2" != - ] && out="${out:+$out, }$2 ($c)"
	done < "$ST_WARP_UP" 2>/dev/null
	echo "$out"
}

_st_warp_i1() {
	local f="$ST_RUN/i1.$1" rc
	mkdir -p "$ST_RUN"
	uci -q set "network.$1.awg_i1=$2"
	awg set "$1" i1 "$2" >/dev/null 2>&1 && return 0
	awg showconf "$1" > "$f" 2>/dev/null || { rm -f "$f"; return 1; }
	awk -v m="$2" '/^\[Interface\]/ { print; print "I1 = " m; next } /^I1[ \t]*=/ { next } { print }' "$f" > "$f.n"
	awg setconf "$1" "$f.n" >/dev/null 2>&1; rc=$?
	rm -f "$f" "$f.n"
	return $rc
}

_st_colo_of() {
	local c
	c=$(curl -sI --interface "$1" --max-time 8 -H 'Host: www.cloudflare.com' http://104.16.132.229/ 2>/dev/null |
		sed -n 's/^[Cc][Ff]-[Rr][Aa][Yy]: *[0-9a-f]*-\([A-Z][A-Z][A-Z]\).*/\1/p' | head -n1)
	[ -n "$c" ] || c=$(curl -s --interface "$1" --connect-timeout 5 --max-time 8 https://1.1.1.1/cdn-cgi/trace 2>/dev/null |
		sed -n 's/^colo=//p' | head -n1)
	[ -n "$c" ] && echo "$c"
}

ST_WARP_PORTS_TTL=43200

ST_WARP_PAR=8
ST_WARP_PRE_WAIT=6
_st_warp_pre_clean() { local i=1; while [ "$i" -le "$ST_WARP_PAR" ]; do ip link del "zmws$i" >/dev/null 2>&1; i=$((i + 1)); done; }
_st_warp_pre1() {
	local dev="$1" ep="$2" key="$3" addr="$4" i1="$5" out="$6" conf="$6.conf" i=0 hs
	ip link del "$dev" >/dev/null 2>&1
	ip link add dev "$dev" type amneziawg >/dev/null 2>&1 || { echo fail > "$out"; return 0; }
	ip addr add "$addr" dev "$dev" >/dev/null 2>&1
	ip link set "$dev" up >/dev/null 2>&1
	( umask 077; printf '%s\n' "[Interface]" "PrivateKey = $key" \
		"Jc = $MIXOMO_AWG_JC" "Jmin = $MIXOMO_AWG_JMIN" "Jmax = $MIXOMO_AWG_JMAX" "S1 = $MIXOMO_AWG_S1" "S2 = $MIXOMO_AWG_S2" \
		"H1 = $MIXOMO_AWG_H1" "H2 = $MIXOMO_AWG_H2" "H3 = $MIXOMO_AWG_H3" "H4 = $MIXOMO_AWG_H4" ${i1:+"I1 = $i1"} "" \
		"[Peer]" "PublicKey = $AWG_WARP_PEER" "AllowedIPs = 0.0.0.0/0" "Endpoint = $ep" "PersistentKeepalive = 5" > "$conf" )
	if ! awg setconf "$dev" "$conf" >/dev/null 2>&1; then
		if [ -z "$i1" ] || ! sed -i '/^I1 = /d' "$conf" || ! awg setconf "$dev" "$conf" >/dev/null 2>&1; then
			rm -f "$conf"; ip link del "$dev" >/dev/null 2>&1; echo fail > "$out"; return 0
		fi
	fi
	rm -f "$conf"
	while [ "$i" -lt $((ST_WARP_PRE_WAIT * 4)) ]; do
		hs=$(awg show "$dev" latest-handshakes 2>/dev/null | awk '{ print $2; exit }')
		[ "${hs:-0}" -gt 0 ] 2>/dev/null && { echo ok > "$out"; break; }
		i=$((i + 1))
		sleep 0.25 2>/dev/null || sleep 1
	done
	[ -s "$out" ] || echo no > "$out"
	ip link del "$dev" >/dev/null 2>&1
	return 0
}
_st_warp_prescreen() {
	local dev="$1" key addr i1 d="$ST_RUN/pre.$$" k=0 n=0 ep fail=0
	shift
	command -v awg >/dev/null 2>&1 || return 2
	key="$(awg show "$dev" private-key 2>/dev/null)"
	[ -n "$key" ] || return 2
	addr="$(uci -q get "network.$dev.addresses" | tr ' ' '\n' | grep -v ':' | head -n1)"
	[ -n "$addr" ] || addr="$AWG_BOOT_IP/32"
	i1="$(uci -q get "network.$dev.awg_i1")"
	rm -rf "$d"; mkdir -p "$d"
	for ep; do
		_st_stopped && break
		k=$((k + 1)); n=$((n + 1))
		_st_warp_pre1 "zmws$n" "$ep" "$key" "$addr" "$i1" "$d/$k" &
		[ "$n" -ge "$ST_WARP_PAR" ] && { wait; n=0; }
	done
	wait
	k=0
	for ep; do
		k=$((k + 1))
		case "$(cat "$d/$k" 2>/dev/null)" in ok) echo "$ep" ;; fail|'') fail=$((fail + 1)) ;; esac
	done
	rm -rf "$d"
	_st_warp_pre_clean
	[ "$k" -gt 0 ] && [ "$fail" -ge "$k" ] && return 2
	return 0
}

_st_warp_ports() {
	local f="$ST_DIR/warp.ports" ok="" p list="$ST_WARP_PORTS" t
	if [ -s "$f" ]; then
		t="$(date -r "$f" +%s 2>/dev/null || echo 0)"
		[ $(( $(date +%s) - t )) -lt "$ST_WARP_PORTS_TTL" ] && { cat "$f"; return 0; }
		rm -f "$f"
	fi
	local ST_WARP_HS_WAIT="$ST_WARP_HS_WAIT" eps="" got rc
	[ "$4" = ext ] && { list="$ST_WARP_PORTS_EXT"; ST_WARP_HS_WAIT=3; }
	for p in $list; do eps="$eps $3:$p"; done
	got="$(_st_warp_prescreen "$1" $eps)"; rc=$?
	if [ "$rc" = 0 ]; then
		for p in $(printf '%s\n' $got | sed 's/.*://'); do
			ok="${ok:+$ok }$p"
			[ "$(echo "$ok" | wc -w)" -ge "$ST_WARP_MAX" ] && break
		done
	fi
	if [ "$rc" = 2 ]; then
		for p in $list; do
			_st_stopped && return 1
			_st_warp_link "$1" "$2" "$3" "$p" && ok="${ok:+$ok }$p"
			[ "$(echo "$ok" | wc -w)" -ge "$ST_WARP_MAX" ] && break
		done
	fi
	[ -n "$ok" ] || return 1
	echo "$ok" > "$f"
	echo "$ok"
}

_st_port_order() {
	local n
	case "$1" in zmwarp) n=0 ;; zmwarp[0-9]*) n=$(( ${1#zmwarp} - 1 )) ;; *) n=0 ;; esac
	[ "$n" -ge 0 ] 2>/dev/null || n=0
	echo $2 | awk -v n="$n" '{ c = NF; if (!c) exit; s = n % c; o = ""; for (i = 0; i < c; i++) o = o (i ? " " : "") $((s + i) % c + 1); print o }'
}

_st_warp_scan1() {
	local dev="$1" peer="$2" busy=" $3 " busyip=" $4 " pool="$5" quick="$6" r="$ST_RUN/scan.$1" cand ip ports port loss rtt torn colo seen city meta pick f cls ccc
	local tried=0 lim=3 ST_WARP_HS_WAIT="$ST_WARP_HS_WAIT"
	[ -n "$quick" ] && { lim=1; ST_WARP_HS_WAIT=4; }
	mkdir -p "$ST_RUN"
	: > "$r"; : > "$r.same"; : > "$r.nc"; : > "$r.ru"; : > "$r.notls"; : > "$r.torn"
	cand=$(awk -v p="$ST_WARP_POOLS" -v n="$ST_WARP_RAND" -v q="$quick" 'BEGIN { srand(); c = split(p, a, " ");
		if (q != "") { for (i = 1; i <= 4; i++) print a[i] "1"; for (i = 0; i < 2; i++) print a[int(rand() * c) + 1] int(rand() * 253) + 2; exit }
		for (i = 1; i <= c; i++) print a[i] "1"; for (i = 0; i < n; i++) print a[int(rand() * c) + 1] int(rand() * 253) + 2 }')
	ports=""
	for ip in $cand; do
		[ -n "$ports" ] && break
		[ "$tried" -ge "$lim" ] && break
		tried=$((tried + 1))
		ports="$(_st_warp_ports "$dev" "$peer" "$ip")"
	done
	if [ -z "$ports" ] && [ -z "$quick" ] && ! _st_stopped; then
		echo "   основные порты ($ST_WARP_PORTS) молчат — проверяем 50 запасных портов WARP, это до минуты" >&2
		ports="$(_st_warp_ports "$dev" "$peer" "$(echo "$cand" | head -n1)" ext)"
		[ -n "$ports" ] && echo "   открыты запасные порты: $ports" >&2
	fi
	[ -n "$ports" ] || { echo "!! WARP: ни один порт не ответил — ни основные ($ST_WARP_PORTS), ни запасные" >&2; return 1; }
	ports="$(_st_port_order "$dev" "$ports")"
	local alt altleft=2 p0 p eps="" alive
	p0="${ports%% *}"
	for ip in $cand; do case "$busyip" in *" $ip "*) ;; *) eps="$eps $ip:$p0" ;; esac; done
	if [ -n "$eps" ] && alive="$(_st_warp_prescreen "$dev" $eps)"; then
		alive="$(printf '%s\n' $alive | sed 's/:[0-9]*$//')"
		[ -n "$alive" ] && echo "   рукопожатие разом: ответили $(echo $alive | wc -w) из $(echo $eps | wc -w) точек" >&2
		cand="$(printf '%s\n' $alive $cand | awk 'NF && !s[$0]++')"
	fi
	for ip in $cand; do
		_st_stopped && return 1
		case "$busyip" in *" $ip "*) continue ;; esac
		port="$p0"
		if ! _st_warp_link "$dev" "$peer" "$ip" "$port"; then
			alt=""
			if [ "$altleft" -gt 0 ]; then
				altleft=$((altleft - 1))
				for p in ${ports#"$p0"}; do
					_st_stopped && return 1
					_st_warp_link "$dev" "$peer" "$ip" "$p" && { alt="$p"; break; }
				done
			fi
			[ -n "$alt" ] || { echo "   $ip:$port — рукопожатия нет" >&2; continue; }
			echo "   $ip:$port — рукопожатия нет, через порт $alt есть" >&2
			port="$alt"
		fi
		set -- $(_st_warp_probe "$dev"); loss="$1"; rtt="$2"; torn="$3"
		[ "$loss" -ge 100 ] 2>/dev/null && { echo "   $ip:$port — туннель молчит" >&2; continue; }
		if [ "$torn" = 1 ]; then
			echo "$loss $rtt $ip $port ?" >> "$r.torn"
			echo "   $ip:$port — трафик пошёл и оборвался: так DPI рвёт туннель" >&2
			[ "$(grep -c . "$r.torn")" -ge 6 ] && ! [ -s "$r" ] && ! [ -s "$r.same" ] && ! [ -s "$r.ru" ] && break
			continue
		fi
		seen=""; city=""; ccc=""
		if meta="$(_cf_meta "$dev")"; then
			set -- $meta; colo="$1"; seen="$2"; ccc="$3"; shift 3; city="$*"
			[ "$seen" = - ] && seen=""; [ "$city" = - ] && city=""
		else
			colo="$(_st_colo_of "$dev")"
			if [ -z "$colo" ]; then
				if ping -I "$dev" -c 2 -W 2 1.1.1.1 >/dev/null 2>&1; then
					echo "$loss $rtt $ip $port ?" >> "$r.nc"
					echo "   $ip:$port — пинг идёт ($rtt мс), но веб-запросы через туннель не проходят" >&2
				else
					echo "$loss $rtt $ip $port ?" >> "$r.torn"
					echo "   $ip:$port — пинг прошёл, а на первом веб-запросе туннель оборвался: так DPI рвёт туннель" >&2
					[ "$(grep -c . "$r.torn")" -ge 6 ] && ! [ -s "$r" ] && ! [ -s "$r.same" ] && ! [ -s "$r.ru" ] && break
				fi
				continue
			fi
			if ! _zm_if_web "$dev"; then
				echo "$loss $rtt $ip $port $colo" >> "$r.notls"; echo "   $ip:$port — колония $colo, но HTTPS через туннель не проходит" >&2; continue
			fi
		fi
		echo "   $ip:$port — потери $loss%, $rtt мс, колония $colo${city:+ ($city)}${seen:+, сайты видят $seen}" >&2
		if _st_warp_is_ru "$colo" "$ccc"; then echo "$loss $rtt $ip $port $colo" >> "$r.ru"; continue; fi
		case "$busy" in *" $colo "*) echo "$loss $rtt $ip $port $colo" >> "$r.same"; continue ;; esac
		echo "$loss $rtt $ip $port $colo" >> "$r"
		[ "$(grep -c . "$r")" -ge 3 ] && break
	done
	if [ -n "$pool" ]; then
		for f in "$r" "$r.same" "$r.notls" "$r.nc"; do
			[ -s "$f" ] || continue
			case "$f" in *.ru) cls=1 ;; *.notls) cls=2 ;; *.nc) cls=3 ;; *) cls=0 ;; esac
			awk -v c="$cls" '{ printf "%d %s %s %s\n", c * 100000000 + $1 * 100000 + $2, $3, $4, $5 }' "$f"
		done | sort -n | awk '{ print $2, $3, $4, $1 }' > "$pool"
	fi
	[ -s "$r.ru" ] && ! [ -s "$r" ] && ! [ -s "$r.same" ] &&
		echo "   ответили только российские узлы ($(awk '{ print $5 }' "$r.ru" | sort -u | tr '\n' ' ' | sed 's/ $//')) — их не берём: заблокированное через них не открывается" >&2
	for f in "$r" "$r.same" "$r.notls" "$r.nc"; do
		[ -s "$f" ] || continue
		case "$f" in *.ru) cls=1 ;; *.notls) cls=2 ;; *.nc) cls=3 ;; *) cls=0 ;; esac
		pick=$(awk -v c="$cls" '{ k = c * 100000000 + $1 * 100000 + $2; printf "%d\t%s %s %s %d\n", k, $3, $4, $5, k }' "$f" |
			sort -n | head -n1 | cut -f2)
		case "$f" in
			*.same) echo "   другой колонии нет — та же, но через другой адрес" >&2 ;;
			*.notls) echo "!! ни через одну точку не проходит HTTPS" >&2 ;;
			*.nc) echo "!! ни через одну точку не проходят веб-запросы, только пинг" >&2 ;;
		esac
		echo "$pick"
		return 0
	done
	[ -s "$r.torn" ] && echo "!! через все ответившие точки ($(grep -c . "$r.torn")) DPI обрывает туннель — нужна другая маска" >&2
	return 1
}

_st_warp_scan() {
	local dev="$1" peer="$2" busy="$3" busyip="$4" pool="$5" orig name mask got fall=""
	if got="$(_st_warp_scan1 "$dev" "$peer" "$busy" "$busyip" "$pool")"; then
		set -- $got
		[ "${4:-0}" -lt 100000000 ] 2>/dev/null && { echo "$got"; return 0; }
		fall="$got"
		[ -n "$pool" ] && cp -f "$pool" "$pool.fall" 2>/dev/null
	fi
	_st_stopped && { [ -n "$fall" ] && echo "$fall"; [ -n "$fall" ]; return; }
	orig="$(uci -q get "network.$dev.awg_i1")"
	[ -n "$orig" ] || { [ -n "$fall" ] && echo "$fall"; [ -n "$fall" ]; return; }
	if [ -n "$fall" ]; then
		echo "   хорошей зарубежной точки нет — пробуем другие маски первого пакета (I1), запасная точка остаётся" >&2
	else
		echo "   меняем маску первого пакета (I1) и пробуем ещё раз" >&2
	fi
	for name in $AWG_I1_SET; do
		_st_stopped && break
		mask="$(_awg_i1 "$name")"
		[ -n "$mask" ] && [ "$mask" != "$orig" ] || continue
		_st_warp_i1 "$dev" "$mask" || { echo "   модуль AmneziaWG не даёт сменить маску на лету" >&2; break; }
		echo "   маска $(_awg_mask_name "$mask"):" >&2
		if got="$(_st_warp_scan1 "$dev" "$peer" "$busy" "$busyip" "$pool" quick)" && set -- $got && [ "${4:-0}" -lt 100000000 ] 2>/dev/null; then
			printf '%s\n' "$mask" > "$ST_RUN/warp.mask"
			echo "   маска $(_awg_mask_name "$mask") проходит — она останется у туннеля" >&2
			[ -n "$pool" ] && rm -f "$pool.fall"
			echo "$got"
			return 0
		fi
	done
	_st_warp_i1 "$dev" "$orig" >/dev/null 2>&1
	if [ -n "$fall" ]; then
		[ -n "$pool" ] && [ -s "$pool.fall" ] && mv -f "$pool.fall" "$pool"
		set -- $fall
		case "$(( ${4:-0} / 100000000 ))" in
			1) echo "   маски не помогли — беру российскую колонию $3: блокировки через неё не снимаются" >&2 ;;
			2) echo "   маски не помогли — беру точку, где HTTPS не проходит" >&2 ;;
			*) echo "   маски не помогли — оставляю точку, где идёт хотя бы пинг" >&2 ;;
		esac
		echo "$fall"
		return 0
	fi
	return 1
}

_st_warp_from_pool() {
	local dev="$1" peer="$2" busy=" $3 " busyip=" $4 " f="$5" ip port colo k pass good isbusy pp
	[ -s "$f" ] || return 1
	[ -s "$ST_RUN/warp.mask" ] && _st_warp_i1 "$dev" "$(cat "$ST_RUN/warp.mask")" >/dev/null 2>&1
	for pass in 1 2 3 4; do
		while read -r ip port colo k <&3; do
			[ -n "$ip" ] || continue
			case "$busyip" in *" $ip "*) continue ;; esac
			good=0; [ "$k" -lt 100000000 ] 2>/dev/null && good=1
			isbusy=0; case "$busy" in *" $colo "*) isbusy=1 ;; esac
			case "$pass$good$isbusy" in 110|211|300|401) ;; *) continue ;; esac
			_st_stopped && return 1
			pp="$(_st_port_order "$dev" "$(cat "$ST_DIR/warp.ports" 2>/dev/null)")"; pp="${pp%% *}"
			if [ -n "$pp" ] && [ "$pp" != "$port" ] && _st_warp_link "$dev" "$peer" "$ip" "$pp"; then port="$pp"
			else _st_warp_link "$dev" "$peer" "$ip" "$port" || { echo "   $ip:$port — с этими ключами рукопожатия нет" >&2; continue; }; fi
			set -- $(_st_warp_probe "$dev")
			[ "$3" = 1 ] && { echo "   $ip:$port — трафик пошёл и оборвался" >&2; continue; }
			if [ "$good" = 1 ] && ! _zm_if_web "$dev"; then
				echo "   $ip:$port — HTTPS через туннель не проходит" >&2; continue
			fi
			echo "$ip $port $colo $k"
			return 0
		done 3< "$f"
	done
	return 1
}

_st_warp_alive_if() {
	local hs
	hs=$(awg show "$1" latest-handshakes 2>/dev/null | awk '{print $2; exit}')
	[ "${hs:-0}" -gt 0 ] 2>/dev/null && [ $(( $(date +%s) - hs )) -lt 180 ]
}
_st_warp_ready_if() { ifstatus "$1" 2>/dev/null | grep -q '"up": true' && awg show "$1" peers 2>/dev/null | grep -q .; }

ST_WARP_PICK="$ST_DIR/warp.pick"
ST_WARP_ORDER="$ST_DIR/warp.order"
_st_warp_pick() { [ "$(cat "$ST_WARP_PICK" 2>/dev/null)" = order ] && echo order || echo latency; }

_st_warp_use() {
	[ -s "$ST_WARP_UP" ] || return 0
	local i c good="" all=""
	while read -r i c; do
		[ -n "$i" ] || continue
		all="$all$i
"
		_st_if_ru "$i" "$c" || good="$good$i
"
	done < "$ST_WARP_UP"
	printf '%s' "${good:-$all}"
}

_st_warp_reorder() {
	[ -s "$ST_WARP_UP" ] || return 0
	awk '{ print $1, $2 }' "$ST_WARP_UP" > "$ST_WARP_UP.tmp"
	_st_warp_order "$ST_WARP_UP.tmp"
	mv -f "$ST_WARP_UP.tmp" "$ST_WARP_UP"
	awk '{ printf "%s%s", (NR > 1 ? ", " : ""), $2 }' "$ST_WARP_UP" > "$ST_DIR/warp.colo"
	_st_tgws_warp
}

_st_colo_guard() {
	local f="$ST_RUN/colo.last" i c n changed=0 moved="" t
	_st_installed || return 0
	[ -f "$ST_OFF" ] && return 0
	[ "$(_st_exit)" = warp ] || return 0
	_st_warp_own && return 0
	[ -s "$ST_WARP_UP" ] || return 0
	_st_running && return 0
	[ -n "$(_st_blocker)" ] && return 0
	mkdir -p "$ST_RUN"
	if [ -f "$f" ]; then
		t="$(date -r "$f" +%s 2>/dev/null || echo 0)"
		[ $(( $(date +%s) - t )) -lt 300 ] && return 0
	fi
	: > "$f"
	: > "$ST_RUN/warp.up.chk"
	while read -r i c; do
		[ -n "$i" ] || continue
		n="$c"
		if _st_warp_alive_if "$i"; then n="$(_st_colo_of "$i")"; [ -n "$n" ] || n="$c"; fi
		if [ "$n" != "$c" ]; then
			changed=1
			_st_warp_is_ru "$n" && ! _st_warp_is_ru "$c" && moved="$moved $i:$n"
		fi
		echo "$i $n" >> "$ST_RUN/warp.up.chk"
	done < "$ST_WARP_UP"
	if [ "$changed" != 1 ]; then
		rm -f "$ST_RUN/warp.up.chk"
		for i in $(awk '{ print $1 }' "$ST_WARP_UP"); do
			_st_warp_use | grep -qx "$i" && continue
			grep -q "\"$i\"" "$STL_SPEC" 2>/dev/null && { job_start steer do_steer_warp_pick keep >/dev/null; break; }
		done
		return 0
	fi
	_st_running && { rm -f "$ST_RUN/warp.up.chk"; return 0; }
	_st_warp_use > "$ST_RUN/warp.up.was"
	mv -f "$ST_RUN/warp.up.chk" "$ST_WARP_UP"
	_st_warp_reorder
	_st_warp_geo $(awk '{ print $1 }' "$ST_WARP_UP")
	for t in $moved; do
		i="${t%%:*}"; case "$i" in zmwarp) n=1 ;; *) n="${i#zmwarp}" ;; esac
		_st_wfix_say "WARP $n переключился на российский узел ${t##*:} — выведен из работы, трафик идёт через остальные туннели"
	done
	if [ "$(_st_warp_use | tr '\n' ' ')" != "$(tr '\n' ' ' < "$ST_RUN/warp.up.was")" ]; then
		rm -f "$ST_RUN/warp.up.was"
		job_start steer do_steer_warp_pick keep >/dev/null
	else
		rm -f "$ST_RUN/warp.up.was"
	fi
	return 0
}

do_steer_warp_pick() {
	_st_phase rules
	rm -f "$ST_STOP_FLAG"
	if [ "$1" != keep ]; then
		mkdir -p "$ST_DIR"
		if [ "$1" = order ]; then
			echo order > "$ST_WARP_PICK"
			printf '%s\n' $2 > "$ST_WARP_ORDER"
			_rb_say "Основной туннель WARP — первый живой по вашему порядку"
		else
			rm -f "$ST_WARP_PICK"
			_rb_say "Основной туннель WARP — самый быстрый из живых"
		fi
		_st_warp_reorder
	else
		_rb_say "Состав туннелей WARP изменился — обновляем правила"
	fi
	set -- $(_st_warp_use)
	[ $# -gt 0 ] && echo "   → в работе: $(echo "$*" | sed 's/zmwarp\([0-9]\)/WARP \1/g; s/zmwarp/WARP 1/g; s/ /, /g')"
	_st_respec
	_rb_say "Готово"
}

_st_warp_order() {
	local f="$1" i c k pos=0 fresh=0 cls
	grep -q ' [0-9][0-9]*$' "$f" && fresh=1
	: > "$f.key"
	while read -r i c k; do
		[ -n "$i" ] || continue
		pos=$((pos + 1))
		if [ "$fresh" = 0 ]; then
			k=$(awk -v i="$i" '$1 == i { print NR; exit }' "$ST_WARP_UP" 2>/dev/null)
			[ -n "$k" ] || k=$((100 + pos))
		elif [ "$k" = - ]; then
			set -- $(_st_warp_probe "$i")
			k=$(($1 * 100000 + $2))
		fi
		if [ "$(_st_warp_pick)" = order ]; then
			k=$(awk -v i="$i" '$1 == i { print NR; exit }' "$ST_WARP_ORDER" 2>/dev/null)
			[ -n "$k" ] || k=$((900 + pos))
		fi
		cls=0; _st_if_ru "$i" "$c" && cls=1
		printf '%d %012d %03d %s %s\n' "$cls" "$k" "$pos" "$i" "$c" >> "$f.key"
	done < "$f"
	sort "$f.key" | awk '{ print $4, $5 }' > "$f"
	rm -f "$f.key"
}

_st_own_conf_ok() {
	local kv="$ST_RUN/own.chk.$$" ep rc=0
	mkdir -p "$ST_RUN"
	_awg_conf_kv "$1" > "$kv"
	ep="$(_awg_cv "$kv" peer endpoint)"
	[ -n "$(_awg_cv "$kv" interface privatekey)" ] && [ -n "$(_awg_cv "$kv" peer publickey)" ] && [ -n "$(_awg_cv "$kv" interface address)" ] || rc=1
	case "$ep" in \[?*\]:?*|?*:?*) ;; *) rc=1 ;; esac
	rm -f "$kv"
	return $rc
}

_st_warp_own_iface() {
	local f="$1" kv="$ST_RUN/own.kv" priv pub psk addr a ep host port keep mtu i="$ST_WARP_IF"
	mkdir -p "$ST_RUN"
	_awg_conf_kv "$f" > "$kv"
	priv="$(_awg_cv "$kv" interface privatekey)"; pub="$(_awg_cv "$kv" peer publickey)"
	addr="$(_awg_cv "$kv" interface address)"; ep="$(_awg_cv "$kv" peer endpoint)"
	psk="$(_awg_cv "$kv" peer presharedkey)"; keep="$(_awg_cv "$kv" peer persistentkeepalive)"; mtu="$(_awg_cv "$kv" interface mtu)"
	case "$ep" in
		\[*\]:*) host="${ep%]:*}"; host="${host#[}"; port="${ep##*]:}" ;;
		?*:*) host="${ep%:*}"; port="${ep##*:}" ;;
	esac
	if [ -z "$priv" ] || [ -z "$pub" ] || [ -z "$addr" ] || [ -z "$host" ] || [ -z "$port" ]; then
		rm -f "$kv"
		echo "ОШИБКА: в конфиге нет PrivateKey, Address, PublicKey или Endpoint (адрес:порт)"
		return 1
	fi
	uci -q delete "network.$i"
	uci -q delete "network.${i}_peer"
	_st_peers_drop "$i"
	uci set "network.$i=interface"
	uci set "network.$i.proto=amneziawg"
	uci set "network.$i.private_key=$priv"
	for a in $(echo "$addr" | tr ',' ' '); do
		case "$a" in */*) ;; *:*) a="$a/128" ;; *) a="$a/32" ;; esac
		uci add_list "network.$i.addresses=$a"
	done
	uci set "network.$i.mtu=${mtu:-1280}"
	_awg_iface_set "$f" "$i"
	uci set "network.${i}_peer=amneziawg_$i"
	uci set "network.${i}_peer.description=Свой WARP"
	uci set "network.${i}_peer.public_key=$pub"
	[ -n "$psk" ] && uci set "network.${i}_peer.preshared_key=$psk"
	uci add_list "network.${i}_peer.allowed_ips=0.0.0.0/0"
	case "$addr" in *:*) uci add_list "network.${i}_peer.allowed_ips=::/0" ;; esac
	uci set "network.${i}_peer.route_allowed_ips=0"
	uci set "network.${i}_peer.persistent_keepalive=${keep:-25}"
	uci set "network.${i}_peer.endpoint_host=$host"
	uci set "network.${i}_peer.endpoint_port=$port"
	uci commit network
	_st_own "net $i"
	rm -f "$kv"
}

_st_warp_park() {
	local i
	for i in "$@"; do
		_st_owns "net $i" || continue
		ifdown "$i" >/dev/null 2>&1
		uci -q set "network.$i.auto=0"
	done
	uci -q commit network
	return 0
}

_st_warp_own_up() {
	local i="$ST_WARP_IF" w=0 col ext="" p
	_st_warp_ext && ext=1
	_st_install_awg || return 1
	_st_awg_loaded || modprobe amneziawg >/dev/null 2>&1
	if [ -n "$ext" ]; then
		[ "$(uci -q get "network.$i.proto")" = amneziawg ] || { echo "ОШИБКА: интерфейса $i больше нет — выберите другой в «Подключении» Steer или вернитесь к автоматическому WARP"; return 1; }
		[ "$(uci -q get "network.$i.auto")" = 0 ] && _rb_say "Интерфейс $i был выключен — включаем"
		p="$(_st_wpeer "$i")"
		[ -n "$p" ] && [ "$(uci -q get "network.$p.route_allowed_ips")" = 1 ] && _rb_warn "У $i включено «Весь трафик» — через него идёт весь интернет роутера, а не только сервисы Steer. Выключить можно на вкладке AmneziaWG"
		_st_ext_fwd
	elif [ "$(uci -q get "network.$i.proto")" != amneziawg ]; then
		_st_own_restore
		[ -s "$ST_WARP_CONF" ] || { echo "ОШИБКА: своего конфига WARP нет — вставьте его в «Подключении» Steer"; return 1; }
		_st_warp_own_iface "$ST_WARP_CONF" || return 1
		ubus call network reload >/dev/null 2>&1
		sleep 2
	fi
	_st_warp_zone
	uci -q get "network.$i.auto" >/dev/null && { uci -q delete "network.$i.auto"; uci -q commit network; }
	_rb_say "$([ -n "$ext" ] && echo "Поднимаем интерфейс $i" || echo "Поднимаем свой туннель WARP")"
	if _st_warp_alive_if "$i" || ! _st_warp_ready_if "$i"; then ubus call "network.interface.$i" up >/dev/null 2>&1; else ifup "$i" >/dev/null 2>&1; fi
	while [ "$w" -lt 25 ]; do
		_st_stopped && return 1
		_st_warp_alive_if "$i" && break
		[ -d "/sys/class/net/$i" ] || sleep 1
		ping -I "$i" -c 1 -W 1 1.1.1.1 >/dev/null 2>&1
		w=$((w + 1))
	done
	if ! _st_warp_alive_if "$i"; then
		rm -f "$ST_WARP_UP" "$ST_DIR/warp.colo"
		if [ -n "$ext" ]; then
			echo "ОШИБКА: интерфейс $i не отвечает — почините его на вкладке AmneziaWG («Точка входа», «Новый WARP») или включите там автопочинку"
		else
			echo "ОШИБКА: сервер из вашего конфига не отвечает — проверьте ключи и Endpoint"
		fi
		return 1
	fi
	col="$(_st_colo_of "$i")"
	echo "$i ${col:-?}" > "$ST_WARP_UP"
	if [ -n "$col" ]; then echo "$col" > "$ST_DIR/warp.colo"; else rm -f "$ST_DIR/warp.colo"; fi
	_st_tgws_warp
	_st_warp_geo "$i"
	p="$(_st_wpeer "$i")"
	_rb_say "$([ -n "$ext" ] && echo "Интерфейс $i работает" || echo "Свой WARP работает"): $(uci -q get "network.$p.endpoint_host"):$(uci -q get "network.$p.endpoint_port")${col:+, колония $col}"
	col="$(_st_geo_line)"
	[ -n "$col" ] && _rb_say "Сайты видят $([ -n "$ext" ] && echo "$i" || echo WARP) как: $col"
	col="$(awk '{ print $2; exit }' "$ST_WARP_UP")"
	[ -n "$col" ] && _st_warp_is_ru "$col" && _rb_warn "Туннель идёт через российскую колонию $col: заблокированное через неё не откроется"
	return 0
}

_st_warp_up() {
	local repick="$1" n i peer got busy="" busyip="" c ready="" w need=0 colos="" alt p
	_st_warp_own && { _st_warp_own_up; return; }
	_st_install_awg || return 1
	[ "$repick" = repick ] && rm -f "$ST_DIR/warp.ports"
	_rb_say "Поднимаем туннели WARP в разных колониях"
	mkdir -p "$ST_RUN"
	n=2
	while [ "$n" -le "$ST_WARP_N" ]; do
		rm -f "$ST_RUN/reg.$n.log" "$ST_RUN/reg.$n.rc"
		if ! _st_with "$n" _st_warp_field PrivateKey 2>/dev/null | grep -q .; then
			( ZM_REG_N="$n"; _st_with "$n" _st_warp_register > "$ST_RUN/reg.$n.log" 2>&1; echo $? > "$ST_RUN/reg.$n.rc" ) &
		fi
		n=$((n + 1))
	done
	n=1
	while [ "$n" -le "$ST_WARP_N" ]; do
		if [ "$n" -gt 1 ]; then wait; [ -f "$ST_RUN/reg.$n.log" ] && cat "$ST_RUN/reg.$n.log"; fi
		if { [ -f "$ST_RUN/reg.$n.rc" ] && [ "$(cat "$ST_RUN/reg.$n.rc")" = 0 ]; } || { [ ! -f "$ST_RUN/reg.$n.rc" ] && _st_with "$n" _st_warp_register; }; then
			ready="$ready $n"
			i="$(_st_wif "$n")"
			if [ "$(uci -q get "network.$i.proto")" != amneziawg ]; then
				_st_with "$n" _st_warp_iface_write 162.159.192.1 2408
				need=1
			fi
		else
			[ "$n" = 1 ] && { wait; echo "ОШИБКА: не удалось получить ключи WARP"; return 1; }
			_rb_warn "WARP $n: не удалось получить ключи — туннелей будет меньше"
		fi
		n=$((n + 1))
	done
	_st_warp_zone
	for n in $ready; do
		i="$(_st_wif "$n")"
		[ "$(uci -q get "network.$i.auto")" = 0 ] && { uci -q delete "network.$i.auto"; need=1; }
	done
	[ "$need" = 1 ] && { uci -q commit network; ubus call network reload >/dev/null 2>&1; }
	for n in $ready; do ubus call "network.interface.$(_st_wif "$n")" up >/dev/null 2>&1; done
	for n in $ready; do
		i="$(_st_wif "$n")"; w=0
		while [ "$w" -lt 20 ] && ! _st_warp_ready_if "$i"; do w=$((w + 1)); sleep 1; done
	done
	: > "$ST_WARP_UP.tmp"
	local pool="$ST_RUN/warp.pool"
	rm -f "$pool" "$ST_RUN/warp.mask"
	for n in $ready; do
		_st_stopped && break
		i="$(_st_wif "$n")"
		peer="$(_st_with "$n" _st_warp_field PublicKey)"
		_st_warp_ready_if "$i" || { _rb_warn "WARP $n: устройство не поднялось"; continue; }
		got=""
		if [ "$repick" != repick ] && grep -q "^$i " "$ST_WARP_UP" 2>/dev/null && _st_warp_alive_if "$i" && c="$(_st_colo_of "$i")" && ! _st_warp_is_ru "$c"; then
			got="$(uci -q get "network.${i}_peer.endpoint_host") $(uci -q get "network.${i}_peer.endpoint_port") $c -"
			_rb_say "WARP $n работает: колония $c"
		elif [ -s "$pool" ] && got="$(_st_warp_from_pool "$i" "$peer" "$busy" "$busyip" "$pool")"; then
			set -- $got
			_rb_say "WARP $n работает: $1:$2, колония $3 — точка из общей разведки"
		else
			echo "   WARP $n: разведка"
			if got="$(_st_warp_scan "$i" "$peer" "$busy" "$busyip" "$pool")"; then
				set -- $got
				if ! _st_warp_link "$i" "$peer" "$1" "$2"; then
					alt=""
					for p in $(cat "$ST_DIR/warp.ports" 2>/dev/null); do
						[ "$p" = "$2" ] && continue
						_st_stopped && break
						_st_warp_link "$i" "$peer" "$1" "$p" && { alt="$p"; break; }
					done
					if [ -z "$alt" ]; then
						_rb_warn "WARP $n: выбранная точка $1:$2 не ответила повторно"
						continue
					fi
					_rb_say "WARP $n: точка $1:$2 не ответила повторно, беру запасной порт $alt"
					got="$1 $alt $3 $4"
					set -- $got
				fi
				_rb_say "WARP $n работает: $1:$2, колония $3"
			else
				_rb_warn "WARP $n не поднялся"
				continue
			fi
		fi
		set -- $got
		if _st_warp_is_ru "$3"; then
			_rb_warn "WARP $n: точка $1:$2 ведёт в российский узел $3 — такой туннель не используем"
			ifdown "$i" >/dev/null 2>&1
			continue
		fi
		busy="$busy $3"; busyip="$busyip $1"
		echo "$i $3 ${4:--}" >> "$ST_WARP_UP.tmp"
		uci set "network.${i}_peer.endpoint_host=$1"
		uci set "network.${i}_peer.endpoint_port=$2"
	done
	if _st_stopped; then
		uci revert network >/dev/null 2>&1
		rm -f "$ST_WARP_UP.tmp"
		return 1
	fi
	uci commit network
	_st_warp_order "$ST_WARP_UP.tmp"
	mv "$ST_WARP_UP.tmp" "$ST_WARP_UP"
	colos="$(awk '{ printf "%s%s", (NR > 1 ? ", " : ""), $2 }' "$ST_WARP_UP")"
	for n in $ready; do
		i="$(_st_wif "$n")"
		grep -q "^$i " "$ST_WARP_UP" || ifdown "$i" >/dev/null 2>&1
	done
	if [ ! -s "$ST_WARP_UP" ]; then
		rm -f "$ST_DIR/warp.colo"
		echo "ОШИБКА: туннель WARP не поднялся ни через одну зарубежную точку входа. Российские узлы (Домодедово и другие) Steer не использует — заблокированное через них не открывается. Попробуйте «Найти новую точку входа» позже или VPN-подписку"
		return 1
	fi
	echo "$colos" > "$ST_DIR/warp.colo"
	_st_tgws_warp
	_st_warp_geo $(awk '{ print $1 }' "$ST_WARP_UP")
	c="$(_st_geo_line)"
	[ -n "$c" ] && _rb_say "Сайты видят WARP как: $c"
	return 0
}

ST_TGWS_WARP="/etc/stgws/warp.lst"
_st_tgws_warp() {
	local i c
	[ -d /etc/stgws ] || return 0
	: > "$ST_TGWS_WARP.tmp"
	while read -r i c; do
		[ -n "$i" ] || continue
		_st_warp_is_ru "$c" || echo "$i" >> "$ST_TGWS_WARP.tmp"
	done < "$ST_WARP_UP" 2>/dev/null
	mv "$ST_TGWS_WARP.tmp" "$ST_TGWS_WARP"
}

ST_LISTS_MANIFEST="https://github.com/xyzmean/splify2-lists/releases/latest/download/lists.json"
ST_LISTS_MANIFEST_RAW="https://raw.githubusercontent.com/xyzmean/splify2-lists/main/lists.json"
ST_CAT_SKIP=" mydyson itdoginfo_meta "
ST_SRS_FALLBACK="https://github.com/itdoginfo/allow-domains/releases/latest/download"

_st_via_ok() { [ -n "$1" ] && [ -d "/sys/class/net/$1" ]; }
_st_via_tun() { local d; d="$(_zm_tun_dev "$1" 2>/dev/null)" && _st_via_ok "$d" && echo "$d|туннель $1"; }
_st_via_pick() {
	local d i
	case "$(_st_exit 2>/dev/null)" in
		warp) d="$(_st_warp_first)"; _st_via_ok "$d" && { echo "$d|WARP"; return 0; } ;;
		vpn) d="$(_st_vpn_dev 2>/dev/null)" && _st_via_ok "$d" && { echo "$d|VPN"; return 0; } ;;
		iface)
			if [ -n "$ST_SEC" ]; then i="$(_st_sec_iface "$ST_SEC")"; else i="$(_st_main_iface)"; fi
			_st_via_tun "$i" && return 0 ;;
	esac
	d="$(_st_warp_first)"; _st_via_ok "$d" && { echo "$d|WARP"; return 0; }
	d="$(_st_vpn_dev 2>/dev/null)" && _st_via_ok "$d" && { echo "$d|VPN"; return 0; }
	for d in $(_st_vpn_devs_all 2>/dev/null); do _st_via_ok "$d" && { echo "$d|VPN"; return 0; }; done
	for i in $(_st_tun_ifaces 2>/dev/null); do _st_via_tun "$i" && return 0; done
	return 1
}
_st_via_dev() {
	local now
	ST_VIA_D=""
	now="$(date +%s)"
	if [ -z "$ST_VIA_C" ] || { [ "$ST_VIA_C" = - ] && [ $((now - ${ST_VIA_T:-0})) -ge 30 ]; } || { [ "$ST_VIA_C" != - ] && ! _st_via_ok "${ST_VIA_C%%|*}"; }; then
		ST_VIA_C="$(_st_via_pick)" || ST_VIA_C=-
		ST_VIA_T="$now"
	fi
	[ "$ST_VIA_C" != - ] || return 1
	ST_VIA_D="${ST_VIA_C%%|*}"
	[ -w "/proc/sys/net/ipv4/conf/$ST_VIA_D/rp_filter" ] && echo 2 > "/proc/sys/net/ipv4/conf/$ST_VIA_D/rp_filter" 2>/dev/null
	return 0
}
_st_via_say() {
	[ -n "$ZM_JOB_LOG" ] && [ -f "$ZM_JOB_LOG" ] || return 0
	grep -qF -- "$1" "$ZM_JOB_LOG" 2>/dev/null && return 0
	echo "$1" >&2
}
_st_fetch() {
	local tried=""
	if [ -f "$ST_DIR/lists.via" ]; then
		if _st_via_dev; then
			_st_via_say "   · Списки сервисов качаем через ${ST_VIA_C#*|}"
			tried=1
			curl -fsSL --interface "$ST_VIA_D" --connect-timeout 6 --max-time 60 -o "$2" "$1" 2>/dev/null && [ -s "$2" ] && return 0
			_st_via_say "   · Через ${ST_VIA_C#*|} не скачалось — качаем напрямую"
		else
			_st_via_say "   · Подключение Steer сейчас не работает — списки сервисов качаем напрямую"
		fi
	fi
	curl -fsSL --connect-timeout 6 --max-time 60 -o "$2" "$1" 2>/dev/null && [ -s "$2" ] && return 0
	[ -z "$tried" ] || return 1
	_st_via_dev || return 1
	curl -fsSL --interface "$ST_VIA_D" --connect-timeout 6 --max-time 60 -o "$2" "$1" 2>/dev/null && [ -s "$2" ]
}

_st_b4_raw() {
	case "$1" in
		https://github.com/[Gg]reeg0ry/b4geoip-forkop/releases/*.srs) echo "https://raw.githubusercontent.com/Greeg0ry/b4geoip-forkop/main/srs/${1##*/}" ;;
		*) echo "$1" ;;
	esac
}

_st_srs_dl() {
	local u r
	u="$(_st_srs_url "$1")"; r="$(_st_b4_raw "$u")"
	if [ "$r" != "$u" ]; then
		_st_fetch "$r" "$2" && [ "$(head -c 3 "$2")" = SRS ] && return 0
		[ -n "$(find "$ST_RUN/b4.down" -mmin -20 2>/dev/null)" ] && return 1
	fi
	_st_fetch "$u" "$2" && [ "$(head -c 3 "$2")" = SRS ] && return 0
	[ "$r" != "$u" ] && { mkdir -p "$ST_RUN"; : > "$ST_RUN/b4.down"; }
	return 1
}

_json_flat() {
	awk 'BEGIN { RS = "\001" }
	function emit(v) { p = ""; for (k = 1; k <= d; k++) p = p (k > 1 ? "." : "") key[k]; print p "\t" v; if (arr[d]) key[d]++ }
	{
		s = $0; n = length(s); i = 1; d = 0
		while (i <= n) {
			c = substr(s, i, 1)
			if (c == "{") { d++; arr[d] = 0; key[d] = ""; want = 1; i++; continue }
			if (c == "[") { d++; arr[d] = 1; key[d] = 0; i++; continue }
			if (c == "}" || c == "]") { d--; if (d > 0 && arr[d]) key[d]++; i++; continue }
			if (c == ",") { if (!arr[d]) want = 1; i++; continue }
			if (c == ":") { want = 0; i++; continue }
			if (c == "\"") {
				v = ""; i++
				while (i <= n) {
					c = substr(s, i, 1)
					if (c == "\\") { e = substr(s, i + 1, 1); v = v (e == "n" || e == "t" || e == "r" ? " " : e); i += 2; continue }
					if (c == "\"") break
					v = v c; i++
				}
				i++
				if (!arr[d] && want) { key[d] = v; want = 0 } else emit(v)
				continue
			}
			if (c ~ /[-0-9a-z]/) {
				v = ""
				while (i <= n && substr(s, i, 1) ~ /[-+.0-9a-zA-Z]/) { v = v substr(s, i, 1); i++ }
				emit(v); continue
			}
			i++
		}
	}' "$1"
}

_st_cat_build() {
	local flat="$ST_RUN/cat.flat" bsets bnames
	mkdir -p "$ST_RUN" "$ST_DIR"
	_json_flat "$1" > "$flat" 2>/dev/null
	grep -q '^domain_lists\.0\.id	\|^categories\.0\.id	' "$flat" || { rm -f "$flat"; return 1; }
	bsets=" $(grep -v '^#' "$RB_SHARE/services.conf" | cut -d'|' -f8 | tr ',\n' '  ') "
	bnames="$(grep -v '^#' "$RB_SHARE/services.conf" | cut -d'|' -f2 | tr 'A-Z' 'a-z' | tr '\n' '|')"
	awk -F'\t' -v skip="$ST_CAT_SKIP" -v bsets="$bsets" -v bnames="|$bnames" -v idx="$ST_CAT_IDX.tmp" -v meta="$ST_CAT_META.tmp" '
		function key(id) { id = tolower(id); sub(/^svc_/, "", id); gsub(/[^a-z0-9_]/, "_", id); return "c_" id }
		function clean(s) { gsub(/[|\t\r\n]/, " ", s); return s }
		{
			p = $1; v = $2
			if (p == "version" || p == "base_url" || p == "generated_at") { top[p] = v; next }
			n = split(p, a, ".")
			if (a[2] !~ /^[0-9]+$/) next
			e = a[1] "." a[2]
			if (!(e in seen)) { seen[e] = 1; order[++cnt] = e }
			if (n == 3) f[e, a[3]] = v
			else if (a[3] == "same_as_ip" && a[4] == "0") f[e, "pair"] = v
		}
		END {
			base = top["base_url"]; sub(/\/+$/, "", base)
			for (j = 1; j <= cnt; j++) {
				e = order[j]; id = f[e, "id"]; if (id == "") continue
				if (tolower(id " " f[e, "source"]) ~ /b4geoip|itdoginfo/) fo[e] = 1
				if (index(skip, " " tolower(id) " ") && !fo[e]) { bad[e] = 1; continue }
				if (f[e, "source_name"] == "" && f[e, "source"] == "" && !fo[e]) { bad[e] = 1; continue }
				k = key(id); byid[id] = e; ek[e] = k
				u = f[e, "url"]; fm = f[e, "format"]
				if (fm != "srs" || u == "") { fm = "lst"; u = (f[e, "file"] != "" && base != "") ? base "/" f[e, "file"] : "" }
				if (u == "" || u !~ /^https:\/\//) { bad[e] = 1; continue }
				if (!(k in done)) { done[k] = 1; print k "|" fm "|" u "|" ((e ~ /^categories/ || (e !~ /^domain_lists/ && f[e, "kind"] != "" && f[e, "kind"] != "domains")) ? "s" : "d") > idx; sets++ }
			}
			for (j = 1; j <= cnt; j++) {
				e = order[j]
				if (e ~ /^categories/ || bad[e] || f[e, "id"] == "") continue
				pr = f[e, "pair"]
				if (pr != "" && (pr in byid) && !bad[byid[pr]]) { used[byid[pr]] = 1; st = ek[e]; if (ek[byid[pr]] != st) st = st "," ek[byid[pr]]; line(e, st) }
				else line(e, ek[e])
			}
			for (j = 1; j <= cnt; j++) {
				e = order[j]
				if (e !~ /^categories/ || bad[e] || used[e] || f[e, "id"] == "") continue
				line(e, ek[e])
			}
			printf "version=%s\nsets=%d\nservices=%d\n", clean(top["version"]), sets, svcs > meta
		}
		function line(e, st,    nm, grp, u, b) {
			nm = clean(f[e, "name_ru"]); if (nm == "") nm = f[e, "id"]
			grp = clean(f[e, "source_name"])
			if (grp == "" && fo[e]) grp = (tolower(f[e, "id"] " " f[e, "source"]) ~ /b4geoip/) ? "b4geoip" : "itdoginfo (allow-domains)"
			if (grp == "") return
			if (tolower(f[e, "id"] " " f[e, "source"]) ~ /itdoginfo/) {
				u = f[e, "url"]; b = u; sub(/.*\//, "", b); sub(/\.srs$/, "", b)
				if (index(bsets, " " b " ") || index(bnames, "|" tolower(nm) "|")) return
			}
			if (ek[e] in out) return
			out[ek[e]] = 1; svcs++
			print ek[e] "|" nm "|||||" "|" st "|" grp
		}' "$flat" > "$ST_CAT_SVC.tmp" || { rm -f "$flat" "$ST_CAT_SVC.tmp" "$ST_CAT_IDX.tmp" "$ST_CAT_META.tmp"; return 1; }
	rm -f "$flat"
	[ -s "$ST_CAT_SVC.tmp" ] && [ -s "$ST_CAT_IDX.tmp" ] || { rm -f "$ST_CAT_SVC.tmp" "$ST_CAT_IDX.tmp" "$ST_CAT_META.tmp"; return 1; }
	mv -f "$ST_CAT_IDX.tmp" "$ST_CAT_IDX"
	mv -f "$ST_CAT_SVC.tmp" "$ST_CAT_SVC"
	mv -f "$ST_CAT_META.tmp" "$ST_CAT_META"
}

_st_cat_src() { [ -s "$ST_CAT_URL" ] && head -n1 "$ST_CAT_URL" || echo "$ST_LISTS_MANIFEST"; }

_st_cat_dl() {
	local u
	u="$(_st_cat_src)"
	if [ "$u" = "$ST_LISTS_MANIFEST" ]; then
		_st_fetch "$ST_LISTS_MANIFEST_RAW" "$1" && _st_cat_build "$1" && return 0
		rm -f "$1"
	fi
	_st_fetch "$u" "$1" && _st_cat_build "$1"
}

_st_cat_refresh() {
	local m="$ST_RUN/lists.json" lk="$ST_RUN/cat.lock" rc=0 t
	[ -f "$ST_CAT_OFF" ] && return 0
	mkdir -p "$ST_DIR" "$ST_RUN"
	if [ "$1" != force ] && [ -s "$ST_CAT_SVC" ]; then
		t="$(date -r "$ST_CAT_SVC" +%s 2>/dev/null || echo 0)"
		[ $(( $(date +%s) - t )) -lt 21600 ] && return 0
	fi
	if ! mkdir "$lk" 2>/dev/null; then
		if [ "$1" = force ]; then
			t=0
			while [ "$t" -lt 10 ] && [ -d "$lk" ]; do sleep 1; t=$((t + 1)); done
		fi
		if ! mkdir "$lk" 2>/dev/null; then
			[ -n "$(find "$lk" -maxdepth 0 -mmin +5 2>/dev/null)" ] || return 0
			rmdir "$lk" 2>/dev/null; mkdir "$lk" 2>/dev/null || return 0
		fi
	fi
	if _st_cat_dl "$m.tmp"; then
		mv -f "$m.tmp" "$m"
		touch "$ST_CAT_SVC"
		rm -f "$ST_DIR/catalog.err"
	else
		rm -f "$m.tmp"
		echo "$(date +%s)" > "$ST_DIR/catalog.err"
		rc=1
	fi
	rmdir "$lk" 2>/dev/null
	return $rc
}

_st_cat_bg() {
	[ -f "$ST_CAT_OFF" ] && return 0
	[ -d "$ST_RUN/cat.lock" ] && [ -z "$(find "$ST_RUN/cat.lock" -maxdepth 0 -mmin +5 2>/dev/null)" ] && return 0
	if grep -q '|Свои списки каталога$' "$ST_CAT_SVC" 2>/dev/null; then ( _st_cat_refresh force >/dev/null 2>&1 & ); return 0; fi
	[ -f "$ST_DIR/catalog.err" ] && [ $(( $(date +%s) - $(awk '{ print $1 + 0; exit }' "$ST_DIR/catalog.err" 2>/dev/null | grep . || echo 0) )) -lt 1800 ] && return 0
	if [ -s "$ST_CAT_SVC" ] && [ "$RB_SHARE/services.conf" -nt "$ST_CAT_SVC" ]; then
		if [ -s "$ST_RUN/lists.json" ] && mkdir "$ST_RUN/cat.lock" 2>/dev/null; then
			_st_cat_build "$ST_RUN/lists.json"; local rc=$?
			rmdir "$ST_RUN/cat.lock" 2>/dev/null
			[ "$rc" = 0 ] && return 0
		fi
		( _st_cat_refresh force >/dev/null 2>&1 & )
		return 0
	fi
	[ -s "$ST_CAT_SVC" ] && [ $(( $(date +%s) - $(date -r "$ST_CAT_SVC" +%s 2>/dev/null || echo 0) )) -lt 21600 ] && return 0
	( _st_cat_refresh >/dev/null 2>&1 & )
}

_st_cat_json() {
	local ver="" sets=0 svcs=0 err=false off=false src
	[ -s "$ST_CAT_META" ] && { ver="$(sed -n 's/^version=//p' "$ST_CAT_META")"; sets="$(sed -n 's/^sets=//p' "$ST_CAT_META")"; svcs="$(sed -n 's/^services=//p' "$ST_CAT_META")"; }
	[ -f "$ST_DIR/catalog.err" ] && err=true
	[ -f "$ST_CAT_OFF" ] && off=true
	src="$(_st_cat_src)"
	printf '{"url":"%s","custom":%s,"version":"%s","sets":%s,"services":%s,"error":%s,"off":%s,"busy":%s}' \
		"$(esc "$src")" "$([ -s "$ST_CAT_URL" ] && echo true || echo false)" "$(esc "$ver")" "${sets:-0}" "${svcs:-0}" "$err" "$off" \
		"$([ -d "$ST_RUN/cat.lock" ] && echo true || echo false)"
}

_st_srs_url() {
	local m="$ST_RUN/lists.json" u=""
	u="$(awk -F'|' -v k="$1" '$1 == k { print $3; exit }' "$ST_CAT_IDX" 2>/dev/null)"
	[ -n "$u" ] && { echo "$u"; return 0; }
	[ -s "$m" ] || _st_fetch "$(_st_cat_src)" "$m" || rm -f "$m"
	[ -s "$m" ] && u=$(grep -o '"url"[[:space:]]*:[[:space:]]*"[^"]*/allow-domains/releases/download/[^"]*/'"$1"'\.srs"' "$m" |
		head -n1 | sed 's/.*"\(https[^"]*\)"$/\1/')
	echo "${u:-$ST_SRS_FALLBACK/$1.srs}"
}

_st_srs_get() {
	local set="$1" d="$ST_DIR/lists" f fmt x
	mkdir -p "$d"
	[ -f "$ST_RUN/srs.$set.done" ] && return 0
	fmt="$(awk -F'|' -v k="$set" '$1 == k { print $2; exit }' "$ST_CAT_IDX" 2>/dev/null)"
	f="$ST_RUN/$set.src"
	if [ "$fmt" = lst ]; then
		if ! _st_fetch "$(_st_srs_url "$set")" "$f"; then
			rm -f "$f"
			[ -s "$d/$set.dom" ] || [ -s "$d/$set.pfx" ] || return 1
			_rb_warn "Набор $set не скачался — беру прошлую копию" >&2
			touch "$ST_RUN/srs.$set.done"
			return 0
		fi
		tr -d '\r' < "$f" | sed 's/[[:space:]]*#.*$//; s/^[[:space:]]*//; s/[[:space:]]*$//' | tr 'A-Z' 'a-z' > "$f.n"
		grep -E '^[0-9]{1,3}(\.[0-9]{1,3}){3}(/[0-9]{1,2})?$' "$f.n" | awk '!s[$0]++' > "$d/$set.pfx.tmp"
		sed 's/^domain://; s/^full://; s/^suffix://; s/^\*\.//; s/^\.//' "$f.n" |
			grep -E '^[a-z0-9]([a-z0-9_-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9_-]*[a-z0-9])?)+$' | grep -vE '^[0-9.]+$' | awk '!s[$0]++' > "$d/$set.dom.tmp"
		: > "$d/$set.meta.tmp"
		rm -f "$f.n"
		if [ ! -s "$d/$set.dom.tmp" ] && [ ! -s "$d/$set.pfx.tmp" ]; then
			rm -f "$f" "$d/$set".*.tmp
			[ -s "$d/$set.dom" ] || [ -s "$d/$set.pfx" ] || return 1
			_rb_warn "Набор $set скачался пустым — беру прошлую копию" >&2
			touch "$ST_RUN/srs.$set.done"
			return 0
		fi
		echo "     ✓ $set: скачан, доменов $(wc -l < "$d/$set.dom.tmp" | tr -d ' '), подсетей $(wc -l < "$d/$set.pfx.tmp" | tr -d ' ')" >&2
	else
		if [ ! -f "$ST_RUN/dl.$set" ]; then
			if _st_srs_dl "$set" "$f"; then
				mv -f "$f" "$d/$set.srs"
				touch "$ST_RUN/dl.$set"
				echo "     ✓ $set.srs: скачан, $(ls -l "$d/$set.srs" | awk '{ printf "%d КБ", ($5 + 1023) / 1024 }')" >&2
			else
				rm -f "$f"
				[ -s "$d/$set.srs" ] || return 1
				_rb_warn "Набор $set не скачался — беру прошлую копию" >&2
				touch "$ST_RUN/dl.$set"
			fi
		fi
		[ -s "$d/$set.srs" ] || return 1
		touch "$ST_RUN/srs.$set.done"
		return 0
	fi
	for x in dom pfx meta; do touch "$d/$set.$x.tmp"; mv "$d/$set.$x.tmp" "$d/$set.$x"; done
	rm -f "$f"
	touch "$ST_RUN/srs.$set.done"
}

_st_svc_lists() {
	local id="$1" name sets set dom="" pfx="" srs="" f fmt took=""
	name="$(_rb_svc_field "$id" 2)"
	sets="$(_rb_svc_field "$id" 8 | tr ',' ' ')"
	if [ -n "$(echo $sets)" ]; then echo "   → «$name»: скачиваем списки $(echo $sets | sed 's/ /, /g')" >&2
	elif [ "$id" = custom ]; then echo "   → «$name»: доменов $(cat "$ST_CUSTOM.lst" 2>/dev/null | grep -c .), подсетей $(cat "$ST_CUSTOM.pfx" 2>/dev/null | grep -c .)" >&2
	else echo "   → «$name»: список из репозитория" >&2; fi
	for set in $sets; do
		[ -f "$ST_RUN/used.$set" ] && continue
		if _st_srs_get "$set"; then
			took="$took $set"
			f="$ST_DIR/lists/$set"
			fmt="$(awk -F'|' -v k="$set" '$1 == k { print $2; exit }' "$ST_CAT_IDX" 2>/dev/null)"
			if [ "$fmt" != lst ]; then srs="$srs $f.srs"; continue; fi
			[ -s "$f.dom" ] && dom="$dom $f.dom"
			[ -s "$f.pfx" ] && pfx="$pfx $f.pfx"
		else
			if [ -n "$(_rb_svc_field "$id" 3)$(_rb_svc_field "$id" 4)" ]; then _rb_warn "Список $set не скачался или не раскрылся — беру резервный список" >&2
			else _rb_warn "Список «$name» не скачался или не раскрылся — пропускаем его в этот раз" >&2; fi
			sets=""
			break
		fi
	done
	for set in $took; do [ -n "$sets" ] && touch "$ST_RUN/used.$set"; done
	if [ -n "$sets" ]; then
		for f in $(_rb_svc_field "$id" 3 | tr ',' ' '); do
			case "$f" in *_extra.lst) f="$(_st_pkg_lists "$f")"; [ -n "$f" ] && dom="$dom $f" ;; esac
		done
	fi
	if [ -z "$sets" ]; then
		dom="$(_st_pkg_lists "$(_rb_svc_field "$id" 3 | tr ',' ' ')")"
		pfx="$(_st_pkg_lists "$(_rb_svc_field "$id" 4 | tr ',' ' ')")"
		srs=""
		if [ -z "$dom$pfx" ] && [ "$id" != custom ]; then
			f="$ST_DIR/lists/$id.base.dom"
			mkdir -p "$ST_DIR/lists"
			printf '%s,%s\n' "$(_rb_svc_field "$id" 5)" "$(_rb_svc_field "$id" 6)" | tr ',' '\n' | grep -E '^[a-z0-9.-]+\.[a-z]+$' | awk '!s[$0]++' > "$f"
			if [ -s "$f" ]; then
				_rb_warn "Списки «$name» не скачались — пока беру только основные домены сервиса ($(wc -l < "$f" | tr -d ' ')), позже нажмите «Применить» ещё раз" >&2
				dom="$f"
			else
				rm -f "$f"
			fi
		fi
	fi
	[ "$id" = custom ] && [ -s "$ST_CUSTOM.lst" ] && dom="$ST_CUSTOM.lst"
	[ "$id" = custom ] && [ -s "$ST_CUSTOM.pfx" ] && pfx="$ST_CUSTOM.pfx"
	[ -n "$srs$dom$pfx" ] || return 0
	printf 'svc\t%s\t%s\n' "$id" "$name"
	for f in $srs; do printf 'srs\t%s\n' "$f"; done
	for f in $dom; do printf 'dom\t%s\n' "$f"; done
	for f in $pfx; do printf 'pfx\t%s\n' "$f"; done
}

_st_pkg_lists() {
	local f
	for f in $1; do _rb_list_get "$f" && [ -s "$ZM_LISTS_DIR/$f" ] && echo "$ZM_LISTS_DIR/$f"; done
}

_st_model_head() {
	local id s k m=none
	printf 'lan'; for id in $(_st_lan_devs); do printf '\t%s' "$id"; done; echo
	if _st_sec_off main || { ! _st_work_main && _st_secs_work; }; then m=none
	elif _st_use_vpn; then m=vpn; elif [ "$(_st_exit)" = iface ]; then m=iface; elif _st_warp_on || ! _st_secs_work; then m=warp; fi
	printf 'main\t%s\n' "$m"
	[ "$m" = iface ] && printf 'mif\t%s\n' "$(_zm_tun_dev "$(_st_main_iface)")"
	if [ "$m" = vpn ]; then
		printf 'vpn\t%s\n' "$ST_SUB"
		_st_sub_filter
	fi
	if [ "$m" = warp ] || { _st_warp_on && _st_secs_warp; }; then
		printf 'wpick\t%s\n' "$(_st_warp_pick)"
		printf 'warp'
		if [ -s "$ST_WARP_UP" ]; then for id in $(_st_warp_use); do printf '\t%s' "$id"; done; else printf '\t%s' "$ST_WARP_IF"; fi
		echo
	fi
	_st_dev_model
	for s in $(_st_secs); do
		_st_sec_live "$s" || continue
		k="$(_st_sec_kind "$s")"
		case "$k" in
			vpn) printf 'so\t%s\tvpn\t%s\n' "$s" "$ST_SEC_DIR/$s/sub.txt"; _st_sec_with "$s" _st_sub_filter | sed "s/^tun	/stun	$s	/" ;;
			iface) printf 'so\t%s\tiface\t%s\n' "$s" "$(_zm_tun_dev "$(_st_sec_iface "$s")")" ;;
			*) printf 'so\t%s\twarp\n' "$s" ;;
		esac
		[ -s "$ST_SEC_DIR/$s/devices" ] && awk -F'\t' -v s="$s" '($1 == "all" || $1 == "only") && $2 != "" && !x[$2]++ { printf "sdev\t%s\t%s\t%s\n", s, $1, $2 }' "$ST_SEC_DIR/$s/devices"
	done
	_st_excl_model
}
_st_model() {
	local id s
	rm -f "$ST_RUN"/used.* "$ST_RUN"/srs.*.done
	mkdir -p "$ST_RUN"
	_st_cust_split
	_st_model_head
	for id; do
		_st_svc_lists "$id"
	done
	for s in $(_st_secs); do
		_st_sec_live "$s" || continue
		rm -f "$ST_RUN"/used.*
		printf 'sec\t%s\n' "$s"
		for id in $(_st_sec_with "$s" _st_sel); do
			_st_sec_with "$s" _st_svc_lists "$id"
		done
	done
}

_st_spec_apply() {
	local m="$ST_RUN/model"
	{ [ $# -gt 0 ] || _st_secs_work; } && _rb_say "Скачиваем списки выбранных сервисов"
	_st_model "$@" > "$m"
	if ! grep -q '^svc	' "$m"; then
		if [ $# -gt 0 ] || ! grep -qE '^(dev	all|sdev	[^	]*	all)	' "$m"; then rm -f "$m"; echo "ОШИБКА: для выбранных сервисов нет ни одного списка"; return 1; fi
	fi
	stl_apply "$m" || { rm -f "$m"; return 1; }
	grep -v '^\(lan\|main\|warp\|wpick\|vpn\|tun\|so\|stun\|sdev\|dev\|xdom\|xpfx\)	' "$m" > "$ST_DIR/model.svc" 2>/dev/null
	rm -f "$m"
	_st_own "steer-spec"
}

_st_spec_clear() {
	_st_owns "steer-spec" || return 0
	stl_stop
	stl_spec_restore
	sed -i '/^steer-spec$/d' "$ST_OWNED"
	_doh_force_apply
}

_st_kick() { _st_sec_with main _st_kick0; }
_st_kick0() {
	_st_owns "steer-spec" || return 0
	[ -f "$ST_OFF" ] && return 0
	stl_enabled || return 0
	local sel
	sel="$(_st_sel | tr '\n' ' ')"
	if { [ -n "$(echo $sel)" ] || _st_devs_all || _st_secs_work; } && _st_spec_apply $sel; then return 0; fi
	stl_restart
	_rb_say "Steer перезапущен"
}

_st_dns_conflict() {
	return 1
}



do_steer_dns_fix() {
	_doh_force_apply
	[ -f "$ST_OFF" ] && return 0
	[ -z "$(_st_blocker)" ] || return 0
	stl_enabled && stl_restart
	return 0
}

_st_cron_restart() {
	local i
	stl_enabled || return 0
	[ -z "$(_st_blocker)" ] || return 0
	for i in $(awk '{print $1}' "$ST_WARP_UP" 2>/dev/null); do ifup "$i"; done
	sleep 15
	stl_restart
}

ST_CRON_KEEP="$ST_DIR/autorestart"
_st_cron_refresh() {
	local cur
	cur="$(_st_cron_get)"
	if [ -z "$cur" ]; then
		[ -s "$ST_CRON_KEEP" ] && _st_installed && _st_cron_set "$(cat "$ST_CRON_KEEP")" >/dev/null 2>&1
		return 0
	fi
	grep -F "$ST_CRON_TAG" "$CRON_FILE" 2>/dev/null | grep -qF "$ST_CRON_CMD" && return 0
	_st_cron_set "$cur" >/dev/null 2>&1
	return 0
}

_st_cron_get() {
	local line hour min
	line=$(grep -F "$ST_CRON_TAG" "$CRON_FILE" 2>/dev/null | head -n1)
	[ -n "$line" ] || return 0
	min=$(echo "$line" | awk '{print $1}')
	hour=$(echo "$line" | awk '{print $2}')
	case "$min" in */*) echo "everym:${min#*/}"; return 0 ;; esac
	case "$hour" in
		*/*) echo "every:${hour#*/}" ;;
		*)
			case "$min" in ''|0|00|*[!0-9]*) echo "daily:$hour" ;; ?) echo "daily:$hour:0$min" ;; *) echo "daily:$hour:$min" ;; esac ;;
	esac
}

_st_cron_set() {
	local mode="${1%%:*}" value="${1#*:}" spec keep="$1" h m
	case "$mode" in
		off) spec="" ;;
		every)
			case "$value" in ''|*[!0-9]*|???*) echo '{"error":"введите интервал от 1 до 23 часов"}'; return 1 ;; esac
			value="${value#0}"
			[ "${value:-0}" -ge 1 ] && [ "$value" -le 23 ] || { echo '{"error":"введите интервал от 1 до 23 часов"}'; return 1; }
			spec="0 */$value * * *"; keep="every:$value" ;;
		everym)
			case "$value" in ''|*[!0-9]*|???*) echo '{"error":"введите интервал от 10 до 59 минут"}'; return 1 ;; esac
			[ "$value" -ge 10 ] && [ "$value" -le 59 ] || { echo '{"error":"введите интервал от 10 до 59 минут"}'; return 1; }
			spec="*/$value * * * *" ;;
		daily)
			h="${value%%:*}"; m=0
			case "$value" in *:*) m="${value#*:}" ;; esac
			case "$h" in ''|*[!0-9]*|???*) echo '{"error":"введите время от 00:00 до 23:59"}'; return 1 ;; esac
			case "$m" in ''|*[!0-9]*|???*) echo '{"error":"введите время от 00:00 до 23:59"}'; return 1 ;; esac
			case "$h" in 0?) h="${h#0}" ;; esac
			case "$m" in 0?) m="${m#0}" ;; esac
			[ "$h" -le 23 ] && [ "$m" -le 59 ] || { echo '{"error":"введите время от 00:00 до 23:59"}'; return 1; }
			spec="$m $h * * *"
			if [ "$m" = 0 ]; then keep="daily:$h"; elif [ "$m" -lt 10 ]; then keep="daily:$h:0$m"; else keep="daily:$h:$m"; fi ;;
		*) echo '{"error":"неизвестный режим"}'; return 1 ;;
	esac
	mkdir -p "$(dirname "$CRON_FILE")"
	touch "$CRON_FILE"
	sed -i "\\|$ST_CRON_TAG|d" "$CRON_FILE"
	[ -n "$spec" ] && echo "$spec $ST_CRON_CMD $ST_CRON_TAG" >> "$CRON_FILE"
	if [ -n "$spec" ] && [ -d "$ST_DIR" ]; then echo "$keep" > "$ST_CRON_KEEP"; else rm -f "$ST_CRON_KEEP"; fi
	/etc/init.d/cron enable >/dev/null 2>&1
	/etc/init.d/cron restart >/dev/null 2>&1
	printf '{"ok":true}\n'
}

_st_down() {
	stl_stop
	local i
	for i in $(_st_wifs_all); do
		_st_owns "net $i" || continue
		ifdown "$i" >/dev/null 2>&1
		uci -q set "network.$i.auto=0"
	done
	uci -q commit network
}

_st_warp_resume() {
	[ -s "$ST_WARP_UP" ] || return 1
	local i ifs need=0 w=0 alive=""
	ifs="$(awk '{print $1}' "$ST_WARP_UP")"
	for i in $ifs; do
		[ "$(uci -q get "network.$i.proto")" = amneziawg ] || continue
		[ "$(uci -q get "network.$i.auto")" = 0 ] && { uci -q delete "network.$i.auto"; need=1; }
	done
	[ "$need" = 1 ] && uci -q commit network
	for i in $ifs; do
		_st_warp_ready_if "$i" || ubus call "network.interface.$i" up >/dev/null 2>&1
	done
	while [ "$w" -lt 25 ]; do
		alive=""
		for i in $ifs; do _st_warp_alive_if "$i" && alive="$alive $i"; done
		[ -n "$alive" ] && break
		sleep 1; w=$((w + 1))
	done
	[ -n "$alive" ] || return 1
	_rb_say "Туннели WARP уже подобраны — берём их как есть ($(cat "$ST_DIR/warp.colo" 2>/dev/null || echo "$alive"))"
	return 0
}

_st_apply() { _st_sec_with main _st_apply0 "$@"; }
_st_secs_fit() {
	local have want s
	have="$(awk -F'\t' '$1 == "sec" { printf "%s ", $2 }' "$ST_DIR/model.svc" 2>/dev/null)"
	want="$(for s in $(_st_secs); do _st_sec_live "$s" && printf '%s ' "$s"; done)"
	[ "$have" = "$want" ]
}
_st_secs_say() {
	local s k n w
	_st_sec_off main && echo "   · Секция «$(_st_sec_name main)» выключена — её сервисы идут напрямую"
	for s in $(_st_secs); do
		_st_sec_off "$s" && { echo "   · Секция «$(_st_sec_name "$s")» выключена — её сервисы идут напрямую"; continue; }
		w="$(_st_sec_with "$s" _st_sel | tr '\n' ' ')"
		n="$(_st_sec_with "$s" _st_devs_n all)"
		[ -n "$(echo $w)" ] || [ "$n" -gt 0 ] || continue
		k="$(_st_sec_kind "$s")"
		w="$(_rb_svc_names "$w")"; [ "$n" -gt 0 ] && w="${w:+$w; }весь трафик устройств: $n"
		if ! _st_sec_live "$s"; then
			case "$k" in
				vpn) _rb_warn "Секция «$(_st_sec_name "$s")»: у неё нет подписки VPN — её сервисы пока идут напрямую" ;;
				iface) _rb_warn "Секция «$(_st_sec_name "$s")»: туннеля $(_st_sec_iface "$s") нет на роутере — её сервисы пока идут напрямую" ;;
				*) _rb_warn "Секция «$(_st_sec_name "$s")»: WARP не подключён — её сервисы пока идут напрямую" ;;
			esac
			continue
		fi
		case "$k" in
			vpn) _rb_say "Секция «$(_st_sec_name "$s")» через VPN ($(_st_sec_with "$s" _st_sub_label)): $w" ;;
			iface)
				_rb_say "Секция «$(_st_sec_name "$s")» через $(_st_sec_iface "$s"): $w"
				_zm_tun_up "$(_st_sec_iface "$s")" || _rb_warn "Секция «$(_st_sec_name "$s")»: туннель $(_st_sec_iface "$s") сейчас не подключён — пока он не поднимется, её сервисы $([ "$(_st_onfail)" = drop ] && echo "остановлены" || echo "идут напрямую")" ;;
			*) _rb_say "Секция «$(_st_sec_name "$s")» через WARP: $w" ;;
		esac
	done
}
_st_apply0() {
	local sel
	_st_tun_hook
	rm -f "$ST_RUN/lists.json" "$ST_RUN"/dl.*
	if [ ! -f "$ST_CAT_OFF" ]; then
		_rb_say "Обновляем каталог списков"
		if _st_cat_refresh force >/dev/null 2>&1; then echo "   ✓ Каталог $(sed -n 's/^version=//p' "$ST_CAT_META" 2>/dev/null): наборов $(sed -n 's/^sets=//p' "$ST_CAT_META" 2>/dev/null)"
		else _rb_warn "Каталог списков не скачался — сервисы из каталога берём по прежнему списку"; fi
	fi
	sel="$(_st_sel | tr '\n' ' ')"
	if [ -z "$(echo $sel)" ] && ! _st_devs_all && ! _st_secs_work; then
		_st_spec_clear
		_st_down
		_rb_say "Ничего не выбрано — туннель и Steer выключены"
		return 0
	fi
	local ex mw=""
	ex="$(_st_exit)"
	_st_work_main && mw=1
	case "$ex" in
		vpn) _st_vpn_zone on ;;
		iface) [ -n "$mw" ] && ! _zm_tun_up "$(_st_main_iface)" && _rb_warn "Туннель $(_st_main_iface) сейчас не подключён — пока он не поднимется, сервисы $([ "$(_st_onfail)" = drop ] && echo "остановлены" || echo "идут напрямую")" ;;
		warp) [ -z "$mw" ] && ! _st_secs_warp || [ "$1" = tunnel_ready ] || _st_warp_resume || _st_warp_up || return 1 ;;
		*)
			if ! _st_secs_work; then
				_st_spec_clear
				_st_down
				_rb_warn "Туннеля нет — подключите WARP или подписку VPN, и выбранные сервисы пойдут через него"
				return 0
			fi
			[ -n "$mw" ] && _rb_warn "У основной секции нет туннеля — подключите WARP или подписку VPN, её сервисы пока идут напрямую" ;;
	esac
	if { [ "$ex" = vpn ] || [ "$ex" = iface ]; } && _st_warp_on && _st_secs_warp && [ "$1" != tunnel_ready ]; then _st_warp_resume || _st_warp_up || return 1; fi
	[ -n "$(_st_secs_vpn)" ] && _st_vpn_zone on
	_st_secs_fw
	local what dn
	what="$(_rb_svc_names "$sel")"
	dn="$(_st_devs_n all)"
	[ "$dn" -gt 0 ] && what="${what:+$what; }весь трафик устройств: $dn"
	if [ -n "$mw" ]; then
		if [ "$ex" = vpn ]; then _rb_say "$([ -n "$(_st_secs)" ] && printf 'Секция «%s» через VPN' "$(_st_sec_name main)" || echo "Через VPN") ($(_st_sub_label)): $what"
		elif [ "$ex" = warp ]; then _rb_say "$([ -n "$(_st_secs)" ] && printf 'Секция «%s» через WARP' "$(_st_sec_name main)" || echo "Через WARP"): $what"
		elif [ "$ex" = iface ]; then _rb_say "$([ -n "$(_st_secs)" ] && printf 'Секция «%s» через %s' "$(_st_sec_name main)" "$(_st_main_iface)" || printf 'Через %s' "$(_st_main_iface)"): $what"; fi
	fi
	_st_secs_say
	[ "$(_st_devs_n byp)" -gt 0 ] && echo "   · Мимо Steer ходят устройства: $(_st_devs_n byp)"
	_st_engine_ready || return 1
	_st_spec_apply $sel
}

_st_engine_ready() {
	local f
	f="$(_st_feats_all)"
	stl_v2 && { [ -z "$(echo $f)" ] || _st_feats_ok $f; } && return 0
	STL_MODS_ONLY=1 _st_install_steer $f
}

_st_failopen() { stl_state "$(_st_exit)" && [ "$STL_FAILED" = true ]; }

ST_HEAL_STAMP="$ST_DIR/heal.reinstall"
_st_heal_wait() {
	local f="$1" i=0
	while [ "$i" -lt 10 ]; do
		sleep 3; i=$((i + 1))
		stl_running || continue
		stl_diag_lines > "$f"
		[ -s "$f" ] && ! grep -q '^fail' "$f" && return 0
	done
	return 1
}
ST_HEAL_CAUSE="$ST_DIR/heal.cause"
_st_heal_cause() { awk -F'\t' '$1 == "fail" { print $2 }' "$1" | while IFS= read -r w; do _st_diag_node "$w" || printf '%s\n' "$w"; done | sort; }
_st_heal() {
	local f="$1" ver c="$ST_RUN/heal.cause.now"
	mkdir -p "$ST_RUN" "$ST_DIR"
	_st_heal_cause "$f" > "$c"
	if [ -s "$ST_HEAL_CAUSE" ] && cmp -s "$c" "$ST_HEAL_CAUSE" && [ -z "$(find "$ST_HEAL_CAUSE" -mmin +360 2>/dev/null)" ]; then
		ST_HEAL_DID="эту же поломку панель уже пыталась исправить в $(date -r "$ST_HEAL_CAUSE" +%H:%M 2>/dev/null) — не помогло"
		echo "   ! Эту же поломку ядра уже пробовали исправить в $(date -r "$ST_HEAL_CAUSE" +%H:%M 2>/dev/null) — не помогло, второй раз по кругу не чиним"
		rm -f "$c"
		return 1
	fi
	ST_HEAL_DID="перезапуск ядра не помог"
	_rb_say "Чиним сами: перезапускаем ядро steer"
	if stl_restart && _st_heal_wait "$f"; then
		echo "   ✓ После перезапуска ядра всё работает"
		rm -f "$c" "$ST_HEAL_CAUSE"
		return 0
	fi
	mv -f "$c" "$ST_HEAL_CAUSE"
	if [ -f "$ST_HEAL_STAMP" ] && [ -z "$(find "$ST_HEAL_STAMP" -mmin +30 2>/dev/null)" ]; then
		echo "   ! Перезапуск не помог, а ядро уже переустанавливали меньше получаса назад — второй раз не трогаем"
		stl_diag_lines > "$f"
		return 1
	fi
	mkdir -p "$ST_DIR"; touch "$ST_HEAL_STAMP"
	ST_HEAL_DID="не помогли ни перезапуск, ни переустановка ядра"
	ver="$(stl_version)"; _stl_ver_ok "$ver" || ver="$(stl_latest)"
	_rb_say "Перезапуск не помог — переустанавливаем ядро steer $ver"
	if ! STL_REINSTALL=1 stl_engine_install "$ver" $(_st_use_vpn && _st_sub_feats); then
		echo "   ✗ Переустановить ядро не удалось — проверьте интернет и нажмите «Применить» ещё раз"
		stl_running || stl_restart >/dev/null 2>&1
		stl_diag_lines > "$f"
		return 1
	fi
	stl_running || stl_restart >/dev/null 2>&1
	if _st_heal_wait "$f"; then
		echo "   ✓ После переустановки ядра всё работает"
		rm -f "$ST_HEAL_CAUSE"
		return 0
	fi
	return 1
}

_st_selfcheck() { _st_sec_with main _st_selfcheck0; }
_st_sec_check1() {
	local s="$1" nm o rc tr ip
	nm="$(_st_sec_name "$s")"
	case "$(_st_sec_kind "$s")" in
		vpn)
			o="$(_st_sec_with "$s" _st_vpn_check 60)"; rc=$?
			printf '%s\n' "$o" | sed "s/^\[ OK \] VPN/[ OK ] Секция «$nm» · VPN/; s/^\[FAIL\] VPN/[FAIL] Секция «$nm» · VPN/"
			return $rc ;;
		iface) _st_tun_check "Секция «$nm»" "$(_st_sec_iface "$s")"; return $? ;;
		*)
			tr="$(curl -s --interface "$(_st_warp_first)" --connect-timeout 5 --max-time 10 https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null)"
			case "$tr" in *ip=*) echo "[ OK ] Секция «$nm» · WARP: трафик идёт ($(printf '%s\n' "$tr" | sed -n 's/^colo=//p'))"; return 0 ;; esac
			echo "[FAIL] Секция «$nm» · WARP: трафик через туннель не идёт"
			return 1 ;;
	esac
}
_st_selfcheck0() {
	local f="$ST_RUN/diag.json" n i v what why bad=0 trace healed="" did="" vdead="" core="" moved="" s
	_rb_say "Проверяем, что всё работает"
	for s in $(_st_secs); do _st_sec_live "$s" && _st_sec_work "$s" && { _st_sec_check1 "$s" || bad=1; }; done
	if _st_work_main && _st_use_vpn; then
		if ! _st_vpn_check; then
			if [ -s "$ST_SUB_NODE" ] && _st_node_down; then
				vdead=1
				if _st_node_failover; then vdead=""; moved=1; else bad=1; fi
			else
				bad=1
				_st_node_down && vdead=1
			fi
		fi
		stl_running && echo "[ OK ] Служба Steer запущена" || { echo "[FAIL] Служба Steer не запущена"; bad=1; }
	elif _st_work_main && [ "$(_st_exit)" = iface ]; then
		_st_tun_check "$([ -n "$(_st_secs)" ] && printf 'Секция «%s»' "$(_st_sec_name main)" || echo "Туннель")" "$(_st_main_iface)" || bad=1
		stl_running && echo "[ OK ] Служба Steer запущена" || { echo "[FAIL] Служба Steer не запущена"; bad=1; }
	elif _st_work_main && _st_warp_on; then
		trace="$(curl -s --interface "$(_st_warp_first)" --connect-timeout 5 --max-time 10 https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null)"
		case "$trace" in
			*warp=on*|*warp=plus*) echo "[ OK ] Туннель WARP: трафик идёт через Cloudflare ($(echo "$trace" | sed -n 's/^colo=//p'))" ;;
			*ip=*)
				if _st_warp_own; then
					local tip dip
					tip="$(echo "$trace" | sed -n 's/^ip=//p')"
					dip="$(curl -s --connect-timeout 5 --max-time 10 https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null | sed -n 's/^ip=//p')"
					local tn="Свой туннель"; _st_warp_ext && tn="Интерфейс $ST_WARP_IF"
					if [ -n "$dip" ] && [ "$tip" = "$dip" ]; then echo "[FAIL] $tn: выход $tip совпадает с IP провайдера — $(_st_warp_ext && echo "трафик идёт мимо него" || echo "конфиг не пускает трафик в интернет")"; bad=1
					else echo "[ OK ] $tn: трафик идёт (выход $tip${dip:+, провайдер $dip})"; fi
				else echo "[FAIL] Туннель WARP: трафик идёт мимо Cloudflare WARP"; bad=1; fi ;;
			*) echo "[FAIL] Туннель WARP: трафик через него не идёт"; bad=1 ;;
		esac
		stl_running && echo "[ OK ] Служба Steer запущена" || { echo "[FAIL] Служба Steer не запущена"; bad=1; }
	fi
	_st_owns "steer-spec" && stl_v2 || return $bad
	if _st_work && _st_failopen; then
		if [ -z "$vdead" ]; then
			_rb_warn "Ядро steer считает туннель нерабочим — ждём, пока его сторож проверит туннель снова"
			i=0
			while [ "$i" -lt 30 ] && _st_failopen; do sleep 2; i=$((i + 1)); done
		fi
		if _st_failopen; then
			if [ "$(_st_onfail)" = drop ]; then echo "[FAIL] Туннель: ядро steer не может пустить через него трафик — выбранные сервисы остановлены"
			else echo "[FAIL] Туннель: ядро steer не может пустить через него трафик — сервисы идут напрямую, через провайдера"; fi
			logread 2>/dev/null | grep -F 'steer[warn]' | tail -n 6 | sed 's/^[^]]*\]: /   /' | _st_outs_text
			bad=1
		else
			echo "[ OK ] Ядро steer снова ведёт трафик в туннель"
		fi
	else
		_st_work && echo "[ OK ] Ядро steer ведёт выбранные сервисы в туннель"
	fi
	stl_diag_lines > "$f"
	while IFS="$(printf '\t')" read -r v what why; do
		[ "$v" = fail ] && ! _st_diag_node "$what" && core=1
	done < "$f"
	local nodeonly=""
	[ -z "$core" ] && [ -z "$moved" ] && _st_diag_human < "$f" | awk -F"$(printf '\037')" '$1 == "fail" { f = 1 } END { exit !f }' && nodeonly=1
	if [ -n "$core" ] && [ -z "$ST_HEALING" ] && _st_work && [ ! -f "$ST_OFF" ]; then
		while IFS="$(printf '\t')" read -r v what why; do
			[ "$v" = fail ] && ! _st_diag_node "$what" && echo "!! $(_st_diag_what "$what")"
		done < "$f"
		ST_HEALING=1
		if _st_heal "$f"; then healed=1; fi
		ST_HEALING=""
		did="$ST_HEAL_DID"
		_rb_say "Проверяем ещё раз"
	fi
	local raw tip note v0 warned=""
	_st_diag_human < "$f" > "$f.h"
	while IFS="$(printf '\037')" read -r v what why tip note v0 raw; do
		case "$v" in
			ok)   echo "[ OK ] $what" ;;
			warn)
				[ -n "$moved" ] && [ "$v0" = fail ] && _st_diag_node "$raw" && continue
				echo "!! $what${why:+ — $why}"; warned=1
				[ -n "$tip" ] && echo "   · $tip"
				[ -n "$note" ] && echo "   · $note" ;;
			fail)
				[ -n "$moved" ] && _st_diag_node "$raw" && continue
				case "$why" in *'init.d/steer'*|*ерезапустите*|*ереустановите*) [ -n "$did" ] && why="$did; пришлите журнал в чат поддержки" ;; esac
				echo "[FAIL] $what${why:+ — $why}"; bad=1
				[ -n "$tip" ] && echo "   · $tip" ;;
		esac
	done < "$f.h"
	rm -f "$f" "$f.h"
	[ -n "$nodeonly" ] && echo "   · Само ядро steer исправно — не отвечает узел или сервер туннеля; перезапуск и переустановка ядра тут не помогут"
	[ -n "$healed" ] && [ "$bad" = 0 ] && echo "   · Поломку ядра панель исправила сама"
	if [ "$bad" != 0 ]; then _rb_warn "Проверка нашла поломку — подробности выше"
	elif [ -n "$warned" ]; then _rb_say "Проверка пройдена — работе ничего не мешает, замечания выше"
	else _rb_say "Проверка пройдена"; fi
	return $bad
}


do_steer_install() {
	local blk
	_st_phase install
	rm -f "$ST_STOP_FLAG"
	rm -f "$ST_HEAL_STAMP"
	blk="$(_st_blocker)"
	_fk_installed && { echo "ОШИБКА: стоит $(_fk_name) — он сам направляет сервисы в туннель. Удалите $(_fk_name), чтобы поставить Steer"; return 1; }
	if ! _st_installed 2>/dev/null && [ -n "$(_zm_px_foreign)" ]; then echo "ОШИБКА: стоит $(_zm_px_foreign) — он сам направляет сервисы в туннель. Удалите $(_zm_px_foreign), чтобы поставить Steer"; return 1; fi
	case "$blk" in
		'') ;;
		splify2) echo "ОШИБКА: установлен splify2 — туннели и списки настраиваются в нём"; return 1 ;;
		steer)   echo "ОШИБКА: у ядра steer уже есть чужие правила — не перезаписываем их"; return 1 ;;
		*)       echo "ОШИБКА: $blk"; return 1 ;;
	esac
	_ensure_deps
	mkdir -p "$ST_DIR"
	_st_phase pkgs
	_st_install_steer || return 1
	if ! command -v conntrack >/dev/null 2>&1; then
		$INSTALL conntrack >&2 && _st_own "pkg conntrack"
	fi
	_st_own "engine"
	_ft_steer_sync
	rm -f "$ST_OFF"
	if [ "$(_st_exit)" != none ] && _st_work; then
		_st_phase rules
		_st_apply || return 1
		_st_phase check
		sleep 2
		_st_selfcheck
	fi
	_rb_say "Готово: ядро steer установлено — подключите WARP или подписку VPN на соседних вкладках"
}

do_steer_warp_setup() {
	_st_phase awg
	rm -f "$ST_STOP_FLAG"
	_st_installed || { echo "ОШИБКА: сначала установите Steer"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: ядро steer сейчас настраивает не Zapret Manager"; return 1; }
	_ensure_deps
	_st_install_awg || return 1
	_st_phase tunnel
	_st_warp_up || return 1
	[ "$(cat "$ST_EXIT" 2>/dev/null)" = vpn ] && [ -s "$ST_SUB" ] || echo warp > "$ST_EXIT"
	if [ ! -f "$ST_OFF" ] && _st_work; then
		_st_phase rules
		_st_apply tunnel_ready || return 1
		_st_phase check
		sleep 2
		_st_selfcheck
	fi
	_rb_say "Готово, WARP подключён"
}

_st_own_keep() { [ -s "$ST_WARP_OWN" ] && cp -f "$ST_WARP_OWN" "$ST_WARP_OWN_KEEP" && chmod 600 "$ST_WARP_OWN_KEEP"; return 0; }
_st_own_restore() {
	[ -s "$ST_WARP_OWN" ] || [ ! -s "$ST_WARP_OWN_KEEP" ] && return 0
	mkdir -p "$ST_DIR"
	cp -f "$ST_WARP_OWN_KEEP" "$ST_WARP_OWN" && chmod 600 "$ST_WARP_OWN"
}
_st_own_saved() { [ -s "$ST_WARP_OWN" ] || [ -s "$ST_WARP_OWN_KEEP" ]; }

do_steer_warp_own() {
	_st_phase awg
	rm -f "$ST_STOP_FLAG"
	_st_installed || { echo "ОШИБКА: сначала установите Steer"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: ядро steer сейчас настраивает не Zapret Manager"; return 1; }
	if [ -s "$ST_DIR/warp.pending" ]; then mv -f "$ST_DIR/warp.pending" "$ST_WARP_OWN"; fi
	_st_own_restore
	[ -s "$ST_WARP_OWN" ] || { echo "ОШИБКА: вставьте конфиг WARP"; return 1; }
	chmod 600 "$ST_WARP_OWN"
	_st_own_keep
	_ensure_deps
	_st_install_awg || return 1
	_st_phase tunnel
	_rb_say "Свой WARP: один туннель по вашему конфигу"
	if ! _st_warp_own; then
		grep -qv "^$ST_OWN_IF " "$ST_WARP_UP" 2>/dev/null && grep -v "^$ST_OWN_IF " "$ST_WARP_UP" > "$ST_WARP_UP_AUTO"
		_st_owns "net zmwarp" && _rb_say "Автоматические туннели WARP выключаем — они сохранятся, вернуться к ним можно в один клик"
	fi
	_st_ext_leave
	_st_warp_park $(_st_wifs_auto)
	echo own > "$ST_WARP_MODE"
	_st_mode_vars
	_st_awg_loaded || modprobe amneziawg >/dev/null 2>&1
	_st_warp_own_iface "$ST_WARP_CONF" || return 1
	_st_warp_zone
	ubus call network reload >/dev/null 2>&1
	sleep 2
	_st_warp_own_up || return 1
	_st_cron_refresh
	[ "$(cat "$ST_EXIT" 2>/dev/null)" = vpn ] && [ -s "$ST_SUB" ] || echo warp > "$ST_EXIT"
	if [ ! -f "$ST_OFF" ] && _st_work; then
		_st_phase rules
		_st_apply tunnel_ready || return 1
		_st_phase check
		sleep 2
		_st_selfcheck
	fi
	_rb_say "Готово, свой WARP подключён"
}

do_steer_warp_iface() {
	local i="$1" was
	_st_phase awg
	rm -f "$ST_STOP_FLAG"
	_st_installed || { echo "ОШИБКА: сначала установите Steer"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: ядро steer сейчас настраивает не Zapret Manager"; return 1; }
	[ "$(uci -q get "network.$i.proto")" = amneziawg ] || { echo "ОШИБКА: интерфейса $i нет — создайте его на вкладке AmneziaWG"; return 1; }
	_ensure_deps
	_st_install_awg || return 1
	_st_phase tunnel
	_rb_say "Интерфейс AmneziaWG: сервисы Steer пойдут через $i"
	was="$(_st_warp_modename)"
	if [ "$was" = auto ]; then
		grep -qv "^$ST_OWN_IF " "$ST_WARP_UP" 2>/dev/null && grep -v "^$ST_OWN_IF " "$ST_WARP_UP" > "$ST_WARP_UP_AUTO"
		_st_owns "net zmwarp" && _rb_say "Автоматические туннели WARP выключаем — они сохранятся, вернуться к ним можно в один клик"
	elif [ "$was" = own ]; then
		_st_owns "net $ST_OWN_IF" && _rb_say "Свой туннель $ST_OWN_IF выключаем — он сохранится, вернуться к нему можно в один клик"
	elif [ "$(_st_ext_if)" != "$i" ]; then
		_st_ext_leave
	fi
	_st_warp_park $(_st_wifs_auto) "$ST_OWN_IF"
	echo "iface:$i" > "$ST_WARP_MODE"
	_st_mode_vars
	rm -f "$ST_WARP_UP" "$ST_DIR/warp.colo"
	_st_awg_loaded || modprobe amneziawg >/dev/null 2>&1
	_st_warp_own_up || return 1
	_st_cron_refresh
	[ "$(cat "$ST_EXIT" 2>/dev/null)" = vpn ] && [ -s "$ST_SUB" ] || echo warp > "$ST_EXIT"
	if [ ! -f "$ST_OFF" ] && _st_work; then
		_st_phase rules
		_st_apply tunnel_ready || return 1
		_st_phase check
		sleep 2
		_st_selfcheck
	fi
	_awf_ifaces | grep -qx "$i" && [ -z "$(_awf_min)" ] && _rb_say "Совет: включите автопочинку на вкладке AmneziaWG — сломается $i, роутер сам подберёт ему новую точку входа"
	_rb_say "Готово, сервисы идут через $i"
}

do_steer_warp_remove() {
	local wi gone="" netrl=0 e secs="" s p z
	_st_phase warp
	rm -f "$ST_STOP_FLAG"
	_st_installed || { echo "ОШИБКА: Steer ещё не установлен"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: ядро steer сейчас настраивает не Zapret Manager"; return 1; }
	_rb_say "Убираем WARP из Steer — сам Steer, VPN и туннели остаются"
	for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = warp ] && secs="$secs «$(_st_sec_name "$s")»"; done
	_st_ext_leave
	for wi in $(_st_wifs_every); do
		_st_owns "net $wi" || continue
		ifdown "$wi" >/dev/null 2>&1
		uci -q delete "network.$wi"
		uci -q delete "network.${wi}_peer"
		_st_peers_drop "$wi"
		sed -i "\|^net $wi\$|d" "$ST_OWNED" 2>/dev/null
		netrl=1; gone="$gone $wi"
	done
	[ "$netrl" = 1 ] && { uci commit network; /etc/init.d/network reload >/dev/null 2>&1; echo "   ✓ Туннели WARP удалены:$gone"; }
	rm -f "$ST_WARP_MODE" "$ST_DIR/warp.conf" "$ST_DIR"/warp[0-9].conf "$ST_WARP_OWN" "$ST_WARP_OWN_KEEP" "$ST_DIR/warp.pending" \
		"$ST_WARP_UP" "$ST_WARP_UP_AUTO" "$ST_WARP_GEO" "$ST_DIR/warp.colo" "$ST_WARP_PICK" "$ST_WARP_ORDER" "$ST_TGWS_WARP"
	_st_mode_vars
	if _st_owns "fw $ST_WARP_ZONE" && [ "$(uci -q get "firewall.$ST_WARP_ZONE")" = zone ]; then
		z="$(_st_secs_zoneless | tr '\n' ' ' | sed 's/ $//')"
		if [ -z "$z" ]; then
			uci -q delete "firewall.$ST_WARP_ZONE"; uci -q delete "firewall.${ST_WARP_ZONE}_fwd"
			sed -i "\|^fw $ST_WARP_ZONE\$|d" "$ST_OWNED" 2>/dev/null
			echo "   ✓ Зона файрвола WARP убрана"
		else
			uci -q delete "firewall.$ST_WARP_ZONE.network"
			for wi in $z; do uci add_list "firewall.$ST_WARP_ZONE.network=$wi"; done
		fi
		uci commit firewall
		/etc/init.d/firewall reload >/dev/null 2>&1
	fi
	_st_wfix_set off >/dev/null 2>&1; _st_wfix_cron
	e="$(cat "$ST_EXIT" 2>/dev/null)"
	case "$e" in
		vpn|iface) ;;
		*) if [ -s "$ST_SUB" ]; then echo vpn > "$ST_EXIT"; _rb_say "Сервисы основной секции теперь идут через VPN"
		   else rm -f "$ST_EXIT"; _rb_warn "У основной секции больше нет подключения — её сервисы идут напрямую, пока не выберете VPN или туннель"; fi ;;
	esac
	[ -n "$secs" ] && _rb_warn "Секции$secs были подключены к WARP — их сервисы идут напрямую, пока не выберете им VPN или туннель"
	if [ "$1" = awg ]; then
		if uci show network 2>/dev/null | grep -q "\.proto='amneziawg'"; then
			_rb_warn "AmneziaWG оставлен: на роутере есть другие его туннели (вкладка AmneziaWG)"
		else
			for p in luci-i18n-amneziawg-ru luci-proto-amneziawg luci-app-amneziawg amneziawg-tools kmod-amneziawg; do
				_st_owns "pkg $p" || continue
				_zm_pkg_purge "$p" >/dev/null 2>&1 && sed -i "\|^pkg $p\$|d" "$ST_OWNED" 2>/dev/null
			done
			_pkg_is_installed kmod-amneziawg || _awg_kmod_manual_rm
			_pkg_is_installed amneziawg-tools || _pkg_is_installed kmod-amneziawg || echo "   ✓ AmneziaWG удалён"
			_pkg_is_installed kmod-amneziawg && _rb_warn "AmneziaWG ставил не Steer — удалить его можно на вкладке AmneziaWG"
		fi
	elif ! uci show network 2>/dev/null | grep -q "\.proto='amneziawg'"; then
		_rb_say "AmneziaWG больше ничем не используется — его можно удалить на вкладке AmneziaWG"
	fi
	if [ ! -f "$ST_OFF" ] && _st_work; then
		_st_phase rules
		_st_apply || return 1
		_st_phase check
		sleep 2
		_st_selfcheck
	fi
	logger -t zapret-manager "Steer: WARP убран$gone"
	_rb_say "Готово, WARP убран из Steer"
}

do_steer_ext_pick() {
	local i
	_st_phase warp
	rm -f "$ST_STOP_FLAG"
	_st_warp_ext || { echo "ОШИБКА: Steer сейчас работает не через интерфейс AmneziaWG"; return 1; }
	i="$(_st_ext_if)"
	do_awg_pick "$i" || return 1
	_awg_steer_sync "$i" force
	_rb_say "Готово"
}

do_steer_warp_auto() {
	_st_phase awg
	rm -f "$ST_STOP_FLAG"
	_st_installed || { echo "ОШИБКА: сначала установите Steer"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: ядро steer сейчас настраивает не Zapret Manager"; return 1; }
	_ensure_deps
	_st_install_awg || return 1
	_st_phase tunnel
	_rb_say "Автоматический WARP: три туннеля с ключами от Cloudflare"
	_st_warp_ownconf && _st_owns "net $ST_OWN_IF" && _rb_say "Свой туннель $ST_OWN_IF выключаем — он сохранится, вернуться к нему можно в один клик"
	_st_ext_leave
	rm -f "$ST_WARP_MODE"
	_st_mode_vars
	_st_warp_park "$ST_OWN_IF"
	_st_warp_zone
	if [ "$(uci -q get "network.zmwarp_peer.description")" = "Свой WARP" ]; then
		ifdown zmwarp >/dev/null 2>&1
		uci -q delete network.zmwarp; uci -q delete network.zmwarp_peer; uci commit network
		rm -f "$ST_DIR/warp.conf" "$ST_WARP_UP_AUTO"
	fi
	rm -f "$ST_WARP_UP"
	[ -s "$ST_WARP_UP_AUTO" ] && mv -f "$ST_WARP_UP_AUTO" "$ST_WARP_UP"
	if _st_warp_resume; then
		awk '{ printf "%s%s", (NR > 1 ? ", " : ""), $2 }' "$ST_WARP_UP" > "$ST_DIR/warp.colo"
		_st_tgws_warp
	else
		_st_warp_up || return 1
	fi
	_st_cron_refresh
	[ "$(cat "$ST_EXIT" 2>/dev/null)" = vpn ] && [ -s "$ST_SUB" ] || echo warp > "$ST_EXIT"
	if [ ! -f "$ST_OFF" ] && _st_work; then
		_st_phase rules
		_st_apply tunnel_ready || return 1
		_st_phase check
		sleep 2
		_st_selfcheck
	fi
	_rb_say "Готово, автоматический WARP подключён"
}

_st_warp_fix() {
	local n="$1" i c peer got busy="" busyip="" w=0 host port x col
	_st_warp_own && { echo "ОШИБКА: у Steer свой конфиг WARP — замените его в «Подключении» Steer"; return 1; }
	[ "$n" -ge 1 ] 2>/dev/null && [ "$n" -le "$ST_WARP_MAX" ] || { echo "ОШИБКА: $ST_OWN_IF — свой туннель, новые ключи ему не нужны; замените конфиг на странице Steer"; return 1; }
	i="$(_st_wif "$n")"; c="$(_st_wconf "$n")"
	_st_awg_loaded || modprobe amneziawg >/dev/null 2>&1
	if [ "$2" = keys ] || [ ! -s "$c" ] || [ "$(uci -q get "network.$i.proto")" != amneziawg ]; then
		host="$(uci -q get "network.${i}_peer.endpoint_host")"; port="$(uci -q get "network.${i}_peer.endpoint_port")"
		if [ "$2" = keys ] || [ ! -s "$c" ]; then
			[ -f "$c" ] && mv "$c" "$c.old"
			_rb_say "WARP $n: получаем новые ключи"
			if ! _st_with "$n" _st_warp_register; then
				[ -f "$c.old" ] && mv "$c.old" "$c"
				echo "ОШИБКА: WARP $n — новые ключи не получены, оставляем прежние"
				return 1
			fi
			rm -f "$c.old"
		fi
		_st_with "$n" _st_warp_iface_write "${host:-162.159.192.1}" "${port:-2408}"
		_st_warp_zone
		ubus call network reload >/dev/null 2>&1
		sleep 2
	fi
	uci -q get "network.$i.auto" >/dev/null && { uci -q delete "network.$i.auto"; uci -q commit network; }
	ubus call "network.interface.$i" up >/dev/null 2>&1
	while [ "$w" -lt 20 ] && ! _st_warp_ready_if "$i"; do w=$((w + 1)); sleep 1; done
	_st_warp_ready_if "$i" || { echo "ОШИБКА: WARP $n — интерфейс не поднялся"; return 1; }
	peer="$(_st_with "$n" _st_warp_field PublicKey)"
	if [ -s "$ST_WARP_UP" ]; then
		while read -r x col; do
			[ "$x" = "$i" ] && continue
			busy="$busy $col"; busyip="$busyip $(uci -q get "network.${x}_peer.endpoint_host")"
		done < "$ST_WARP_UP"
	fi
	_rb_say "WARP $n: подбираем точку входа"
	if ! got="$(_st_warp_scan "$i" "$peer" "$busy" "$busyip")"; then
		ifdown "$i" >/dev/null 2>&1
		echo "ОШИБКА: WARP $n — ни одна точка входа не ответила; попробуйте новые ключи"
		return 1
	fi
	set -- $got
	if _st_warp_is_ru "$3"; then
		ifdown "$i" >/dev/null 2>&1
		echo "ОШИБКА: WARP $n — нашлась только точка через российский узел $3, её не берём; попробуйте позже или новые ключи"
		return 1
	fi
	_st_warp_link "$i" "$peer" "$1" "$2" >/dev/null 2>&1
	uci set "network.${i}_peer.endpoint_host=$1"
	uci set "network.${i}_peer.endpoint_port=$2"
	uci commit network
	{
		[ -s "$ST_WARP_UP" ] && while read -r x col; do [ "$x" = "$i" ] || echo "$x $col -"; done < "$ST_WARP_UP"
		echo "$i $3 ${4:--}"
	} > "$ST_WARP_UP.tmp"
	_st_warp_order "$ST_WARP_UP.tmp"
	mv "$ST_WARP_UP.tmp" "$ST_WARP_UP"
	awk '{ printf "%s%s", (NR > 1 ? ", " : ""), $2 }' "$ST_WARP_UP" > "$ST_DIR/warp.colo"
	_st_tgws_warp
	_rb_say "WARP $n работает: $1:$2, колония $3"
	_st_warp_geo "$i"
}

do_steer_warp_fix() {
	_st_phase warp
	_st_need_warp || return 1
	rm -f "$ST_STOP_FLAG"
	_st_warp_fix "$1" "$2" || return 1
	_st_respec
	_rb_say "Готово"
}

ST_WFIX="$ST_DIR/wfix"
ST_WFIX_STATE="$ST_DIR/wfix.state"
ST_WFIX_LOG="$ST_DIR/wfix.log"
ST_WFIX_TAG="# zm-wfix"
ST_WFIX_TRIES=4

_st_wfix_say() {
	mkdir -p "$ST_DIR"
	{ tail -n 19 "$ST_WFIX_LOG" 2>/dev/null; echo "$(date +%s)|$1"; } > "$ST_WFIX_LOG.tmp" && mv -f "$ST_WFIX_LOG.tmp" "$ST_WFIX_LOG"
	logger -t zm-steer "автоподбор: $1" 2>/dev/null
}

_st_wfix_get() { awk -v i="$1" -v f="$2" '$1 == i { print $f; exit }' "$ST_WFIX_STATE" 2>/dev/null; }
_st_wfix_put() {
	mkdir -p "$ST_DIR"
	{ grep -v "^$1 " "$ST_WFIX_STATE" 2>/dev/null; [ "$2" = - ] || echo "$1 $2 ${3:-0} ${4:-0}"; } > "$ST_WFIX_STATE.tmp.$$"
	mv -f "$ST_WFIX_STATE.tmp.$$" "$ST_WFIX_STATE"
	[ -s "$ST_WFIX_STATE" ] || rm -f "$ST_WFIX_STATE"
}

_st_wfix_hs() { awg show "$1" latest-handshakes 2>/dev/null | awk '{ print $2 + 0; exit }'; }

_st_wfix_alive() {
	local hs
	[ -d "/sys/class/net/$1" ] || return 1
	hs="$(_st_wfix_hs "$1")"
	[ "${hs:-0}" -gt 0 ] 2>/dev/null && [ $(( $(date +%s) - hs )) -lt 300 ] || return 1
	_st_if_ru "$1" "$(awk -v i="$1" '$1 == i { print $2; exit }' "$ST_WARP_UP" 2>/dev/null)" && return 1
	ping -I "$1" -c 2 -W 3 1.1.1.1 >/dev/null 2>&1 || ping -I "$1" -c 2 -W 3 8.8.8.8 >/dev/null 2>&1
}

_st_wfix_net_ok() {
	ping -c 2 -W 3 1.1.1.1 >/dev/null 2>&1 || ping -c 2 -W 3 8.8.8.8 >/dev/null 2>&1 ||
		curl -s -o /dev/null --connect-timeout 5 --max-time 8 https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null
}

_st_wfix_min() { local m; m="$(cat "$ST_WFIX" 2>/dev/null)"; case "$m" in 30|60|180) echo "$m" ;; *) echo "" ;; esac; }

_st_wfix_set() {
	case "$1" in
		off) rm -f "$ST_WFIX" "$ST_WFIX_STATE" "$ST_RUN/wfix.last" "$ST_DIR/wfix.last" ;;
		30|60|180) mkdir -p "$ST_DIR"; echo "$1" > "$ST_WFIX" ;;
		*) echo '{"error":"допустимо: выкл, 30, 60 или 180 минут"}'; return 1 ;;
	esac
	_st_wfix_cron
	[ "$1" = off ] || ( _st_wfix_tick >/dev/null 2>&1 & )
	printf '{"ok":true}\n'
}

_st_wfix_cron() {
	local want=""
	[ -n "$(_st_wfix_min)" ] && want="*/10 * * * * /opt/zapret-manager-luci/backend.sh steer_action wfix_tick x >/dev/null 2>&1 $ST_WFIX_TAG"
	if [ -n "$want" ]; then
		grep -qxF "$want" "$CRON_FILE" 2>/dev/null && return 0
	else
		grep -qF "$ST_WFIX_TAG" "$CRON_FILE" 2>/dev/null || return 0
	fi
	mkdir -p "$(dirname "$CRON_FILE")"
	touch "$CRON_FILE"
	sed -i "\\|$ST_WFIX_TAG|d" "$CRON_FILE"
	[ -n "$want" ] && echo "$want" >> "$CRON_FILE"
	/etc/init.d/cron enable >/dev/null 2>&1
	/etc/init.d/cron restart >/dev/null 2>&1
	return 0
}

_st_wfix_tick() {
	local lim now n i since tries last dead="" all=1 any=0 pick="" pn="" keys=""
	lim="$(_st_wfix_min)"
	[ -n "$lim" ] || return 0
	_st_installed || return 0
	[ -f "$ST_OFF" ] && return 0
	[ -n "$(_st_blocker)" ] && return 0
	_st_warp_own && return 0
	[ "$(_st_exit)" = warp ] || return 0
	_st_running && return 0
	_st_work || return 0
	now="$(date +%s)"
	mkdir -p "$ST_RUN"
	echo "$now" > "$ST_RUN/wfix.last"
	n=1
	while [ "$n" -le "$ST_WARP_MAX" ]; do
		i="$(_st_wif "$n")"
		n=$((n + 1))
		_st_owns "net $i" || continue
		[ -s "$(_st_wconf $((n - 1)))" ] || continue
		any=1
		if _st_wfix_alive "$i"; then
			all=0
			since="$(_st_wfix_get "$i" 2)"
			if [ -n "$since" ]; then
				_st_wfix_put "$i" -
				_st_wfix_say "WARP $((n - 1)) снова работает"
			fi
			continue
		fi
		since="$(_st_wfix_get "$i" 2)"; tries="$(_st_wfix_get "$i" 3)"; last="$(_st_wfix_get "$i" 4)"
		if [ -z "$since" ]; then
			since="$(_st_wfix_hs "$i")"
			[ "${since:-0}" -gt 0 ] 2>/dev/null && [ "$since" -le "$now" ] && [ $((now - since)) -ge 300 ] || since="$now"
			tries=0; last=0
			_st_wfix_put "$i" "$since" 0 0
		fi
		dead="$dead $((n - 1))"
		[ "${tries:-0}" -ge "$ST_WFIX_TRIES" ] && continue
		[ $((now - since)) -ge $((lim * 60)) ] || continue
		[ $((now - ${last:-0})) -ge $((lim * 60)) ] || continue
		[ -z "$pick" ] && { pick="$i"; pn=$((n - 1)); }
	done
	[ "$any" = 1 ] && [ -n "$pick" ] || return 0
	if [ "$all" = 1 ] && ! _st_wfix_net_ok; then
		[ -f "$ST_RUN/wfix.nonet" ] || { mkdir -p "$ST_RUN"; touch "$ST_RUN/wfix.nonet"; _st_wfix_say "нет интернета — подбор отложен"; }
		return 0
	fi
	rm -f "$ST_RUN/wfix.nonet"
	tries="$(_st_wfix_get "$pick" 3)"; since="$(_st_wfix_get "$pick" 2)"
	[ "${tries:-0}" -ge 2 ] && keys=keys
	_st_wfix_put "$pick" "$since" $(( ${tries:-0} + 1 )) "$now"
	job_start steer do_steer_wfix "$pn" "$keys" "$since" >/dev/null
}

do_steer_wfix() {
	local n="$1" keys="$2" since="$3" i mins tries
	i="$(_st_wif "$n")"
	mins=$(( ($(date +%s) - ${since:-$(date +%s)}) / 60 ))
	tries="$(_st_wfix_get "$i" 3)"
	_st_phase warp
	rm -f "$ST_STOP_FLAG"
	mkdir -p "$ST_RUN"; echo "$n" > "$ST_RUN/wfix.busy"
	_rb_say "Автоподбор: WARP $n не работает $mins мин — подбираем новую точку входа${keys:+ с новыми ключами} (попытка ${tries:-1} из $ST_WFIX_TRIES)"
	if _st_warp_fix "$n" "$keys"; then
		rm -f "$ST_RUN/wfix.busy"
		_st_wfix_put "$i" -
		_st_kick
		set -- $(awk -v i="$i" '$1 == i { print $2; exit }' "$ST_WARP_UP" 2>/dev/null)
		_st_wfix_say "WARP $n не работал $mins мин — подобрана точка $(uci -q get "network.${i}_peer.endpoint_host"):$(uci -q get "network.${i}_peer.endpoint_port")${1:+, колония $1}${keys:+, новые ключи}"
		_rb_say "Готово"
		return 0
	fi
	rm -f "$ST_RUN/wfix.busy"
	_st_stopped && { _st_wfix_say "WARP $n: подбор остановлен вручную"; return 1; }
	if [ "${tries:-0}" -ge "$ST_WFIX_TRIES" ]; then
		_st_wfix_say "WARP $n: $ST_WFIX_TRIES попытки подбора не помогли — автоподбор для него остановлен до ручной починки"
	else
		_st_wfix_say "WARP $n: новая точка не нашлась (попытка $tries из $ST_WFIX_TRIES), повторим через $(_st_wfix_min) мин"
	fi
	return 1
}

_st_wfix_json() {
	local m out="" sep="" i since tries last t txt n fixing=""
	m="$(_st_wfix_min)"
	if [ -s "$ST_WFIX_STATE" ]; then
		while read -r i since tries last; do
			[ -n "$i" ] || continue
			case "$i" in zmwarp) n=1 ;; *) n="${i#zmwarp}" ;; esac
			out="$out$sep{\"n\":${n:-0},\"since\":${since:-0},\"tries\":${tries:-0},\"last\":${last:-0}}"; sep=","
		done < "$ST_WFIX_STATE"
	fi
	_st_running && [ -s "$ST_RUN/wfix.busy" ] && fixing="$(cat "$ST_RUN/wfix.busy")"
	printf '{"mode":"%s","max":%s,"now":%s,"last_check":%s,"fixing":"%s","dead":[%s],"log":[' "${m:-off}" "$ST_WFIX_TRIES" "$(date +%s)" \
		"$(awk '{ print $1 + 0; exit }' "$ST_RUN/wfix.last" 2>/dev/null | grep . || echo 0)" "$fixing" "$out"
	sep=""
	[ -s "$ST_WFIX_LOG" ] && tail -n 5 "$ST_WFIX_LOG" | while IFS='|' read -r t txt; do
		printf '%s{"t":%s,"text":"%s"}' "$sep" "${t:-0}" "$(esc "$txt")"; sep=","
	done
	printf ']}'
}

_st_spec_quick0() {
	local m="$ST_RUN/model" f
	[ -f "$ST_DIR/model.svc" ] && _st_owns "steer-spec" && stl_running || return 2
	for f in $(awk -F'\t' '$1 == "srs" || $1 == "dom" || $1 == "pfx" { print $2 }' "$ST_DIR/model.svc"); do [ -s "$f" ] || return 2; done
	_st_secs_fit || return 2
	if { ! _st_use_vpn && _st_warp_on; } || { _st_warp_on && _st_secs_warp; }; then [ -s "$ST_WARP_UP" ] || return 2; fi
	_st_engine_ready || return 1
	_st_vpn_any && _st_vpn_zone on
	_st_secs_fw
	mkdir -p "$ST_RUN"
	{
		_st_model_head
		cat "$ST_DIR/model.svc"
	} > "$m"
	stl_apply "$m"; f=$?
	rm -f "$m"
	return $f
}
_st_spec_quick() { _st_sec_with main _st_spec_quick0; }
_st_spec_quick_warp() { _st_sec_with main _st_spec_quick0; }

_st_respec() {
	local rc
	if _st_use_vpn; then _st_spec_quick; else _st_spec_quick_warp; fi
	rc=$?
	[ "$rc" = 0 ] && { echo "   ✓ Правила обновлены, списки сервисов не перекачивались"; return 0; }
	_st_kick
}

do_steer_dnsopt() {
	_st_phase rules
	rm -f "$ST_STOP_FLAG"
	_st_dnsopt_save "$1" "$2"
	case "$1:$2" in
		dnsmode:router) _rb_say "Адреса выбранных сервисов узнаёт DNS роутера" ;;
		dnsmode:*) _rb_say "Адреса выбранных сервисов узнаются через туннель — как при полном VPN" ;;
		realip:on) _rb_say "Точно по IP: роутер отдаёт настоящие адреса выбранных сервисов" ;;
		realip:*) _rb_say "Точно по IP выключено: роутер отдаёт подменные адреса" ;;
		cttl:0) _rb_say "Адреса сервисов помнятся столько, сколько разрешает DNS" ;;
		cttl:*) _rb_say "Адреса сервисов помнятся не меньше $(($2 / 60)) мин — приложения, которые долго держат адрес, не уходят мимо туннеля" ;;
	esac
	_st_respec
	_rb_say "Готово"
}

do_steer_onfail() {
	_st_phase rules
	rm -f "$ST_STOP_FLAG"
	mkdir -p "$ST_DIR"
	if [ "$1" = drop ]; then
		echo drop > "$ST_DIR/onfail"
		_rb_say "Туннель недоступен — выбранные сервисы останавливаются, мимо туннеля не идут"
	else
		rm -f "$ST_DIR/onfail"
		_rb_say "Туннель недоступен — выбранные сервисы идут напрямую"
	fi
	_st_respec
	_rb_say "Готово"
}

_st_node_label() { local n; n="$(cat "$ST_SUB_NODE" 2>/dev/null)"; [ -n "$n" ] && printf '«%s»' "$n" || printf 'автовыбор'; }

do_steer_switch() {
	local prev="${1:--}" rc why pol
	rm -f "$ST_STOP_FLAG"
	_st_installed || { echo "ОШИБКА: Steer ещё не установлен"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: настройку ядра steer сейчас ведёт не Zapret Manager"; return 1; }
	_st_phase rules
	_rb_say "Переключаем VPN: $(_st_node_label) — списки сервисов и правила не трогаем"
	_st_spec_quick; rc=$?
	if [ "$rc" = 2 ]; then
		_rb_say "Списки ещё не собирались — применяем настройку целиком"
		do_steer_apply; return $?
	fi
	[ "$rc" = 0 ] || return 1
	_st_phase check
	if _st_vpn_check 30; then _rb_say "Готово"; return 0; fi
	why="$STL_NWHY"
	pol="$(_st_node_pol)"
	if [ "$pol" = hold ] && [ -s "$ST_SUB_NODE" ]; then
		_rb_warn "Узел $(_st_node_label) не отвечает${why:+ ($why)} — держим его, как задано в «Если выбранный узел не отвечает»: $(_st_fail_text), пока он не ответит"
		return 0
	fi
	[ "$pol" = back ] && [ -s "$ST_SUB_NODE" ] && { mkdir -p "$ST_DIR"; head -n1 "$ST_SUB_NODE" > "$ST_SUB_HOME"; }
	case "$prev" in
		-) _rb_say "Готово, но VPN сейчас не отвечает — сторож Steer переключит на рабочий узел сам"; return 0 ;;
		auto) [ -s "$ST_SUB_NODE" ] || { _rb_say "Сторож Steer сам переберёт узлы"; return 0; }
			_rb_warn "Узел $(_st_node_label) не отвечает${why:+ ($why)} — возвращаем автовыбор"
			mkdir -p "$ST_DIR"; head -n1 "$ST_SUB_NODE" > "$ST_SUB_FELL"; rm -f "$ST_SUB_NODE" ;;
		*) [ "$prev" = "$(cat "$ST_SUB_NODE" 2>/dev/null)" ] && return 0
			_rb_warn "Узел $(_st_node_label) не отвечает${why:+ ($why)} — возвращаем прежний «$prev»"
			mkdir -p "$ST_DIR"; head -n1 "$ST_SUB_NODE" > "$ST_SUB_FELL"
			if _st_key_in "$(_st_nodes)" "$prev"; then printf '%s\n' "$prev" > "$ST_SUB_NODE"; else rm -f "$ST_SUB_NODE"; fi ;;
	esac
	_st_spec_quick || return 1
	if _st_vpn_check 30; then
		_rb_say "Готово: VPN снова работает через $(_st_node_label)$([ -s "$ST_SUB_HOME" ] && printf ' — на «%s» вернёмся, когда он ответит' "$(head -n1 "$ST_SUB_HOME")")"
		return 0
	fi
	_rb_warn "И прежний выбор не отвечает — сторож Steer будет искать рабочий узел сам"
	return 0
}

do_steer_apply() {
	_st_phase rules
	rm -f "$ST_STOP_FLAG"
	_st_installed || { echo "ОШИБКА: Steer ещё не установлен"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: настройку ядра steer сейчас ведёт не Zapret Manager"; return 1; }
	rm -f "$ST_OFF"
	_st_apply || return 1
	_st_phase check
	sleep 2
	_st_selfcheck
	_rb_say "Готово"
}

do_steer_stop() {
	_st_phase rules
	_st_installed || { echo "ОШИБКА: Steer ещё не установлен"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: ядро steer сейчас настраивает не Zapret Manager"; return 1; }
	touch "$ST_OFF"
	_st_down
	rm -f "$ST_TGWS_WARP"
	if [ -f /etc/config/https-dns-proxy ]; then
		_doh_force_apply
	fi
	_rb_say "Готово, Steer и туннель выключены — всё идёт напрямую"
}

_st_need_warp() {
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: ядро steer сейчас настраивает не Zapret Manager"; return 1; }
	_st_warp_on && return 0
	echo "ОШИБКА: WARP ещё не подключён — подключите его в «Подключении» Steer"
	return 1
}

do_steer_warp_restart() {
	_st_phase warp
	_st_need_warp || return 1
	rm -f "$ST_STOP_FLAG"
	_rb_say "Перезапускаем туннель WARP"
	_st_warp_up || return 1
	_st_respec
	_rb_say "Готово"
}

do_steer_warp_endpoint() {
	_st_phase warp
	_st_need_warp || return 1
	rm -f "$ST_STOP_FLAG"
	_st_warp_up repick || return 1
	_st_respec
	_rb_say "Готово, точка входа подобрана"
}

do_steer_warp_recreate() {
	_st_phase warp
	_st_need_warp || return 1
	_st_warp_own && { echo "ОШИБКА: в этом режиме ключи задаёт ваш конфиг или интерфейс AmneziaWG — новые ключи Steer не получает"; return 1; }
	rm -f "$ST_STOP_FLAG"
	local n c host port
	_rb_say "Пересоздаём WARP с новыми ключами"
	n=1
	while [ "$n" -le "$ST_WARP_N" ]; do
		c="$(_st_wconf "$n")"
		[ -f "$c" ] && mv "$c" "$c.old"
		if ! _st_with "$n" _st_warp_register; then
			[ -f "$c.old" ] && mv "$c.old" "$c"
			[ "$n" = 1 ] && { echo "ОШИБКА: не удалось получить новые ключи — оставляем прежние"; return 1; }
			_rb_warn "WARP $n: новых ключей нет — оставляем прежние"
		else
			rm -f "$c.old"
			host="$(uci -q get "network.$(_st_wif "$n")_peer.endpoint_host")"
			port="$(uci -q get "network.$(_st_wif "$n")_peer.endpoint_port")"
			_st_with "$n" _st_warp_iface_write "${host:-162.159.192.1}" "${port:-2408}"
		fi
		n=$((n + 1))
	done
	ubus call network reload >/dev/null 2>&1
	_st_warp_up repick || return 1
	_st_respec
	_rb_say "Готово, WARP пересоздан"
}

do_steer_remove() {
	local rc
	_do_steer_remove_core "$@"; rc=$?
	stl_present || rm -f "$FT_STEER_OFF"
	_ft_steer_sync
	return $rc
}
_do_steer_remove_core() {
	_st_phase remove
	rm -f "$ST_HEAL_STAMP"
	_rb_say "Удаляем Steer и туннель WARP"
	local foreign="" p pkgs="" rc=0 keepf="$JOBS_DIR/steer.keep.$$" keptif="" kept=0 alien="" ownpk=""
	case "$(_st_blocker)" in
		splify2) foreign=splify2 ;;
		steer) foreign="чужой настройке (правила в $STL_ETC писала не панель)" ;;
	esac
	[ -z "$foreign" ] && foreign="$(stl_busy_by)"
	if [ -n "$foreign" ]; then
		sed -i '/^steer-spec$/d; /^pkg steer/d' "$ST_OWNED" 2>/dev/null
		_rb_warn "Ядро steer нужно $foreign — оставляем его и его правила"
	else
		_st_spec_clear
		stl_stop
		echo "   ✓ Ядро steer остановлено, правила панели сняты"
		[ "$(stl_spec_whose)" = foreign ] && alien=1
	fi
	local wi netrl=0 gone=""
	: > "$keepf"
	[ -n "$foreign" ] && _zm_engine_refs engine > "$keepf" 2>/dev/null
	for wi in $(_st_wifs_every); do
		_st_owns "net $wi" || continue
		if [ -n "$foreign" ] && grep -qsw -- "$wi" "$STL_SPEC" "$STL_YAML"; then keptif="$keptif $wi"; continue; fi
		ifdown "$wi" >/dev/null 2>&1
		uci -q delete "network.$wi"
		uci -q delete "network.${wi}_peer"
		netrl=1
		gone="$gone $wi"
	done
	[ "$netrl" = 1 ] && { uci commit network; /etc/init.d/network reload >/dev/null 2>&1; echo "   ✓ Туннели удалены:$gone"; }
	[ -n "$keptif" ] && _rb_warn "Туннели$keptif оставлены — они записаны в правилах ядра steer, которые ведёт $foreign"
	_st_ext_release_fwd
	for p in $(sed -n 's/^fw \(zmsec_[A-Za-z0-9_]*\)$/\1/p' "$ST_OWNED" 2>/dev/null); do uci -q delete "firewall.$p"; uci commit firewall; done
	_st_lan_fw_drop
	rm -f "$ST_TUN_HOOK" "$ST_DIR/tun.watch"
	if [ -z "$keptif" ] && _st_owns "fw $ST_WARP_ZONE"; then
		uci -q delete "firewall.$ST_WARP_ZONE"
		uci -q delete "firewall.${ST_WARP_ZONE}_fwd"
		uci commit firewall
		/etc/init.d/firewall reload >/dev/null 2>&1
		echo "   ✓ Зона файрвола туннеля убрана"
	fi
	if grep -qF "$ST_CRON_TAG" "$CRON_FILE" 2>/dev/null || grep -qF "# zm-subupd" "$CRON_FILE" 2>/dev/null || grep -qF "$ST_WFIX_TAG" "$CRON_FILE" 2>/dev/null || grep -qF "$ST_PING_TAG" "$CRON_FILE" 2>/dev/null; then
		sed -i "\\|$ST_CRON_TAG|d; \\|# zm-subupd|d; \\|$ST_WFIX_TAG|d; \\|$ST_PING_TAG|d" "$CRON_FILE"
		/etc/init.d/cron restart >/dev/null 2>&1
		echo "   ✓ Задания расписания Steer убраны"
	fi
	if [ -n "$foreign" ] && grep -qsw -- "$STL_VPN_DEV" "$STL_SPEC" "$STL_YAML"; then :; else _st_vpn_zone off; fi
	for p in $(sed -n 's/^pkg \(steer[a-z0-9-]*\)$/\1/p' "$ST_OWNED" 2>/dev/null); do pkgs="$pkgs $p"; done
	if [ -z "$foreign" ] && [ -z "$alien" ]; then
		for p in $(stl_pkgs_installed); do case " $pkgs " in *" $p "*) ;; *) pkgs="$pkgs $p" ;; esac; done
	fi
	[ -n "$pkgs" ] && { stl_engine_remove $pkgs || rc=1; }
	_st_owns "pkg conntrack" && { _zm_pkg_purge conntrack || rc=1; }
	if ! uci show network 2>/dev/null | grep -q "\.proto='amneziawg'"; then
		local p
		for p in luci-i18n-amneziawg-ru luci-proto-amneziawg luci-app-amneziawg amneziawg-tools kmod-amneziawg; do
			_st_owns "pkg $p" && { _zm_pkg_purge "$p" || rc=1; }
		done
		_pkg_is_installed kmod-amneziawg || _awg_kmod_manual_rm
	fi
	_rb_rpcd_ensure
	[ "$rc" = 0 ] || ownpk="$(grep '^pkg ' "$ST_OWNED" 2>/dev/null)"
	if [ -n "$foreign" ] && grep -q "^$ST_DIR/" "$keepf" 2>/dev/null; then
		find "$ST_DIR" \( -type f -o -type l \) 2>/dev/null | while IFS= read -r p; do grep -qxF "$p" "$keepf" || rm -f "$p"; done
		find "$ST_DIR" -depth -type d -exec rmdir {} \; 2>/dev/null
		kept="$(find "$ST_DIR" -type f 2>/dev/null | grep -c .)"
		_zm_wipe "$ST_RUN" "$ST_TGWS_WARP" || rc=1
	else
		_zm_wipe "$ST_DIR" "$ST_RUN" "$ST_TGWS_WARP" && echo "   ✓ Файлы, настройки и подписки Steer удалены" || rc=1
	fi
	rm -f "$keepf"
	[ -n "$foreign" ] || stl_leftovers
	if [ "$rc" != 0 ]; then
		[ -n "$ownpk" ] && { mkdir -p "$ST_DIR"; printf '%s\n' "$ownpk" > "$ST_OWNED"; }
		stl_present && _st_own "engine"
	fi
	_zm_after_remove "Steer"
	if [ "$rc" = 0 ] && [ -n "$alien" ] && stl_present; then
		_rb_warn "Ядро steer оставлено: в нём правила, которые писала не панель ($STL_ETC)"
		echo "==> Готово: Steer панели удалён. Ядро steer осталось на роутере — им пользуется чужая настройка"
		_zm_rb_note
		return 0
	fi
	if [ "$rc" = 0 ] && [ -z "$foreign" ] && stl_present; then
		_rb_warn "Команда steer всё ещё есть на роутере: $(command -v steer). Она стоит не из пакета — панель её не удаляет"
		echo "==> Готово: Steer панели удалён, но само ядро steer осталось — см. строку выше"
		_zm_rb_note
		return 0
	fi
	if [ "$rc" = 0 ] && [ -n "$foreign" ] && [ "${kept:-0}" = 0 ] && [ -z "$keptif" ]; then
		echo "==> Готово: Steer панели удалён. Ядро steer оставлено — оно нужно $foreign"
		_zm_rb_note
		return 0
	fi
	if [ "$rc" = 0 ] && { [ "${kept:-0}" -gt 0 ] || [ -n "$keptif" ]; }; then
		[ "${kept:-0}" -gt 0 ] && _rb_warn "В $ST_DIR оставлено файлов: $kept — на них ссылаются правила ядра steer, которые ведёт $foreign. Без них ядро не запустится"
		echo "==> Готово: Steer панели удалён. Оставлено только то, чем пользуется $foreign"
		_zm_rb_note
		return 0
	fi
	_zm_rm_done "$rc" "Steer"
}

steer_status() {
	_st_cust_split
	ZM_STL_CACHE=1; STL_ST_J=""
	stl_present && STL_ST_J="$(_stl_t 10 steer status 2>/dev/null)"
	local running=false phase="" blk colo="" warp_up=false installed=false ver="" run=false chans=0 dns=false
	local host="" port="" hs="" age="" rx=0 tx=0 off=false svc="" id sel=" " skip w k r
	_st_running && running=true
	[ -f "$ST_PHASE_FILE" ] && phase=$(cat "$ST_PHASE_FILE")
	blk="$(_st_blocker)"
	_st_installed && installed=true
	[ -z "$blk" ] && [ "$installed" = false ] && _fk_installed && blk="$(_fk_foreign && echo netshift || echo forkozz)"
	[ -f "$ST_OFF" ] && off=true
	if [ -s "$ST_WARP_UP" ]; then
		colo=$(while read -r w k; do [ -d "/sys/class/net/$w" ] && printf '%s\n' "$k"; done < "$ST_WARP_UP" | tr '\n' ',' | sed 's/,$//; s/,/, /g')
		[ -n "$colo" ] && warp_up=true
	elif [ -f "$ST_DIR/warp.colo" ]; then
		colo=$(cat "$ST_DIR/warp.colo")
		[ -d "/sys/class/net/$ST_WARP_IF" ] && warp_up=true
	fi
	if _st_wnet "$ST_WARP_IF"; then
		k="$(_st_wpeer "$ST_WARP_IF")"
		host="$(uci -q get "network.$k.endpoint_host")"
		port="$(uci -q get "network.$k.endpoint_port")"
	fi
	if [ "$warp_up" = true ] && command -v awg >/dev/null 2>&1; then
		for w in $(_st_wifs_all); do
			[ -d "/sys/class/net/$w" ] || continue
			k=$(awg show "$w" latest-handshakes 2>/dev/null | awk '{print $2; exit}')
			[ "${k:-0}" -gt "${hs:-0}" ] 2>/dev/null && hs="$k"
			set -- $(awg show "$w" transfer 2>/dev/null | head -n1)
			rx=$((rx + ${2:-0})); tx=$((tx + ${3:-0}))
		done
		[ -n "$hs" ] && [ "$hs" != 0 ] && age=$(( $(date +%s) - hs ))
	fi
	if stl_present; then
		ver="$(stl_version)"
		stl_running && run=true
		_st_owns "steer-spec" && chans="$(stl_rules)"
	fi
	_st_dns_conflict && dns=true
	local doh="" dohn=0 u
	if [ -x /etc/init.d/https-dns-proxy ] && /etc/init.d/https-dns-proxy running >/dev/null 2>&1; then
		while u="$(uci -q get "https-dns-proxy.@https-dns-proxy[$dohn].resolver_url")"; do
			dohn=$((dohn + 1)); [ "$dohn" = 1 ] && doh="$(_doh_provider_of "$u")"; [ "$dohn" -gt 16 ] && break
		done
		[ "$dohn" -gt 1 ] && doh=multi
		[ "$dohn" -ge 1 ] && [ -z "$doh" ] && doh=other
	fi
	{ _st_installed || _fk_installed; } && _st_cat_bg
	[ -n "$(_st_wfix_min)" ] && _st_wfix_cron
	sel=" $(_st_sel_raw | tr '\n' ' ') "
	local cust=0
	{ [ -s "$ST_CUSTOM.lst" ] || [ -s "$ST_CUSTOM.pfx" ]; } && cust=1
	svc="$(_rb_svc_src | awk -F'|' -v sel="$sel" -v skipf="$ST_SKIP" -v dcf="$ST_DOMCNT" -v idxf="$ST_CAT_IDX" -v cust="$cust" '
		function j(v,    o, i, c) { o = ""; for (i = 1; i <= length(v); i++) { c = substr(v, i, 1); if (c == "\\") o = o "\\\\"; else if (c == "\"") o = o "\\\""; else if (c == "\t" || c == "\r" || c == "\n") o = o " "; else o = o c } return o }
		function hasdom(    m, i, s) {
			if ($1 == "custom") return cust + 0
			if ($1 in dc) return dc[$1] > 0
			if ($3 != "" || $5 != "" || $6 != "") return 1
			m = split($8, s, ",")
			for (i = 1; i <= m; i++) if (s[i] != "" && (!(s[i] in ik) || ik[s[i]] != "s")) return 1
			return 0
		}
		BEGIN {
			while ((getline l < skipf) > 0) sk[l] = 1
			while ((getline l < dcf) > 0) { split(l, a, " "); if (a[1] != "") dc[a[1]] = a[2] + 0 }
			while ((getline l < idxf) > 0) { split(l, a, "|"); if (a[1] != "") ik[a[1]] = a[4] }
		}
		$1 == "" || ($1 in seen) { next }
		{ seen[$1] = 1 }
		$1 != "custom" && $3 $4 $8 == "" { next }
		{
			printf "%s{\"id\":\"%s\",\"name\":\"%s\",\"group\":\"%s\",\"on\":%s,\"skip\":%s,\"dom\":%s}", (n++ ? "," : ""), $1, j($2), j($9),
				(index(sel, " " $1 " ") ? "true" : "false"), (($1 in sk) ? "true" : "false"), (hasdom() ? "true" : "false")
		}')"
	local vexit vup=false vsub=false latest="" ext=false won=false failed=false active="" wfail=false
	vexit="$(_st_exit)"
	_st_warp_on && won=true
	stl_v2 && { [ ! -s "$ST_SUB" ] || _st_feats_ok $(_st_sub_feats); } && ext=true
	if [ -s "$STL_CACHE" ]; then latest="$(cat "$STL_CACHE")"
	elif stl_present; then ( stl_latest >/dev/null 2>&1 & ); fi
	if [ "$run" = true ] && _st_owns "steer-spec" && stl_state "$vexit"; then
		failed="$STL_FAILED"
		[ "$vexit" = vpn ] || [ "$vexit" = iface ] || [ "$failed" = true ] || active="$STL_DEV"
	fi
	if [ "$run" = true ] && [ "$won" = true ] && _st_owns "steer-spec"; then
		if [ "$vexit" = warp ]; then wfail="$failed"; elif stl_state warp; then wfail="$STL_FAILED"; fi
	fi
	_st_vpn_dev >/dev/null && vup=true
	[ -s "$ST_SUB" ] && vsub=true
	local vlive=null mtun=null
	if [ "$(cat "$ST_DIR/exit" 2>/dev/null)" = iface ] && [ -n "$(_st_main_iface)" ]; then
		mtun="$(_zm_tun_json "$(_st_main_iface)" "$([ "$vexit" = iface ] && [ "$failed" = true ] && echo true || echo false)")"
	fi
	if [ "$vup" = true ] && [ "$vexit" = vpn ] && [ "$off" = false ]; then
		_st_vpn_live; case $? in 0) vlive=true ;; 1) vlive=false ;; esac
	fi
	printf '{"running":%s,"phase":"%s","blocker":"%s","installed":%s,"stopped":%s,"version":"%s","steer_running":%s,"channels":%s,"warp_up":%s,"warp_colo":"%s","warp_host":"%s","warp_port":"%s","warp_hs_age":"%s","warp_rx":%s,"warp_tx":%s,"autorestart":"%s","dns_conflict":%s,"doh":"%s","doh_mode":"%s","exit":"%s","vpn_up":%s,"vpn_live":%s,"has_sub":%s,"sub_label":"%s","latest":"%s","ext":%s,"warp_on":%s,"warp_mode":"%s","warp_iface":"%s","warp_pick":"%s","onfail":"%s","warp_own_saved":%s,"tunnels":%s,"warp_active":"%s","catalog":%s,"wfix":%s,"lists_via":%s,"sub_via":%s,"failopen":%s,"warp_failed":%s,"hosts_extra":%s,"dnsmode":"%s","realip":"%s","cttl":%s,"devices":[%s],"services":[%s],"main_name":"%s","main_off":%s,"exit_want":"%s","main_tun":%s,"sec_max":%s,"sec_vpn_max":%s,"sections":[%s],"awg_by_steer":%s,"awg_other":%s}\n' \
		"$running" "$(esc "$phase")" "$(esc "$blk")" "$installed" "$off" "$(esc "$ver")" "$run" "${chans:-0}" "$warp_up" "$(esc "$colo")" \
		"$(esc "$host")" "$(esc "$port")" "$age" "${rx:-0}" "${tx:-0}" "$(_st_cron_get)" "$dns" "$doh" "$(_doh_force_mode)" \
		"$vexit" "$vup" "$vlive" "$vsub" "$(esc "$(_st_sub_label)")" "$(esc "$latest")" "$ext" "$won" "$(_st_warp_modename)" "$(esc "$(_st_ext_if)")" "$(_st_warp_pick)" "$(_st_onfail)" "$(_st_own_saved && echo true || echo false)" "$(_st_tunnels_json)" "$active" "$(_st_cat_json)" "$(_st_wfix_json)" "$([ -f "$ST_DIR/lists.via" ] && echo true || echo false)" "$([ -f "$ST_SUB_VIA" ] && echo true || echo false)" "$failed" "$wfail" "$(_hosts_extra)" "$(_st_dnsmode)" "$(_st_realip)" "$(_st_cttl)" "$(_st_devs_json)" "$svc" "$(esc "$(_st_sec_name main)")" "$(_st_sec_off main && echo true || echo false)" "$(esc "$(cat "$ST_DIR/exit" 2>/dev/null)")" "$mtun" "$ST_SEC_MAX" "$ST_SEC_VPN_MAX" "$(_st_secs_json)" \
		"$(_st_owns "pkg kmod-amneziawg" || _st_owns "pkg amneziawg-tools" && echo true || echo false)" \
		"$(uci -q -X show network 2>/dev/null | sed -n "s/^network\.\([^.=]*\)\.proto='amneziawg'\$/\1/p" | grep -cvE '^zmwarp[0-9]*$')"
}

_st_active_if() {
	[ "$(_st_exit)" = vpn ] && return 0
	_st_owns "steer-spec" && stl_running && stl_state warp || return 0
	[ "$STL_FAILED" = true ] || printf '%s' "$STL_DEV"
}

_st_tunnels_json() {
	local n=1 i up hs age rx tx host port colo out="" sep="" seen city cc pos isru pp
	while [ "$n" -le "$ST_WARP_N" ]; do
		i="$(_st_wif "$n")"
		if _st_wnet "$i"; then
			up=false; age=""; rx=0; tx=0
			[ -d "/sys/class/net/$i" ] && up=true
			pp="$(_st_wpeer "$i")"
			host="$(uci -q get "network.$pp.endpoint_host")"
			port="$(uci -q get "network.$pp.endpoint_port")"
			colo="$(awk -v i="$i" '$1 == i {print $2; exit}' "$ST_WARP_UP" 2>/dev/null)"
			if [ "$up" = true ] && command -v awg >/dev/null 2>&1; then
				hs=$(awg show "$i" latest-handshakes 2>/dev/null | awk '{print $2; exit}')
				[ "${hs:-0}" -gt 0 ] 2>/dev/null && age=$(( $(date +%s) - hs ))
				set -- $(awg show "$i" transfer 2>/dev/null | head -n1)
				rx="${2:-0}"; tx="${3:-0}"
			fi
			seen=""; city=""; cc=""
			set -- $(_st_geo_get "$i")
			if [ $# -ge 4 ] && { [ "$1" = "$colo" ] || [ -z "$colo" ] || [ "$colo" = "?" ]; }; then
				[ -n "$colo" ] && [ "$colo" != "?" ] || colo="$1"
				seen="$2"; cc="$3"; shift 3; city="$*"
				[ "$seen" = - ] && seen=""; [ "$cc" = - ] && cc=""; [ "$city" = - ] && city=""
			fi
			pos="$(awk -v i="$i" '$1 == i { print NR; exit }' "$ST_WARP_UP" 2>/dev/null)"
			isru=false; [ -n "$colo" ] && _st_if_ru "$i" "$colo" && isru=true
			out="$out$sep{\"n\":$n,\"if\":\"$i\",\"pos\":${pos:-0},\"ru\":$isru,\"up\":$up,\"colo\":\"$(esc "$colo")\",\"city\":\"$(esc "$city")\",\"cc\":\"$(esc "$cc")\",\"seen\":\"$(esc "$seen")\",\"host\":\"$(esc "$host")\",\"port\":\"$(esc "$port")\",\"hs_age\":\"$age\",\"rx\":$rx,\"tx\":$tx}"
			sep=","
		fi
		n=$((n + 1))
	done
	printf '[%s]' "$out"
}

ST_USER_DIR="$ST_DIR/user"
ST_CUSTOM="$ST_USER_DIR/custom"
_st_ufile() { if [ "$1" = custom ]; then printf '%s' "$ST_CUSTOM"; else printf '%s' "$ST_USER_DIR/$1"; fi; }
_st_cust_split() {
	local s m="$ST_DIR/custom.split"
	[ -f "$m" ] && return 0
	[ -d "$ST_DIR" ] || return 0
	for s in $(_st_secs); do
		_rb_in custom "$ST_SEC_DIR/$s/services" || continue
		[ -s "$ST_SEC_DIR/$s/custom.lst" ] || [ -s "$ST_SEC_DIR/$s/custom.pfx" ] && continue
		[ -s "$ST_USER_DIR/custom.lst" ] && cp -f "$ST_USER_DIR/custom.lst" "$ST_SEC_DIR/$s/custom.lst"
		[ -s "$ST_USER_DIR/custom.pfx" ] && cp -f "$ST_USER_DIR/custom.pfx" "$ST_SEC_DIR/$s/custom.pfx"
	done
	: > "$m"
}

_st_list_effective() {
	local id="$1" set f any=0
	if [ "$id" = exclude ]; then ST_LIST_SRC=user; cat "$ST_USER_DIR/$id.lst" "$ST_USER_DIR/$id.pfx" 2>/dev/null; return 0; fi
	f="$(_st_ufile "$id")"
	if [ -s "$f.lst" ] || [ -s "$f.pfx" ]; then ST_LIST_SRC=user; cat "$f.lst" "$f.pfx" 2>/dev/null; return 0; fi
	for set in $(_rb_svc_field "$id" 8 | tr ',' ' '); do
		f="$ST_DIR/lists/$set.dom"
		[ -s "$f" ] && { cat "$f"; any=1; }
	done
	if [ "$any" = 1 ]; then ST_LIST_SRC=sets; return 0; fi
	ST_LIST_SRC=package
	for f in $(_rb_svc_field "$id" 3 | tr ',' ' '); do _rb_list_get "$f" 2>/dev/null && [ -s "$ZM_LISTS_DIR/$f" ] && cat "$ZM_LISTS_DIR/$f"; done
}

_st_user_list() { [ "$1" = exclude ] || { [ "$1" = custom ] && _rb_routable "$1"; }; }

ST_DOMCNT="$ST_DIR/domcount"
_st_dom_norm() {
	awk '{
		l = tolower($0); sub(/[#;].*$/, "", l); gsub(/^[ \t\r]+|[ \t\r]+$/, "", l); sub(/[ \t].*$/, "", l)
		sub(/^(domain|full|suffix|domain_suffix):/, "", l); sub(/^=/, "", l); sub(/^\*\./, "", l); sub(/^\./, "", l)
		if (l ~ /^[a-z0-9]([a-z0-9_-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9_-]*[a-z0-9])?)+$/ && l !~ /^[0-9.]+$/) print l
	}'
}
_st_srs_dump() {
	local j="$2.json.$$"
	if command -v steer >/dev/null 2>&1; then
		steer srs-read "$1" --out "$2" --prefixes-out "$3" >/dev/null 2>&1 && return 0
	fi
	command -v sing-box >/dev/null 2>&1 && command -v jsonfilter >/dev/null 2>&1 || return 1
	GOMEMLIMIT="$(_zm_gml)" sing-box rule-set decompile -o "$j" "$1" >/dev/null 2>&1 && [ -s "$j" ] || { rm -f "$j"; return 1; }
	jsonfilter -i "$j" -e '@.rules[*].domain[*]' -e '@.rules[*].domain_suffix[*]' -e '@.rules[*].rules[*].domain[*]' -e '@.rules[*].rules[*].domain_suffix[*]' 2>/dev/null > "$2"
	jsonfilter -i "$j" -e '@.rules[*].ip_cidr[*]' -e '@.rules[*].rules[*].ip_cidr[*]' 2>/dev/null > "$3"
	rm -f "$j"
	return 0
}

_st_dom_build() {
	local id="$1" out="$2" src="$2.src.$$" pfx="$2.pfx.$$" dl=1 sets set f fmt x ok=1
	ST_DOM_SRC=""; ST_DOM_MISS=""
	{ _st_running || [ -n "$ST_DOM_NODL" ]; } && dl=0
	mkdir -p "${out%/*}" "$ST_DIR/lists" "$ST_RUN/srsdump"
	: > "$src"; : > "$pfx"
	if [ "$id" = custom ]; then
		[ -s "$ST_CUSTOM.lst" ] && echo "$ST_CUSTOM.lst" >> "$src"
		[ -s "$ST_CUSTOM.pfx" ] && echo "$ST_CUSTOM.pfx" >> "$pfx"
		ST_DOM_SRC="ваши строки"
	else
		sets="$(_rb_svc_field "$id" 8 | tr ',' ' ')"
		for set in $sets; do
			fmt="$(awk -F'|' -v k="$set" '$1 == k { print $2; exit }' "$ST_CAT_IDX" 2>/dev/null)"
			if [ "$fmt" = lst ]; then
				f="$ST_DIR/lists/$set.dom"
				[ -s "$f" ] || [ -s "$ST_DIR/lists/$set.pfx" ] || { [ "$dl" = 1 ] && _st_srs_get "$set" >/dev/null 2>&1; }
				[ -s "$ST_DIR/lists/$set.pfx" ] && echo "$ST_DIR/lists/$set.pfx" >> "$pfx"
				if [ -s "$f" ]; then echo "$f" >> "$src"
				elif [ ! -s "$ST_DIR/lists/$set.pfx" ]; then ST_DOM_MISS="$ST_DOM_MISS $set"; ok=0; break; fi
			else
				f="$ST_DIR/lists/$set.srs"
				[ -s "$f" ] || { [ "$dl" = 1 ] && _st_srs_get "$set" >/dev/null 2>&1; }
				[ -s "$f" ] || ST_DOM_MISS="$ST_DOM_MISS $set"
				[ -s "$f" ] || { ok=0; break; }
				x="$ST_RUN/srsdump/$(printf '%s' "$f" | tr -c 'A-Za-z0-9_.-' '_')"
				if { [ ! -s "$x.dom" ] && [ ! -s "$x.pfx" ]; } || [ "$f" -nt "$x.dom" ]; then
					rm -f "$x.dom" "$x.pfx"
					_st_srs_dump "$f" "$x.dom" "$x.pfx" || rm -f "$x.dom" "$x.pfx"
				fi
				[ -f "$x.dom" ] || { ok=0; break; }
				[ -s "$x.dom" ] && echo "$x.dom" >> "$src"
				[ -s "$x.pfx" ] && echo "$x.pfx" >> "$pfx"
			fi
		done
		if [ -n "$sets" ] && [ "$ok" = 1 ]; then ST_DOM_SRC="каталог списков"
		else
			: > "$src"; : > "$pfx"
			for f in $(_rb_svc_field "$id" 4 | tr ',' ' '); do
				if [ "$dl" = 1 ]; then _rb_list_get "$f" >/dev/null 2>&1; fi
				[ -s "$ZM_LISTS_DIR/$f" ] && echo "$ZM_LISTS_DIR/$f" >> "$pfx"
			done
			for f in $(_rb_svc_field "$id" 3 | tr ',' ' '); do
				if [ "$dl" = 1 ]; then _rb_list_get "$f" >/dev/null 2>&1; fi
				[ -s "$ZM_LISTS_DIR/$f" ] && echo "$ZM_LISTS_DIR/$f" >> "$src"
			done
			if [ -s "$src" ]; then ST_DOM_SRC="списки сервиса"
			else
				printf '%s,%s\n' "$(_rb_svc_field "$id" 5)" "$(_rb_svc_field "$id" 6)" | tr ',' '\n' > "$out.base.$$"
				[ -s "$out.base.$$" ] && echo "$out.base.$$" >> "$src"
				ST_DOM_SRC="основные домены сервиса"
			fi
		fi
	fi
	while IFS= read -r f; do cat "$f"; echo; done < "$src" | _st_dom_norm | sort -u > "$out.$$"
	mv -f "$out.$$" "$out"
	mv -f "$pfx" "$out.pfxsrc"
	rm -f "$src" "$out.base.$$"
	printf '%s\n' "$ST_DOM_MISS" > "$out.miss"
	printf '%s\n' "$ST_DOM_SRC" > "$out.how"
	if [ -s "$out.pfxsrc" ]; then
		awk '{ l = tolower($0); sub(/[#;].*$/, "", l); gsub(/[ \t\r]/, "", l)
			if (l ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+((\/[0-9]+)|(-[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+))?$/ || (l ~ /^[0-9a-f:]+(\/[0-9]+)?$/ && index(l, ":"))) if (!s[l]++) print l }' \
			$(cat "$out.pfxsrc") 2>/dev/null > "$out.ips"
	else
		: > "$out.ips"
	fi
	wc -l < "$out.ips" | tr -d ' ' > "$out.ipn"
}

steer_svc_domflags() {
	_rb_svc_src | awk -F'|' -v dcf="$ST_DOMCNT" -v idxf="$ST_CAT_IDX" '
		BEGIN {
			while ((getline l < dcf) > 0) { split(l, a, " "); if (a[1] != "") dc[a[1]] = a[2] + 0 }
			while ((getline l < idxf) > 0) { split(l, a, "|"); if (a[1] != "") ik[a[1]] = a[4] }
			printf "{"
		}
		$1 == "" || $1 == "custom" || ($1 in seen) || $3 $4 $8 == "" || $1 !~ /^[A-Za-z0-9_.-]+$/ { next }
		{
			seen[$1] = 1; d = 0
			if ($1 in dc) d = dc[$1] > 0
			else if ($3 != "" || $5 != "" || $6 != "") d = 1
			else { m = split($8, s, ","); for (i = 1; i <= m; i++) if (s[i] != "" && (!(s[i] in ik) || ik[s[i]] != "s")) d = 1 }
			printf "%s\"%s\":%s", (n++ ? "," : ""), $1, (d ? "true" : "false")
		}
		END { printf "}\n" }'
}

steer_svc_dom() {
	local id="${1%%:*}" r o l f n ipn k="" src
	r="${1#*:}"; o="${r%%:*}"; l="${r#*:}"
	case "$l" in *:*) k="${l#*:}"; l="${l%%:*}" ;; esac
	case "$id" in ''|*[!A-Za-z0-9_.-]*) echo '{"error":"нет такого сервиса"}'; return 1 ;; esac
	case "$o" in ''|*[!0-9]*) o=0 ;; esac
	case "$l" in ''|*[!0-9]*) l=500 ;; esac
	[ "$l" -gt 5000 ] && l=5000
	[ "$l" -lt 1 ] && l=1
	_rb_routable "$id" || { echo '{"error":"у этого пункта нет списка"}'; return 1; }
	f="$ST_RUN/dom/$id.txt"
	[ "$id" = custom ] && [ -n "$ST_SEC" ] && f="$ST_RUN/dom/custom.$ST_SEC.txt"
	if [ ! -f "$f" ] || [ ! -f "$f.how" ] || [ ! -f "$f.ipn" ] || [ ! -f "$f.ips" ] || [ -n "$(find "$f" -mmin +1 2>/dev/null)" ] || { [ "$o" = 0 ] && [ "$id" = custom ] && [ "$k" != ip ]; }; then
		_st_dom_build "$id" "$f"
	fi
	n="$(wc -l < "$f" | tr -d ' ')"
	if [ "$id" != custom ]; then
		mkdir -p "$ST_DIR"
		{ grep -v "^$id " "$ST_DOMCNT" 2>/dev/null; echo "$id $n"; } > "$ST_DOMCNT.$$" && mv -f "$ST_DOMCNT.$$" "$ST_DOMCNT"
	fi
	ipn="$(cat "$f.ipn" 2>/dev/null)"; case "$ipn" in ''|*[!0-9]*) ipn=0 ;; esac
	src="$f"; [ "$k" = ip ] && src="$f.ips"
	printf '{"id":"%s","name":"%s","kind":"%s","count":%s,"ips":%s,"offset":%s,"src":"%s","domains":"%s"}\n' "$id" "$(esc "$(_rb_svc_field "$id" 2)")" "${k:-dom}" "${n:-0}" "$ipn" "$o" \
		"$(esc "$(cat "$f.how" 2>/dev/null)")" "$(sed -n "$((o + 1)),$((o + l))p" "$src" 2>/dev/null | tr '\n' ' ')"
}

_st_find_ip() {
	local a s
	for s in 127.0.0.1 77.88.8.8 1.1.1.1; do
		a="$(_stl_t 4 nslookup "$1" "$s" 2>/dev/null | awk '/^Name:/ { f = 1; next } f && /^Address/ { a = $0; sub(/^Address[ 0-9]*:[ \t]*/, "", a); if (a ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/) { print a; exit } }')"
		case "$a" in ''|198.18.*|198.19.*|0.*|127.*) continue ;; esac
		printf '%s' "$a"
		return 0
	done
	return 1
}

_st_ip_in() {
	local ip="$1"; shift
	[ $# -gt 0 ] || return 0
	awk -v ip="$ip" '
		function ipn(a,  p) { if (split(a, p, ".") != 4) return -1; return ((p[1] * 256 + p[2]) * 256 + p[3]) * 256 + p[4] }
		BEGIN { iv = ipn(ip); bw = -1 }
		{
			l = $0; sub(/[#;].*$/, "", l); gsub(/[ \t\r]/, "", l)
			if (l ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+(\/[0-9]+)?$/) {
				split(l, c, "/"); b = (c[2] == "") ? 32 : c[2] + 0; if (b < 0 || b > 32) next
				z = 2 ^ (32 - b); a = ipn(c[1])
				if (a >= 0 && int(iv / z) == int(a / z) && b > bw) { best = l; bw = b }
			} else if (l ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+-[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/) {
				split(l, c, "-"); if (iv >= ipn(c[1]) && iv <= ipn(c[2]) && bw < 0) { best = l; bw = 0 }
			}
		}
		END { if (bw >= 0) print best }' "$@" 2>/dev/null
}

steer_svc_find() {
	local q host="" ip="" d="$ST_RUN/dom" suf="$ST_RUN/find.$$.s" res="$ST_RUN/find.$$.r" sel miss nmiss=0 sep=""
	local id name f3 f4 f5 f6 f7 f8 rest f by line n grp on
	q="$(_zm_route_target "$1")" || { echo '{"error":"введите сайт или IP, например fast.com или 1.2.3.4"}'; return 1; }
	if printf '%s' "$q" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$'; then
		printf '%s' "$q" | awk -F. '$1 < 256 && $2 < 256 && $3 < 256 && $4 < 256 { ok = 1 } END { exit !ok }' || { echo '{"error":"такого IP-адреса не бывает — в каждой части число от 0 до 255"}'; return 1; }
		ip="$q"
	elif printf '%s' "$q" | grep -q ':'; then echo '{"error":"IPv6 пока не ищется — введите IPv4-адрес или сайт"}'; return 1
	else host="$q"; ip="$(_st_find_ip "$host")"; fi
	mkdir -p "$d"
	sel=" $(_st_sel_raw | tr '\n' ' ') "
	: > "$res"; : > "$suf"
	[ -n "$host" ] && printf '%s\n' "$host" | awk '{ s = $0; while (1) { print s; i = index(s, "."); if (!i) break; s = substr(s, i + 1) } }' > "$suf"
	_rb_svc_src | awk -F'|' '$1 != "" && !s[$1]++ && ($1 == "custom" || $3 $4 $8 != "")' > "$res.svc"
	while IFS='|' read -r id name f3 f4 f5 f6 f7 f8 rest; do
		case "$id" in *[!A-Za-z0-9_.-]*) continue ;; esac
		f="$d/$id.txt"
		[ "$id" = custom ] && [ -n "$ST_SEC" ] && f="$d/custom.$ST_SEC.txt"
		if [ "$id" = custom ] || [ ! -f "$f" ] || [ ! -f "$f.pfxsrc" ] || [ -s "$f.miss" ] || [ -n "$(find "$f" -mmin +9 2>/dev/null)" ]; then
			ST_DOM_NODL=1
			_st_dom_build "$id" "$f" </dev/null 2>/dev/null
			ST_DOM_NODL=""
		fi
		by=""; line=""
		if [ -s "$suf" ] && [ -s "$f" ]; then
			line="$(grep -xF -f "$suf" "$f" 2>/dev/null | awk '{ print length($0) "\t" $0 }' | sort -rn | head -n1 | cut -f2)"
			[ -n "$line" ] && by=dom
		fi
		if [ -z "$by" ] && [ -n "$ip" ] && [ -s "$f.pfxsrc" ]; then
			line="$(_st_ip_in "$ip" $(cat "$f.pfxsrc"))"
			[ -n "$line" ] && by=ip
		fi
		[ -n "$by" ] || continue
		n="$(cat "$f" $(cat "$f.pfxsrc" 2>/dev/null) 2>/dev/null | wc -l | tr -d ' ')"
		grp="${rest%%|*}"
		on=false; case "$sel" in *" $id "*) on=true ;; esac
		printf '%s|%s|%s|%s|%s|%s|%s\n' "$id" "$name" "$grp" "$on" "$by" "$line" "${n:-0}" >> "$res"
	done < "$res.svc"
	miss="$(cat "$d"/*.txt.miss 2>/dev/null | tr ' ' '\n' | grep . | sort -u)"
	if [ -n "$miss" ]; then
		nmiss="$(printf '%s\n' "$miss" | grep -c .)"
		[ -d "$ST_RUN/find.lock" ] && [ -n "$(find "$ST_RUN/find.lock" -maxdepth 0 -mmin +10 2>/dev/null)" ] && rmdir "$ST_RUN/find.lock" 2>/dev/null
		if ! _st_running && mkdir "$ST_RUN/find.lock" 2>/dev/null; then
			( for f in $miss; do _st_srs_get "$f"; done; rmdir "$ST_RUN/find.lock" ) >/dev/null 2>&1 </dev/null &
		fi
	fi
	printf '{"q":"%s","host":"%s","ip":"%s","missing":%s,"hits":[' "$(esc "$q")" "$(esc "$host")" "$(esc "$ip")" "${nmiss:-0}"
	while IFS='|' read -r id name grp on by line n; do
		printf '%s{"id":"%s","name":"%s","group":"%s","on":%s,"by":"%s","line":"%s","size":%s}' "$sep" "$id" "$(esc "$name")" "$(esc "$grp")" "$on" "$by" "$(esc "$line")" "${n:-0}"
		sep=","
	done < "$res"
	printf ']}\n'
	rm -f "$res" "$res.svc" "$suf"
}

steer_list_get() {
	local id="$1" body n tmp="$JOBS_DIR/steer-list.$$"
	_st_user_list "$id" || { echo '{"error":"редактируется только свой список или исключения"}'; return 1; }
	ST_LIST_SRC=""
	mkdir -p "$JOBS_DIR"
	_st_list_effective "$id" > "$tmp"
	body="$(tr -d '\r' < "$tmp" | grep -v '^[[:space:]]*$' | awk '!s[$0]++')"
	rm -f "$tmp"
	n=$(printf '%s\n' "$body" | grep -c .)
	printf '{"id":"%s","name":"%s","source":"%s","count":%s,"domains":%s,"subnets":%s,"content":"%s"}\n' "$id" "$(esc "$(_rb_svc_field "$id" 2)")" "$ST_LIST_SRC" "$n" \
		"$(cat "$(_st_ufile "$id").lst" 2>/dev/null | grep -c .)" "$(cat "$(_st_ufile "$id").pfx" 2>/dev/null | grep -c .)" "$(esc_ml "$body")"
}

steer_list_set() {
	local id="${1%%|*}" body="${1#*|}" f tmp n on=""
	case "$1" in *'|'*) ;; *) echo '{"error":"нет списка"}'; return 1 ;; esac
	case "$id" in custom+on) id=custom; on=1 ;; esac
	_st_user_list "$id" || { echo '{"error":"редактируется только свой список или исключения"}'; return 1; }
	f="$(_st_ufile "$id")"; mkdir -p "${f%/*}"
	f="$f.lst"; tmp="$f.tmp"
	printf '%s\n' "$body" | tr -d '\r' | tr 'A-Z' 'a-z' | tr ',;' '\n\n' |
		sed 's/[[:space:]]*#.*$//; s/^[[:space:]]*//; s/[[:space:]]*$//; s#^[a-z][a-z0-9+.-]*://\([^/?]*\).*#\1#; s/^domain://; s/^full://; s/^suffix://; s/^\*\.//; s/^\.//' > "$tmp.all"
	grep -E '^[a-z0-9]([a-z0-9_-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9_-]*[a-z0-9])?)+$' "$tmp.all" | grep -vE '^[0-9.]+$' | awk '!s[$0]++' > "$tmp"
	grep -E '^[0-9]{1,3}(\.[0-9]{1,3}){3}(/[0-9]{1,2})?$' "$tmp.all" | awk -F'[./]' '$1 < 256 && $2 < 256 && $3 < 256 && $4 < 256 && ($5 == "" || $5 <= 32) { print ($5 == "" ? $0 "/32" : $0) }' | awk '!s[$0]++' > "$tmp.pfx"
	rm -f "$tmp.all"
	n=$(( $(grep -c . "$tmp") + $(grep -c . "$tmp.pfx") ))
	[ "$n" -gt 0 ] || { rm -f "$tmp" "$tmp.pfx"; echo '{"error":"в списке нет ни одного домена или IP-адреса"}'; return 1; }
	if [ -s "$tmp" ]; then mv "$tmp" "$f"; else rm -f "$tmp" "$f"; fi
	if [ -s "$tmp.pfx" ]; then mv "$tmp.pfx" "${f%.lst}.pfx"; else rm -f "$tmp.pfx" "${f%.lst}.pfx"; fi
	if [ -n "$on" ] && ! _rb_in custom "$ST_SEL"; then
		mkdir -p "$(dirname "$ST_SEL")"
		echo custom >> "$ST_SEL"
		[ -f "$ST_SKIP" ] && sed -i '/^custom$/d' "$ST_SKIP"
	fi
	_st_list_changed "$id" "$n"
}

steer_list_reset() {
	local s
	_st_user_list "$1" || { echo '{"error":"редактируется только свой список или исключения"}'; return 1; }
	rm -f "$(_st_ufile "$1").lst" "$(_st_ufile "$1").pfx"
	if [ "$1" = custom ]; then
		if _rb_in custom "$ST_SEL"; then
			sed -i '/^custom$/d' "$ST_SEL" 2>/dev/null
			if _st_installed && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ]; then
				job_start steer do_steer_apply
				return
			fi
		fi
		printf '{"ok":true,"saved":true,"count":0}\n'
		return
	fi
	_st_list_changed "$1" 0
}

_st_list_changed() {
	if [ "$1" = exclude ]; then
		if _st_installed && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] && _st_owns "steer-spec" && _st_work; then
			job_start steer do_steer_excl
		else
			printf '{"ok":true,"saved":true,"count":%s}\n' "$2"
		fi
		return
	fi
	if _st_installed && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] && _rb_in custom "$ST_SEL"; then
		job_start steer do_steer_apply
	else
		printf '{"ok":true,"saved":true,"count":%s}\n' "$2"
	fi
}

_st_sel_set() {
	local want id
	want=" $(echo "$1" | tr ',' ' ') "
	for id in $want; do
		case "$id" in *[!a-z0-9_-]*) echo '{"error":"неизвестный сервис"}'; return 1 ;; esac
		[ -n "$(_rb_svc_field "$id" 1)" ] && _rb_routable "$id" || { echo '{"error":"неизвестный сервис"}'; return 1; }
		[ "$id" = custom ] && [ ! -s "$ST_CUSTOM.lst" ] && [ ! -s "$ST_CUSTOM.pfx" ] && { echo '{"error":"свой список пуст — сначала добавьте в него домены или IP"}'; return 1; }
	done
	mkdir -p "$ST_DIR"
	touch "$ST_SKIP"
	for id in $(_st_sel_raw); do case "$want" in *" $id "*) ;; *) _rb_in "$id" "$ST_SKIP" || echo "$id" >> "$ST_SKIP" ;; esac; done
	for id in $want; do sed -i "/^$id\$/d" "$ST_SKIP"; done
	printf '%s\n' $want | grep . > "$ST_SEL"
	[ -s "$ST_SKIP" ] || rm -f "$ST_SKIP"
	return 0
}

ST_VPN_ZONE="zmvpn"
ST_VDIR="$ST_DIR"
ST_SUB="$ST_DIR/sub.txt"
ST_SUB_INFO="$ST_DIR/sub.userinfo"
ST_SUB_URL="$ST_DIR/sub.url"
ST_SUB_TITLE="$ST_DIR/sub.title"
ST_SUB_NODE="$ST_DIR/sub.node"
ST_SUB_EXCL="$ST_DIR/sub.exclude"
ST_SUB_HIDE="$ST_DIR/sub.hidden"
ST_EXIT="$ST_DIR/exit"

_st_exit() {
	local e
	if [ -n "$ST_SEC" ]; then
		case "$(_st_sec_kind "$ST_SEC")" in
			vpn) if [ -s "$ST_SUB" ] && _st_vpn_ok; then echo vpn; else echo none; fi ;;
			iface) if _st_sec_live "$ST_SEC"; then echo iface; else echo none; fi ;;
			*) if _st_warp_on; then echo warp; else echo none; fi ;;
		esac
		return
	fi
	e="$(cat "$ST_EXIT" 2>/dev/null)"
	if [ "$e" = iface ] && _st_tun_live "$(_st_main_iface)"; then echo iface; return; fi
	if [ "$e" = vpn ] && [ -s "$ST_SUB" ] && _st_vpn_ok; then echo vpn; return; fi
	if _st_warp_on; then echo warp; return; fi
	if [ -s "$ST_SUB" ] && _st_vpn_ok; then echo vpn; return; fi
	echo none
}
_st_use_vpn() { [ "$(_st_exit)" = vpn ]; }

ST_VPN_PROBE="$JOBS_DIR/steer.vpnprobe"
_st_vpn_probe() {
	local trace ip="" loc="" r=fail dev
	if dev="$(_st_vpn_dev)"; then
		trace="$(_st_vpn_trace "$dev")"
		ip="$(echo "$trace" | sed -n 's/^ip=//p')"; loc="$(echo "$trace" | sed -n 's/^loc=//p')"
		[ -n "$ip" ] && r=ok
	fi
	mkdir -p "$ZM_STATE_DIR"
	echo "$(date +%s) $r $ip $loc" > "$ST_VPN_PROBE"
	[ "$r" = ok ]
}
_st_vpn_live() {
	local t r age
	read -r t r _ 2>/dev/null < "$ST_VPN_PROBE"
	age=$(( $(date +%s) - ${t:-0} ))
	if [ "$age" -gt 120 ] || [ "$age" -lt 0 ]; then
		if mkdir "$ST_VPN_PROBE.lock" 2>/dev/null; then
			( _st_vpn_probe >/dev/null 2>&1; rmdir "$ST_VPN_PROBE.lock" ) >/dev/null 2>&1 &
		elif [ -n "$(find "$ST_VPN_PROBE.lock" -mmin +1 2>/dev/null)" ]; then
			rmdir "$ST_VPN_PROBE.lock" 2>/dev/null
		fi
	fi
	[ -z "$r" ] && return 2
	[ "$age" -gt 600 ] && return 2
	[ "$r" = ok ]
}

_st_sub_label() {
	[ -s "$ST_SUB" ] || return 0
	if [ -s "$ST_SUB_TITLE" ]; then
		case "$(head -n1 "$ST_SUB_TITLE")" in
			*🌨*VPN*) echo "StressKVN" ;;
			*) head -n1 "$ST_SUB_TITLE" ;;
		esac
	elif [ -s "$ST_SUB_URL" ]; then sed -n 's#^[a-z]*://\([^/:?]*\).*#\1#p' "$ST_SUB_URL" | head -n1
	else echo "свои ссылки"; fi
}

ZM_FOLD_AWK='function fold(x,  k) { x = tolower(x); for (k = 1; k <= nU; k++) gsub(U[k], L[k], x); return x }
BEGIN { nU = split("А Б В Г Д Е Ё Ж З И Й К Л М Н О П Р С Т У Ф Х Ц Ч Ш Щ Ъ Ы Ь Э Ю Я", U, " "); split("а б в г д е ё ж з и й к л м н о п р с т у ф х ц ч ш щ ъ ы ь э ю я", L, " ") }'

_zm_excl_hits() {
	[ -s "$1" ] || [ -s "${2:-/nonexistent}" ] || { cat >/dev/null; return 0; }
	ZM_EXCL="$(head -n1 "$1" 2>/dev/null)" ZM_HIDE="${2:-}" awk -F'\t' "$ZM_FOLD_AWK"'
		BEGIN {
			c = split(ENVIRON["ZM_EXCL"], a, /[|,]/); n = 0
			for (i = 1; i <= c; i++) { t = a[i]; gsub(/^[ \t]+|[ \t]+$/, "", t); if (t != "") m[++n] = fold(t) }
			f = ENVIRON["ZM_HIDE"]
			if (f != "") while ((getline l < f) > 0) if (l != "") h[l] = 1
		}
		{
			if ($2 in h) { print $1; next }
			nm = fold($2); for (i = 1; i <= n; i++) if (index(nm, m[i])) { print $1; break }
		}'
}

_zm_json_lines() {
	local l sep=""
	[ -s "$1" ] || return 0
	while IFS= read -r l || [ -n "$l" ]; do
		[ -n "$l" ] || continue
		printf '%s"%s"' "$sep" "$(esc "$l")"; sep=","
	done < "$1"
}

_zm_names_save() {
	local src="$1" dst="$2"
	awk 'length($0) > 0 && length($0) <= 400 && !s[$0]++' "$src" 2>/dev/null | head -n 300 > "$dst.tmp"
	if [ -s "$dst.tmp" ]; then mv -f "$dst.tmp" "$dst"; else rm -f "$dst.tmp" "$dst"; fi
}

_zm_excl_save() {
	local m="$2" f="$1"
	case "$m" in *"
"*|*"$(printf '\r')"*) echo "маркеры — одной строкой через |"; return 1 ;; esac
	[ "${#m}" -le 1600 ] || { echo "слишком длинный список маркеров"; return 1; }
	mkdir -p "$(dirname "$f")"
	rm -f "$f.v"
	if [ -z "$(printf '%s' "$m" | tr -d ' |,')" ]; then rm -f "$f"; return 0; fi
	printf '%s\n' "$m" > "$f"
}

ST_SUB_NODES="$ST_DIR/sub.nodes"
_st_nodes() {
	local mods
	[ -s "$ST_SUB" ] || return 1
	if [ ! -f "$ST_SUB.map" ]; then
		if stl_sub_norm "$ST_SUB" "$ST_SUB.n"; then mv -f "$ST_SUB.n.map" "$ST_SUB.map"; mv -f "$ST_SUB.n" "$ST_SUB"; chmod 600 "$ST_SUB"; fi
		rm -f "$ST_SUB.n" "$ST_SUB.n.map"
	fi
	mods="$(_stl_mods_present)"
	if [ ! -s "$ST_SUB_NODES" ] || [ "$ST_SUB" -nt "$ST_SUB_NODES" ] || [ "$(sed -n 's/^mods=//p' "$ST_SUB_NODES.meta" 2>/dev/null)" != "$mods" ]; then
		mkdir -p "$ST_DIR"
		stl_sub_nodes "$ST_SUB" "$ST_SUB_NODES.tmp" "$ST_SUB_NODES.meta"
		mv -f "$ST_SUB_NODES.tmp" "$ST_SUB_NODES"
		echo "mods=$mods" >> "$ST_SUB_NODES.meta"
		_st_sub_names_fix
	fi
	echo "$ST_SUB_NODES"
}
_st_key_in() { [ -s "$1" ] && ZM_W="$2" awk -F'\t' '$5 == ENVIRON["ZM_W"] { f = 1 } END { exit !f }' "$1"; }
_st_nodes_kv() { local t; t="$(_st_nodes)" && cut -f1,5 "$t"; }
_st_key_hidden() { [ -n "$1" ] && _st_nodes_kv | ZM_W="$1" awk -F'\t' '$2 == ENVIRON["ZM_W"]' | _zm_excl_hits "$ST_SUB_EXCL" "$ST_SUB_HIDE" | grep -q .; }
_st_order_head() {
	local t hid
	[ "$(_st_pick)" = ping ] && [ -s "$ST_SUB_ORDER" ] && t="$(_st_nodes)" || return 0
	hid=" $(cut -f1,5 "$t" | _zm_excl_hits "$ST_SUB_EXCL" "$ST_SUB_HIDE" | tr '\n' ' ') "
	awk -F'\t' -v h="$hid" -v of="$ST_SUB_ORDER" 'index(h, " " $1 " ") { x[$5] = 1 } END { while ((getline l < of) > 0) if (l != "" && !(l in x)) { print l; exit } }' "$t"
}
_st_hidden_drop() {
	[ -s "$ST_SUB_HOME" ] && _st_key_hidden "$(head -n1 "$ST_SUB_HOME")" && rm -f "$ST_SUB_HOME"
	[ -s "$ST_SUB_FELL" ] && _st_key_hidden "$(head -n1 "$ST_SUB_FELL")" && rm -f "$ST_SUB_FELL"
	return 0
}

_st_sub_names_fix() {
	local t="$ST_SUB_NODES" node w f
	[ -s "$t" ] || return 0
	node="$(cat "$ST_SUB_NODE" 2>/dev/null)"
	if [ -n "$node" ] && ! _st_key_in "$t" "$node"; then
		w="$(printf '%s' "$node" | sed 's/[[:space:]]*$//')"
		f="$(ZM_W="$w" awk -F'\t' 'index($5, ENVIRON["ZM_W"]) == 1 { n++; k = $5 } END { if (n == 1) print k }' "$t")"
		[ -n "$f" ] && printf '%s\n' "$f" > "$ST_SUB_NODE"
	fi
	[ -s "$ST_SUB_HIDE" ] || return 0
	while IFS= read -r w || [ -n "$w" ]; do
		[ -n "$w" ] || continue
		if _st_key_in "$t" "$w"; then printf '%s\n' "$w"
		else ZM_W="$(printf '%s' "$w" | sed 's/[[:space:]]*$//')" awk -F'\t' 'index($5, ENVIRON["ZM_W"]) == 1 { print $5 }' "$t"; fi
	done < "$ST_SUB_HIDE" | awk '!s[$0]++' > "$ST_SUB_HIDE.tmp"
	if [ -s "$ST_SUB_HIDE.tmp" ]; then mv -f "$ST_SUB_HIDE.tmp" "$ST_SUB_HIDE"; else rm -f "$ST_SUB_HIDE.tmp" "$ST_SUB_HIDE"; fi
}

_st_sub_filter() {
	local t want hid all n mk
	mk="$(head -n1 "$ST_SUB_EXCL" 2>/dev/null | tr '\t' ' ')"
	[ -n "$(printf '%s' "$mk" | tr -d ' |,')" ] || mk=-
	t="$(_st_nodes)"; all="$(grep -c . "$t" 2>/dev/null)"
	if [ -z "$t" ] || [ "${all:-0}" -eq 0 ]; then printf 'tun\tvless\t-\t%s\n' "$mk"; return 0; fi
	hid=" $(cut -f1,5 "$t" | _zm_excl_hits "$ST_SUB_EXCL" "$ST_SUB_HIDE" | tr '\n' ' ')"
	if [ "$(echo $hid | wc -w)" -ge "$all" ]; then
		echo "!! Фильтр узлов скрыл все узлы подписки — пока используем все, поправьте маркеры" >&2
		hid=" "; mk=-
	fi
	want="$(cat "$ST_SUB_NODE" 2>/dev/null)"
	if [ -n "$want" ]; then
		n="$(ZM_W="$want" awk -F'\t' '$5 == ENVIRON["ZM_W"] { print $1 " " $2 " " $3; exit }' "$t")"
		if [ -n "$n" ]; then
			set -- $n
			case "$hid" in *" $1 "*) ;; *) printf 'tun\t%s\t%s\t%s\n' "$2" "$3" "$mk"; return 0 ;; esac
		fi
	fi
	if [ "$(_st_pick)" = ping ] && [ -s "$ST_SUB_ORDER" ]; then
		ZM_MK="$mk" awk -F'\t' -v h="$hid " -v of="$ST_SUB_ORDER" '
			BEGIN { mk = ENVIRON["ZM_MK"]; while ((getline l < of) > 0) if (!(l in rk)) rk[l] = ++r }
			index(h, " " $1 " ") { next }
			{ c++; key[c] = ($5 in rk) ? rk[$5] : 100000 + NR; pr[c] = $2; ix[c] = $3; o[c] = c }
			END {
				for (i = 2; i <= c; i++) { x = o[i]; j = i - 1; while (j > 0 && key[o[j]] > key[x]) { o[j + 1] = o[j]; j-- } o[j + 1] = x }
				for (i = 1; i <= c; i++) { p = pr[o[i]]; if (!(p in L)) ord[++np] = p; L[p] = L[p] (L[p] == "" ? "" : ",") ix[o[i]] }
				for (i = 1; i <= np; i++) printf "tun\t%s\t%s\t%s\n", ord[i], L[ord[i]], mk
			}' "$t"
		return 0
	fi
	ZM_MK="$mk" awk -F'\t' -v h="$hid " '
		BEGIN { mk = ENVIRON["ZM_MK"] }
		{ if (!($2 in tot)) ord[++np] = $2; tot[$2]++
		  if (!index(h, " " $1 " ")) { ok[$2] = ok[$2] (ok[$2] == "" ? "" : ",") $3; cnt[$2]++ } }
		END { for (i = 1; i <= np; i++) { p = ord[i]; if (cnt[p]) printf "tun\t%s\t%s\t%s\n", p, (cnt[p] == tot[p] ? "-" : ok[p]), mk } }' "$t"
}

_st_active_key() {
	local t
	t="$(_st_nodes)" || return 0
	ZM_P="$STL_PROTO" ZM_I="$STL_PIDX" ZM_N="$STL_NODE" awk -F'\t' '$2 == ENVIRON["ZM_P"] &&
		((ENVIRON["ZM_I"] != "" && $3 == ENVIRON["ZM_I"]) || (ENVIRON["ZM_I"] == "" && ENVIRON["ZM_N"] != "" && index($5, ENVIRON["ZM_N"]) == 1)) { print $5; exit }' "$t"
}
_st_vpn_json() {
	local key=""
	stl_state vpn || { echo null; return; }
	[ "$STL_UP" = true ] && key="$(_st_active_key)"
	printf '{"up":%s,"failed":%s' "$STL_UP" "$STL_FAILED"
	[ "$STL_UP" = true ] && [ -n "$key$STL_NODE" ] && printf ',"node":"%s"' "$(esc "${key:-$STL_NODE}")"
	[ -n "$STL_NWHY" ] && printf ',"why":"%s"' "$(esc "$STL_NWHY")"
	[ -n "$STL_PSTATE" ] && printf ',"probe":{"state":"%s","node":%s,"total":%s}' "$STL_PSTATE" "$STL_PNODE" "$STL_PTOTAL"
	printf '}'
}
_st_vpn_dev() {
	local d
	stl_state vpn >/dev/null 2>&1 && [ -n "$STL_DEV" ] && [ -d "/sys/class/net/$STL_DEV" ] && { echo "$STL_DEV"; return 0; }
	for d in $STL_VPN_DEVS; do [ -d "/sys/class/net/$d" ] && { echo "$d"; return 0; }; done
	return 1
}
_st_vpn_trace() {
	local u t
	[ -w "/proc/sys/net/ipv4/conf/$1/rp_filter" ] && echo 2 > "/proc/sys/net/ipv4/conf/$1/rp_filter" 2>/dev/null
	for u in https://1.1.1.1/cdn-cgi/trace https://www.cloudflare.com/cdn-cgi/trace; do
		t="$(curl -4 -s --interface "$1" --connect-timeout 5 --max-time 10 "$u" 2>/dev/null)"
		case "$t" in *ip=*) printf '%s\n' "$t"; return 0 ;; esac
	done
	return 1
}

_st_vpn_zone() {
	local d have ch=0
	if [ "$1" = on ]; then
		if [ "$(uci -q get "firewall.$ST_VPN_ZONE")" = zone ]; then
			have=" $(uci -q get "firewall.$ST_VPN_ZONE.device") "
			for d in $(_st_vpn_devs_all); do
				case "$have" in *" $d "*) ;; *) uci add_list "firewall.$ST_VPN_ZONE.device=$d"; ch=1 ;; esac
			done
			[ "$ch" = 1 ] && { uci commit firewall; /etc/init.d/firewall reload >/dev/null 2>&1; }
			_zm_fwd_fix "${ST_VPN_ZONE}_fwd"
			return 0
		fi
		uci set "firewall.$ST_VPN_ZONE=zone"
		uci set "firewall.$ST_VPN_ZONE.name=$ST_VPN_ZONE"
		for d in $(_st_vpn_devs_all); do uci add_list "firewall.$ST_VPN_ZONE.device=$d"; done
		uci set "firewall.$ST_VPN_ZONE.input=REJECT"
		uci set "firewall.$ST_VPN_ZONE.output=ACCEPT"
		uci set "firewall.$ST_VPN_ZONE.forward=REJECT"
		uci set "firewall.$ST_VPN_ZONE.masq=0"
		uci set "firewall.$ST_VPN_ZONE.mtu_fix=1"
		uci set "firewall.${ST_VPN_ZONE}_fwd=forwarding"
		uci set "firewall.${ST_VPN_ZONE}_fwd.src=$(_zm_lan_zone)"
		uci set "firewall.${ST_VPN_ZONE}_fwd.dest=$ST_VPN_ZONE"
		uci commit firewall
		_st_own "fw $ST_VPN_ZONE"
		/etc/init.d/firewall reload >/dev/null 2>&1
	else
		_st_owns "fw $ST_VPN_ZONE" || return 0
		_st_vpn_any && return 0
		uci -q delete "firewall.$ST_VPN_ZONE"
		uci -q delete "firewall.${ST_VPN_ZONE}_fwd"
		uci commit firewall
		/etc/init.d/firewall reload >/dev/null 2>&1
		sed -i "/^fw $ST_VPN_ZONE\$/d" "$ST_OWNED" 2>/dev/null
	fi
}

_st_vpn_check() {
	local w=0 tr ip loc max="${1:-90}"
	while [ "$w" -lt "$max" ]; do
		stl_state vpn >/dev/null 2>&1
		[ "$STL_UP" = true ] && [ -n "$STL_DEV" ] && [ -d "/sys/class/net/$STL_DEV" ] && break
		[ "$w" -ge 6 ] && { [ -n "$STL_NWHY" ] || [ "$STL_PSTATE" = failed ] || [ "$STL_PSTATE" = no_such_node ]; } && break
		sleep 2; w=$((w + 2))
	done
	if [ "$STL_UP" = true ] && [ -n "$STL_DEV" ]; then
		w=0
		while [ "$w" -lt 3 ]; do
			tr="$(_st_vpn_trace "$STL_DEV")"
			ip="$(echo "$tr" | sed -n 's/^ip=//p')"; loc="$(echo "$tr" | sed -n 's/^loc=//p')"
			if [ -n "$ip" ]; then
				echo "[ OK ] VPN: трафик идёт через узел${STL_NODE:+ «$STL_NODE»} (выход $ip${loc:+, $loc})"
				return 0
			fi
			w=$((w + 1)); [ "$w" -lt 3 ] && { sleep 5; stl_state vpn >/dev/null 2>&1; }
		done
	fi
	stl_state vpn >/dev/null 2>&1
	if [ "$STL_FAILED" = true ] && [ -n "$STL_NWHY" ]; then
		echo "[FAIL] VPN: узел$( [ -s "$ST_SUB_NODE" ] && printf ' «%s»' "$(head -n1 "$ST_SUB_NODE")") не отвечает — $STL_NWHY; $(_st_fail_text)"
	elif [ "$STL_PSTATE" = no_such_node ]; then
		echo "[FAIL] VPN: выбранного узла больше нет в подписке — выберите «Авто» или другой узел"
	elif [ "$STL_PSTATE" = failed ] || [ "$STL_UP" != true ]; then
		echo "[FAIL] VPN: ни один выбранный узел не ответил за $max с — проверьте задержку узлов на вкладке «Подписка»"
	else
		echo "[FAIL] VPN: туннель поднят${STL_NODE:+ (узел «$STL_NODE»)}, но трафик через него не идёт"
	fi
	return 1
}

_st_need_ext() {
	_st_installed || { echo "ОШИБКА: сначала установите Steer"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: ядро steer сейчас настраивает не Zapret Manager"; return 1; }
	if ! stl_has vpn; then
		_ensure_deps
		_st_phase pkgs
		STL_MODS_ONLY=1 _st_install_steer vpn || return 1
		stl_has vpn || { echo "ОШИБКА: модуль VLESS ядра steer не установился"; return 1; }
	fi
	_st_phase sub
}
_st_need_mods() {
	local f names=""
	f="$(stl_sub_mods "$1")"
	_st_feats_ok $f && return 0
	case " $f " in *" hy2 "*) names="Hysteria2" ;; esac
	case " $f " in *" proxy "*) names="${names:+$names, }Trojan, Shadowsocks, SOCKS, HTTP или VMess" ;; esac
	_rb_say "В подписке есть серверы ${names:-VLESS} — ставим для них модули ядра steer"
	_st_phase pkgs
	STL_MODS_ONLY=1 _st_install_steer $f || return 1
	_st_feats_ok $f || { echo "ОШИБКА: модули ядра steer для протоколов подписки не установились"; return 1; }
	_st_phase sub
}
_st_sub_take() {
	rm -f "$ST_SUB.new" "$ST_SUB.new.map"
	stl_sub_norm "$1" "$ST_SUB.new" || { rm -f "$ST_SUB.new" "$ST_SUB.new.map"; echo "ОШИБКА: в подписке пусто"; return 1; }
	_st_need_mods "$ST_SUB.new" || { rm -f "$ST_SUB.new" "$ST_SUB.new.map"; return 1; }
	_st_sub_check "$ST_SUB.new" || { rm -f "$ST_SUB.new" "$ST_SUB.new.map"; return 1; }
}
_st_sub_commit() {
	mv -f "$ST_SUB.new.map" "$ST_SUB.map" 2>/dev/null || : > "$ST_SUB.map"
	mv -f "$ST_SUB.new" "$ST_SUB"
	chmod 600 "$ST_SUB"
	rm -f "$ST_SUB_NODES"
}

_st_proto_names() {
	local p o=""
	for p; do
		case "$p" in vless) p=VLESS ;; hysteria2) p=Hysteria2 ;; trojan) p=Trojan ;; shadowsocks) p=Shadowsocks ;; socks) p=SOCKS ;; http) p=HTTP ;; vmess) p=VMess ;; esac
		o="$o${o:+, }$p"
	done
	printf '%s' "$o"
}
_st_sub_check() {
	if stl_sub_check "$1"; then
		_rb_say "Узлов, с которыми умеет работать Steer: $STL_SUB_USABLE ($(_st_proto_names $STL_SUB_PROTOS))"
		return 0
	fi
	echo "ОШИБКА: в подписке нет узлов, с которыми умеет работать Steer (VLESS, Hysteria2, Trojan, Shadowsocks, SOCKS, HTTP, VMess)"
	[ -n "$STL_SUB_WHY" ] && printf '%s\n' "$STL_SUB_WHY" | sed 's/^/   причина: /'
	return 1
}

ST_SUB_VIA="$ST_DIR/sub.via"
_zm_bin() { local d IFS=:; for d in ${PATH:-/usr/sbin:/usr/bin:/sbin:/bin}; do [ -n "$d" ] && [ -x "$d/$1" ] && [ ! -d "$d/$1" ] && { echo "$d/$1"; return 0; }; done; return 1; }
_st_sub_via_pick() {
	local d
	d="$(_st_vpn_dev 2>/dev/null)" && _st_via_ok "$d" && { echo "$d|VPN"; return 0; }
	_st_via_pick
}
_st_sub_get() {
	local c w dv lb op rc
	[ -f "$ST_SUB_VIA" ] || { stl_sub_fetch "$@"; return; }
	if ! c="$(_zm_bin curl)"; then
		echo "   · Через VPN подписку качать нечем (нет curl) — качаем напрямую"
		stl_sub_fetch "$@"; return
	fi
	if ! dv="$(_st_sub_via_pick)"; then
		echo "   · Подключение Steer сейчас не работает — подписку качаем напрямую"
		stl_sub_fetch "$@"; return
	fi
	lb="${dv#*|}"; dv="${dv%%|*}"
	[ -w "/proc/sys/net/ipv4/conf/$dv/rp_filter" ] && echo 2 > "/proc/sys/net/ipv4/conf/$dv/rp_filter" 2>/dev/null
	w="$JOBS_DIR/subvia.$$"
	rm -rf "$w"; mkdir -p "$w"
	printf '#!/bin/sh\nexec "%s" --interface "%s" --connect-timeout 10 "$@"\n' "$c" "$dv" > "$w/curl"
	chmod 755 "$w/curl"
	echo "   · Подписку качаем через $lb"
	op="$PATH"; PATH="$w:$PATH"; export PATH
	stl_sub_fetch "$@"; rc=$?
	PATH="$op"; export PATH
	rm -rf "$w"
	[ "$rc" = 0 ] && return 0
	echo "   · Через $lb подписка не скачалась${STL_SUB_ERR:+ ($STL_SUB_ERR)} — качаем напрямую"
	stl_sub_fetch "$@"
}
_st_sub_fetch() {
	rm -f "$ST_SUB.raw"
	if ! _st_sub_get "$1" "$ST_SUB.raw" "$ST_SUB_INFO"; then
		echo "ОШИБКА: подписка не скачалась${STL_SUB_ERR:+ — $STL_SUB_ERR}"
		return 1
	fi
	[ -n "$STL_SUB_WARN" ] && _rb_warn "$STL_SUB_WARN"
	_st_sub_take "$ST_SUB.raw" || { rm -f "$ST_SUB.raw"; return 1; }
	rm -f "$ST_SUB.raw"
	_st_sub_commit
	printf '%s\n' "${STL_SUB_URL:-$1}" > "$ST_SUB_URL"
	chmod 600 "$ST_SUB_URL"
	if [ -n "$STL_SUB_TITLE" ]; then printf '%s\n' "$STL_SUB_TITLE" > "$ST_SUB_TITLE"; else rm -f "$ST_SUB_TITLE"; fi
	_rb_say "Подписка «$(_st_sub_label)» скачана"
	_st_sub_node_gone
}

_st_sub_node_gone() {
	local node t
	node="$(cat "$ST_SUB_NODE" 2>/dev/null)"
	[ -n "$node" ] && [ -s "$ST_SUB" ] || return 0
	t="$(_st_nodes)" && _st_key_in "$t" "$node" && return 0
	rm -f "$ST_SUB_NODE"
	echo "   · выбранного узла «$node» больше нет в подписке — Steer сам выберет рабочий"
}

_st_sub_apply() {
	_st_ping_cron
	if [ -f "$ST_OFF" ]; then
		_rb_say "Steer выключен — настройки сохранены и применятся при включении"
		return 0
	fi
	[ "$(_st_pick)" = ping ] && _st_use_vpn && [ ! -s "$ST_SUB_NODE" ] && _st_ping_refresh
	_st_phase rules
	_st_apply || return 1
	_st_phase check
	sleep 2
	_st_selfcheck
	_rb_say "Готово"
}

do_steer_sub_set() {
	local f="$ST_VDIR/sub.pending" in
	rm -f "$ST_STOP_FLAG"
	_st_phase sub
	[ -s "$f" ] || { echo "ОШИБКА: нет ссылки"; return 1; }
	in="$(cat "$f")"
	rm -f "$f"
	_st_need_ext || return 1
	case "$in" in
		http://*|https://*)
			_rb_say "Скачиваем подписку"
			_st_sub_fetch "$(printf '%s' "$in" | tr -d ' \r\n\t')" || return 1
			;;
		*)
			printf '%s\n' "$in" | tr ' \t\r' '\n\n\n' | grep -iE "$STL_LINK_RE" | awk '!s[$0]++' > "$ST_SUB.raw"
			[ -s "$ST_SUB.raw" ] || { rm -f "$ST_SUB.raw"; echo "ОШИБКА: в тексте нет ссылок на серверы (vless://, trojan://, ss://, vmess://, hysteria2://, socks5://)"; return 1; }
			_st_sub_take "$ST_SUB.raw" || { rm -f "$ST_SUB.raw"; return 1; }
			rm -f "$ST_SUB.raw"
			_st_sub_commit
			rm -f "$ST_SUB_URL" "$ST_SUB_TITLE" "$ST_SUB_INFO"
			_rb_say "Ссылки сохранены"
			;;
	esac
	rm -f "$ST_SUB_NODE" "$ST_SUB_HOME"
	echo vpn > "$ST_EXIT"
	_rb_say "Выбранные сервисы теперь идут через подписку"
	_rb_say "Перезапускаем VPN-туннель с новым списком серверов"
	_st_sub_apply
}

do_steer_sub_links() {
	local f="$ST_VDIR/sub.pending" n
	rm -f "$ST_STOP_FLAG"
	_st_phase sub
	[ -s "$f" ] || { echo "ОШИБКА: нет ссылок"; return 1; }
	_st_need_ext || { rm -f "$f"; return 1; }
	tr ' \t\r' '\n\n\n' < "$f" | grep -iE "$STL_LINK_RE" | awk '!s[$0]++' > "$ST_SUB.raw"
	rm -f "$f"
	[ -s "$ST_SUB.raw" ] || { rm -f "$ST_SUB.raw"; echo "ОШИБКА: в тексте нет ссылок на серверы"; return 1; }
	n="$(grep -c . "$ST_SUB.raw")"
	_rb_say "Проверяем ссылки: $n"
	_st_sub_take "$ST_SUB.raw" || { rm -f "$ST_SUB.raw"; echo "Прежний список серверов не тронут"; return 1; }
	rm -f "$ST_SUB.raw"
	rm -f "$ST_SUB.bak"
	_st_sub_commit
	rm -f "$ST_SUB_URL" "$ST_SUB_TITLE" "$ST_SUB_INFO"
	_st_sub_node_gone
	_rb_say "Список серверов сохранён"
	if _st_use_vpn && _st_installed; then _rb_say "Перезапускаем VPN-туннель с новым списком серверов"; _st_sub_apply
	else _rb_say "Готово — серверы применятся, когда выход будет «VPN»"; fi
}

do_steer_sub_update() {
	local was now
	rm -f "$ST_STOP_FLAG"
	_st_phase sub
	[ -s "$ST_SUB_URL" ] || { echo "ОШИБКА: это не подписка, а свои ссылки — обновлять нечего"; return 1; }
	_st_need_ext || return 1
	_rb_say "Обновляем подписку"
	was="$(md5sum < "$ST_SUB" 2>/dev/null)"
	if ! _st_sub_fetch "$(head -n1 "$ST_SUB_URL")"; then
		[ "$1" = auto ] && echo "   · прежний список серверов остался в работе"
		return 1
	fi
	now="$(md5sum < "$ST_SUB" 2>/dev/null)"
	_st_use_vpn || { _rb_say "Готово"; return 0; }
	if [ "$1" = auto ] && [ "$was" = "$now" ] && [ ! -f "$ST_OFF" ] && stl_running && _st_vpn_probe; then
		_rb_say "Список серверов не изменился, VPN работает — туннель не трогаем"
		return 0
	fi
	_rb_say "Перезапускаем VPN-туннель с обновлённым списком серверов"
	_st_sub_apply || { [ "$1" = auto ] && [ ! -f "$ST_OFF" ] && _st_vpn_heal; return 1; }
	[ "$1" = auto ] && [ ! -f "$ST_OFF" ] && _st_work && ! _st_vpn_probe && _st_vpn_heal
	return 0
}

ST_SUB_FELL="$ST_DIR/sub.node.fell"
ST_VPN_WATCH="$JOBS_DIR/steer.vpnwatch"
ST_NODE_POL="$ST_DIR/node.pol"
ST_SUB_HOME="$ST_DIR/sub.node.home"
_st_node_pol() { case "$(cat "$ST_NODE_POL" 2>/dev/null)" in switch) echo switch ;; hold) echo hold ;; *) echo back ;; esac; }
_st_fail_text() { [ "$(_st_onfail)" = drop ] && echo "выбранные сервисы остановлены" || echo "выбранные сервисы идут напрямую"; }
_st_node_down() {
	[ "$STL_UP" = true ] && return 1
	[ -n "$STL_NWHY" ] || [ "$STL_PSTATE" = failed ] || [ "$STL_PSTATE" = no_such_node ]
}
_st_diag_node() {
	case "$1" in
		"выход "*": узел перестал отвечать"*|"выход "*": соединение с узлом "*" не поднято"*|"выход "*": ни один узел подписки не ответил"*|\
		"выход "*": выбран узел "*|"выход "*": все узлы-кандидаты"*|"выход "*": в подписке нет пригодных узлов"*|"выход "*" не отвечает, трафик канала"*) return 0 ;;
	esac
	return 1
}

_st_node_failover() {
	local pinned pol
	pinned="$(cat "$ST_SUB_NODE" 2>/dev/null)"
	[ -n "$pinned" ] || return 1
	pol="$(_st_node_pol)"
	if [ "$pol" = hold ]; then
		echo "   · Узел «$pinned» не трогаем — так задано в «Если выбранный узел не отвечает»: $(_st_fail_text), пока он не ответит или вы не выберете другой узел"
		return 1
	fi
	mkdir -p "$ST_VDIR"
	printf '%s\n' "$pinned" > "$ST_SUB_FELL"
	if [ "$pol" = back ]; then printf '%s\n' "$pinned" > "$ST_SUB_HOME"; else rm -f "$ST_SUB_HOME"; fi
	rm -f "$ST_SUB_NODE"
	if [ "$pol" = back ]; then _rb_say "Узел «$pinned» не отвечает — переходим на рабочий узел и вернёмся на него, когда он ответит"
	else _rb_say "Узел «$pinned» не отвечает — переходим на рабочий узел"; fi
	logger -t zapret-manager "Steer: узел «$pinned» не отвечает — переходим на рабочий узел"
	_st_spec_quick >/dev/null 2>&1
	[ $? = 2 ] && _st_apply >/dev/null 2>&1
	_st_vpn_check && return 0
	echo "   · Рабочего узла пока нет — ядро steer продолжит перебирать узлы само"
	return 1
}

_st_home_tick() {
	local home cur t i st="$JOBS_DIR/steer.hometick${ST_SEC:+.$ST_SEC}"
	home="$(head -n1 "$ST_SUB_HOME" 2>/dev/null)"
	[ -n "$home" ] || return 0
	cur="$(cat "$ST_SUB_NODE" 2>/dev/null)"
	if [ "$cur" = "$home" ] || [ "$(_st_node_pol)" != back ]; then rm -f "$ST_SUB_HOME"; return 0; fi
	t="$(_st_nodes)" && i="$(ZM_W="$home" awk -F'\t' '$5 == ENVIRON["ZM_W"] { print $1; exit }' "$t")"
	[ -n "$i" ] || { rm -f "$ST_SUB_HOME"; return 0; }
	_st_key_hidden "$home" && { rm -f "$ST_SUB_HOME"; return 0; }
	[ -n "$(find "$st" -mmin -10 2>/dev/null)" ] && return 0
	mkdir -p "$JOBS_DIR"; : > "$st"
	( [ "$(steer_sub_probe "$i" 2>/dev/null | jsonfilter -e '@.results[0].ok' 2>/dev/null)" = true ] &&
		! _zm_busy_job >/dev/null 2>&1 && job_start steer do_steer_home_back >/dev/null 2>&1 ) >/dev/null 2>&1 &
	return 0
}

do_steer_home_back() {
	local home prev
	rm -f "$ST_STOP_FLAG"
	home="$(head -n1 "$ST_SUB_HOME" 2>/dev/null)"
	[ -n "$home" ] || { _rb_say "Возвращаться не на что — выбор узла уже изменён"; return 0; }
	_st_key_in "$(_st_nodes)" "$home" || { rm -f "$ST_SUB_HOME"; _rb_say "Узла «$home» больше нет в подписке — остаёмся на текущем"; return 0; }
	_st_key_hidden "$home" && { rm -f "$ST_SUB_HOME"; _rb_say "Узел «$home» скрыт — остаёмся на текущем"; return 0; }
	prev="$(cat "$ST_SUB_NODE" 2>/dev/null)"; prev="${prev:-auto}"
	_rb_say "Узел «$home» снова отвечает — возвращаемся на него"
	logger -t zapret-manager "Steer: узел «$home» снова отвечает — возвращаемся на него"
	mkdir -p "$ST_VDIR"
	printf '%s\n' "$home" > "$ST_SUB_NODE"
	rm -f "$ST_SUB_HOME" "$ST_SUB_FELL" "$ST_VPN_WATCH"
	do_steer_switch "$prev"
}

_st_vpn_heal() {
	local pinned
	pinned="$(cat "$ST_SUB_NODE" 2>/dev/null)"
	if [ -n "$pinned" ] && stl_running && stl_state vpn >/dev/null 2>&1 && _st_node_down; then
		_rb_warn "VPN не отвечает: не отвечает выбранный узел «$pinned»${STL_NWHY:+ ($STL_NWHY)} — ядро steer исправно, перезапускать его незачем"
		_st_node_failover && { _st_vpn_probe >/dev/null 2>&1; echo "[ OK ] VPN работает через другой узел"; return 0; }
		[ "$(_st_node_pol)" = hold ] && return 0
		echo "[FAIL] VPN не поднялся — ни один узел подписки не отвечает"
		return 1
	fi
	_rb_say "VPN не отвечает — перезапускаем Steer"
	logger -t zapret-manager "Steer: VPN не отвечает — перезапускаем службу"
	_zm_run 120 stl_restart >/dev/null 2>&1
	sleep 3
	if _st_vpn_check >/dev/null 2>&1; then
		_st_vpn_probe >/dev/null 2>&1
		echo "[ OK ] VPN снова работает"
		return 0
	fi
	pinned="$(cat "$ST_SUB_NODE" 2>/dev/null)"
	if [ -n "$pinned" ] && [ "$(_st_node_pol)" != hold ]; then
		_rb_warn "Узел «$pinned» не отвечает — переходим на рабочий"
		if _st_node_failover >/dev/null 2>&1; then
			_st_vpn_probe >/dev/null 2>&1
			echo "[ OK ] VPN работает через другой узел"
			return 0
		fi
	fi
	echo "[FAIL] VPN не поднялся — ни один сервер подписки не отвечает"
	return 1
}

do_steer_vpn_heal() {
	rm -f "$ST_STOP_FLAG"
	_st_phase check
	_st_vpn_heal
}

_st_vpn_watch() {
	local f="$ST_VPN_WATCH" fails=0 heals=0 last=0 now wait
	_st_installed && _st_use_vpn && [ ! -f "$ST_OFF" ] && [ -s "$ST_SUB" ] && _st_owns "steer-spec" || { rm -f "$f"; return 0; }
	stl_enabled || { rm -f "$f"; return 0; }
	_st_work_main || { rm -f "$f"; return 0; }
	[ -z "$(_st_blocker)" ] || return 0
	_zm_busy_job >/dev/null 2>&1 && return 0
	[ -s "$ST_SUB_HOME" ] && _st_home_tick
	if _st_vpn_probe; then rm -f "$f" "$JOBS_DIR/steer.holdlog${ST_SEC:+.$ST_SEC}"; return 0; fi
	_zm_inet_ok || return 0
	if [ -s "$ST_SUB_NODE" ] && [ "$(_st_node_pol)" = hold ] && stl_running && stl_state vpn >/dev/null 2>&1 && _st_node_down; then
		if ! cmp -s "$ST_SUB_NODE" "$JOBS_DIR/steer.holdlog${ST_SEC:+.$ST_SEC}" 2>/dev/null; then
			cp -f "$ST_SUB_NODE" "$JOBS_DIR/steer.holdlog${ST_SEC:+.$ST_SEC}" 2>/dev/null
			logger -t zapret-manager "Steer: выбранный узел «$(head -n1 "$ST_SUB_NODE")» не отвечает — держим его, как задано в настройке"
		fi
		rm -f "$f"
		return 0
	fi
	{ read -r fails heals last < "$f"; } 2>/dev/null
	fails="${fails:-0}"; heals="${heals:-0}"; last="${last:-0}"
	fails=$((fails + 1))
	now="$(date +%s)"
	if [ "$fails" -lt 2 ]; then echo "$fails $heals $last" > "$f"; return 0; fi
	case "$heals" in 0) wait=0 ;; 1) wait=600 ;; 2) wait=1800 ;; *) wait=10800 ;; esac
	[ $((now - last)) -lt "$wait" ] && { echo "$fails $heals $last" > "$f"; return 0; }
	echo "$fails $((heals + 1)) $now" > "$f"
	job_start steer do_steer_vpn_heal >/dev/null 2>&1
	return 0
}

do_steer_sub_remove() {
	local was=0
	_st_phase sub
	rm -f "$ST_STOP_FLAG"
	_st_use_vpn && was=1
	rm -f "$ST_SUB" "$ST_SUB.bak" "$ST_SUB.map" "$ST_SUB_NODES" "$ST_SUB_NODES.meta" "$ST_SUB_NODES.hp" "$ST_SUB_INFO" "$ST_SUB_URL" "$ST_SUB_TITLE" "$ST_SUB_NODE" "$ST_SUB_FELL" "$ST_SUB_HOME" "$ST_SUB_PING" "$ST_SUB_ORDER"
	[ -n "$ST_SEC" ] || echo warp > "$ST_EXIT"
	_st_vpn_zone off
	[ -n "$(_st_sec_with main eval '[ -s "$ST_SUB_URL" ] && echo 1')$(_st_secs_url)" ] || _st_sub_auto_set off >/dev/null
	_st_ping_cron
	if [ -n "$ST_SEC" ]; then _rb_say "Подписка секции «$(_st_sec_name "$ST_SEC")» удалена — её сервисы идут напрямую, пока не добавите подписку или не смените подключение секции"
	elif _st_warp_on; then _rb_say "Подписка удалена — выбранные сервисы идут через WARP"
	else _rb_say "Подписка удалена — туннеля больше нет, сервисы идут напрямую"; fi
	if [ "$was" = 1 ] && _st_installed; then _st_sub_apply || return 1; fi
	return 0
}

steer_sub_action() {
	rm -f "$ST_VPN_PROBE"
	local action="$1" mode="$2"
	case "$action" in
		sub_set)
			_st_installed || { echo '{"error":"сначала установите Steer"}'; return 1; }
			case "$mode" in
				http://*|https://*) ;;
				*) printf '%s\n' "$mode" | tr ' \t\r' '\n\n\n' | grep -qiE "$STL_LINK_RE" || { echo '{"error":"нужна ссылка на подписку (https://…) или ссылки на серверы: vless://, trojan://, ss://, vmess://, hysteria2://, socks5://"}'; return 1; } ;;
			esac
			mkdir -p "$ST_VDIR"
			printf '%s\n' "$mode" > "$ST_VDIR/sub.pending"
			chmod 600 "$ST_VDIR/sub.pending"
			job_start steer do_steer_sub_set
			;;
		sub_links)
			_st_installed || { echo '{"error":"сначала установите Steer"}'; return 1; }
			[ -s "$ST_SUB_URL" ] && { echo '{"error":"сейчас подключена подписка по ссылке — свои серверы можно задать, удалив её"}'; return 1; }
			printf '%s\n' "$mode" | tr ' \t\r' '\n\n\n' | grep -qiE "$STL_LINK_RE" || { echo '{"error":"нет ни одной ссылки на сервер"}'; return 1; }
			mkdir -p "$ST_VDIR"
			printf '%s\n' "$mode" > "$ST_VDIR/sub.pending"
			chmod 600 "$ST_VDIR/sub.pending"
			job_start steer do_steer_sub_links
			;;
		sub_update)
			[ -s "$ST_SUB_URL" ] || { echo '{"error":"обновлять нечего"}'; return 1; }
			job_start steer do_steer_sub_update
			;;
		sub_remove)
			[ -s "$ST_SUB" ] || { echo '{"error":"подписки нет"}'; return 1; }
			job_start steer do_steer_sub_remove
			;;
		iface_forget)
			[ -s "$ST_DIR/exit.iface" ] || [ "$(cat "$ST_EXIT" 2>/dev/null)" = iface ] || { echo '{"error":"туннель для основной секции не выбран"}'; return 1; }
			rm -f "$ST_DIR/exit.iface"
			[ "$(cat "$ST_EXIT" 2>/dev/null)" = iface ] || { printf '{"ok":true}\n'; return 0; }
			if [ -s "$ST_SUB" ] && _st_vpn_ok; then echo vpn > "$ST_EXIT"
			elif _st_warp_on; then echo warp > "$ST_EXIT"; _st_vpn_zone off
			else rm -f "$ST_EXIT"; _st_vpn_zone off; fi
			if _st_installed && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] && _st_work; then
				if [ "$(cat "$ST_EXIT" 2>/dev/null)" = vpn ] && ! _st_feats_ok $(_st_sub_feats); then job_start steer do_steer_sub_exit_vpn
				else job_start steer do_steer_apply; fi
			else
				printf '{"ok":true,"saved":true}\n'
			fi
			;;
		sub_exit)
			case "$mode" in warp|vpn|iface:?*) ;; *) echo '{"error":"неизвестный выход"}'; return 1 ;; esac
			[ "$mode" = vpn ] && [ ! -s "$ST_SUB" ] && { echo '{"error":"сначала добавьте подписку"}'; return 1; }
			[ "$mode" = warp ] && ! _st_warp_on && { echo '{"error":"сначала подключите WARP"}'; return 1; }
			mkdir -p "$ST_VDIR"
			case "$mode" in iface:*)
				_st_sec_kind_check iface "${mode#iface:}" "" || return 1
				printf '%s\n' "${mode#iface:}" > "$ST_DIR/exit.iface"
				mode=iface ;;
			esac
			echo "$mode" > "$ST_EXIT"
			[ "$mode" = vpn ] || _st_vpn_zone off
			if _st_installed && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] && _st_work; then
				if [ "$mode" = vpn ] && ! _st_feats_ok $(_st_sub_feats); then job_start steer do_steer_sub_exit_vpn
				else job_start steer do_steer_apply; fi
			else
				printf '{"ok":true,"saved":true}\n'
			fi
			;;
		sub_filter)
			local m err tsv total hid
			case "$mode" in '{'*) m="$(printf '%s' "$mode" | jsonfilter -e '@.m' 2>/dev/null)" ;; *) m="$mode" ;; esac
			if [ -s "$ST_SUB" ] && _st_vpn_ok && [ -n "$(printf '%s' "$m" | tr -d ' |,')" ]; then
				_zm_excl_save "$ST_VDIR/sub.exclude.try" "$m" >/dev/null
				tsv="$(_st_nodes_kv)"
				total="$(printf '%s\n' "$tsv" | grep -c .)"
				hid="$(printf '%s\n' "$tsv" | _zm_excl_hits "$ST_VDIR/sub.exclude.try" "$ST_SUB_HIDE" | grep -c .)"
				rm -f "$ST_VDIR/sub.exclude.try"
				[ "$total" -gt 0 ] && [ "$hid" -ge "$total" ] && { echo '{"error":"под эти маркеры попадают все узлы подписки — тогда VPN работать не сможет. Уберите лишние маркеры"}'; return 1; }
			fi
			err="$(_zm_excl_save "$ST_SUB_EXCL" "$m")" || { printf '{"error":"%s"}\n' "$(esc "$err")"; return 1; }
			if [ -s "$ST_SUB_NODE" ] && _st_nodes_kv | ZM_W="$(cat "$ST_SUB_NODE")" awk -F'\t' '$2 == ENVIRON["ZM_W"]' | _zm_excl_hits "$ST_SUB_EXCL" "$ST_SUB_HIDE" | grep -c . | grep -qv '^0$'; then
				rm -f "$ST_SUB_NODE"
			fi
			_st_hidden_drop
			if [ -s "$ST_SUB" ] && _st_use_vpn && _st_installed && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] && _st_work; then
				job_start steer do_steer_switch -
			else
				printf '{"ok":true,"saved":true}\n'
			fi
			;;
		sub_hide)
			local nf="$JOBS_DIR/steer.hide.in" tsv total hid mk xf="$ST_SUB_EXCL" err
			[ -s "$ST_SUB" ] || { echo '{"error":"подписки нет"}'; return 1; }
			mkdir -p "$ST_VDIR"
			if [ "$(printf '%s' "$mode" | jsonfilter -e '@.reset' 2>/dev/null)" = true ]; then
				rm -f "$ST_SUB_HIDE" "$ST_SUB_EXCL"
			else
				case "$mode" in *'"markers":'*|*'"markers" :'*)
					mk="$(printf '%s' "$mode" | jsonfilter -e '@.markers' 2>/dev/null)"
					xf="$ST_VDIR/sub.exclude.try.$$"
					err="$(_zm_excl_save "$xf" "$mk")" || { printf '{"error":"%s"}\n' "$(esc "$err")"; return 1; }
					;;
				esac
				printf '%s' "$mode" | jsonfilter -e '@.names[*]' > "$nf" 2>/dev/null
				tsv="$(_st_nodes_kv)"
				total="$(printf '%s\n' "$tsv" | grep -c .)"
				hid="$(printf '%s\n' "$tsv" | _zm_excl_hits "$xf" "$nf" | grep -c .)"
				if [ "$total" -gt 0 ] && [ "$hid" -ge "$total" ]; then rm -f "$nf" "$ST_VDIR/sub.exclude.try.$$"; echo '{"error":"нельзя скрыть все узлы — тогда VPN работать не сможет"}'; return 1; fi
				if [ "$xf" != "$ST_SUB_EXCL" ]; then
					if [ -s "$xf" ]; then mv -f "$xf" "$ST_SUB_EXCL"; else rm -f "$xf" "$ST_SUB_EXCL"; fi
				fi
				_zm_names_save "$nf" "$ST_SUB_HIDE"
				rm -f "$nf"
				if [ -s "$ST_SUB_NODE" ] && printf '%s\n' "$tsv" | ZM_W="$(cat "$ST_SUB_NODE")" awk -F'\t' '$2 == ENVIRON["ZM_W"]' | _zm_excl_hits "$ST_SUB_EXCL" "$ST_SUB_HIDE" | grep -c . | grep -qv '^0$'; then
					rm -f "$ST_SUB_NODE"
				fi
				_st_hidden_drop
			fi
			if _st_use_vpn && _st_installed && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] && _st_work; then
				job_start steer do_steer_switch -
			else
				printf '{"ok":true,"saved":true}\n'
			fi
			;;
		sub_pick)
			local pm piv ptol
			case "$mode" in
				order) pm=order ;;
				ping:*)
					pm=ping; piv="$(printf '%s' "$mode" | cut -d: -f2)"; ptol="$(printf '%s' "$mode" | cut -d: -f3)"
					case "$piv" in 15|30|60|180) ;; *) echo '{"error":"интервал проверки: 15, 30, 60 или 180 минут"}'; return 1 ;; esac
					case "$ptol" in ''|*[!0-9]*) echo '{"error":"допуск — число миллисекунд от 0 до 10000"}'; return 1 ;; esac
					[ "$ptol" -le 10000 ] || { echo '{"error":"допуск — число миллисекунд от 0 до 10000"}'; return 1; } ;;
				*) echo '{"error":"неизвестный режим автовыбора"}'; return 1 ;;
			esac
			mkdir -p "$ST_VDIR"
			if [ "$pm" = ping ]; then echo "ping $piv $ptol" > "$ST_SUB_PICK"; else rm -f "$ST_SUB_PICK" "$ST_SUB_ORDER"; fi
			if [ -s "$ST_SUB" ] && _st_installed && _st_vpn_ok; then job_start steer do_steer_ping
			else _st_ping_cron; printf '{"ok":true,"saved":true}\n'; fi
			;;
		sub_ping)
			[ -s "$ST_SUB" ] || { echo '{"error":"подписки нет"}'; return 1; }
			[ "$(_st_pick)" = ping ] || { echo '{"error":"сначала выберите автовыбор «По пингу»"}'; return 1; }
			job_start steer do_steer_ping
			;;
		sub_node)
			[ -s "$ST_SUB" ] || { echo '{"error":"подписки нет"}'; return 1; }
			if [ -n "$mode" ] && ! _st_key_in "$(_st_nodes)" "$mode"; then
				echo '{"error":"такого узла нет в подписке — обновите страницу"}'; return 1
			fi
			if [ -n "$mode" ] && _st_nodes_kv | ZM_W="$mode" awk -F'\t' '$2 == ENVIRON["ZM_W"]' | _zm_excl_hits "$ST_SUB_EXCL" "$ST_SUB_HIDE" | grep -c . | grep -qv '^0$'; then
				echo '{"error":"этот узел скрыт фильтром — уберите маркер или выберите другой узел"}'; return 1
			fi
			mkdir -p "$ST_VDIR"
			local prev
			prev="$(cat "$ST_SUB_NODE" 2>/dev/null)"; prev="${prev:-auto}"
			if [ -n "$mode" ]; then printf '%s\n' "$mode" > "$ST_SUB_NODE"; else rm -f "$ST_SUB_NODE"; fi
			rm -f "$ST_SUB_FELL" "$ST_SUB_HOME" "$ST_VPN_WATCH"
			if _st_use_vpn && _st_installed && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] && _st_work; then
				job_start steer do_steer_switch "$prev"
			else
				printf '{"ok":true,"saved":true}\n'
			fi
			;;
	esac
}

ST_SUB_TAG="# zm-subupd"

_st_sub_auto_get() {
	local l h
	l="$(grep -F "$ST_SUB_TAG" "$CRON_FILE" 2>/dev/null | head -n1)"
	[ -n "$l" ] || { echo off; return; }
	h="$(echo "$l" | awk '{print $2}')"
	case "$h" in */*) echo "${h#*/}" ;; *) echo 24 ;; esac
}

_st_sub_auto_set() {
	local spec=""
	case "$1" in
		off) ;;
		3|6|12) spec="$(( $(date +%M | sed 's/^0//') % 60 )) */$1 * * *" ;;
		24) spec="$(( $(date +%M | sed 's/^0//') % 60 )) 5 * * *" ;;
		*) echo '{"error":"допустимо: выкл, 3, 6, 12 или 24 часа"}'; return 1 ;;
	esac
	mkdir -p "$(dirname "$CRON_FILE")"
	touch "$CRON_FILE"
	sed -i "\\|$ST_SUB_TAG|d" "$CRON_FILE"
	[ -n "$spec" ] && echo "$spec /opt/zapret-manager-luci/backend.sh steer_action sub_refresh x >/dev/null 2>&1 $ST_SUB_TAG" >> "$CRON_FILE"
	/etc/init.d/cron enable >/dev/null 2>&1
	/etc/init.d/cron restart >/dev/null 2>&1
	printf '{"ok":true}\n'
}

do_steer_engine() {
	_st_phase pkgs
	rm -f "$ST_STOP_FLAG"
	_st_installed || { echo "ОШИБКА: Steer ещё не установлен"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: ядро steer сейчас настраивает не Zapret Manager"; return 1; }
	rm -f "$STL_CACHE"
	_ensure_deps
	_st_install_steer || return 1
	if [ ! -f "$ST_OFF" ] && _st_work; then
		_st_phase rules
		_st_apply || return 1
	fi
	_rb_say "Готово, ядро steer $(stl_version)"
}

do_steer_sub_exit_vpn() {
	rm -f "$ST_STOP_FLAG"
	_st_need_ext || return 1
	_st_sub_apply
}

_st_nodes_json() {
	awk -F'\t' -v meta="$ST_SUB_NODES.meta" '
		function j(s,    o, i, c, n) { o = ""; n = length(s); for (i = 1; i <= n; i++) { c = substr(s, i, 1); if (c == "\\") o = o "\\\\"; else if (c == "\"") o = o "\\\""; else if (c < " ") o = o " "; else o = o c } return o }
		BEGIN { while ((getline l < meta) > 0) { if (l ~ /^skipped=/) sk = substr(l, 9); if (l ~ /^reasons=/) rs = substr(l, 9) }; printf "{\"nodes\":[" }
		{ printf "%s{\"index\":%d,\"name\":\"%s\",\"proto\":\"%s\",\"type\":\"%s\",\"security\":\"%s\",\"vision\":%s}", (NR > 1 ? "," : ""), $1, j($5), $2, j($6), j($7), ($8 == 1 ? "true" : "false") }
		END { printf "],\"usable\":%d,\"skipped\":%d,\"skipped_reasons\":%s}", NR, sk + 0, (rs == "" ? "[]" : rs) }' "$1"
}

steer_sub_status() {
	local has=false kind="" url="" title="" ext=false vexit=warp node="" up="" down="" total="" expire="" list=null vpn=null mt=0 hidden="" t
	_st_vpn_ok && ext=true
	vexit="$(_st_exit)"
	if [ -s "$ST_SUB" ]; then
		has=true
		if [ -s "$ST_SUB_URL" ]; then kind=url; url="$(head -n1 "$ST_SUB_URL")"; else kind=links; fi
		title="$(_st_sub_label)"
		if [ -s "$ST_SUB_INFO" ]; then
			up="$(sed -n 's/^upload=//p' "$ST_SUB_INFO" | head -n1)"
			down="$(sed -n 's/^download=//p' "$ST_SUB_INFO" | head -n1)"
			total="$(sed -n 's/^total=//p' "$ST_SUB_INFO" | head -n1)"
			expire="$(sed -n 's/^expire=//p' "$ST_SUB_INFO" | head -n1)"
		fi
		mt="$(date -r "$ST_SUB" +%s 2>/dev/null)"
		if [ "$ext" = true ] && t="$(_st_nodes)"; then
			list="$(_st_nodes_json "$t")"
			hidden="$(cut -f1,5 "$t" | _zm_excl_hits "$ST_SUB_EXCL" "$ST_SUB_HIDE" | tr '\n' ',' | sed 's/,$//')"
		fi
		node="$(cat "$ST_SUB_NODE" 2>/dev/null)"
	fi
	_st_use_vpn && _st_owns "steer-spec" && vpn="$(_st_vpn_json)"
	printf '{"ext":%s,"has":%s,"kind":"%s","url":"%s","title":"%s","exit":"%s","auto":"%s","node":"%s","quota":{"up":"%s","down":"%s","total":"%s","expire":"%s"},"updated":%s,"list":%s,"vpn":%s,"hidden":[%s],"exclude":"%s","hide_names":[%s],"fell":"%s","pick":"%s","pick_iv":%s,"pick_tol":%s,"ping_at":%s,"ping":{%s},"order_head":"%s","lat_mode":"%s","ping_blk":[%s],"ping_tcp":[%s],"home":"%s","node_pol":"%s"}\n' \
		"$ext" "$has" "$kind" "$(esc "$url")" "$(esc "$title")" "$vexit" "$(_st_sub_auto_get)" "$(esc "$node")" \
		"$(esc "$up")" "$(esc "$down")" "$(esc "$total")" "$(esc "$expire")" "${mt:-0}" "$list" "$vpn" "$hidden" "$(esc "$(cat "$ST_SUB_EXCL" 2>/dev/null)")" "$(_zm_json_lines "$ST_SUB_HIDE")" "$(esc "$(head -n1 "$ST_SUB_FELL" 2>/dev/null)")" \
		"$(_st_pick)" "$(_st_pick_iv)" "$(_st_pick_tol)" "$(date -r "$ST_SUB_PING" +%s 2>/dev/null || echo 0)" \
		"$([ -s "$ST_SUB_PING" ] && awk -F'\t' -v q='"' 'function j(s,    o, i, c, n) { o = ""; n = length(s); for (i = 1; i <= n; i++) { c = substr(s, i, 1); if (c == "\\") o = o "\\\\"; else if (c == "\"") o = o "\\\""; else if (c < " ") o = o " "; else o = o c } return o } { n = j($1); printf "%s%s%s%s:%d", (NR > 1 ? "," : ""), q, n, q, $2 + 0 }' "$ST_SUB_PING")" \
		"$(esc "$(_st_order_head)")" \
		"$(_st_lat_mode)" "$([ -s "$ST_SUB_PING" ] && awk -F'\t' -v q='"' 'function j(s,    o, i, c, n) { o = ""; n = length(s); for (i = 1; i <= n; i++) { c = substr(s, i, 1); if (c == "\\") o = o "\\\\"; else if (c == "\"") o = o "\\\""; else if (c < " ") o = o " "; else o = o c } return o } $3 == "b" { n = j($1); printf "%s%s%s%s", (c++ ? "," : ""), q, n, q }' "$ST_SUB_PING")" \
		"$([ -s "$ST_SUB_PING" ] && awk -F'\t' -v q='"' 'function j(s,    o, i, c, n) { o = ""; n = length(s); for (i = 1; i <= n; i++) { c = substr(s, i, 1); if (c == "\\") o = o "\\\\"; else if (c == "\"") o = o "\\\""; else if (c < " ") o = o " "; else o = o c } return o } $3 == "t" { n = j($1); printf "%s%s%s%s", (c++ ? "," : ""), q, n, q }' "$ST_SUB_PING")" \
		"$(esc "$(head -n1 "$ST_SUB_HOME" 2>/dev/null)")" "$(_st_node_pol)"
}

_st_hp_build() {
	local m hp="$ST_SUB_NODES.hp"
	[ -s "$hp" ] && [ ! "$ST_SUB" -nt "$hp" ] && return 0
	mkdir -p "$ST_DIR"
	{ for m in vless proxy; do
		[ -x "$STL_SBIN/steer-$m" ] || continue
		_stl_t 30 steer "$m-nodes" "$ST_SUB" 2>/dev/null | tr '\n\t' '  ' | awk -v M="$m" '{
			j = $0; p = index(j, "\"nodes\":["); if (!p) next
			j = substr(j, p + 9); n = split(j, C, /\{"index":/)
			for (i = 2; i <= n; i++) {
				ch = C[i]; idx = ch + 0; h = ""; pt = 0
				if (match(ch, /"host":"[^"]*"/)) h = substr(ch, RSTART + 8, RLENGTH - 9)
				if (match(ch, /"port":[0-9]+/)) pt = substr(ch, RSTART + 7, RLENGTH - 7) + 0
				if (h != "" && pt > 0) printf "%s\t%d\t%s\t%d\n", M, idx, h, pt
			}
		}'
	done; } > "$hp.$$" 2>/dev/null
	mv -f "$hp.$$" "$hp" 2>/dev/null
}

_st_tcp_one() {
	local h="$1" p="$2" to="$3" out="$4"
	case "$h" in *:*) h="[$h]" ;; esac
	( curl -s -o /dev/null --noproxy '*' --connect-timeout "$to" --max-time "$to" -w '%{time_connect} %{time_namelookup}\n' "http://$h:$p/" 2>/dev/null > "$out.a" ) &
	( curl -s -o /dev/null --noproxy '*' --connect-timeout "$to" --max-time "$to" -w '%{time_connect} %{time_namelookup}\n' "http://$h:$p/" 2>/dev/null > "$out.b" ) &
	wait
	cat "$out.a" "$out.b" 2>/dev/null | awk '{ c = $1 + 0; n = $2 + 0; if (c > 0) { if (n > 0 && n < c) c -= n; m = int(c * 1000 + 0.5); if (m < 1) m = 1; if (!b || m < b) b = m } } END { if (b) print b }' > "$out"
	rm -f "$out.a" "$out.b"
}

steer_sub_tcp() {
	local t dir list="" i p f hp retry="" out="" sep="" ms
	_zm_has curl || { echo '{"error":"на роутере нет curl"}'; return 1; }
	[ -s "$ST_SUB" ] && _st_vpn_ok && t="$(_st_nodes)" || { echo '{"error":"подписки нет"}'; return 1; }
	_st_hp_build
	dir="$ST_RUN/tcp.$$"; mkdir -p "$dir"
	for i in $(printf '%s' "$1" | tr ',' ' '); do
		case "$i" in ''|*[!0-9]*) continue ;; esac
		set -- $(awk -F'\t' -v g="$i" '$1 == g { print $2, $4; exit }' "$t")
		p="$(_stl_mod_of "$1")"; f="$2"
		hp=""
		[ -n "$1" ] && [ "$p" != hysteria2 ] && hp="$(awk -F'\t' -v m="$p" -v n="$f" '$1 == m && $2 == n { print $3, $4; exit }' "$ST_SUB_NODES.hp" 2>/dev/null)"
		if [ -z "$hp" ]; then echo udp > "$dir/$i.k"; list="$list $i"; continue; fi
		echo "$hp" > "$dir/$i.k"
		_st_tcp_one "${hp% *}" "${hp#* }" 3 "$dir/$i" &
		list="$list $i"
	done
	wait
	for i in $list; do
		[ "$(cat "$dir/$i.k")" != udp ] && [ ! -s "$dir/$i" ] || continue
		hp="$(cat "$dir/$i.k")"
		_st_tcp_one "${hp% *}" "${hp#* }" 6 "$dir/$i" &
		retry=1
	done
	[ -n "$retry" ] && wait
	for i in $list; do
		if [ "$(cat "$dir/$i.k")" = udp ]; then out="$out$sep\"$i\":{\"core\":true}"
		elif ms="$(cat "$dir/$i" 2>/dev/null)" && [ -n "$ms" ]; then out="$out$sep\"$i\":{\"ok\":true,\"ms\":$ms}"
		else out="$out$sep\"$i\":{\"ok\":false}"; fi
		sep=","
	done
	rm -rf "$dir"
	printf '{"results":{%s}}\n' "$out"
}

ST_SUB_PICK="$ST_DIR/sub.pick"
ST_LAT_MODE="$ST_DIR/lat.mode"
_st_lat_mode() { [ "$(cat "$ST_LAT_MODE" 2>/dev/null)" = real ] && echo real || echo fast; }
ST_SUB_PING="$ST_DIR/sub.ping"
ST_SUB_ORDER="$ST_DIR/sub.order"
ST_PING_TAG="# zm-subping"
_st_pick() { set -- $(head -n1 "$ST_SUB_PICK" 2>/dev/null); [ "$1" = ping ] && echo ping || echo order; }
_st_pick_iv() { set -- $(head -n1 "$ST_SUB_PICK" 2>/dev/null); case "$2" in 15|30|60|180) echo "$2" ;; *) echo 15 ;; esac; }
_st_pick_tol() { set -- $(head -n1 "$ST_SUB_PICK" 2>/dev/null); case "$3" in ''|*[!0-9]*) echo 50 ;; *) if [ "$3" -le 10000 ]; then echo "$3"; else echo 50; fi ;; esac; }

ST_SEC_DIR="$ST_DIR/sec"
ST_SEC_LIST="$ST_SEC_DIR/list"
ST_SEC_MAX=6
ST_SEC_VPN_MAX=3
_st_bind() {
	local d n
	if [ -z "$1" ] || [ "$1" = main ]; then
		ST_SEC=""; d="$ST_DIR"
		ST_SEL="$ST_DIR/services"; ST_SKIP="$ST_DIR/skip"; ST_DEVS="$ST_DIR/devices"; ST_EXIT="$ST_DIR/exit"
		ST_VPN_PROBE="$JOBS_DIR/steer.vpnprobe"; ST_VPN_WATCH="$JOBS_DIR/steer.vpnwatch"
		STL_VPN_OUT="zm_vpn"; STL_VPN_DEV="zm_vpn"; STL_VPN_PFX="zmv"; ST_CUSTOM="$ST_DIR/user/custom"
	else
		ST_SEC="$1"; n="${1#s}"; d="$ST_SEC_DIR/$1"
		ST_SEL="$d/services"; ST_SKIP="$d/skip"; ST_DEVS="$d/devices"; ST_EXIT="$d/exit"
		ST_VPN_PROBE="$JOBS_DIR/steer.vpnprobe.$1"; ST_VPN_WATCH="$JOBS_DIR/steer.vpnwatch.$1"
		STL_VPN_OUT="zm_vpn$n"; STL_VPN_DEV="zm_vpn$n"; STL_VPN_PFX="zmv$n"; ST_CUSTOM="$d/custom"
	fi
	ST_VDIR="$d"
	ST_SUB="$d/sub.txt"; ST_SUB_INFO="$d/sub.userinfo"; ST_SUB_URL="$d/sub.url"; ST_SUB_TITLE="$d/sub.title"
	ST_SUB_NODE="$d/sub.node"; ST_SUB_EXCL="$d/sub.exclude"; ST_SUB_HIDE="$d/sub.hidden"; ST_SUB_NODES="$d/sub.nodes"
	ST_SUB_FELL="$d/sub.node.fell"; ST_NODE_POL="$d/node.pol"; ST_SUB_HOME="$d/sub.node.home"
	ST_SUB_PICK="$d/sub.pick"; ST_LAT_MODE="$d/lat.mode"; ST_SUB_PING="$d/sub.ping"; ST_SUB_ORDER="$d/sub.order"
	STL_VPN_DEVS="$STL_VPN_DEV ${STL_VPN_PFX}_vless ${STL_VPN_PFX}_hy2 ${STL_VPN_PFX}_trojan ${STL_VPN_PFX}_ss ${STL_VPN_PFX}_socks ${STL_VPN_PFX}_http ${STL_VPN_PFX}_vmess"
}
_st_sec_with() {
	local _sw_was="$ST_SEC" _sw_rc
	_st_bind "$1"; shift
	"$@"; _sw_rc=$?
	_st_bind "$_sw_was"
	return $_sw_rc
}
_st_secs() { [ -s "$ST_SEC_LIST" ] || return 0; grep -E '^s[2-9]$' "$ST_SEC_LIST" | while read -r _s; do [ -d "$ST_SEC_DIR/$_s" ] && echo "$_s"; done; }
_st_sec_ok() { case "$1" in s[2-9]) [ -d "$ST_SEC_DIR/$1" ] ;; *) return 1 ;; esac; }
_st_sec_kind() { local k=""; [ -f "$ST_SEC_DIR/$1/kind" ] && read -r k < "$ST_SEC_DIR/$1/kind"; case "$k" in vpn|iface) echo "$k" ;; *) echo warp ;; esac; }
_st_sec_iface() { local k=""; [ -f "$ST_SEC_DIR/$1/iface" ] && read -r k < "$ST_SEC_DIR/$1/iface"; printf '%s' "$k"; }
_st_sec_name() {
	local f="$ST_SEC_DIR/$1/name" v=""
	case "$1" in ''|main) f="$ST_SEC_DIR/main.name" ;; esac
	[ -f "$f" ] && read -r v < "$f"
	[ -n "$v" ] || case "$1" in ''|main) v="Основная" ;; *) v="Секция ${1#s}" ;; esac
	printf '%s' "$v"
}
_st_sec_out() {
	case "$(_st_sec_kind "$1")" in
		vpn) echo "zm_vpn${1#s}" ;;
		iface) echo "zm_if${1#s}" ;;
		*) echo "$STL_WARP_OUT" ;;
	esac
}
_zm_tun_kind() {
	local d
	[ -n "$1" ] && [ "$1" != loopback ] && [ "$1" != "$TSC_NET" ] || return 1
	_awg_is_steer "$1" && return 1
	case "$(uci -q get "network.$1.proto")" in
		amneziawg) echo awg ;;
		wireguard) echo wg ;;
		pptp) echo pptp ;;
		l2tp) echo l2tp ;;
		sstp) echo sstp ;;
		openvpn) echo ovpn ;;
		none)
			d="$(uci -q get "network.$1.device")"
			case "$d" in ''|@*|br-*|lo|tailscale*|zm*|eth*|lan*|wan*|wlan*|phy*|bond*|veth*) return 1 ;; esac
			case "$d" in tun*|tap*|wg*|awg*|ovpn*|ppp*) echo tun; return 0 ;; esac
			case "$(cat "/sys/class/net/$d/type" 2>/dev/null)" in 65534|512|776) echo tun ;; *) return 1 ;; esac ;;
		*) return 1 ;;
	esac
}
_zm_tun_label() { case "$1" in awg) echo AmneziaWG ;; wg) echo WireGuard ;; pptp) echo PPTP ;; l2tp) echo L2TP ;; sstp) echo SSTP ;; ovpn) echo OpenVPN ;; *) echo "туннель" ;; esac; }
_zm_tun_dev() {
	local d p
	d="$(ifstatus "$1" 2>/dev/null | jsonfilter -e '@.l3_device' 2>/dev/null)"
	if [ -z "$d" ]; then
		p="$(uci -q get "network.$1.proto")"
		case "$p" in
			pptp|l2tp|sstp) d="$p-$1" ;;
			amneziawg|wireguard) d="$1" ;;
			*) d="$(uci -q get "network.$1.device")"; case "$d" in @*) d="" ;; esac ;;
		esac
	fi
	printf '%s' "$d" | grep -E '^[A-Za-z0-9_.-]{1,15}$'
}
_zm_tun_up() { local d; d="$(_zm_tun_dev "$1")" && [ -d "/sys/class/net/$d" ] && [ "$(cat "/sys/class/net/$d/operstate" 2>/dev/null)" != down ]; }
_zm_tun_age() {
	local t
	t="$({ awg show "$1" latest-handshakes || wg show "$1" latest-handshakes; } 2>/dev/null | awk '$2 > mx { mx = $2 } END { if (mx > 0) print mx }')"
	[ -n "$t" ] && echo $(( $(date +%s) - t ))
}
_zm_tun_peer() { uci -q -X show network | sed -n -e "s/^network\.\([^.=]*\)=amneziawg_$1\$/\1/p" -e "s/^network\.\([^.=]*\)=wireguard_$1\$/\1/p" | head -n1; }
_zm_tun_json() {
	local i="$1" k d up=false alive=false age="" ep="" warp=false route=false p port
	k="$(_zm_tun_kind "$i")" || k=""
	d="$(_zm_tun_dev "$i")"
	[ -n "$d" ] && [ -d "/sys/class/net/$d" ] && [ "$(cat "/sys/class/net/$d/operstate" 2>/dev/null)" != down ] && up=true
	case "$k" in
		awg|wg)
			p="$(_zm_tun_peer "$i")"
			[ "$up" = true ] && age="$(_zm_tun_age "$d")"
			[ -n "$age" ] && [ "$age" -lt 180 ] && alive=true
			ep="$(uci -q get "network.$p.endpoint_host")"; port="$(uci -q get "network.$p.endpoint_port")"; ep="$ep${ep:+${port:+:$port}}"
			[ -n "$p" ] && [ "$(uci -q get "network.$p.public_key")" = "$AWG_WARP_PEER" ] && warp=true
			[ -n "$p" ] && [ "$(uci -q get "network.$p.route_allowed_ips")" = 1 ] && route=true ;;
		pptp|l2tp|sstp)
			alive="$up"
			ep="$(uci -q get "network.$i.server")"
			[ "$(uci -q get "network.$i.defaultroute")" = 0 ] || route=true ;;
		*) alive="$up" ;;
	esac
	printf '{"name":"%s","kind":"%s","label":"%s","dev":"%s","up":%s,"alive":%s,"hs_age":"%s","endpoint":"%s","warp":%s,"route_all":%s,"enabled":%s,"zone":"%s","forkozz":%s,"failed":%s}' \
		"$(esc "$i")" "$k" "$(esc "$(_zm_tun_label "$k")")" "$(esc "$d")" "$up" "$alive" "$age" "$(esc "$ep")" "$warp" "$route" \
		"$([ "$(uci -q get "network.$i.auto")" = 0 ] && echo false || echo true)" "$(esc "$(_zm_zone_of_net "$i")")" \
		"$([ -n "$d" ] && _awg_fk_live "$d" && echo true || echo false)" "${2:-false}"
}
steer_tun_list() {
	local n sep=""
	printf '{"tuns":['
	for n in $(uci -q -X show network | sed -n 's/^network\.\([^.=]*\)=interface$/\1/p'); do
		_zm_tun_kind "$n" >/dev/null || continue
		printf '%s%s' "$sep" "$(_zm_tun_json "$n")"
		sep=","
	done
	printf '],"main":"%s"}\n' "$(esc "$(_st_main_iface)")"
}
_st_tun_live() { _zm_tun_kind "$1" >/dev/null && _zm_tun_dev "$1" >/dev/null; }
_st_main_iface() { local k=""; [ -f "$ST_DIR/exit.iface" ] && read -r k < "$ST_DIR/exit.iface"; printf '%s' "$k"; }
_st_main_tun() { [ "$(cat "$ST_DIR/exit" 2>/dev/null)" = iface ] && ! _st_sec_off main && _st_tun_live "$(_st_main_iface)" && _st_sec_with main _st_work_main && _st_main_iface; }
_st_tun_ifaces() { { _st_main_tun && echo; _st_secs_ifaces; } | grep . | awk '!x[$0]++'; }
_st_tun_check() {
	local nm="$1" i="$2" d tr ip
	d="$(_zm_tun_dev "$i")"
	if [ -z "$d" ] || [ ! -d "/sys/class/net/$d" ]; then
		echo "[FAIL] $nm · $i: туннель не подключён — подключите его в Сеть → Интерфейсы"
		return 1
	fi
	tr="$(curl -s --interface "$d" --connect-timeout 5 --max-time 10 https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null)"
	ip="$(printf '%s\n' "$tr" | sed -n 's/^ip=//p')"
	if [ -n "$ip" ]; then echo "[ OK ] $nm · $i: трафик идёт (выход $ip)"; return 0; fi
	case "$(_zm_tun_kind "$i")" in
		awg) echo "[FAIL] $nm · $i: трафик через туннель не идёт — почините его на вкладке AmneziaWG" ;;
		*) echo "[FAIL] $nm · $i: трафик через туннель не идёт — проверьте подключение в Сеть → Интерфейсы" ;;
	esac
	return 1
}
ST_TUN_HOOK="/etc/hotplug.d/iface/95-zm-steer"
_st_tun_hook() {
	local i s w=""
	for i in $({ [ "$(cat "$ST_DIR/exit" 2>/dev/null)" = iface ] && _st_main_iface && echo; for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = iface ] && ! _st_sec_off "$s" && _st_sec_iface "$s" && echo; done; } | grep . | awk '!x[$0]++'); do
		case "$(_zm_tun_kind "$i")" in ''|awg|wg) ;; *) w="$w $i" ;; esac
	done
	if [ -z "$w" ]; then rm -f "$ST_DIR/tun.watch" "$ST_TUN_HOOK"; return 0; fi
	mkdir -p "$ST_DIR" "${ST_TUN_HOOK%/*}"
	printf '%s\n' $w > "$ST_DIR/tun.watch"
	[ -s "$ST_TUN_HOOK" ] && grep -q 'tun_up' "$ST_TUN_HOOK" && return 0
	cat > "$ST_TUN_HOOK" <<'ZM_TUN_HOOK_EOF'
#!/bin/sh
[ "$ACTION" = ifup ] || exit 0
[ -n "$INTERFACE" ] && grep -qx "$INTERFACE" /etc/zm-steer/tun.watch 2>/dev/null || exit 0
[ -x /opt/zapret-manager-luci/backend.sh ] || exit 0
( sleep 5; /opt/zapret-manager-luci/backend.sh steer_action tun_up "$INTERFACE" ) >/dev/null 2>&1 &
ZM_TUN_HOOK_EOF
	chmod 755 "$ST_TUN_HOOK"
}
do_steer_tunup() {
	_st_phase rules
	rm -f "$ST_STOP_FLAG"
	_rb_say "Туннель $1 подключился — обновляем правила Steer"
	if _st_owns "steer-spec"; then _st_respec; else _st_work && _st_apply; fi
	_rb_say "Готово"
}
_st_sec_live() {
	_st_sec_off "$1" && return 1
	case "$(_st_sec_kind "$1")" in
		vpn) [ -s "$ST_SEC_DIR/$1/sub.txt" ] && _st_vpn_ok ;;
		iface) _st_tun_live "$(_st_sec_iface "$1")" ;;
		*) _st_warp_on ;;
	esac
}
_st_sec_work() { _st_sec_with "$1" _st_work; }
_st_secs_work() { local s; for s in $(_st_secs); do _st_sec_live "$s" && _st_sec_work "$s" && return 0; done; return 1; }
_st_secs_vpn() { local s; for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = vpn ] && _st_sec_live "$s" && _st_sec_work "$s" && echo "$s"; done; }
_st_secs_warp() { local s; for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = warp ] && _st_sec_work "$s" && return 0; done; return 1; }
_st_secs_ifaces() { local s; for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = iface ] && _st_sec_live "$s" && _st_sec_work "$s" && _st_sec_iface "$s" && echo; done | grep . | awk '!x[$0]++'; }
_st_vpn_any() { _st_sec_with main _st_use_vpn && return 0; [ -n "$(_st_secs_vpn)" ]; }
_st_sec_vpn_json() {
	local has=false key="" node=""
	[ -s "$ST_SUB" ] && has=true
	node="$(cat "$ST_SUB_NODE" 2>/dev/null)"
	printf '{"has":%s,"url":%s,"label":"%s","pinned":"%s","state":%s}' "$has" "$([ -s "$ST_SUB_URL" ] && echo true || echo false)" "$(esc "$(_st_sub_label)")" "$(esc "$node")" "$(_st_vpn_json)"
}
_st_secs_json() {
	local s sep="" k i lv sel vpn ifs age fl
	for s in $(_st_secs); do
		k="$(_st_sec_kind "$s")"; i="$(_st_sec_iface "$s")"
		lv=false; _st_sec_live "$s" && lv=true
		sel="$(_st_sec_with "$s" _st_sel_raw | awk '{ printf "%s\"%s\"", (n++ ? "," : ""), $0 }')"
		vpn=null; ifs=null
		[ "$k" = vpn ] && vpn="$(_st_sec_with "$s" _st_sec_vpn_json)"
		if [ "$k" = iface ] && [ -n "$i" ]; then
			fl=false; [ "$lv" = true ] && _st_owns "steer-spec" && _st_sec_with "$s" stl_state iface && [ "$STL_FAILED" = true ] && fl=true
			ifs="$(_zm_tun_json "$i" "$fl")"
		fi
		printf '%s{"id":"%s","name":"%s","kind":"%s","iface":"%s","live":%s,"off":%s,"services":[%s],"devices":[%s],"vpn":%s,"ifs":%s}' "$sep" "$s" "$(esc "$(_st_sec_name "$s")")" "$k" "$(esc "$i")" "$lv" "$(_st_sec_off "$s" && echo true || echo false)" "$sel" "$(_st_sec_with "$s" _st_devs_json)" "$vpn" "$ifs"
		sep=","
	done
}
_st_secs_url() { local s; for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = vpn ] && [ -s "$ST_SEC_DIR/$s/sub.url" ] && echo "$s"; done; }
do_steer_sub_update_all() {
	local s rc=0
	if [ -s "$ST_SUB_URL" ]; then do_steer_sub_update auto || rc=1; fi
	for s in $(_st_secs_url); do
		_rb_say "Секция «$(_st_sec_name "$s")»"
		_st_sec_with "$s" do_steer_sub_update auto || rc=1
	done
	return $rc
}
_st_secs_ping_tick() {
	local s iv
	for s in $(_st_secs_vpn); do
		iv="$(_st_sec_with "$s" _st_pick_iv)"
		[ -f "$ST_SEC_DIR/$s/sub.ping" ] && [ -z "$(find "$ST_SEC_DIR/$s/sub.ping" -mmin +$((iv - 1)) 2>/dev/null)" ] && continue
		_st_sec_with "$s" steer_ping_tick
	done
}
_st_secs_vpn_watch() { local s; for s in $(_st_secs_vpn); do _st_sec_with "$s" _st_vpn_watch; done; }
_st_vpn_devs_all() { local s; _st_sec_with main eval 'echo $STL_VPN_DEVS'; for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = vpn ] && _st_sec_with "$s" eval 'echo $STL_VPN_DEVS'; done; }
_st_feats_all() { local s; { _st_sec_with main _st_use_vpn && _st_sec_with main _st_sub_feats; for s in $(_st_secs_vpn); do _st_sec_with "$s" _st_sub_feats; done; } | tr ' ' '\n' | grep . | awk '!x[$0]++' | tr '\n' ' '; }
_st_sec_new_id() { local n=2; while [ "$n" -le 9 ]; do [ -d "$ST_SEC_DIR/s$n" ] || { echo "s$n"; return 0; }; n=$((n + 1)); done; return 1; }
_st_sec_count() { _st_secs | grep -c .; }
_st_sec_vpn_count() { local n=0 s; _st_sec_with main _st_use_vpn && n=1; for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = vpn ] && n=$((n + 1)); done; echo "$n"; }

_st_ping_iv1() { [ "$(_st_pick)" = ping ] && [ -s "$ST_SUB" ] && _st_pick_iv; }
_st_ping_iv_any() {
	local s
	{ _st_sec_with main _st_ping_iv1; for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = vpn ] && _st_sec_with "$s" _st_ping_iv1; done; } | sort -n | head -n1
}
_st_ping_cron() {
	local iv spec want="" had=""
	grep -qF "$ST_PING_TAG" "$CRON_FILE" 2>/dev/null && had=1
	iv="$(_st_ping_iv_any)"
	if [ -n "$iv" ] && _st_installed; then
		case "$iv" in 60) spec="7 * * * *" ;; 180) spec="7 */3 * * *" ;; *) spec="*/$iv * * * *" ;; esac
		want="$spec /opt/zapret-manager-luci/backend.sh steer_action sub_ping_tick x >/dev/null 2>&1 $ST_PING_TAG"
		grep -qxF "$want" "$CRON_FILE" 2>/dev/null && return 0
	fi
	[ -z "$want" ] && [ -z "$had" ] && return 0
	mkdir -p "$(dirname "$CRON_FILE")"; touch "$CRON_FILE"
	sed -i "\\|$ST_PING_TAG|d" "$CRON_FILE"
	[ -n "$want" ] && echo "$want" >> "$CRON_FILE"
	/etc/init.d/cron enable >/dev/null 2>&1
	/etc/init.d/cron restart >/dev/null 2>&1
	return 0
}

_st_ping_measure() {
	local t dir hid i proto pidx fidx name rest p hp k n=0 hy=0 f ms j tab kd
	[ -s "$ST_SUB" ] && _st_vpn_ok && t="$(_st_nodes)" || return 1
	_zm_has curl || return 1
	tab="$(printf '\t')"
	_st_hp_build
	hid=" $(cut -f1,5 "$t" | _zm_excl_hits "$ST_SUB_EXCL" "$ST_SUB_HIDE" | tr '\n' ' ') "
	dir="$ST_RUN/ping.$$"; rm -rf "$dir"; mkdir -p "$dir"
	while IFS="$tab" read -r i proto pidx fidx name rest; do
		case "$i" in ''|*[!0-9]*) continue ;; esac
		case "$hid" in *" $i "*) continue ;; esac
		printf '%s\n' "$name" > "$dir/$i.n"
		if [ "$proto" = hysteria2 ]; then echo "hy $fidx" > "$dir/$i.k"; continue; fi
		p="$(_stl_mod_of "$proto")"
		hp="$(awk -F'\t' -v m="$p" -v n="$fidx" '$1 == m && $2 == n { print $3, $4; exit }' "$ST_SUB_NODES.hp" 2>/dev/null)"
		[ -n "$hp" ] || { echo none > "$dir/$i.k"; continue; }
		echo "$hp" > "$dir/$i.k"
		echo "$p $fidx" > "$dir/$i.m"
		_st_tcp_one "${hp% *}" "${hp#* }" 3 "$dir/$i" &
		n=$((n + 1)); [ $((n % 16)) = 0 ] && wait
	done < "$t"
	wait
	n=0
	for f in "$dir"/*.k; do
		[ -f "$f" ] || continue
		i="${f##*/}"; i="${i%.k}"; read -r k < "$f"
		case "$k" in hy*|none) continue ;; esac
		[ -s "$dir/$i" ] && continue
		_st_tcp_one "${k% *}" "${k#* }" 6 "$dir/$i" &
		n=$((n + 1)); [ $((n % 16)) = 0 ] && wait
	done
	wait
	if stl_has hy2; then
		for f in "$dir"/*.k; do
			[ -f "$f" ] || continue
			read -r k < "$f"
			case "$k" in hy*) ;; *) continue ;; esac
			[ "$hy" -ge 6 ] && break
			hy=$((hy + 1))
			i="${f##*/}"; i="${i%.k}"
			( j="$(stl_probe "$ST_SUB" hysteria2 "${k#hy }")"
			  if [ "$(printf '%s' "$j" | jsonfilter -e '@.results[0].ok' 2>/dev/null)" = true ]; then
				ms="$(printf '%s' "$j" | jsonfilter -e '@.results[0].handshake_ms' 2>/dev/null)"
				case "$ms" in ''|*[!0-9]*|0) ms="$(printf '%s' "$j" | jsonfilter -e '@.results[0].ttfb_ms' 2>/dev/null)" ;; esac
				case "$ms" in ''|*[!0-9]*|0) ms=1 ;; esac
				echo "$ms" > "$dir/$i"
			  else : > "$dir/$i.dead"; fi ) &
			[ $((hy % 2)) = 0 ] && wait
		done
		wait
	fi
	if [ "$(_st_lat_mode)" = real ]; then
		for f in "$dir"/*.m; do
			[ -f "$f" ] || continue
			i="${f##*/}"; i="${i%.m}"
			[ -s "$dir/$i" ] && printf '%s %s\n' "$(cat "$dir/$i")" "$i"
		done | sort -n | head -n 8 | while read -r ms i; do echo "$i"; done > "$dir/real.list"
		if [ -n "$1" ]; then
			for f in "$dir"/*.m; do
				[ -f "$f" ] || continue
				i="${f##*/}"; i="${i%.m}"
				[ -s "$dir/$i" ] && [ "$(cat "$dir/$i.n")" = "$1" ] || continue
				grep -qx "$i" "$dir/real.list" || echo "$i" >> "$dir/real.list"
				break
			done
		fi
		n=0
		while read -r i; do
			[ -n "$i" ] || continue
			read -r p k < "$dir/$i.m"
			stl_has "$p" || continue
			( j="$(stl_probe "$ST_SUB" "$p" "$k")"
			  okv="$(printf '%s' "$j" | jsonfilter -e '@.results[0].ok' 2>/dev/null)"
			  if [ "$okv" = true ]; then
				ms="$(printf '%s' "$j" | jsonfilter -e '@.results[0].ttfb_ms' 2>/dev/null)"
				case "$ms" in ''|*[!0-9]*|0) ms="$(printf '%s' "$j" | jsonfilter -e '@.results[0].handshake_ms' 2>/dev/null)" ;; esac
				case "$ms" in ''|*[!0-9]*|0) ms=1 ;; esac
				echo "$ms" > "$dir/$i"; echo r > "$dir/$i.kind"
			  elif [ "$okv" = false ]; then echo b > "$dir/$i.kind"; fi ) &
			n=$((n + 1)); [ $((n % 2)) = 0 ] && wait
		done < "$dir/real.list"
		wait
		for f in "$dir"/*.m; do
			[ -f "$f" ] || continue
			i="${f##*/}"; i="${i%.m}"
			[ -s "$dir/$i" ] && [ ! -f "$dir/$i.kind" ] && echo t > "$dir/$i.kind"
		done
	fi
	for f in $(ls "$dir"/*.n 2>/dev/null | sed 's#.*/##; s#\.n$##' | sort -n); do
		read -r k < "$dir/$f.k"
		kd=""; [ -f "$dir/$f.kind" ] && read -r kd < "$dir/$f.kind"
		if [ "$kd" = b ]; then ms=0
		elif [ -s "$dir/$f" ]; then ms="$(cat "$dir/$f")"
		elif [ "$k" = none ] || { [ "${k%% *}" = hy ] && [ ! -f "$dir/$f.dead" ]; }; then ms=-1
		else ms=0; fi
		printf '%s\t%s\t%s\n' "$(cat "$dir/$f.n")" "$ms" "$kd"
	done > "$ST_SUB_PING.tmp"
	rm -rf "$dir"
	mkdir -p "$ST_DIR"
	mv -f "$ST_SUB_PING.tmp" "$ST_SUB_PING"
	[ -s "$ST_SUB_PING" ]
}

_st_ping_order() {
	local old new
	[ -s "$ST_SUB_PING" ] || return 1
	old="$(head -n1 "$ST_SUB_ORDER" 2>/dev/null)"
	ZM_CUR="${1:-$old}" awk -F'\t' -v tol="$(_st_pick_tol)" '
		{ n[NR] = $1; m[NR] = $2 + 0; if ($3 == "t" && m[NR] > 0) m[NR] += 100000 }
		END {
			c = 0
			for (i = 1; i <= NR; i++) if (m[i] > 0) a[++c] = i
			for (i = 2; i <= c; i++) { x = a[i]; j = i - 1; while (j > 0 && m[a[j]] > m[x]) { a[j + 1] = a[j]; j-- } a[j + 1] = x }
			cur = ENVIRON["ZM_CUR"]; h = 0
			if (c && cur != "") for (i = 1; i <= c; i++) if (n[a[i]] == cur && m[a[i]] <= m[a[1]] + tol) { h = a[i]; break }
			if (h) print n[h]
			for (i = 1; i <= c; i++) if (a[i] != h) print n[a[i]]
			for (i = 1; i <= NR; i++) if (m[i] < 0) print n[i]
			for (i = 1; i <= NR; i++) if (m[i] == 0) print n[i]
		}' "$ST_SUB_PING" > "$ST_SUB_ORDER.tmp"
	mv -f "$ST_SUB_ORDER.tmp" "$ST_SUB_ORDER"
	new="$(head -n1 "$ST_SUB_ORDER")"
	[ "$new" != "$old" ]
}

_st_ping_line() { awk -F'\t' -v w="$1" '$1 == w { print $2; exit }' "$ST_SUB_PING" 2>/dev/null; }

_st_ping_refresh() {
	local cur="" total ok best ms blk
	_rb_say "Замеряем пинг узлов подписки"
	_st_owns "steer-spec" && stl_running && stl_state vpn >/dev/null 2>&1 && [ "$STL_UP" = true ] && cur="$(_st_active_key)"
	if ! _st_ping_measure "$cur"; then _rb_warn "Пинг замерить не удалось — узлы идут по порядку подписки"; rm -f "$ST_SUB_ORDER"; return 1; fi
	total="$(grep -c . "$ST_SUB_PING")"; ok="$(awk -F'\t' '$2 > 0' "$ST_SUB_PING" | grep -c .)"
	blk="$(awk -F'\t' '$3 == "b"' "$ST_SUB_PING" | grep -c .)"
	_st_ping_order "$cur"
	best="$(head -n1 "$ST_SUB_ORDER")"; ms="$(_st_ping_line "$best")"
	[ "$blk" -gt 0 ] && echo "   • Порт открыт, но трафик не идёт (похоже, блокирует провайдер): $blk — эти узлы в конце"
	if [ "$ok" -gt 0 ]; then echo "   ✓ Отвечают $ok из $total, первым — «$best» (${ms} мс)"
	else _rb_warn "Ни один узел не ответил на пинг — ядро steer переберёт их само по порядку"; fi
	return 0
}

_st_ping_ready() {
	[ "$(_st_pick)" = ping ] && [ -s "$ST_SUB" ] && [ ! -s "$ST_SUB_NODE" ] && _st_use_vpn && _st_installed &&
		[ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] && _st_owns "steer-spec" && _st_work_main
}

steer_ping_tick() {
	local lk="$ST_RUN/ping.lock" cur="" best
	_st_ping_ready || return 0
	_st_running && return 0
	mkdir -p "$ST_RUN"
	mkdir "$lk" 2>/dev/null || { [ -n "$(find "$lk" -maxdepth 0 -mmin +20 2>/dev/null)" ] && rmdir "$lk" 2>/dev/null; return 0; }
	stl_running && stl_state vpn >/dev/null 2>&1 && [ "$STL_UP" = true ] && cur="$(_st_active_key)"
	if _st_ping_measure "$cur" && _st_ping_order "$cur" && ! _st_running && _st_ping_ready; then
		best="$(head -n1 "$ST_SUB_ORDER")"
		if _st_spec_quick >/dev/null 2>&1; then logger -t zapret-manager "Steer: по пингу первым стал узел «$best» ($(_st_ping_line "$best") мс)"
		else logger -t zapret-manager "Steer: узел по пингу «$best» применить не удалось"; fi
	fi
	rmdir "$lk" 2>/dev/null
	return 0
}

do_steer_ping() {
	_st_phase sub
	rm -f "$ST_STOP_FLAG"
	_st_ping_cron
	if [ "$(_st_pick)" != ping ]; then
		rm -f "$ST_SUB_ORDER"
		_rb_say "Автовыбор: первый рабочий узел по порядку подписки"
	else
		_rb_say "Автовыбор по пингу: замер раз в $(_st_pick_iv) мин, допуск $(_st_pick_tol) мс"
		_st_ping_refresh
	fi
	if [ -s "$ST_SUB_NODE" ]; then
		_rb_say "Готово. Сейчас закреплён узел $(_st_node_label) — автовыбор заработает, когда выберете «Авто»"
		return 0
	fi
	if _st_use_vpn && _st_installed && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] && _st_work; then
		do_steer_switch -; return $?
	fi
	_rb_say "Готово: сохранено — применится, когда сервисы пойдут через VPN"
}

steer_sub_probe() {
	local out t p f
	case "$1" in ''|*[!0-9]*) echo '{"ok":false,"error":"неверный номер узла"}'; return 1 ;; esac
	[ -s "$ST_SUB" ] && _st_vpn_ok && t="$(_st_nodes)" || { echo '{"ok":false,"error":"подписки нет"}'; return 1; }
	set -- $(awk -F'\t' -v g="$1" '$1 == g { print $2, $4; exit }' "$t")
	[ -n "$1" ] || { echo '{"ok":false,"error":"узла нет в подписке"}'; return 1; }
	p="$(_stl_mod_of "$1")"; f="$2"
	stl_has "$p" || { echo '{"ok":false,"error":"модуль ядра steer для этого протокола не установлен"}'; return 1; }
	out="$(stl_probe "$ST_SUB" "$p" "$f")"
	case "$out" in '{'*) printf '%s\n' "$out" ;; *) echo '{"ok":false,"error":"проверка не удалась"}' ;; esac
}

_st_sec_label_ok() { printf '%s' "$1" | tr -d '"\\\000-\037' | cut -c1-120 | sed 's/^[[:space:]]*//; s/[[:space:]]*$//'; }
steer_sec_action() {
	local action="$1" mode="$2" id k i n d
	case "$action" in
		sec_add)
			[ -z "$(_st_blocker)" ] || { echo '{"error":"ядро steer сейчас настраивает не Zapret Manager"}'; return 1; }
			k="${mode%%|*}"; mode="${mode#*|}"; i="${mode%%|*}"; n="${mode#*|}"
			[ "$(_st_sec_count)" -lt $((ST_SEC_MAX - 1)) ] || { printf '{"error":"%s"}\n' "$(esc "секций может быть не больше $ST_SEC_MAX")"; return 1; }
			_st_sec_kind_check "$k" "$i" "" || return 1
			id="$(_st_sec_new_id)" || { echo '{"error":"нет свободного номера секции"}'; return 1; }
			d="$ST_SEC_DIR/$id"
			mkdir -p "$d"
			echo "$k" > "$d/kind"
			[ "$k" = iface ] && echo "$i" > "$d/iface"
			n="$(_st_sec_label_ok "$n")"; [ -n "$n" ] && printf '%s\n' "$n" > "$d/name"
			{ _st_secs; echo "$id"; } | awk '!x[$0]++' > "$ST_SEC_LIST.tmp" && mv -f "$ST_SEC_LIST.tmp" "$ST_SEC_LIST"
			printf '{"ok":true,"id":"%s"}\n' "$id" ;;
		sec_name)
			id="${mode%%|*}"; n="$(_st_sec_label_ok "${mode#*|}")"
			if [ "$id" = main ]; then d="$ST_SEC_DIR/main.name"; mkdir -p "$ST_SEC_DIR"
			else _st_sec_ok "$id" || { echo '{"error":"нет такой секции — обновите страницу"}'; return 1; }; d="$ST_SEC_DIR/$id/name"; fi
			if [ -n "$n" ]; then printf '%s\n' "$n" > "$d"; else rm -f "$d"; fi
			printf '{"ok":true}\n' ;;
		sec_kind)
			_st_running && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			[ -z "$(_st_blocker)" ] || { echo '{"error":"ядро steer сейчас настраивает не Zapret Manager"}'; return 1; }
			id="${mode%%|*}"; mode="${mode#*|}"; k="${mode%%|*}"; i="${mode#*|}"; [ "$i" = "$mode" ] && i=""
			_st_sec_ok "$id" || { echo '{"error":"нет такой секции — обновите страницу"}'; return 1; }
			_st_sec_kind_check "$k" "$i" "$id" || return 1
			d="$ST_SEC_DIR/$id"
			echo "$k" > "$d/kind"
			if [ "$k" = iface ]; then echo "$i" > "$d/iface"; else rm -f "$d/iface"; fi
			_st_ping_cron
			if _st_installed && [ ! -f "$ST_OFF" ] && _st_owns "steer-spec" && _st_sec_work "$id"; then job_start steer do_steer_apply
			else printf '{"ok":true,"saved":true}\n'; fi ;;
		sec_off)
			_st_running && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			[ -z "$(_st_blocker)" ] || { echo '{"error":"ядро steer сейчас настраивает не Zapret Manager"}'; return 1; }
			id="${mode%%|*}"; k="${mode#*|}"
			case "$k" in 0|1) ;; *) echo '{"error":"неизвестное значение"}'; return 1 ;; esac
			[ -n "$(_st_secs)" ] || { echo '{"error":"секций нет — выключите Steer целиком"}'; return 1; }
			[ "$id" = main ] || _st_sec_ok "$id" || { echo '{"error":"нет такой секции — обновите страницу"}'; return 1; }
			if [ "$id" = main ]; then d="$ST_SEC_DIR/main.off"; else d="$ST_SEC_DIR/$id/off"; fi
			if [ "$k" = 1 ]; then
				n=0
				for i in main $(_st_secs); do [ "$i" = "$id" ] || _st_sec_off "$i" || n=$((n + 1)); done
				[ "$n" -gt 0 ] || { echo '{"error":"это последняя включённая секция — чтобы выключить всё, нажмите «Выключить Steer целиком»"}'; return 1; }
				[ -f "$d" ] && { printf '{"ok":true,"saved":true}\n'; return 0; }
				mkdir -p "$ST_SEC_DIR"; : > "$d"
				logger -t zapret-manager "Steer: секция «$(_st_sec_name "$id")» выключена"
			else
				[ -f "$d" ] || { printf '{"ok":true,"saved":true}\n'; return 0; }
				rm -f "$d"
				logger -t zapret-manager "Steer: секция «$(_st_sec_name "$id")» включена"
			fi
			_st_ping_cron
			if _st_installed && [ ! -f "$ST_OFF" ] && _st_owns "steer-spec"; then job_start steer do_steer_apply
			elif _st_installed && [ ! -f "$ST_OFF" ] && [ "$k" = 0 ]; then job_start steer do_steer_apply
			else printf '{"ok":true,"saved":true}\n'; fi ;;
		sec_del)
			_st_running && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			[ -z "$(_st_blocker)" ] || { echo '{"error":"ядро steer сейчас настраивает не Zapret Manager"}'; return 1; }
			id="$mode"
			_st_sec_ok "$id" || { echo '{"error":"нет такой секции — обновите страницу"}'; return 1; }
			k=""; _st_sec_work "$id" && k=1
			_st_secs | grep -vx "$id" > "$ST_SEC_LIST.tmp"; mv -f "$ST_SEC_LIST.tmp" "$ST_SEC_LIST"
			[ -s "$ST_SEC_LIST" ] || { rm -f "$ST_SEC_LIST"; [ -f "$ST_SEC_DIR/main.off" ] && { rm -f "$ST_SEC_DIR/main.off"; k=1; }; }
			rm -rf "${ST_SEC_DIR:?}/$id"
			rm -f "$JOBS_DIR/steer.vpnprobe.$id" "$JOBS_DIR/steer.vpnwatch.$id" "$JOBS_DIR/steer.hometick.$id" "$JOBS_DIR/steer.holdlog.$id"
			_st_ping_cron
			if [ -n "$k" ] && _st_installed && [ ! -f "$ST_OFF" ] && _st_owns "steer-spec"; then job_start steer do_steer_apply
			else
				_st_owns "steer-spec" && _st_secs_fw >/dev/null 2>&1
				printf '{"ok":true,"saved":true}\n'
			fi ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
}
_st_sec_kind_check() {
	local k="$1" i="$2" id="$3" n
	case "$k" in
		warp) ;;
		vpn)
			n="$(_st_sec_vpn_count)"
			[ -n "$id" ] && [ "$(_st_sec_kind "$id")" = vpn ] && n=$((n - 1))
			[ "$n" -lt "$ST_SEC_VPN_MAX" ] || { printf '{"error":"%s"}\n' "$(esc "VPN-секций может быть не больше $ST_SEC_VPN_MAX — каждая держит свой туннель и память роутера")"; return 1; } ;;
		iface)
			printf '%s' "$i" | grep -qE '^[A-Za-z0-9_]{1,15}$' || { echo '{"error":"выберите туннель"}'; return 1; }
			_awg_is_steer "$i" && { echo '{"error":"это туннель самого Steer — выберите свой туннель"}'; return 1; }
			_zm_tun_kind "$i" >/dev/null || { echo '{"error":"такого туннеля нет — подойдут AmneziaWG, WireGuard, PPTP, L2TP, SSTP и OpenVPN"}'; return 1; }
			_zm_tun_dev "$i" >/dev/null || { echo '{"error":"у туннеля ещё нет устройства — подключите его в Сеть → Интерфейсы и выберите снова"}'; return 1; } ;;
		*) echo '{"error":"неизвестный способ подключения"}'; return 1 ;;
	esac
	return 0
}

steer_action() {
	local action="$1" mode="$2" w d
	case "$action" in sec_add|sec_name|sec_kind|sec_del|sec_off) steer_sec_action "$action" "$mode"; return ;; esac
	case "$mode" in
		"~s"[2-9]"~"*)
			w="${mode#?}"; w="${w%%\~*}"; mode="${mode#?$w?}"
			_st_sec_ok "$w" || { echo '{"error":"нет такой секции — обновите страницу"}'; return 1; }
			case "$action" in
				lists|devs_set|list_set|list_get|list_reset|svc_find|svc_dom|sub_status|sub_probe|sub_tcp|lat_mode|node_pol|sub_home|sub_links_get|sub_set|sub_links|sub_update|sub_remove|sub_node|sub_filter|sub_hide|sub_pick|sub_ping) ;;
				*) echo '{"error":"это действие общее для всех секций"}'; return 1 ;;
			esac
			( _st_bind "$w"; steer_action "$action" "$mode" ); return $? ;;
	esac
	case "$action" in diag|wfix_tick|explain) ;; *) rm -f "$ST_VPN_PROBE" ;; esac
	case "$action" in
		install|apply|start|stop|remove|warp_restart|warp_endpoint|warp_recreate|lists|engine|warp_setup|warp_fix|warp_fixkeys|warp_own|warp_mode|warp_iface|ext_pick|warp_pick|warp_remove|onfail|dnsmode|realip|cttl|lan_set)
			_st_running && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			case "$action" in warp_iface|ext_pick|warp_restart|warp_mode|warp_own) _job_alive awg && { echo '{"error":"на вкладке AmneziaWG идёт операция — дождитесь её окончания"}'; return 1; } ;; esac
			[ "$action" = remove ] || [ -z "$(_st_blocker)" ] || { echo '{"error":"ядро steer сейчас настраивает не Zapret Manager — панель его не трогает"}'; return 1; }
			case "$action" in
				warp_endpoint|warp_recreate|warp_fix|warp_fixkeys|warp_pick)
					_st_warp_ext && { echo '{"error":"в режиме «Интерфейс AmneziaWG» туннель чинится на вкладке AmneziaWG или кнопкой «Подобрать точку входа»"}'; return 1; }
					_st_warp_own && { echo '{"error":"в режиме «Свой конфиг» ключи и точку входа задаёт ваш конфиг — замените его или вернитесь к автоматическому WARP"}'; return 1; } ;;
			esac
			case "$action" in
				warp_own)
					if [ -n "$mode" ]; then
						printf '%s\n' "$mode" | grep -qi '^[[:space:]]*\[interface\]' || { echo '{"error":"в конфиге нет секции [Interface]"}'; return 1; }
						printf '%s\n' "$mode" | grep -qi '^[[:space:]]*\[peer\]' || { echo '{"error":"в конфиге нет секции [Peer]"}'; return 1; }
						printf '%s\n' "$mode" | grep -qi '^[[:space:]]*endpoint[[:space:]]*=' || { echo '{"error":"в конфиге нет Endpoint — адреса сервера"}'; return 1; }
						mkdir -p "$ST_DIR"
						( umask 077; printf '%s\n' "$mode" | tr -d '\r' > "$ST_DIR/warp.pending" )
						chmod 600 "$ST_DIR/warp.pending"
						if ! _st_own_conf_ok "$ST_DIR/warp.pending"; then
							rm -f "$ST_DIR/warp.pending"
							echo '{"error":"в конфиге нет PrivateKey, Address, PublicKey или Endpoint (адрес:порт) — прежний туннель не тронут"}'
							return 1
						fi
					else
						_st_own_saved || { echo '{"error":"вставьте конфиг WARP"}'; return 1; }
					fi
					job_start steer do_steer_warp_own ;;
				warp_mode)
					[ "$mode" = auto ] || { echo '{"error":"неизвестный режим"}'; return 1; }
					job_start steer do_steer_warp_auto ;;
				warp_remove)
					_st_installed || { echo '{"error":"Steer не установлен"}'; return 1; }
					_job_alive awg && { echo '{"error":"на вкладке AmneziaWG идёт операция — дождитесь её окончания"}'; return 1; }
					_st_warp_on || _st_warp_ext || [ -s "$ST_WARP_OWN" ] || grep -q '^net zmwarp' "$ST_OWNED" 2>/dev/null || { echo '{"error":"WARP в Steer не подключён — убирать нечего"}'; return 1; }
					case "$mode" in ''|awg) ;; *) echo '{"error":"неизвестный режим"}'; return 1 ;; esac
					job_start steer do_steer_warp_remove "$mode" ;;
				warp_iface)
					printf '%s' "$mode" | grep -qE '^[A-Za-z0-9_]{1,15}$' || { echo '{"error":"неверное имя интерфейса"}'; return 1; }
					_awg_is_steer "$mode" && { echo '{"error":"это туннель самого Steer — выберите интерфейс, созданный на вкладке AmneziaWG"}'; return 1; }
					[ "$(uci -q get "network.$mode.proto")" = amneziawg ] || { echo '{"error":"такого интерфейса AmneziaWG нет"}'; return 1; }
					job_start steer do_steer_warp_iface "$mode" ;;
				ext_pick)
					_st_warp_ext || { echo '{"error":"Steer сейчас работает не через интерфейс AmneziaWG"}'; return 1; }
					[ "$(uci -q get "network.$(_awg_peer_sec "$(_st_ext_if)").public_key")" = "$AWG_WARP_PEER" ] || { echo '{"error":"подбор точки входа есть только для туннелей WARP"}'; return 1; }
					job_start steer do_steer_ext_pick ;;
				dnsmode|realip|cttl)
					if [ "$action" = dnsmode ]; then
						case "$mode" in tun|router) ;; *) echo '{"error":"неизвестный режим"}'; return 1 ;; esac
					elif [ "$action" = cttl ]; then
						case "$mode" in 0|300|900|3600) ;; *) echo '{"error":"неизвестный срок"}'; return 1 ;; esac
					else
						case "$mode" in on|off) ;; *) echo '{"error":"неизвестный режим"}'; return 1 ;; esac
					fi
					if _st_installed && [ ! -f "$ST_OFF" ] && _st_owns "steer-spec"; then job_start steer do_steer_dnsopt "$action" "$mode"
					else _st_dnsopt_save "$action" "$mode"; printf '{"ok":true,"saved":true}\n'
					fi ;;
				lan_set)
					w=""
					for d in $(printf '%s' "$mode" | tr ',;' '  '); do
						printf '%s' "$d" | grep -qE '^([A-Za-z0-9._-]{1,15}|ppp\+)$' || { printf '{"error":"%s"}\n' "$(esc "неверное имя сети: $d")"; return 1; }
						case " $(_st_out_tun_devs | tr '\n' ' ') " in *" $d "*) printf '{"error":"%s"}\n' "$(esc "через $d уже идут сервисы Steer — одна и та же сеть не может быть и выходом, и источником")"; return 1 ;; esac
						case " $(_zm_lan_devs) " in *" $d "*) continue ;; esac
						case " $w " in *" $d "*) ;; *) w="$w $d" ;; esac
					done
					[ "$(echo $w | wc -w)" -le "$ST_LAN_MAX" ] || { echo "{\"error\":\"не больше $ST_LAN_MAX дополнительных сетей\"}"; return 1; }
					mkdir -p "$ST_DIR"
					if [ -n "$w" ]; then printf '%s\n' $w > "$ST_LAN_EXTRA"; else rm -f "$ST_LAN_EXTRA"; fi
					if _st_installed && [ ! -f "$ST_OFF" ] && _st_owns "steer-spec"; then job_start steer do_steer_lanset
					else
						[ -n "$w" ] || _st_lan_fw_drop
						printf '{"ok":true,"saved":true}\n'
					fi ;;
				onfail)
					case "$mode" in drop|direct) ;; *) echo '{"error":"неизвестный режим"}'; return 1 ;; esac
					if _st_installed && [ ! -f "$ST_OFF" ] && _st_owns "steer-spec"; then job_start steer do_steer_onfail "$mode"
					else
						mkdir -p "$ST_DIR"
						if [ "$mode" = drop ]; then echo drop > "$ST_DIR/onfail"; else rm -f "$ST_DIR/onfail"; fi
						printf '{"ok":true,"saved":true}\n'
					fi ;;
				warp_pick)
					_st_warp_on || { echo '{"error":"WARP ещё не подключён"}'; return 1; }
					case "$mode" in
						latency) job_start steer do_steer_warp_pick latency ;;
						order:*)
							mode="$(printf '%s' "${mode#order:}" | tr ',' ' ')"
							for w in $mode; do printf '%s' "$w" | grep -qE '^zmwarp[0-9]?$' || { echo '{"error":"неверное имя туннеля"}'; return 1; }; done
							[ -n "$(echo $mode)" ] || { echo '{"error":"пустой порядок туннелей"}'; return 1; }
							job_start steer do_steer_warp_pick order "$mode" ;;
						*) echo '{"error":"неизвестный режим"}'; return 1 ;;
					esac ;;
				install)       job_start steer do_steer_install ;;
				apply|start)   job_start steer do_steer_apply ;;
				stop)          job_start steer do_steer_stop ;;
				remove)        job_start steer do_steer_remove ;;
				warp_restart)  job_start steer do_steer_warp_restart ;;
				engine)        job_start steer do_steer_engine ;;
				warp_setup)    job_start steer do_steer_warp_setup ;;
				warp_fix|warp_fixkeys)
					case "$mode" in [1-9]) ;; *) echo '{"error":"неверный номер туннеля"}'; return 1 ;; esac
					[ "$mode" -le "$ST_WARP_N" ] || { echo '{"error":"неверный номер туннеля"}'; return 1; }
					if [ "$action" = warp_fixkeys ]; then job_start steer do_steer_warp_fix "$mode" keys
					else job_start steer do_steer_warp_fix "$mode"; fi ;;
				warp_endpoint) job_start steer do_steer_warp_endpoint ;;
				warp_recreate) job_start steer do_steer_warp_recreate ;;
				lists)
					_st_sel_set "$mode" || return 1
					if _st_installed && [ ! -f "$ST_OFF" ]; then job_start steer do_steer_apply
					else printf '{"ok":true,"saved":true}\n'; fi ;;
			esac
			;;
		sub_status) steer_sub_status ;;
		explain) steer_explain "$mode" ;;
		sub_auto) _st_sub_auto_set "$mode" ;;
		sub_refresh)
			_st_running && return 0
			[ -s "$ST_SUB_URL" ] || [ -n "$(_st_secs_url)" ] || return 0
			job_start steer do_steer_sub_update_all >/dev/null
			;;
		sub_probe) steer_sub_probe "$mode" ;;
		sub_tcp) steer_sub_tcp "$mode" ;;
		lat_mode)
			case "$mode" in
				real) mkdir -p "$ST_DIR"; echo real > "$ST_LAT_MODE" ;;
				fast) rm -f "$ST_LAT_MODE" ;;
				'') ;;
				*) echo '{"error":"неизвестный способ проверки"}'; return 1 ;;
			esac
			printf '{"ok":true,"mode":"%s"}\n' "$(_st_lat_mode)" ;;
		node_pol)
			case "$mode" in
				back) rm -f "$ST_NODE_POL" ;;
				switch|hold) mkdir -p "$ST_DIR"; echo "$mode" > "$ST_NODE_POL"; rm -f "$ST_SUB_HOME" ;;
				'') ;;
				*) echo '{"error":"неизвестная настройка"}'; return 1 ;;
			esac
			printf '{"ok":true,"pol":"%s"}\n' "$(_st_node_pol)" ;;
		sub_home)
			rm -f "$ST_SUB_HOME" "$ST_SUB_FELL"
			printf '{"ok":true}\n' ;;
		sub_links_get)
			[ -s "$ST_SUB" ] || { echo '{"error":"подписки нет"}'; return 1; }
			[ -s "$ST_SUB_URL" ] && { echo '{"error":"это подписка по ссылке — её серверы задаёт сервис, а не вы"}'; return 1; }
			printf '{"links":"%s"}\n' "$(esc_ml "$(grep -iE "$STL_LINK_RE" "$ST_SUB")")"
			;;
		sub_ping_tick) steer_ping_tick; _st_secs_ping_tick; printf '{"ok":true}\n' ;;
		sub_set|sub_links|sub_update|sub_remove|sub_exit|sub_node|sub_filter|sub_hide|sub_pick|sub_ping|iface_forget)
			_st_running && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			[ -z "$(_st_blocker)" ] || { echo '{"error":"ядро steer сейчас настраивает не Zapret Manager — панель его не трогает"}'; return 1; }
			steer_sub_action "$action" "$mode"
			;;
		list_get) steer_list_get "$mode" ;;
		svc_dom) steer_svc_dom "$mode" ;;
		svc_find) steer_svc_find "$mode" ;;
		svc_domflags) steer_svc_domflags ;;
		devices) steer_devices ;;
		devs_set)
			_st_running && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			[ -z "$(_st_blocker)" ] || { echo '{"error":"ядро steer сейчас настраивает не Zapret Manager — панель его не трогает"}'; return 1; }
			_st_devs_save "$mode"
			if _st_installed && [ ! -f "$ST_OFF" ] && [ "$(_st_exit)" != none ] && { _st_work || _st_owns "steer-spec"; }; then job_start steer do_steer_devs
			else printf '{"ok":true,"saved":true}\n'; fi
			;;
		catalog_refresh)
			[ -f "$ST_CAT_OFF" ] && { echo '{"error":"каталог списков выключен"}'; return 1; }
			rm -f "$ST_DIR/catalog.err"
			( _st_cat_refresh force >/dev/null 2>&1 & )
			printf '{"ok":true}\n'
			;;
		catalog_src)
			_st_running && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			mkdir -p "$ST_DIR"
			case "$mode" in
				off) touch "$ST_CAT_OFF"; printf '{"ok":true}\n'; return 0 ;;
				on) rm -f "$ST_CAT_OFF" ;;
				'') rm -f "$ST_CAT_URL" ;;
				https://*)
					case "$mode" in *[[:space:]\"\'\\\`\$\;\|\<\>]*) echo '{"error":"недопустимые символы в ссылке"}'; return 1 ;; esac
					printf '%s\n' "$mode" > "$ST_CAT_URL" ;;
				*) echo '{"error":"нужна ссылка https://…/lists.json"}'; return 1 ;;
			esac
			rm -f "$ST_DIR/catalog.err"
			_zm_run 17 _st_cat_refresh force >/dev/null 2>&1
			case $? in
				0) printf '{"ok":true}\n' ;;
				137|143) rmdir "$ST_RUN/cat.lock" 2>/dev/null; rm -f "$ST_RUN/lists.json.tmp"; echo '{"error":"каталог не успел скачаться за 17 секунд — прежний список сервисов оставлен, попробуйте позже"}'; return 1 ;;
				*) echo '{"error":"каталог по этой ссылке не скачался или в нём нет списков — прежний список сервисов оставлен"}'; return 1 ;;
			esac
			;;
		list_set|list_reset)
			_st_running && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			if [ "$action" = list_set ]; then steer_list_set "$mode"; else steer_list_reset "$mode"; fi
			;;
		halt)
			_st_running || { echo '{"error":"ничего не выполняется"}'; return 1; }
			touch "$ST_STOP_FLAG"
			printf '{"ok":true}\n'
			;;
		restart)
			_st_running && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			_st_owns "steer-spec" || { echo '{"error":"правил для Steer нет — выберите сервисы"}'; return 1; }
			[ -z "$(_st_blocker)" ] || { echo '{"error":"ядро steer сейчас настраивает не Zapret Manager — панель его не трогает"}'; return 1; }
			stl_restart || { echo '{"error":"Steer не запустился — загляните в системный журнал"}'; return 1; }
			printf '{"ok":true}\n'
			;;
		autorestart) _st_cron_set "$mode" ;;
		lan_list) steer_lan_list ;;
		tun_list) steer_tun_list ;;
		tun_up)
			printf '%s' "$mode" | grep -qE '^[A-Za-z0-9_]{1,15}$' || { echo '{"error":"неверное имя туннеля"}'; return 1; }
			_st_installed && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] || { printf '{"ok":true}\n'; return 0; }
			_st_uses_if "$mode" || { printf '{"ok":true}\n'; return 0; }
			d="$(_zm_tun_dev "$mode")" || { printf '{"ok":true}\n'; return 0; }
			grep -qF "\"device\":\"$d\"" "$STL_SPEC" 2>/dev/null && { printf '{"ok":true,"same":true}\n'; return 0; }
			_st_running && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			job_start steer do_steer_tunup "$mode" ;;
		lists_via)
			mkdir -p "$ST_DIR"
			if [ "$mode" = on ]; then touch "$ST_DIR/lists.via"; else rm -f "$ST_DIR/lists.via"; fi
			printf '{"ok":true}\n' ;;
		sub_via)
			mkdir -p "$ST_DIR"
			if [ "$mode" = on ]; then touch "$ST_SUB_VIA"; else rm -f "$ST_SUB_VIA"; fi
			printf '{"ok":true}\n' ;;
		wfix) _st_wfix_set "$mode" ;;
		wfix_tick) _st_wfix_tick; printf '{"ok":true}\n' ;;
		conns)
			stl_present && stl_running || { echo '{"error":"Steer не запущен"}'; return 1; }
			w="$(_stl_t 15 steer conns 2>/dev/null | tr -d '\n\r')"
			case "$w" in '{'*'"conns"'*) ;; *) echo '{"error":"ядро Steer не отдало список соединений — нужна версия 2.0 или новее"}'; return 1 ;; esac
			if [ "$(printf '%s' "$w" | sed 's/}, *{/}\n{/g' | wc -l)" -gt 400 ]; then
				printf '%s' "$w" | sed 's/}, *{/}\n{/g' | head -n 400 | tr '\n' ',' | sed 's/,$//'
				w="$(printf '%s' "$w" | sed -n 's/.*"total": *\([0-9][0-9]*\).*/\1/p')"
				printf '],"shown":400,"total":%s,"truncated":true}\n' "${w:-400}"
			else printf '%s\n' "$w"; fi ;;
		dnslog)
			stl_present && stl_running || { echo '{"error":"Steer не запущен"}'; return 1; }
			w="$(_stl_t 15 steer dns-log 2>/dev/null | tr -d '\n\r')"
			case "$w" in '{'*'"names"'*) ;; *) echo '{"error":"ядро Steer не отдало журнал имён — нужна версия 2.0 или новее"}'; return 1 ;; esac
			mkdir -p "$ST_RUN"
			printf '%s\n' "$w" > "$ST_RUN/dnslog.$$"
			_st_dnslog_fix "$ST_RUN/dnslog.$$" 2>/dev/null | grep . || printf '%s\n' "$w"
			rm -f "$ST_RUN/dnslog.$$" ;;
		wfix_reset)
			rm -f "$ST_WFIX_STATE"; printf '{"ok":true}\n' ;;
		warp_own_get)
			local of="$ST_WARP_OWN"
			[ -s "$of" ] || of="$ST_WARP_OWN_KEEP"
			if [ -s "$of" ]; then printf '{"content":"%s"}\n' "$(esc_ml "$(tr -d '\r' < "$of" | tr '\t' ' ')")"
			else printf '{"content":""}\n'; fi
			;;
		diag)
			local trace warp="none" colo="" tun="" tsep="" wi wn wv wc vpn="none" vip="" vloc="" gs gt
			if _st_installed && _st_work && [ ! -f "$ST_OFF" ] && _st_use_vpn; then
				vpn=off
				_st_vpn_probe && vpn=on
				read -r _ _ vip vloc 2>/dev/null < "$ST_VPN_PROBE"
			elif _st_installed && _st_warp_on && _st_work && [ ! -f "$ST_OFF" ] && { [ "$(_st_exit)" != iface ] || _st_secs_warp; }; then
				warp=off
				wn=1
				while [ "$wn" -le "$ST_WARP_N" ]; do
					wi="$(_st_wif "$wn")"
					if _st_wnet "$wi" && [ -d "/sys/class/net/$wi" ]; then
						trace="$(curl -s --interface "$wi" --connect-timeout 4 --max-time 8 https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null)"
						wc="$(echo "$trace" | sed -n 's/^colo=//p')"
						wv=""
						case "$trace" in
							*warp=on*|*warp=plus*) wv=on ;;
							*ip=*) _st_warp_own && wv=on ;;
						esac
						gs=""; gt=""
						if [ "$wv" = on ]; then
							warp=on; [ -n "$colo" ] || colo="$wc"
							_st_warp_geo "$wi"
							set -- $(_st_geo_get "$wi")
							if [ $# -ge 4 ]; then
								[ -n "$wc" ] || wc="$1"
								gs="$2"; shift 3; gt="$*"
								[ "$gs" = - ] && gs=""; [ "$gt" = - ] && gt=""
							fi
						else wc="$(_st_colo_of "$wi")"; [ -n "$wc" ] && wv=notls || wv=off; fi
						tun="$tun$tsep{\"n\":$wn,\"warp\":\"$wv\",\"colo\":\"$(esc "$wc")\",\"city\":\"$(esc "$gt")\",\"seen\":\"$(esc "$gs")\"}"
						tsep=","
					fi
					wn=$((wn + 1))
				done
			fi
			local d="" itj="" isep="" ti td tip tup
			if _st_installed && _st_work && [ ! -f "$ST_OFF" ]; then
				for ti in $(_st_tun_ifaces); do
					td="$(_zm_tun_dev "$ti")"; tip=""; tup=false
					if [ -n "$td" ] && [ -d "/sys/class/net/$td" ]; then
						tup=true
						tip="$(curl -s --interface "$td" --connect-timeout 4 --max-time 8 https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null | sed -n 's/^ip=//p')"
					fi
					itj="$itj$isep{\"name\":\"$(esc "$ti")\",\"label\":\"$(esc "$(_zm_tun_label "$(_zm_tun_kind "$ti")")")\",\"kind\":\"$(_zm_tun_kind "$ti")\",\"up\":$tup,\"ip\":\"$(esc "$tip")\"}"
					isep=","
				done
			fi
			local hj=""
			if stl_present && _st_owns "steer-spec"; then
				d="$(stl_diag)"
				if [ "$d" != null ]; then
					mkdir -p "$ST_RUN"
					printf '%s\n' "$d" > "$ST_RUN/diag.ui.$$"
					hj="$(_stl_diag_tsv "$ST_RUN/diag.ui.$$" | _st_diag_hjson)"
					rm -f "$ST_RUN/diag.ui.$$"
				fi
			fi
			printf '{"warp":"%s","colo":"%s","vpn":"%s","vpn_ip":"%s","vpn_loc":"%s","tunnels":[%s],"ifs":[%s],"diag":%s,"human":[%s]}\n' "$warp" "$(esc "$colo")" "$vpn" "$(esc "$vip")" "$(esc "$vloc")" "$tun" "$itj" "${d:-null}" "$hj"
			;;
		dns_fix)
			do_steer_dns_fix
			printf '{"ok":true}\n'
			;;
		cron_restart) _st_cron_restart ;;
		sync)
			_st_cron_refresh
			_st_ping_cron
			_st_owns "steer-spec" && [ ! -f "$ST_OFF" ] && [ -z "$(_st_blocker)" ] && stl_reload
			printf '{"ok":true}\n'
			;;
		*) echo '{"error":"неизвестное действие"}' ;;
	esac
}

AWG_DIR="/etc/zm-awg"
AWG_RUN="$JOBS_DIR/awg"
AWG_WARP_PEER="bmXOC+F1FxEMF9dyiK2H5/1SUtzH0JuVo51h2wPfgyo="
AWG_ENDPOINTS="engage.cloudflareclient.com:4500 engage.cloudflareclient.com:2408 162.159.192.1:2408 162.159.193.1:2408 162.159.195.1:2408 188.114.97.1:2408 188.114.98.1:500 188.114.99.1:4500"

[ -d "$AWG_RUN" ] || mkdir -p "$AWG_RUN" 2>/dev/null

_awg_say() { echo "==> $*"; }
_awg_pkg_ver() {
	if [ "$PKG" = "apk" ]; then
		_apk_ver "$1"
	else
		_opkg_ver "$1"
	fi
}
_awg_installed() { command -v awg >/dev/null 2>&1 && { _awg_kmod_have || _st_awg_loaded; }; }
_awg_proto_ok() { ubus call network get_proto_handlers 2>/dev/null | grep -q '"amneziawg"'; }
_awg_ifaces() { uci -q show network | sed -n "s/^network\.\([A-Za-z0-9_]*\)\.proto='amneziawg'\$/\1/p"; }
_awg_is_steer() { case "$1" in zmwarp|zmwarp[0-9]) return 0 ;; esac; return 1; }
_awg_peer_sec() { uci -q -X show network | sed -n "s/^network\.\([^.=]*\)=amneziawg_$1\$/\1/p" | head -n1; }
_awg_owned() { grep -qxF "$1" "$AWG_DIR/owned" 2>/dev/null; }
_awg_fk_secs() {
	local s
	[ -s /etc/config/netshift ] || return 0
	for s in $(uci -q show netshift 2>/dev/null | sed -n "s/^netshift\.\([^.=]*\)\.interface='$1'\$/\1/p"); do
		[ "$(uci -q get "netshift.$s.connection_type")" = vpn ] && echo "$s"
	done
	return 0
}
_awg_fk_live() { _fk_installed && _fk_enabled && [ -n "$(_awg_fk_secs "$1")" ]; }
_awg_down() {
	local i="$1" w=0
	ifdown "$i" >/dev/null 2>&1
	while [ -d "/sys/class/net/$i" ] && [ "$w" -lt 5 ]; do sleep 1; w=$((w + 1)); done
	[ -d "/sys/class/net/$i" ] && ip link del "$i" >/dev/null 2>&1
	return 0
}
_awg_hs_age() {
	local hs
	hs=$(awg show "$1" latest-handshakes 2>/dev/null | awk '$2 > 0 { print $2; exit }')
	[ -n "$hs" ] && echo $(( $(date +%s) - hs ))
}

_awg_health() {
	local i n=0 up=0 a st=0
	if _awg_installed; then
		for i in $(_awg_ifaces); do
			[ "$(uci -q get "network.$i.auto")" = 0 ] && [ ! -d "/sys/class/net/$i" ] && continue
			n=$((n + 1))
			a="$(_awg_hs_age "$i")"
			[ -n "$a" ] && [ "$a" -lt 180 ] && up=$((up + 1))
		done
		if [ "$n" = 0 ]; then
			if [ -f /lib/netifd/proto/amneziawg.sh ]; then st=1; else st=3; fi
		elif [ "$up" = "$n" ]; then st=1
		elif [ "$up" = 0 ]; then st=2
		else st=3; fi
	fi
	printf '%s,"awg_up":%s,"awg_total":%s' "$st" "$up" "$n"
}

_awg_iface_json() {
	local i="$1" p up=false addr ep host port age rx=0 tx=0 zone route auto desc warp=false owner=user mtu
	p="$(_awg_peer_sec "$i")"
	ifstatus "$i" 2>/dev/null | grep -q '"up": true' && up=true
	addr="$(uci -q get "network.$i.addresses" | tr ' ' ',')"
	mtu="$(uci -q get "network.$i.mtu")"
	host="$(uci -q get "network.$p.endpoint_host")"; port="$(uci -q get "network.$p.endpoint_port")"
	ep="$(awg show "$i" endpoints 2>/dev/null | awk '{ print $2; exit }')"
	[ -n "$ep" ] && [ "$ep" != "(none)" ] || ep="$host${port:+:$port}"
	age="$(_awg_hs_age "$i")"
	set -- $(awg show "$i" transfer 2>/dev/null | awk '{ r += $2; t += $3 } END { print r + 0, t + 0 }')
	rx="${1:-0}"; tx="${2:-0}"
	zone="$(_zm_zone_of_net "$i")"
	route="$(uci -q get "network.$p.route_allowed_ips")"
	auto="$(uci -q get "network.$i.auto")"
	desc="$(uci -q get "network.$p.description")"
	[ "$(uci -q get "network.$p.public_key")" = "$AWG_WARP_PEER" ] && warp=true
	_awg_is_steer "$i" && owner=steer
	printf '{"name":"%s","owner":"%s","owned":%s,"forkozz":%s,"up":%s,"enabled":%s,"address":"%s","mtu":"%s","endpoint":"%s","hs_age":"%s","rx":%s,"tx":%s,"zone":"%s","route_all":%s,"warp":%s,"desc":"%s"}' \
		"$i" "$owner" "$(_awg_owned "$i" && echo true || echo false)" "$(_awg_fk_live "$i" && echo true || echo false)" "$up" "$([ "$auto" = 0 ] && echo false || echo true)" "$(esc "$addr")" "$(esc "$mtu")" "$(esc "$ep")" "$age" \
		"$rx" "$tx" "$(esc "$zone")" "$([ "$route" = 1 ] && echo true || echo false)" "$warp" "$(esc "$desc")"
}

awg_status() {
	local i x list="" sep="" running=false conf=false ep="" mask="" mih=false lp=luci-proto-amneziawg lv
	lv="$(_awg_pkg_ver luci-proto-amneziawg)"
	[ -n "$lv" ] || { lv="$(_awg_pkg_ver luci-app-amneziawg)"; [ -n "$lv" ] && lp=luci-app-amneziawg; }
	_job_alive awg && running=true
	for i in $(_awg_ifaces); do list="$list$sep$(_awg_iface_json "$i")"; sep=","; done
	if [ -s "$MIXOMO_WARP_CONF" ]; then
		conf=true
		ep="$(sed -n 's/^[[:space:]]*Endpoint[[:space:]]*=[[:space:]]*//p' "$MIXOMO_WARP_CONF" | head -n1)"
		mask="$(sed -n 's/^[[:space:]]*I1[[:space:]]*=[[:space:]]*//p' "$MIXOMO_WARP_CONF" | head -n1)"
		[ -n "$mask" ] && mask="$(_awg_mask_name "$mask")"
	fi
	[ -x /etc/init.d/mihomo ] && mih=true
	printf '{"running":%s,"phase":"%s","installed":%s,"kmod":"%s","tools":"%s","luci":"%s","luci_pkg":"%s","module":%s,"proto":%s,"steer":%s,"warp_conf":%s,"warp_path":"%s","warp_endpoint":"%s","warp_mask":"%s","mihomo":%s,"endpoints":"%s","steer_own":%s,"steer_ext":"%s","steer_ifs":[%s],"steer_active":"%s","fk_name":"%s","fix":%s,"ifaces":[%s]}\n' \
		"$running" "$(cat "$AWG_RUN/phase" 2>/dev/null)" "$(_awg_installed && echo true || echo false)" \
		"$(esc "$(_awg_kmod_ver)")" "$(esc "$(_awg_pkg_ver amneziawg-tools)")" "$(esc "$lv")" "$lp" \
		"$(_st_awg_loaded && echo true || echo false)" "$(_awg_proto_ok && echo true || echo false)" \
		"$(_st_warp_on && echo true || echo false)" "$conf" "$MIXOMO_WARP_CONF" "$(esc "$ep")" "$(esc "$mask")" "$mih" "$AWG_ENDPOINTS" "$(_st_warp_own && echo true || echo false)" "$(_st_installed && _st_warp_ext && esc "$(_st_ext_if)")" "$(_st_installed && { _st_warp_ext && _st_ext_if; [ "$(cat "$ST_DIR/exit" 2>/dev/null)" = iface ] && _st_main_iface && echo; for x in $(_st_secs); do [ "$(_st_sec_kind "$x")" = iface ] && _st_sec_iface "$x" && echo; done; } | grep . | awk '!s[$0]++ { printf "%s\"%s\"", (n++ ? "," : ""), $0 }')" "$(_st_warp_on && _st_active_if)" "$(_fk_name)" "$(_awf_json)" "$list"
}

do_awg_install() {
	echo "${1:-install}" > "$AWG_RUN/phase"
	_ensure_deps
	mkdir -p "$ST_RUN" "$AWG_DIR"
	[ "$1" = update ] && _awg_say "Переустанавливаем AmneziaWG"
	ST_AWG_OWN=0 _st_install_awg "$1" || return 1
	_awg_say "Готово: AmneziaWG $(_awg_pkg_ver amneziawg-tools) установлен"
}

do_awg_remove() {
	local p i all="$1" used="" left="" rc=0
	echo remove > "$AWG_RUN/phase"
	for i in $(_awg_ifaces); do
		_awg_is_steer "$i" && [ -s "$ST_OWNED" ] && continue
		_awg_fk_live "$i" && used="$used $i"
	done
	if [ -n "$used" ] && _fk_foreign; then
		echo "ОШИБКА: через туннель${used} сейчас работает NetShift. Панель его не трогает — выберите в нём другое подключение или выключите его, потом удалите AmneziaWG"
		return 1
	fi
	if [ -n "$used" ]; then
		_awg_say "Forkozz работает через туннель${used} — сначала выключаем Forkozz, чтобы сервисы не зависли"
		/etc/init.d/netshift disable >/dev/null 2>&1
		_zm_run 90 $FK_REL /etc/init.d/netshift stop >/dev/null 2>&1
		nft delete table inet "$FK_NFT" >/dev/null 2>&1
		nft delete table inet "$FK_NFT_GUARD" >/dev/null 2>&1
		_fk_dnsmasq_clean
		/etc/init.d/dnsmasq restart >/dev/null 2>&1
		echo "   ✓ Forkozz выключен, трафик идёт напрямую. Его настройки сохранены — выберите в нём другое подключение и включите снова"
	fi
	for i in $(_awg_ifaces); do
		_awg_is_steer "$i" && [ -s "$ST_OWNED" ] && continue
		if ! _awg_is_steer "$i" && ! _awg_owned "$i" && [ "$all" != all ]; then left="$left $i"; continue; fi
		_awg_say "Удаляем туннель $i с его пиром и зоной файрвола"
		_awg_delete "$i"
		echo "   ✓ Туннель $i удалён"
	done
	if [ -n "$left" ]; then
		echo "ОШИБКА: туннели${left} созданы не панелью. Удалите их сами (Сеть → Интерфейсы) или отметьте их в окне удаления"
		return 1
	fi
	rm -f "$AWF_MODE" "$AWF_STATE" "$AWF_SKIP"; _awf_cron
	_awg_say "Удаляем пакеты AmneziaWG"
	for p in luci-i18n-amneziawg-ru luci-proto-amneziawg luci-app-amneziawg amneziawg-tools kmod-amneziawg; do
		_pkg_is_installed "$p" || continue
		_zm_pkg_purge "$p" || rc=1
	done
	_awg_say "Выгружаем модуль ядра и чистим файлы"
	rmmod amneziawg >/dev/null 2>&1
	_awg_kmod_manual_rm
	[ -d /sys/module/amneziawg ] && _zm_reboot_hint "AmneziaWG удалён, но его модуль ядра ещё загружен. Перезагрузите роутер, чтобы он выгрузился."
	sed -i -E '/^pkg (kmod-amneziawg|amneziawg-tools|luci-proto-amneziawg|luci-app-amneziawg|luci-i18n-amneziawg-ru)$/d' "$ST_OWNED" 2>/dev/null
	_zm_wipe "$AWG_DIR" /usr/bin/awg /usr/bin/awg-quick /lib/netifd/proto/amneziawg.sh || rc=1
	_zm_rm_listed awg || rc=1
	if [ -s "$MIXOMO_WARP_CONF" ]; then
		if _mx_installed; then echo "   · $MIXOMO_WARP_CONF оставляем — он нужен Mixomo"; else rm -f "$MIXOMO_WARP_CONF"; fi
	fi
	rm -f /tmp/luci-indexcache* /tmp/luci-modulecache/* 2>/dev/null
	_rb_rpcd_ensure
	if [ "$ZM_NO_NETCHECK" = 1 ]; then
		if [ "$rc" = 0 ]; then echo "   ✓ AmneziaWG удалён"; else echo "!! AmneziaWG удалён не полностью — что осталось, написано выше"; fi
		return "$rc"
	fi
	if _zm_inet_wait 9; then echo "   ✓ Интернет на роутере работает"
	else echo "!! Интернет на роутере пока не отвечает — подождите минуту или перезагрузите роутер"; _zm_net_why; fi
	_zm_rm_done "$rc" "AmneziaWG"
}
_awg_valid_ep() { _zm_re "$1" '^(\[[0-9A-Fa-f:]+\]|[A-Za-z0-9.-]+):[0-9]{1,5}$'; }
_awg_new_ok() { grep -q awg_random_trailers /lib/netifd/proto/amneziawg.sh 2>/dev/null; }

AWF_MODE="$ZM_STATE_DIR/awgfix"
AWF_SKIP="$ZM_STATE_DIR/awgfix.skip"
AWF_STATE="$ZM_STATE_DIR/awgfix.state"
AWF_LOG="$ZM_STATE_DIR/awgfix.log"
AWF_TAG="# zm-awgfix"
AWF_TRIES=4

_awf_min() { case "$(cat "$AWF_MODE" 2>/dev/null)" in 30) echo 30 ;; 60) echo 60 ;; 180) echo 180 ;; esac; }
_awf_warp() { [ "$(uci -q get "network.$(_awg_peer_sec "$1").public_key")" = "$AWG_WARP_PEER" ]; }
_awg_steer_sync() {
	local i="$1" col w=0
	_st_mode_vars
	_st_uses_if "$i" || return 0
	[ -f "$ST_OFF" ] && return 0
	_st_running && [ "$2" != force ] && return 0
	while [ "$w" -lt 15 ] && ! _st_warp_alive_if "$i"; do sleep 2; w=$((w + 1)); done
	_st_warp_alive_if "$i" || return 0
	if ! { _st_warp_ext && [ "$(_st_ext_if)" = "$i" ]; }; then
		_st_kick >/dev/null 2>&1
		echo "   ✓ Секция Steer продолжает работать через $i"
		return 0
	fi
	mkdir -p "$ST_DIR"
	col="$(_st_colo_of "$i")"
	echo "$i ${col:-?}" > "$ST_WARP_UP"
	if [ -n "$col" ]; then echo "$col" > "$ST_DIR/warp.colo"; else rm -f "$ST_DIR/warp.colo"; fi
	_st_warp_geo "$i"
	_st_kick >/dev/null 2>&1
	echo "   ✓ Steer продолжает работать через $i${col:+ (колония $col)}"
	return 0
}
_awf_ifaces() { local i; for i in $(_awg_ifaces); do _awg_is_steer "$i" && continue; _awf_warp "$i" && echo "$i"; done; }
_awf_watched() { ! grep -qxF "$1" "$AWF_SKIP" 2>/dev/null; }
_awf_get() { awk -v i="$1" -v f="$2" '$1 == i { print $f; exit }' "$AWF_STATE" 2>/dev/null; }
_awf_put() {
	mkdir -p "$ZM_STATE_DIR"
	{ grep -v "^$1 " "$AWF_STATE" 2>/dev/null; [ "$2" = - ] || echo "$1 $2 ${3:-0} ${4:-0} ${5:-dead}"; } > "$AWF_STATE.$$"
	mv -f "$AWF_STATE.$$" "$AWF_STATE"
	[ -s "$AWF_STATE" ] || rm -f "$AWF_STATE"
}
_awf_say() {
	mkdir -p "$ZM_STATE_DIR"
	{ tail -n 19 "$AWF_LOG" 2>/dev/null; echo "$(date +%s)|$1"; } > "$AWF_LOG.$$" && mv -f "$AWF_LOG.$$" "$AWF_LOG"
	logger -t zapret-manager "Автопочинка WARP: $1"
}
_awf_alive() {
	local age
	[ -d "/sys/class/net/$1" ] || return 1
	age="$(_awg_hs_age "$1")"
	[ -n "$age" ] && [ "$age" -lt 300 ] 2>/dev/null || return 1
	ping -I "$1" -c 2 -W 3 1.1.1.1 >/dev/null 2>&1 || ping -I "$1" -c 2 -W 3 8.8.8.8 >/dev/null 2>&1
}
_awf_check() {
	_awf_alive "$1" || { echo dead; return 0; }
	set -- $(_cf_meta "$1")
	if [ -n "$1" ] && _st_warp_is_ru "$1" "$3"; then echo "ru $1"; else echo ok; fi
}
_awf_ep() { local p; p="$(_awg_peer_sec "$1")"; printf '%s:%s' "$(uci -q get "network.$p.endpoint_host")" "$(uci -q get "network.$p.endpoint_port")"; }

_awf_cron() {
	local want=""
	[ -n "$(_awf_min)" ] && want="*/10 * * * * /opt/zapret-manager-luci/backend.sh awg_action fix_tick x >/dev/null 2>&1 $AWF_TAG"
	if [ -n "$want" ]; then
		[ "$(grep -cF "$AWF_TAG" "$CRON_FILE" 2>/dev/null)" = 1 ] && grep -qxF "$want" "$CRON_FILE" && return 0
	else
		grep -qF "$AWF_TAG" "$CRON_FILE" 2>/dev/null || return 0
	fi
	mkdir -p "$(dirname "$CRON_FILE")"; touch "$CRON_FILE"
	sed -i "\\|$AWF_TAG|d" "$CRON_FILE"
	[ -n "$want" ] && echo "$want" >> "$CRON_FILE"
	/etc/init.d/cron restart >/dev/null 2>&1
	return 0
}

_awf_set() {
	case "$1" in
		off) rm -f "$AWF_MODE" "$AWF_STATE" "$AWG_RUN/fix.last" "$AWG_RUN/fix.nonet" ;;
		30|60|180) mkdir -p "$ZM_STATE_DIR"; echo "$1" > "$AWF_MODE" ;;
		*) echo '{"error":"неверный интервал"}'; return 1 ;;
	esac
	_awf_cron
	[ "$1" = off ] || ( _awf_tick >/dev/null 2>&1 & )
	printf '{"ok":true}\n'
}

_awf_skip() {
	local i="${1%%|*}" v="${1#*|}"
	_awf_ifaces | grep -qxF "$i" || { echo '{"error":"нет такого туннеля WARP"}'; return 1; }
	mkdir -p "$ZM_STATE_DIR"
	{ grep -vxF "$i" "$AWF_SKIP" 2>/dev/null; [ "$v" = off ] && echo "$i"; } > "$AWF_SKIP.$$"
	mv -f "$AWF_SKIP.$$" "$AWF_SKIP"
	[ -s "$AWF_SKIP" ] || rm -f "$AWF_SKIP"
	[ "$v" = off ] && _awf_put "$i" -
	printf '{"ok":true}\n'
}

_awf_tick() {
	local lim now i since tries last all=1 any=0 pick="" age why
	lim="$(_awf_min)"
	[ -n "$lim" ] || return 0
	_awg_installed || return 0
	_job_alive awg && return 0
	_job_alive steer && return 0
	now="$(date +%s)"
	mkdir -p "$AWG_RUN"; echo "$now" > "$AWG_RUN/fix.last"
	for i in $(_awf_ifaces); do
		_awf_watched "$i" || continue
		[ "$(uci -q get "network.$i.auto")" = 0 ] && { _awf_put "$i" -; continue; }
		any=1
		set -- $(_awf_check "$i")
		if [ "$1" = ok ]; then
			all=0
			[ -n "$(_awf_get "$i" 2)" ] && { _awf_put "$i" -; _awf_say "$i снова работает"; }
			continue
		fi
		why="$1${2:+:$2}"
		[ "$1" = ru ] && all=0
		since="$(_awf_get "$i" 2)"; tries="$(_awf_get "$i" 3)"; last="$(_awf_get "$i" 4)"
		if [ -z "$since" ]; then
			age="$(_awg_hs_age "$i")"
			if [ "$why" = dead ] && [ -n "$age" ] && [ "$age" -ge 300 ] 2>/dev/null && [ "$age" -lt 86400 ] 2>/dev/null; then since=$((now - age)); else since="$now"; fi
			tries=0; last=0
		fi
		_awf_put "$i" "$since" "${tries:-0}" "${last:-0}" "$why"
		[ "${tries:-0}" -ge "$AWF_TRIES" ] && continue
		[ $((now - since)) -ge $((lim * 60)) ] || continue
		[ $((now - ${last:-0})) -ge $((lim * 60)) ] || continue
		[ -z "$pick" ] && pick="$i"
	done
	[ "$any" = 1 ] && [ -n "$pick" ] || return 0
	if [ "$all" = 1 ] && ! _st_wfix_net_ok; then
		[ -f "$AWG_RUN/fix.nonet" ] || { touch "$AWG_RUN/fix.nonet"; _awf_say "нет интернета у роутера — починка отложена"; }
		return 0
	fi
	rm -f "$AWG_RUN/fix.nonet"
	_zm_busy_job >/dev/null 2>&1 && return 0
	tries="$(_awf_get "$pick" 3)"; since="$(_awf_get "$pick" 2)"; why="$(_awf_get "$pick" 5)"
	_awf_put "$pick" "$since" $(( ${tries:-0} + 1 )) "$now" "$why"
	job_start awg do_awg_fix "$pick" "$since" >/dev/null
}

do_awg_fix() {
	local i="$1" since="$2" tries mins keys="" bak="$AWG_RUN/fix.network" w=0 ok=0 old new why res=""
	mkdir -p "$AWG_RUN"
	echo autofix > "$AWG_RUN/phase"
	echo "$i" > "$AWG_RUN/fix.busy"
	tries="$(_awf_get "$i" 3)"; [ "${tries:-1}" -ge 3 ] && keys=1
	why="$(_awf_get "$i" 5)"
	mins=$(( ($(date +%s) - ${since:-$(date +%s)}) / 60 ))
	old="$(_awf_ep "$i")"
	_awg_say "Автопочинка: $i $(case "$why" in ru:*) echo "работает через российский узел ${why#ru:} — блокировки через него не снимаются" ;; *) echo "не работает $mins мин" ;; esac) — $([ -n "$keys" ] && echo "получаем новые ключи и подбираем зарубежную точку входа" || echo "подбираем зарубежную точку входа") (попытка ${tries:-1} из $AWF_TRIES)"
	cp -f /etc/config/network "$bak"
	echo "   · текущая настройка сохранена — если новая не заработает, вернём её"
	if [ -n "$keys" ]; then
		ZM_NOSYNC=1 do_awg_regen "$i" >/dev/null 2>&1 && echo "   ✓ новые ключи получены" || echo "!! новые ключи получить не удалось"
	fi
	do_awg_pick "$i" 2>&1 | grep -E '^==> Готово|ОШИБКА' | sed 's/^==> Готово: /   ✓ точка входа: /; s/^ОШИБКА: /!! /'
	echo autofix > "$AWG_RUN/phase"
	_awg_say "Проверяем, работает ли $i"
	ubus call "network.interface.$i" up >/dev/null 2>&1
	while [ "$w" -lt 12 ]; do
		_awf_alive "$i" && { ok=1; break; }
		sleep 5; w=$((w + 1))
	done
	[ "$ok" = 1 ] && res="$(_awf_check "$i")"
	rm -f "$AWG_RUN/fix.busy"
	new="$(_awf_ep "$i")"
	if [ "$res" = ok ]; then
		rm -f "$bak"
		_awf_put "$i" -
		echo "   ✓ $i работает через зарубежный узел: точка входа $new"
		_awg_steer_sync "$i"
		_awf_say "$i $(case "$why" in ru:*) echo "шёл через российский узел ${why#ru:}" ;; *) echo "не работал $mins мин" ;; esac) — подобрана точка $new${keys:+, новые ключи}"
		_awg_say "Готово"
		return 0
	fi
	case "$res" in ru*)
		if [ "${why%%:*}" != ru ]; then
			rm -f "$bak"
			_awf_put "$i" "$since" "${tries:-1}" "$(date +%s)" "ru:${res#ru }"
			echo "!! $i снова работает, но только через российский узел ${res#ru } — оставляем, это лучше, чем ничего; зарубежный поищем при следующей проверке"
			_awg_steer_sync "$i"
			_awf_say "$i: зарубежной точки не нашлось — работает через российский узел ${res#ru }, поищем снова через $(_awf_min) мин"
			return 1
		fi ;;
	esac
	echo "!! с новой настройкой $i не стал лучше — возвращаем прежнюю"
	cat "$bak" > /etc/config/network
	rm -f "$bak"
	ubus call network reload >/dev/null 2>&1
	sleep 2
	ubus call "network.interface.$i" up >/dev/null 2>&1
	_awg_steer_sync "$i"
	if [ "${tries:-1}" -ge "$AWF_TRIES" ]; then
		_awf_say "$i: $AWF_TRIES попытки не помогли — автопочинка для него остановлена до «Попробовать снова»"
	else
		_awf_say "$i: $(case "$res" in ru*) echo "нашлась только российская точка ${res#ru }" ;; *) echo "новая настройка не заработала" ;; esac) — вернули прежнюю, повторим через $(_awf_min) мин"
	fi
	return 1
}

_awf_json() {
	local m out="" sep="" i since tries last why fixing="" sk="" t txt
	m="$(_awf_min)"
	if [ -s "$AWF_STATE" ]; then
		while read -r i since tries last why; do
			[ -n "$i" ] || continue
			out="$out$sep{\"name\":\"$(esc "$i")\",\"since\":${since:-0},\"tries\":${tries:-0},\"last\":${last:-0},\"why\":\"$(esc "${why:-dead}")\"}"; sep=","
		done < "$AWF_STATE"
	fi
	sep=""
	for i in $(cat "$AWF_SKIP" 2>/dev/null); do sk="$sk$sep\"$(esc "$i")\""; sep=","; done
	_job_alive awg && [ -s "$AWG_RUN/fix.busy" ] && fixing="$(cat "$AWG_RUN/fix.busy")"
	printf '{"mode":"%s","max":%s,"now":%s,"last_check":%s,"fixing":"%s","skip":[%s],"dead":[%s],"log":[' "${m:-off}" "$AWF_TRIES" "$(date +%s)" \
		"$(awk '{ print $1 + 0; exit }' "$AWG_RUN/fix.last" 2>/dev/null | grep . || echo 0)" "$(esc "$fixing")" "$sk" "$out"
	sep=""
	[ -s "$AWF_LOG" ] && tail -n 5 "$AWF_LOG" | while IFS='|' read -r t txt; do
		printf '%s{"t":%s,"text":"%s"}' "$sep" "${t:-0}" "$(esc "$txt")"; sep=","
	done
	printf ']}'
}

AWG_API1="https://api.cloudflareclient.com/v0a4005/reg"
AWG_API2="https://api.cloudflareclient.com/v0i1909051800/reg"
AWG_RELAY="https://edge-client-api.vercel.app/v0a4005/reg"
AWG_CF_VER="a-6.11-2223"
AWG_BOOT_PRIV="4OnO86dDLpqJ2U10ODwX3tarx6xlRGLfkmbSBtMgaHg="
AWG_BOOT_IP="172.16.0.3"
AWG_TEST_IF="zmawgtest"
AWG_TEST_HOSTS="162.159.192.1 188.114.97.1 188.114.96.3 162.159.193.2 162.159.195.2 188.114.98.2 188.114.99.2 8.6.112.2 8.34.70.2 8.34.146.2 8.39.125.2"
AWG_TEST_PORTS="2408 500 4500 1701"
AWG_I1_ICLOUD="<r 2><b 0x858000010001000000000669636c6f756403636f6d0000010001c00c000100010000105a00044d583737>"
AWG_I1_QUIC1="<b >"

AWG_I1_SET="quic2 dns stun icloud sip quic"
AWG_I1_HOSTS="www.apple.com www.google.com www.microsoft.com cdn.jsdelivr.net"

_i1_hex() { if command -v hexdump >/dev/null 2>&1; then hexdump -ve '1/1 "%02x"'; else od -An -v -tx1 | tr -d ' \n'; fi; }
_i1_num() {
	awk -v a="$1" -v b="$2" -v s="$(head -c 4 /dev/urandom | _i1_hex)" 'BEGIN { x = 0; for (i = 1; i <= length(s); i++) x = x * 16 + index("0123456789abcdef", substr(s, i, 1)) - 1; srand(x); print a + int(rand() * (b - a + 1)) }'
}
_i1_str() { tr -dc 'a-z0-9' < /dev/urandom 2>/dev/null | head -c "$1"; }
_i1_host() { set -- $AWG_I1_HOSTS; eval "echo \"\${$(_i1_num 1 $#)}\""; }

_i1_dns() {
	local h="${1:-$(_i1_host)}" q="" l p
	for l in $(echo "$h" | tr '.' ' '); do q="$q$(printf '%02x' "${#l}")$(printf '%s' "$l" | _i1_hex)"; done
	p="$(_i1_num 60 180)"
	printf '<r 2><b 0x01000001000000000001%s0000010001000029100000000000%04x000c%04x><r %d>' "$q" $((p + 4)) "$p" "$p"
}

_i1_stun() {
	local s
	s=$(( $(_i1_num 4 8) * 4 ))
	printf '<b 0x0001%04x2112a442><r 12><b 0x8022%04x%s>' $((s + 4)) "$s" "$(_i1_str "$s" | _i1_hex)"
}

_i1_sip() {
	local h="${1:-$(_i1_host)}"
	printf '<b 0x%s>' "$(printf '%s\r\n' \
		"OPTIONS sip:$h SIP/2.0" \
		"Via: SIP/2.0/UDP 192.168.$(_i1_num 0 255).$(_i1_num 2 254):5060;branch=z9hG4bK$(_i1_str 10)" \
		"From: <sip:$(_i1_str 8)@$h>;tag=$(_i1_num 100000 999999)" \
		"To: <sip:$h>" \
		"Call-ID: $(_i1_str 16)@$h" \
		"CSeq: $(_i1_num 1000 9999) OPTIONS" \
		"Max-Forwards: 70" \
		"User-Agent: PJSIP/2.13" \
		"Content-Length: 0" \
		"" | _i1_hex)"
}

_awg_i1() {
	case "$1" in
		quic) echo "$MIXOMO_AWG_I1" ;;
		quic2) echo "$AWG_I1_QUIC1" ;;
		icloud) echo "$AWG_I1_ICLOUD" ;;
		dns) _i1_dns ;;
		stun) _i1_stun ;;
		sip) _i1_sip ;;
	esac
}

_awg_write_conf() {
	mkdir -p "$(dirname "$MIXOMO_WARP_CONF")"
	printf '%s\n' \
		"[Interface]" "PrivateKey = $1" "Address = ${3}${4:+, $4}" "DNS = 1.1.1.1, 1.0.0.1" "MTU = 1280" \
		"S1 = $MIXOMO_AWG_S1" "S2 = $MIXOMO_AWG_S2" "Jc = $MIXOMO_AWG_JC" "Jmin = $MIXOMO_AWG_JMIN" "Jmax = $MIXOMO_AWG_JMAX" \
		"H1 = $MIXOMO_AWG_H1" "H2 = $MIXOMO_AWG_H2" "H3 = $MIXOMO_AWG_H3" "H4 = $MIXOMO_AWG_H4" "I1 = ${6:-$MIXOMO_AWG_I1}" "" \
		"[Peer]" "PublicKey = $2" "AllowedIPs = 0.0.0.0/0, ::/0" "Endpoint = $5" "PersistentKeepalive = 25" \
		> "$MIXOMO_WARP_CONF"
	chmod 600 "$MIXOMO_WARP_CONF"
}
_awg_write_sip_conf() {
	mkdir -p "$(dirname "$MIXOMO_WARP_CONF")"
	printf '%s\n' \
		"[Interface]" "PrivateKey = $1" "Address = ${3%/*}" "DNS = 1.1.1.1, 1.0.0.1" "MTU = 1280" \
		"S1 = 0" "S2 = 0" "S3 = 0" "S4 = 0" "Jc = 4" "Jmin = 40" "Jmax = 70" \
		"H1 = 1" "H2 = 2" "H3 = 3" "H4 = 4" "I1 = $AWG_SIP_I1" "I2 = $AWG_SIP_I2" \
		"RandomTrailers = on" "DisableCookies = on" "" \
		"[Peer]" "PublicKey = ${2:-$AWG_WARP_PEER}" "AllowedIPs = 0.0.0.0/0" "Endpoint = $4" "PersistentKeepalive = 25" \
		> "$MIXOMO_WARP_CONF"
	chmod 600 "$MIXOMO_WARP_CONF"
}

_awg_keys_main() {
	local reg="$AWG_RUN/reg.$$.${ZM_REG_N:-0}.json"
	mkdir -p "$AWG_RUN"
	rm -f "$reg"
	curl -fsSL --connect-timeout 10 --max-time 30 "$MIXOMO_WARP_PRIMARY" -o "$reg" 2>/dev/null && grep -q '"public_key"' "$reg" || { rm -f "$reg"; return 1; }
	G_PRIV=$(grep -o '"key"[[:space:]]*:[[:space:]]*"[^"]*"' "$reg" | head -n1 | sed 's/.*:[[:space:]]*"//;s/"$//')
	G_PEER=$(grep -o '"public_key"[[:space:]]*:[[:space:]]*"[^"]*"' "$reg" | head -n1 | sed 's/.*:[[:space:]]*"//;s/"$//')
	G_V4=$(grep -o '"v4"[[:space:]]*:[[:space:]]*"[^"]*"' "$reg" | sed -n '2p' | sed 's/.*:[[:space:]]*"//;s/"$//')
	G_V6=$(grep -o '"v6"[[:space:]]*:[[:space:]]*"[^"]*"' "$reg" | sed -n '2p' | sed 's/.*:[[:space:]]*"//;s/"$//')
	rm -f "$reg"
	[ -n "$G_PRIV" ] && [ -n "$G_PEER" ] && [ -n "$G_V4" ]
}
_awg_keys_get() {
	G_PRIV=""; G_PEER=""; G_V4=""; G_V6=""
	mkdir -p "$AWG_RUN"
	if [ -z "$(_awg_keygen_tool)" ] && [ "$ZM_KEYS_INSTALL" = 1 ]; then
		_awg_say "Ставим wireguard-tools, чтобы создавать ключи на роутере"
		$UPDATE >/dev/null 2>&1
		$INSTALL wireguard-tools >&2 || echo "   wireguard-tools не установился"
	fi
	if [ -n "$(_awg_keygen_tool)" ]; then
		_awg_say "Получаем ключи WARP: Cloudflare, ключ создаётся на роутере"
		_awg_cf_register "" && return 0
		echo "   Cloudflare не выдал ключи"
	fi
	_awg_say "Получаем ключи WARP: внешний генератор"
	_awg_keys_main && return 0
	echo "   внешний генератор не ответил"
	if [ -n "$1" ] && [ -d "/sys/class/net/$1" ] && [ -n "$(_awg_keygen_tool)" ]; then
		_awg_say "Пробуем Cloudflare через туннель $1"
		_awg_cf_register "--interface $1" && return 0
	fi
	return 1
}
_awg_keygen_tool() {
	if command -v awg >/dev/null 2>&1; then echo awg
	elif command -v wg >/dev/null 2>&1; then echo wg; fi
}
_awg_genkey() {
	local gen
	gen="$(_awg_keygen_tool)"
	[ -n "$gen" ] || return 1
	G_PRIV="$($gen genkey 2>/dev/null)"; G_PUB="$(printf '%s' "$G_PRIV" | $gen pubkey 2>/dev/null)"
	[ -n "$G_PRIV" ] && [ -n "$G_PUB" ]
}
_awg_cf_register() {
	local reg="$AWG_RUN/reg.$$.${ZM_REG_N:-0}.json" api code pre id tok host lbl dead="" ua='okhttp/3.12.1' cv="$AWG_CF_VER"
	_awg_genkey || { echo "   нет утилиты awg или wg"; return 1; }
	mkdir -p "$AWG_RUN"
	for api in "$AWG_API1" "$AWG_API2" $ST_WARP_API "$AWG_RELAY"; do
		host="${api#https://}"; host="${host%%/*}"
		case " $dead " in *" $host "*) continue ;; esac
		lbl="$host"; [ "$api" = "$AWG_RELAY" ] && lbl="реле $host"
		rm -f "$reg"
		code=$(curl -s --connect-timeout 6 --max-time 25 $1 -X POST \
			-H 'Content-Type: application/json' -H "User-Agent: $ua" -H "CF-Client-Version: $cv" -H 'Accept-Encoding: identity' \
			-d "{\"key\":\"$G_PUB\",\"install_id\":\"\",\"fcm_token\":\"\",\"tos\":\"$(date -u +%Y-%m-%dT%H:%M:%S.000Z)\",\"type\":\"Android\",\"model\":\"\",\"locale\":\"en_US\"}" \
			-o "$reg" -w '%{http_code}' "$api" 2>/dev/null)
		case "$code" in
			200|201) ;;
			''|000) echo "   $lbl: нет связи"; dead="$dead $host"; continue ;;
			*) echo "   $lbl: ответ $code"; continue ;;
		esac
		G_PEER=""; G_V4=""; G_V6=""; id=""; tok=""
		for pre in '@.result' '@'; do
			G_PEER="$(jsonfilter -i "$reg" -e "$pre.config.peers[0].public_key" 2>/dev/null)"
			[ -n "$G_PEER" ] || continue
			G_V4="$(jsonfilter -i "$reg" -e "$pre.config.interface.addresses.v4" 2>/dev/null)"
			G_V6="$(jsonfilter -i "$reg" -e "$pre.config.interface.addresses.v6" 2>/dev/null)"
			id="$(jsonfilter -i "$reg" -e "$pre.id" 2>/dev/null)"; tok="$(jsonfilter -i "$reg" -e "$pre.token" 2>/dev/null)"
			break
		done
		if [ -n "$G_PEER" ] && [ -n "$G_V4" ]; then
			if [ -n "$id" ] && [ -n "$tok" ]; then
				code=$(curl -s --connect-timeout 6 --max-time 15 $1 -X PATCH \
					-H 'Content-Type: application/json' -H "User-Agent: $ua" -H "CF-Client-Version: $cv" -H 'Accept-Encoding: identity' -H "Authorization: Bearer $tok" \
					-d '{"warp_enabled":true}' -o /dev/null -w '%{http_code}' "${api}/$id" 2>/dev/null)
				case "$code" in
					2??) ;;
					*) echo "   $lbl: ключ выдан, но WARP не включился (ответ ${code:-нет связи})"; G_PEER=""; G_V4=""; G_V6=""; dead="$dead $host"; continue ;;
				esac
			fi
			rm -f "$reg"
			echo "   ключи выданы ($lbl)"
			return 0
		fi
		echo "   $lbl: в ответе нет ключа сервера"
	done
	rm -f "$reg"
	return 1
}
_awg_api_ok() {
	local code
	code=$(curl -s --connect-timeout 5 --max-time 8 $1 -o /dev/null -w '%{http_code}' "$AWG_API1/" 2>/dev/null)
	[ -n "$code" ] && [ "$code" != 000 ]
}

AWG_NO_I1=0
AWG_TRY_WAIT=8
_awg_try() {
	local dev="$1" conf="$AWG_RUN/try.conf" hs i=0 i1="$5"
	[ "$AWG_NO_I1" = 1 ] && i1=""
	ip link del "$dev" >/dev/null 2>&1
	ip link add dev "$dev" type amneziawg >/dev/null 2>&1 || return 2
	ip link set "$dev" mtu 1280 >/dev/null 2>&1
	ip addr add "$3/32" dev "$dev" >/dev/null 2>&1
	ip link set "$dev" up >/dev/null 2>&1
	printf '%s\n' "[Interface]" "PrivateKey = $2" \
		"Jc = $MIXOMO_AWG_JC" "Jmin = $MIXOMO_AWG_JMIN" "Jmax = $MIXOMO_AWG_JMAX" "S1 = $MIXOMO_AWG_S1" "S2 = $MIXOMO_AWG_S2" \
		"H1 = $MIXOMO_AWG_H1" "H2 = $MIXOMO_AWG_H2" "H3 = $MIXOMO_AWG_H3" "H4 = $MIXOMO_AWG_H4" ${i1:+"I1 = $i1"} "" \
		"[Peer]" "PublicKey = ${6:-$AWG_WARP_PEER}" "AllowedIPs = 0.0.0.0/0" "Endpoint = $4" "PersistentKeepalive = 5" > "$conf"
	if ! awg setconf "$dev" "$conf" >/dev/null 2>&1; then
		if [ -n "$i1" ] && sed -i '/^I1 = /d' "$conf" && awg setconf "$dev" "$conf" >/dev/null 2>&1; then
			[ "$AWG_NO_I1" = 1 ] || echo "   модуль AmneziaWG не знает маску I1 (версия 1.0) — пробуем без неё"
			AWG_NO_I1=1
		else
			rm -f "$conf"; return 1
		fi
	fi
	rm -f "$conf"
	while [ "$i" -lt "$AWG_TRY_WAIT" ]; do
		hs=$(awg show "$dev" latest-handshakes 2>/dev/null | awk '{ print $2; exit }')
		[ "${hs:-0}" -gt 0 ] 2>/dev/null && return 0
		sleep 0.5 2>/dev/null || sleep 1
		i=$((i + 1))
	done
	return 1
}
_awg_try_down() { ip link del "$1" >/dev/null 2>&1; }
_awg_ml() { [ "$AWG_NO_I1" = 1 ] || echo ", маска $(_awg_mask_name "$1")"; }
_awg_trace() {
	curl -s --interface "$1" --connect-timeout 4 --max-time 6 http://1.1.1.1/cdn-cgi/trace 2>/dev/null | grep -Eq '^warp=(on|plus)' && return 0
	curl -s -o /dev/null --interface "$1" --connect-timeout 4 --max-time 7 https://www.google.com/generate_204 2>/dev/null
}
_awg_mask_name() {
	case "$1" in
		"$AWG_I1_ICLOUD") echo "iCloud-DNS" ;;
		"$AWG_I1_QUIC1") echo "QUIC-2" ;;
		"<r 2><b 0x01000001000000000001"*) echo "DNS" ;;
		"<b 0x0001"*) echo "STUN" ;;
		"<b 0x4f5054494f4e53"*|"<b 0x494e56495445"*) echo "SIP" ;;
		*) echo "QUIC" ;;
	esac
}

_zm_rand32() {
	local v=""
	if command -v hexdump >/dev/null 2>&1; then v="$(head -c 4 /dev/urandom 2>/dev/null | hexdump -e '1/4 "%u"' 2>/dev/null)"
	elif command -v od >/dev/null 2>&1; then v="$(head -c 4 /dev/urandom 2>/dev/null | od -An -tu4 2>/dev/null | tr -d ' \n')"; fi
	case "$v" in ''|*[!0-9]*) v="$(( $(date +%s) % 100000 * 1000 + $$ % 1000 ))" ;; esac
	echo "$v"
}

_awg_rand_hosts() {
	awk -v n="$1" -v pools="$ST_WARP_POOLS" -v seed="$(_zm_rand32)" 'BEGIN {
		srand(seed + 0); c = split(pools, p, " ")
		for (i = 1; i <= c; i++) for (k = 0; k < n; k++) printf "%s%d\n", p[i], 2 + int(rand() * 253)
	}' | awk 'BEGIN { srand() } { print rand() "\t" $0 }' | sort -n | cut -f2
}

do_awg_gen() {
	local mode="$1" ep="$2" sip="" path="" i a host port m n=0 best="" fall="" ru="" rucnt=0 t0 colo="" bmask="$MIXOMO_AWG_I1" bep="" masks tried=""
	mkdir -p "$AWG_RUN"
	[ "$ZM_GEN_NOPHASE" = 1 ] || echo gen > "$AWG_RUN/phase"
	G_PRIV=""; G_PEER=""; G_V4=""; G_V6=""
	if [ "$mode" = std ]; then
		_awg_say "Генерируем WARP"
		_awg_keys_get || { echo "ОШИБКА: ключи не получены — ни один источник не ответил. Попробуйте «С проверкой связи»"; return 1; }
		_awg_say "Ключи получены, адрес $G_V4"
		[ "$ep" = auto ] || sip=1
		if [ "$ep" = auto ]; then
			_awg_say "Подбираем точку входа"
			ep="$(_zm_wait "проверяем точки входа" _mixomo_warp_best_endpoint)"
			cat "$JOBS_DIR/mixomo_warp/pick.info" 2>/dev/null || echo "   зарубежный узел не нашёлся — беру стандартную точку"
			rm -f "$JOBS_DIR/mixomo_warp/pick.info"
		fi
		_awg_valid_ep "$ep" || ep="engage.cloudflareclient.com:4500"
		_awg_say "Точка входа: $ep"
		if [ -n "$sip" ]; then
			_awg_write_sip_conf "$G_PRIV" "$G_PEER" "$G_V4" "$ep"
			_awg_say "Маскировка: SIP-звонок"
			_awg_installed && ! _awg_new_ok && echo "   AmneziaWG на роутере старше 3.1 — при создании интерфейса роутер возьмёт только то, что понимает. Обновите AmneziaWG, чтобы работали все параметры"
		else
			_awg_write_conf "$G_PRIV" "$G_PEER" "$G_V4" "$G_V6" "$ep"
		fi
		_awg_say "Готово: WARP.conf сохранён"
		return 0
	fi

	_awg_installed || { echo "ОШИБКА: для проверки связи нужен AmneziaWG — установите его выше"; return 1; }
	_st_awg_loaded || modprobe amneziawg >/dev/null 2>&1
	trap '_awg_try_down "$AWG_TEST_IF"' EXIT INT TERM
	AWG_NO_I1=0
	_awg_try "$AWG_TEST_IF" "$AWG_BOOT_PRIV" "$AWG_BOOT_IP" "127.0.0.1:9" "$MIXOMO_AWG_I1"
	if [ $? = 2 ]; then echo "ОШИБКА: модуль ядра AmneziaWG не загружен — переустановите AmneziaWG или перезагрузите роутер"; return 1; fi
	_awg_try_down "$AWG_TEST_IF"
	_awg_say "Шаг 1 из 2: получаем ключи WARP (ключ создаётся на роутере)"
	if _awg_cf_register ""; then
		:
	elif _awg_keys_main; then
		echo "   ключи выдал внешний генератор"
	else
		echo "   внешний генератор тоже не ответил"
		echo "   ищем обходной путь через туннель"
		path=""
		for i in $(_awg_ifaces); do
			a="$(_awg_hs_age "$i")"
			[ -n "$a" ] && [ "$a" -lt 180 ] || continue
			if _awg_api_ok "--interface $i"; then path="--interface $i"; echo "   через туннель $i"; break; fi
		done
		if [ -z "$path" ]; then
			echo "   поднимаем временный туннель на общих ключах"
			for host in 188.114.96.3 162.159.192.1 188.114.97.1; do
				for port in $AWG_TEST_PORTS; do
					for m in "$MIXOMO_AWG_I1" "$AWG_I1_ICLOUD" "$AWG_I1_QUIC1"; do
						[ "$AWG_NO_I1" = 1 ] && [ "$m" != "$MIXOMO_AWG_I1" ] && continue
						if _awg_try "$AWG_TEST_IF" "$AWG_BOOT_PRIV" "$AWG_BOOT_IP" "$host:$port" "$m" && _awg_api_ok "--interface $AWG_TEST_IF"; then
							path="--interface $AWG_TEST_IF"; bep="$host:$port"; bmask="$m"
							echo "   временный туннель: $host:$port$(_awg_ml "$m")"
							break 3
						fi
					done
				done
			done
		fi
		[ -n "$path" ] || { _awg_try_down "$AWG_TEST_IF"; echo "ОШИБКА: источник ключей недоступен ни напрямую, ни через туннели — похоже, провайдер закрыл WARP"; return 1; }
		if ! _awg_cf_register "$path"; then
			_awg_try_down "$AWG_TEST_IF"
			echo "ОШИБКА: ключи не выданы"; return 1
		fi
		_awg_try_down "$AWG_TEST_IF"
	fi
	_awg_say "Ключи получены, адрес $G_V4"

	_awg_say "Шаг 2 из 2: ищем рабочую точку входа и маску"
	masks="$bmask"
	for m in "$MIXOMO_AWG_I1" "$AWG_I1_ICLOUD" "$AWG_I1_QUIC1"; do [ "$m" = "$bmask" ] || masks="$masks
$m"; done
	local ports="" oifs="$IFS" nl='
' h1="${bep%%:*}" allm meta torn seen
	allm="$masks
$(_i1_dns)
$(_i1_stun)
$(_i1_sip)"
	[ -n "$h1" ] || h1="${AWG_TEST_HOSTS%% *}"
	for port in $AWG_TEST_PORTS; do
		IFS="$nl"
		for m in $masks; do
			IFS="$oifs"
			[ "$AWG_NO_I1" = 1 ] && [ "$m" != "$bmask" ] && continue
			n=$((n + 1))
			if _awg_try "$AWG_TEST_IF" "$G_PRIV" "$G_V4" "$h1:$port" "$m" "$G_PEER"; then ports="$ports $port"; break; fi
		done
		IFS="$oifs"
		echo "   порт $port: $(case " $ports " in *" $port "*) echo открыт ;; *) echo закрыт ;; esac)"
	done
	if [ -z "$ports" ]; then
		echo "   основные порты молчат — пробуем 50 запасных, это до двух минут"
		AWG_TRY_WAIT=4
		for port in $ST_WARP_PORTS_EXT; do
			_awg_try "$AWG_TEST_IF" "$G_PRIV" "$G_V4" "$h1:$port" "$bmask" "$G_PEER" && ports="$ports $port"
			[ "$(echo $ports | wc -w)" -ge 2 ] && break
		done
		AWG_TRY_WAIT=8
		[ -n "$ports" ] && echo "   открыты запасные порты:$ports"
	fi
	[ -n "$ports" ] || _rb_warn "Ни один порт не ответил — похоже, провайдер режет UDP для WARP"
	t0="$(date +%s)"
	for host in $h1 $AWG_TEST_HOSTS $(_awg_rand_hosts 2); do
		if [ "$rucnt" -ge 12 ]; then echo "   все проверенные точки ведут на российские узлы — похоже, провайдер направляет туда весь WARP"; break; fi
		for port in $ports; do
			a="$host:$port"
			case " $tried " in *" $a "*) continue ;; esac
			tried="$tried $a"
			IFS="$nl"
			for m in $allm; do
				IFS="$oifs"
				[ "$AWG_NO_I1" = 1 ] && [ "$m" != "$bmask" ] && continue
				[ $(( $(date +%s) - t0 )) -gt 420 ] && { echo "   поиск идёт больше 7 минут — останавливаемся"; break 3; }
				n=$((n + 1))
				[ "$n" -gt 80 ] && break 3
				if _awg_try "$AWG_TEST_IF" "$G_PRIV" "$G_V4" "$a" "$m" "$G_PEER"; then
					if _awg_trace "$AWG_TEST_IF"; then
						set -- $(_st_warp_probe "$AWG_TEST_IF"); torn="$3"
						if [ "$torn" = 1 ]; then
							echo "   $a$(_awg_ml "$m") — трафик пошёл и оборвался: так DPI рвёт туннель"
							[ -n "$fall" ] || fall="$a|$m"
							continue
						fi
						meta="потери $1%, $2 мс"
						colo=""
						set -- $(_cf_meta "$AWG_TEST_IF")
						if [ $# -ge 4 ]; then
							colo="$1"
							meta="$meta, узел $1"
							[ "$2" != - ] && seen="$2" || seen=""
							shift 3
							[ "$*" != - ] && meta="$meta ($*)"
							[ -n "$seen" ] && meta="$meta, сайты видят $seen"
						fi
						if [ -n "$colo" ] && _st_warp_is_ru "$colo"; then
							echo "   $a$(_awg_ml "$m") — трафик идёт, но через российский узел $colo: там свой DPI, ищем зарубежный"
							[ -n "$ru" ] || ru="$a|$m|$colo"
							rucnt=$((rucnt + 1))
							break 2
						fi
						best="$a"; bmask="$m"
						echo "   $a$(_awg_ml "$m") — трафик идёт: $meta"
						break 3
					fi
					echo "   $a$(_awg_ml "$m") — рукопожатие есть, трафика нет"
					[ -n "$fall" ] || fall="$a|$m"
				else
					echo "   $a$(_awg_ml "$m") — нет ответа"
				fi
			done
			IFS="$oifs"
		done
	done
	IFS="$oifs"
	_awg_try_down "$AWG_TEST_IF"
	if [ -z "$best" ] && [ -n "$ru" ]; then
		best="${ru%%|*}"; bmask="${ru#*|}"; bmask="${bmask%|*}"
		_rb_warn "Зарубежный узел не нашёлся — записываю точку через российский узел ${ru##*|} ($best): WARP работает, но часть сайтов через него может не открыться"
	fi
	if [ -z "$best" ]; then
		if [ -n "$fall" ]; then
			best="${fall%%|*}"; bmask="${fall#*|}"
			_rb_warn "Трафик нигде не пошёл — записываю точку с рукопожатием ($best), туннель может не заработать"
		else
			best="engage.cloudflareclient.com:4500"; bmask="$MIXOMO_AWG_I1"
			_rb_warn "Ни одна точка не ответила — записываю стандартную ($best)"
		fi
	fi
	_awg_write_conf "$G_PRIV" "$G_PEER" "$G_V4" "$G_V6" "$best" "$bmask"
	if [ "$AWG_NO_I1" = 1 ]; then
		sed -i '/^I1 = /d' "$MIXOMO_WARP_CONF"
		_awg_say "Готово: WARP.conf сохранён (точка $best, без маски I1)"
	else
		_awg_say "Готово: WARP.conf сохранён (точка $best, маска $(_awg_mask_name "$bmask"))"
	fi
}

_awg_iface_opts() {
	awk 'function trim(s) { gsub(/^[ \t\r]+|[ \t\r]+$/, "", s); return s }
		{ l = $0; sub(/[#;].*$/, "", l); l = trim(l); if (l == "") next
		  if (l ~ /^\[.*\]$/) { sec = tolower(trim(substr(l, 2, length(l) - 2))); next }
		  if (sec != "interface") next
		  p = index(l, "="); if (!p) next
		  k = trim(substr(l, 1, p - 1)); v = trim(substr(l, p + 1))
		  if (v == "" || tolower(k) ~ /^(privatekey|address|dns|mtu|listenport|table|saveconfig|preup|postup|predown|postdown|fwmark)$/) next
		  n = ""
		  for (i = 1; i <= length(k); i++) { c = substr(k, i, 1); if (c ~ /[A-Z]/ && i > 1 && substr(k, i - 1, 1) ~ /[a-z0-9]/) n = n "_"; n = n tolower(c) }
		  gsub(/[^a-z0-9_]/, "", n); if (n == "") next
		  if (n ~ /^(random_trailers|disable_cookies)$/) { lv = tolower(v); v = (lv == "on" || lv == "true" || lv == "yes" || lv == "1") ? 1 : 0 }
		  print "awg_" n, v }' "$1"
}
_awg_iface_set() {
	local o v
	_awg_iface_opts "$1" | while read -r o v; do uci set "network.$2.$o=$v"; done
}
_awg_uci_conf() {
	local o v
	for o in $(uci -q show "network.$1" | sed -n "s/^network\.$1\.\(awg_[a-z0-9_]*\)=.*/\1/p"); do
		v="$(uci -q get "network.$1.$o")"
		[ -n "$v" ] || continue
		case "$o" in awg_random_trailers|awg_disable_cookies) [ "$v" = 1 ] && v=on || v=off ;; esac
		echo "$(echo "${o#awg_}" | awk -F_ '{ for (i = 1; i <= NF; i++) printf "%s%s", toupper(substr($i, 1, 1)), substr($i, 2) }') = $v"
	done
}

_awg_conf_kv() {
	awk 'function trim(s) { gsub(/^[ \t\r]+|[ \t\r]+$/, "", s); return s }
		{ l = $0; sub(/[#;].*$/, "", l); l = trim(l); if (l == "") next
		  if (l ~ /^\[.*\]$/) { sec = tolower(trim(substr(l, 2, length(l) - 2))); next }
		  p = index(l, "="); if (!p) next
		  print sec, tolower(trim(substr(l, 1, p - 1))), trim(substr(l, p + 1)) }' "$1"
}
_awg_cv() { awk -v s="$2" -v k="$3" '$1 == s && $2 == k { $1 = ""; $2 = ""; sub(/^  /, ""); print; exit }' "$1"; }

do_awg_create() {
	local name="$1" route="$2" fw="$3" f="$AWG_DIR/pending.conf" kv="$AWG_RUN/kv" priv pub psk addr a allowed ep host port keep mtu v p zone w=0 age foreign=""
	echo create > "$AWG_RUN/phase"
	[ -s "$f" ] || { echo "ОШИБКА: нет конфигурации"; return 1; }
	_awg_installed || { echo "ОШИБКА: сначала установите AmneziaWG"; return 1; }
	_awg_conf_kv "$f" > "$kv"
	priv="$(_awg_cv "$kv" interface privatekey)"; pub="$(_awg_cv "$kv" peer publickey)"
	addr="$(_awg_cv "$kv" interface address)"; ep="$(_awg_cv "$kv" peer endpoint)"
	[ -n "$priv" ] && [ -n "$pub" ] && [ -n "$addr" ] && [ -n "$ep" ] || { echo "ОШИБКА: в файле нет PrivateKey, Address, PublicKey или Endpoint"; return 1; }
	case "$ep" in
		\[*\]:*) host="${ep%]:*}"; host="${host#[}"; port="${ep##*]:}" ;;
		*) host="${ep%:*}"; port="${ep##*:}" ;;
	esac
	psk="$(_awg_cv "$kv" peer presharedkey)"; allowed="$(_awg_cv "$kv" peer allowedips)"
	keep="$(_awg_cv "$kv" peer persistentkeepalive)"; mtu="$(_awg_cv "$kv" interface mtu)"

	_awg_say "Создаём интерфейс $name"
	[ -n "$(uci -q get "network.$name")" ] && ! _awg_owned "$name" && foreign=1
	uci -q delete "network.$name"
	for p in $(uci -q -X show network | sed -n "s/^network\.\([^.=]*\)=amneziawg_$name\$/\1/p"); do uci -q delete "network.$p"; done
	uci set "network.$name=interface"
	uci set "network.$name.proto=amneziawg"
	uci set "network.$name.private_key=$priv"
	for a in $(echo "$addr" | tr ',' ' '); do
		case "$a" in */*) ;; *:*) a="$a/128" ;; *) a="$a/32" ;; esac
		uci add_list "network.$name.addresses=$a"
	done
	uci set "network.$name.mtu=${mtu:-1280}"
	_awg_iface_set "$f" "$name"
	if ! _awg_new_ok && [ -n "$(_awg_cv "$kv" interface randomtrailers)$(_awg_cv "$kv" interface disablecookies)" ]; then
		echo "   AmneziaWG на роутере старше 3.1 — RandomTrailers и DisableCookies он не знает и пропустит. Туннель будет работать и без них"
	fi
	p="$(uci add network "amneziawg_$name")"
	uci set "network.$p.description=$name"
	uci set "network.$p.public_key=$pub"
	[ -n "$psk" ] && uci set "network.$p.preshared_key=$psk"
	for a in $(echo "${allowed:-0.0.0.0/0, ::/0}" | tr ',' ' '); do uci add_list "network.$p.allowed_ips=$a"; done
	uci set "network.$p.endpoint_host=$host"
	uci set "network.$p.endpoint_port=${port:-51820}"
	uci set "network.$p.persistent_keepalive=${keep:-25}"
	uci set "network.$p.route_allowed_ips=$route"
	uci commit network
	[ -n "$foreign" ] || grep -qxF "$name" "$AWG_DIR/owned" 2>/dev/null || echo "$name" >> "$AWG_DIR/owned"

	if [ "$fw" = 1 ]; then
		zone="$(echo "$name" | cut -c1-11)"
		_awg_say "Создаём зону firewall «$zone» — устройства сети смогут ходить в туннель"
		uci -q delete "firewall.zmawg_$name"; uci -q delete "firewall.zmawg_${name}_fwd"
		uci set "firewall.zmawg_$name=zone"
		uci set "firewall.zmawg_$name.name=$zone"
		uci add_list "firewall.zmawg_$name.network=$name"
		uci set "firewall.zmawg_$name.input=REJECT"
		uci set "firewall.zmawg_$name.output=ACCEPT"
		uci set "firewall.zmawg_$name.forward=REJECT"
		uci set "firewall.zmawg_$name.masq=1"
		uci set "firewall.zmawg_$name.mtu_fix=1"
		uci set "firewall.zmawg_${name}_fwd=forwarding"
		uci set "firewall.zmawg_${name}_fwd.src=$(_zm_lan_zone)"
		uci set "firewall.zmawg_${name}_fwd.dest=$zone"
		uci commit firewall
		/etc/init.d/firewall reload >/dev/null 2>&1
	fi
	[ "$route" = 1 ] && echo "!! Весь трафик роутера пойдёт через $name. Упадёт туннель — пропадёт интернет"
	_awg_say "Поднимаем $name"
	ubus call network reload >/dev/null 2>&1
	sleep 2
	ubus call "network.interface.$name" up >/dev/null 2>&1
	_awg_say "Ждём ответа сервера"
	printf 'Подождите '
	while [ "$w" -lt 20 ]; do
		age="$(_awg_hs_age "$name")"
		[ -n "$age" ] && break
		[ -d "/sys/class/net/$name" ] || sleep 1
		ping -I "$name" -c 1 -W 1 1.1.1.1 >/dev/null 2>&1
		w=$((w + 1))
		[ $((w % 5)) = 0 ] && printf '.'
	done
	echo
	rm -f "$f" "$kv"
	if [ -n "$age" ]; then
		[ -n "$ZM_NOSYNC" ] || _awg_steer_sync "$name"
		_awg_say "Готово: $name работает"
	else
		echo "!! $name создан, но сервер не отвечает — проверьте точку входа"
	fi
}

do_awg_pick() {
	local i="$1" p got
	echo pick > "$AWG_RUN/phase"
	p="$(_awg_peer_sec "$i")"
	[ "$(uci -q get "network.$p.public_key")" = "$AWG_WARP_PEER" ] || { echo "ОШИБКА: подбор точки есть только для туннелей WARP"; return 1; }
	mkdir -p "$ST_DIR" "$ST_RUN"
	rm -f "$ST_STOP_FLAG"
	ubus call "network.interface.$i" up >/dev/null 2>&1
	sleep 3
	_awg_say "Подбираем точку входа для $i — это до пары минут"
	got="$(_st_warp_scan "$i" "$AWG_WARP_PEER" "" "")" || { echo "ОШИБКА: ни одна точка не ответила — провайдер может резать UDP к WARP"; return 1; }
	set -- $got
	_st_warp_link "$i" "$AWG_WARP_PEER" "$1" "$2" >/dev/null 2>&1
	uci set "network.$p.endpoint_host=$1"
	uci set "network.$p.endpoint_port=$2"
	uci commit network
	_awg_say "Готово: $i → $1:$2 (сервер $3)"
	set -- $(_cf_meta "$i")
	[ $# -ge 4 ] && [ "$2" != - ] && _awg_say "Сайты видят страну: $2"
	return 0
}

do_awg_pick_sync() { do_awg_pick "$1" || return 1; _awg_steer_sync "$1"; }

do_awg_regen() {
	local i="$1" p host port ep warp=0 route k v have=0 f="$AWG_DIR/pending.conf" rc
	mkdir -p "$AWG_RUN" "$AWG_DIR"
	echo gen > "$AWG_RUN/phase"
	p="$(_awg_peer_sec "$i")"
	[ "$(uci -q get "network.$p.public_key")" = "$AWG_WARP_PEER" ] && warp=1
	host="$(uci -q get "network.$p.endpoint_host")"; port="$(uci -q get "network.$p.endpoint_port")"
	case "$host" in *:*) ep="[$host]:$port" ;; *) ep="$host:$port" ;; esac
	[ "$warp" = 1 ] && _awg_valid_ep "$ep" || ep="engage.cloudflareclient.com:4500"
	route="$(uci -q get "network.$p.route_allowed_ips")"; [ "$route" = 1 ] || route=0
	G_PRIV=""; G_PEER=""; G_V4=""; G_V6=""
	_awg_say "Новые ключи WARP для $i"
	_awg_keys_get "$i" || { echo "ОШИБКА: ключи не получены — ни один источник не ответил"; return 1; }
	_awg_say "Ключи получены, адрес $G_V4"
	if [ "$warp" = 1 ]; then
		[ -n "$(_awg_uci_conf "$i")" ] && have=1
	fi
	{
		echo "[Interface]"
		echo "PrivateKey = $G_PRIV"
		echo "Address = $G_V4${G_V6:+, $G_V6}"
		echo "MTU = $(uci -q get "network.$i.mtu" || echo 1280)"
		if [ "$have" = 1 ]; then
			_awg_uci_conf "$i"
		else
			AWG_NO_I1=0
			if _awg_installed; then
				_st_awg_loaded || modprobe amneziawg >/dev/null 2>&1
				_awg_try "$AWG_TEST_IF" "$G_PRIV" "$G_V4" "$ep" "$MIXOMO_AWG_I1" "$G_PEER" >&2
				rc=$?
				_awg_try_down "$AWG_TEST_IF" >&2
				if [ "$rc" = 0 ]; then _awg_say "Проверка: точка $ep отвечает" >&2; else _rb_warn "Точка $ep не ответила — после создания подберите точку входа" >&2; fi
			fi
			printf '%s\n' "Jc = $MIXOMO_AWG_JC" "Jmin = $MIXOMO_AWG_JMIN" "Jmax = $MIXOMO_AWG_JMAX" "S1 = $MIXOMO_AWG_S1" "S2 = $MIXOMO_AWG_S2" \
				"H1 = $MIXOMO_AWG_H1" "H2 = $MIXOMO_AWG_H2" "H3 = $MIXOMO_AWG_H3" "H4 = $MIXOMO_AWG_H4"
			[ "$AWG_NO_I1" = 1 ] || echo "I1 = $MIXOMO_AWG_I1"
		fi
		echo ""
		echo "[Peer]"
		echo "PublicKey = $G_PEER"
		echo "AllowedIPs = 0.0.0.0/0, ::/0"
		echo "Endpoint = $ep"
		echo "PersistentKeepalive = 25"
	} > "$f"
	chmod 600 "$f"
	do_awg_create "$i" "$route" 0
}

_awg_steer_n() { case "$1" in zmwarp) echo 1 ;; *) echo "${1#zmwarp}" ;; esac; }

do_awg_steer_replace() {
	local i="$1" n c f="$AWG_DIR/pending.conf" kv="$AWG_RUN/kv" ep host port k v w=0 col
	echo replace > "$AWG_RUN/phase"
	if [ "$i" = "$ST_OWN_IF" ]; then
		mkdir -p "$ST_DIR" "$ST_RUN"
		if _st_warp_ownconf; then
			mv -f "$f" "$ST_DIR/warp.pending"
			do_steer_warp_own
			return
		fi
		mv -f "$f" "$ST_WARP_OWN"; chmod 600 "$ST_WARP_OWN"
		_st_own_keep
		( ST_WARP_IF="$ST_OWN_IF"; _st_warp_own_iface "$ST_WARP_OWN" ) || return 1
		_st_warp_park "$ST_OWN_IF"
		_awg_say "Готово: конфиг сохранён. Он заработает, когда в Steer выберете «Свой конфиг»"
		return 0
	fi
	if _st_warp_own; then
		echo "ОШИБКА: сейчас Steer работает $(_st_warp_ext && echo "через интерфейс $(_st_ext_if)" || echo "на своём конфиге ($ST_OWN_IF)") — автоматические туннели меняются, когда они включены"
		return 1
	fi
	n="$(_awg_steer_n "$i")"; c="$(_st_wconf "$n")"
	_awg_conf_kv "$f" > "$kv"
	[ -n "$(_awg_cv "$kv" interface privatekey)" ] && [ -n "$(_awg_cv "$kv" peer publickey)" ] && [ -n "$(_awg_cv "$kv" interface address)" ] ||
		{ rm -f "$f" "$kv"; echo "ОШИБКА: в конфиге нет PrivateKey, Address или PublicKey"; return 1; }
	ep="$(_awg_cv "$kv" peer endpoint)"
	case "$ep" in \[*\]:*) host="${ep%]:*}"; host="${host#[}"; port="${ep##*]:}" ;; ?*:*) host="${ep%:*}"; port="${ep##*:}" ;; esac
	[ -n "$host" ] || host="$(uci -q get "network.${i}_peer.endpoint_host")"
	[ -n "$port" ] || port="$(uci -q get "network.${i}_peer.endpoint_port")"
	mkdir -p "$ST_DIR"
	cp "$f" "$c"; chmod 600 "$c"
	_awg_say "Записываем конфиг в туннель Steer $i"
	_st_with "$n" _st_warp_iface_write "${host:-162.159.192.1}" "${port:-2408}"
	_awg_iface_set "$f" "$i"
	uci -q delete "network.$i.auto"
	uci commit network
	rm -f "$f" "$kv"
	ubus call network reload >/dev/null 2>&1
	sleep 2
	ubus call "network.interface.$i" up >/dev/null 2>&1
	while [ "$w" -lt 20 ]; do
		_st_warp_alive_if "$i" && break
		[ -d "/sys/class/net/$i" ] || sleep 1
		ping -I "$i" -c 1 -W 1 1.1.1.1 >/dev/null 2>&1
		w=$((w + 1))
	done
	if _st_warp_alive_if "$i"; then
		col="$(_st_colo_of "$i")"
		if [ -s "$ST_WARP_UP" ]; then
			{ while read -r x cc; do [ "$x" = "$i" ] || echo "$x $cc"; done < "$ST_WARP_UP"; echo "$i ${col:-?}"; } > "$ST_WARP_UP.tmp"
			mv "$ST_WARP_UP.tmp" "$ST_WARP_UP"
		fi
		_st_kick >/dev/null 2>&1
		_awg_say "Готово: $i работает${col:+, сервер $col}"
	else
		echo "!! $i: конфиг записан, но сервер не отвечает — проверьте точку входа или нажмите «Новый WARP»"
	fi
}

do_awg_steer_regen() {
	echo regen > "$AWG_RUN/phase"
	_job_alive steer && { echo "ОШИБКА: на странице Steer идёт операция — дождитесь её окончания"; return 1; }
	_st_warp_fix "$(_awg_steer_n "$1")" keys || return 1
	_st_kick >/dev/null 2>&1
	_awg_say "Готово: у $1 новые ключи WARP"
}

_awg_export() {
	local i="$1" p a k v
	p="$(_awg_peer_sec "$i")"
	echo "[Interface]"
	echo "PrivateKey = $(uci -q get "network.$i.private_key")"
	echo "Address = $(uci -q get "network.$i.addresses" | sed 's/ /, /g')"
	v="$(uci -q get "network.$i.mtu")"; [ -n "$v" ] && echo "MTU = $v"
	_awg_uci_conf "$i"
	echo ""
	echo "[Peer]"
	echo "PublicKey = $(uci -q get "network.$p.public_key")"
	v="$(uci -q get "network.$p.preshared_key")"; [ -n "$v" ] && echo "PresharedKey = $v"
	echo "AllowedIPs = $(uci -q get "network.$p.allowed_ips" | sed 's/ /, /g')"
	a="$(uci -q get "network.$p.endpoint_host")"
	case "$a" in *:*) a="[$a]" ;; esac
	echo "Endpoint = $a:$(uci -q get "network.$p.endpoint_port")"
	v="$(uci -q get "network.$p.persistent_keepalive")"; [ -n "$v" ] && echo "PersistentKeepalive = $v"
}

_awg_delete() {
	local i="$1" p z
	_awg_down "$i"
	for p in $(uci -q -X show network | sed -n "s/^network\.\([^.=]*\)=amneziawg_$i\$/\1/p"); do uci -q delete "network.$p"; done
	uci -q delete "network.$i"
	uci commit network
	if [ "$(uci -q get "firewall.zmawg_$i")" = zone ]; then
		uci -q delete "firewall.zmawg_$i"; uci -q delete "firewall.zmawg_${i}_fwd"
	else
		for z in $(uci -q -X show firewall | sed -n "s/^firewall\.\([^.=]*\)=zone\$/\1/p"); do
			case " $(uci -q get "firewall.$z.network") " in *" $i "*) uci -q del_list "firewall.$z.network=$i" ;; esac
		done
	fi
	uci commit firewall
	/etc/init.d/firewall reload >/dev/null 2>&1
	ubus call network reload >/dev/null 2>&1
	sed -i "/^$i\$/d" "$AWG_DIR/owned" 2>/dev/null
}

_awg_check_name() {
	_zm_re "$1" '^[a-z][a-z0-9_]{0,10}$' || { echo '{"error":"имя: латиница в нижнем регистре, цифры и _, начинается с буквы, до 11 символов"}'; return 1; }
	_awg_is_steer "$1" && { echo '{"error":"имена zmwarp заняты туннелями Steer"}'; return 1; }
	case "$1" in lan|wan|wan6|loopback) echo '{"error":"это имя занято системным интерфейсом"}'; return 1 ;; esac
	return 0
}

awg_action() {
	local action="$1" mode="$2" i name route fw conf ep
	case "$action" in
		install|update|remove|gen|create|pick|replace|regen)
			_job_alive awg && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			_job_alive steer && { echo '{"error":"на странице Steer идёт операция — дождитесь её окончания"}'; return 1; }
			;;
	esac
	case "$action" in
		install) job_start awg do_awg_install ;;
		update)  job_start awg do_awg_install update ;;
		remove)
			_st_warp_on && { echo '{"error":"AmneziaWG нужен WARP в Steer — уберите WARP: Steer → вкладка «Настройки» → «Подключения Steer» → «Убрать WARP». Сам Steer удалять не нужно"}'; return 1; }
			ep=""
			for i in $(_awg_ifaces); do
				if _awg_is_steer "$i"; then
					[ -s "$ST_OWNED" ] && { echo '{"error":"туннели WARP для Steer ещё настроены — уберите их: Steer → вкладка «Настройки» → «Подключения Steer» → «Убрать WARP»"}'; return 1; }
				else
					_awg_owned "$i" || ep="$ep $i"
				fi
			done
			[ -n "$ep" ] && [ "$mode" != all ] && { printf '{"error":"%s"}\n' "$(esc "туннели${ep} созданы не панелью — отметьте их в окне удаления или удалите сами (Сеть → Интерфейсы)")"; return 1; }
			_job_running forkop && { echo '{"error":"на вкладке Forkozz идёт операция — дождитесь её окончания"}'; return 1; }
			job_start awg do_awg_remove "$mode"
			;;
		gen)
			_job_running mixomo_warp && { echo '{"error":"на вкладке Mixomo → WARP идёт генерация — дождитесь её окончания"}'; return 1; }
			i="${mode%%|*}"; ep="${mode#*|}"
			case "$i" in
				std)
					[ "$ep" = default ] && ep="engage.cloudflareclient.com:4500"
					[ "$ep" = auto ] || _awg_valid_ep "$ep" || { echo '{"error":"endpoint: адрес:порт, например 162.159.192.1:2408"}'; return 1; }
					job_start awg do_awg_gen std "$ep" ;;
				check)
					_awg_installed || { echo '{"error":"для проверки связи нужен AmneziaWG — установите его выше"}'; return 1; }
					job_start awg do_awg_gen check ;;
				*) echo '{"error":"неизвестный способ"}'; return 1 ;;
			esac
			;;
		conf_get) mixomo_warp_status ;;
		fix_set) _awf_set "$mode" ;;
		fix_skip) _awf_skip "$mode" ;;
		fix_reset)
			[ -s "$AWF_STATE" ] && awk '{ print $1, $2, 0, 0, ($5 == "" ? "dead" : $5) }' "$AWF_STATE" > "$AWF_STATE.$$" && mv -f "$AWF_STATE.$$" "$AWF_STATE"
			_awf_say "попытки сброшены вручную"
			( _awf_tick >/dev/null 2>&1 & )
			printf '{"ok":true}\n' ;;
		fix_tick) _awf_tick ;;
		conf_set) mixomo_warp_config_set "$mode" ;;
		create)
			name="${mode%%|*}"; mode="${mode#*|}"
			route="${mode%%|*}"; mode="${mode#*|}"
			fw="${mode%%|*}"; conf="${mode#*|}"
			_awg_check_name "$name" || return 1
			case "$route$fw" in [01][01]) ;; *) echo '{"error":"неверные параметры"}'; return 1 ;; esac
			if [ -n "$(uci -q get "network.$name")" ] && [ "$(uci -q get "network.$name.proto")" != amneziawg ]; then
				echo '{"error":"интерфейс с таким именем уже есть и это не AmneziaWG"}'; return 1
			fi
			printf '%s\n' "$conf" | grep -qi '^[[:space:]]*\[interface\]' || { echo '{"error":"в конфигурации нет секции [Interface]"}'; return 1; }
			printf '%s\n' "$conf" | grep -qi '^[[:space:]]*\[peer\]' || { echo '{"error":"в конфигурации нет секции [Peer]"}'; return 1; }
			mkdir -p "$AWG_DIR"
			printf '%s\n' "$conf" | tr -d '\r' > "$AWG_DIR/pending.conf"
			chmod 600 "$AWG_DIR/pending.conf"
			job_start awg do_awg_create "$name" "$route" "$fw"
			;;
		replace)
			i="${mode%%|*}"; conf="${mode#*|}"
			[ "$(uci -q get "network.$i.proto")" = amneziawg ] || { echo '{"error":"нет такого интерфейса"}'; return 1; }
			if _awg_is_steer "$i"; then
				printf '%s\n' "$conf" | grep -qi '^[[:space:]]*\[peer\]' || { echo '{"error":"в конфигурации нет секции [Peer]"}'; return 1; }
				mkdir -p "$AWG_DIR"
				printf '%s\n' "$conf" | tr -d '\r' > "$AWG_DIR/pending.conf"
				chmod 600 "$AWG_DIR/pending.conf"
				job_start awg do_awg_steer_replace "$i"
				return
			fi
			printf '%s\n' "$conf" | grep -qi '^[[:space:]]*\[interface\]' || { echo '{"error":"в конфигурации нет секции [Interface]"}'; return 1; }
			printf '%s\n' "$conf" | grep -qi '^[[:space:]]*\[peer\]' || { echo '{"error":"в конфигурации нет секции [Peer]"}'; return 1; }
			route="$(uci -q get "network.$(_awg_peer_sec "$i").route_allowed_ips")"; [ "$route" = 1 ] || route=0
			mkdir -p "$AWG_DIR"
			printf '%s\n' "$conf" | tr -d '\r' > "$AWG_DIR/pending.conf"
			chmod 600 "$AWG_DIR/pending.conf"
			job_start awg do_awg_create "$i" "$route" 0
			;;
		regen)
			[ "$(uci -q get "network.$mode.proto")" = amneziawg ] || { echo '{"error":"нет такого интерфейса"}'; return 1; }
			if _awg_is_steer "$mode"; then job_start awg do_awg_steer_regen "$mode"; return; fi
			job_start awg do_awg_regen "$mode"
			;;
		pick)
			[ "$(uci -q get "network.$mode.proto")" = amneziawg ] || { echo '{"error":"нет такого интерфейса"}'; return 1; }
			_awg_is_steer "$mode" && { echo '{"error":"точки туннелей Steer подбираются на странице Steer"}'; return 1; }
			job_start awg do_awg_pick_sync "$mode"
			;;
		endpoint)
			i="${mode%%|*}"; ep="${mode#*|}"
			[ "$(uci -q get "network.$i.proto")" = amneziawg ] || { echo '{"error":"нет такого интерфейса"}'; return 1; }
			_awg_is_steer "$i" && { echo '{"error":"точки туннелей Steer меняются на странице Steer"}'; return 1; }
			_awg_valid_ep "$ep" || { echo '{"error":"точка входа: адрес:порт, например 162.159.192.1:2408"}'; return 1; }
			name="$(_awg_peer_sec "$i")"
			case "$ep" in \[*\]:*) route="${ep%]:*}"; route="${route#[}" ;; *) route="${ep%:*}" ;; esac
			uci set "network.$name.endpoint_host=$route"
			uci set "network.$name.endpoint_port=${ep##*:}"
			uci commit network
			ifup "$i" >/dev/null 2>&1
			_st_uses_if "$i" && ( sleep 3; _awg_steer_sync "$i" ) >/dev/null 2>&1 &
			printf '{"ok":true}\n'
			;;
		restart|up|down)
			[ "$(uci -q get "network.$mode.proto")" = amneziawg ] || { echo '{"error":"нет такого интерфейса"}'; return 1; }
			case "$action" in
				restart|up)
					[ "$action" = up ] && { uci -q delete "network.$mode.auto"; uci commit network; }
					ifup "$mode" >/dev/null 2>&1
					_st_uses_if "$mode" && ( sleep 3; _awg_steer_sync "$mode" ) >/dev/null 2>&1 & ;;
				down)
					_awg_is_steer "$mode" && { echo '{"error":"туннели Steer выключаются на странице Steer"}'; return 1; }
					_st_uses_if "$mode" && { printf '{"error":"%s"}\n' "$(esc "через $mode работают сервисы Steer. Сначала выберите в Steer другой режим WARP или другое подключение секции")"; return 1; }
					_awg_fk_live "$mode" && { printf '{"error":"%s"}\n' "$(esc "через туннель $mode сейчас работает $(_fk_name). Сначала выключите $(_fk_name) или выберите в нём другое подключение")"; return 1; }
					uci set "network.$mode.auto=0"; uci commit network; _awg_down "$mode" ;;
			esac
			printf '{"ok":true}\n'
			;;
		test)
			[ "$(uci -q get "network.$mode.proto")" = amneziawg ] || { echo '{"error":"нет такого интерфейса"}'; return 1; }
			local tr colo ip warp age seen="" city="" loss="" rtt="" torn=""
			age="$(_awg_hs_age "$mode")"
			tr="$(curl -s --interface "$mode" --connect-timeout 4 --max-time 6 https://www.cloudflare.com/cdn-cgi/trace 2>/dev/null)"
			[ -n "$tr" ] || tr="$(curl -s --interface "$mode" --connect-timeout 4 --max-time 6 https://1.1.1.1/cdn-cgi/trace 2>/dev/null)"
			colo="$(printf '%s\n' "$tr" | sed -n 's/^colo=//p')"; ip="$(printf '%s\n' "$tr" | sed -n 's/^ip=//p')"; warp="$(printf '%s\n' "$tr" | sed -n 's/^warp=//p')"
			if [ -z "$ip" ]; then
				tr="$(curl -s --interface "$mode" --connect-timeout 3 --max-time 5 https://ipinfo.io/json 2>/dev/null)"
				ip="$(printf '%s' "$tr" | jsonfilter -e '@.ip' 2>/dev/null)"
				[ -n "$ip" ] && seen="$(printf '%s' "$tr" | jsonfilter -e '@.country' 2>/dev/null)"
			fi
			if [ -z "$ip" ]; then
				ip="$(curl -s --interface "$mode" --connect-timeout 3 --max-time 5 https://api.ipify.org 2>/dev/null | grep -Eo '^[0-9a-fA-F.:]{3,45}$' | head -n1)"
			fi
			if [ -n "$ip" ]; then
				set -- $(_cf_meta "$mode")
				if [ $# -ge 4 ]; then
					[ -n "$colo" ] || colo="$1"
					[ "$2" != - ] && [ -z "$seen" ] && seen="$2"
					shift 3; [ "$*" != - ] && city="$*"
				fi
				set -- $(_st_warp_probe "$mode"); loss="$1"; rtt="$2"; torn="$3"
				[ "$loss" -ge 100 ] 2>/dev/null && { loss=""; rtt=""; torn=""; }
			fi
			printf '{"ok":%s,"hs_age":"%s","colo":"%s","city":"%s","seen":"%s","ip":"%s","warp":"%s","loss":"%s","rtt":"%s","torn":%s}\n' "$([ -n "$ip" ] && echo true || echo false)" "$age" "$(esc "$colo")" "$(esc "$city")" "$(esc "$seen")" "$(esc "$ip")" "$(esc "$warp")" "$loss" "$rtt" "$([ "$torn" = 1 ] && echo true || echo false)"
			;;
		export)
			[ "$(uci -q get "network.$mode.proto")" = amneziawg ] || { echo '{"error":"нет такого интерфейса"}'; return 1; }
			printf '{"content":"%s"}\n' "$(esc_ml "$(_awg_export "$mode")")"
			;;
		delete)
			[ "$(uci -q get "network.$mode.proto")" = amneziawg ] || { echo '{"error":"нет такого интерфейса"}'; return 1; }
			_awg_is_steer "$mode" && { echo '{"error":"туннели Steer удаляются вместе со Steer на его странице"}'; return 1; }
			_st_uses_if "$mode" && { printf '{"error":"%s"}\n' "$(esc "через $mode работают сервисы Steer. Сначала выберите в Steer другой режим WARP или другое подключение секции")"; return 1; }
			_awg_fk_live "$mode" && { printf '{"error":"%s"}\n' "$(esc "через туннель $mode сейчас работает $(_fk_name). Сначала выключите $(_fk_name) или выберите в нём другое подключение")"; return 1; }
			_awg_delete "$mode"
			printf '{"ok":true}\n'
			;;
		mihomo)
			[ -s "$MIXOMO_WARP_CONF" ] || { echo '{"error":"сначала получите WARP.conf"}'; return 1; }
			mixomo_warp_integrate_action
			;;
		*) echo '{"error":"неизвестное действие"}' ;;
	esac
}

_term_say() { echo "==> $*"; }
_term_installed() { [ -x /usr/bin/ttyd ]; }
_term_running() { pidof ttyd >/dev/null 2>&1; }
_term_enabled() { ls /etc/rc.d/S*ttyd >/dev/null 2>&1; }
_term_version() { ttyd --version 2>/dev/null | head -n1 | awk '{ print $NF }'; }
_term_port() {
	local p
	p="$(uci -q get 'ttyd.@ttyd[0].port' 2>/dev/null)"
	case "$p" in ''|*[!0-9]*) p=7681 ;; esac
	echo "$p"
}

TERM_ALL="$ZM_STATE_DIR/ttyd.all"
_term_iface() { uci -q get 'ttyd.@ttyd[0].interface'; }
_term_mode() {
	local i
	i="$(_term_iface)"
	case "$i" in
		'') [ -f "$TERM_ALL" ] && echo all || echo home ;;
		@lan|br-lan) echo home ;;
		@tailscale|tailscale0) echo ts ;;
		*) echo other ;;
	esac
}

_term_all_guard() {
	[ -f "$TERM_ALL" ] || return 1
	[ -z "$(_term_iface)" ] || { rm -f "$TERM_ALL"; return 1; }
	_tsc_wan_closed && return 1
	uci -q set 'ttyd.@ttyd[0].interface=@lan'; uci -q commit ttyd
	rm -f "$TERM_ALL"
	logger -t zapret-manager "Терминал: вход из интернета в firewall открыт — терминал снова только для домашней сети"
	return 0
}

_term_set_mode() {
	_term_config
	case "$1" in
		all)
			_tsc_wan_closed || { echo "вход из интернета в firewall не закрыт — открыть терминал на всех интерфейсах небезопасно"; return 1; }
			uci -q delete 'ttyd.@ttyd[0].interface'
			mkdir -p "$ZM_STATE_DIR"; : > "$TERM_ALL" ;;
		home)
			uci -q set 'ttyd.@ttyd[0].interface=@lan'
			rm -f "$TERM_ALL" ;;
		*) echo "неизвестный режим"; return 1 ;;
	esac
	uci -q commit ttyd
	_term_running && /etc/init.d/ttyd restart >/dev/null 2>&1
	return 0
}

_term_config() {
	[ -f /etc/config/ttyd ] || : > /etc/config/ttyd
	uci -q get 'ttyd.@ttyd[0]' >/dev/null 2>&1 || uci -q add ttyd ttyd >/dev/null 2>&1
	_term_all_guard
	[ -n "$(_term_iface)" ] || [ -f "$TERM_ALL" ] || uci -q set 'ttyd.@ttyd[0].interface=@lan'
	[ -n "$(uci -q get 'ttyd.@ttyd[0].port')" ] || uci -q set 'ttyd.@ttyd[0].port=7681'
	[ -n "$(uci -q get 'ttyd.@ttyd[0].command')" ] || uci -q set 'ttyd.@ttyd[0].command=/bin/login'
	uci -q commit ttyd
}

_term_start() {
	local t=0
	_term_installed || { echo "ОШИБКА: терминал не установлен"; return 1; }
	_term_config
	rm -f "$ZM_STATE_DIR/ttyd.htop"
	/etc/init.d/ttyd enable >/dev/null 2>&1
	/etc/init.d/ttyd restart >/dev/null 2>&1
	while [ "$t" -lt 10 ]; do
		_term_running && break
		sleep 1; t=$((t + 1))
	done
	_term_running || { echo "ОШИБКА: ttyd не запустился"; return 1; }
	return 0
}

_term_stop() {
	[ -x /etc/init.d/ttyd ] && { /etc/init.d/ttyd stop >/dev/null 2>&1; /etc/init.d/ttyd disable >/dev/null 2>&1; }
	_term_running && { killall ttyd >/dev/null 2>&1; sleep 1; killall -9 ttyd >/dev/null 2>&1; }
	return 0
}

term_status() {
	local inst=false run=false en=false
	_term_installed && inst=true
	_term_running && run=true
	_term_enabled && en=true
	printf '{"installed":%s,"running":%s,"enabled":%s,"version":"%s","port":%s,"lan_ip":"%s","mode":"%s","iface":"%s","ts":%s,"ts_ip":"%s","wan_closed":%s,"job":%s}\n' \
		"$inst" "$run" "$en" "$(esc "$(_term_version)")" "$(_term_port)" "$(esc "$(_zm_lan_ip)")" \
		"$(_term_mode)" "$(esc "$(_term_iface)")" "$(_tsc_installed && echo true || echo false)" \
		"$(esc "$(_tsc_running && _zm_tmo 5 tailscale ip -4 2>/dev/null | head -n1)")" \
		"$(_tsc_wan_closed && echo true || echo false)" \
		"$(_job_alive term && echo true || echo false)"
}

do_term_install() {
	_ensure_deps
	_term_say "Устанавливаем терминал (ttyd)"
	$UPDATE || echo "!! Список пакетов не обновился — пробуем с тем, что есть"
	$INSTALL ttyd || { echo "ОШИБКА: ttyd не установился — проверьте интернет и доступность пакета для вашей прошивки"; return 1; }
	_term_installed || { echo "ОШИБКА: файла /usr/bin/ttyd нет — пакет встал не полностью"; return 1; }
	_term_say "Запускаем терминал"
	_term_start || return 1
	echo "   ✓ Терминал работает: порт $(_term_port), только домашняя сеть"
	_term_say "Готово: терминал ttyd $(_term_version)"
}

do_term_remove() {
	_term_say "Останавливаем терминал"
	_term_stop
	echo "   ✓ Терминал остановлен и убран из автозапуска"
	_term_say "Удаляем ttyd"
	local rc=0
	_zm_pkg_wipe luci-i18n-ttyd-ru luci-app-ttyd ttyd || rc=1
	_zm_wipe /etc/config/ttyd /etc/config/ttyd-opkg /etc/config/ttyd.apk-new /etc/init.d/ttyd /etc/rc.d/*ttyd || rc=1
	rm -f "$TERM_ALL"
	_zm_rm_listed terminal || rc=1
	rm -f /tmp/luci-indexcache* /tmp/luci-modulecache/* 2>/dev/null
	_term_installed && rc=1
	_zm_rm_done "$rc" "Терминал"
}

term_action() {
	local a="$1" j
	case "$a" in
		install|remove)
			_job_alive term && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			if j="$(_zm_busy_job)"; then printf '{"error":"%s"}\n' "$(esc "Сейчас идёт операция: $j — дождитесь её окончания")"; return 1; fi
			case "$a" in
				install) job_start term do_term_install ;;
				remove)  job_start term do_term_remove ;;
			esac ;;
		start|restart)
			_term_installed || { echo '{"error":"терминал не установлен"}'; return 1; }
			_job_alive term && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			_term_start >/dev/null 2>&1 || { echo '{"error":"ttyd не запустился — смотрите журнал роутера"}'; return 1; }
			printf '{"ok":true}\n' ;;
		ts_on|ts_off)
			_term_installed || { echo '{"error":"терминал не установлен"}'; return 1; }
			_job_alive term && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			if j="$(_term_set_mode "$([ "$a" = ts_on ] && echo all || echo home)")"; then printf '{"ok":true,"mode":"%s"}\n' "$(_term_mode)"
			else printf '{"error":"%s"}\n' "$(esc "$j")"; return 1; fi ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
}

TSC_DIR="$ZM_STATE_DIR/tailscale"
TSC_ON="$TSC_DIR/on"
TSC_STOP="$TSC_DIR/stopped"
TSC_NOEXIT="$TSC_DIR/noexit"
TSC_LAN="$TSC_DIR/lan"
TSC_LS_PREV="$TSC_DIR/localservice"
TSC_ZR_OWN="$TSC_DIR/zapret.own"
TSC_STATE="$TSC_DIR/state"
TSC_SRV="$TSC_DIR/server"
TSC_KEY="$TSC_DIR/authkey"
TSC_DEV="tailscale0"
TSC_NET="tailscale"
TSC_FW_RULE="zm_tailscale"
TSC_NFT="/usr/share/nftables.d/chain-pre/forward/30-zm-tailscale.nft"
TSC_HOOK="/usr/libexec/zm-tailscale-tgws"
TSC_SYSCTL="/etc/sysctl.d/90-zm-tailscale.conf"
TSC_UPLOG="$JOBS_DIR/tsc.up.log"
TSC_NEED_KB=10240

_tsc_say() { echo "==> $*"; }
_tsc_installed() { [ -x /usr/sbin/tailscaled ] && [ -e /usr/sbin/tailscale ]; }
_tsc_running() { pidof tailscaled >/dev/null 2>&1; }
_tsc_enabled() { ls /etc/rc.d/S*tailscale >/dev/null 2>&1; }
TSC_SOCK="/var/run/tailscale/tailscaled.sock"
_tsc_api() {
	local o
	[ -S "$TSC_SOCK" ] && _zm_has curl || return 1
	o="$(curl -sf --max-time 6 --unix-socket "$TSC_SOCK" "http://local-tailscaled.sock/localapi/v0/$1" 2>/dev/null)" || return 1
	case "$o" in '{'*) printf '%s\n' "$o" ;; *) return 1 ;; esac
}
_tsc_ver() {
	local f="$TSC_DIR/version" k v
	k="$(ls -ilL /usr/sbin/tailscaled 2>/dev/null | awk 'NR == 1 && $1 ~ /^[0-9]+$/ { print $1 ":" $6 }')"
	[ -n "$k" ] && k="$k:$(date -r /usr/sbin/tailscaled +%s 2>/dev/null)"
	if [ -n "$k" ] && [ -s "$f" ]; then
		read -r v 2>/dev/null < "$f"
		[ "${v%% *}" = "$k" ] && { printf '%s\n' "${v#* }"; return 0; }
	fi
	v="$(tailscale version 2>/dev/null | head -n1)"
	[ -n "$v" ] && [ -n "$k" ] && { mkdir -p "$TSC_DIR"; printf '%s %s\n' "$k" "$v" > "$f" 2>/dev/null; }
	printf '%s\n' "$v"
}
_tsc_json() { _tsc_api status || _zm_tmo 8 tailscale status --json 2>/dev/null; }
_tsc_free_kb() { df -k /overlay 2>/dev/null | awk 'NR == 2 { print $4; exit }'; }
_tsc_port() { local p; p="$(uci -q get tailscale.settings.port)"; case "$p" in ''|*[!0-9]*) echo 41641 ;; *) echo "$p" ;; esac; }

_tsc_lan_cidr() {
	local d a=""
	for d in $(_zm_lan_devs); do
		[ "$d" = "$TSC_DEV" ] && continue
		a="$(ip -4 -o addr show dev "$d" 2>/dev/null | awk '{ print $4; exit }')"
		[ -n "$a" ] && break
	done
	[ -n "$a" ] || return 1
	awk -v a="$a" 'BEGIN {
		split(a, p, "/"); split(p[1], o, "."); m = (p[2] == "" ? 32 : p[2] + 0)
		ip = ((o[1] * 256 + o[2]) * 256 + o[3]) * 256 + o[4]; s = 2 ^ (32 - m); n = int(ip / s) * s
		printf "%d.%d.%d.%d/%d\n", int(n / 16777216) % 256, int(n / 65536) % 256, int(n / 256) % 256, n % 256, m
	}'
}

_tsc_hostname() {
	local h c
	h="$(uci -q get system.@system[0].hostname)"
	[ -n "$h" ] || h="$(cat /proc/sys/kernel/hostname 2>/dev/null)"
	[ -n "$h" ] || return 1
	c="$(printf '%s' "$h" | tr -c 'A-Za-z0-9-' '-' | sed 's/--*/-/g; s/^-//; s/-$//' | cut -c1-63)"
	[ -n "$c" ] || c=openwrt
	[ "$c" != "$h" ] && echo "$c"
}

_tsc_flags() {
	local e=true r="" h
	[ -f "$TSC_NOEXIT" ] && e=false
	[ -f "$TSC_LAN" ] && r="$(_tsc_lan_cidr)"
	printf -- '--accept-dns=false --advertise-exit-node=%s --advertise-routes=%s' "$e" "$r"
	h="$(_tsc_hostname)" && printf -- ' --hostname=%s' "$h"
	return 0
}

_tsc_srv() { cat "$TSC_SRV" 2>/dev/null; }
_tsc_kind() {
	case "$(_tsc_srv)" in
		'') echo official ;;
		*://rc.routerich.ru|*://rc.routerich.ru/*) echo routerich ;;
		*) echo custom ;;
	esac
}
_tsc_admin() {
	case "$(_tsc_kind)" in
		official) echo "https://login.tailscale.com/admin" ;;
		routerich) echo "https://remote.routerich.ru" ;;
	esac
}
_tsc_upflags() {
	local s
	s="$(_tsc_srv)"
	printf '%s --netfilter-mode=off' "$(_tsc_flags)"
	[ -n "$s" ] && printf ' --login-server=%s' "$s"
	return 0
}

TSC_GH_BASES="https://raw.githubusercontent.com/gunanovo/openwrt-tailscale/refs/heads/feed https://cdn.jsdelivr.net/gh/gunanovo/openwrt-tailscale@feed"
TSC_LUCI_BASES="https://raw.githubusercontent.com/Tokisaki-Galaxy/luci-app-tailscale-community/gh-pages/all https://tokisaki-galaxy.github.io/luci-app-tailscale-community/all https://cdn.jsdelivr.net/gh/Tokisaki-Galaxy/luci-app-tailscale-community@gh-pages/all"
TSC_SRC="$TSC_DIR/source"

_tsc_arch() {
	local a
	a="$(awk -F\' '/DISTRIB_ARCH/ { print $2 }' /etc/openwrt_release 2>/dev/null)"
	[ -n "$a" ] || a="$(cat /etc/apk/arch 2>/dev/null)"
	[ -n "$a" ] || a="$(opkg print-architecture 2>/dev/null | awk '$2 != "all" && $2 != "noarch" { a = $2 } END { print a }')"
	printf '%s' "$a" | tr -d '\r\n\t '
}

_tsc_fetch() {
	local b
	for b in $3; do
		rm -f "$2"
		_zm_gh_get "$b/$1" "$2" "" "${4:-120}" && _zm_dl_sane "$2" && return 0
	done
	rm -f "$2"
	return 1
}

_tsc_gh_latest() {
	local f="$JOBS_DIR/tsc.ver.$$" v ZM_ARCH_FB=1
	mkdir -p "$JOBS_DIR"
	_tsc_fetch "$(_tsc_arch)/version" "$f" "$TSC_GH_BASES" 15 || return 1
	v="$(head -c 64 "$f" | tr -d ' \r\n')"
	rm -f "$f"
	case "$v" in ''|*[!0-9A-Za-z.-]*) return 1 ;; esac
	echo "$v"
}

_tsc_vnum() { printf '%s' "$1" | sed 's/-r[0-9]*$//; s/[^0-9.].*$//'; }

_tsc_install_gh() {
	local arch ver f sum want got ZM_ARCH_FB=1
	arch="$(_tsc_arch)"
	[ -n "$arch" ] || { echo "   · Не удалось узнать архитектуру роутера"; return 1; }
	echo "   → Архитектура: $arch, ищем сборку на GitHub"
	ver="$(_tsc_gh_latest)" || { echo "   · GitHub не ответил или сборки для $arch нет"; return 1; }
	f="$JOBS_DIR/tailscale-$ver.$RAZ"
	sum="$JOBS_DIR/tailscale.$RAZ.sha256"
	echo "   → Скачиваем Tailscale $ver ($RAZ, около 7 МБ)"
	_tsc_fetch "$arch/tailscale-$ver.$RAZ" "$f" "$TSC_GH_BASES" 300 || { echo "   · Пакет не скачался ни с GitHub, ни с зеркала"; return 1; }
	_tsc_fetch "$arch/$RAZ.sha256" "$sum" "$TSC_GH_BASES" 20 || { rm -f "$f"; echo "   · Не скачалась контрольная сумма"; return 1; }
	want="$(head -c 200 "$sum" | tr -d ' \r\n' | cut -c1-64)"
	got="$(sha256sum "$f" 2>/dev/null | cut -d' ' -f1)"
	rm -f "$sum"
	if [ -z "$want" ] || [ "$want" != "$got" ]; then
		rm -f "$f"; echo "   · Контрольная сумма не сошлась — файл повреждён, ставить не будем"; return 1
	fi
	echo "   ✓ Контрольная сумма сошлась"
	$INSTALL "$f" || { rm -f "$f"; return 1; }
	rm -f "$f"
	_tsc_installed || return 1
	mkdir -p "$TSC_DIR"; echo github > "$TSC_SRC"
	return 0
}

_tsc_install_luci() {
	local idx="$JOBS_DIR/tsc.luci.idx" ver f
	if _tsc_fetch Packages "$idx" "$TSC_LUCI_BASES" 20; then
		ver="$(awk '/^Package: luci-app-tailscale-community$/ { p = 1; next } /^Package:/ { p = 0 } p && /^Version:/ { print $2; exit }' "$idx")"
		rm -f "$idx"
		case "$ver" in ''|*[!0-9A-Za-z.~+-]*) ver="" ;; esac
		if [ -n "$ver" ]; then
			if [ "$RAZ" = apk ]; then f="luci-app-tailscale-community-$ver.apk"; else f="luci-app-tailscale-community_${ver}_all.ipk"; fi
			if _tsc_fetch "$f" "$JOBS_DIR/$f" "$TSC_LUCI_BASES" 120 && $INSTALL "$JOBS_DIR/$f" >/dev/null 2>&1; then
				rm -f "$JOBS_DIR/$f"
				return 0
			fi
			rm -f "$JOBS_DIR/$f"
		fi
	fi
	$INSTALL luci-app-tailscale-community >/dev/null 2>&1
}

_tsc_luci_path() { grep -ho '"admin/[A-Za-z0-9_-]*/tailscale"' /usr/share/luci/menu.d/*.json 2>/dev/null | head -n1 | tr -d '"'; }
_tsc_luci_app() { [ -n "$(_tsc_luci_path)" ]; }

_tsc_uci_sync() {
	local r e l
	uci -q show tailscale >/dev/null 2>&1 || return 0
	uci -q get tailscale.settings >/dev/null || uci set tailscale.settings=settings
	e=1; [ -f "$TSC_NOEXIT" ] && e=0
	uci set tailscale.settings.advertise_exit_node="$e"
	uci set tailscale.settings.dns_mode=disabled
	uci set tailscale.settings.service_enabled="$([ -f "$TSC_STOP" ] && echo 0 || echo 1)"
	uci set tailscale.settings.disable_fw_config=1
	r="$(_tsc_lan_cidr)"
	if [ -n "$r" ]; then
		l="$(uci -q get tailscale.settings.advertise_routes | tr ' ,' '\n\n' | grep . | grep -vxF "$r")"
		[ -f "$TSC_LAN" ] && l="$(printf '%s\n%s' "$l" "$r" | grep .)"
		uci -q delete tailscale.settings.advertise_routes
		for e in $l; do uci add_list tailscale.settings.advertise_routes="$e"; done
	fi
	uci commit tailscale
}

_tsc_start() {
	local t=0
	[ -f "$TSC_STOP" ] && { echo "ОШИБКА: Tailscale остановлен кнопкой «Остановить» — запустите его кнопкой «Запустить»"; return 1; }
	/etc/init.d/tailscale enable >/dev/null 2>&1
	/etc/init.d/tailscale restart >/dev/null 2>&1
	while [ "$t" -lt 20 ]; do
		[ -n "$(_tsc_json | jsonfilter -e '@.BackendState' 2>/dev/null)" ] && { _tsc_prefs >/dev/null 2>&1; return 0; }
		sleep 1; t=$((t + 1))
	done
	echo "ОШИБКА: служба Tailscale не ответила за 20 секунд — смотрите журнал роутера (logread | grep tailscale)"
	return 1
}

_tsc_wan_closed() {
	local s i
	s="$(_zm_zone_sec "$(_zm_wan_zone)")" || return 1
	i="$(uci -q get "firewall.$s.input")"
	[ "$i" = REJECT ] || [ "$i" = DROP ]
}

_tsc_nft_text() {
	printf '%s\n' \
		'# Zapret Manager: Tailscale. Файл создаёт и убирает панель.' \
		'iifname "tailscale0" meta nfproto ipv6 counter reject with icmpv6 type admin-prohibited comment "zm-tailscale: no IPv6"' \
		'iifname "tailscale0" tcp flags syn tcp option maxseg size set 1240 comment "zm-tailscale: MSS"' \
		'oifname "tailscale0" tcp flags syn tcp option maxseg size set 1240 comment "zm-tailscale: MSS"'
}

_tsc_hook_text() {
	cat <<'EOF'
#!/bin/sh
(
	ip="$(/opt/zapret-manager-luci/backend.sh tsc_lan_ip 2>/dev/null | head -n1)"
	[ -n "$ip" ] || ip="$(ifstatus lan 2>/dev/null | jsonfilter -e "@['ipv4-address'][0].address" 2>/dev/null)"
	[ -n "$ip" ] || ip="$(uci -q get network.lan.ipaddr | awk '{ print $1 }' | cut -d/ -f1)"
	[ -n "$ip" ] || ip="$(ip -4 -o addr show dev br-lan 2>/dev/null | awk '{ print $4; exit }' | cut -d/ -f1)"
	case "$ip" in *.*.*.*) ;; *) exit 0 ;; esac
	i=0
	while ! nft list chain inet stgws tgws_redirect >/dev/null 2>&1 || ! nft list chain inet stgws prerouting_mark >/dev/null 2>&1; do
		i=$((i + 1)); [ "$i" -gt 40 ] && exit 0; sleep 1
	done
	for c in prerouting_mark tgws_redirect; do
		nft -a list chain inet stgws "$c" 2>/dev/null | sed -n '/comment "zm-tailscale"/s/.*# handle \([0-9]*\)$/\1/p' |
			while read -r h; do nft delete rule inet stgws "$c" handle "$h"; done
	done
	nft add rule inet stgws prerouting_mark iifname "tailscale0" ip daddr @tg_ip meta mark set meta mark and 0xefffffff or 0x50000000 counter return comment '"zm-tailscale"'
	nft insert rule inet stgws tgws_redirect iifname "tailscale0" meta mark and 0x10000000 == 0x10000000 tcp dport '{ 80, 443, 5222 }' counter dnat ip to "$ip:8490" comment '"zm-tailscale"'
) </dev/null >/dev/null 2>&1 &
EOF
}

_tsc_tg_rules() { nft list table inet stgws 2>/dev/null | grep -c 'comment "zm-tailscale"'; }
_tsc_tg_ip_fix() {
	local ip r
	[ -x "$TSC_HOOK" ] || return 0
	r="$(nft list chain inet stgws tgws_redirect 2>/dev/null | grep 'zm-tailscale')" || return 0
	ip="$(_zm_lan_ip)" || return 0
	printf '%s' "$r" | grep -qF "to $ip:8490" && return 0
	"$TSC_HOOK"
	return 0
}

_tsc_tg_ensure() {
	[ -f "$TSC_ON" ] && [ -f /etc/init.d/tgws ] || return 0
	local t="$TSC_HOOK.zmtmp"
	mkdir -p "${TSC_HOOK%/*}"
	_tsc_hook_text > "$t"
	if cmp -s "$t" "$TSC_HOOK"; then rm -f "$t"; else mv -f "$t" "$TSC_HOOK"; fi
	chmod 0755 "$TSC_HOOK"
	if ! grep -qF "$TSC_HOOK" /etc/init.d/tgws; then
		grep -q 'procd_close_instance' /etc/init.d/tgws || return 1
		awk -v l="	[ -x $TSC_HOOK ] && $TSC_HOOK" '{ print } !d && /procd_close_instance/ { print l; d = 1 }' /etc/init.d/tgws > /etc/init.d/tgws.zmtmp &&
			cat /etc/init.d/tgws.zmtmp > /etc/init.d/tgws
		rm -f /etc/init.d/tgws.zmtmp
	fi
	[ "$(_tsc_tg_rules)" -ge 2 ] 2>/dev/null || "$TSC_HOOK"
	return 0
}

_tsc_tg_drop() {
	local c h
	[ -f /etc/init.d/tgws ] && grep -qF "$TSC_HOOK" /etc/init.d/tgws && sed -i "\#$TSC_HOOK#d" /etc/init.d/tgws
	rm -f "$TSC_HOOK"
	for c in prerouting_mark tgws_redirect; do
		nft -a list chain inet stgws "$c" 2>/dev/null | sed -n '/comment "zm-tailscale"/s/.*# handle \([0-9]*\)$/\1/p' |
			while read -r h; do nft delete rule inet stgws "$c" handle "$h" 2>/dev/null; done
	done
	return 0
}

_tsc_zapret() {
	local f
	for f in /opt/zapret/config /opt/zapret2/config; do
		[ -f "$f" ] || continue
		case "$1" in
			add)
				grep -qE '^IFACE_LAN="?[^" ]' "$f" || continue
				grep '^IFACE_LAN=' "$f" | tr '"' ' ' | grep -qw "$TSC_DEV" && continue
				sed -i "s/^IFACE_LAN=\"\{0,1\}\([^\"]*\)\"\{0,1\}\$/IFACE_LAN=\"\1 $TSC_DEV\"/" "$f"
				mkdir -p "$TSC_DIR"; grep -qxF "$f" "$TSC_ZR_OWN" 2>/dev/null || echo "$f" >> "$TSC_ZR_OWN"
				echo "   ✓ ${f%/config}: интерфейс $TSC_DEV добавлен в IFACE_LAN" ;;
			del)
				grep -qxF "$f" "$TSC_ZR_OWN" 2>/dev/null || continue
				sed -i "/^IFACE_LAN=/s/ $TSC_DEV//" "$f" ;;
		esac
		case "$f" in
			/opt/zapret/*) [ -x /etc/init.d/zapret ] && /etc/init.d/zapret restart >/dev/null 2>&1 ;;
			*) [ -x /etc/init.d/zapret2 ] && /etc/init.d/zapret2 restart >/dev/null 2>&1 ;;
		esac
	done
	[ "$1" = del ] && rm -f "$TSC_ZR_OWN"
	return 0
}

_tsc_fk_has() { uci -q get netshift.settings.source_network_interfaces | tr ' ' '\n' | grep -qx "$TSC_DEV"; }
_tsc_fk() {
	local cur ch=0 d own="$TSC_DIR/forkozz.own" orig want
	uci -q get netshift.settings >/dev/null || return 0
	cur="$(uci -q get netshift.settings.source_network_interfaces)"
	case "$1" in
		add)
			_tsc_fk_has && return 0
			mkdir -p "$TSC_DIR"
			if uci -q get netshift.settings.source_network_interfaces >/dev/null; then orig="list $cur"; else orig="unset"; fi
			[ -n "$cur" ] || uci add_list netshift.settings.source_network_interfaces="br-lan"
			uci add_list netshift.settings.source_network_interfaces="$TSC_DEV"
			printf 'orig=%s\nset=%s\n' "$orig" "$(uci -q get netshift.settings.source_network_interfaces)" > "$own"; ch=1
			echo "   ✓ Forkozz: устройства Tailscale добавлены к домашней сети" ;;
		del)
			[ -f "$own" ] || return 0
			orig="$(sed -n 's/^orig=//p' "$own")"; want="$(sed -n 's/^set=//p' "$own")"
			if [ -n "$want" ] && [ "$cur" = "$want" ] && [ -n "$orig" ]; then
				uci -q delete netshift.settings.source_network_interfaces
				case "$orig" in list\ *) for d in ${orig#list }; do uci add_list netshift.settings.source_network_interfaces="$d"; done ;; esac
				ch=1
				echo "   ✓ Forkozz: источники трафика вернулись к прежним"
			elif _tsc_fk_has; then
				uci -q del_list netshift.settings.source_network_interfaces="$TSC_DEV"; ch=1
				echo "   ✓ Forkozz: устройства Tailscale убраны из источников трафика"
			fi
			rm -f "$own" ;;
	esac
	[ "$ch" = 1 ] || return 0
	uci commit netshift
	return 0
}

_tsc_kick_bypass() {
	local l="$TSC_DIR/kick.lock" w=0
	mkdir -p "$TSC_DIR"
	if [ "$1" = wait ]; then
		while [ -d "$l" ] && [ "$w" -lt 120 ]; do sleep 2; w=$((w + 2)); done
	fi
	find "$TSC_DIR" -maxdepth 1 -name kick.lock -mmin +10 -exec rmdir {} \; 2>/dev/null
	mkdir "$l" 2>/dev/null || { echo "   · Forkozz и Steer уже перезапускаются"; return 0; }
	pidof tailscaled > "$TSC_DIR/kick.pid" 2>/dev/null
	if [ -x /etc/init.d/netshift ] && [ -f /etc/config/netshift ] && /etc/init.d/netshift enabled 2>/dev/null; then
		echo "   → Перезапускаем Forkozz, чтобы он подхватил изменения сети"
		_zm_run 180 /etc/init.d/netshift restart >/dev/null 2>&1
	fi
	_tsc_steer_kick
	rmdir "$l" 2>/dev/null
	return 0
}
_tsc_kick_bg() { ( _tsc_kick_bypass ) </dev/null >/dev/null 2>&1 & }

_tsc_steer_on() { _st_installed && [ ! -f "$ST_OFF" ] && _st_owns "steer-spec" && [ -z "$(_st_blocker)" ]; }

_tsc_steer_kick() {
	_tsc_steer_on || return 0
	_job_alive steer && { echo "   · Steer сейчас занят — устройства Tailscale попадут в его правила при следующем применении"; return 0; }
	echo "==> Steer: обновляем правила для устройств Tailscale"
	_st_respec
	return 0
}

_st_lan_devs() {
	local out d i outd
	out="$(_zm_lan_devs)"
	if [ -f "$TSC_ON" ]; then case " $out " in *" $TSC_DEV "*) ;; *) out="$out $TSC_DEV" ;; esac; fi
	outd=" $(_st_out_tun_devs | tr '\n' ' ') "
	for d in $(_st_lan_extra); do
		case "$outd" in *" $d "*) continue ;; esac
		if [ "$d" = "$ST_PPP_SRV" ]; then
			i=0
			while [ "$i" -lt "$ST_PPP_N" ]; do case " $out " in *" ppp$i "*) ;; *) out="$out ppp$i" ;; esac; i=$((i + 1)); done
			continue
		fi
		[ -d "/sys/class/net/$d" ] || _st_tun_srcdev "$d" >/dev/null || continue
		case " $out " in *" $d "*) ;; *) out="$out $d" ;; esac
	done
	echo $out
}
ST_PPP_SRV="ppp+"
ST_PPP_N=16
_st_ppp_server() {
	local w=""
	{ [ -x /usr/sbin/pptpd ] || [ -s /etc/config/pptpd ]; } && w="$w PPTP"
	[ -x /usr/sbin/xl2tpd ] && w="$w L2TP"
	{ [ -x /usr/sbin/sstpd ] || [ -x /usr/bin/sstpd ]; } && w="$w SSTP"
	[ -x /usr/sbin/accel-pppd ] && w="$w accel-ppp"
	[ -z "$w" ] && ls /sys/class/net 2>/dev/null | grep -qE '^ppp[0-9]+$' && w=" PPP"
	[ -n "$w" ] && echo ${w# }
}
_st_tun_srcdev() {
	local n
	for n in $(uci -q -X show network | sed -n 's/^network\.\([^.=]*\)=interface$/\1/p'); do
		_zm_tun_kind "$n" >/dev/null && [ "$(_zm_tun_dev "$n")" = "$1" ] && { echo "$n"; return 0; }
	done
	return 1
}
_st_out_tun_devs() {
	local i s
	{ [ "$(cat "$ST_DIR/exit" 2>/dev/null)" = iface ] && _st_main_iface && echo
	  for s in $(_st_secs); do [ "$(_st_sec_kind "$s")" = iface ] && _st_sec_iface "$s" && echo; done; } 2>/dev/null | grep . | awk '!x[$0]++' | while read -r i; do
		_zm_tun_dev "$i"
	done
	_st_warp_ext && _st_ext_if
	return 0
}

ST_LAN_EXTRA="$ST_DIR/lan.extra"
ST_LAN_MAX=8
_st_lan_extra() { [ -s "$ST_LAN_EXTRA" ] || return 0; tr -s ' \t\r' '\n\n\n' < "$ST_LAN_EXTRA" 2>/dev/null | grep -E '^([A-Za-z0-9._-]{1,15}|ppp\+)$' | awk '!x[$0]++'; }
_st_net_dev() {
	local d
	d="$(ifstatus "$1" 2>/dev/null | jsonfilter -e '@.l3_device' 2>/dev/null)"
	[ -n "$d" ] || d="$(ifstatus "$1" 2>/dev/null | jsonfilter -e '@.device' 2>/dev/null)"
	[ -n "$d" ] || d="$(uci -q get "network.$1.device")"
	echo "$d"
}
_st_dev_zone() {
	local z n e
	for z in $(uci -q -X show firewall | sed -n "s/^firewall\.\([^.=]*\)=zone\$/\1/p"); do
		case " $(uci -q get "firewall.$z.device") " in *" $1 "*) uci -q get "firewall.$z.name"; return 0 ;; esac
		if [ "$1" = "$ST_PPP_SRV" ]; then
			for e in $(uci -q get "firewall.$z.device"); do
				case "$e" in pppoe*) ;; ppp*) uci -q get "firewall.$z.name"; return 0 ;; esac
			done
		fi
	done
	[ "$1" = "$ST_PPP_SRV" ] && return 1
	for n in $(uci -q -X show network | sed -n 's/^network\.\([^.=]*\)=interface$/\1/p'); do
		[ "$(_st_net_dev "$n")" = "$1" ] && _zm_zone_of_net "$n" && return 0
	done
	n="$(_st_tun_srcdev "$1")" && _zm_zone_of_net "$n" && return 0
	return 1
}
_st_out_zones() {
	local i z lz wz
	lz="$(_zm_lan_zone)"; wz="$(_zm_wan_zone)"
	[ "$(uci -q get "firewall.$ST_WARP_ZONE")" = zone ] && echo "$ST_WARP_ZONE"
	[ "$(uci -q get "firewall.$ST_VPN_ZONE")" = zone ] && echo "$ST_VPN_ZONE"
	{ _st_tun_ifaces; _st_warp_ext && echo "$ST_WIF1"; } 2>/dev/null | while read -r i; do
		[ -n "$i" ] || continue
		z="$(_zm_zone_of_net "$i")"
		[ -n "$z" ] && [ "$z" != "$lz" ] && [ "$z" != "$wz" ] && echo "$z"
	done
}
_st_lan_fw() {
	local d z lz dz r keep="" ch=0 zs="" outs
	local wz outd nm
	lz="$(_zm_lan_zone)"; wz="$(_zm_wan_zone)"
	outd=" $(_st_out_tun_devs | tr '\n' ' ') "
	for d in $(_st_lan_extra); do
		nm="$d"; [ "$d" = "$ST_PPP_SRV" ] && nm="клиентов VPN-сервера (ppp…)"
		case "$outd" in *" $d "*) _rb_warn "Через $d идут сервисы Steer — источником трафика она быть не может, Steer её пропускает"; continue ;; esac
		if [ "$d" != "$ST_PPP_SRV" ] && [ ! -d "/sys/class/net/$d" ] && ! _st_tun_srcdev "$d" >/dev/null; then _rb_warn "Сети $d сейчас нет на роутере — Steer её пропускает"; continue; fi
		case " $(_zm_lan_devs) " in *" $d "*) continue ;; esac
		z="$(_st_dev_zone "$d")"
		if [ -z "$z" ]; then
			if [ "$d" = "$ST_PPP_SRV" ]; then _rb_warn "Для $nm нет зоны firewall — туннели Steer для них могут быть закрыты. Добавьте устройство ppp+ в зону (Сеть → Межсетевой экран)"
			else _rb_warn "$d не входит ни в одну зону firewall — туннели Steer для неё могут быть закрыты. Добавьте её интерфейс в зону (Сеть → Межсетевой экран)"; fi
			continue
		fi
		[ "$z" = "$lz" ] && continue
		if [ "$z" = "$wz" ]; then _rb_warn "Трафик $nm приходит в зону интернета «$z» — из неё Steer проходы в туннели не открывает. Вынесите $d в отдельную зону (Сеть → Межсетевой экран)"; continue; fi
		case " $zs " in *" $z "*) ;; *) zs="$zs $z" ;; esac
	done
	outs="$(_st_out_zones | awk '!x[$0]++')"
	for z in $zs; do
		for dz in $outs; do
			[ "$dz" = "$z" ] && continue
			r="zmlan_$(printf '%s_%s' "$z" "$dz" | tr -c 'A-Za-z0-9_' '_')"
			_st_fwd_has "$z" "$dz" "$r" && continue
			keep="$keep $r"
			[ "$(uci -q get "firewall.$r.src")" = "$z" ] && [ "$(uci -q get "firewall.$r.dest")" = "$dz" ] && continue
			uci -q delete "firewall.$r"
			uci set "firewall.$r=forwarding"
			uci set "firewall.$r.src=$z"
			uci set "firewall.$r.dest=$dz"
			_st_own "fw $r"
			ch=1
			_rb_say "Разрешаем сети из зоны «$z» ходить в зону «$dz» — туннель Steer"
		done
	done
	for r in $(sed -n 's/^fw \(zmlan_[A-Za-z0-9_]*\)$/\1/p' "$ST_OWNED" 2>/dev/null); do
		case " $keep " in *" $r "*) continue ;; esac
		uci -q delete "firewall.$r"
		sed -i "\\|^fw $r\$|d" "$ST_OWNED" 2>/dev/null
		ch=1
	done
	[ "$ch" = 1 ] && { uci commit firewall; /etc/init.d/firewall reload >/dev/null 2>&1; }
	return 0
}
_st_lan_fw_drop() {
	local r ch=0
	for r in $(sed -n 's/^fw \(zmlan_[A-Za-z0-9_]*\)$/\1/p' "$ST_OWNED" 2>/dev/null); do
		uci -q delete "firewall.$r"; sed -i "\\|^fw $r\$|d" "$ST_OWNED" 2>/dev/null; ch=1
	done
	[ "$ch" = 1 ] && { uci commit firewall; /etc/init.d/firewall reload >/dev/null 2>&1; }
	return 0
}
steer_lan_list() {
	local base extra n d z wz seen="" sep="" pr k outd up srv
	base=" $(_zm_lan_devs) "
	extra=" $(_st_lan_extra | tr '\n' ' ') "
	wz="$(_zm_wan_zone)"
	printf '{"lan_zone":"%s","max":%s,"items":[' "$(esc "$(_zm_lan_zone)")" "$ST_LAN_MAX"
	for n in $(uci -q -X show network | sed -n 's/^network\.\([^.=]*\)=interface$/\1/p'); do
		[ "$n" = loopback ] && continue
		pr="$(uci -q get "network.$n.proto")"
		case "$pr" in dhcp|dhcpv6|pppoe|pppoa|3g|qmi|ncm|mbim|modemmanager|wwan|wireguard|amneziawg|openvpn|none|pptp|l2tp|sstp) continue ;; esac
		d="$(_st_net_dev "$n")"
		case "$d" in ''|@*|lo) continue ;; esac
		[ -d "/sys/class/net/$d" ] || continue
		[ "$(cat "/sys/class/net/$d/type" 2>/dev/null)" = 1 ] || continue
		case " $seen " in *" $d "*) continue ;; esac
		z="$(_zm_zone_of_net "$n")"
		[ -n "$z" ] || z="$(_st_dev_zone "$d")"
		case "$z" in "$wz"|"$ST_WARP_ZONE"|"$ST_VPN_ZONE") continue ;; esac
		seen="$seen $d"
		printf '%s{"dev":"%s","net":"%s","zone":"%s","auto":%s,"on":%s}' "$sep" "$(esc "$d")" "$(esc "$n")" "$(esc "$z")" \
			"$(case "$base" in *" $d "*) echo true ;; *) echo false ;; esac)" "$(case "$extra" in *" $d "*) echo true ;; *) echo false ;; esac)"
		sep=","
	done
	outd=" $(_st_out_tun_devs | tr '\n' ' ') "
	for n in $(uci -q -X show network | sed -n 's/^network\.\([^.=]*\)=interface$/\1/p'); do
		k="$(_zm_tun_kind "$n")" || continue
		d="$(_zm_tun_dev "$n")" || continue
		case " $seen " in *" $d "*) continue ;; esac
		seen="$seen $d"
		z="$(_zm_zone_of_net "$n")"
		up=false; [ -d "/sys/class/net/$d" ] && up=true
		printf '%s{"dev":"%s","net":"%s","zone":"%s","auto":false,"on":%s,"kind":"tun","label":"%s","up":%s,"out":%s,"wan":%s}' "$sep" "$(esc "$d")" "$(esc "$n")" "$(esc "$z")" \
			"$(case "$extra" in *" $d "*) echo true ;; *) echo false ;; esac)" "$(esc "$(_zm_tun_label "$k")")" "$up" \
			"$(case "$outd" in *" $d "*) echo true ;; *) echo false ;; esac)" "$([ -n "$z" ] && [ "$z" = "$wz" ] && echo true || echo false)"
		sep=","
	done
	srv="$(_st_ppp_server)"
	if [ -n "$srv" ] || case "$extra" in *" $ST_PPP_SRV "*) true ;; *) false ;; esac; then
		z="$(_st_dev_zone "$ST_PPP_SRV")"
		printf '%s{"dev":"%s","net":"","zone":"%s","auto":false,"on":%s,"kind":"pppsrv","label":"%s","up":%s,"clients":%s,"wan":%s}' "$sep" "$ST_PPP_SRV" "$(esc "$z")" \
			"$(case "$extra" in *" $ST_PPP_SRV "*) echo true ;; *) echo false ;; esac)" "$(esc "$srv")" "$([ -n "$srv" ] && echo true || echo false)" \
			"$(ls /sys/class/net 2>/dev/null | grep -cE '^ppp[0-9]+$')" "$([ -n "$z" ] && [ "$z" = "$wz" ] && echo true || echo false)"
		sep=","
		seen="$seen $ST_PPP_SRV"
	fi
	for d in $extra; do
		case " $seen " in *" $d "*) continue ;; esac
		printf '%s{"dev":"%s","net":"","zone":"","auto":false,"on":true,"missing":true}' "$sep" "$(esc "$d")"
		sep=","
	done
	printf ']}\n'
}
do_steer_lanset() {
	_st_phase rules
	rm -f "$ST_STOP_FLAG"
	if [ -s "$ST_LAN_EXTRA" ]; then _rb_say "Steer обслуживает и дополнительные сети: $(_st_lan_extra | sed "s/^ppp+\$/клиенты VPN-сервера (ppp0…ppp$((ST_PPP_N - 1)))/" | tr '\n' ' ' | sed 's/ $//')"
	else _rb_say "Steer обслуживает только домашнюю сеть"; fi
	_st_secs_fw
	_st_respec
	_rb_say "Готово"
}

_tsc_state_keep() {
	local f n="/etc/tailscale/tailscaled.state"
	f="$(uci -q get tailscale.settings.state_file)"
	case "$f" in /tmp/*|/var/*|/dev/shm/*) ;; *) return 1 ;; esac
	mkdir -p "${n%/*}"
	[ -s "$f" ] && cp -f "$f" "$n"
	uci set tailscale.settings.state_file="$n"
	uci commit tailscale
	echo "   ✓ Вход Tailscale теперь хранится на флеш-памяти ($n) — после перезагрузки не придётся входить заново"
	return 0
}

_tsc_setup() {
	local z lz ch=0 p t
	mkdir -p "$TSC_DIR"; : > "$TSC_ON"
	_tsc_state_keep && _tsc_running && _tsc_start >/dev/null 2>&1
	_tsc_say "Настраиваем сеть и firewall"
	if [ "$(uci -q get "network.$TSC_NET")" != interface ]; then
		uci set "network.$TSC_NET=interface"
		uci set "network.$TSC_NET.proto=none"
		uci set "network.$TSC_NET.device=$TSC_DEV"
		uci commit network
		ubus call network reload >/dev/null 2>&1
		echo "   ✓ Интерфейс «$TSC_NET» ($TSC_DEV) создан"
	fi
	lz="$(_zm_lan_zone)"
	if z="$(_zm_zone_sec "$lz")"; then
		case " $(uci -q get "firewall.$z.network") " in
			*" $TSC_NET "*) ;;
			*) uci add_list "firewall.$z.network=$TSC_NET"; ch=1; echo "   ✓ Tailscale добавлен в зону «$lz» — телефон для роутера как домашнее устройство" ;;
		esac
	else
		echo "!! Не нашли зону домашней сети в firewall — добавьте интерфейс «$TSC_NET» в неё вручную"
	fi
	p="$(_tsc_port)"
	if [ "$(uci -q get "firewall.$TSC_FW_RULE")" != rule ] || [ "$(uci -q get "firewall.$TSC_FW_RULE.dest_port")" != "$p" ]; then
		uci set "firewall.$TSC_FW_RULE=rule"
		uci set "firewall.$TSC_FW_RULE.name=Allow-Tailscale"
		uci set "firewall.$TSC_FW_RULE.src=$(_zm_wan_zone)"
		uci set "firewall.$TSC_FW_RULE.proto=udp"
		uci set "firewall.$TSC_FW_RULE.dest_port=$p"
		uci set "firewall.$TSC_FW_RULE.target=ACCEPT"
		ch=1
		echo "   ✓ Открыт порт UDP $p — для прямого соединения с телефоном"
	fi
	[ "$ch" = 1 ] && uci commit firewall
	t="$TSC_NFT.zmtmp"
	mkdir -p "${TSC_NFT%/*}"
	_tsc_nft_text > "$t"
	if cmp -s "$t" "$TSC_NFT"; then rm -f "$t"; else mv -f "$t" "$TSC_NFT"; ch=1; echo "   ✓ IPv6 из Tailscale отклоняется сразу, размер пакетов подогнан под туннель"; fi
	if [ "$ch" = 1 ]; then
		if fw4 check >/dev/null 2>&1 || ! command -v fw4 >/dev/null 2>&1; then
			/etc/init.d/firewall reload >/dev/null 2>&1
		else
			rm -f "$TSC_NFT"
			echo "!! firewall не принял правила IPv6 и MSS — они отключены, остальное работает"
			/etc/init.d/firewall reload >/dev/null 2>&1
		fi
	fi
	if [ "$(cat /proc/sys/net/ipv4/ip_forward 2>/dev/null)" != 1 ]; then
		mkdir -p "${TSC_SYSCTL%/*}"; echo 'net.ipv4.ip_forward=1' > "$TSC_SYSCTL"
		sysctl -w net.ipv4.ip_forward=1 >/dev/null 2>&1
		echo "   ✓ Включена пересылка пакетов"
	fi
	if [ ! -f "$TSC_LS_PREV" ] && [ "$(uci -q get dhcp.@dnsmasq[0].localservice)" != 0 ]; then
		if _tsc_wan_closed; then
			uci -q get dhcp.@dnsmasq[0].localservice > "$TSC_LS_PREV" || : > "$TSC_LS_PREV"
			uci set dhcp.@dnsmasq[0].localservice=0
			uci commit dhcp
			/etc/init.d/dnsmasq restart >/dev/null 2>&1
			echo "   ✓ DNS роутера отвечает и устройствам Tailscale (из интернета он по-прежнему закрыт)"
		else
			echo "!! Вход из интернета в firewall не закрыт — DNS роутера для Tailscale не открываем"
		fi
	fi
	_tsc_uci_sync
	_tsc_cron on
	_tsc_fk add
	_tsc_zapret add
	if [ -f /etc/init.d/tgws ]; then
		_tsc_tg_ensure && echo "   ✓ sTGWS: Telegram с телефона пойдёт через мост"
	fi
	_tsc_kick_bypass
	return 0
}

_tsc_unsetup() {
	local z lz ch=0 v
	_tsc_say "Убираем настройки сети и firewall"
	_tsc_tg_drop
	_tsc_nft_clean
	lz="$(_zm_lan_zone)"
	if z="$(_zm_zone_sec "$lz")"; then
		case " $(uci -q get "firewall.$z.network") " in *" $TSC_NET "*) uci del_list "firewall.$z.network=$TSC_NET"; ch=1 ;; esac
	fi
	uci -q get "firewall.$TSC_FW_RULE" >/dev/null && { uci delete "firewall.$TSC_FW_RULE"; ch=1; }
	[ "$ch" = 1 ] && uci commit firewall
	[ -f "$TSC_NFT" ] && { rm -f "$TSC_NFT"; ch=1; }
	[ "$ch" = 1 ] && /etc/init.d/firewall reload >/dev/null 2>&1
	if uci -q get "network.$TSC_NET" >/dev/null; then
		uci delete "network.$TSC_NET"; uci commit network
		ubus call network reload >/dev/null 2>&1
	fi
	rm -f "$TSC_SYSCTL"
	if [ -f "$TSC_LS_PREV" ]; then
		v="$(cat "$TSC_LS_PREV")"
		if [ -n "$v" ]; then uci set "dhcp.@dnsmasq[0].localservice=$v"; else uci -q delete dhcp.@dnsmasq[0].localservice; fi
		uci commit dhcp
		/etc/init.d/dnsmasq restart >/dev/null 2>&1
		rm -f "$TSC_LS_PREV"
	fi
	_tsc_zapret del
	_tsc_fk del
	_tsc_cron off
	rm -f "$TSC_ON"
	if [ -f "$TERM_ALL" ] && _term_installed; then
		_term_set_mode home >/dev/null 2>&1
		echo "   ✓ Терминал снова только для домашней сети"
	fi
	_tsc_kick_bypass wait
	echo "   ✓ Сеть и firewall вернулись к прежнему виду"
	return 0
}

_tsc_dbg() { _tsc_api prefs || _zm_tmo 8 tailscale debug prefs 2>/dev/null; }
_tsc_nf_on() {
	local m
	m="$(printf '%s' "${1:-$(_tsc_dbg)}" | jsonfilter -e '@.NetfilterMode' 2>/dev/null)"
	[ -n "$m" ] && [ "$m" != 0 ]
}

_tsc_prefs() {
	local st
	TSC_KICK=""
	_tsc_nf_on "$1" && TSC_KICK=1
	_tsc_uci_sync
	st="$(_tsc_json | jsonfilter -e '@.BackendState' 2>/dev/null)"
	case "$st" in Running|NeedsMachineAuth|Starting) ;;
		NeedsLogin|Stopped) _zm_tmo 20 tailscale set --netfilter-mode=off --accept-dns=false >/dev/null 2>&1; _tsc_nft_clean && TSC_KICK=1; return 0 ;;
		*) return 0 ;;
	esac
	# shellcheck disable=SC2046
	if _zm_tmo 20 tailscale set $(_tsc_flags) --netfilter-mode=off >/dev/null 2>&1 ||
		_zm_tmo 25 tailscale up --reset $(_tsc_upflags) >/dev/null 2>&1 ||
		_zm_tmo 20 tailscale set $(_tsc_flags) >/dev/null 2>&1; then
		_tsc_nft_clean && TSC_KICK=1
		return 0
	fi
	return 1
}

_tsc_prefs_ok() {
	local p="$1" r c
	[ -n "$p" ] || p="$(_tsc_dbg)"
	[ -n "$p" ] || return 0
	r="$(printf '%s' "$p" | jsonfilter -e '@.AdvertiseRoutes[*]' 2>/dev/null)"
	if [ -f "$TSC_NOEXIT" ]; then printf '%s\n' "$r" | grep -qx '0.0.0.0/0' && return 1
	else printf '%s\n' "$r" | grep -qx '0.0.0.0/0' || return 1; fi
	c="$(_tsc_lan_cidr)"
	if [ -n "$c" ]; then
		if [ -f "$TSC_LAN" ]; then printf '%s\n' "$r" | grep -qxF "$c" || return 1
		else printf '%s\n' "$r" | grep -qxF "$c" && return 1; fi
	fi
	[ "$(printf '%s' "$p" | jsonfilter -e '@.CorpDNS' 2>/dev/null)" = true ] && return 1
	_tsc_nf_on "$p" && return 1
	_tsc_nft_left && return 1
	return 0
}

_tsc_nft_clean() {
	local fam t out ch h n=0
	for fam in ip ip6; do
		for t in filter nat mangle; do
			out="$(nft -a list table "$fam" "$t" 2>/dev/null)" || continue
			printf '%s\n' "$out" | grep -qE 'jump ts-|chain ts-|0x00ff0000' || continue
			printf '%s\n' "$out" | awk '/^\tchain /{ c = $2 } /^\t\t/ && /# handle / && (/jump ts-/ || /0x00ff0000/) { h = $NF; print c, h }' |
				while read -r ch h; do nft delete rule "$fam" "$t" "$ch" handle "$h" 2>/dev/null; done
			for ch in $(printf '%s\n' "$out" | awk '/^\tchain ts-/ { print $2 }'); do
				nft flush chain "$fam" "$t" "$ch" 2>/dev/null; nft delete chain "$fam" "$t" "$ch" 2>/dev/null
			done
			if ! nft -a list table "$fam" "$t" 2>/dev/null | grep -qE '^		.*# handle [0-9]+$'; then
				nft delete table "$fam" "$t" 2>/dev/null
			fi
			n=$((n + 1))
		done
	done
	[ "$n" -gt 0 ] || return 1
	sysctl -w net.ipv4.conf.all.src_valid_mark=0 >/dev/null 2>&1
	return 0
}
_tsc_nft_left() {
	local t
	for t in $(nft list tables 2>/dev/null | awk '$1 == "table" && ($2 == "ip" || $2 == "ip6") && ($3 == "filter" || $3 == "nat" || $3 == "mangle") { print $2 "/" $3 }'); do
		nft list table "${t%/*}" "${t#*/}" 2>/dev/null | grep -qE 'jump ts-|chain ts-|0x00ff0000' && return 0
	done
	return 1
}

TSC_CRON_TAG="# zm-tailscale"
_tsc_cron() {
	local l="* * * * * /opt/zapret-manager-luci/backend.sh tsc_watch >/dev/null 2>&1 $TSC_CRON_TAG"
	if [ "$1" = on ]; then
		[ "$(grep -cF "$TSC_CRON_TAG" "$CRON_FILE" 2>/dev/null)" = 1 ] && grep -qxF "$l" "$CRON_FILE" && return 0
	else
		grep -qF "$TSC_CRON_TAG" "$CRON_FILE" 2>/dev/null || return 0
	fi
	sed -i "\\|$TSC_CRON_TAG|d" "$CRON_FILE" 2>/dev/null
	[ "$1" = on ] && echo "$l" >> "$CRON_FILE"
	/etc/init.d/cron restart >/dev/null 2>&1
	return 0
}

_tsc_heal_need() {
	local z f
	[ "$(uci -q get "network.$TSC_NET")" = interface ] || { echo "интерфейс сети"; return 0; }
	[ "$(uci -q get "firewall.$TSC_FW_RULE")" = rule ] || { echo "порт в firewall"; return 0; }
	z="$(_zm_zone_sec "$(_zm_lan_zone)")" && case " $(uci -q get "firewall.$z.network") " in
		*" $TSC_NET "*) ;;
		*) echo "зона домашней сети"; return 0 ;;
	esac
	if uci -q get netshift.settings >/dev/null && ! _tsc_fk_has; then echo "Forkozz"; return 0; fi
	for f in $(cat "$TSC_ZR_OWN" 2>/dev/null); do
		[ -f "$f" ] && grep -qE '^IFACE_LAN="?[^" ]' "$f" && ! grep '^IFACE_LAN=' "$f" | tr '"' ' ' | grep -qw "$TSC_DEV" && { echo "Zapret"; return 0; }
	done
	[ -f /etc/init.d/tgws ] && grep -q procd_close_instance /etc/init.d/tgws && ! grep -qF "$TSC_HOOK" /etc/init.d/tgws && { echo "sTGWS"; return 0; }
	return 1
}

tsc_watch() {
	local pid l="$TSC_DIR/watch.lock"
	[ -f "$TSC_ON" ] && _tsc_installed || return 0
	[ -f "$TSC_STOP" ] && return 0
	pid="$(pidof tailscaled 2>/dev/null)"
	[ -n "$pid" ] || return 0
	_job_alive tsc && return 0
	find "$TSC_DIR" -maxdepth 1 -name watch.lock -mmin +10 -exec rmdir {} \; 2>/dev/null
	mkdir "$l" 2>/dev/null || return 0
	_tsc_watch_run "$pid"
	rmdir "$l" 2>/dev/null
	return 0
}

_tsc_watch_run() {
	local pid="$1" key st dp why
	_term_all_guard && _term_running && /etc/init.d/ttyd restart >/dev/null 2>&1
	if why="$(_tsc_heal_need)"; then
		if ! find "$TSC_DIR" -maxdepth 1 -name heal.ts -mmin -30 2>/dev/null | grep -q .; then
			: > "$TSC_DIR/heal.ts"
			logger -t zapret-manager "Tailscale: восстанавливаем настройку ($why)"
			_tsc_setup >/dev/null 2>&1
			rm -f "$TSC_DIR/watch.key"
		fi
	fi
	if _tsc_nft_left; then
		_tsc_nft_clean && { logger -t zapret-manager "Tailscale: убраны его правила firewall, мешавшие Steer, Forkozz и Zapret"; _tsc_kick_bypass >/dev/null 2>&1; }
		rm -f "$TSC_DIR/watch.key"
	fi
	[ -s "$TSC_DIR/login.req" ] && _tsc_login_nudge "$(_tsc_json | jsonfilter -e '@.BackendState' 2>/dev/null)"
	key="$pid $(date -r "$(uci -q get tailscale.settings.state_file || echo /etc/tailscale/tailscaled.state)" +%s 2>/dev/null) $(_tsc_lan_cidr) $(_zm_lan_ip) $([ -f "$TSC_NOEXIT" ] && echo e)$([ -f "$TSC_LAN" ] && echo l)"
	[ "$key" = "$(cat "$TSC_DIR/watch.key" 2>/dev/null)" ] && return 0
	_tsc_tg_ip_fix
	st="$(_tsc_json | jsonfilter -e '@.BackendState' 2>/dev/null)"
	printf '%s\n' "$st" > "$TSC_STATE" 2>/dev/null
	_tsc_login_nudge "$st"
	case "$st" in
		Running)
			dp="$(_tsc_dbg)"
			_tsc_prefs_ok "$dp" || {
				_tsc_prefs "$dp" >/dev/null 2>&1
				logger -t zapret-manager "Tailscale: применены настройки выхода в интернет и подсети"
				[ -n "$TSC_KICK" ] && { logger -t zapret-manager "Tailscale: перезапускаем Forkozz и Steer"; _tsc_kick_bypass >/dev/null 2>&1; }
			}
			_tsc_prefs_ok && printf '%s\n' "$key" > "$TSC_DIR/watch.key"
			if [ "$pid" != "$(cat "$TSC_DIR/kick.pid" 2>/dev/null)" ]; then
				logger -t zapret-manager "Tailscale перезапущен: перезапускаем Forkozz и Steer"
				_tsc_kick_bypass >/dev/null 2>&1
			fi ;;
		NeedsLogin|Stopped)
			_tsc_prefs >/dev/null 2>&1
			[ -n "$TSC_KICK" ] && _tsc_kick_bypass >/dev/null 2>&1
			printf '%s\n' "$key" > "$TSC_DIR/watch.key" ;;
		*)
			_tsc_prefs >/dev/null 2>&1
			[ -n "$TSC_KICK" ] && _tsc_kick_bypass >/dev/null 2>&1 ;;
	esac
	return 0
}

_tsc_clock_hint() {
	[ "$(date +%Y)" -lt 2025 ] 2>/dev/null && printf ' Часы роутера показывают %s — включите синхронизацию времени (LuCI → Система → Система → NTP), без неё вход не пройдёт.' "$(date +%d.%m.%Y)"
	return 0
}

_tsc_login_bg() {
	local s h a=""
	s="$(_tsc_srv)"
	[ "$1" != plain ] && h="$(_tsc_hostname)" && a="--hostname=$h"
	[ -n "$s" ] && a="$a --login-server=$s"
	pkill -f 'tailscale (up|login)' >/dev/null 2>&1
	: > "$TSC_UPLOG"
	# shellcheck disable=SC2086
	( _zm_tmo 900 tailscale login $a >"$TSC_UPLOG" 2>&1 & ) >/dev/null 2>&1
}
_tsc_login_nudge() {
	local r
	[ "$1" = NeedsLogin ] || { [ "$1" = Running ] && rm -f "$TSC_DIR/login.req" "$TSC_DIR/login.nudge"; return 0; }
	[ -s "$TSC_DIR/login.req" ] || return 0
	r="$(cat "$TSC_DIR/login.req" 2>/dev/null)"
	[ $(( $(date +%s) - ${r:-0} )) -lt 900 ] 2>/dev/null || { rm -f "$TSC_DIR/login.req" "$TSC_DIR/login.nudge"; return 0; }
	[ -f "$TSC_DIR/login.nudge" ] && [ $(( $(date +%s) - $(cat "$TSC_DIR/login.nudge" 2>/dev/null || echo 0) )) -lt 30 ] 2>/dev/null && return 0
	date +%s > "$TSC_DIR/login.nudge"
	_tsc_login_bg
}

_tsc_login() {
	local i=0 st url key
	_tsc_running || _tsc_start >/dev/null 2>&1 || { echo '{"error":"служба Tailscale не запускается — нажмите «Перезапустить» или смотрите журнал роутера"}'; return 1; }
	st="$(_tsc_json | jsonfilter -e '@.BackendState' 2>/dev/null)"
	if [ "$st" = Running ]; then printf '{"ok":true,"state":"Running"}\n'; return 0; fi
	pkill -f 'tailscale (up|login)' >/dev/null 2>&1
	_tsc_uci_sync
	: > "$TSC_UPLOG"
	key="$(cat "$TSC_KEY" 2>/dev/null)"
	if [ -n "$key" ]; then
		# shellcheck disable=SC2046
		_zm_tmo 45 tailscale up --reset $(_tsc_upflags) --auth-key="$key" >"$TSC_UPLOG" 2>&1
		st="$(_tsc_json | jsonfilter -e '@.BackendState' 2>/dev/null)"
		case "$st" in
			Running|NeedsMachineAuth) printf '{"ok":true,"state":"%s"}\n' "$st"; return 0 ;;
		esac
		printf '{"error":"%s"}\n' "$(esc "Сервер не принял ключ. Проверьте, что это Device Auth Key, а не Management Key, и адрес сервера. Ключ Routerich действует год с создания сети.$(_tsc_clock_hint) $(tail -n 2 "$TSC_UPLOG" 2>/dev/null | sed "s#$key#***#g" | tr '\n' ' ')")"
		return 1
	fi
	mkdir -p "$TSC_DIR"; date +%s > "$TSC_DIR/login.req"; rm -f "$TSC_DIR/login.nudge"
	_tsc_login_bg
	while [ "$i" -lt 30 ]; do
		sleep 1; i=$((i + 1))
		if [ "$i" = 4 ] && grep -qiE 'requires mentioning|invalid|error' "$TSC_UPLOG" 2>/dev/null && ! grep -q 'https://' "$TSC_UPLOG" 2>/dev/null; then
			_tsc_login_bg plain
		fi
		url="$(_tsc_json | jsonfilter -e '@.AuthURL' 2>/dev/null)"
		[ -n "$url" ] || url="$(grep -o 'https\{0,1\}://[^[:space:]]*' "$TSC_UPLOG" 2>/dev/null | head -n1)"
		[ -n "$url" ] && { printf '{"ok":true,"url":"%s"}\n' "$(esc "$url")"; return 0; }
		st="$(_tsc_json | jsonfilter -e '@.BackendState' 2>/dev/null)"
		[ "$st" = Running ] && { rm -f "$TSC_DIR/login.req"; printf '{"ok":true,"state":"Running"}\n'; return 0; }
	done
	printf '{"error":"%s"}\n' "$(esc "Tailscale не выдал ссылку для входа. Проверьте интернет на роутере и попробуйте ещё раз.$(_tsc_clock_hint) $(tail -n 2 "$TSC_UPLOG" 2>/dev/null | tr '\n' ' ')")"
	return 1
}

_tsc_route_ok() {
	{ printf '%s' "$1" | jsonfilter -e '@.Self.PrimaryRoutes[*]' 2>/dev/null; printf '%s' "$1" | jsonfilter -e '@.Self.AllowedIPs[*]' 2>/dev/null; } |
	awk -v want="$2" '
		function ipn(a,  o) { if (split(a, o, ".") != 4) return -1; return ((o[1] * 256 + o[2]) * 256 + o[3]) * 256 + o[4] }
		BEGIN { split(want, w, "/"); wa = ipn(w[1]); wm = (w[2] == "" ? 32 : w[2] + 0) }
		$0 !~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+\/[0-9]+$/ { next }
		{ split($0, r, "/"); m = r[2] + 0; if (m < 1 || m > wm) next; z = 1; for (i = m; i < 32; i++) z *= 2; if (int(ipn(r[1]) / z) == int(wa / z)) { ok = 1; exit } }
		END { exit !ok }'
}

TSC_MANUAL="$TSC_DIR/approved.manual"

tsc_status() {
	local inst=false run=false en=false on=false j="" st="" url="" ip="" host="" tn="" exo=false lano=false man=false
	local pok=true cidr="" ver="" kexp="" lip lprev="" net=false zone=false nft=false tg=false tgr=0 zr=false st_on=false z lz free
	_tsc_installed && { inst=true; ver="$(_tsc_ver)"; }
	[ -f "$TSC_STOP" ] && _tsc_running && [ -n "$(find "$TSC_STOP" -mmin +1 2>/dev/null)" ] && rm -f "$TSC_STOP"
	[ -f "$TSC_ON" ] && on=true
	_tsc_enabled && en=true
	if $inst && _tsc_running; then
		run=true
		j="$(_tsc_json)"
	fi
	if [ -n "$j" ]; then
		st="$(printf '%s' "$j" | jsonfilter -e '@.BackendState' 2>/dev/null)"
		_tsc_login_nudge "$st"
		url="$(printf '%s' "$j" | jsonfilter -e '@.AuthURL' 2>/dev/null)"
		ip="$(printf '%s' "$j" | jsonfilter -e '@.Self.TailscaleIPs[*]' 2>/dev/null | grep -m1 '\.')"
		host="$(printf '%s' "$j" | jsonfilter -e '@.Self.HostName' 2>/dev/null)"
		tn="$(printf '%s' "$j" | jsonfilter -e '@.CurrentTailnet.Name' 2>/dev/null)"
		kexp="$(printf '%s' "$j" | jsonfilter -e '@.Self.KeyExpiry' 2>/dev/null)"
		[ "$(printf '%s' "$j" | jsonfilter -e '@.Self.ExitNodeOption' 2>/dev/null)" = true ] && exo=true
		printf '%s' "$j" | jsonfilter -e '@.Self.AllowedIPs[*]' 2>/dev/null | grep -qx '0.0.0.0/0' && exo=true
		cidr="$(_tsc_lan_cidr)"
		[ -n "$cidr" ] && _tsc_route_ok "$j" "$cidr" && lano=true
		[ "$st" = Running ] && [ -s "$TSC_MANUAL" ] && {
			! $exo && grep -qx 'exit' "$TSC_MANUAL" && exo=true && man=true
			! $lano && [ -n "$cidr" ] && grep -qxF "lan $cidr" "$TSC_MANUAL" && lano=true && man=true
		}
		if [ "$st" = Running ] && [ -f "$TSC_ON" ] && ! _job_alive tsc; then
			local dp
			dp="$(_tsc_dbg)"
			_tsc_prefs_ok "$dp" || { _tsc_prefs "$dp" >/dev/null 2>&1; [ -n "$TSC_KICK" ] && _tsc_kick_bg; _tsc_prefs_ok || pok=false; }
		fi
	fi
	[ -z "$cidr" ] && cidr="$(_tsc_lan_cidr)"
	lip="$(_zm_lan_ip)"
	if [ "$st" = Running ] && [ -n "$lip" ]; then
		[ -s "$TSC_DIR/lan.ip" ] || printf '%s\n' "$lip" > "$TSC_DIR/lan.ip" 2>/dev/null
		lprev="$(cat "$TSC_DIR/lan.ip" 2>/dev/null)"
		[ "$lprev" = "$lip" ] && lprev=""
		$on && $run && _tsc_tg_ip_fix >/dev/null 2>&1
	fi
	[ -f "$TSC_ON" ] && $inst && ! grep -qF "$TSC_CRON_TAG" "$CRON_FILE" 2>/dev/null && _tsc_cron on
	mkdir -p "$TSC_DIR" 2>/dev/null; printf '%s\n' "${st:-}" > "$TSC_STATE" 2>/dev/null
	[ "$(uci -q get "network.$TSC_NET")" = interface ] && net=true
	lz="$(_zm_lan_zone)"
	z="$(_zm_zone_sec "$lz")" && case " $(uci -q get "firewall.$z.network") " in *" $TSC_NET "*) zone=true ;; esac
	[ -f "$TSC_NFT" ] && nft=true
	if [ -f /etc/init.d/tgws ]; then
		tg=true
		$on && $run && [ "$(_tsc_tg_rules)" -lt 2 ] 2>/dev/null && [ -n "$(tgws status 2>/dev/null)" ] && _tsc_tg_ensure >/dev/null 2>&1
		tgr="$(_tsc_tg_rules)"
	fi
	[ -f /etc/init.d/zapret ] && pgrep -f "/opt/zapre[t]/" >/dev/null 2>&1 && zr=true
	_tsc_steer_on && st_on=true
	free="$(_tsc_free_kb)"
	printf '{"installed":%s,"version":"%s","running":%s,"enabled":%s,"on":%s,"state":"%s","auth_url":"%s","ip":"%s","host":"%s","tailnet":"%s",' \
		"$inst" "$(esc "$ver")" "$run" "$en" "$on" "$(esc "$st")" "$(esc "$url")" "$(esc "$ip")" "$(esc "$host")" "$(esc "$tn")"
	printf '"exit_want":%s,"exit_ok":%s,"lan_want":%s,"lan_ok":%s,"lan_cidr":"%s","lan_ip":"%s","net":%s,"zone":%s,"nft":%s,' \
		"$([ -f "$TSC_NOEXIT" ] && echo false || echo true)" "$exo" "$([ -f "$TSC_LAN" ] && echo true || echo false)" "$lano" \
		"$(esc "$cidr")" "$(esc "$lip")" "$net" "$zone" "$nft"
	local lat="" vcur
	$inst && lat="$(_zm_cached tsc _tsc_gh_latest)"
	vcur="$(_tsc_vnum "$ver")"
	printf '"manual_ok":%s,' "$man"
	printf '"prefs_ok":%s,"luci_path":"%s","key_expiry":"%s","lan_prev":"%s","term_mode":"%s",' "$pok" "$(esc "$(_tsc_luci_path)")" "$(esc "$kexp")" "$(esc "$lprev")" "$(_term_installed && _term_mode)"
	printf '"fk":%s,"fk_ok":%s,"mx":%s,"adblock":%s,' "$(_fk_installed && echo true || echo false)" "$(_tsc_fk_has && echo true || echo false)" \
		"$([ -x /etc/init.d/magitrickle ] && echo true || echo false)" "$(_ab_on && echo true || echo false)"
	printf '"luci_app":%s,"latest":"%s","newer":%s,"source":"%s",' "$(_tsc_luci_app && echo true || echo false)" "$(esc "$(_tsc_vnum "$lat")")" \
		"$([ -n "$lat" ] && [ -n "$vcur" ] && _st_ver_lt "$vcur" "$(_tsc_vnum "$lat")" && echo true || echo false)" "$(esc "$(cat "$TSC_SRC" 2>/dev/null)")"
	printf '"server":"%s","server_kind":"%s","admin":"%s","has_key":%s,' "$(esc "$(_tsc_srv)")" "$(_tsc_kind)" "$(esc "$(_tsc_admin)")" "$([ -s "$TSC_KEY" ] && echo true || echo false)"
	printf '"stopped":%s,' "$([ -f "$TSC_STOP" ] && echo true || echo false)"
	printf '"stgws":%s,"tg_rules":%s,"zapret":%s,"zapret_inst":%s,"steer":%s,"steer_inst":%s,"steer_dns":"%s","free_kb":%s,"need_kb":%s,"job":%s}\n' \
		"$tg" "${tgr:-0}" "$zr" "$([ -f /etc/init.d/zapret ] && echo true || echo false)" "$st_on" "$(_st_installed && echo true || echo false)" "$(esc "$(_st_dnsmode 2>/dev/null)")" "${free:-0}" "$TSC_NEED_KB" \
		"$(_job_alive tsc && echo true || echo false)"
}

do_tsc_install() {
	local free
	rm -f "$TSC_STOP"
	_ensure_deps
	_tsc_say "Проверяем место на флеш-памяти"
	free="$(_tsc_free_kb)"
	if [ -n "$free" ] && [ "$free" -lt "$TSC_NEED_KB" ]; then
		echo "ОШИБКА: свободно $((free / 1024)) МБ, а Tailscale нужно около $((TSC_NEED_KB / 1024)) МБ. Освободите место — например, удалите ненужные компоненты в разделе «Очистка и удаление»"
		return 1
	fi
	[ -n "$free" ] && echo "   ✓ Свободно $((free / 1024)) МБ"
	_tsc_say "Обновляем список пакетов OpenWrt"
	$UPDATE || echo "!! Список пакетов не обновился — пробуем с тем, что есть"
	if _tsc_installed; then
		echo "   ✓ Tailscale уже установлен: $(_tsc_ver)"
	else
		_tsc_say "Устанавливаем Tailscale с GitHub — уменьшенная сборка для OpenWrt"
		if ! _tsc_install_gh; then
			_tsc_say "Пробуем репозиторий OpenWrt (пакет больше, около 25 МБ)"
			$INSTALL tailscale || { echo "ОШИБКА: Tailscale не установился ни с GitHub, ни из репозитория OpenWrt — проверьте интернет и место на флеш-памяти"; return 1; }
			mkdir -p "$TSC_DIR"; echo openwrt > "$TSC_SRC"
		fi
		_tsc_installed || { echo "ОШИБКА: файла /usr/sbin/tailscaled нет — пакет встал не полностью"; return 1; }
		echo "   ✓ Tailscale $(_tsc_ver)"
	fi
	_tsc_say "Ставим страницу Tailscale для LuCI (luci-app-tailscale-community)"
	if _tsc_luci_app || _tsc_install_luci; then
		rm -f /tmp/luci-indexcache* /tmp/luci-modulecache/* 2>/dev/null
		case "$(_tsc_luci_path)" in
			admin/vpn/*) echo "   ✓ Готово: LuCI → VPN → Tailscale" ;;
			*) echo "   ✓ Готово: LuCI → Службы → Tailscale" ;;
		esac
	else
		echo "   · Не установилась — не страшно, всё настраивается на этой странице"
	fi
	mkdir -p "$TSC_DIR"
	[ -f "$TSC_DIR/lan.init" ] || { : > "$TSC_LAN"; : > "$TSC_DIR/lan.init"; }
	_tsc_say "Запускаем службу Tailscale"
	_tsc_start || return 1
	echo "   ✓ Служба работает"
	_tsc_setup
	_tsc_say "Готово. Осталось войти в аккаунт Tailscale — кнопка «Войти» на этой странице"
}

do_tsc_update() {
	local old new lat
	_tsc_installed || { echo "ОШИБКА: Tailscale не установлен"; return 1; }
	old="$(_tsc_ver)"
	_tsc_say "Обновляем Tailscale (сейчас $old)"
	$UPDATE >/dev/null 2>&1
	_tsc_install_gh || { echo "ОШИБКА: свежая версия не скачалась — Tailscale $old продолжает работать"; return 1; }
	rm -f "$TSC_DIR/version"
	if [ -f "$TSC_STOP" ]; then
		/etc/init.d/tailscale stop >/dev/null 2>&1
		/etc/init.d/tailscale disable >/dev/null 2>&1
		ZM_VER_FORCE=1 _zm_cached tsc _tsc_gh_latest >/dev/null 2>&1
		_tsc_say "Готово: Tailscale $old → $(_tsc_ver). Служба остановлена, как и была — запустите её кнопкой «Запустить»"
		return 0
	fi
	_tsc_say "Перезапускаем службу"
	_tsc_start || return 1
	_tsc_prefs
	_tsc_kick_bypass
	ZM_VER_FORCE=1 _zm_cached tsc _tsc_gh_latest >/dev/null 2>&1
	new="$(_tsc_ver)"
	lat="$(_tsc_vnum "$(cat "$ZM_STATE_DIR/latest.tsc" 2>/dev/null)")"
	if [ -n "$new" ] && [ -n "$lat" ] && _st_ver_lt "$(_tsc_vnum "$new")" "$lat"; then
		echo "!! Пакет установился, но Tailscale по-прежнему $new — возможно, на флеш-памяти не хватило места или файл программы занят. Перезагрузите роутер и проверьте версию ещё раз"
		return 1
	fi
	if [ "$new" = "$old" ]; then _tsc_say "Готово: Tailscale $new"; else _tsc_say "Готово: Tailscale $old → $new"; fi
}

do_tsc_repair() {
	_tsc_installed || { echo "ОШИБКА: Tailscale не установлен"; return 1; }
	[ -f "$TSC_STOP" ] && { echo "ОШИБКА: Tailscale остановлен — сначала нажмите «Запустить»"; return 1; }
	_tsc_running || { _tsc_say "Запускаем службу Tailscale"; _tsc_start || return 1; }
	_tsc_setup
	_tsc_prefs
	_tsc_say "Готово: настройки для телефона на месте"
}

do_tsc_remove() {
	local rc=0
	_tsc_say "Выходим из аккаунта и останавливаем Tailscale"
	_tsc_running && _zm_tmo 10 tailscale logout >/dev/null 2>&1
	pkill -f 'tailscale (up|login)' >/dev/null 2>&1
	if [ -x /etc/init.d/tailscale ]; then /etc/init.d/tailscale stop >/dev/null 2>&1; /etc/init.d/tailscale disable >/dev/null 2>&1; fi
	killall tailscaled >/dev/null 2>&1
	echo "   ✓ Служба остановлена"
	_tsc_unsetup
	_tsc_say "Удаляем пакет tailscale"
	_zm_pkg_wipe luci-i18n-tailscale-community-ru luci-app-tailscale-community >/dev/null 2>&1
	_zm_pkg_wipe tailscale || rc=1
	_zm_rm_listed tailscale || rc=1
	rm -f /tmp/luci-indexcache* /tmp/luci-modulecache/* 2>/dev/null
	_tsc_installed && rc=1
	_zm_rm_done "$rc" "Tailscale"
}

_tsc_server_set() {
	local srv key old st
	srv="$(printf '%s' "$1" | head -n1 | cut -f1 | tr -d '\r ')"
	key="$(printf '%s' "$1" | head -n1 | cut -s -f2 | tr -d '\r ')"
	srv="${srv%/}"
	case "$srv" in
		'') ;;
		http://*|https://*) printf '%s' "$srv" | grep -qE '^https?://[A-Za-z0-9.-]+(:[0-9]+)?(/[A-Za-z0-9._~/-]*)?$' || { echo '{"error":"адрес сервера записан с ошибкой — пример: https://rc.routerich.ru"}'; return 1; } ;;
		*) echo '{"error":"адрес сервера должен начинаться с https://"}'; return 1 ;;
	esac
	if [ -n "$key" ]; then
		[ "${#key}" -le 300 ] && printf '%s' "$key" | grep -qE '^[A-Za-z0-9_:.+/=-]+$' || { echo '{"error":"в ключе есть лишние символы — скопируйте его целиком, без пробелов"}'; return 1; }
		printf '%s' "$key" | grep -qE '^[0-9a-fA-F]{64}$' && { echo '{"error":"это похоже на Management Key (ключ входа в панель). Для роутера и телефона нужен Device Auth Key"}'; return 1; }
	fi
	[ -z "$srv" ] && key=""
	old="$(_tsc_srv)"
	mkdir -p "$TSC_DIR"
	if [ -n "$srv" ]; then printf '%s\n' "$srv" > "$TSC_SRV"; else rm -f "$TSC_SRV"; fi
	if [ -n "$key" ]; then ( umask 077; printf '%s\n' "$key" > "$TSC_KEY" ); else rm -f "$TSC_KEY"; fi
	[ "$old" != "$srv" ] && rm -f "$TSC_DIR/lan.ip"
	if [ "$old" != "$srv" ] && _tsc_running; then
		st="$(_tsc_json | jsonfilter -e '@.BackendState' 2>/dev/null)"
		case "$st" in Running|NeedsMachineAuth|Starting|Stopped)
			pkill -f 'tailscale (up|login)' >/dev/null 2>&1
			_zm_tmo 15 tailscale logout >/dev/null 2>&1 ;;
		esac
	fi
	printf '{"ok":true,"changed":%s}\n' "$([ "$old" != "$srv" ] && echo true || echo false)"
}

tsc_action() {
	local a="$1" m="$2" j
	case "$a" in
		install|remove|repair|update)
			_job_alive tsc && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			if j="$(_zm_busy_job)"; then printf '{"error":"%s"}\n' "$(esc "Сейчас идёт операция: $j — дождитесь её окончания")"; return 1; fi
			case "$a" in
				install) job_start tsc do_tsc_install ;;
				remove)  job_start tsc do_tsc_remove ;;
				repair)  job_start tsc do_tsc_repair ;;
				update)  job_start tsc do_tsc_update ;;
			esac ;;
		login|logout|restart|exit|lan|server|apply|kick|lanack|approved|stop|start)
			_tsc_installed || { echo '{"error":"Tailscale не установлен"}'; return 1; }
			_job_alive tsc && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			case "$a" in
				login|logout|restart|apply|kick) [ -f "$TSC_STOP" ] && { echo '{"error":"Tailscale остановлен — сначала нажмите «Запустить»"}'; return 1; } ;;
			esac
			case "$a" in
				stop)
					mkdir -p "$TSC_DIR"; : > "$TSC_STOP"
					pkill -f 'tailscale (up|login)' >/dev/null 2>&1
					_tsc_uci_sync
					[ -x /etc/init.d/tailscale ] && { /etc/init.d/tailscale stop >/dev/null 2>&1; /etc/init.d/tailscale disable >/dev/null 2>&1; }
					sleep 1
					if _tsc_running; then killall tailscaled >/dev/null 2>&1; sleep 2; _tsc_running && killall -9 tailscaled >/dev/null 2>&1; fi
					rm -f "$TSC_DIR/watch.key"
					_tsc_running && { echo '{"error":"служба Tailscale не остановилась — смотрите журнал роутера"}'; return 1; }
					logger -t zapret-manager "Tailscale остановлен кнопкой — сам не запустится, пока не нажмут «Запустить»"
					printf '{"ok":true}\n' ;;
				start)
					rm -f "$TSC_STOP"
					_tsc_start >/dev/null 2>&1; j=$?
					_tsc_uci_sync
					[ "$j" = 0 ] || { echo '{"error":"служба Tailscale не запустилась — смотрите журнал роутера"}'; return 1; }
					_tsc_kick_bg
					printf '{"ok":true}\n' ;;
				login) _tsc_login ;;
				server) rm -f "$TSC_MANUAL"; _tsc_server_set "$m" ;;
				kick) _tsc_kick_bg; printf '{"ok":true}\n' ;;
				lanack) mkdir -p "$TSC_DIR"; _zm_lan_ip > "$TSC_DIR/lan.ip"; printf '{"ok":true}\n' ;;
				approved)
					mkdir -p "$TSC_DIR"
					if [ "$m" = off ]; then rm -f "$TSC_MANUAL"; printf '{"ok":true}\n'; return 0; fi
					{ [ -f "$TSC_NOEXIT" ] || echo exit; [ -f "$TSC_LAN" ] && _tsc_lan_cidr | sed 's/^/lan /'; } > "$TSC_MANUAL"
					printf '{"ok":true}\n' ;;
				apply)
					_tsc_prefs
					[ -n "$TSC_KICK" ] && _tsc_kick_bg
					if _tsc_prefs_ok; then printf '{"ok":true}\n'
					else echo '{"error":"Tailscale не принял настройки — нажмите «Перезапустить» и попробуйте ещё раз"}'; return 1; fi ;;
				logout)
					rm -f "$TSC_MANUAL"
					pkill -f 'tailscale (up|login)' >/dev/null 2>&1
					_zm_tmo 15 tailscale logout >/dev/null 2>&1 || { echo '{"error":"не получилось выйти из аккаунта — смотрите журнал роутера"}'; return 1; }
					printf '{"ok":true}\n' ;;
				restart)
					_tsc_start >/dev/null 2>&1 || { echo '{"error":"служба Tailscale не запустилась — смотрите журнал роутера"}'; return 1; }
					_tsc_kick_bg
					printf '{"ok":true}\n' ;;
				exit|lan)
					case "$m" in on|off) ;; *) echo '{"error":"неизвестный режим"}'; return 1 ;; esac
					mkdir -p "$TSC_DIR"
					if [ "$a" = exit ]; then
						if [ "$m" = on ]; then rm -f "$TSC_NOEXIT"; else : > "$TSC_NOEXIT"; fi
					else
						if [ "$m" = on ]; then
							[ -n "$(_tsc_lan_cidr)" ] || { echo '{"error":"не удалось узнать подсеть домашней сети"}'; return 1; }
							: > "$TSC_LAN"
						else rm -f "$TSC_LAN"; fi
					fi
					[ "$m" = off ] && rm -f "$TSC_MANUAL"
					[ -f "$TSC_STOP" ] && { printf '{"ok":true}\n'; return 0; }
					_tsc_prefs || { echo '{"error":"Tailscale не принял настройку — смотрите журнал роутера"}'; return 1; }
					printf '{"ok":true}\n' ;;
			esac ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
}

_tsc_dot() {
	_tsc_installed || { echo 0; return; }
	if _tsc_running; then
		[ "$(cat "$TSC_STATE" 2>/dev/null)" = Running ] && echo 1 || echo 4
	elif _tsc_enabled; then echo 2; else echo 4; fi
}

MON_HTOP_PID="$JOBS_DIR/htop.pid"
MON_TTYD_OWN="$ZM_STATE_DIR/ttyd.htop"

_mon_alive() { [ -d "/proc/$1" ] && ! grep -q '^State:[[:space:]]*Z' "/proc/$1/status" 2>/dev/null; }

_mon_kill() {
	local pid="${1%%:*}" sig=TERM name ppid t=0
	case "$1" in *:KILL) sig=KILL ;; esac
	case "$pid" in ''|*[!0-9]*) echo '{"error":"неверный номер процесса"}'; return 1 ;; esac
	[ "$pid" -gt 2 ] || { echo '{"error":"этот процесс завершать нельзя"}'; return 1; }
	_mon_alive "$pid" || { echo '{"error":"процесс уже завершился"}'; return 1; }
	name="$(cat "/proc/$pid/comm" 2>/dev/null)"
	ppid="$(sed -n 's/^PPid:[[:space:]]*//p' "/proc/$pid/status" 2>/dev/null)"
	[ "$ppid" = 2 ] && { echo '{"error":"это поток ядра Linux — его не завершают"}'; return 1; }
	case "$name" in
		procd|ubusd|rpcd|uhttpd|netifd|logd|ubox|init)
			printf '{"error":"%s"}\n' "$(esc "«$name» — служба, без которой роутер или эта панель перестанут отвечать. Её не завершаем: перезапустите её в LuCI → Система → Автозагрузка")"
			return 1 ;;
	esac
	kill -s "$sig" "$pid" 2>/dev/null || { echo '{"error":"не удалось отправить сигнал процессу"}'; return 1; }
	while [ "$t" -lt 3 ] && _mon_alive "$pid"; do /bin/sleep 1; t=$((t + 1)); done
	printf '{"ok":true,"name":"%s","alive":%s}\n' "$(esc "$name")" "$(_mon_alive "$pid" && echo true || echo false)"
}

_mon_kids() { grep -l "^PPid:[[:space:]]*$1\$" /proc/[0-9]*/status 2>/dev/null | sed 's#^/proc/\([0-9]*\)/status$#\1#'; }

_mon_htop_close() {
	local p c t=0
	p="$(cat "$MON_HTOP_PID" 2>/dev/null)"
	rm -f "$MON_HTOP_PID"
	case "$p" in ''|*[!0-9]*) return 0 ;; esac
	grep -q ttyd "/proc/$p/comm" 2>/dev/null || return 0
	for c in $(_mon_kids "$p"); do kill "$c" 2>/dev/null; done
	kill "$p" 2>/dev/null
	while [ "$t" -lt 3 ] && _mon_alive "$p"; do /bin/sleep 1; t=$((t + 1)); done
	_mon_alive "$p" && kill -9 "$p" 2>/dev/null
	return 0
}

_mon_htop_open() {
	local tok port=7682 dev w="" p
	[ -x /usr/bin/htop ] || { echo '{"error":"htop не установлен"}'; return 1; }
	_term_installed || { echo '{"error":"нет ttyd — он нужен, чтобы показать htop в браузере. Нажмите «Установить htop»"}'; return 1; }
	_mon_htop_close
	tok="$(head -c 16 /dev/urandom 2>/dev/null | hexdump -v -e '/1 "%02x"' 2>/dev/null)"
	[ "${#tok}" = 32 ] || tok="$(head -c 16 /dev/urandom 2>/dev/null | od -An -tx1 2>/dev/null | tr -d ' \n')"
	[ "${#tok}" = 32 ] || { echo '{"error":"не удалось создать одноразовый адрес"}'; return 1; }
	while netstat -ltn 2>/dev/null | grep -q "[:.]${port}[[:space:]]"; do
		port=$((port + 1))
		[ "$port" -gt 7699 ] && { echo '{"error":"нет свободного порта 7682–7699"}'; return 1; }
	done
	dev="$(_mon_dev lan)"
	[ -f "$TSC_ON" ] && _tsc_wan_closed && dev=""
	ttyd --help 2>&1 | grep -q -- '--writable' && w="-W"
	( TERM=xterm-256color ttyd -p "$port" ${dev:+-i "$dev"} -o -m 1 $w -b "/$tok" htop </dev/null >/dev/null 2>&1 & echo $! > "$MON_HTOP_PID" )
	sleep 1
	p="$(cat "$MON_HTOP_PID" 2>/dev/null)"
	kill -0 "$p" 2>/dev/null || { rm -f "$MON_HTOP_PID"; echo '{"error":"ttyd с htop не запустился — смотрите журнал роутера"}'; return 1; }
	( sleep 120; [ "$(cat "$MON_HTOP_PID" 2>/dev/null)" = "$p" ] && kill -0 "$p" 2>/dev/null && [ -z "$(_mon_kids "$p")" ] && _mon_htop_close ) >/dev/null 2>&1 </dev/null &
	printf '{"ok":true,"port":%s,"path":"/%s/"}\n' "$port" "$tok"
}

do_htop_install() {
	_ensure_deps
	echo "==> Устанавливаем htop"
	mkdir -p "$ZM_STATE_DIR"; rm -f "$ZM_STATE_DIR/htop.off"
	$UPDATE || echo "!! Список пакетов не обновился — пробуем с тем, что есть"
	if [ ! -x /usr/bin/htop ]; then
		$INSTALL htop || { echo "ОШИБКА: htop не установился — проверьте интернет и доступность пакета для вашей прошивки"; return 1; }
		: > "$ZM_STATE_DIR/htop.own"
	fi
	[ -x /usr/bin/htop ] || { echo "ОШИБКА: файла /usr/bin/htop нет — пакет встал не полностью"; return 1; }
	echo "   ✓ $(htop --version 2>/dev/null | head -n1)"
	if ! _term_installed; then
		echo "==> Устанавливаем ttyd — через него htop показывается в браузере"
		$INSTALL ttyd || { echo "ОШИБКА: ttyd не установился — проверьте интернет и доступность пакета для вашей прошивки"; return 1; }
		_term_installed || { echo "ОШИБКА: файла /usr/bin/ttyd нет — пакет встал не полностью"; return 1; }
		[ -x /etc/init.d/ttyd ] && { /etc/init.d/ttyd stop >/dev/null 2>&1; /etc/init.d/ttyd disable >/dev/null 2>&1; }
		mkdir -p "$ZM_STATE_DIR"; : > "$MON_TTYD_OWN"
		echo "   ✓ ttyd $(_term_version) — только для htop, вкладка «Терминал» не включена"
	fi
	echo "==> Готово: htop установлен"
}

do_htop_remove() {
	local rc=0
	_mon_htop_close
	echo "==> Удаляем htop"
	_zm_pkg_wipe htop || rc=1
	rm -rf /etc/htoprc /root/.config/htop 2>/dev/null
	if [ -f "$MON_TTYD_OWN" ] && _term_installed && ! _term_enabled; then
		echo "==> ttyd ставился только для htop — удаляем и его"
		do_term_remove || rc=1
	fi
	rm -f "$MON_TTYD_OWN" "$ZM_STATE_DIR/htop.own"
	mkdir -p "$ZM_STATE_DIR"; : > "$ZM_STATE_DIR/htop.off"
	[ -x /usr/bin/htop ] && rc=1
	_zm_rm_done "$rc" "htop"
}

htop_gone() {
	_mon_htop_close
	if [ -f "$ZM_STATE_DIR/htop.own" ] && [ -x /usr/bin/htop ]; then
		_zm_pkg_wipe htop >/dev/null 2>&1
		rm -rf /etc/htoprc /root/.config/htop 2>/dev/null
	fi
	if [ -f "$MON_TTYD_OWN" ] && _term_installed && ! _term_enabled; then
		ZM_RM_INNER=1 do_term_remove >/dev/null 2>&1
	fi
	rm -f "$ZM_STATE_DIR/htop.own" "$MON_TTYD_OWN"
	return 0
}

monitor_action() {
	local a="$1" m="$2" j
	case "$a" in
		kill) _mon_kill "$m" ;;
		htop_install|htop_remove)
			_job_alive htop && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			if j="$(_zm_busy_job)"; then printf '{"error":"%s"}\n' "$(esc "Сейчас идёт операция: $j — дождитесь её окончания")"; return 1; fi
			if [ "$a" = htop_install ]; then job_start htop do_htop_install; else job_start htop do_htop_remove; fi ;;
		htop_open) _mon_htop_open ;;
		htop_close) _mon_htop_close; printf '{"ok":true}\n' ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
}

WATCH_OFF="$ZM_STATE_DIR/watch.off"
WATCH_CRON_LINE='*/2 * * * * /opt/zapret-manager-luci/backend.sh zm_watch >/dev/null 2>&1 # zm-rpcd-watch'

_watch_cron() {
	mkdir -p /etc/crontabs 2>/dev/null
	[ -f "$CRON_FILE" ] || : > "$CRON_FILE"
	sed -i '/# zm-rpcd-watch$/d' "$CRON_FILE"
	[ "$1" = on ] && echo "$WATCH_CRON_LINE" >> "$CRON_FILE"
	/etc/init.d/cron restart >/dev/null 2>&1
	return 0
}

watch_status() {
	local on=true cron=false last=0 items="" sep="" b
	[ -f "$WATCH_OFF" ] && on=false
	grep -q '# zm-rpcd-watch$' "$CRON_FILE" 2>/dev/null && cron=true
	[ -f "$JOBS_DIR/watch.last" ] && last="$(date -r "$JOBS_DIR/watch.last" +%s 2>/dev/null || echo 0)"
	_wi() { items="$items$sep{\"id\":\"$1\",\"title\":\"$(esc "$2")\",\"what\":\"$(esc "$3")\",\"active\":$4}"; sep=","; }
	_wi rpcd "Вход в LuCI и Web UI" "rpcd завис или не видит панель — перезапускает его. Без этого после такого сбоя войти получится только после перезагрузки роутера" true
	_wi recover "Возврат после оборванных операций" "Тест стратегий, смена DNS или сети оборвались (перезагрузка, пропало питание) — возвращает прежние настройки" true
	b=false; _ab_on && b=true
	_wi adblock "Блокировка рекламы после перезагрузки" "Списки dnsmasq живут в памяти: после перезагрузки сторож подключает их снова. Без него реклама не блокируется, пока не нажмёте «Применить» на вкладке" "$b"
	b=false; _fk_installed && ! _fk_foreign && _fk_enabled && b=true
	_wi forkozz "Forkozz" "Поднимает sing-box, если он упал, переключает на запасной сервер и возвращает правки панели после обновления движка" "$b"
	b=false; _st_installed && [ ! -f "$ST_OFF" ] && b=true
	_wi steer "Steer" "Следит за туннелями WARP и VPN по подписке, поднимает их после сбоя" "$b"
	b=false; [ -f "$TG_WATCH_FLAG" ] && _tg_any_installed && b=true
	_wi tg "TG WS Proxy" "Перезапускает прокси для Telegram, если он перестал работать" "$b"
	b=false; [ "$(_dn_get ru off)" = isp ] && b=true
	_wi dnsnet "DNS провайдера для российских сайтов" "Провайдер сменил адреса DNS — обновляет их в настройках" "$b"
	b=false; [ "$(_ver_mode)" = day ] && b=true
	_wi ver "Поиск новых версий" "$([ "$(_ver_every)" = 24 ] && echo "Раз в сутки, в $(_ver_time)" || echo "Каждые $(_ver_every) ч, начиная с $(_ver_time)"), узнаёт, вышли ли обновления панели и компонентов. Выключено — Дашборд проверит сам при открытии, если с прошлой проверки прошли сутки" "$b"
	b="$(grep -F '/opt/zapret-manager-luci/backend.sh' "$CRON_FILE" 2>/dev/null | grep -v -e '# zm-rpcd-watch$' -e '# zm-versions$' | grep -vc '^[[:space:]]*#')"
	printf '{"on":%s,"cron":%s,"last":%s,"now":%s,"others":%s,"items":[%s]}\n' "$on" "$cron" "${last:-0}" "$(date +%s)" "${b:-0}" "$items"
}

watch_set() {
	case "$1" in
		off)
			mkdir -p "$ZM_STATE_DIR"; : > "$WATCH_OFF"
			ZM_NO_CRON_RESTART=1 _ver_cron_sync
			_watch_cron off
			logger -t zapret-manager "Фоновые проверки выключены в «Системе» — сторож панели не запускается" ;;
		on)
			rm -f "$WATCH_OFF"
			ZM_NO_CRON_RESTART=1 _ver_cron_sync
			_watch_cron on
			( ZM_WATCH_FORCE=1 /opt/zapret-manager-luci/backend.sh zm_watch >/dev/null 2>&1 </dev/null & )
			logger -t zapret-manager "Фоновые проверки включены" ;;
		run)
			( ZM_WATCH_FORCE=1 /opt/zapret-manager-luci/backend.sh zm_watch >/dev/null 2>&1 </dev/null & )
			sleep 1 ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
	watch_status
}

FK_ZASH_MARK=".zm-zashboard"

_fk_ui_dir() {
	local c=/etc/sing-box/config.json ui pid base
	[ -s "$c" ] || return 1
	ui="$(jsonfilter -i "$c" -e '@.experimental.clash_api.external_ui' 2>/dev/null)"
	[ -n "$ui" ] || return 1
	case "$ui" in /*) [ -d "$ui" ] && { echo "$ui"; return 0; }; return 1 ;; esac
	pid="$(pidof sing-box sing-box-core 2>/dev/null | awk '{ print $1 }')"
	base=""
	[ -n "$pid" ] && base="$(readlink "/proc/$pid/cwd" 2>/dev/null)"
	for base in "$base" /etc/sing-box /tmp/sing-box /var/run/sing-box; do
		[ -n "$base" ] && [ -d "$base/$ui" ] && { echo "$base/$ui"; return 0; }
	done
	return 1
}

_fk_zash_ensure() {
	local quiet="$1" d stage tmp="/tmp/zm-zash" i ok=0 fail="$ZM_STATE_DIR/fk.zash.fail" now last
	[ "$(uci -q get netshift.settings.enable_yacd)" = 1 ] || return 0
	d="$(_fk_ui_dir)" || return 0
	[ -f "$d/$FK_ZASH_MARK" ] && { rm -f "$fail"; return 0; }
	now="$(date +%s)"
	if [ -n "$quiet" ]; then
		last="$(cat "$fail" 2>/dev/null)"; last="${last:-0}"
		[ $((now - last)) -lt 1800 ] && return 0
	else
		_fk_say "Ставим панель Zashboard вместо YACD"
	fi
	rm -rf "$tmp" "$tmp.zip"; mkdir -p "$tmp"
	for i in 1 2 3; do
		_zm_fetch "${GH_MAIN}/Zephyruso/zashboard/releases/latest/download/dist-cdn-fonts.zip" "$tmp.zip" 90 && { ok=1; break; }
		[ -n "$quiet" ] || _fk_say "· попытка $i из 3: $ZM_FETCH_ERR"
		sleep 1
	done
	if [ "$ok" = 1 ]; then
		command -v unzip >/dev/null 2>&1 || $INSTALL unzip >/dev/null 2>&1
		unzip -oq "$tmp.zip" -d "$tmp" >/dev/null 2>&1 || ok=0
	fi
	stage="$tmp/dist"
	[ "$ok" = 1 ] && [ -f "$stage/index.html" ] || ok=0
	if [ "$ok" = 1 ]; then
		rm -rf "$d.zm-new"
		if cp -r "$stage" "$d.zm-new" 2>/dev/null && : > "$d.zm-new/$FK_ZASH_MARK"; then
			{ rm -rf "$d" && mv "$d.zm-new" "$d"; } 2>/dev/null || { mkdir -p "$d"; cp -r "$d.zm-new"/. "$d"/ 2>/dev/null; rm -rf "$d.zm-new"; }
		else
			rm -rf "$d.zm-new"; ok=0
		fi
	fi
	rm -rf "$tmp" "$tmp.zip"
	if [ "$ok" = 1 ] && [ -f "$d/$FK_ZASH_MARK" ]; then
		rm -f "$fail"
		[ -n "$quiet" ] && logger -t zapret-manager "Forkozz: панель sing-box — Zashboard" || echo "   ✓ Zashboard установлен"
		return 0
	fi
	echo "$now" > "$fail"
	[ -n "$quiet" ] || echo "!! Zashboard поставить не удалось (GitHub недоступен или мало памяти) — остаётся стандартная панель sing-box"
	return 0
}

FK_REPO="yandexru45/netshift"
FK_PIN="0.9.12"
FK_MARK="/usr/lib/netshift/zm-managed"
FK_UC="/opt/zapret-manager-luci/netshift.uc"
FK_SB_OWN="$ZM_STATE_DIR/netshift.singbox"
FK_DEPS="ca-bundle kmod-inet-diag kmod-tun curl jq ucode ucode-mod-fs ucode-mod-uci kmod-nft-tproxy coreutils-base64 bind-dig ip-full"
FK_NFT="NetShiftTable"
FK_NFT_GUARD="NetShiftGuard"
FK_REL="env NETSHIFT_BLOCK_LEAKS_RELEASE=1"
FK_SB_PKGS="sing-box sing-box-tiny sing-box-extended podkop-engine podkop-engine-full"
FK_DEPS_OWN="$ZM_STATE_DIR/netshift.deps"
FK_FILES="/usr/lib/netshift /usr/lib/netshift.zm-old /etc/netshift /usr/bin/netshift /etc/init.d/netshift /etc/rc.d/*netshift /etc/config/netshift /etc/config/netshift-opkg /etc/config/netshift-070 /etc/config/netshift.apk-new \
/etc/init.d/netshift-naive /etc/rc.d/*netshift-naive /var/run/netshift* /var/lock/netshift* /tmp/netshift* /tmp/local-ruleset.json /tmp/local-ruleset.srs /tmp/sing-box-config.json /tmp/sing-box/rulesets /tmp/sing-box/subscription* \
/www/luci-static/resources/view/netshift /usr/share/luci/menu.d/luci-app-netshift.json /usr/share/rpcd/acl.d/luci-app-netshift.json \
/tmp/zm-fk-* /tmp/zm-zash /tmp/zm-zash.zip /opt/zapret-manager-luci/fk-rs"

_fk_say() { echo "==> $*"; }
_fk_installed() { [ -x /usr/bin/netshift ] && [ -f /usr/lib/netshift/constants.sh ]; }
_fk_version() { sed -n 's/^NETSHIFT_VERSION="\([^"]*\)".*/\1/p' /usr/lib/netshift/constants.sh 2>/dev/null | head -n1; }
_fk_enabled() { ls /etc/rc.d/S*netshift >/dev/null 2>&1; }
FK_SB_PROCS="sing-box sing-box-core"
_fk_sb_alive() { pidof $FK_SB_PROCS >/dev/null 2>&1; }
_fk_nft_on() { nft list chain inet "$FK_NFT" mangle >/dev/null 2>&1 || nft list table inet "$FK_NFT" >/dev/null 2>&1; }
_fk_up() { _fk_sb_alive && _fk_nft_on; }
FK_SERIAL_DIR="/var/run/netshift-zm-serial"
_fk_engine_busy() {
	local p
	if [ -d "$FK_SERIAL_DIR" ]; then
		p="$(cat "$FK_SERIAL_DIR/pid" 2>/dev/null)"
		case "$p" in
			''|*[!0-9]*) [ -n "$(find "$FK_SERIAL_DIR" -maxdepth 0 -mmin -1 2>/dev/null)" ] && return 0 ;;
			*) kill -0 "$p" 2>/dev/null && return 0 ;;
		esac
	fi
	ubus call service list '{"name":"netshift"}' 2>/dev/null | grep -q '"running": *true'
}
_fk_ready() { _fk_up && ! _fk_engine_busy; }
_fk_settle() {
	local i=0 max="${1:-120}"
	_fk_engine_busy || return 0
	[ -n "$2" ] && _fk_say "$2"
	while [ "$i" -lt "$max" ]; do
		sleep 1
		i=$((i + 1))
		_fk_engine_busy || return 0
	done
	return 1
}
_fk_sb_ver() { command -v sing-box >/dev/null 2>&1 && sing-box version 2>/dev/null | head -n1 | awk '{print $NF}'; }
_fk_sb_pkg() { local p; for p in sing-box-tiny sing-box sing-box-extended podkop-engine podkop-engine-full; do _pkg_is_installed "$p" && { echo "$p"; return 0; }; done; return 1; }
_fk_sb_var() {
	local v
	v="$(_fk_sb_ver)"
	[ -n "$v" ] || { echo ""; return 0; }
	case "$v" in *-lite*) echo lite; return 0 ;; *extended*) echo extended; return 0 ;; esac
	[ "$(head -c 2 /usr/bin/sing-box 2>/dev/null)" = "#!" ] && [ -f /usr/libexec/sing-box-core ] && { echo lite; return 0; }
	case "$(_fk_sb_pkg)" in
		sing-box-tiny) echo tiny ;;
		sing-box) echo stable ;;
		sing-box-extended) echo extended ;;
		*) echo manual ;;
	esac
}
_fk_sb_name() { case "$1" in tiny) echo Облегчённый ;; stable) echo Обычный ;; extended) echo Расширенный ;; lite|compact) echo "Расширенный облегчённый" ;; manual) echo "установлен вручную" ;; *) echo "$1" ;; esac; }
FK_SBL_REPO="yandexru45/sing-box-extended-lite"
_fk_sbl_latest() {
	curl -Ls --connect-timeout 5 --max-time 10 -o /dev/null -w '%{url_effective}' "https://github.com/$FK_SBL_REPO/releases/latest" 2>/dev/null |
		sed -n 's#.*/tag/[vV]\{0,1\}##p' | head -n1
}
_fk_lite_engine() { grep -q 'install_extended_lite' /usr/lib/netshift/updater.sh /usr/bin/netshift 2>/dev/null; }
_fk_lite_arch() {
	_tg_arch_init
	case "$TG_ARCH" in
		x86_64*) echo amd64 ;;
		aarch64*) echo arm64 ;;
		arm_cortex-a*|armv7*|arm_arm_cortex-a*) echo armv7 ;;
		mipsel*|mipsle*) echo mipsle-softfloat ;;
		mips64*) return 1 ;;
		mips*) echo mips-softfloat ;;
		*) return 1 ;;
	esac
}
_fk_lite_state() {
	_fk_lite_arch >/dev/null || { echo arch; return 0; }
	_fk_installed && ! _fk_lite_engine && { echo engine; return 0; }
	echo ok
}
_fk_sbx_latest() {
	curl -Ls --connect-timeout 5 --max-time 10 -o /dev/null -w '%{url_effective}' "https://github.com/shtorm-7/sing-box-extended/releases/latest" 2>/dev/null |
		sed -n 's#.*/tag/[vV]\{0,1\}##p' | head -n1
}
_fk_foreign() {
	if [ "$PKG" = apk ]; then apk info -e netshift >/dev/null 2>&1 || apk info -e luci-app-netshift >/dev/null 2>&1
	else [ -f /usr/lib/opkg/info/netshift.control ] || [ -f /usr/lib/opkg/info/luci-app-netshift.control ]; fi
}
_fk_ours() { _fk_installed && ! _fk_foreign; }
_fk_name() { if _fk_foreign; then echo NetShift; else echo Forkozz; fi; }
_fk_foreign_err() { _fk_foreign || return 1; printf '{"error":"%s","foreign":true}\n' "$(esc "Стоит NetShift отдельным пакетом — он настраивается в своём разделе: Службы → NetShift. Панель его не трогает")"; }
_fk_uc() { command -v ucode >/dev/null 2>&1 && [ -f "$FK_UC" ] || { echo '{"error":"Forkozz не установлен"}'; return 1; }; ucode "$FK_UC" "$@"; }
_fk_ucj() {
	local out rc ef="$JOBS_DIR/fk-uc.$$.err"
	mkdir -p "$JOBS_DIR"
	out="$(_fk_uc "$@" 2>"$ef")"; rc=$?
	case "$out" in
		'{'*|'['*) rm -f "$ef"; printf '%s\n' "$out" ;;
		*) [ -n "$out" ] || out="$(cat "$ef" 2>/dev/null)"; rm -f "$ef"
			printf '{"error":"%s"}\n' "$(esc "Forkozz не ответил: $(printf '%s' "${out:-пустой ответ}" | head -n 3 | tr '\t' ' ')")"; return 1 ;;
	esac
	return $rc
}

_fk_noauto() {
	if [ "$(uci -q get netshift.settings.auto_update)" = 1 ]; then
		uci -q set netshift.settings.auto_update='0' && uci -q commit netshift
		logger -t zapret-manager "Forkozz: собственное автообновление движка выключено — обновлениями управляет панель"
	fi
	if crontab -l 2>/dev/null | grep -q '/usr/bin/netshift auto_update'; then
		crontab -l 2>/dev/null | grep -v '/usr/bin/netshift auto_update' | crontab -
	fi
	return 0
}
_fk_device_setup() {
	local res
	_fk_foreign && { echo '{"ok":true,"changed":false,"foreign":true}'; return 0; }
	_fk_noauto
	res="$(_fk_ucj device_setup)" || { echo "$res"; return 1; }
	if [ "$1" = apply ] && [ "$(printf '%s' "$res" | jsonfilter -e '@.changed')" = true ] && _fk_up; then
		do_fk_service apply
	fi
}

_fk_latest_fetch() {
	local v
	v="$(_ver_gh_latest "$FK_REPO")"
	echo "$v" | grep -qE '^[0-9]+\.[0-9]+\.[0-9]+$' ||
		v="$(curl -sI -o /dev/null -w '%{redirect_url}' --connect-timeout 5 --max-time 15 "https://github.com/$FK_REPO/releases/latest" 2>/dev/null | sed -n 's#.*/releases/tag/v\{0,1\}##p')"
	echo "$v" | grep -qE '^[0-9]+\.[0-9]+\.[0-9]+$' && echo "$v"
}
_fk_latest() { _zm_cached netshift _fk_latest_fetch; }

_fk_blocker() {
	_pkg_is_installed https-dns-proxy && { echo doh; return; }
	{ _pkg_is_installed podkop || _pkg_is_installed podkop-plus || [ -x /etc/init.d/podkop ] || [ -x /etc/init.d/podkop-plus ]; } && { echo podkop; return; }
	[ -n "$(_zm_px_foreign)" ] && { echo foreign; return; }
	{ _pkg_is_installed luci-app-passwall || _pkg_is_installed luci-app-passwall2 || [ -x /etc/init.d/passwall ] || [ -x /etc/init.d/passwall2 ]; } && { echo passwall; return; }
	{ _pkg_is_installed nextdns || [ -x /etc/init.d/nextdns ]; } && { echo nextdns; return; }
	[ -x "$MIHOMO_BIN" ] && { echo mixomo; return; }
	_st_installed 2>/dev/null && { echo steer; return; }
	echo ""
}

_fk_blocker_text() {
	case "$1" in
		doh) echo "Стоит DNS over HTTPS — Forkozz шифрует DNS сам. Удалите DoH на его вкладке." ;;
		podkop) echo "Стоит Podkop — он тоже перехватывает трафик. Удалите его." ;;
		foreign) echo "Стоит $(_zm_px_foreign) — он работает на том же sing-box и тоже перехватывает трафик и DNS. Вместе с Forkozz они сломают друг друга: удалите $(_zm_px_foreign) или не ставьте Forkozz." ;;
		passwall) echo "Стоит PassWall — он тоже перехватывает трафик. Удалите его." ;;
		nextdns) echo "Стоит NextDNS — он тоже перехватывает DNS. Удалите его." ;;
		mixomo) echo "Стоит Mixomo — он тоже перехватывает трафик и DNS. Удалите его на вкладке Mixomo." ;;
		steer) echo "Стоит Steer — он тоже направляет сервисы в туннель. Удалите его на вкладке Steer." ;;
		*) echo "$1" ;;
	esac
}

_fk_warn() {
	local w=""
	[ -x /usr/bin/bytetube ] && /etc/init.d/bytetube enabled 2>/dev/null && w="$w bytetube"
	[ "$(uci -q get netshift.settings.block_leaks)" = 1 ] && [ -f /usr/lib/netshift/kill_switch.sh ] && ! _fk_up && ! _job_running forkop && w="$w leaks"
	echo $w
}

_fk_fwd_sync() {
	local want have x
	[ -f /usr/lib/netshift/dnsforward.sh ] || return 0
	[ "$(uci -q get netshift.settings.dont_touch_dhcp)" = 1 ] && return 0
	[ "$(uci -q get dhcp.@dnsmasq[0].netshift_configured)" = 1 ] || return 0
	_fk_up || return 0
	want="$(uci -q get netshift.settings.dns_forward)"
	for x in $want; do case "$x" in /*/*) ;; *) return 0 ;; esac; done
	want="$(printf '%s\n' $want | sed '/^$/d' | sort -u)"
	have="$(printf '%s\n' $(uci -q get dhcp.@dnsmasq[0].server) | grep '^/' | sort -u)"
	[ "$want" = "$have" ] && return 0
	for x in $have; do uci -q del_list "dhcp.@dnsmasq[0].server=$x"; done
	for x in $want; do uci -q add_list "dhcp.@dnsmasq[0].server=$x"; done
	uci -q commit dhcp
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	return 0
}

_fk_naive_arch() {
	local a
	a="$(sed -n "s/^DISTRIB_ARCH=['\"]\{0,1\}\([^'\"]*\)['\"]\{0,1\}$/\1/p" /etc/openwrt_release 2>/dev/null | head -n1)"
	case "$a" in
		aarch64_cortex-a76) a=aarch64_generic ;;
		i386_pentium-mmx|i386_pentium4) a=x86 ;;
		mipsel_24kc_24kf|mipsel_74kc) a=mipsel_24kc ;;
		riscv64_riscv64) a=riscv64 ;;
	esac
	echo "$a"
}

_fk_naive_need() {
	[ -f /usr/lib/netshift/naive.sh ] || return 1
	grep -Eqi "'naive\+(https|quic)://" /etc/config/netshift 2>/dev/null || return 1
	[ -x /usr/bin/naive ] || [ -x /usr/bin/naiveproxy ] || command -v naive >/dev/null 2>&1 && return 1
	grep -q '^get_core_capabilities)' /usr/bin/netshift 2>/dev/null &&
		/usr/bin/netshift get_core_capabilities 2>/dev/null | jq -e '.naive_core == true' >/dev/null 2>&1 && return 1
	return 0
}

_fk_naive_install() {
	local arch rel asset url dig d x sz fr act unx
	arch="$(_fk_naive_arch)"
	[ -n "$arch" ] || { echo "не удалось определить архитектуру роутера"; return 1; }
	d="$JOBS_DIR/fk-naive"
	rm -rf "$d"; mkdir -p "$d/x"
	_zm_gh_get "https://api.github.com/repos/klzgrad/naiveproxy/releases/latest" "$d/rel.json" "" 30 || { rm -rf "$d"; echo "GitHub не ответил — ни напрямую, ни через WARP"; return 1; }
	rel="$(jq -r '.tag_name // empty' "$d/rel.json" 2>/dev/null)"
	[ -n "$rel" ] || { rm -rf "$d"; echo "GitHub прислал непонятный ответ"; return 1; }
	local a
	for a in $(_zm_arch_alts "$arch"); do
		asset="naiveproxy-$rel-openwrt-$a.tar.xz"
		url="$(jq -r --arg n "$asset" '[.assets[]? | select(.name == $n) | .browser_download_url] | first // empty' "$d/rel.json")"
		[ -n "$url" ] && { [ "$a" = "$arch" ] || echo "   · Сборки NaiveProxy для $arch нет — берём совместимую $a"; arch="$a"; break; }
	done
	dig="$(jq -r --arg n "$asset" '[.assets[]? | select(.name == $n) | .digest] | first // empty' "$d/rel.json")"
	[ -n "$url" ] || { rm -rf "$d"; echo "для архитектуры $arch сборки NaiveProxy нет"; return 1; }
	if command -v xz >/dev/null 2>&1; then unx="xz -dc"
	elif command -v unxz >/dev/null 2>&1; then unx="unxz -c"
	else
		$INSTALL xz >/dev/null 2>&1
		command -v xz >/dev/null 2>&1 || { rm -rf "$d"; echo "не удалось поставить пакет xz для распаковки"; return 1; }
		mkdir -p "$ZM_STATE_DIR"; grep -qx xz "$FK_DEPS_OWN" 2>/dev/null || echo xz >> "$FK_DEPS_OWN"
		unx="xz -dc"
	fi
	echo "   → Скачиваем NaiveProxy $rel для $arch"
	_zm_gh_get "$url" "$d/n.tar.xz" "" 300 || { rm -rf "$d"; echo "архив не скачался"; return 1; }
	case "$dig" in sha256:*)
		act="$(sha256sum "$d/n.tar.xz" 2>/dev/null | awk '{print $1}')"
		[ "$act" = "$(echo "${dig#sha256:}" | tr 'A-F' 'a-f')" ] || { rm -rf "$d"; echo "архив не совпал с контрольной суммой релиза"; return 1; } ;;
	esac
	$unx "$d/n.tar.xz" 2>/dev/null | tar -x -C "$d/x" 2>/dev/null
	rm -f "$d/n.tar.xz"
	x="$(find "$d/x" -type f -name naive 2>/dev/null | head -n1)"
	[ -n "$x" ] || { rm -rf "$d"; echo "в архиве нет программы naive"; return 1; }
	chmod 0755 "$x"
	"$x" --version >/dev/null 2>&1
	case "$?" in 126|127) rm -rf "$d"; echo "NaiveProxy не запускается на этом роутере"; return 1 ;; esac
	sz="$(du -k "$x" 2>/dev/null | awk '{print $1}')"
	fr="$(df -Pk /usr/bin 2>/dev/null | awk 'NR==2 {print $4}')"
	if [ -n "$sz" ] && [ -n "$fr" ] && [ "$fr" -lt $((sz + 1024)) ]; then rm -rf "$d"; echo "не хватает памяти: нужно $(((sz + 1023) / 1024)) МБ"; return 1; fi
	cp "$x" /usr/bin/naive.zm-new && mv /usr/bin/naive.zm-new /usr/bin/naive || { rm -f /usr/bin/naive.zm-new; rm -rf "$d"; echo "не удалось записать /usr/bin/naive"; return 1; }
	chmod 0755 /usr/bin/naive
	mkdir -p /etc/netshift
	echo "${rel#v}" > /etc/netshift/naive.version
	rm -rf "$d"
	echo "   ✓ Клиент NaiveProxy ${rel#v} установлен"
	return 0
}

_fk_naive_auto() {
	local r
	_fk_naive_need || return 0
	if [ -f "$FK_NAIVE_FAIL" ] && [ -z "$(find "$FK_NAIVE_FAIL" -mmin +720 2>/dev/null)" ]; then
		_rb_warn "Клиент NaiveProxy недавно поставить не удалось — серверы NaiveProxy пока пропускаются"
		return 0
	fi
	_fk_say "Среди серверов есть NaiveProxy — ставим его клиент с GitHub"
	if r="$(_fk_naive_install)"; then
		printf '%s\n' "$r"
		rm -f "$FK_NAIVE_FAIL"
	else
		printf '%s\n' "$r" | grep '^   '
		mkdir -p "$ZM_STATE_DIR"; touch "$FK_NAIVE_FAIL"
		_rb_warn "Клиент NaiveProxy не встал: $(printf '%s\n' "$r" | grep -v '^   ' | tail -n1) — серверы NaiveProxy пропускаются"
	fi
	return 0
}

_fk_health() {
	_fk_ours || { echo 0; return; }
	_fk_enabled || { echo 5; return; }
	_fk_up && echo 1 || echo 2
}

forkop_status() {
	local inst=false ver="" latest="" newer=false en=false up=false sb sbp="" blk busy=false warn="" x sbu=""
	_fk_installed && { inst=true; ver="$(_fk_version)"; }
	latest="$(_fk_latest)"
	[ -n "$ver" ] && [ -n "$latest" ] && _st_ver_lt "$ver" "$latest" && newer=true
	_fk_enabled && en=true
	_fk_up && up=true
	sb="$(_fk_sb_ver)"
	sbp="$(_fk_sb_var)"
	[ "$inst" = false ] && [ -n "$sb" ] && sbu="$(_fk_sb_users)"
	blk="$(_fk_blocker)"
	_job_running forkop && busy=true
	for x in $(_fk_warn); do warn="$warn${warn:+,}\"$x\""; done
	printf '{"installed":%s,"version":"%s","latest":"%s","newer":%s,"enabled":%s,"running":%s,"managed":%s,"foreign":%s,"singbox":"%s","singbox_pkg":"%s","singbox_users":"%s","blocker":"%s","blocker_text":"%s","warn":[%s],"busy":%s,"lan_ip":"%s","watch":%s,"hosts_extra":%s,"sb_lite":"%s"}\n' \
		"$inst" "$(esc "$ver")" "$(esc "$latest")" "$newer" "$en" "$up" \
		"$([ -f "$FK_MARK" ] && echo true || echo false)" "$(_fk_foreign && echo true || echo false)" \
		"$(esc "$sb")" "$(esc "$sbp")" "$(esc "$sbu")" "$(esc "$blk")" "$(esc "$(_fk_blocker_text "$blk")")" "$warn" "$busy" \
		"$(esc "$(_zm_lan_ip)")" \
		"$(awk '{print $1 + 0; exit}' "$ZM_STATE_DIR/fk.watch" 2>/dev/null | grep . || echo 0)" "$(_hosts_extra)" "$(_fk_lite_state)"
}

_fk_restore_old() {
	[ -d /usr/lib/netshift.zm-old ] || return 0
	rm -rf /usr/lib/netshift
	mv /usr/lib/netshift.zm-old/.bin /usr/bin/netshift 2>/dev/null
	mv /usr/lib/netshift.zm-old/.init /etc/init.d/netshift 2>/dev/null
	rm -f /etc/init.d/netshift-naive
	mv /usr/lib/netshift.zm-old/.naive /etc/init.d/netshift-naive 2>/dev/null
	mv /usr/lib/netshift.zm-old /usr/lib/netshift
	_fk_say "Вернули прежнюю версию Forkozz"
}

_fk_sb_pkg_switch() {
	local want="$1" pkg tmp="$JOBS_DIR/fk-sb-bak" oldpkg p f moved=""
	case "$want" in tiny) pkg=sing-box-tiny ;; *) pkg=sing-box ;; esac
	oldpkg="$(_fk_sb_pkg)"
	rm -rf "$tmp"; mkdir -p "$tmp"
	_fk_say "Ставим пакет $pkg из репозитория OpenWrt"
	if [ -z "$oldpkg" ]; then
		for f in /usr/bin/sing-box /usr/lib/libcronet.so /usr/libexec/sing-box-core /etc/init.d/sing-box; do
			[ -e "$f" ] || continue
			mkdir -p "$tmp/keep${f%/*}"
			mv -f "$f" "$tmp/keep$f" 2>/dev/null && moved="$moved $f"
		done
		[ -n "$moved" ] && echo "   → Убираем прежний sing-box, поставленный не пакетом:$(echo "$moved" | sed 's# /# /#g')"
	else
		[ -e /usr/bin/sing-box ] && cp -p /usr/bin/sing-box "$tmp/sing-box" 2>/dev/null
		[ -e /etc/init.d/sing-box ] && cp -p /etc/init.d/sing-box "$tmp/init" 2>/dev/null
	fi
	for p in $FK_SB_PKGS; do
		[ "$p" = "$pkg" ] && continue
		_pkg_is_installed "$p" && { echo "   → Удаляем прежний пакет $p"; $DELETE "$p" >/dev/null 2>&1; }
	done
	if _pkg_is_installed "$pkg"; then
		echo "   → Переустанавливаем пакет $pkg"
		if command -v apk >/dev/null 2>&1; then apk fix --reinstall "$pkg" >/dev/null 2>&1 || apk add --force-overwrite "$pkg" >/dev/null 2>&1
		else opkg install --force-reinstall "$pkg" >/dev/null 2>&1; fi
	else
		echo "   → Скачиваем и ставим пакет $pkg"
		$INSTALL "$pkg" >/dev/null 2>&1
	fi
	if _pkg_is_installed "$pkg" && [ -x /usr/bin/sing-box ] && sing-box version >/dev/null 2>&1 && ! _fk_sb_is_ext; then
		echo "   ✓ Пакет $pkg на месте, sing-box $(_fk_sb_ver) запускается"
		rm -rf "$tmp"
		_fk_sb_leftovers
		return 0
	fi
	echo "   → Пакет $pkg не установился — возвращаем прежний sing-box"
	_pkg_is_installed "$pkg" && [ "$pkg" != "$oldpkg" ] && $DELETE "$pkg" >/dev/null 2>&1
	[ -n "$oldpkg" ] && [ "$oldpkg" != "$pkg" ] && ! _pkg_is_installed "$oldpkg" && $INSTALL "$oldpkg" >/dev/null 2>&1
	for f in $moved; do mkdir -p "${f%/*}"; mv -f "$tmp/keep$f" "$f" 2>/dev/null; done
	[ -s "$tmp/sing-box" ] && ! sing-box version >/dev/null 2>&1 && cp -p "$tmp/sing-box" /usr/bin/sing-box 2>/dev/null
	[ -s "$tmp/init" ] && [ ! -e /etc/init.d/sing-box ] && { cp -p "$tmp/init" /etc/init.d/sing-box 2>/dev/null; chmod 0755 /etc/init.d/sing-box 2>/dev/null; }
	rm -rf "$tmp"
	return 1
}

_fk_sb_drop_pkgs() {
	local p had="" k="$JOBS_DIR/fk-sb-keep"
	for p in $FK_SB_PKGS; do _pkg_is_installed "$p" && had="$had $p"; done
	case " $had " in *" sing-box-tiny "*) had="$(echo $had | tr ' ' '\n' | grep -vx 'sing-box' | tr '\n' ' ')" ;; esac
	[ -n "$(echo $had)" ] || { _fk_sb_leftovers; return 0; }
	rm -rf "$k"; mkdir -p "$k"
	cp -p /etc/init.d/sing-box "$k/init" 2>/dev/null
	cp -p /etc/config/sing-box "$k/config" 2>/dev/null
	mv -f /usr/bin/sing-box /usr/bin/.sing-box.zm-keep 2>/dev/null || { rm -rf "$k"; return 1; }
	$DELETE $had >/dev/null 2>&1
	mv -f /usr/bin/.sing-box.zm-keep /usr/bin/sing-box
	[ -e /etc/init.d/sing-box ] || { cp -p "$k/init" /etc/init.d/sing-box 2>/dev/null; chmod 0755 /etc/init.d/sing-box 2>/dev/null; }
	[ -e /etc/config/sing-box ] || cp -p "$k/config" /etc/config/sing-box 2>/dev/null
	mkdir -p /etc/sing-box
	rm -rf "$k"
	_fk_sb_leftovers
	echo "   ✓ Прежний sing-box удалён полностью (пакет$(echo "$had" | sed 's/^ / /; s/ \([^ ]\)/, \1/g; s/^,//')) — остался только $([ "$(_fk_sb_var)" = lite ] && echo "расширенный облегчённый" || echo "расширенный")"
}

_fk_sb_leftovers() {
	local var
	var="$(_fk_sb_var)"
	rm -f /usr/bin/.sing-box.zm-keep 2>/dev/null
	rm -rf /tmp/netshift-sbext.* /tmp/netshift-sblite.* 2>/dev/null
	[ "$var" = lite ] || rm -f /usr/libexec/sing-box-core /etc/netshift/core-version.cache /etc/sing-box-version.cache 2>/dev/null
	case "$var" in extended|lite) ;; *) rm -f /usr/lib/libcronet.so 2>/dev/null ;; esac
	return 0
}

_fk_sb_init_write() {
	[ -x /etc/init.d/sing-box ] && [ -s /etc/config/sing-box ] && return 1
	mkdir -p /etc/init.d /etc/config /etc/sing-box
	if [ ! -x /etc/init.d/sing-box ]; then
		cat > /etc/init.d/sing-box << 'ZM_SB_INIT_EOF'
#!/bin/sh /etc/rc.common

USE_PROCD=1
START=99

script=$(readlink "$initscript")
NAME="$(basename ${script:-$initscript})"
PROG="/usr/bin/sing-box"

start_service() {
	config_load "$NAME"

	local enabled user group conffile workdir ifaces
	config_get_bool enabled "main" "enabled" "0"
	[ "$enabled" -eq "1" ] || return 0

	config_get user "main" "user" "root"
	config_get conffile "main" "conffile"
	config_get ifaces "main" "ifaces"
	config_get workdir "main" "workdir" "/usr/share/sing-box"

	mkdir -p "$workdir"
	local group="$(id -ng $user)"
	chown $user:$group "$workdir"

	procd_open_instance "$NAME.main"
	procd_set_param command "$PROG" run -c "$conffile" -D "$workdir"

	procd_set_param user "$user"
	procd_set_param file "$conffile"
	[ -z "$ifaces" ] || procd_set_param netdev $ifaces
	procd_set_param stdout 1
	procd_set_param stderr 1
	procd_set_param respawn

	procd_close_instance
}

service_triggers() {
	local ifaces
	config_load "$NAME"
	config_get ifaces "main" "ifaces"
	procd_open_trigger
	for iface in $ifaces; do
		procd_add_interface_trigger "interface.*.up" $iface /etc/init.d/$NAME restart
	done
	procd_close_trigger
	procd_add_reload_trigger "$NAME"
}
ZM_SB_INIT_EOF
		chmod 0755 /etc/init.d/sing-box
	fi
	if [ ! -s /etc/config/sing-box ]; then
		printf "\nconfig sing-box 'main'\n\toption enabled '0'\n\toption user 'root'\n\toption conffile '/etc/sing-box/config.json'\n\toption workdir '/usr/share/sing-box'\n" > /etc/config/sing-box
		chmod 0644 /etc/config/sing-box
	fi
	return 0
}

_fk_sb_install() {
	local v up=0 own=""
	rm -f /tmp/zm-fk-rlcore
	v="$(_fk_sb_ver)"
	if [ -n "$v" ] && ! _st_ver_lt "$v" 1.12.0 && [ -x /etc/init.d/sing-box ]; then
		_fk_say "sing-box $v уже установлен ($(_fk_sb_name "$(_fk_sb_var)")) — оставляем его"
		return 0
	fi
	if [ -n "$v" ] && _st_ver_lt "$v" 1.12.0; then _fk_say "sing-box $v слишком старый для Forkozz (нужен 1.12 и новее) — заменяем"
	elif [ -n "$v" ]; then _fk_say "У sing-box $v нет службы запуска — ставим заново"; fi
	if [ "$1" != stable ] && _fk_lite_arch >/dev/null && _fk_lite_engine; then
		/etc/init.d/netshift running >/dev/null 2>&1 && up=1
		_fk_sb_init_write && own=1
		ZM_FK_SB_NESTED=1; ZM_FK_SB_FRESH=1
		do_fk_singbox lite norestart; v=$?
		ZM_FK_SB_NESTED=""; ZM_FK_SB_FRESH=""
		[ "$up" = 0 ] && /etc/init.d/netshift running >/dev/null 2>&1 && _zm_run 60 $FK_REL /etc/init.d/netshift stop >/dev/null 2>&1
		if [ "$v" = 0 ] && [ "$(_fk_sb_var)" = lite ]; then
			mkdir -p "$ZM_STATE_DIR"; echo sing-box > "$FK_SB_OWN"
			return 0
		fi
		[ -n "$own" ] && [ -z "$(_fk_sb_pkg)" ] && rm -f /etc/init.d/sing-box /etc/config/sing-box
		_fk_say "Расширенный облегчённый sing-box не встал — ставим облегчённый из репозитория OpenWrt. Перейти на расширенный облегчённый можно позже в «Настройках» → sing-box"
	elif [ "$1" != stable ] && ! _fk_lite_arch >/dev/null; then
		_fk_say "Расширенного облегчённого sing-box для этого роутера ($TG_ARCH) нет — ставим облегчённый из репозитория OpenWrt"
	fi
	if [ "$1" != stable ] && _fk_sb_pkg_switch tiny; then :
	else
		[ "$1" != stable ] && _fk_say "Облегчённого sing-box для этого роутера нет — ставим обычный"
		_fk_sb_pkg_switch stable || { echo "ОШИБКА: sing-box не установился"; return 1; }
	fi
	_fk_sb_pkg > "$FK_SB_OWN"
	_fk_say "sing-box $(_fk_sb_ver) установлен ($(_fk_sb_name "$(_fk_sb_var)"))"
	return 0
}

_fk_sb_users() {
	local p u=""
	for p in podkop podkop-plus forkop luci-app-forkop tachyon luci-app-tachyon luci-app-passwall luci-app-passwall2 luci-app-homeproxy homeproxy luci-app-ssr-plus luci-app-momo momo; do
		_pkg_is_installed "$p" && u="$u${u:+, }$p"
	done
	for p in podkop podkop-plus forkop tachyon passwall passwall2 homeproxy momo; do
		[ -x "/etc/init.d/$p" ] && ! echo ", $u," | grep -q ", $p," && u="$u${u:+, }$p"
	done
	echo "$u"
}

_fk_sb_purge() {
	local p had="" v var u
	u="$(_fk_sb_users)"
	if [ -n "$u" ]; then
		_fk_say "sing-box оставляем — он нужен: $u"
		return 0
	fi
	v="$(_fk_sb_ver)"
	var="$(_fk_sb_var)"
	for p in $FK_SB_PKGS; do _pkg_is_installed "$p" && had="$had $p"; done
	_fk_say "Удаляем sing-box${v:+ $v}${var:+ ($(_fk_sb_name "$var"))} — все варианты, файлы, настройки и кэш"
	echo "   → Останавливаем sing-box и убираем из автозапуска"
	if [ -x /etc/init.d/sing-box ]; then
		/etc/init.d/sing-box stop >/dev/null 2>&1
		/etc/init.d/sing-box disable >/dev/null 2>&1
	fi
	if _fk_sb_alive; then
		killall $FK_SB_PROCS >/dev/null 2>&1
		sleep 1
		killall -9 $FK_SB_PROCS >/dev/null 2>&1
	fi
	ZM_PKG_QUIET=1
	for p in $had; do _zm_pkg_purge "$p"; done
	ZM_PKG_QUIET=""
	if _zm_wipe /usr/bin/sing-box /etc/sing-box /etc/config/sing-box /etc/config/sing-box-opkg /etc/config/sing-box.apk-new /var/run/sing-box /tmp/sing-box /usr/share/sing-box /etc/init.d/sing-box \
		/usr/lib/libcronet.so /usr/libexec/sing-box-core /etc/sing-box-version.cache /etc/netshift/core-version.cache \
		/usr/bin/.sing-box.zm-keep /etc/rc.d/*sing-box /etc/rc.d/*podkop-engine /etc/init.d/podkop-engine /usr/libexec/podkop-engine "$FK_SB_OWN" &&
		[ -z "$(_fk_sb_pkg)" ] && [ -z "$(_fk_sb_ver)" ]; then
		echo "   ✓ sing-box удалён вместе с настройками и кэшем"
		return 0
	fi
	echo "!! sing-box удалить до конца не получилось"
	return 1
}

_fk_dnsmasq_clean() {
	local s v o x ch=0 left pre own bk
	for s in $(uci -q show dhcp | sed -n "s/^dhcp\.\([^.=]*\)=dnsmasq\$/\1/p"); do
		own=0
		[ -n "$(uci -q get "dhcp.$s.netshift_configured")" ] && own=1
		bk="$(uci -q get "dhcp.$s.netshift_dnsmasq_backup")"
		[ "$bk" = 1 ] && own=1
		for pre in netshift; do
			for o in noresolv cachesize; do
				if uci -q get "dhcp.$s.${pre}_$o" >/dev/null; then
					v="$(uci -q get "dhcp.$s.${pre}_$o")"
					if [ -n "$v" ]; then uci -q set "dhcp.$s.$o=$v"; else uci -q delete "dhcp.$s.$o"; fi
					uci -q delete "dhcp.$s.${pre}_$o"
					ch=1
				elif [ "$bk" = 1 ] && [ "$(uci -q get "dhcp.$s.${pre}_${o}_set")" != 1 ] && uci -q get "dhcp.$s.$o" >/dev/null; then
					uci -q delete "dhcp.$s.$o"
					ch=1
				fi
				uci -q get "dhcp.$s.${pre}_${o}_set" >/dev/null && { uci -q delete "dhcp.$s.${pre}_${o}_set"; ch=1; }
			done
			if uci -q get "dhcp.$s.${pre}_server" >/dev/null; then
				v="$(uci -q get "dhcp.$s.${pre}_server")"
				uci -q delete "dhcp.$s.server"
				for x in $v; do uci -q add_list "dhcp.$s.server=$x"; done
				uci -q delete "dhcp.$s.${pre}_server"
				ch=1
			elif [ "$own" = 1 ] && uci -q get "dhcp.$s.server" >/dev/null; then
				uci -q delete "dhcp.$s.server"
				ch=1
			fi
		done
		uci -q get "dhcp.$s.netshift_configured" >/dev/null && { uci -q delete "dhcp.$s.netshift_configured"; ch=1; }
		uci -q get "dhcp.$s.netshift_dnsmasq_backup" >/dev/null && { uci -q delete "dhcp.$s.netshift_dnsmasq_backup"; ch=1; }
		for v in $(uci -q get "dhcp.$s.server"); do
			case "$v" in 127.0.0.4[0-9]|127.0.0.4[0-9]#*) uci -q del_list "dhcp.$s.server=$v"; ch=1 ;; esac
		done
		left="$(uci -q get "dhcp.$s.server" | tr ' ' '\n' | grep -v '^/')"
		if [ -z "$left" ] && [ "$(uci -q get "dhcp.$s.noresolv")" = 1 ]; then
			uci -q delete "dhcp.$s.noresolv"
			ch=1
		fi
		[ "$(uci -q get "dhcp.$s.cachesize")" = 0 ] && { uci -q delete "dhcp.$s.cachesize"; ch=1; }
	done
	if [ "$ch" = 1 ]; then
		uci -q commit dhcp
		[ "$1" = q ] || echo "   ✓ Настройки DNS роутера возвращены"
	fi
	return 0
}

_fk_ip_clean() {
	local f l pr t
	for t in netshift; do
		for f in "" -6; do
			ip $f rule show 2>/dev/null | grep -i "lookup $t" | while IFS= read -r l; do
				pr="${l%%:*}"
				ip $f rule del pref "$pr" >/dev/null 2>&1
			done
			ip $f route flush table "$t" >/dev/null 2>&1
		done
		grep -qi "[[:space:]]$t\$" /etc/iproute2/rt_tables 2>/dev/null && sed -i "/[[:space:]]$t\$/d" /etc/iproute2/rt_tables
	done
	if ip rule show 2>/dev/null | grep -qi 'netshift'; then
		[ "$1" = q ] || echo "!! Часть правил маршрутизации Forkozz осталась — они пропадут после перезагрузки роутера"
		return 1
	fi
	[ "$1" = q ] || echo "   ✓ Правила маршрутизации Forkozz убраны"
	return 0
}

_fk_fast_patch() {
	local f=/usr/lib/netshift/rulesets.sh n
	[ -f "$f" ] && [ -f /usr/lib/netshift/nft.sh ] && [ -f /usr/lib/netshift/helpers.sh ] || return 0
	grep -q '^# zm-fast-begin 3$' "$f" && return 0
	for n in patch_source_ruleset_rules import_plain_domain_list_to_local_source_ruleset_chunked import_plain_subnet_list_to_local_source_ruleset_chunked extract_ip_cidr_from_json_ruleset_to_file; do
		grep -q "^$n() {" "$f" || return 0
	done
	grep -q '^nft_add_set_elements() {' /usr/lib/netshift/nft.sh && grep -q '^nft_add_set_elements_from_file_chunked() {' /usr/lib/netshift/nft.sh || return 0
	grep -q '^comma_string_to_json_array() {' /usr/lib/netshift/helpers.sh || return 0
	grep -q '^# zm-fast-begin' "$f" && sed -i '/^# zm-fast-begin/,/^# zm-fast-end$/d' "$f"
	cat >> "$f" << 'ZM_FK_FAST_EOF'
# zm-fast-begin 3
_zm_fast_subnets() {
	awk -v n="$2" '{ gsub(/\r/, ""); sub(/^[ \t]+/, ""); sub(/[ \t]+$/, ""); if ($0 == "") next
		m = split($0, p, "/"); if (m > 2) next
		if (m == 2 && (p[2] !~ /^[0-9]+$/ || length(p[2]) > 2 || p[2] + 0 > 32)) next
		if (split(p[1], o, ".") != 4) next
		ok = 1; for (i = 1; i <= 4; i++) if (o[i] !~ /^(0|[1-9][0-9]?[0-9]?)$/ || o[i] + 0 > 255) ok = 0
		if (!ok || ($0 in seen)) next
		seen[$0] = 1; buf = buf (c ? "," : "") $0
		if (++c == n) { print buf; buf = ""; c = 0 } }
		END { if (c) print buf }' "$1"
}

_zm_fast_domains() {
	awk -v n="$2" -v px="$3" '{ gsub(/\r/, ""); sub(/^[ \t]+/, ""); sub(/[ \t]+$/, ""); if ($0 == "") next
		d = tolower($0); if (px && d ~ /^(full|keyword|regexp?):/) next
		sub(/^(full|domain|suffix):/, "", d); t = d; sub(/^\./, "", t)
		if (t !~ /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*$/) next
		if (t ~ /^[0-9.]+$/ || (d in seen)) next
		seen[d] = 1; buf = buf (c ? "," : "") d
		if (++c == n) { print buf; buf = ""; c = 0 } }
		END { if (c) print buf }' "$1"
}

import_plain_domain_list_to_local_source_ruleset_chunked() {
	local plain_list_filepath="$1" ruleset_filepath="$2" chunk_size="${3:-1000}" zm_tmp zm_line zm_px="" zm_work
	command -v _import_plain_domain_list_into >/dev/null 2>&1 && command -v domain_rule_normalize >/dev/null 2>&1 && zm_px=1
	zm_tmp="$(mktemp)"
	_zm_fast_domains "$plain_list_filepath" "$chunk_size" "$zm_px" > "$zm_tmp"
	while IFS= read -r zm_line; do
		[ -n "$zm_line" ] || continue
		patch_source_ruleset_rules "$ruleset_filepath" "domain_suffix" "$(comma_string_to_json_array "$zm_line")"
	done < "$zm_tmp"
	if [ -n "$zm_px" ]; then
		tr -d '\r' < "$plain_list_filepath" | sed 's/^[[:space:]]*//;s/[[:space:]]*$//' | grep -Ei '^(full|keyword|regexp?):' > "$zm_tmp"
		if [ -s "$zm_tmp" ] && zm_work="$(mktemp -d)"; then
			( _import_plain_domain_list_into "$zm_work" "$zm_tmp" "$ruleset_filepath" "$chunk_size" )
			rm -rf "$zm_work"
		fi
	fi
	rm -f "$zm_tmp"
}

import_plain_subnet_list_to_local_source_ruleset_chunked() {
	local plain_list_filepath="$1" ruleset_filepath="$2" chunk_size="${3:-1000}" zm_tmp zm_line
	zm_tmp="$(mktemp)"
	_zm_fast_subnets "$plain_list_filepath" "$chunk_size" > "$zm_tmp"
	while IFS= read -r zm_line; do
		[ -n "$zm_line" ] || continue
		patch_source_ruleset_rules "$ruleset_filepath" "ip_cidr" "$(comma_string_to_json_array "$zm_line")"
	done < "$zm_tmp"
	rm -f "$zm_tmp"
}

nft_add_set_elements_from_file_chunked() {
	local filepath="$1" nft_table_name="$2" nft_set_name="$3" chunk_size="${4:-5000}" zm_tmp zm_line
	zm_tmp="$(mktemp)"
	_zm_fast_subnets "$filepath" "$chunk_size" > "$zm_tmp"
	while IFS= read -r zm_line; do
		[ -n "$zm_line" ] || continue
		nft_add_set_elements "$nft_table_name" "$nft_set_name" "$zm_line"
	done < "$zm_tmp"
	rm -f "$zm_tmp"
}

extract_ip_cidr_from_json_ruleset_to_file() {
	jq -r '.rules[]? | .ip_cidr? // empty | if type == "array" then .[] else . end' "$1" > "$2" 2>/dev/null
}
# zm-fast-end
ZM_FK_FAST_EOF
	return 0
}

_fk_b4_watch() {
	local f="$JOBS_DIR/fk-b4.last"
	grep -qi 'greeg0ry/b4geoip-forkop/releases/' /etc/config/netshift 2>/dev/null || return 0
	[ -n "$(find "$f" -mmin -30 2>/dev/null)" ] && return 0
	_job_running forkop && return 0
	mkdir -p "$JOBS_DIR"; : > "$f"
	( _fk_device_setup apply >/dev/null 2>&1 </dev/null & )
	return 0
}

_fk_ghdl_patch() {
	local f=/usr/lib/netshift/helpers.sh
	[ -f "$f" ] || return 0
	grep -q '^# zm-ghdl-begin 1$' "$f" && return 0
	if grep -q '^# zm-ghdl-begin' "$f"; then
		sed -i '/^# zm-ghdl-begin/,/^# zm-ghdl-end$/d' "$f"
	else
		[ "$(grep -c '^download_to_file() {$' "$f")" = 1 ] && grep -q '^redact_url_for_log() {$' "$f" || return 0
		sed -i 's/^download_to_file() {$/zm_download_to_file_raw() {/' "$f"
	fi
	grep -q '^zm_download_to_file_raw() {$' "$f" || return 0
	cat >> "$f" << 'ZM_FK_GHDL_EOF'
# zm-ghdl-begin 1
download_to_file() {
	local zm_url="$1" zm_fp="$2" zm_m zm_slow=/tmp/netshift.zm-ghslow zm_skip=""
	case "$zm_url" in
		https://github.com/*|https://raw.githubusercontent.com/*|https://objects.githubusercontent.com/*|https://release-assets.githubusercontent.com/*|https://codeload.github.com/*) ;;
		*) zm_download_to_file_raw "$@"; return ;;
	esac
	[ -n "$3" ] && { zm_download_to_file_raw "$@"; return; }
	[ -n "${ZM_GHDL_MS+x}" ] || ZM_GHDL_MS="$(/opt/zapret-manager-luci/backend.sh gh_mirrors 2>/dev/null)"
	[ -n "$ZM_GHDL_MS" ] || { zm_download_to_file_raw "$@"; return; }
	if [ -n "$(find "$zm_slow" -mmin -30 2>/dev/null)" ]; then zm_skip=1
	else
		zm_download_to_file_raw "$@" && return 0
		: > "$zm_slow"
	fi
	for zm_m in $ZM_GHDL_MS; do
		log "Downloading via GitHub mirror $zm_m: $(redact_url_for_log "$zm_url")" "warn"
		if zm_download_to_file_raw "https://$zm_m/$zm_url" "$zm_fp" "" 1 1 15 && [ -s "$zm_fp" ] && ! head -c 512 "$zm_fp" | grep -qiE '<(!doctype|html)'; then
			log "Downloaded via GitHub mirror $zm_m" "info"
			return 0
		fi
	done
	if [ -n "$zm_skip" ] && zm_download_to_file_raw "$zm_url" "$zm_fp" "" 1 1 10; then rm -f "$zm_slow"; return 0; fi
	return 1
}
# zm-ghdl-end
ZM_FK_GHDL_EOF
	return 0
}

_fk_subck_patch() {
	local f=/usr/lib/netshift/helpers.sh b
	[ -f "$f" ] || return 0
	grep -q '^# zm-subck-begin 1$' "$f" && return 0
	b="$f.zm-subck"
	cp -f "$f" "$b" || return 0
	if grep -q '^# zm-subck-begin' "$f"; then
		sed -i '/^# zm-subck-begin/,/^# zm-subck-end$/d' "$f"
	else
		[ "$(grep -c '^_wget_subscription_request() {$' "$f")" = 1 ] &&
			grep -q '^    local req_url="\$9"$' "$f" &&
			grep -q -- '--header "X-HWID: \$req_hwid"' "$f" || { rm -f "$b"; return 0; }
		sed -i 's/^_wget_subscription_request() {$/zm__wget_subscription_request_raw() {/' "$f"
	fi
	grep -q '^zm__wget_subscription_request_raw() {$' "$f" || { cat "$b" > "$f"; rm -f "$b"; return 0; }
	cat >> "$f" << 'ZM_FK_SUBCK_EOF'
# zm-subck-begin 1
zm_subck_host() {
	local h="${1#*://}"
	h="${h%%/*}"; h="${h%%\?*}"; h="${h##*@}"
	printf '%s' "$h"
}
zm_subck_ok() { [ "$1" = /dev/null ] || [ -s "$1" ]; }
zm_subck_curl() {
	local zm_ua="$2" zm_id="$3" zm_os="$4" zm_md="$5" zm_kv="$6" zm_out="$7" zm_err="$8" zm_url="$9" zm_k="" zm_4="" zm_t=10
	[ "$1" = "--no-check-certificate" ] && zm_k=-k
	shift 9
	while [ "$#" -gt 0 ]; do
		case "$1" in
			-4) zm_4=-4 ;;
			-T) [ "$#" -gt 1 ] && { zm_t="$2"; shift; } ;;
			--no-check-certificate) zm_k=-k ;;
		esac
		shift
	done
	case "$zm_t" in ''|*[!0-9]*) zm_t=10 ;; esac
	curl -fsS -L --max-redirs 10 -b "" $zm_4 $zm_k --connect-timeout "$zm_t" --speed-time "$zm_t" --speed-limit 1 \
		-o "$zm_out" -A "$zm_ua" \
		-H "X-HWID: $zm_id" -H "X-Device-OS: $zm_os" -H "X-Device-Model: $zm_md" -H "X-Ver-OS: $zm_kv" \
		-H "Accept-Language: ru-RU,en,*" -H "X-Device-Locale: EN" \
		"$zm_url" 2>"$zm_err"
}
_wget_subscription_request() {
	local zm_h zm_rc zm_m=/tmp/netshift.zm-subck zm_tried=""
	zm_h="$(zm_subck_host "$9")"
	command -v curl > /dev/null 2>&1 || { zm__wget_subscription_request_raw "$@"; return; }
	if [ -n "$zm_h" ] && grep -qxF "$zm_h" "$zm_m" 2> /dev/null; then
		zm_tried=1
		zm_subck_curl "$@" && zm_subck_ok "$7" && return 0
	fi
	zm__wget_subscription_request_raw "$@"
	zm_rc=$?
	[ "$zm_rc" -eq 0 ] && zm_subck_ok "$7" && return 0
	[ -z "$zm_tried" ] || return "$zm_rc"
	if zm_subck_curl "$@" && zm_subck_ok "$7"; then
		[ -n "$zm_h" ] && ! grep -qxF "$zm_h" "$zm_m" 2> /dev/null && printf '%s\n' "$zm_h" >> "$zm_m"
		command -v log > /dev/null 2>&1 && log "Subscription server $zm_h needs cookies, downloaded with curl" "info"
		return 0
	fi
	[ "$7" = /dev/null ] || : > "$7"
	return "$zm_rc"
}
# zm-subck-end
ZM_FK_SUBCK_EOF
	if sh -n "$f" 2> /dev/null; then
		rm -f "$b"
		logger -t zapret-manager "$(_fk_name): подписки за проверкой cookie качаются через curl"
	else
		cat "$b" > "$f"; rm -f "$b"
	fi
	return 0
}

_fk_listsvia_patch() {
	local f=/usr/bin/netshift tmp
	[ -f "$f" ] || return 0
	grep -q '^# ZM_LISTS_FALLBACK 1$' "$f" && return 0
	[ "$(grep -c '^get_service_proxy_address() {$' "$f")" = 1 ] &&
		[ "$(grep -c '^            if curl -s -x "http://\$service_proxy_address" -m \$curl_timeout https://github.com > /dev/null; then$' "$f")" = 1 ] || return 0
	tmp="$f.zm-lists"
	awk '
		$0 == "get_service_proxy_address() {" {
			print "# ZM_LISTS_FALLBACK 1"
			print "# Zapret Manager: when the VPN does not answer, list_update downloads lists directly this time"
			print "# (ZM_LISTS_DIRECT) instead of leaving every list undownloaded until the next scheduled update."
			print "get_service_proxy_address() {"
			print "    [ \"$ZM_LISTS_DIRECT\" = 1 ] && return 0"
			print "    zm_get_service_proxy_address_raw \"$@\""
			print "}"
			print ""
			print "zm_get_service_proxy_address_raw() {"
			r++; next
		}
		$0 == "            if curl -s -x \"http://$service_proxy_address\" -m $curl_timeout https://github.com > /dev/null; then" { a = 1 }
		{ print }
		a && $0 == "            fi" {
			a = 0; c++
			print "            # ZM_LISTS_FALLBACK: the VPN does not answer, GitHub opens directly - lists go directly this time"
			print "            if [ \"$i\" -ge 3 ] && curl -s -m $curl_timeout https://github.com > /dev/null; then"
			print "                ZM_LISTS_DIRECT=1"
			print "                echolog \"GitHub is unavailable through the VPN, downloading lists directly this time\" \"warn\""
			print "                break"
			print "            fi"
		}
		END { exit (r == 1 && c == 1) ? 0 : 1 }' "$f" > "$tmp" || { rm -f "$tmp"; return 0; }
	if sh -n "$tmp" && chmod 0755 "$tmp"; then
		mv -f "$tmp" "$f"
	fi
	rm -f "$tmp"
	return 0
}

_fk_subvia_patch() {
	local f=/usr/bin/netshift tmp
	[ -f "$f" ] || return 0
	grep -q '^# ZM_SUBVIA 1$' "$f" && return 0
	[ "$(grep -c '^            if ! wait_for_subscription_connectivity "\$section" "\$url" "\$service_proxy_address" 6 5 5; then$' "$f")" = 1 ] || return 0
	tmp="$f.zm-subvia"
	awk '
		NR == 1 { print; print "# ZM_SUBVIA 1"; next }
		$0 == "            if ! wait_for_subscription_connectivity \"$section\" \"$url\" \"$service_proxy_address\" 6 5 5; then" {
			print "            if [ -n \"$service_proxy_address\" ] && ! wait_for_subscription_connectivity \"$section\" \"$url\" \"$service_proxy_address\" 2 3 5; then"
			print "                echolog \"Subscription server is unavailable through the VPN, updating the subscription directly this time\" \"warn\""
			print "                service_proxy_address=\"\""
			print "            fi"
			c++
		}
		{ print }
		END { exit c == 1 ? 0 : 1 }' "$f" > "$tmp" || { rm -f "$tmp"; return 0; }
	if sh -n "$tmp" && chmod 0755 "$tmp"; then
		mv -f "$tmp" "$f"
	fi
	rm -f "$tmp"
	return 0
}

_fk_reality_patch() {
	local f=/usr/bin/netshift tmp
	[ -f "$f" ] || return 0
	grep -q '^# ZM_REALITY 1$' "$f" && return 0
	grep -q '^sing_box_save_config() {$' "$f" || return 0
	[ "$(grep -c '^    sing_box_cm_save_config_to_file "\$config" "\$temp_file_path"$' "$f")" = 1 ] || return 0
	[ "$(grep -c '^    sing_box_config_check "\$temp_file_path"$' "$f")" = 1 ] || return 0
	tmp="$f.zm-reality"
	cat > "$tmp.blk" << 'ZM_FK_REALITY_EOF'
    local zm_rl=0 zm_rl_msg zm_rl_core=""
    if grep -q '"reality"' "$temp_file_path" 2> /dev/null && command -v ucode > /dev/null 2>&1 && [ -s /opt/zapret-manager-luci/netshift.uc ]; then
        [ "${NETSHIFT_REALITY_MLKEM_HINT_UNGATED:-0}" = "1" ] && zm_rl_core=1
        zm_rl_msg="$(ZM_RL_CORE="$zm_rl_core" ucode /opt/zapret-manager-luci/netshift.uc reality "$temp_file_path" "$temp_file_path.zm" 2> /dev/null)" && [ -s "$temp_file_path.zm" ] && zm_rl=1
        [ -n "$zm_rl_msg" ] && log "$zm_rl_msg"
        if [ "$zm_rl" = 1 ]; then
            cp "$temp_file_path" "$temp_file_path.zm0" 2> /dev/null && mv -f "$temp_file_path.zm" "$temp_file_path" || zm_rl=0
        fi
        rm -f "$temp_file_path.zm"
        [ "$zm_rl" = 1 ] || rm -f "$temp_file_path.zm0"
    fi
ZM_FK_REALITY_EOF
	cat > "$tmp.chk" << 'ZM_FK_REALITY_EOF'
    if [ "$zm_rl" = 1 ] && ! sing_box_oneshot -c "$temp_file_path" check > /dev/null 2>&1; then
        log "REALITY (Zapret Manager): sing-box did not accept the compatibility settings, the config is used without them" "warn"
        mv -f "$temp_file_path.zm0" "$temp_file_path"
        zm_rl=0
    fi
    rm -f "$temp_file_path.zm0"
    [ "$zm_rl" = 1 ] || sing_box_config_check "$temp_file_path"
ZM_FK_REALITY_EOF
	awk -v bf="$tmp.blk" -v cf="$tmp.chk" '
		NR == 1 { print; print "# ZM_REALITY 1"; next }
		/^sing_box_save_config\(\) \{$/ { f = 1 }
		f && /^}$/ { f = 0 }
		f && $0 == "    sing_box_cm_save_config_to_file \"$config\" \"$temp_file_path\"" { print; while ((getline l < bf) > 0) print l; a++; next }
		f && $0 == "    sing_box_config_check \"$temp_file_path\"" { while ((getline l < cf) > 0) print l; b++; next }
		{ print }
		END { exit a == 1 && b == 1 ? 0 : 1 }' "$f" > "$tmp" || { rm -f "$tmp" "$tmp.blk" "$tmp.chk"; return 0; }
	if sh -n "$tmp" && chmod 0755 "$tmp"; then
		mv -f "$tmp" "$f"
	fi
	rm -f "$tmp" "$tmp.blk" "$tmp.chk"
	return 0
}

FK_RS_DIR="/opt/zapret-manager-luci/fk-rs"
FK_RS_MAXF=2097152
FK_RS_MAXT=4194304
FK_RS_FREE=2048
_fk_rs_on() { [ "$(uci -q get netshift.settings.zm_rs_snap)" != 0 ]; }
_fk_rs_sbok() {
	local v
	v="$(_fk_sb_ver)"
	v="${v#v}"
	case "$v" in [0-9]*.[0-9]*) ;; *) return 1 ;; esac
	set -- $(printf '%s' "$v" | sed 's/^\([0-9]*\)\.\([0-9]*\).*/\1 \2/')
	[ "${1:-0}" -gt 1 ] || { [ "${1:-0}" -eq 1 ] && [ "${2:-0}" -ge 14 ]; }
}
_fk_rsinit_patch() {
	local f=/usr/bin/netshift tmp
	[ -f "$f" ] || return 0
	grep -q '^# ZM_RSINIT 1$' "$f" && return 0
	grep -q '^sing_box_save_config() {$' "$f" || return 0
	[ "$(grep -c '^    current_config_hash=\$(md5sum "\$sing_box_config_path" 2> /dev/null | awk '"'"'{print \$1}'"'"')$' "$f")" = 1 ] || return 0
	tmp="$f.zm-rsinit"
	cat > "$tmp.blk" << 'ZM_FK_RSINIT_EOF'
    if [ "$(uci -q get netshift.settings.zm_rs_snap)" != 0 ] && [ -n "$(ls /opt/zapret-manager-luci/fk-rs/*.url 2> /dev/null)" ] &&
        command -v ucode > /dev/null 2>&1 && command -v jq > /dev/null 2>&1 && [ -s /opt/zapret-manager-luci/netshift.uc ]; then
        local zm_rs_rc zm_rs_id
        zm_rs_id="$(ZM_SB_VER="${NETSHIFT_SING_BOX_VERSION:-}" ucode /opt/zapret-manager-luci/netshift.uc rs_initial "$temp_file_path" "$temp_file_path.zmrsm" 2> /dev/null)"
        zm_rs_rc=$?
        if { [ "$zm_rs_rc" = 0 ] || [ "$zm_rs_rc" = 4 ]; } && [ -s "$temp_file_path.zmrsm" ] &&
            jq --argjson zm "$(cat "$temp_file_path.zmrsm")" \
                'if (.route.rule_set | type) == "array" then .route.rule_set |= map(if type == "object" and .type == "remote" and (.tag | type) == "string" and .initial_path == null and ($zm[.tag] | type) == "string" then . + {initial_path: $zm[.tag]} else . end) else . end' \
                "$temp_file_path" > "$temp_file_path.zmrs" 2> /dev/null && [ -s "$temp_file_path.zmrs" ]; then
            if [ "$zm_rs_rc" = 4 ]; then
                if sing_box_oneshot -c "$temp_file_path.zmrs" check > /dev/null 2>&1; then
                    ucode /opt/zapret-manager-luci/netshift.uc rs_cap "$zm_rs_id" yes > /dev/null 2>&1
                else
                    ucode /opt/zapret-manager-luci/netshift.uc rs_cap "$zm_rs_id" no > /dev/null 2>&1
                    log "Rule-set snapshots (Zapret Manager): this sing-box does not accept initial_path, the config is used without it" "warn"
                    rm -f "$temp_file_path.zmrs"
                fi
            fi
            if [ -s "$temp_file_path.zmrs" ] && mv -f "$temp_file_path.zmrs" "$temp_file_path"; then
                log "Rule-set snapshots (Zapret Manager): saved copies of the lists are ready, sing-box starts without waiting for downloads" "info"
            fi
        fi
        rm -f "$temp_file_path.zmrs" "$temp_file_path.zmrsm"
    fi
ZM_FK_RSINIT_EOF
	awk -v bf="$tmp.blk" '
		NR == 1 { print; print "# ZM_RSINIT 1"; next }
		/^sing_box_save_config\(\) \{$/ { f = 1 }
		f && /^}$/ { f = 0 }
		f && $0 == "    current_config_hash=$(md5sum \"$sing_box_config_path\" 2> /dev/null | awk '"'"'{print $1}'"'"')" { while ((getline l < bf) > 0) print l; a++ }
		{ print }
		END { exit a == 1 ? 0 : 1 }' "$f" > "$tmp" || { rm -f "$tmp" "$tmp.blk"; return 0; }
	if sh -n "$tmp" && chmod 0755 "$tmp"; then
		mv -f "$tmp" "$f"
	fi
	rm -f "$tmp" "$tmp.blk"
	return 0
}
_fk_rs_px() { command curl -fsSL --connect-timeout 10 --max-time 40 --max-filesize "$FK_RS_MAXF" -x "http://$3" -o "$2" "$1" </dev/null >/dev/null 2>&1 && [ -s "$2" ]; }
_fk_rs_get() {
	local url="$1" out="$2" via="$3" px="$4"
	rm -f "$out"
	[ "$via" = p ] && [ -n "$px" ] && _fk_rs_px "$url" "$out" "$px" && return 0
	rm -f "$out"
	curl -fsSL --connect-timeout 10 --max-time 40 --max-filesize "$FK_RS_MAXF" -o "$out" "$url" </dev/null >/dev/null 2>&1 && [ -s "$out" ] && return 0
	rm -f "$out"
	[ "$via" != p ] && [ -n "$px" ] && _fk_rs_px "$url" "$out" "$px" && return 0
	rm -f "$out"
	return 1
}
_fk_rs_valid() {
	local f="$1" fmt="$2" sz
	sz="$(wc -c < "$f" 2>/dev/null | tr -d ' ')"
	[ "${sz:-0}" -gt 0 ] && [ "$sz" -le "$FK_RS_MAXF" ] || return 1
	if [ "$fmt" = binary ]; then
		[ "$(head -c 3 "$f")" = SRS ]
	else
		[ "$(jsonfilter -i "$f" -t '@.rules' 2>/dev/null)" = array ]
	fi
}
_fk_rs_used() { du -sk "$FK_RS_DIR" 2>/dev/null | awk '{ print $1 + 0 }'; }
_fk_rs_refresh() {
	local lk="$JOBS_DIR/fk-rs.lock" plan="$JOBS_DIR/fk-rs.plan" tab kind fmt via url px="" id ext f m tmp chk keep=" " sz used free new=0 upd=0 bad=0 nr=0 got=0 x t0
	_fk_rs_on && _fk_installed && ! _fk_foreign && _fk_rs_sbok || return 0
	command -v jsonfilter >/dev/null 2>&1 && command -v md5sum >/dev/null 2>&1 || return 0
	mkdir -p "$JOBS_DIR"
	if ! mkdir "$lk" 2>/dev/null; then
		[ -n "$(find "$lk" -maxdepth 0 -mmin +60 2>/dev/null)" ] && rmdir "$lk" 2>/dev/null
		return 0
	fi
	t0="$(date +%s)"
	if ! _fk_uc rs_plan > "$plan" 2>/dev/null; then rm -f "$plan"; rmdir "$lk"; return 1; fi
	tab="$(printf '\t')"
	px="$(awk -F'\t' '$1 == "P" { print $2; exit }' "$plan")"
	case "$px" in 127.0.0.1:[0-9]*|"[::1]":[0-9]*) ;; *) px="" ;; esac
	mkdir -p "$FK_RS_DIR"
	while IFS="$tab" read -r kind fmt via url; do
		[ "$kind" = R ] || continue
		case "$fmt" in binary) ext=srs ;; source) ext=json ;; *) continue ;; esac
		case "$url" in http://*|https://*) ;; *) continue ;; esac
		id="$(printf '%s\n%s' "$url" "$fmt" | md5sum | cut -c1-32)"
		case "$id" in *[!0-9a-f]*|'') continue ;; esac
		keep="$keep$id "; nr=$((nr + 1))
		f="$FK_RS_DIR/$id.$ext"; m="$FK_RS_DIR/$id.url"; chk="$JOBS_DIR/fk-rs.chk.$id"
		[ -s "$f" ] && [ -s "$m" ] && [ -n "$(find "$chk" "$f" -mmin -1200 2>/dev/null)" ] && continue
		[ "$got" = 0 ] && [ "$bad" -ge 3 ] && continue
		[ $(( $(date +%s) - t0 )) -lt 900 ] || continue
		tmp="$JOBS_DIR/fk-rs.$id.dl"
		if ! _fk_rs_get "$url" "$tmp" "$via" "$px" || ! _fk_rs_valid "$tmp" "$fmt"; then
			rm -f "$tmp"; bad=$((bad + 1)); continue
		fi
		got=$((got + 1))
		: > "$chk"
		if [ -s "$f" ] && cmp -s "$tmp" "$f"; then
			rm -f "$tmp"
		else
			sz=$(( ($(wc -c < "$tmp") + 1023) / 1024 ))
			used="$(_fk_rs_used)"; [ -s "$f" ] && used=$((used - ($(wc -c < "$f") + 1023) / 1024))
			free="$(df -kP "$FK_RS_DIR" 2>/dev/null | awk 'NR == 2 { print $4 + 0 }')"
			if [ $(( (${used:-0} + sz) * 1024 )) -gt "$FK_RS_MAXT" ] || [ $(( ${free:-0} - sz )) -lt "$FK_RS_FREE" ]; then
				rm -f "$tmp"; bad=$((bad + 1)); continue
			fi
			if cp -f "$tmp" "$f.zmn" 2>/dev/null && mv -f "$f.zmn" "$f"; then
				if [ -s "$m" ]; then upd=$((upd + 1)); else new=$((new + 1)); fi
			else
				rm -f "$f.zmn" "$tmp"; bad=$((bad + 1)); continue
			fi
			rm -f "$tmp"
		fi
		if [ "$(cat "$m" 2>/dev/null)" != "$(printf '%s\n%s' "$url" "$fmt")" ]; then
			printf '%s\n%s\n' "$url" "$fmt" > "$m.zmn" && mv -f "$m.zmn" "$m" || rm -f "$m.zmn" "$f"
		fi
	done < "$plan"
	rm -f "$plan"
	[ "$nr" -gt 0 ] && for x in $(find "$FK_RS_DIR" -maxdepth 1 -name '*.url' -mtime +7 2>/dev/null); do
		id="${x##*/}"; id="${id%.url}"
		case "$keep" in *" $id "*) ;; *) rm -f "$FK_RS_DIR/$id.url" "$FK_RS_DIR/$id.srs" "$FK_RS_DIR/$id.json" "$JOBS_DIR/fk-rs.chk.$id" ;; esac
	done
	for x in "$FK_RS_DIR"/*.srs "$FK_RS_DIR"/*.json; do
		[ -f "$x" ] || continue
		id="${x##*/}"; id="${id%.*}"
		[ -s "$FK_RS_DIR/$id.url" ] || rm -f "$x"
	done
	rmdir "$lk" 2>/dev/null
	if [ $((new + upd)) -gt 0 ]; then
		x=""; [ "$bad" -gt 0 ] && x=", не скачалось $bad"
		logger -t zapret-manager "Forkozz: копии списков на роутере — новых $new, обновлено $upd$x. После перезагрузки sing-box запустится, даже если GitHub недоступен"
	fi
	return 0
}
_fk_rs_watch() {
	local st="$JOBS_DIR/fk-rs.last" c
	_fk_rs_on && _fk_installed && ! _fk_foreign && _fk_up || return 0
	_job_running forkop && return 0
	c="$(uci -q get netshift.settings.config_path)"; c="${c:-/etc/sing-box/config.json}"
	if [ -f "$st" ] && [ ! "$c" -nt "$st" ] && [ -n "$(find "$st" -mmin -360 2>/dev/null)" ]; then return 0; fi
	mkdir -p "$JOBS_DIR"; : > "$st"
	( _fk_rs_refresh >/dev/null 2>&1 & ) >/dev/null 2>&1
	return 0
}
fk_rs_set() {
	_fk_installed || { echo '{"error":"Forkozz не установлен"}'; return 1; }
	case "$1" in
		on)
			uci -q delete netshift.settings.zm_rs_snap; uci -q commit netshift
			rm -f "$JOBS_DIR/fk-rs.last"
			_fk_up && ( _fk_rs_refresh >/dev/null 2>&1 & ) >/dev/null 2>&1 ;;
		off)
			uci -q set netshift.settings.zm_rs_snap=0; uci -q commit netshift
			rm -rf "$FK_RS_DIR"; rm -f "$JOBS_DIR"/fk-rs.chk.* "$JOBS_DIR/fk-rs.last" ;;
		*) echo '{"error":"неизвестная команда"}'; return 1 ;;
	esac
	printf '{"ok":true,"on":%s}\n' "$([ "$1" = on ] && echo true || echo false)"
}

FK_FIP_DEF="198.18.0.0/15"
_fk_fip_want() {
	local v
	v="$(uci -q get netshift.settings.zm_fakeip4)"
	case "$v" in 198.1[89].*/1[5-9]|198.1[89].*/20|198.2[0-3].*/1[5-9]|198.2[0-3].*/20) printf '%s' "$v" ;; *) printf '%s' "$FK_FIP_DEF" ;; esac
}
_fk_fip_live() {
	nft list chain inet "$FK_NFT" mangle 2>/dev/null | sed -n 's/.*ip daddr \(198\.\(1[89]\|2[0-3]\)\.[0-9.]*\/[0-9]*\) meta mark set.*/\1/p' | head -n1
}
_fk_fakeip_patch() {
	local f=/usr/lib/netshift/constants.sh want cur
	[ -f "$f" ] || return 0
	cur="$(_fk_fip_file)"
	[ -n "$cur" ] || return 0
	want="$(_fk_fip_want)"
	[ "$cur" = "$want" ] && return 0
	sed -i "s#^SB_FAKEIP_INET4_RANGE=\"[0-9./]*\"\$#SB_FAKEIP_INET4_RANGE=\"$want\"#" "$f"
	logger -t zapret-manager "$(_fk_name): пул Fake IP $want"
	return 0
}
_fk_fip_in() {
	local p
	p="$(_fk_fip_live)"; [ -n "$p" ] || p="$(_fk_fip_file)"; [ -n "$p" ] || p="$FK_FIP_DEF"
	awk -v a="$1" -v p="$p" 'function n(x,   o) { if (split(x, o, ".") != 4) return -1; return ((o[1] * 256 + o[2]) * 256 + o[3]) * 256 + o[4] }
		BEGIN { split(p, q, "/"); b = n(q[1]); v = n(a); if (b < 0 || v < 0 || q[2] == "" || q[2] < 1 || q[2] > 32) exit 1; z = 1; for (i = q[2]; i < 32; i++) z *= 2; exit !(v >= b && v < b + z) }'
}
_fk_fip_file() { sed -n 's/^SB_FAKEIP_INET4_RANGE="\([0-9./]*\)"$/\1/p' /usr/lib/netshift/constants.sh 2>/dev/null | head -n1; }
_fk_fip_stale() {
	local l f
	l="$(_fk_fip_live)"; f="$(_fk_fip_file)"
	[ -n "$l" ] && [ -n "$f" ] && [ "$l" != "$f" ]
}
_fk_ru_watch() {
	local now old z ip e n="" ch="" sv
	[ "$(uci -q get netshift.settings.zm_ru)" = isp ] || return 0
	now="$(_dn_isp | tr ',' '\n' | grep -E '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$' | head -n 4 | tr '\n' ' ' | sed 's/ $//')"
	[ -n "$now" ] || return 0
	old="$(uci -q get netshift.settings.zm_ru_ips)"
	[ "$now" = "$old" ] && return 0
	for e in $(uci -q get netshift.settings.dns_forward); do
		case "$e" in /ru/*|/su/*|/xn--p1ai/*) ;; *) n="${n:+$n }$e" ;; esac
	done
	for z in ru su xn--p1ai; do for ip in $now; do n="${n:+$n }/$z/$ip"; done; done
	uci -q delete netshift.settings.dns_forward
	for e in $n; do uci -q add_list "netshift.settings.dns_forward=$e"; done
	uci -q delete netshift.settings.zm_ru_ips
	for ip in $now; do uci -q add_list "netshift.settings.zm_ru_ips=$ip"; done
	uci -q commit netshift
	if [ "$(uci -q get 'dhcp.@dnsmasq[0].netshift_configured')" = 1 ] && [ "$(uci -q get netshift.settings.dont_touch_dhcp)" != 1 ]; then
		sv=""
		for e in $(uci -q get 'dhcp.@dnsmasq[0].server'); do
			case "$e" in /ru/*|/su/*|/xn--p1ai/*) ch=1 ;; *) sv="${sv:+$sv }$e" ;; esac
		done
		for z in ru su xn--p1ai; do for ip in $now; do sv="${sv:+$sv }/$z/$ip"; done; done
		uci -q delete 'dhcp.@dnsmasq[0].server'
		for e in $sv; do uci -q add_list "dhcp.@dnsmasq[0].server=$e"; done
		uci -q commit dhcp
		/etc/init.d/dnsmasq restart >/dev/null 2>&1
	fi
	logger -t zapret-manager "$(_fk_name): DNS провайдера для российских сайтов сменился — теперь $(printf '%s' "$now" | sed 's/ /, /g')"
	return 0
}
_fk_desync_patch() {
	local f=/usr/bin/netshift k=/usr/lib/netshift/kill_switch.sh tmp m="" new=""
	[ -f "$f" ] || return 0
	tmp="$f.zm-desync"
	cat > "$tmp.fn" << 'ZM_FK_DESYNC_EOF'
# ZM_DESYNC 1
zm_desync_mask() {
    local zm_m=0 zm_v zm_f
    for zm_f in /etc/config/zapret /etc/config/zapret2; do
        for zm_v in $(sed -n "s/^[[:space:]]*option[[:space:]][[:space:]]*DESYNC_MARK[[:space:]][[:space:]]*'\{0,1\}\(0x[0-9a-fA-F]\{1,8\}\)'\{0,1\}[[:space:]]*$/\1/p" "$zm_f" 2> /dev/null); do
            zm_m=$((zm_m | zm_v))
        done
    done
    zm_m=$((zm_m & 0xffcfffff))
    [ "$zm_m" -gt 0 ] 2> /dev/null || zm_m=$((0x40000000))
    printf '0x%08x\n' "$zm_m"
}
ZM_FK_DESYNC_EOF
	if ! grep -q '^# ZM_DESYNC 1$' "$f" &&
		[ "$(grep -c '^    nft add rule inet "\$NFT_TABLE_NAME" mangle_output meta mark "\$NFT_OUTBOUND_MARK" counter return$' "$f")" = 1 ]; then
		awk -v bf="$tmp.fn" '
			NR == 1 { print; while ((getline l < bf) > 0) print l; next }
			$0 == "    nft add rule inet \"$NFT_TABLE_NAME\" mangle_output meta mark \"$NFT_OUTBOUND_MARK\" counter return" {
				print
				print "    nft add rule inet \"$NFT_TABLE_NAME\" mangle_output meta mark \\& \"$(zm_desync_mask)\" != 0 counter return"
				c++
				next
			}
			{ print }
			END { exit c == 1 ? 0 : 1 }' "$f" > "$tmp" &&
		sh -n "$tmp" && chmod 0755 "$tmp" && mv -f "$tmp" "$f" && new=1
		rm -f "$tmp"
	fi
	if [ -f "$k" ] && ! grep -q '^# ZM_DESYNC 1$' "$k" &&
		[ "$(grep -c '^        echo "        meta mark & \$NFT_OUTBOUND_MARK == \$NFT_OUTBOUND_MARK accept"$' "$k")" = 1 ]; then
		awk '
			NR == 1 { print; print "# ZM_DESYNC 1"; next }
			$0 == "        echo \"        meta mark & $NFT_OUTBOUND_MARK == $NFT_OUTBOUND_MARK accept\"" {
				print
				print "        echo \"        meta mark & $(zm_desync_mask 2> /dev/null || echo 0x40000000) != 0 accept\""
				c++
				next
			}
			{ print }
			END { exit c == 1 ? 0 : 1 }' "$k" > "$k.zm-desync" &&
		sh -n "$k.zm-desync" && cat "$k.zm-desync" > "$k" && new=1
		rm -f "$k.zm-desync"
	fi
	if [ -n "$new" ] && command -v nft >/dev/null 2>&1; then
		m="$(sh -c '. "$1"; zm_desync_mask' _ "$tmp.fn" 2>/dev/null)"
		case "$m" in 0x[0-9a-f]*) ;; *) m=0x40000000 ;; esac
		nft list chain inet NetShiftTable mangle_output 2>/dev/null | grep -q "meta mark & $m != 0x00000000" ||
			nft insert rule inet NetShiftTable mangle_output meta mark \& "$m" != 0 counter return 2>/dev/null
		nft list chain inet NetShiftGuard output_guard 2>/dev/null | grep -q "meta mark & $m != 0x00000000" ||
			nft insert rule inet NetShiftGuard output_guard meta mark \& "$m" != 0 accept 2>/dev/null
	fi
	rm -f "$tmp.fn"
	return 0
}

_fk_serial_patch() {
	local f=/usr/bin/netshift tmp
	[ -f "$f" ] || return 0
	grep -q '^# ZM_SERIAL 1$' "$f" && return 0
	[ "$(grep -c '^case "\$1" in$' "$f")" = 1 ] && [ "$(grep -c '^reload_sing_box_config_in_place() {$' "$f")" = 1 ] &&
		[ "$(grep -c '^    /etc/init.d/sing-box start$' "$f")" = 1 ] || return 0
	tmp="$f.zm-serial"
	cat > "$tmp.blk" << 'ZM_FK_SERIAL_EOF'
# ZM_SERIAL 1
ZM_SERIAL_DIR="/var/run/netshift-zm-serial"

zm_serial_me() {
    local zm_rest
    read -r ZM_SERIAL_ME zm_rest < /proc/self/stat
}

zm_serial_busy() {
    local zm_owner
    [ -d "$ZM_SERIAL_DIR" ] || return 1
    zm_owner="$(cat "$ZM_SERIAL_DIR/pid" 2> /dev/null)"
    case "$zm_owner" in
    '' | *[!0-9]*) return 0 ;;
    esac
    zm_serial_me
    [ "$zm_owner" != "$ZM_SERIAL_ME" ] && kill -0 "$zm_owner" 2> /dev/null
}

zm_serial_takeover() {
    local zm_seen="$1" zm_guard="$ZM_SERIAL_DIR.takeover" zm_g
    if ! mkdir "$zm_guard" 2> /dev/null; then
        zm_g="$(cat "$zm_guard/pid" 2> /dev/null)"
        case "$zm_g" in
        '' | *[!0-9]*) ;;
        *) kill -0 "$zm_g" 2> /dev/null || rm -rf "$zm_guard" ;;
        esac
        return 0
    fi
    echo "$ZM_SERIAL_ME" > "$zm_guard/pid"
    [ "$(cat "$ZM_SERIAL_DIR/pid" 2> /dev/null)" = "$zm_seen" ] && rm -rf "$ZM_SERIAL_DIR"
    rm -rf "$zm_guard"
    return 0
}

zm_serial_lock() {
    local zm_owner zm_waited=0 zm_empty=0 zm_nodir=0
    [ "$ZM_SERIAL_OWNED" = 1 ] && return 0
    zm_serial_me
    while :; do
        mkdir "$ZM_SERIAL_DIR" 2> /dev/null && break
        if [ ! -d "$ZM_SERIAL_DIR" ]; then
            zm_nodir=$((zm_nodir + 1))
            if [ "$zm_nodir" -ge 5 ]; then
                log "Cannot create the NetShift operation lock $ZM_SERIAL_DIR, continuing without it" "warn"
                return 0
            fi
            mkdir -p "${ZM_SERIAL_DIR%/*}" 2> /dev/null
            continue
        fi
        zm_nodir=0
        zm_owner="$(cat "$ZM_SERIAL_DIR/pid" 2> /dev/null)"
        case "$zm_owner" in
        '' | *[!0-9]*)
            zm_empty=$((zm_empty + 1))
            [ "$zm_empty" -ge 10 ] && { zm_serial_takeover "$zm_owner"; zm_empty=0; }
            ;;
        *)
            zm_empty=0
            if ! kill -0 "$zm_owner" 2> /dev/null; then
                zm_serial_takeover "$zm_owner"
            elif [ "$zm_waited" -eq 0 ]; then
                log "Another NetShift start, stop or subscription apply is running (pid $zm_owner), waiting for it to finish" "info"
            fi
            ;;
        esac
        if [ "$zm_waited" -ge 300 ]; then
            log "The NetShift operation lock is still held after 300s, continuing without it" "warn"
            return 0
        fi
        sleep 1
        zm_waited=$((zm_waited + 1))
    done
    echo "$ZM_SERIAL_ME" > "$ZM_SERIAL_DIR/pid"
    ZM_SERIAL_OWNED=1
    trap 'zm_serial_unlock' EXIT
    return 0
}

zm_serial_unlock() {
    [ "$ZM_SERIAL_OWNED" = 1 ] || return 0
    ZM_SERIAL_OWNED=""
    zm_serial_me
    [ "$(cat "$ZM_SERIAL_DIR/pid" 2> /dev/null)" = "$ZM_SERIAL_ME" ] && rm -rf "$ZM_SERIAL_DIR"
    return 0
}

zm_rulesets_ensure() {
    local zm_conf="$1" zm_path
    [ -n "$zm_conf" ] || config_get zm_conf "settings" "config_path"
    [ -n "$zm_conf" ] && [ -s "$zm_conf" ] || return 0
    for zm_path in $(jq -r '.route.rule_set[]? | select(.type == "local") | select((.format // "") == "source" or ((.path // "") | endswith(".json"))) | .path // empty' "$zm_conf" 2> /dev/null); do
        [ -s "$zm_path" ] && continue
        mkdir -p "${zm_path%/*}" 2> /dev/null
        if printf '%s\n' '{"version":3,"rules":[]}' > "$zm_path.zm-tmp" 2> /dev/null && mv -f "$zm_path.zm-tmp" "$zm_path"; then
            log "Rule set $zm_path was missing before sing-box read its config; created it empty so sing-box does not abort, the next lists update fills it" "warn"
        else
            rm -f "$zm_path.zm-tmp"
        fi
    done
    return 0
}

reload_sing_box_config_in_place() {
    local zm_rc zm_held="$ZM_SERIAL_OWNED"
    zm_serial_lock
    zm_reload_sing_box_config_in_place_unlocked "$@"
    zm_rc=$?
    [ "$zm_held" = 1 ] || zm_serial_unlock
    return "$zm_rc"
}

case "$1" in
start | stop | reload | restart) zm_serial_lock ;;
esac
# ZM_SERIAL_END

ZM_FK_SERIAL_EOF
	awk -v bf="$tmp.blk" '
		BEGIN { while ((getline l < bf) > 0) blk = blk l "\n" }
		/^monitor_sing_box\(\) \{$/ { m = 1 }
		m && $0 == "}" { m = 0 }
		$0 == "case \"$1\" in" { printf "%s", blk; d++ }
		$0 == "reload_sing_box_config_in_place() {" { print "zm_reload_sing_box_config_in_place_unlocked() {"; r++; next }
		$0 == "    if ! kill -HUP \"$sing_box_pid\" 2>/dev/null; then" { print "    zm_rulesets_ensure \"$config_path\""; h++ }
		$0 == "    /etc/init.d/sing-box start" { print "    zm_rulesets_ensure"; s++ }
		m && !mb && $0 == "        config_load \"$NETSHIFT_CONFIG\"" {
			print "        # ZM_SERIAL: sing-box is down because another NetShift operation is restarting it, not a crash"
			print "        zm_serial_busy && continue"
			print ""
			mb++
		}
		m && ml == 1 {
			ml = 2
			if ($0 != "        stop_main") bad = 1
			print "        # ZM_SERIAL: wait for any other NetShift operation. If sing-box is back meanwhile, no restart:"
			print "        # only point dnsmasq at it again (it was restored above, idempotent when already done)"
			print "        zm_serial_lock"
			print "        if sing_box_process_exists; then"
			print "            config_get_bool dont_touch_dhcp \"settings\" \"dont_touch_dhcp\" 0"
			print "            [ \"$dont_touch_dhcp\" -eq 0 ] && dnsmasq_configure force"
			print "            zm_serial_unlock"
			print "            log \"sing-box is running again after another NetShift operation, recovery restart is not needed\" \"info\""
			print "            crash_count=0"
			print "            continue"
			print "        fi"
		}
		m && $0 == "        log \"Attempting sing-box recovery restart\" \"warn\"" { ml++ }
		m && mu == 1 {
			mu = 2
			if ($0 != "        fi") bad = 1
			print
			print "        zm_serial_unlock"
			next
		}
		m && $0 == "            log \"Recovery restart failed, will retry\" \"error\"" { mu++ }
		{ print }
		END { exit (bad || d != 1 || r != 1 || h != 1 || s != 1 || mb != 1 || ml != 2 || mu != 2) ? 1 : 0 }' "$f" > "$tmp" ||
		{ rm -f "$tmp" "$tmp.blk"; return 0; }
	if sh -n "$tmp" && chmod 0755 "$tmp"; then
		mv -f "$tmp" "$f"
	fi
	rm -f "$tmp" "$tmp.blk"
	return 0
}

_fk_mlkem_patch() {
	local f=/usr/lib/netshift/sing_box_config_facade.sh tmp
	[ -f "$f" ] || return 0
	grep -q '^        # ZM_REALITY_MLKEM 1$' "$f" && return 0
	grep -q '^_add_outbound_security() {$' "$f" && grep -q '^        local reality_mlkem=""$' "$f" || return 0
	grep -q '^is_sing_box_extended_at_least() {' /usr/lib/netshift/helpers.sh 2>/dev/null || return 0
	grep -q '^SB_EXTENDED_REALITY_MLKEM_MIN=' /usr/lib/netshift/constants.sh 2>/dev/null || return 0
	[ "$(awk '/^_add_outbound_security\(\) \{$/ { f = 1 } f && /^}$/ { f = 0 } f && $0 == "        config=$(" { n++ } END { print n + 0 }' "$f")" = 1 ] || return 0
	tmp="$f.zm-mlkem"
	cat > "$tmp.blk" << 'ZM_FK_MLKEM_EOF'
        # ZM_REALITY_MLKEM 1
        if [ "$security" = "reality" ] && [ -z "$reality_mlkem" ]; then
            case "$(url_get_query_param "$url" "support-x25519mlkem768")" in
            true | 1)
                case "$outbound_tag" in
                *-fb[0-9]*-out)
                    fingerprint="chrome"
                    reality_mlkem="true"
                    ;;
                *)
                    if is_sing_box_extended_at_least "$SB_EXTENDED_REALITY_MLKEM_MIN"; then
                        [ "$fingerprint" = "chrome" ] || log "Link for '$outbound_tag' has support-x25519mlkem768: using fingerprint chrome instead of '${fingerprint:-none}', only it sends the X25519MLKEM768 key share" "info"
                        fingerprint="chrome"
                        reality_mlkem="true"
                    else
                        log "Link for '$outbound_tag' has support-x25519mlkem768: the X25519MLKEM768 key share requires sing-box-extended $SB_EXTENDED_REALITY_MLKEM_MIN or newer, the server will reject this connection" "warn"
                    fi
                    ;;
                esac
                ;;
            esac
        fi
        # ZM_REALITY_MLKEM_END

ZM_FK_MLKEM_EOF
	awk -v bf="$tmp.blk" '
		/^_add_outbound_security\(\) \{$/ { f = 1 }
		f && /^}$/ { f = 0 }
		/^        # ZM_REALITY_MLKEM / { skip = 1 }
		skip { if ($0 == "        # ZM_REALITY_MLKEM_END") { skip = 0; drop = 1 } next }
		drop { drop = 0; if ($0 == "") next }
		f && !done && $0 == "        config=$(" { while ((getline l < bf) > 0) print l; done = 1 }
		{ print }
		END { exit done ? 0 : 1 }' "$f" > "$tmp" || { rm -f "$tmp" "$tmp.blk"; return 0; }
	if [ "$(grep -c -- '^        --argjson reality_mlkem "$reality_mlkem" \\$' "$tmp")" = 1 ] &&
	   [ "$(grep -c '^                      then (if \$reality_mlkem$' "$tmp")" = 1 ]; then
		awk '
			$0 == "        --argjson reality_mlkem \"$reality_mlkem\" \\" {
				print
				print "        --argjson zm_mlkem \"$(is_sing_box_extended_at_least \"$SB_EXTENDED_REALITY_MLKEM_MIN\" && echo true || echo false)\" \\"
				next
			}
			$0 == "                      then (if $reality_mlkem" {
				print "                      # ZM_REALITY_MLKEM_SUB: ключ и у узлов, чья ссылка его просила (support-x25519mlkem768)"
				print "                      then (if ($reality_mlkem or ($zm_mlkem and ((.tls.reality.support_x25519mlkem768 // false) == true)))"
				next
			}
			{ print }' "$tmp" > "$tmp.2" && mv -f "$tmp.2" "$tmp"
	fi
	sh -n "$tmp" && cat "$tmp" > "$f"
	rm -f "$tmp" "$tmp.2" "$tmp.blk"
	return 0
}

_fk_sub_cache_files() {
	local sec u h d=/etc/netshift/subscriptions
	for sec in $(uci -q show netshift 2>/dev/null | sed -n "s/^netshift\.\([A-Za-z0-9_]*\)=section$/\1/p"); do
		[ "$(uci -q get "netshift.$sec.proxy_config_type")" = subscription ] || continue
		[ -s "$d/$sec.json" ] && echo "$d/$sec.json"
		uci -q get "netshift.$sec.subscription_url" | tr ' ' '\n' | while IFS= read -r u; do
			[ -n "$u" ] || continue
			h="$(printf '%s' "${u%%#*}" | md5sum | awk '{print $1}')"
			[ -s "$d/$sec.$h.json" ] && echo "$d/$sec.$h.json"
		done
	done
	return 0
}

_fk_mlkem_why() {
	local f
	grep -Ei "security=reality" /etc/config/netshift 2>/dev/null | grep -Eqi '[?&]support-x25519mlkem768=(true|1)([&#'"'"' ]|$)' && { echo "среди серверов есть REALITY для Xray 26.9.8+ (ключ X25519MLKEM768)"; return 0; }
	[ "$1" = config ] && return 1
	for f in $(_fk_sub_cache_files); do
		[ -s "$f" ] || continue
		grep -Eq '"support_x25519mlkem768"[[:space:]]*:[[:space:]]*true' "$f" && { echo "в подписке есть серверы REALITY для Xray 26.9.8+ (ключ X25519MLKEM768)"; return 0; }
	done
	return 1
}
_fk_mlkem_core_ok() {
	local v
	v="$(sing-box version 2>/dev/null | head -n1 | awk '{ for (i = 1; i < NF; i++) if ($i == "version") { print $(i + 1); exit } print $NF }')"
	case "$v" in *-extended-*) ;; *) return 1 ;; esac
	v="${v##*-extended-}"; v="${v%%-*}"
	case "$v" in ''|*[!0-9.]*) return 1 ;; esac
	! _st_ver_lt "$v" 2.7.2
}


_fk_log_mark() {
	FK_MARKN=$((${FK_MARKN:-0} + 1))
	FK_LOGMARK="zm-lists-$$-$(date +%s)-$FK_MARKN"
	logger -t netshift "[info] $FK_LOGMARK" 2>/dev/null
	FK_LOGSEEN=0
}

_fk_lists_progress() {
	local all tot
	[ -n "$FK_LOGMARK" ] || return 0
	all="$(logread 2>/dev/null | awk -v m="$FK_LOGMARK" 'f && /netshift/ { print } index($0, m) { f = 1 }')"
	tot="$(printf '%s\n' "$all" | grep -c .)"
	[ "$tot" -gt "${FK_LOGSEEN:-0}" ] 2>/dev/null || return 0
	printf '%s\n' "$all" | awk -v skip="${FK_LOGSEEN:-0}" '
		function base(u) { sub(/[?#].*$/, "", u); sub(/^.*\//, "", u); return u }
		NR <= skip { next }
		{ sub(/^.*netshift[^:]*: /, ""); sub(/^\[[a-z]+\] /, "") }
		/Starting lists update/ { print "   → Начинаем загрузку списков"; next }
		/DNS check passed/ { print "   ✓ DNS отвечает"; next }
		/DNS check failed/ { print "   ✗ DNS не ответил — списки не скачаны"; next }
		/DNS is unavailable/ { print "   · DNS пока не отвечает — пробуем ещё раз"; next }
		/GitHub connection check passed \(via proxy\)/ { print "   ✓ GitHub доступен через VPN — списки качаем через него"; next }
		/GitHub is unavailable through the VPN/ { print "   ! Через VPN GitHub не ответил — в этот раз списки качаем напрямую"; next }
		/GitHub connection check passed/ { print "   ✓ GitHub доступен"; next }
		/GitHub connection check failed/ { print "   ✗ GitHub недоступен — списки не скачаны"; next }
		/GitHub is unavailable/ { print "   · GitHub пока не отвечает — пробуем ещё раз"; next }
		/Downloading and processing lists/ { print "   → Скачиваем и разбираем списки"; next }
		/Importing community subnet lists for/ { print "   → Адреса встроенных сервисов — заносим в файрвол"; next }
		/Importing domains from URL: / { u = $0; sub(/^.*URL: /, "", u); print "   → Домены из списка " base(u); next }
		/Importing subnets from URL: / { u = $0; sub(/^.*URL: /, "", u); print "   → Адреса из списка " base(u) " — заносим в файрвол"; next }
		/^Downloading via GitHub mirror / { m = $0; sub(/^Downloading via GitHub mirror /, "", m); sub(/:.*$/, "", m); print "   · GitHub не отдал файл напрямую — качаем через зеркало " m; next }
		/^Downloaded via GitHub mirror / { m = $0; sub(/^Downloaded via GitHub mirror /, "", m); print "   ✓ Скачано через зеркало " m; next }
		/^Download .* list failed/ { u = $2; print "   ✗ Не скачался список " base(u); next }
		/Failed to decompile binary rule set/ { print "   ✗ Набор правил не раскрылся — его адреса пропущены"; next }
		/Lists update completed successfully/ { print "   ✓ Все списки загружены"; next }
		/Lists update failed/ { print "   ✗ Часть списков не загрузилась — работают остальные"; next }'
	FK_LOGSEEN="$tot"
	return 0
}

_fk_lists_wait() {
	local p i=0 max="${1:-240}"
	p="${2:-$(cat /var/run/netshift_list_update.pid 2>/dev/null)}"
	case "$p" in ''|*[!0-9]*) return 0 ;; esac
	kill -0 "$p" 2>/dev/null || { _fk_lists_progress; return 0; }
	_fk_say "Forkozz скачивает списки и заносит адреса в файрвол"
	while [ "$i" -lt "$max" ]; do
		_fk_lists_progress
		kill -0 "$p" 2>/dev/null || { _fk_lists_progress; return 0; }
		sleep 2
		i=$((i + 2))
	done
	_fk_lists_progress
	return 1
}

_fk_lists_report() {
	local c=/etc/sing-box/config.json n=0 i=0 t ty u pth sz lines tbl sets set cnt shown=0
	if [ -s "$c" ]; then
		n="$(jsonfilter -i "$c" -e '@.route.rule_set[*].tag' 2>/dev/null | wc -l)"
		_fk_say "Наборов правил в sing-box: $n"
		while [ "$i" -lt "$n" ] && [ "$i" -lt 80 ]; do
			t="$(jsonfilter -i "$c" -e "@.route.rule_set[$i].tag" 2>/dev/null)"
			ty="$(jsonfilter -i "$c" -e "@.route.rule_set[$i].type" 2>/dev/null)"
			if [ "$ty" = remote ]; then
				u="$(jsonfilter -i "$c" -e "@.route.rule_set[$i].url" 2>/dev/null)"
				echo "   · $t — с ${u#https://}"
			elif [ "$ty" = inline ]; then
				echo "   · $t — встроен в конфиг sing-box"
			else
				pth="$(jsonfilter -i "$c" -e "@.route.rule_set[$i].path" 2>/dev/null)"
				if [ -s "$pth" ]; then
					sz="$(ls -l "$pth" 2>/dev/null | awk '{ s = $5; if (s >= 1048576) printf "%.1f МБ", s / 1048576; else printf "%d КБ", (s + 1023) / 1024 }')"
					case "$pth" in
						*.json) lines="$(grep -o '"[^"]*"' "$pth" 2>/dev/null | grep -c '\.')" ; echo "   ✓ $t — $sz, записей ≈$lines" ;;
						*) echo "   ✓ $t — $sz" ;;
					esac
				else
					echo "   ✗ $t — файла ещё нет ($pth)"
				fi
			fi
			i=$((i + 1))
		done
		[ "$n" -gt 80 ] && echo "   … и ещё $((n - 80))"
	fi
	tbl="$(nft list table inet "$FK_NFT" 2>/dev/null)"
	if [ -n "$tbl" ]; then
		sets="$(printf '%s\n' "$tbl" | awk '$1 == "set" { print $2 }')"
		for set in $sets; do
			cnt="$(nft list set inet "$FK_NFT" "$set" 2>/dev/null | sed -n '/elements = {/,/}/p' | tr ',' '\n' | grep -c '[0-9a-f]')"
			[ "$cnt" -gt 0 ] 2>/dev/null || continue
			[ "$shown" = 0 ] && { _fk_say "Адреса в правилах файрвола (nftables):"; shown=1; }
			case "$set" in
				netshift_subnets|netshift_subnets_v6) echo "   · $set — $cnt (адреса и подсети из списков)" ;;
				*) echo "   · $set — $cnt" ;;
			esac
		done
	fi
	return 0
}

_fk_rs_fatal() {
	local m="$FK_LOGMARK"
	if [ -z "$m" ]; then [ "$1" = recent ] || return 0; fi
	logread 2>/dev/null | { if [ -n "$m" ]; then cat; else tail -n 400; fi; } |
		awk -v m="$m" 'm != "" && !f { if (index($0, m)) f = 1; next } /sing-box/ && /initial rule-set/ { l = $0 } END { if (l != "") print l }' |
		sed 's/\x1b\[[0-9;]*m//g' | awk '
		function rsw(r) {
			if (r ~ /deadline exceeded|i\/o timeout|[Tt]imeout|timed out/) return "сервер не ответил вовремя"
			if (r ~ /connection reset|EOF|broken pipe|forcibly closed/) return "соединение оборвалось"
			if (r ~ /connection refused/) return "сервер отказал в соединении"
			if (r ~ /network is unreachable|no route to host|host is unreachable/) return "нет связи с сервером"
			if (r ~ /no such host|lookup |server misbehaving/) return "не удалось узнать адрес сервера (DNS)"
			if (r ~ /x509|certificate|tls: /) return "не установилось защищённое соединение"
			if (r ~ /operation not permitted/) return "запрос заблокировал сам роутер: правила или туннель ещё не были готовы"
			if (match(r, /(status|code)[: ]+[0-9][0-9][0-9]/)) return "сервер ответил ошибкой " substr(r, RSTART + RLENGTH - 3, 3)
			return substr(r, 1, 160)
		}
		function rsbase(u) { sub(/[?#].*$/, "", u); sub(/^.*\//, "", u); return u }
		{
			t = ""; u = ""; r = ""
			if (match($0, /initial rule-set: [^:]+:/)) t = substr($0, RSTART + 18, RLENGTH - 19)
			if (match($0, /"https?:\/\/[^"]+"/)) { u = substr($0, RSTART + 1, RLENGTH - 2); r = substr($0, RSTART + RLENGTH); sub(/^:[ ]*/, "", r) }
			else if (match($0, /initial rule-set: [^:]+: /)) r = substr($0, RSTART + RLENGTH)
			print t "\t" u "\t" rsw(r)
		}'
}

_fk_clash_ok() { _zm_run 6 /usr/bin/netshift clash_api get_proxies 2>/dev/null | grep -q '"proxies"'; }

_fk_sb_settle() {
	local i=0 max="${1:-60}"
	while [ "$i" -lt "$max" ]; do
		_fk_clash_ok && return 0
		[ -n "$(_fk_rs_fatal)" ] && return 1
		sleep 3; i=$((i + 3))
	done
	return 1
}

_fk_rs_check() {
	local rf t u r sec
	rf="$(_fk_rs_fatal "$1")"
	[ -n "$rf" ] || return 1
	t="$(printf '%s' "$rf" | cut -f1)"; u="$(printf '%s' "$rf" | cut -f2)"; r="$(printf '%s' "$rf" | cut -f3)"
	echo "!! sing-box не запустился: не скачался набор правил ${u:+${u##*/} }(${t:-?})${r:+ — $r}"
	echo "   · sing-box скачивает наборы правил сам при каждом запуске (и после перезагрузки роутера) и без любого из них не работает"
	if [ "$(uci -q get netshift.settings.download_lists_via_proxy)" != 1 ]; then
		case "$r" in *"оборвалось"*|*"вовремя"*|*"нет связи"*) echo "   · Похоже, провайдер не даёт скачивать файлы с GitHub напрямую" ;; esac
		sec="$(_fk_uc secnames 2>/dev/null | head -n1)"
		case "$sec" in ''|*[!A-Za-z0-9_]*) sec="" ;; esac
		if [ -n "$sec" ] && [ -n "$(uci -q get "netshift.$sec.connection_type")" ]; then
			uci -q set netshift.settings.download_lists_via_proxy=1
			uci -q set "netshift.settings.download_lists_via_proxy_section=$sec"
			uci -q commit netshift
			logger -t zapret-manager "Forkozz: набор правил ${u##*/} не скачался напрямую ($r) — включено «Скачивать списки сервисов через VPN», через подключение теперь обновляется и подписка"
			_fk_say "Включаем «Скачивать списки сервисов через VPN»: наборы правил sing-box и обновления подписки пойдут через подключение (не ответит VPN — подписка скачается напрямую)"
			return 0
		fi
	fi
	echo "   · Наборы правил и так качаются через VPN — проверьте, что сервер подключения работает и через него открывается GitHub"
	return 2
}

_fk_lists_errors() {
	local e
	[ -n "$FK_LOGMARK" ] || return 0
	e="$(logread 2>/dev/null | awk -v m="$FK_LOGMARK" '
		function base(u) { sub(/[?#].*$/, "", u); sub(/^.*\//, "", u); return u }
		function why(s,   c) {
			c = ""
			if (match(s, /error_class=[a-z_]+/)) c = substr(s, RSTART + 12, RLENGTH - 12)
			if (c == "operation_not_permitted") return "запрос заблокировал сам роутер: правила или туннель ещё не были готовы"
			if (c ~ /timeout|timed_out/) return "сервер не ответил вовремя"
			if (c ~ /dns|resolve/) return "не удалось узнать адрес сервера"
			if (c ~ /refused|unreachable|network/) return "сервер недоступен"
			if (c ~ /tls|ssl|cert/) return "не установилось защищённое соединение"
			if (c ~ /not_found|404/) return "такого файла на сервере нет"
			return c
		}
		function add(s, own) { if (seen[s]++) return; out[++n] = s; if (own) nn++ }
		function rsw(r) {
			if (r ~ /deadline exceeded|i\/o timeout|[Tt]imeout|timed out/) return "сервер не ответил вовремя"
			if (r ~ /connection reset|EOF|broken pipe|forcibly closed/) return "соединение оборвалось"
			if (r ~ /connection refused/) return "сервер отказал в соединении"
			if (r ~ /network is unreachable|no route to host|host is unreachable/) return "нет связи с сервером"
			if (r ~ /no such host|lookup |server misbehaving/) return "не удалось узнать адрес сервера (DNS)"
			if (r ~ /x509|certificate|tls: /) return "не установилось защищённое соединение"
			if (r ~ /operation not permitted/) return "запрос заблокировал сам роутер: правила или туннель ещё не были готовы"
			if (match(r, /(status|code)[: ]+[0-9][0-9][0-9]/)) return "сервер ответил ошибкой " substr(r, RSTART + RLENGTH - 3, 3)
			return substr(r, 1, 160)
		}
		function rsbase(u) { sub(/[?#].*$/, "", u); sub(/^.*\//, "", u); return u }
		!f { if (index($0, m)) f = 1; next }
		{
			if (!match($0, /(netshift|sing-box)(\[[0-9]+\])?: /)) next
			src = substr($0, RSTART, 8)
			l = substr($0, RSTART + RLENGTH)
		}
		src != "netshift" {
			gsub(/\033\[[0-9;]*m/, "", l)
			if (l ~ /(ERROR|FATAL)/ && l ~ /rule[-_]?set/ && l !~ /initial rule-set/) {
				if (match(l, /"https?:\/\/[^"]+"/)) { u = substr(l, RSTART + 1, RLENGTH - 2); r = substr(l, RSTART + RLENGTH); sub(/^:[ ]*/, "", r); add("sing-box: набор правил " rsbase(u) " не обновился — " rsw(r)) }
				else add("sing-box: " substr(l, 1, 200))
			}
			next
		}
		{ sub(/^\[[a-z]+\] /, "", l) }
		l ~ /Starting lists update/ { k = 0; for (i = 1; i <= n; i++) if (out[i] ~ /^sing-box: /) out[++k] = out[i]; n = k; nn = 0; last = ""; res = ""; split("", seen); for (i = 1; i <= n; i++) seen[out[i]] = 1; next }
		l ~ /Lists update completed successfully/ { res = "ok"; next }
		l ~ /Lists update failed/ { res = "fail"; next }
		l ~ /\[[0-9]+\/[0-9]+\]/ && l ~ /[Ff]ail|[Ee]rror/ { last = why(l); next }
		l ~ /^Download .* list failed/ { split(l, a, " "); add("Не скачался список " base(a[2]) (last != "" ? " — " last : ""), 1); last = ""; next }
		l ~ /Failed to decompile binary rule set/ { add("Набор правил не раскрылся — его адреса пропущены", 1); next }
		l ~ /DNS check failed/ { add("DNS не ответил — списки не скачаны", 1); next }
		l ~ /GitHub connection check failed/ { add("GitHub недоступен — списки не скачаны", 1); next }
		END {
			if (res == "ok") { k = 0; for (i = 1; i <= n; i++) if (out[i] ~ /^sing-box: /) out[++k] = out[i]; n = k }
			else if (res == "fail" && !nn) add("Forkozz сообщил об ошибке загрузки списков" (last != "" ? " — " last : ""), 1)
			from = n > 8 ? n - 7 : 1
			for (i = from; i <= n; i++) print out[i]
		}')"
	[ -n "$e" ] || return 0
	echo "!! Не все списки загрузились:"
	printf '%s\n' "$e" | sed 's/^/   ✗ /'
	case "$e" in *"сервер не ответил вовремя"*|*"сервер недоступен"*)
		if [ "$(uci -q get netshift.settings.download_lists_via_proxy)" != 1 ] && [ -z "$(gh_mirrors)" ]; then
			echo "   · Похоже, провайдер не пускает к файлам GitHub (их отдаёт release-assets.githubusercontent.com). Включите"
			echo "     «Скачивать списки сервисов через VPN» в настройках Forkozz или «Авто» в Система → Доступ к GitHub и нажмите «Перезапустить»"
		fi ;;
	esac
	return 0
}

_fk_sub_wait() {
	local p n i=0 max="${1:-90}" lg
	p="$(cat /var/run/netshift_subscription_retry.pid 2>/dev/null)"
	case "$p" in ''|*[!0-9]*) return 0 ;; esac
	kill -0 "$p" 2>/dev/null || return 0
	_fk_say "Подписка при запуске не скачалась — Forkozz догружает её сам, ждём (до $max с)"
	while [ "$i" -lt "$max" ]; do
		sleep 2
		i=$((i + 2))
		kill -0 "$p" 2>/dev/null && continue
		_fk_settle 120 || true
		n="$(cat /var/run/netshift_subscription_retry.pid 2>/dev/null)"
		case "$n" in ''|*[!0-9]*) ;; *) [ "$n" != "$p" ] && kill -0 "$n" 2>/dev/null && { p="$n"; continue; } ;; esac
		lg=""
		[ -n "$FK_LOGMARK" ] && lg="$(logread 2>/dev/null | awk -v m="$FK_LOGMARK" 'f; index($0, m) { f = 1 }')"
		case "$lg" in
			*'could not apply them'*) _rb_warn "Подписка скачалась, но не применилась — Forkozz повторит при плановом обновлении подписки" ;;
			*'Deferred subscription refresh succeeded'*) echo "   ✓ Подписка догружена и применена" ;;
			*) echo "   · Forkozz закончил догрузку подписки" ;;
		esac
		return 0
	done
	_rb_warn "Подписка пока не скачалась — Forkozz сам пробует снова каждые 30 с; серверы появятся, когда она загрузится"
	return 1
}

_fk_servers_report() {
	local s j err i lbl
	command -v jq >/dev/null 2>&1 || return 0
	for s in $(_fk_uc secnames 2>/dev/null); do
		case "$s" in *[!A-Za-z0-9_]*|'') continue ;; esac
		[ "$(uci -q get netshift."$s".connection_type 2>/dev/null)" = proxy ] || continue
		lbl="$(uci -q get netshift."$s".zm_label 2>/dev/null)"
		lbl="${lbl:-$s}"
		i=0
		while :; do
			j="$(_fk_uc servers "$s" 2>/dev/null)"
			err="$(printf '%s' "$j" | jq -r 'if type == "object" then (.error // empty) else "нет ответа" end' 2>/dev/null)"
			[ -n "$j" ] && [ -z "$err" ] && break
			i=$((i + 1))
			[ "$i" -ge 8 ] && break
			sleep 2
		done
		if [ -z "$j" ] || [ -n "$err" ]; then
			echo "!! Серверы ($lbl): список не получен${err:+ — $err}"
			continue
		fi
		printf '%s' "$j" | jq -r --arg sec "$lbl" '
			def kind: ((.type // "") | ascii_downcase);
			def leaves($n; $t; $seen):
				if ($seen | index([$t])) != null then empty
				else ($n[$t]) as $x
					| if $x == null then empty
					  elif ($x.members | type) == "array" then ($x.members[] as $m | leaves($n; $m; $seen + [$t]))
					  elif ([ "direct", "reject", "block", "dns", "selector", "urltest" ] | index([$x | kind])) != null then empty
					  else $t end
				end;
			def current($n; $t; $d):
				if $d < 16 and $n[$t] != null and (($n[$t].now // "") != "") and $n[$t].now != $t then current($n; $n[$t].now; $d + 1) else $t end;
			. as $j | ($j.nodes // {}) as $n
			| current($n; ($j.now // ""); 0) as $c
			| ([ ($j.list // [])[] as $t | leaves($n; $t; []) ] | reduce .[] as $t ([]; if index([$t]) != null then . else . + [$t] end)) as $L
			| "==> Серверы (\($sec)): \($L | length)",
			  (if ($L | length) == 0 then "   ✗ ни одного сервера — проверьте ссылку подписки или ссылки серверов" else empty end),
			  (if $c != "" then
				"   → сейчас трафик идёт \(if (($n[$c] // {}) | kind) == "direct" or ($c | contains("direct")) then "напрямую, без VPN" else "через «\($n[$c].name // $c)»" end)"
			   else empty end)' 2>/dev/null || echo "!! Серверы ($lbl): не удалось разобрать ответ панели"
	done
	return 0
}

_fk_check_live() {
	local j
	if _fk_sb_alive; then echo "   ✓ sing-box работает"; else echo "   ✗ sing-box не запущен"; fi
	if nft list table inet "$FK_NFT" >/dev/null 2>&1; then echo "   ✓ Правила перехвата трафика на месте"; else echo "   ✗ Правил перехвата трафика нет"; fi
	local t=0
	while :; do
		j="$(_zm_run 20 /usr/bin/netshift check_fakeip 2>/dev/null)"
		case "$j" in *'"fakeip": true'*|*'"fakeip":true'*) break ;; esac
		t=$((t + 1)); [ "$t" -ge 5 ] && break
		sleep 3
	done
	case "$j" in
		*'"fakeip": true'*|*'"fakeip":true'*) echo "   ✓ DNS отдаёт адреса Forkozz — выбранные сервисы идут через туннель" ;;
		*) echo "   ! Проверочный домен не получил адрес Forkozz — нажмите «Проверить» через минуту; если так и останется, перезапустите Forkozz" ;;
	esac
}

_fk_resume() {
	[ -x /etc/init.d/netshift ] || return 0
	[ "$1" = 1 ] && /etc/init.d/netshift enable >/dev/null 2>&1
	[ "$2" = 1 ] && { _fk_say "Запускаем Forkozz обратно"; mkdir -p /etc/sing-box; /etc/init.d/netshift start >/dev/null 2>&1; }
	return 0
}

do_fk_install() {
	local mode="$1" tag tmp="$JOBS_DIR/netshift-src" tgz src rel major b need="" p free was_run=0 was_en=0 fresh=1 sbfree=0
	local keep="$JOBS_DIR/netshift.conf.keep"
	_fk_say "Проверяем роутер: версию OpenWrt, свободную память и конфликты"
	rel="$(awk -F\' '/DISTRIB_RELEASE/ {print $2}' /etc/openwrt_release)"
	major="${rel%%.*}"
	case "$major" in ''|*[!0-9]*) ;; *) [ "$major" -ge 24 ] || { echo "ОШИБКА: Forkozz работает на OpenWrt 24.10 и новее, а здесь $rel"; return 1; } ;; esac
	b="$(_fk_blocker)"
	[ -n "$b" ] && { echo "ОШИБКА: $(_fk_blocker_text "$b")"; return 1; }
	_fk_installed && fresh=0
	[ -z "$(_fk_sb_ver)" ] && sbfree=12288
	free="$(df -k /overlay 2>/dev/null | awk 'NR==2 {print $4}')"
	[ -n "$free" ] || free="$(df -k / 2>/dev/null | awk 'NR==2 {print $4}')"
	if [ -n "$free" ] && [ "$free" -lt $((4096 + sbfree)) ]; then
		echo "ОШИБКА: мало памяти: свободно $((free / 1024)) МБ, нужно около $(((4096 + sbfree) / 1024)) МБ"
		return 1
	fi
	echo "   ✓ OpenWrt $rel, свободно ${free:+$((free / 1024)) МБ}, конфликтов нет"

	_zm_net_prepare "$(_zm_feed_host)" || return 1
	_zm_dns_ok codeload.github.com || _zm_net_heal
	_fk_say "Обновляем список пакетов"
	$UPDATE || { echo "ОШИБКА: список пакетов не обновился — проверьте интернет"; return 1; }
	_fk_say "Проверяем нужные пакеты"
	for p in $FK_DEPS; do _pkg_is_installed "$p" || need="$need $p"; done
	[ -n "$need" ] || echo "   ✓ Все нужные пакеты уже стоят"
	if [ -n "$need" ]; then
		_fk_say "Ставим недостающие пакеты:$need"
		$INSTALL $need
		for p in $need; do _pkg_is_installed "$p" || { echo "ОШИБКА: не установился пакет $p"; return 1; }; done
		mkdir -p "$ZM_STATE_DIR"
		for p in $need; do grep -qx "$p" "$FK_DEPS_OWN" 2>/dev/null || echo "$p" >> "$FK_DEPS_OWN"; done
	fi

	{ [ "$mode" = update ] || [ "$fresh" = 1 ]; } && tag="$(ZM_VER_FORCE=1 _zm_cached netshift _fk_latest_fetch)"
	[ -n "$ZM_FK_TAG" ] && tag="$ZM_FK_TAG"
	[ -n "$tag" ] || tag="$(_fk_version)"
	[ -n "$tag" ] || tag="$FK_PIN"
	_fk_say "Скачиваем движок Forkozz $tag с GitHub"
	rm -rf "$tmp"
	mkdir -p "$tmp"
	tgz="$tmp/src.tar.gz"
	_zm_gh_get "https://codeload.github.com/$FK_REPO/tar.gz/refs/tags/$tag" "$tgz" ||
		_zm_gh_get "https://github.com/$FK_REPO/archive/refs/tags/$tag.tar.gz" "$tgz" || {
		rm -rf "$tmp"
		echo "ОШИБКА: GitHub не отвечает — ни напрямую, ни через WARP"
		return 1
	}
	if ! tar -xzf "$tgz" -C "$tmp" 2>/dev/null; then
		rm -rf "$tmp"
		echo "ОШИБКА: архив скачался битым — попробуйте ещё раз"
		return 1
	fi
	echo "   ✓ Архив скачан ($(ls -l "$tgz" 2>/dev/null | awk '{ printf "%d КБ", ($5 + 1023) / 1024 }')), распаковываем"
	rm -f "$tgz"
	src="$(ls -d "$tmp"/*/netshift/files 2>/dev/null | head -n1)"
	if [ ! -f "$src/usr/bin/netshift" ] || [ ! -f "$src/usr/lib/constants.sh" ] || [ ! -f "$src/etc/init.d/netshift" ] || [ ! -f "$src/etc/config/netshift" ]; then
		rm -rf "$tmp"
		echo "ОШИБКА: в архиве движка Forkozz нет нужных файлов"
		return 1
	fi
	sed -i "s#__COMPILED_VERSION_VARIABLE__#$tag#g" "$src/usr/lib/constants.sh"
	grep -q "^NETSHIFT_VERSION=\"$tag\"" "$src/usr/lib/constants.sh" || { rm -rf "$tmp"; echo "ОШИБКА: не удалось прописать версию движка Forkozz"; return 1; }
	if [ -n "$(gh_mirrors)" ]; then _fk_say "Источники: GitHub (если не отвечает — через зеркала) и репозиторий OpenWrt"
	else _fk_say "Источники: GitHub и репозиторий OpenWrt, без зеркал"; fi

	if _fk_foreign; then
		_fk_say "Убираем отдельный пакет движка с LuCI, настройки оставляем"
		_fk_up && was_run=1
		_fk_enabled && was_en=1
		[ -s /etc/config/netshift ] && cp /etc/config/netshift "$keep"
		[ "$was_run" = 1 ] && _zm_run 60 $FK_REL /etc/init.d/netshift stop >/dev/null 2>&1
		for p in luci-i18n-netshift-ru luci-app-netshift netshift; do _pkg_is_installed "$p" && $DELETE "$p" >&2; done
		rm -rf /www/luci-static/resources/view/netshift /usr/share/luci/menu.d/luci-app-netshift.json /usr/share/rpcd/acl.d/luci-app-netshift.json
		[ -s "$keep" ] && cp "$keep" /etc/config/netshift
		rm -f "$keep"
		fresh=0
	elif [ "$fresh" = 0 ]; then
		_fk_up && was_run=1
		_fk_enabled && was_en=1
		[ "$was_run" = 1 ] && { _fk_say "Останавливаем Forkozz на время обновления"; _zm_run 60 $FK_REL /etc/init.d/netshift stop >/dev/null 2>&1; }
	fi

	_fk_say "Копируем файлы движка Forkozz в систему"
	rm -rf /usr/lib/netshift.zm-old
	if [ -d /usr/lib/netshift ]; then
		mv /usr/lib/netshift /usr/lib/netshift.zm-old
		[ -f /usr/bin/netshift ] && mv /usr/bin/netshift /usr/lib/netshift.zm-old/.bin
		[ -f /etc/init.d/netshift ] && mv /etc/init.d/netshift /usr/lib/netshift.zm-old/.init
		[ -f /etc/init.d/netshift-naive ] && mv /etc/init.d/netshift-naive /usr/lib/netshift.zm-old/.naive
	fi
	rm -f /etc/init.d/netshift-naive
	mkdir -p /usr/lib/netshift /etc/netshift
	if ! cp -R "$src/usr/lib/." /usr/lib/netshift/ ||
		! cp "$src/usr/bin/netshift" /usr/bin/netshift ||
		! cp "$src/etc/init.d/netshift" /etc/init.d/netshift ||
		! { [ ! -f "$src/etc/init.d/netshift-naive" ] || cp "$src/etc/init.d/netshift-naive" /etc/init.d/netshift-naive; } ||
		! cp "$src/etc/config/netshift" /usr/lib/netshift/default.config; then
		_fk_restore_old
		rm -rf "$tmp"
		_fk_resume "$was_en" "$was_run"
		echo "ОШИБКА: файлы не записались — похоже, кончилась память"
		return 1
	fi
	chmod 0755 /usr/bin/netshift /etc/init.d/netshift
	[ -f /etc/init.d/netshift-naive ] && chmod 0755 /etc/init.d/netshift-naive
	chmod -R a+rX /usr/lib/netshift
	_fk_fast_patch
	_fk_mlkem_patch
	_fk_serial_patch
	_fk_listsvia_patch
	_fk_subvia_patch
	_fk_reality_patch
	_fk_rsinit_patch
	_fk_desync_patch
	_fk_fakeip_patch
	_fk_ghdl_patch
	_fk_subck_patch
	rm -rf "$tmp"

	if [ ! -s /etc/config/netshift ]; then
		cp /usr/lib/netshift/default.config /etc/config/netshift
		uci -q delete netshift.main
		uci -q set netshift.settings.dns_type='udp'
		uci -q set netshift.settings.dns_server='9.9.9.9'
		uci -q set netshift.settings.bootstrap_dns_server='9.9.9.9'
		uci -q delete netshift.settings.zm_dns_servers
		uci -q add_list netshift.settings.zm_dns_servers='9.9.9.9'
		uci -q delete netshift.settings.zm_bootstrap
		uci -q add_list netshift.settings.zm_bootstrap='9.9.9.9'
		uci -q add_list netshift.settings.zm_bootstrap='77.88.8.8'
		uci -q set netshift.settings.disable_quic='1'
		uci -q commit netshift
		_fk_say "DNS по умолчанию: Quad9 9.9.9.9 (обычный UDP). Сменить можно в «Настройках»"
	fi
	chmod 0644 /etc/config/netshift
	_fk_log_default

	if ! _fk_device_setup; then
		if [ -d /usr/lib/netshift.zm-old ]; then
			echo "ОШИБКА: новая версия движка не приняла доработки панели — возвращаем прежнюю"
			_fk_restore_old
			_fk_resume "$was_en" "$was_run"
		fi
		return 1
	fi
	rm -rf /usr/lib/netshift.zm-old
	echo "$tag" > "$FK_MARK"
	rm -f /tmp/luci-indexcache* /tmp/luci-modulecache/* /var/luci-indexcache* 2>/dev/null

	_fk_sb_install || { echo "!! Forkozz установлен, но без sing-box он не работает — выберите вариант sing-box в «Настройках» или нажмите «Переустановить»"; return 1; }

	[ "$was_en" = 1 ] && /etc/init.d/netshift enable >/dev/null 2>&1
	if [ "$was_run" = 1 ]; then
		_fk_say "Запускаем Forkozz"
		mkdir -p /etc/sing-box
		_zm_quiet "" /etc/init.d/netshift start || true
		_fk_wait_up 90 || echo "!! Forkozz не запустился — нажмите «Проверить»"
		_fk_fwd_sync
	fi
	if [ "$mode" = reinstall ] && [ "$fresh" = 0 ]; then
		_fk_say "Готово: Forkozz $tag переустановлен, настройки сохранены"
	elif [ "$fresh" = 1 ]; then
		_fk_say "Готово: Forkozz $tag установлен. Настройте подключение и сервисы"
	else
		_fk_say "Готово: Forkozz обновлён до $tag"
	fi
}

_fk_tunnels() {
	local s i seen=""
	for s in $(uci -q show netshift 2>/dev/null | sed -n "s/^netshift\.\([^.=]*\)\.connection_type='vpn'\$/\1/p"); do
		i="$(uci -q get "netshift.$s.interface" 2>/dev/null)"
		[ -n "$i" ] || continue
		[ "$(uci -q get "network.$i.proto")" = amneziawg ] || continue
		_awg_is_steer "$i" && continue
		case " $seen " in *" $i "*) continue ;; esac
		seen="$seen $i"
		echo "$i"
	done
}

_fk_tunnels_json() {
	local i sep="" own route p up v u
	printf '{"tunnels":['
	for i in $(_fk_tunnels); do
		own=false; _awg_owned "$i" && own=true
		p="$(_awg_peer_sec "$i")"
		route=false; [ -n "$p" ] && [ "$(uci -q get "network.$p.route_allowed_ips")" = 1 ] && route=true
		up=false; [ -d "/sys/class/net/$i" ] && up=true
		printf '%s{"name":"%s","owned":%s,"route_all":%s,"up":%s}' "$sep" "$(esc "$i")" "$own" "$route" "$up"
		sep=","
	done
	v="$(_fk_sb_ver)"; u="$(_fk_sb_users)"
	printf '],"singbox":"%s","singbox_users":"%s","awg_installed":%s,"awg_busy":"%s"}\n' "$(esc "$v")" "$(esc "$u")" \
		"$(_awg_installed && echo true || echo false)" "$(esc "$(_fk_awg_busy $(_fk_tunnels))")"
}

_fk_awg_busy() {
	local i others=""
	_st_warp_on && { echo "он нужен Steer для WARP"; return 0; }
	_job_running awg && { echo "на вкладке AmneziaWG идёт операция"; return 0; }
	for i in $(_awg_ifaces); do
		case " $* " in *" $i "*) continue ;; esac
		_awg_is_steer "$i" && { echo "его туннели использует Steer"; return 0; }
		others="$others${others:+, }$i"
	done
	[ -n "$others" ] && echo "на нём работают другие туннели: $others"
	return 0
}

_fk_tunnels_off() {
	local mode="$1" i p
	shift
	for i in "$@"; do
		if _st_uses_if "$i"; then
			echo "   · Туннель $i оставлен как есть — через него работают сервисы Steer"
			continue
		fi
		if [ "$mode" = keep ]; then
			p="$(_awg_peer_sec "$i")"
			if [ -n "$p" ] && [ "$(uci -q get "network.$p.route_allowed_ips")" = 1 ]; then
				echo "!! Туннель $i оставлен включённым, и через него идёт ВЕСЬ интернет роутера. Не нужен — выключите его на вкладке AmneziaWG"
			else
				echo "   · Туннель $i оставлен включённым. Маршрутов через него нет, трафик устройств в него не идёт"
			fi
		elif [ "$mode" = purge ] || { [ "$mode" = delete ] && _awg_owned "$i"; }; then
			_fk_say "Удаляем туннель $i"
			_awg_delete "$i"
			echo "   ✓ Туннель $i удалён"
		else
			[ "$mode" = delete ] && echo "   · Туннель $i создан не панелью — не удаляем, только выключаем"
			_fk_say "Выключаем туннель $i"
			uci set "network.$i.auto=0"
			uci commit network
			_awg_down "$i"
			echo "   ✓ Туннель $i выключен, настройки сохранены (включить: вкладка AmneziaWG → «Включить»)"
		fi
	done
}

_fk_sb_park() {
	[ -n "$(_fk_sb_ver)" ] || return 0
	if [ -n "$(_fk_sb_users)" ]; then
		_fk_say "sing-box оставляем — он нужен: $(_fk_sb_users)"
		return 0
	fi
	_fk_say "Оставляем sing-box $(_fk_sb_ver) ($(_fk_sb_name "$(_fk_sb_var)"))"
	[ -x /etc/init.d/sing-box ] && { /etc/init.d/sing-box stop >/dev/null 2>&1; /etc/init.d/sing-box disable >/dev/null 2>&1; }
	_fk_sb_alive && { killall $FK_SB_PROCS >/dev/null 2>&1; sleep 1; killall -9 $FK_SB_PROCS >/dev/null 2>&1; }
	rm -rf /tmp/sing-box 2>/dev/null
	echo "   ✓ Он остановлен и убран из автозапуска — без Forkozz ему нечего делать. Удалить его можно на вкладке Forkozz"
}

do_fk_remove() {
	local arg="$1" tmode=stop sbmode=remove awg=keep tun rc=0 why
	case "$arg" in delete|stop|keep) tmode="$arg" ;; esac
	case "$arg" in *tun=delete*) tmode=delete ;; *tun=keep*) tmode=keep ;; *tun=stop*) tmode=stop ;; *tun=purge*) tmode=purge; awg=remove ;; esac
	case "$arg" in *sb=keep*) sbmode=keep ;; esac
	case "$arg" in *awg=remove*) awg=remove ;; esac
	tun="$(_fk_tunnels | tr '\n' ' ')"
	if [ "$awg" = remove ]; then
		why="$(_fk_awg_busy $tun)"
		if [ -n "$why" ]; then
			_rb_warn "AmneziaWG оставляем: $why"
			awg=keep
			[ "$tmode" = purge ] && tmode=delete
		fi
	fi
	_fk_say "Останавливаем Forkozz"
	if [ -x /etc/init.d/netshift ]; then
		/etc/init.d/netshift disable >/dev/null 2>&1
		_zm_run 90 $FK_REL /etc/init.d/netshift stop >/dev/null 2>&1
	fi
	if _fk_sb_alive && [ -z "$(_fk_sb_users)" ]; then
		[ -x /etc/init.d/sing-box ] && /etc/init.d/sing-box stop >/dev/null 2>&1
		_fk_sb_alive && { killall $FK_SB_PROCS >/dev/null 2>&1; sleep 1; killall -9 $FK_SB_PROCS >/dev/null 2>&1; }
	fi
	echo "   ✓ Forkozz остановлен и убран из автозапуска"
	_fk_say "Снимаем перехват трафика и возвращаем DNS роутера"
	nft delete table inet "$FK_NFT" >/dev/null 2>&1
	nft delete table inet "$FK_NFT_GUARD" >/dev/null 2>&1
	if nft list table inet "$FK_NFT" >/dev/null 2>&1; then echo "!! Правила файрвола Forkozz не снялись — они пропадут после перезагрузки роутера"
	elif _fk_ip_clean q; then echo "   ✓ Правила файрвола и маршруты Forkozz убраны"
	else echo "!! Правила файрвола убраны, но часть маршрутов осталась — она пропадёт после перезагрузки роутера"; fi
	_fk_dnsmasq_clean q
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	echo "   ✓ DNS роутера работает как обычно — интернет идёт напрямую"
	[ -n "$tun" ] && _fk_tunnels_off "$tmode" $tun
	_fk_say "Удаляем файлы, настройки и кэш Forkozz"
	if [ -x /etc/init.d/netshift-naive ]; then
		_zm_run 30 /etc/init.d/netshift-naive stop >/dev/null 2>&1
		/etc/init.d/netshift-naive disable >/dev/null 2>&1
	fi
	sed -i '/^naive:x:6501:/d' /etc/passwd /etc/group 2>/dev/null
	_fk_bg_stop
	_zm_pkg_wipe luci-i18n-netshift-ru luci-app-netshift netshift || rc=1
	sed -i '/netshift/d' /etc/sysupgrade.conf 2>/dev/null
	if grep -q 'netshift' "$CRON_FILE" 2>/dev/null; then
		sed -i '/netshift/d' "$CRON_FILE"
		/etc/init.d/cron restart >/dev/null 2>&1
	fi
	_zm_wipe $FK_FILES "$JOBS_DIR/netshift-src" $(_fk_naive_own) \
		"$FK_MARK" "$ZM_STATE_DIR/latest.netshift" "$ZM_STATE_DIR"/fk.sub.* "$ZM_STATE_DIR"/fk.fell* "$ZM_STATE_DIR"/fk.home.* "$ZM_STATE_DIR/fk.dnsfo" "$ZM_STATE_DIR/fk.watch" "$ZM_STATE_DIR/fk.zash.fail" "$FK_EXT_FAIL" "$FK_NAIVE_FAIL" "$JOBS_DIR/netshift.conf.bak" \
		"$JOBS_DIR"/fk.heal* "$JOBS_DIR"/fk-* "$JOBS_DIR"/fkdns.* "$JOBS_DIR/forkop-svc.out" "$JOBS_DIR/forkop-sb.json" "$JOBS_DIR/forkop-lists.out" &&
		echo "   ✓ Файлы, настройки, кэш и задания расписания удалены" || rc=1
	if [ "$sbmode" = keep ]; then _fk_sb_park; else _fk_sb_purge || rc=1; fi
	_fk_deps_purge
	if [ "$awg" = remove ] && _awg_installed; then
		_fk_say "Удаляем AmneziaWG — больше он нигде не используется"
		ZM_NO_NETCHECK=1 do_awg_remove all || rc=1
	fi
	rm -f /tmp/luci-indexcache* /tmp/luci-modulecache/* /var/luci-indexcache* 2>/dev/null
	_zm_after_remove "Forkozz"
	_zm_rm_done "$rc" "Forkozz"
}

_fk_bg_stop() {
	local f p
	for f in "$FK_GUARD_PID" /tmp/zm-fk-pingloop.*/pid; do
		p="$(cat "$f" 2>/dev/null)"
		case "$p" in ''|*[!0-9]*) continue ;; esac
		[ "$p" != "$$" ] && kill "$p" 2>/dev/null
	done
	return 0
}
_fk_naive_own() {
	[ -e /usr/bin/naive ] || return 0
	_pkg_is_installed naiveproxy && return 0
	echo /usr/bin/naive
}
_fk_deps_purge() {
	local p keep left="" gone="" list
	list="$(cat "$FK_DEPS_OWN" 2>/dev/null) jq bind-dig coreutils-base64 kmod-inet-diag"
	_fk_say "Удаляем пакеты, которые ставил Forkozz"
	for p in $(printf '%s\n' $list | awk '!s[$0]++'); do
		_pkg_is_installed "$p" || continue
		keep=""
		case "$p" in
			curl|ca-bundle|ucode|ucode-mod-fs|ucode-mod-uci|ip-full) keep="нужен самой панели и LuCI" ;;
			kmod-tun) _mx_installed && keep="нужен Mixomo"; [ -z "$keep" ] && _bt_installed && keep="нужен ByeTube" ;;
			kmod-nft-tproxy) _mx_installed && keep="нужен Mixomo" ;;
		esac
		if [ -n "$keep" ]; then echo "   · $p оставляем — $keep"; left="$left $p"; continue; fi
		if [ "$PKG" = apk ]; then _zm_run 180 apk del "$p" >/dev/null 2>&1
		else _zm_run 180 opkg remove --autoremove "$p" >/dev/null 2>&1; fi
		_zm_pkg_unlock
		if _pkg_is_installed "$p"; then echo "   · $p оставляем — он нужен другим пакетам"; left="$left $p"
		else gone="$gone $p"; fi
	done
	[ -n "$gone" ] && echo "   ✓ Удалены:$gone"
	[ -z "$gone$left" ] && echo "   ✓ Таких пакетов на роутере нет"
	rm -f "$FK_DEPS_OWN"
	return 0
}

do_fk_sb_remove() {
	_fk_installed && { echo "ОШИБКА: Forkozz установлен — без sing-box он не работает. Сначала удалите Forkozz"; return 1; }
	local u
	u="$(_fk_sb_users)"
	[ -n "$u" ] && { echo "ОШИБКА: sing-box нужен другим программам ($u) — удалять его нельзя"; return 1; }
	_fk_sb_purge || return 1
	rm -f /tmp/luci-indexcache* /tmp/luci-modulecache/* 2>/dev/null
	_fk_say "Готово: sing-box удалён полностью, остатков нет"
}

_fk_start_once() {
	mkdir -p /etc/sing-box
	_zm_run 60 /etc/init.d/netshift start >> "$JOBS_DIR/forkop-svc.out" 2>&1
}

_fk_wait_up() {
	local i=0 max="$1"
	while [ "$i" -lt "$max" ]; do
		_fk_ready && break
		sleep 1
		i=$((i + 1))
		[ "$i" = 20 ] && printf 'Подождите '
		[ "$i" -gt 20 ] && [ $((i % 5)) = 0 ] && printf '.'
		[ "$i" = "$max" ] && [ "$max" = "$1" ] && _fk_engine_busy && max=$((max + 150))
	done
	[ "$i" -ge 20 ] && echo
	_fk_ready
}

_fk_why() {
	local l
	if [ -n "$FK_LOGMARK" ]; then
		l="$(logread 2>/dev/null | awk -v m="$FK_LOGMARK" 'f { print } index($0, m) { f = 1 }' | grep -E 'netshift|sing-box' | grep -E 'fatal|FATAL|Aborted|error|is not started: no section' | tail -n 1)"
	else
		l="$(logread 2>/dev/null | tail -n 200 | grep -E 'netshift|sing-box' | grep -E 'fatal|FATAL|Aborted|error|is not started: no section' | tail -n 1)"
	fi
	case "$l" in
		*"initial rule-set"*) echo "sing-box не смог скачать набор правил при запуске (подробности выше)" ;;
		*"no section has a connection yet"*) echo "ни в одной секции нет подключения — добавьте ссылку на сервер или подписку" ;;
		*"Outbound section not found"*) echo "ни в одной секции нет настроенного подключения" ;;
		*"Invalid service in community lists"*) echo "в секции выбран список, которого Forkozz не знает — сохраните сервисы заново" ;;
		*"configuration"*"is invalid"*) echo "sing-box не принял собранный конфиг — посмотрите журнал" ;;
		*"version"*"lower than the required"*) echo "sing-box слишком старый — замените его в «Настройках»" ;;
		*"Service 'sing-box' is missing"*) echo "нет службы sing-box — переустановите sing-box в «Настройках»" ;;
		*"Proxy string is not set"*|*"links is not set"*) echo "в секции нет ни одного сервера" ;;
		*"VPN interface is not set"*) echo "в секции не выбран туннель" ;;
	esac
}

_fk_reset_runtime() {
	_zm_run 90 /etc/init.d/netshift stop >/dev/null 2>&1
	if _fk_sb_alive && [ -z "$(_fk_sb_users)" ]; then
		[ -x /etc/init.d/sing-box ] && /etc/init.d/sing-box stop >/dev/null 2>&1
		killall $FK_SB_PROCS >/dev/null 2>&1
		sleep 2
		_fk_sb_alive && killall -9 $FK_SB_PROCS >/dev/null 2>&1
		echo "   ✓ Остановлен оставшийся процесс sing-box"
	fi
	nft delete table inet "$FK_NFT" >/dev/null 2>&1
	uci -q set netshift.settings.shutdown_correctly='1' && uci -q commit netshift
}

_fk_svc_report() {
	local f="$JOBS_DIR/forkop-svc.out" lines
	[ -s "$f" ] || return 0
	lines="$(sed 's/\x1b\[[0-9;]*m//g' "$f" | grep -v '^[[:space:]]*$' | grep -viE 'udhcpc|^pending$|^Start netshift$|service_triggers|Command failed: ubus call service (delete|list|signal)' | grep -iE 'error|fatal|fail|abort|ошиб|не удалось' | awk '!s[$0]++' | tail -n 8)"
	[ -n "$lines" ] && printf '%s\n' "$lines" | sed 's/^/   /'
	return 0
}

_fk_rl_si() {
	local fp mk n
	fp="$(uci -q get "netshift.$1.zm_rl_fp")"; mk="$(uci -q get "netshift.$1.zm_rl_mk")"
	n="$(uci -q get "netshift.$1.zm_rl_node" | wc -w)"; n=$((n / 3))
	[ -n "$fp$mk" ] || [ "$n" -gt 0 ] || return 0
	printf ' · REALITY: отпечаток %s, ключ %s' "$(case "${fp:-auto}" in auto) echo авто ;; sub) echo как в подписке ;; *) echo "$fp" ;; esac)" \
		"$(case "${mk:-auto}" in on) echo включён ;; off) echo выключен ;; *) echo авто ;; esac)"
	[ "$n" -gt 0 ] && printf ', свои настройки у серверов: %s' "$n"
	return 0
}

_fk_rl_learn_run() {
	local req="$1" quiet="$2" j n
	[ -n "$req" ] || req='{}'
	command -v jq >/dev/null 2>&1 || return 0
	[ -s /tmp/zm-fk-rlalt.json ] || { [ -n "$quiet" ] || echo "   · проверять нечего: серверов REALITY с выбором ключа «Авто» нет, или sing-box не умеет отправлять ключ"; return 0; }
	j="$(printf '%s' "$req" | _fk_ucj rllearn)"
	case "$j" in *'"error"'*) [ -n "$quiet" ] || echo "!! Проверка ключа не удалась: $(printf '%s' "$j" | jq -r '.error // empty' 2>/dev/null)"; return 1 ;; esac
	n="$(printf '%s' "$j" | jq -r '.tested // 0' 2>/dev/null)"
	[ "${n:-0}" -gt 0 ] 2>/dev/null || { [ -n "$quiet" ] || echo "   · все серверы REALITY уже проверены — ключ подобран"; return 0; }
	printf '%s' "$j" | jq -r '
		"   · проверено серверов REALITY: \(.tested) — работают как есть: \(.works)\(if .dead > 0 then ", не отвечают ни с ключом, ни без: \(.dead)" else "" end)",
		(.list[] | "   ✓ «\(.name)»: работает только \(if .key then "с ключом X25519MLKEM768" else "без ключа X25519MLKEM768" end) — запомнили")' 2>/dev/null
	n="$(printf '%s' "$j" | jq -r '.changed // 0' 2>/dev/null)"
	[ "${n:-0}" -gt 0 ] 2>/dev/null || return 0
	_fk_say "Применяем подобранный ключ X25519MLKEM768"
	if _zm_run 240 /usr/bin/netshift reload >/dev/null 2>&1; then echo "   ✓ Настройки применены"
	else echo "!! Forkozz не применил подобранный ключ — нажмите «Применить» ещё раз"; return 1; fi
	return 0
}

do_fk_rl_learn() {
	_fk_installed || { echo "ОШИБКА: Forkozz не установлен"; return 1; }
	_fk_up || { echo "ОШИБКА: Forkozz выключен — включите его, и серверы можно будет проверить"; return 1; }
	_fk_say "Проверяем серверы REALITY с ключом X25519MLKEM768 и без — запрос через каждый вариант"
	_fk_rl_learn_run "$1" || return 1
	_fk_say "Готово"
}

_fk_rl_watch() {
	local s="$ZM_STATE_DIR/fk.rl.watch" now
	[ -s /tmp/zm-fk-rlalt.json ] || return 0
	now="$(date +%s)"
	[ "$(( now - $(cat "$s" 2>/dev/null || echo 0) ))" -ge 21600 ] 2>/dev/null || return 0
	_job_running forkop && return 0
	_fk_up || return 0
	echo "$now" > "$s"
	( _fk_rl_learn_run '{"max":40}' quiet >/dev/null 2>&1 & )
}

_fk_rl_report() {
	[ -n "$FK_LOGMARK" ] || return 0
	logread 2>/dev/null | awk -v m="$FK_LOGMARK" 'f && /REALITY \(Zapret Manager\): / { print } index($0, m) { f = 1 }' | awk '
		{ sub(/^.*REALITY \(Zapret Manager\): /, "") }
		/did not accept/ { rej = 1; next }
		/key share on [0-9]+ of [0-9]+/ { s = $0; rej = 0 }
		END {
			if (rej) { print "!! REALITY: sing-box не принял настройки совместимости — конфиг собран без них"; exit }
			if (s == "" || !match(s, /key share on [0-9]+ of [0-9]+/)) exit
			split(substr(s, RSTART, RLENGTH), a, " ")
			fc = ""; if (match(s, /fingerprint changed on [0-9]+/)) { split(substr(s, RSTART, RLENGTH), b, " "); fc = b[4] }
			nd = ""; if (match(s, /; [0-9]+ server/)) nd = substr(s, RSTART + 2, RLENGTH - 9)
			print "==> REALITY: серверов — " a[6] ", с ключом X25519MLKEM768 — " a[4] (fc != "" ? ", отпечаток изменён — " fc : "")
			if (match(s, /test variants for [0-9]+/)) print "   · Ключ «Авто»: каждый сервер проверяется с ключом и без, рабочий вариант запоминается"
			if (nd != "") print "   ! Без ключа остались серверы REALITY: " nd " — ключ отправляет только расширенный sing-box 2.7.2 и новее (или используйте Steer)"
		}'
	return 0
}

do_fk_service() {
	local a="$1" b
	_fk_installed || { echo "ОШИБКА: Forkozz не установлен"; return 1; }
	case "$a" in
		stop)
			_fk_say "Выключаем Forkozz — трафик пойдёт напрямую"
			/etc/init.d/netshift disable >/dev/null 2>&1
			echo "   ✓ Убран из автозапуска"
			_zm_run 90 $FK_REL /etc/init.d/netshift stop >/dev/null 2>&1
			nft delete table inet "$FK_NFT" >/dev/null 2>&1
			nft delete table inet "$FK_NFT_GUARD" >/dev/null 2>&1
			if nft list table inet "$FK_NFT" >/dev/null 2>&1; then echo "!! Служба остановлена, но её правила в firewall остались — перезагрузите роутер"
			else echo "   ✓ Служба остановлена, правила сняты"; fi
			_ab_free_sync >/dev/null 2>&1
			_fk_say "Готово: Forkozz выключен"
			return 0 ;;
	esac
	_fk_dns_migrate >/dev/null 2>&1
	_fk_device_setup || return 1
	b="$(_fk_blocker)"
	[ -n "$b" ] && { echo "ОШИБКА: $(_fk_blocker_text "$b")"; return 1; }
	[ -n "$(_fk_sb_ver)" ] || _fk_sb_install || return 1
	_fk_ext_auto config "" norestart
	_fk_naive_auto
	_fk_log_default
	if _fk_sub_fmt_auto; then
		_fk_say "Скачиваем подписку в новом формате"
		if _fk_sub_update; then echo "   ✓ Подписка обновлена"
		else echo "!! Подписка в новом формате не обновилась — Forkozz возьмёт её при следующем обновлении"; fi
	fi
	local lx; lx="$(_fk_log_ext)"
	/etc/init.d/netshift enable >/dev/null 2>&1
	_fk_fast_patch
	_fk_mlkem_patch
	_fk_serial_patch
	_fk_listsvia_patch
	_fk_subvia_patch
	_fk_reality_patch
	_fk_rsinit_patch
	_fk_desync_patch
	_fk_fakeip_patch
	_fk_ghdl_patch
	_fk_subck_patch
	mkdir -p /etc/sing-box
	_fk_log_mark
	: > "$JOBS_DIR/forkop-svc.out"
	_fk_settle 180 "Forkozz ещё заканчивает прошлую операцию (запуск или применение подписки) — ждём её" ||
		_rb_warn "Прошлая операция Forkozz не закончилась за 3 минуты — продолжаем, движок выполнит нашу следом"
	if [ "$a" = apply ] && _fk_up && _fk_fip_stale; then
		_fk_say "Пул Fake IP теперь $(_fk_fip_file) — перезапускаем Forkozz полностью"
		a=start
	fi
	if [ "$a" = apply ] && _fk_up; then
		_fk_say "Применяем настройки: Forkozz пересобирает конфиг sing-box и подхватывает списки"
		_zm_run 240 /usr/bin/netshift reload >> "$JOBS_DIR/forkop-svc.out" 2>&1 || echo "!! Перезагрузка настроек завершилась с ошибкой"
	else
		_fk_say "Запускаем Forkozz: собираем конфиг sing-box, скачиваем списки, ставим правила"
		if _fk_up || _fk_sb_alive || nft list table inet "$FK_NFT" >/dev/null 2>&1; then
			_zm_run 90 /etc/init.d/netshift stop >> "$JOBS_DIR/forkop-svc.out" 2>&1
		fi
		_fk_start_once || echo "!! Запуск завершился с ошибкой"
	fi
	_fk_svc_report
	if ! _fk_ready; then
		_fk_say "Ждём, пока поднимутся sing-box и правила (до 90 с)"
		_fk_wait_up 90
	fi
	if ! _fk_up; then
		_fk_rs_check
		if [ "$?" = 1 ]; then
			b="$(_fk_why)"
			_rb_warn "Forkozz не поднялся${b:+: $b}"
		fi
		_fk_say "Пробуем ещё раз: снимаем остатки прошлого запуска и запускаем заново"
		_fk_log_mark
		_fk_reset_runtime
		: > "$JOBS_DIR/forkop-svc.out"
		_fk_start_once || echo "!! Повторный запуск завершился с ошибкой"
		_fk_svc_report
		_fk_ready || _fk_wait_up 90
	fi
	rm -f "$JOBS_DIR/forkop-svc.out"
	if _fk_up; then
		_fk_say "Проверяем, что всё работает"
		_fk_check_live
		_fk_sub_wait 90
		_fk_ext_auto all "$lx"
		_fk_lists_wait 240 || _rb_warn "Списки ещё скачиваются — числа ниже могут быть неполными. Они догрузятся сами; позже нажмите «Обновить списки сейчас», чтобы увидеть итог"
		_fk_lists_report
		_fk_lists_errors
		_fk_sb_settle 60
		_fk_rs_check; b=$?
		if [ "$b" = 0 ]; then
			_fk_say "Перезапускаем Forkozz с новой настройкой"
			_fk_log_mark
			_fk_reset_runtime
			: > "$JOBS_DIR/forkop-svc.out"
			_fk_start_once || echo "!! Запуск завершился с ошибкой"
			_fk_svc_report
			rm -f "$JOBS_DIR/forkop-svc.out"
			_fk_ready || _fk_wait_up 90
			_fk_sb_settle 90
			_fk_rs_check; b=$?
			if [ "$b" = 1 ] && _fk_up; then
				echo "   ✓ sing-box запустился — наборы правил скачались через VPN"
				_fk_lists_wait 240 || _rb_warn "Списки ещё скачиваются — они догрузятся сами"
				_fk_lists_errors
			fi
		fi
		if [ "$b" != 1 ] || ! _fk_up; then
			echo "ОШИБКА: Forkozz не работает — sing-box не запустился. Если GitHub у провайдера не открывается, проверьте сервер подключения и включите «Авто» в Система → Доступ к GitHub."
			_zm_reboot_hint "Forkozz не запустился: sing-box не смог скачать наборы правил с GitHub."
			return 1
		fi
		_fk_clash_ok || echo "!! sing-box пока не отвечает — он ещё запускается; если так и останется, нажмите «Перезапустить»"
		_fk_servers_report
		_fk_rl_report
		if [ -s /tmp/zm-fk-rlalt.json ]; then
			_fk_say "Проверяем новые серверы REALITY с ключом X25519MLKEM768 и без"
			_fk_rl_learn_run '{"max":60}'
		fi
		_ab_free_sync >/dev/null 2>&1
		_fk_zash_ensure
		local ps
		for ps in $(_fk_uc secnames 2>/dev/null); do
			[ "$(uci -q get netshift."$ps".zm_sub_priority)" = 1 ] && _fk_fallback_sec "$ps" >/dev/null 2>&1 &
		done
		_fk_fwd_sync
		_fk_say "Готово: Forkozz работает"
		_fk_guard
		grep -q '^Forkozz не запустился' "$ZM_REBOOT_HINT" 2>/dev/null && rm -f "$ZM_REBOOT_HINT"
		return 0
	fi
	[ -n "$(_fk_rs_fatal)" ] && _fk_rs_check
	b="$(_fk_why)"
	echo "ОШИБКА: Forkozz не запустился${b:+: $b}. Если ошибка повторяется, перезагрузите роутер — это сбросит всё, что осталось от прошлых запусков."
	_zm_reboot_hint "Forkozz не запустился. Перезагрузите роутер — это сбросит всё, что осталось от прошлых запусков, — и включите Forkozz снова."
	echo "Последние записи журнала:"
	logread 2>/dev/null | { if [ -n "$FK_LOGMARK" ]; then awk -v m="$FK_LOGMARK" 'f { print } index($0, m) { f = 1 }'; else cat; fi; } |
		grep -E 'netshift|sing-box' | grep -v 'DEBUG\|\[debug\]\|udhcpc\|is deprecated\|deprecated in sing-box' |
		sed 's/\x1b\[[0-9;]*m//g; s/\[[0-9;]*m//g' | tail -n 10 | sed 's/^[^]]*\]: //; s/^/   /'
	return 1
}

do_fk_lists() {
	local rc=0 out="$JOBS_DIR/forkop-lists.out"
	_fk_installed || { echo "ОШИБКА: Forkozz не установлен"; return 1; }
	_fk_settle 180 "Forkozz ещё заканчивает запуск или применение подписки — ждём, затем обновим списки" || true
	_fk_up || { echo "ОШИБКА: Forkozz выключен — включите его, и списки скачаются сами"; return 1; }
	local lp
	_fk_fast_patch
	_fk_mlkem_patch
	_fk_serial_patch
	_fk_listsvia_patch
	_fk_subvia_patch
	_fk_reality_patch
	_fk_rsinit_patch
	_fk_desync_patch
	_fk_fakeip_patch
	_fk_ghdl_patch
	_fk_subck_patch
	_fk_log_mark
	/usr/bin/netshift list_update > "$out" 2>&1 &
	lp=$!
	if ! _fk_lists_wait 300 "$lp"; then
		_zm_kill_tree "$lp"
		_rb_warn "Загрузка списков не завершилась за 5 минут — прерываем её"
		rc=1
	fi
	wait "$lp" 2>/dev/null || rc=1
	[ "$rc" = 0 ] || sed 's/\x1b\[[0-9;]*m//g' "$out" 2>/dev/null | grep -v '^[[:space:]]*$' | grep -iE 'error|fail|ошиб' | grep -v '^jq: ' | grep -vE '\[[0-9]+/[0-9]+\]' | tail -n 8 | sed 's/^/   /'
	rm -f "$out"
	if [ "$rc" != 0 ]; then
		echo "!! Скачивание списков завершилось с ошибкой — работают прежние"
	else
		echo "   ✓ Загрузка списков закончилась — sing-box подхватит новые сам"
	fi
	_fk_say "Проверяем, что списки на месте и работают"
	_fk_check_live
	_fk_lists_report
	_fk_lists_errors
	_fk_up || { echo "ОШИБКА: после обновления списков Forkozz не работает — нажмите «Перезапустить»"; return 1; }
	_fk_say "Готово: списки обновлены"
}

_fk_sub_keys() {
	jq -r '
		def ap($a; $p): if $a == null or $p == null then empty else "\($a):\($p)" end;
		if type == "object" and (.outbounds | type) == "array" and ((.outbounds[0].protocol // null) == null) then
			[.outbounds[] | select(.type == "vless" or .type == "trojan" or .type == "shadowsocks" or .type == "hysteria2" or .type == "vmess" or .type == "tuic" or .type == "anytls")
				| "\(.type)|" + ap(.server; .server_port)] | unique | .[]
		else
			[(if type == "array" then .[] else . end) | .outbounds[]? | select(type == "object")
				| select(.protocol == "vless" or .protocol == "trojan" or .protocol == "shadowsocks" or .protocol == "hysteria")
				| select((.streamSettings.sockopt.dialerProxy // "") == "")
				| select(.protocol != "hysteria" or ((.streamSettings.hysteriaSettings.version // 0) == 2))
				| (.settings // {}) as $s | ($s.vnext[0] // $s.servers[0] // $s) as $x
				| (if .protocol == "hysteria" then "hysteria2" else .protocol end) + "|" + ap($x.address; $x.port)] | unique | .[]
		end' 2>/dev/null
}

_fk_sub_fmt_name() { case "$1" in xray) echo "Happ" ;; singbox) echo "sing-box" ;; *) echo "Авто" ;; esac; }

_fk_sub_fmt_auto() {
	local sec url key ver ch="" sw="" d="$JOBS_DIR/fk-subfmt" n_sb n_xr miss xex lost extra pref was man cust name
	command -v jq >/dev/null 2>&1 || return 1
	ver="$(sing-box version 2>/dev/null | head -n1 | awk '{print $3}')"
	for sec in $(uci -q show netshift | sed -n "s/^netshift\.\([A-Za-z0-9_]*\)\.subscription_url=.*/\1/p" | sort -u); do
		[ "$(uci -q get "netshift.$sec.proxy_config_type")" = subscription ] || continue
		url="$(uci -q get "netshift.$sec.subscription_url")"
		key="$(printf '%s' "$url" | md5sum | cut -c1-16)"
		pref="$(uci -q get "netshift.$sec.subscription_format_preference")"; was="${pref:-auto}"
		man="$(uci -q get "netshift.$sec.zm_subfmt_man")"
		cust="$(uci -q get "netshift.$sec.subscription_user_agent")$(uci -q get "netshift.$sec.subscription_hwid")$(uci -q get "netshift.$sec.subscription_device_os")"
		name="$(uci -q get "netshift.$sec.zm_label" || echo "$sec")"
		if [ "$(uci -q get "netshift.$sec.zm_subfmt_url")" = "$key" ]; then
			[ "$pref" = xray ] && [ "$man" != "$url" ] && [ -z "$cust" ] && [ "$(uci -q get "netshift.$sec.zm_subfmt_chk")" != "$key" ] || continue
			case "$url" in http://*|https://*) ;; *) continue ;; esac
			case "$url" in *' '*) continue ;; esac
			_fk_say "Подписка «$name»: проверяем, отдаёт ли сервер её в формате Happ"
			rm -rf "$d"; mkdir -p "$d"; : > "$d/sb"; : > "$d/xr"
			curl -fsSL --compressed -m 15 -b "" --max-redirs 10 -A "singbox/${ver:-1.12.0}" -o "$d/sb" "$url" 2>/dev/null
			curl -fsSL --compressed -m 15 -b "" --max-redirs 10 -A "Happ/1.0.0" -o "$d/xr" "$url" 2>/dev/null
			n_sb="$(_fk_sub_keys < "$d/sb" | sort -u | grep -c .)"; n_xr="$(_fk_sub_keys < "$d/xr" | sort -u | grep -c .)"
			rm -rf "$d"
			if [ "$n_sb" = 0 ] && [ "$n_xr" = 0 ]; then echo "   · подписка не скачалась напрямую — проверим в следующий раз"; continue; fi
			uci set "netshift.$sec.zm_subfmt_chk=$key"; ch=1
			if [ "$n_xr" = 0 ]; then
				uci -q delete "netshift.$sec.subscription_format_preference"; uci -q delete "netshift.$sec.zm_subfmt_man"; sw=1
				echo "   ! в формате Happ сервер подписку не отдаёт, а в sing-box — $n_sb серверов: формат переключён на «Авто»"
				logger -t zapret-manager "Forkozz: подписка секции $sec не отдаётся в формате Happ — формат переключён на «Авто»"
			else
				echo "   ✓ формат Happ подходит: в нём $n_xr серверов"
			fi
			continue
		fi
		if [ -n "$pref" ] && [ "$pref" != auto ] && [ "$man" != "$url" ] && [ -z "$cust" ] && [ -n "$(uci -q get "netshift.$sec.zm_subfmt_url")" ]; then
			_fk_say "Подписка «$name» сменилась: формат «$(_fk_sub_fmt_name "$pref")» остался от прежней — определяем заново"
			uci -q delete "netshift.$sec.subscription_format_preference"; uci -q delete "netshift.$sec.zm_subfmt_man"; uci -q delete "netshift.$sec.zm_subfmt_chk"
			pref=""; ch=1; sw=1
		fi
		if [ "$(cat "$ZM_STATE_DIR/fk.subfmt.$sec" 2>/dev/null)" = "$key" ] || { [ -n "$pref" ] && [ "$pref" != auto ]; } || [ -n "$cust" ]; then
			uci set "netshift.$sec.zm_subfmt_url=$key"; uci -q delete "netshift.$sec.zm_subfmt_auto"
			rm -f "$ZM_STATE_DIR/fk.subfmt.$sec"; ch=1
			continue
		fi
		case "$url" in *' '*|'') continue ;; esac
		case "$url" in http://*|https://*) ;; *) continue ;; esac
		_fk_say "Новая подписка «$(uci -q get "netshift.$sec.zm_label" || echo "$sec")»: определяем формат — сравниваем, что сервер отдаёт в форматах sing-box и Happ"
		rm -rf "$d"; mkdir -p "$d"; : > "$d/sb"; : > "$d/xr"
		curl -fsSL --compressed -m 15 -b "" --max-redirs 10 -A "singbox/${ver:-1.12.0}" -o "$d/sb" "$url" 2>/dev/null
		curl -fsSL --compressed -m 15 -b "" --max-redirs 10 -A "Happ/1.0.0" -o "$d/xr" "$url" 2>/dev/null
		_fk_sub_keys < "$d/sb" | sort -u > "$d/sb.k"; _fk_sub_keys < "$d/xr" | sort -u > "$d/xr.k"
		n_sb="$(grep -c . "$d/sb.k")"; n_xr="$(grep -c . "$d/xr.k")"
		if [ "$n_sb" = 0 ] && [ "$n_xr" = 0 ]; then echo "   · подписка не скачалась напрямую — формат определим в следующий раз, пока «Авто»"; rm -rf "$d"; continue; fi
		uci set "netshift.$sec.zm_subfmt_url=$key"; ch=1
		miss="$(grep -vxF -f "$d/xr.k" "$d/sb.k" | grep -c .)"; [ -s "$d/xr.k" ] || miss="$n_sb"
		xex="$(grep -vxF -f "$d/sb.k" "$d/xr.k" | grep -c .)"; [ -s "$d/sb.k" ] || xex="$n_xr"
		if [ "$n_xr" -gt 0 ] && [ "$xex" -gt 0 ] && { [ "$miss" = 0 ] || [ "$n_xr" -gt "$n_sb" ]; }; then
			extra="$(grep -vxF -f "$d/sb.k" "$d/xr.k" | cut -d'|' -f1 | sort -u | tr '\n' ' ' | sed 's/ $//')"
			lost=""; [ "$miss" = 0 ] || lost="$(grep -vxF -f "$d/xr.k" "$d/sb.k" | cut -d'|' -f1 | sort -u | tr '\n' ' ' | sed 's/ $//')"
			uci set "netshift.$sec.subscription_format_preference=xray"; uci set "netshift.$sec.zm_subfmt_chk=$key"; sw=1
			echo "   ✓ в формате Happ серверов больше ($n_xr против $n_sb${extra:+, в том числе $extra}) — подписке поставлен формат Happ"
			[ -n "$lost" ] && echo "   ! в формате Happ нет $miss серверов из формата sing-box ($lost)"
			logger -t zapret-manager "Forkozz: новой подписке секции $sec поставлен формат Happ ($n_xr серверов против $n_sb)"
		elif [ "$n_xr" = 0 ]; then echo "   ✓ формат «Авто» (sing-box): в формате Happ сервер подписку не отдал"
		elif [ "$xex" = 0 ]; then echo "   ✓ формат «Авто» (sing-box): в Happ нет серверов, которых нет в нём ($n_sb)"
		elif [ "$n_sb" = "$n_xr" ]; then echo "   ✓ формат «Авто» (sing-box): серверов столько же ($n_sb), но $xex есть только в Happ, а $miss — только в sing-box. Нужны именно они — выберите Happ вручную"
		else echo "   ✓ формат «Авто» (sing-box): в нём серверов больше ($n_sb против $n_xr), хотя $xex есть только в Happ. Нужны именно они — выберите Happ вручную"; fi
		echo "   · формат запомнен для этой подписки — поменять можно вручную в её настройках; для другой подписки панель определит формат заново"
		rm -rf "$d"
	done
	[ -n "$ch" ] || return 1
	uci commit netshift
	[ -n "$sw" ]
}

_fk_sub_update() {
	local p m="zm-sub-$$-$(date +%s)" seen=0 tot all i=0 rc=0 out="$JOBS_DIR/fk-sub.out"
	mkdir -p "$JOBS_DIR"
	logger -t netshift "[info] $m" 2>/dev/null
	/usr/bin/netshift subscription_update all > "$out" 2>&1 &
	p=$!
	while kill -0 "$p" 2>/dev/null; do
		sleep 2; i=$((i + 2))
		if [ "$i" -ge 600 ]; then _zm_kill_tree "$p"; echo "!! Подписка не обновилась за 10 минут — прерываем"; rm -f "$out"; return 1; fi
		all="$(logread 2>/dev/null | awk -v m="$m" 'f && /netshift/ { print } index($0, m) { f = 1 }')"
		tot="$(printf '%s\n' "$all" | grep -c .)"
		[ "$tot" -gt "$seen" ] || continue
		printf '%s\n' "$all" | awk -v skip="$seen" -v fast="$([ -f /usr/lib/netshift/linkfast.jq ] && echo 1)" '
			NR <= skip { next }
			{ sub(/^.*netshift[^:]*: /, ""); sub(/^\[[a-z]+\] /, "") }
			/Updating subscription feed for section/ { if ($0 ~ /via service proxy/) { v = 1; print "   → Качаем подписку через VPN" } else { v = 0; print "   → Качаем подписку напрямую" }; next }
			/updating the subscription directly this time/ { v = 0; print "   → Качаем подписку напрямую"; next }
			/Subscription connectivity check passed/ { print "   ✓ Сервер подписки отвечает"; next }
			/Subscription connectivity check failed/ { print (v ? "   ✗ Через VPN сервер подписки не отвечает" : "   ✗ Сервер подписки не отвечает"); next }
			/Trying subscription User-Agent/ { u = $0; sub(/^.*: /, "", u); f = (u ~ /^[Hh]app|^v2ray/) ? "Happ" : (u ~ /^sing-?box/) ? "sing-box" : u; print "   → Просим подписку в формате " f; next }
			/Downloaded subscription body/ { b = $0; sub(/^.*bytes=/, "", b); sub(/[^0-9].*$/, "", b); if (b + 0 > 0) printf "   ✓ Скачано %d КБ\n", (b + 1023) / 1024; next }
			/Detected Xray JSON subscription/ { print (fast ? "   → Формат Happ: разбираем серверы" : "   → Формат Happ: движок Forkozz разбирает серверы по одному — на роутере это минута-две, дождитесь"); next }
			/produced [0-9]+ outbound/ { n = $0; sub(/^.*produced /, "", n); sub(/ .*$/, "", n); print "   ✓ Разобрано серверов: " n; next }
			/needs cookies, downloaded with curl/ { print "   ✓ Сервер подписки проверяет cookie — подписка скачана через curl"; next }
			/Subscription download failed/ { print "   ! Подписка не скачалась — пробуем другой формат"; next }
			/Applying updated subscriptions/ { print "   → Применяем новые серверы в sing-box"; next }
			/is unchanged/ && /Subscription for section/ { if (!u1++) print "   ✓ Подписка не изменилась"; next }
			/Subscription feed updated for section/ { n = $0; sub(/^.*: /, "", n); sub(/ outbounds.*$/, "", n); print "   ✓ Подписка обновлена: серверов " n; next }
			/Failed to update any subscription feed/ { print "   ✗ Подписка не обновилась"; next }'
		seen="$tot"
	done
	wait "$p" 2>/dev/null || rc=1
	[ "$rc" = 0 ] || sed 's/\x1b\[[0-9;]*m//g' "$out" 2>/dev/null | grep -iE 'error|fail|❌' | tail -n 5 | sed 's/^/   /'
	rm -f "$out"
	return $rc
}

do_fk_subs() {
	_fk_installed || { echo "ОШИБКА: Forkozz не установлен"; return 1; }
	_fk_say "Обновляем подписки"
	_fk_sub_fmt_auto
	local lx; lx="$(_fk_log_ext)"
	_fk_mlkem_patch
	_fk_serial_patch
	_fk_listsvia_patch
	_fk_subvia_patch
	_fk_reality_patch
	_fk_rsinit_patch
	_fk_desync_patch
	_fk_fakeip_patch
	_fk_ghdl_patch
	_fk_subck_patch
	_fk_sub_update || { echo "ОШИБКА: подписка не обновилась — проверьте ссылку"; return 1; }
	_fk_ext_auto all "$lx"
	_fk_say "Готово: подписки обновлены"
}

FK_EXT_FAIL="$ZM_STATE_DIR/fk.ext.fail"
FK_NAIVE_FAIL="$ZM_STATE_DIR/fk.naive.fail"
_fk_sb_is_ext() { sing-box version 2>/dev/null | head -n1 | grep -qi extended; }
_fk_log_ext() { logread 2>/dev/null | grep -ci 'requires sing-box-extended'; }
_fk_log_default() {
	[ -s /etc/config/netshift ] || return 0
	[ "$(uci -q get netshift.settings.zm_log)" = 1 ] && return 0
	uci -q get netshift.settings >/dev/null || return 0
	uci -q set netshift.settings.log_level='panic'
	uci -q set netshift.settings.zm_log='1'
	uci -q commit netshift
}
_fk_ext_why() {
	local f var="${3:-$(_fk_sb_var)}"
	grep -Eqi "[?&](type|transport)=(xhttp|splithttp)|'vmess://" /etc/config/netshift 2>/dev/null && { echo "среди серверов есть XHTTP или VMess"; return 0; }
	_fk_mlkem_why "$1" && return 0
	[ "$1" = config ] && return 1
	for f in $(_fk_sub_cache_files); do
		[ -s "$f" ] || continue
		grep -Eqi '"type"[[:space:]]*:[[:space:]]*"(xhttp|splithttp)"' "$f" && { echo "в подписке есть серверы XHTTP"; return 0; }
		grep -Eqi '"type"[[:space:]]*:[[:space:]]*"vmess"' "$f" && { echo "в подписке есть серверы VMess"; return 0; }
		[ "$var" = tiny ] && grep -Eqi '"type"[[:space:]]*:[[:space:]]*"wireguard"' "$f" && { echo "в подписке есть серверы WireGuard"; return 0; }
	done
	[ -n "$2" ] && [ "$(_fk_log_ext)" -gt "$2" ] 2>/dev/null && { echo "в подписке есть серверы, которые работают только на расширенном sing-box"; return 0; }
	return 1
}
_fk_ext_need() {
	if [ -n "$(_fk_sb_ver)" ] && _fk_sb_is_ext; then
		_fk_mlkem_core_ok && return 1
		_fk_mlkem_why "$1"
		return
	fi
	_fk_ext_why "$1" "$2"
}
_fk_ext_auto() {
	local why rc
	why="$(_fk_ext_need "$1" "$2")" || return 0
	if [ -f "$FK_EXT_FAIL" ] && [ -z "$(find "$FK_EXT_FAIL" -mmin +720 2>/dev/null)" ]; then
		_rb_warn "${why}, а расширенный облегчённый sing-box поставить не удалось — такие серверы пока пропускаются"
		return 0
	fi
	if ! _fk_lite_arch >/dev/null; then
		_rb_warn "${why}, а расширенного облегчённого sing-box для этого роутера ($TG_ARCH) нет — такие серверы пропускаются"
		return 0
	fi
	if ! _fk_lite_engine; then
		_rb_warn "${why} — их умеет только расширенный облегчённый sing-box, а этот движок Forkozz ($(_fk_version)) его не ставит. Обновите Forkozz"
		return 0
	fi
	_fk_say "${why} — нынешний sing-box их не умеет, ставим расширенный облегчённый"
	ZM_FK_SB_NESTED=1
	do_fk_singbox lite "$3"; rc=$?
	ZM_FK_SB_NESTED=""
	if [ "$rc" = 0 ]; then rm -f "$FK_EXT_FAIL"
	else mkdir -p "$ZM_STATE_DIR"; touch "$FK_EXT_FAIL"; _rb_warn "Расширенный облегчённый sing-box не встал — Forkozz работает на прежнем, такие серверы пропускаются"; fi
	return 0
}

_fk_sbext_say() {
	local m="$1" h a
	case "$m" in
		*"pre-flight: DNS resolve of "*" ok"*) h="${m#*resolve of }"; echo "   ✓ Адрес ${h% ok} найден" ;;
		*"pre-flight: DNS resolve of "*"FAILED"*) h="${m#*resolve of }"; echo "   ! Адрес ${h% FAILED} не находится" ;;
		*"pre-flight: HTTPS reachability of "*" ok"*) h="${m#*reachability of }"; echo "   ✓ ${h%% *} отвечает" ;;
		*"pre-flight: HTTPS reachability of "*"FAILED"*) h="${m#*reachability of }"; echo "   ! ${h%% *} не отвечает" ;;
		*"is not reachable via the service proxy"*) h="${m#*pre-flight: }"; echo "   ! ${h%% *} не отвечает через VPN — пробуем напрямую" ;;
		*"attempting self-heal"*) echo "   → Нет доступа к GitHub — временно чиним DNS и выход в интернет" ;;
		*"Self-heal: connectivity restored"*) echo "   ✓ Доступ к GitHub есть" ;;
		*"Self-heal: keeping the NetShift redirect up"*) echo "   · Скачиваем через VPN Forkozz" ;;
		*"Self-heal: connectivity could NOT be restored"*) echo "   ✗ Доступ к GitHub восстановить не удалось" ;;
		*"Downloading sing-box extended lite "*) h="${m#*Downloading sing-box extended lite }"; a="${h#* }"; a="${a#(}"; a="${a%)}"
			case "$a" in compressed,*) a="сжатая сборка (UPX), ${a#*, }" ;; elf,*) a="обычная сборка, ${a#*, }" ;; esac
			echo "   → Скачиваем sing-box-extended-lite ${h%% *} — $a" ;;
		*"sha256 mismatch"*) echo "   ✗ Архив скачался повреждённым (не сошлась контрольная сумма) — ничего не меняли" ;;
		*"Extended Lite is not available"*) echo "   ✗ Для этого роутера нет облегчённой сборки" ;;
		*"Installed sing-box extended lite"*) ;;
		*"Downloading sing-box-extended "*) h="${m#*Downloading sing-box-extended }"; a="${h#* }"; a="${a#(}"; echo "   → Скачиваем sing-box-extended ${h%% *} для ${a%)}" ;;
		*"Download via the service proxy"*) echo "   ! Через VPN не скачалось — качаем напрямую" ;;
		*"Found a non-runnable /usr/bin/sing-box"*) echo "   · Убираем недоустановленный sing-box" ;;
		*"Restarting netshift after component change"*) echo "   → Новое ядро на месте — движок перезапускает Forkozz на нём" ;;
		*"Restore: "*) [ -n "$ZM_SBX_RESTORE" ] || { ZM_SBX_RESTORE=1; echo "   · Возвращаем временные настройки DNS как было"; } ;;
		*"Installed sing-box-extended"*) ;;
		*"[error]"*|*"[fatal]"*) echo "   ✗ ${m#*Updater: }" ;;
		*"[warn]"*) echo "   ! ${m#*Updater: }" ;;
	esac
}
_fk_sbext_run() {
	local out="$1" p seen="$JOBS_DIR/fk-sbx.seen" new="$JOBS_DIR/fk-sbx.new" t=0 a sz=0 last=0 still=0 unp=0 dl=0 nolog=0 rs=0 l
	local act=install_extended tg="/tmp/netshift-sbext.*/sing-box-extended.tar.gz" td="/tmp/netshift-sbext.*" nm=sing-box-extended
	[ "$2" = lite ] && { act=install_extended_lite; tg="/tmp/netshift-sblite.*/sing-box-extended-lite.tar.gz"; td="/tmp/netshift-sblite.*"; nm=sing-box-extended-lite; }
	ZM_SBX_RESTORE=""
	logread 2>/dev/null | grep 'Updater: ' > "$seen"
	/usr/bin/netshift component_action sing_box "$act" > "$out" 2>/dev/null &
	p=$!
	while kill -0 "$p" 2>/dev/null; do
		sleep 2; t=$((t + 2))
		if [ "$t" -ge 900 ]; then
			_zm_kill_tree "$p"
			echo "!! Движок не закончил установку за 15 минут — прерываем"
			break
		fi
		logread 2>/dev/null | grep 'Updater: ' | grep -vxF -f "$seen" > "$new"
		if [ -s "$new" ]; then
			while IFS= read -r l; do
				case "$l" in
					*"Downloading sing-box-extended"*|*"Downloading sing-box extended lite"*) dl=1 ;;
					*"Restarting netshift"*) unp=1; [ "$rs" = 1 ] && continue; rs=1; [ -n "$ZM_FK_SB_FRESH" ] && continue ;;
				esac
				_fk_sbext_say "$l"
			done < "$new"
			cat "$new" >> "$seen"
		fi
		a="$(ls -l $tg 2>/dev/null | awk '{ print int($5 / 1048576); exit }')"
		if [ -n "$a" ] && [ "$dl" = 0 ]; then
			nolog=$((nolog + 1))
			if [ "$nolog" -ge 2 ]; then dl=1; echo "   → Скачиваем $nm"; else a=""; fi
		fi
		if [ -n "$a" ]; then
			if [ "$a" -gt "$sz" ]; then
				sz="$a"; still=0
				[ "$((sz - last))" -ge 5 ] && { last="$sz"; echo "   · Скачано $sz МБ"; }
			elif [ "$dl" = 1 ] && [ "$unp" = 0 ] && [ "$sz" -gt 0 ]; then
				still=$((still + 1))
				[ "$still" = 2 ] && { unp=1; echo "   ✓ Архив скачан ($sz МБ) — распаковываем и проверяем новое ядро"; }
			fi
		fi
		if [ "$unp" = 1 ] && [ "$rs" = 0 ] && ! ls -d $td >/dev/null 2>&1; then
			rs=1; [ -n "$ZM_FK_SB_FRESH" ] || echo "   → Новое ядро на месте — движок перезапускает Forkozz на нём"
		fi
	done
	wait "$p" 2>/dev/null
	logread 2>/dev/null | grep 'Updater: ' | grep -vxF -f "$seen" | while IFS= read -r l; do _fk_sbext_say "$l"; done
	rm -f "$seen" "$new"
}

do_fk_singbox() {
	local want="$1" norestart="$2" free tfree have need tneed out="$JOBS_DIR/forkop-sb.json" old oldvar msg why same=0 verb
	_fk_installed || { echo "ОШИБКА: Forkozz не установлен"; return 1; }
	rm -f /tmp/zm-fk-rlcore
	case "$want" in
		tiny|stable|lite) ;;
		extended) echo "ОШИБКА: сборку sing-box-extended панель больше не ставит — выберите «Расширенный облегчённый»: те же протоколы, а места нужно в 3 раза меньше"; return 1 ;;
		*) echo "ОШИБКА: неизвестный вариант sing-box"; return 1 ;;
	esac
	if [ "$want" = lite ]; then
		_fk_lite_arch >/dev/null || { echo "ОШИБКА: для этого роутера ($TG_ARCH) нет облегчённой сборки — она выходит для amd64, arm64, armv7, mips и mipsel. Выберите «Расширенный»"; return 1; }
		_fk_lite_engine || { echo "ОШИБКА: этот движок Forkozz ($(_fk_version)) ещё не умеет ставить облегчённый расширенный sing-box — обновите Forkozz"; return 1; }
	fi
	old="$(_fk_sb_ver)"; oldvar="$(_fk_sb_var)"
	if [ "$want" != lite ] && why="$(_fk_ext_why all "" "$want")"; then
		echo "ОШИБКА: ${why} — такие серверы работают только на расширенном облегчённом sing-box, а Forkozz при следующем запуске сам вернул бы его. Чтобы сменить вариант, сначала уберите их в «Подключении»"
		return 1
	fi
	[ -n "$old" ] && [ "$oldvar" = "$want" ] && same=1
	if [ "$same" = 1 ]; then verb="Переустанавливаем"; elif [ -n "$old" ]; then verb="Меняем"; else verb="Ставим"; fi
	_fk_say "$verb sing-box: $([ -n "$old" ] && [ "$same" = 0 ] && echo "$old ($(_fk_sb_name "$oldvar")) → ")$(_fk_sb_name "$want")"
	free="$(df -k /overlay 2>/dev/null | awk 'NR==2 {print $4}')"
	[ -n "$free" ] || free="$(df -k / 2>/dev/null | awk 'NR==2 {print $4}')"
	have="$(ls -l /usr/bin/sing-box 2>/dev/null | awk '{print int($5 / 1024)}')"
	tfree="$(df -k /tmp 2>/dev/null | awk 'NR==2 {print $4}')"
	case "$want" in
		lite) need=12288; tneed=$((18432 + ${have:-0})) ;;
		*) need=16384; tneed=12288 ;;
	esac
	if [ -n "$free" ] && [ $((free + ${have:-0})) -lt "$need" ]; then
		echo "ОШИБКА: мало места на флеше для этого sing-box: свободно $(((free + ${have:-0}) / 1024)) МБ, нужно около $((need / 1024)) МБ"
		return 1
	fi
	if [ -n "$tfree" ] && [ "$tfree" -lt "$tneed" ]; then
		echo "ОШИБКА: мало оперативной памяти для загрузки: свободно $((tfree / 1024)) МБ, нужно около $((tneed / 1024)) МБ"
		return 1
	fi
	echo "   ✓ Места хватает: флеш $(((free + ${have:-0}) / 1024)) МБ, /tmp $((tfree / 1024)) МБ${old:+. Если новый не встанет, останется прежний $old}"
	case "$want" in
		lite)
			_zm_net_prepare api.github.com github.com objects.githubusercontent.com || return 1
			_fk_say "Скачиваем расширенный облегчённый sing-box с GitHub (github.com/$FK_SBL_REPO) — около 10–17 МБ"
			_fk_sbext_run "$out" lite
			if [ "$(jsonfilter -i "$out" -e '@.success' 2>/dev/null)" != true ] || [ "$(_fk_sb_var)" != lite ]; then
				msg="$(jsonfilter -i "$out" -e '@.message' 2>/dev/null)"
				echo "ОШИБКА: расширенный облегчённый sing-box не встал${msg:+: $msg}"
				[ -n "$old" ] && [ "$(_fk_sb_ver)" = "$old" ] && echo "   ✓ Прежний sing-box $old на месте — Forkozz работает как раньше"
				rm -f "$out"
				return 1
			fi
			case "$(jsonfilter -i "$out" -e '@.build' 2>/dev/null)" in
				compressed) echo "   ✓ Расширенный облегчённый sing-box $(_fk_sb_ver) поставлен — сжатая сборка (UPX), на флеше около 10 МБ" ;;
				*) echo "   ✓ Расширенный облегчённый sing-box $(_fk_sb_ver) поставлен" ;;
			esac
			[ "$(jsonfilter -i "$out" -e '@.warning' 2>/dev/null)" = upx_ram_spike ] && _rb_warn "Памяти у роутера меньше 256 МБ: сжатая сборка при каждом запуске ненадолго занимает 35–45 МБ — если Forkozz будет падать, выберите «Облегчённый»"
			rm -f "$out"
			if [ -n "$ZM_FK_SB_FRESH" ]; then _fk_settle 180 "Движок заканчивает установку ядра — ждём" || _rb_warn "Движок долго заканчивает установку — продолжаем"
			else _fk_settle 180 "Движок перезапускает Forkozz на новом ядре — ждём, это до пары минут" || _rb_warn "Перезапуск Forkozz затянулся — продолжаем"; fi
			_fk_sb_drop_pkgs ;;
		*)
			_zm_net_prepare "$(_zm_feed_host)" || return 1
			_fk_say "Обновляем список пакетов"
			if $UPDATE >/dev/null 2>&1; then echo "   ✓ Список пакетов обновлён"; else echo "   ! Список пакетов не обновился — пробуем с прежним"; fi
			_fk_sb_pkg_switch "$want" || {
				echo "ОШИБКА: $(_fk_sb_name "$want") sing-box не встал$([ "$want" = tiny ] && echo " — возможно, для этого роутера его нет в репозитории OpenWrt; выберите «Обычный»")"
				[ -n "$old" ] && [ "$(_fk_sb_ver)" = "$old" ] && echo "   ✓ Прежний sing-box $old на месте — Forkozz работает как раньше"
				return 1
			} ;;
	esac
	_fk_sb_pkg > "$FK_SB_OWN" || echo "sing-box" > "$FK_SB_OWN"
	echo "   ✓ $([ "$same" = 1 ] && echo Переустановлен || echo Установлен) sing-box $(_fk_sb_ver) ($(_fk_sb_name "$(_fk_sb_var)"))"
	if [ "$norestart" != norestart ] && _fk_enabled; then
		_fk_say "Перезапускаем Forkozz на $([ "$same" = 1 ] && echo переустановленном || echo новом) sing-box"
		_zm_run 90 /etc/init.d/netshift stop >/dev/null 2>&1
		: > "$JOBS_DIR/forkop-svc.out"
		_fk_start_once
		_fk_svc_report
		rm -f "$JOBS_DIR/forkop-svc.out"
		_fk_wait_up 90
		if ! _fk_up; then
			msg="$(_fk_why)"
			echo "ОШИБКА: Forkozz не запустился на этом sing-box${msg:+: $msg}. Выберите другой вариант в «Настройках» → sing-box"
			return 1
		fi
		_fk_check_live
	fi
	[ -n "$ZM_FK_SB_NESTED" ] && return 0
	_fk_say "Готово: sing-box $(_fk_sb_ver), $(_fk_sb_name "$(_fk_sb_var)")"
}
FK_DNS_Q="AAABAAABAAAAAAAAB2V4YW1wbGUDY29tAAABAAE"

_fk_dns_ms() { awk -v t="$1" 'BEGIN { if (t == "" || t + 0 <= 0) print 0; else printf "%d\n", t * 1000 + 0.5 }'; }

_fk_dns_probe() {
	local t="$1" v="$2" out="$3" f="$3.body" host port url code tm res ms="" ok=0 how=""
	case "$t" in
		udp)
			host="${v%:*}"; port="${v##*:}"; [ "$host" = "$v" ] && port=53
			res="$(dig @"$host" -p "$port" example.com A +time=3 +tries=1 2>&1)"
			echo "$res" | grep -q 'status: NOERROR' && { ok=1; ms="$(echo "$res" | sed -n 's/.*Query time: \([0-9]*\) msec.*/\1/p' | head -n1)"; }
			how=udp ;;
		dot)
			host="${v%:*}"; port="${v##*:}"; [ "$host" = "$v" ] && port=853
			res="$(dig +tls @"$host" -p "$port" example.com A +time=4 +tries=1 2>&1)"
			if echo "$res" | grep -q 'status: NOERROR'; then
				ok=1; ms="$(echo "$res" | sed -n 's/.*Query time: \([0-9]*\) msec.*/\1/p' | head -n1)"; how=dot
			else
				res="$(curl -sk -o /dev/null -w '%{time_appconnect}' --connect-timeout 4 --max-time 5 "https://$host:$port/" 2>/dev/null)"
				tm="$(_fk_dns_ms "$res")"
				[ "$tm" -gt 0 ] 2>/dev/null && { ok=1; ms="$tm"; how=tls; }
			fi ;;
		doh)
			case "$v" in
				https://*) url="$v"; case "${url#https://}" in */*) ;; *) url="$url/dns-query" ;; esac ;;
				*/*) url="https://$v" ;;
				*) url="https://$v/dns-query" ;;
			esac
			case "$url" in *\?*) url="$url&dns=$FK_DNS_Q" ;; *) url="$url?dns=$FK_DNS_Q" ;; esac
			res="$(curl -s -o "$f" -w '%{http_code} %{time_total}' -H 'accept: application/dns-message' --connect-timeout 4 --max-time 6 "$url" 2>/dev/null)"
			code="${res%% *}"; tm="${res##* }"
			if [ "$code" = 200 ] && [ "$(wc -c < "$f" 2>/dev/null || echo 0)" -ge 29 ]; then ok=1; ms="$(_fk_dns_ms "$tm")"; fi
			rm -f "$f"; how=doh ;;
	esac
	[ "$ok" = 1 ] && [ "${ms:-0}" -lt 1 ] 2>/dev/null && ms=1
	printf '%s|%s|%s|%s\n' "$v" "$ok" "${ms:-0}" "$how" > "$out"
}

_fk_doh_url() {
	local url
	case "$1" in
		https://*) url="$1"; case "${url#https://}" in */*) ;; *) url="$url/dns-query" ;; esac ;;
		*/*) url="https://$1" ;;
		*) url="https://$1/dns-query" ;;
	esac
	case "$url" in *\?*) echo "$url&dns=$FK_DNS_Q" ;; *) echo "$url?dns=$FK_DNS_Q" ;; esac
}

_fk_dns_test_vpn() {
	local list="$1" v j sep="" n=0 urls="" ms u
	for v in $list; do
		case "$v" in *[!A-Za-z0-9.:/_?=%-]*|'') continue ;; esac
		n=$((n + 1)); [ "$n" -gt 16 ] && break
		urls="$urls$(_fk_doh_url "$v")
"
	done
	j="$(printf '%s' "$urls" | _fk_ucj dnsvpn)" || return 1
	printf '{"type":"doh","via":"vpn","results":['
	n=0
	for v in $list; do
		case "$v" in *[!A-Za-z0-9.:/_?=%-]*|'') continue ;; esac
		n=$((n + 1)); [ "$n" -gt 16 ] && break
		u="$(_fk_doh_url "$v")"
		ms="$(printf '%s' "$j" | jsonfilter -e "@.results[@.url='$u'].ms" 2>/dev/null | head -n1)"
		case "$ms" in ''|*[!0-9]*) ms=0 ;; esac
		printf '%s{"server":"%s","ok":%s,"ms":%s,"how":"vpn"}' "$sep" "$(esc "$v")" "$([ "$ms" -gt 0 ] && echo true || echo false)" "$ms"
		sep=","
	done
	printf ']}\n'
}

fk_dns_test() {
	local t="${1%%|*}" list="${1#*|}" d="$JOBS_DIR/fkdns.$$" v i=0 sep="" line ok ms how
	case "$t" in udp|dot|doh) ;; *) echo '{"error":"неизвестный тип DNS"}'; return 1 ;; esac
	if [ "$t" = doh ] && [ "$(uci -q get netshift.settings.dns_via_outbound)" = 1 ] && _fk_up; then
		_fk_dns_test_vpn "$list" && return 0
	fi
	command -v dig >/dev/null 2>&1 || [ "$t" = doh ] || { echo '{"error":"нет программы dig — нажмите «Переустановить» Forkozz"}'; return 1; }
	mkdir -p "$d"
	for v in $list; do
		case "$v" in *[!A-Za-z0-9.:/_?=%-]*|'') continue ;; esac
		i=$((i + 1))
		[ "$i" -gt 16 ] && break
		_fk_dns_probe "$t" "$v" "$d/$i" &
	done
	wait
	printf '{"type":"%s","via":"%s","results":[' "$t" "$([ "$(uci -q get netshift.settings.dns_via_outbound)" = 1 ] && echo direct_detour || echo direct)"
	for v in $(ls "$d" 2>/dev/null | sort -n); do
		IFS='|' read -r line ok ms how < "$d/$v"
		printf '%s{"server":"%s","ok":%s,"ms":%s,"how":"%s"}' "$sep" "$(esc "$line")" "$([ "$ok" = 1 ] && echo true || echo false)" "${ms:-0}" "$how"
		sep=","
	done
	printf ']}\n'
	rm -rf "$d"
}

forkop_config_get() {
	_fk_foreign_err && return 1
	_fk_installed || { echo '{"error":"Forkozz не установлен"}'; return 1; }
	if [ ! -f "$ST_CAT_OFF" ]; then
		if [ -s "$ST_CAT_IDX" ] && ! head -n1 "$ST_CAT_IDX" | grep -q '^[^|]*|[^|]*|[^|]*|[sd]$'; then
			[ -d "$ST_RUN/cat.lock" ] || ( _st_cat_refresh force >/dev/null 2>&1 & )
		else
			_st_cat_bg
		fi
	fi
	ZM_FK_CAT="$(_st_cat_json)" _fk_ucj get "$1"
}

forkop_config_set() {
	local res
	_fk_foreign_err && return 1
	_fk_installed || { echo '{"error":"Forkozz не установлен"}'; return 1; }
	_job_running forkop && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
	res="$(printf '%s' "$1" | _fk_ucj set)" || { echo "$res"; return 1; }
	rm -f "$ZM_STATE_DIR"/fk.fell "$ZM_STATE_DIR"/fk.fell.* "$ZM_STATE_DIR"/fk.home.* "$JOBS_DIR"/fk.heal "$JOBS_DIR"/fk.heal.*
	_ab_dns_bg
	echo "$res"
}

_zm_route_target() {
	local q
	q="$(printf '%s' "$1" | tr -d ' \t\r\n' | tr 'A-Z' 'a-z' | sed 's#^[a-z0-9+.-]*://##; s#^[^/@]*@##; s#[/?\#].*$##')"
	case "$q" in
		\[*\]*) q="${q#\[}"; q="${q%%\]*}" ;;
		*:*:*) ;;
		*:*) q="${q%%:*}" ;;
	esac
	printf '%s' "$q" | grep -Eq '^([a-z0-9]([a-z0-9_-]{0,62}\.)+[a-z0-9-]{1,63}|[0-9a-f:]{2,39})$' || return 1
	printf '%s' "$q"
}

_zm_resolve4() {
	nslookup "$1" 127.0.0.1 2>/dev/null | awk '/^Name:/ { f = 1; next } f && /^Address/ { a = $0; sub(/^Address[ 0-9]*:[ \t]*/, "", a); if (a ~ /^[0-9.]+$/) { print a; exit }}' | head -n1
}

_zm_resolve_any() {
	local a
	a="$(_zm_resolve4 "$1")"
	[ -n "$a" ] || a="$(nslookup "$1" 127.0.0.1 2>/dev/null | awk '/^Name:/ { f = 1; next } f && /^Address/ { a = $0; sub(/^Address[ 0-9]*:[ \t]*/, "", a); print a; exit }')"
	printf '%s' "$a"
}

_st_where() {
	local host="$1" ip="$2" man="$ST_RUN/where.$$" res="$ST_RUN/where.$$.r" on id name f3 f4 f5 f6 f7 f8 rest x f n=0 st path ent sep="" lab
	mkdir -p "$ST_RUN"
	{
		for f in "$ST_USER_DIR/exclude.lst" "$ST_USER_DIR/exclude.pfx"; do [ -s "$f" ] && printf 'x\texclude\tИсключения\t%s\n' "$f"; done
		if [ -s "$ST_DIR/model.svc" ] && _st_owns "steer-spec" && [ ! -f "$ST_OFF" ]; then
			ZM_SN="$(for x in $(_st_secs); do printf '%s=%s\t' "$x" "$(_st_sec_name "$x")"; done)" awk -F'\t' 'BEGIN { n = split(ENVIRON["ZM_SN"], a, "\t"); for (i = 1; i <= n; i++) if (a[i] != "") { k = a[i]; sub(/=.*/, "", k); v = a[i]; sub(/^[^=]*=/, "", v); SN[k] = v } }
				$1 == "sec" { sec = $2; next } $1 == "svc" { id = $2; nm = $3 (sec != "" && (sec in SN) ? " · " SN[sec] : ""); next } ($1 == "dom" || $1 == "pfx" || $1 == "srs") && id != "" { print "on\t" id "\t" nm "\t" $2 }' "$ST_DIR/model.svc"
		fi
	} > "$man"
	on=" $(awk -F'\t' '$1 == "on" { print $2 }' "$man" | sort -u | tr '\n' ' ') "
	_rb_svc_src | while IFS='|' read -r id name f3 f4 f5 f6 f7 f8 rest; do
		[ -n "$id" ] || continue
		case "$on" in *" $id "*) continue ;; esac
		{
			if [ "$id" = custom ]; then
				printf '%s\n' "$ST_USER_DIR/custom.lst" "$ST_USER_DIR/custom.pfx"
				for x in $(_st_secs); do printf '%s\n' "$ST_SEC_DIR/$x/custom.lst" "$ST_SEC_DIR/$x/custom.pfx"; done
			else
				for x in $(printf '%s,%s' "$f3" "$f4" | tr ',' ' '); do printf '%s\n' "$ZM_LISTS_DIR/$x"; done
				for x in $(printf '%s' "$f8" | tr ',' ' '); do printf '%s\n' "$ST_DIR/lists/$x.dom" "$ST_DIR/lists/$x.pfx" "$ST_DIR/lists/$x.srs"; done
			fi
		} | while IFS= read -r f; do [ -s "$f" ] && printf 'off\t%s\t%s\t%s\n' "$id" "$name" "$f"; done
	done | awk -F'\t' '!s[$2 "\t" $4]++' >> "$man"
	mkdir -p "$ST_RUN/srsdump"
	awk -F'\t' '{ print NR "\t" $0 }' "$man" | while IFS="$(printf '\t')" read -r n st id name path; do
		case "$path" in
			*.srs)
				x="$ST_RUN/srsdump/$(printf '%s' "$path" | tr -c 'A-Za-z0-9_.-' '_')"
				if { [ ! -s "$x.dom" ] && [ ! -s "$x.pfx" ]; } || [ "$path" -nt "$x.dom" ]; then
					rm -f "$x.dom" "$x.pfx"
					steer srs-read "$path" --out "$x.dom" --prefixes-out "$x.pfx" >/dev/null 2>&1 || rm -f "$x.dom" "$x.pfx"
				fi
				if [ -f "$x.dom" ]; then
					printf '%s\t%s\t%s\t%s\t%s\n' "$st" "$id" "$name" "$x.dom" "$path"
					[ -s "$x.pfx" ] && printf '%s\t%s\t%s\t%s\t%s\n' "$st" "$id" "$name" "$x.pfx" "$path"
				else
					printf '%s\t%s\t%s\t%s\t%s\n' "$st" "$id" "$name" "$path" "$path"
				fi ;;
			*) printf '%s\t%s\t%s\t%s\t%s\n' "$st" "$id" "$name" "$path" "$path" ;;
		esac
	done > "$man.x"
	mv -f "$man.x" "$man"
	{
		awk -F'\t' -v h="$host" -v ip="$ip" '
			function ipn(a,  p) { if (split(a, p, ".") != 4) return -1; return ((p[1] * 256 + p[2]) * 256 + p[3]) * 256 + p[4] }
			function under(n, d) { return length(n) > length(d) && substr(n, length(n) - length(d)) == "." d }
			BEGIN { iv = ip != "" ? ipn(ip) : -1 }
			$4 ~ /\.srs$/ { next }
			{
				best = ""; bw = -1; path = $4
				while ((getline l < path) > 0) {
					sub(/[#;].*$/, "", l); gsub(/^[ \t\r]+|[ \t\r]+$/, "", l); l = tolower(l)
					if (l == "" || l ~ /^re:/ || l ~ /[ \t]/) continue
					if (iv >= 0 && l ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+(\/[0-9]+)?$/) {
						split(l, c, "/"); b = (c[2] == "") ? 32 : c[2] + 0; if (b < 0 || b > 32) continue
						z = 2 ^ (32 - b); a = ipn(c[1])
						if (a >= 0 && int(iv / z) == int(a / z) && 100 + b > bw) { best = l; bw = 100 + b }
						continue
					}
					if (iv >= 0 && l ~ /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+-[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/) {
						split(l, c, "-"); if (iv >= ipn(c[1]) && iv <= ipn(c[2]) && 100 > bw) { best = l; bw = 100 }
						continue
					}
					if (h == "") continue
					if (substr(l, 1, 1) == "=") { w = substr(l, 2); if (h == w && length(w) > bw) { best = l; bw = length(w) } continue }
					if (substr(l, 1, 2) == "*.") { w = substr(l, 3); if (under(h, w) && length(w) > bw) { best = l; bw = length(w) } continue }
					if (l ~ /[*?]/) continue
					if ((h == l || under(h, l)) && length(l) > bw) { best = l; bw = length(l) }
				}
				close(path)
				if (best != "") print NR "\t" $1 "\t" $2 "\t" $3 "\t" ($5 != "" ? $5 : $4) "\t" best
			}' "$man"
		if command -v sing-box >/dev/null 2>&1; then
			_zm_gml >/dev/null
			awk -F'\t' '$4 ~ /\.srs$/ { print NR "\t" $1 "\t" $2 "\t" $3 "\t" $4 }' "$man" | while IFS="$(printf '\t')" read -r n st id name path; do
				for x in $host $ip; do
					GOMEMLIMIT="$ZM_GML_ONE" sing-box rule-set match -f binary "$path" "$x" 2>&1 | grep -q 'match rules' && { printf '%s\t%s\t%s\t%s\t%s\t%s\n' "$n" "$st" "$id" "$name" "$path" ""; break; }
				done
			done
		fi
	} | sort -n -k1,1 | head -n 40 > "$res"
	printf '['
	while IFS="$(printf '\t')" read -r n st id name path ent; do
		case "$path" in
			"$ST_USER_DIR"/exclude.*) lab="Исключения" ;;
			"$ST_USER_DIR"/custom.*|"$ST_SEC_DIR"/*/custom.*) lab="Свой список" ;;
			"$ST_DIR"/lists/*.base.dom) lab="основные домены сервиса" ;;
			"$ST_DIR"/lists/*) lab="${path##*/}"; lab="${lab%.*} (каталог списков)" ;;
			*) lab="${path##*/}" ;;
		esac
		printf '%s{"state":"%s","id":"%s","name":"%s","list":"%s","entry":"%s"}' "$sep" "$st" "$(esc "$id")" "$(esc "$name")" "$(esc "$lab")" "$(esc "$ent")"
		sep=","
	done < "$res"
	printf ']'
	rm -f "$man" "$man.x" "$res"
}

_st_dnslog_fix() {
	local src="$1" man="$ST_RUN/dlfix.$$" nl="$ST_RUN/dlfix.$$.n" map="$ST_RUN/dlfix.$$.m" tab x path nm
	tab="$(printf '\t')"
	if [ ! -s "$ST_DIR/model.svc" ] || [ "$(grep -c '^svc	' "$ST_DIR/model.svc")" -le 1 ]; then cat "$src"; return 0; fi
	mkdir -p "$ST_RUN/srsdump"
	awk -F'\t' '$1 == "svc" { nm = $3; next } ($1 == "dom" || $1 == "srs") && nm != "" { print nm "\t" $2 }' "$ST_DIR/model.svc" |
	while IFS="$tab" read -r nm path; do
		case "$path" in
			*.srs)
				x="$ST_RUN/srsdump/$(printf '%s' "$path" | tr -c 'A-Za-z0-9_.-' '_')"
				if [ -s "$path" ] && { { [ ! -s "$x.dom" ] && [ ! -s "$x.pfx" ]; } || [ "$path" -nt "$x.dom" ]; }; then
					rm -f "$x.dom" "$x.pfx"
					steer srs-read "$path" --out "$x.dom" --prefixes-out "$x.pfx" >/dev/null 2>&1 || rm -f "$x.dom" "$x.pfx"
				fi
				[ -s "$x.dom" ] && printf '%s\t%s\n' "$nm" "$x.dom" ;;
			*) [ -s "$path" ] && printf '%s\t%s\n' "$nm" "$path" ;;
		esac
	done > "$man"
	grep -o '{"name":"[^"]*","channel":"' "$src" | sed 's/^{"name":"//; s/",.*$//' | awk '!s[$0]++' > "$nl"
	if [ ! -s "$man" ] || [ ! -s "$nl" ]; then cat "$src"; rm -f "$man" "$nl"; return 0; fi
	awk -F'\t' '
		FNR == NR {
			n = $0; sub(/\.$/, "", n); has[n] = 1; ord[++nn] = $0; key[$0] = n
			s = n
			while (1) { suf[s] = 1; i = index(s, "."); if (!i) break; s = substr(s, i + 1) }
			next
		}
		function add(k, lab) { if (!((k, lab) in got)) { got[k, lab] = 1; hit[k] = hit[k] SUBSEP lab } }
		{
			lab = $1; path = $2
			if (!(lab in rank)) rank[lab] = ++nr
			while ((getline l < path) > 0) {
				sub(/[#;].*$/, "", l); gsub(/^[ \t\r]+|[ \t\r]+$/, "", l)
				if (l == "") continue
				l = tolower(l)
				c = substr(l, 1, 1)
				if (c == "=") { w = substr(l, 2); if (w in has) add("e" SUBSEP w, lab); continue }
				if (c == "*" && substr(l, 2, 1) == ".") { w = substr(l, 3); if (w in suf) add("s" SUBSEP w, lab); continue }
				if (l ~ /^re:/ || l ~ /[*? \t\/]/) continue
				if (l in suf) add("d" SUBSEP l, lab)
			}
			close(path)
		}
		END {
			for (j = 1; j <= nn; j++) {
				n = key[ord[j]]; all = ""; delete pick
				s = n
				while (1) {
					all = all hit["d" SUBSEP s]
					if (s == n) all = all hit["e" SUBSEP s]; else all = all hit["s" SUBSEP s]
					i = index(s, "."); if (!i) break; s = substr(s, i + 1)
				}
				m = split(all, p, SUBSEP); out = ""
				for (r = 1; r <= nr; r++) for (t = 2; t <= m; t++) if (rank[p[t]] == r && !(p[t] in pick)) {
					pick[p[t]] = 1; out = out (out == "" ? "" : ", ") p[t]
				}
				print ord[j] "\t" out
			}
		}' "$nl" "$man" > "$map"
	awk -v map="$map" -v direct="$ST_DIRECT_OUT" '
		BEGIN { while ((getline l < map) > 0) { k = index(l, "\t"); n = substr(l, 1, k - 1); v = substr(l, k + 1); gsub(/["\\]/, "", v); lab[n] = v; known[n] = 1 } close(map) }
		{
			sep = "{\"name\":\""; pre = "\",\"channel\":\""; rest = $0; o = ""
			while ((i = index(rest, sep)) > 0) {
				o = o substr(rest, 1, i - 1 + length(sep)); rest = substr(rest, i + length(sep))
				k = index(rest, "\""); nm = substr(rest, 1, k - 1); t = substr(rest, k)
				if (!(nm in known) || substr(t, 1, length(pre)) != pre) continue
				t = substr(t, length(pre) + 1); e = 0
				for (z = 1; z <= length(t); z++) { c = substr(t, z, 1); if (c == "\\") { z++; continue } if (c == "\"") { e = z; break } }
				if (!e) continue
				after = substr(t, e + 1)
				if (index(after, ",\"out\":\"" direct "\"") == 1) continue
				o = o nm "\",\"channel\":" (lab[nm] != "" ? "\"" lab[nm] "\"" : "null"); rest = after
			}
			print o rest
		}' "$src"
	rm -f "$man" "$nl" "$map"
}

_st_src_dev() {
	local ip="$1" mac line s f
	[ -s "$ST_DIR/devices" ] || [ -n "$(_st_secs)" ] || return 1
	mac="$(awk -v ip="$ip" '$3 == ip { print tolower($2); exit }' /tmp/dhcp.leases 2>/dev/null)"
	[ -n "$mac" ] || mac="$(awk -v ip="$ip" 'NR > 1 && $1 == ip && $3 != "0x0" { print tolower($4); exit }' /proc/net/arp 2>/dev/null)"
	[ -n "$mac" ] || mac="$(uci -q -X show dhcp 2>/dev/null | awk -F= -v ip="$ip" '
		/^dhcp\.[^.]*\.(mac|ip)=/ { split($1, a, "."); v = $2; gsub(/\x27/, "", v); x[a[2], a[3]] = v }
		END { for (k in x) { split(k, z, SUBSEP); if (z[2] == "ip" && x[k] == ip && x[z[1], "mac"] != "") { split(x[z[1], "mac"], m, " "); print tolower(m[1]); exit } } }')"
	for s in main $(_st_secs); do
		if [ "$s" = main ]; then f="$ST_DIR/devices"; else f="$ST_SEC_DIR/$s/devices"; fi
		[ -s "$f" ] || continue
		line="$(awk -F'\t' -v k="$ip" -v m="$mac" '($1 == "all" || $1 == "byp" || $1 == "only") && ($2 == k || (m != "" && $2 == m)) { print $1 "\t" $2 "\t" $3; exit }' "$f")"
		[ -n "$line" ] && { printf '%s\t%s\n' "$line" "$s"; return 0; }
	done
	return 1
}

_st_lan_ip() {
	case "$1" in
		10.*|192.168.*|172.1[6-9].*|172.2[0-9].*|172.3[01].*|169.254.*|127.*|fe80:*|fd*|fc*) return 0 ;;
	esac
	return 1
}

_st_x_node() {
	local n
	n="$(cat "$ST_SUB_NODE" 2>/dev/null)"
	[ "$STL_X_VERDICT" = vpn ] && stl_state vpn && [ "$STL_UP" = true ] && [ -n "$STL_NODE" ] && { n="$(_st_active_key)"; n="${n:-$STL_NODE}"; }
	printf '%s' "$n"
}
steer_explain() {
	local q host="" ip="" fd where arg="$1" src="" sdev="" smode="" skey="" sname="" ssec=""
	case "$arg" in *'|'*) src="${arg#*|}"; arg="${arg%%|*}" ;; esac
	q="$(_zm_route_target "$arg")" || { echo '{"error":"введите домен (например, youtube.com) или IP-адрес"}'; return 1; }
	stl_present || { echo '{"error":"Steer не установлен"}'; return 1; }
	src="$(printf '%s' "$src" | tr -d ' \t\r\n')"
	if [ -n "$src" ]; then
		printf '%s' "$src" | grep -Eq '^(25[0-5]|2[0-4][0-9]|1?[0-9]?[0-9])(\.(25[0-5]|2[0-4][0-9]|1?[0-9]?[0-9])){3}$' || { echo '{"error":"IP устройства — адрес вида 192.168.1.100"}'; return 1; }
		if sdev="$(_st_src_dev "$src")"; then
			smode="$(printf '%s' "$sdev" | cut -f1)"; skey="$(printf '%s' "$sdev" | cut -f2)"; sname="$(printf '%s' "$sdev" | cut -f3)"; ssec="$(printf '%s' "$sdev" | cut -f4)"
			[ "$ssec" = main ] && ssec=""
		fi
	fi
	if printf '%s' "$q" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$'; then ip="$q"
	elif printf '%s' "$q" | grep -q ':'; then :
	else host="$q"; fi
	if ! { _st_owns "steer-spec" && [ ! -f "$ST_OFF" ]; }; then
		printf '{"target":"%s","verdict":"off","text":"","where":%s}\n' "$(esc "$q")" "$(_st_where "$host" "$ip")"
		return 0
	fi
	local node probe="" p
	stl_explain "$q"
	if [ "$STL_X_VERDICT" = noaddr ] && [ -n "$host" ]; then
		for p in $ZM_ROUTE_PROBES; do
			case "$host" in "$p".*) continue ;; esac
			stl_explain "$p.$host"
			case "$STL_X_VERDICT" in noaddr|unknown) ;; *) probe="$p.$host"; break ;; esac
		done
		[ -n "$probe" ] || stl_explain "$q"
	fi
	local xs=""
	case "$STL_X_OUT" in zm_vpn[2-9]|zm_if[2-9]|zmv[2-9]_*) xs="s$(printf '%s' "$STL_X_OUT" | tr -cd '0-9' | cut -c1)" ;; esac
	[ -z "$xs" ] && case "$STL_X_SET" in s[2-9]_*) xs="${STL_X_SET%%_*}" ;; esac
	_st_sec_ok "$xs" || xs=""
	node="$(_st_sec_with "${xs:-main}" _st_x_node)"
	fd="$(printf '%s\n' "$STL_X_TEXT" | sed -n 's/^[[:space:]]*поддельный адрес имени \([^ ]*\).*/\1/p' | head -n1)"
	[ -z "$host" ] && [ -n "$fd" ] && host="$fd" && ip=""
	[ -z "$ip" ] && [ "$STL_X_FAKE" != true ] && printf '%s' "$STL_X_ADDR" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$' && ip="$STL_X_ADDR"
	where="$(_st_where "$host" "$ip")"
	[ "$STL_X_VERDICT" = direct ] && [ "$STL_X_OUT" = "$ST_DIRECT_OUT" ] && case "$where" in *'"state":"x"'*) STL_X_VERDICT=exclude ;; esac
	if [ "$smode" = byp ]; then STL_X_VERDICT=devbyp
	elif [ "$smode" = all ]; then
		case "$where" in *'"state":"x"'*) STL_X_VERDICT=exclude ;; *)
			if [ -n "$ip" ] && _st_lan_ip "$ip"; then STL_X_VERDICT=devlan
			elif [ -n "$ssec" ]; then
				xs="$ssec"; STL_X_DEV=""; STL_X_OUT="$(_st_sec_out "$ssec")"
				case "$(_st_sec_kind "$ssec")" in
					vpn) STL_X_VERDICT=vpn; node="$(_st_sec_with "$ssec" _st_x_node)" ;;
					iface) STL_X_VERDICT=iface; STL_X_DEV="$(_st_sec_iface "$ssec")" ;;
					*) STL_X_VERDICT=warp ;;
				esac
			elif _st_use_vpn; then STL_X_VERDICT=vpn; STL_X_DEV=""; node="$(cat "$ST_SUB_NODE" 2>/dev/null)"; stl_state vpn && [ "$STL_UP" = true ] && [ -n "$STL_NODE" ] && node="$(_st_active_key)" && node="${node:-$STL_NODE}"
			elif [ "$(_st_exit)" = iface ]; then STL_X_VERDICT=iface; STL_X_DEV="$(_st_main_iface)"
			else STL_X_VERDICT=warp; STL_X_DEV=""; fi ;;
		esac
	fi
	printf '{"target":"%s","verdict":"%s","out":"%s","dev":"%s","channel":"%s","addr":"%s","fake":%s,"node":"%s","probe":"%s","where":%s,"src":"%s","src_mode":"%s","src_key":"%s","src_name":"%s","src_sec":"%s","src_sec_name":"%s","sec":"%s","sec_name":"%s","sec_sub":"%s","text":"%s"}\n' \
		"$(esc "$q")" "$STL_X_VERDICT" "$(esc "$STL_X_OUT")" "$(esc "$STL_X_DEV")" "$(esc "$STL_X_SET")" "$(esc "$STL_X_ADDR")" "$STL_X_FAKE" \
		"$(esc "$node")" "$(esc "$probe")" "$where" "$(esc "$src")" "$smode" "$(esc "$skey")" "$(esc "$sname")" "$ssec" "$(esc "$([ -n "$ssec" ] && _st_sec_name "$ssec")")" "$xs" "$(esc "$([ -n "$xs" ] && _st_sec_name "$xs")")" "$(esc "$([ -n "$xs" ] && _st_sec_with "$xs" _st_sub_label)")" "$(esc_ml "$STL_X_TEXT")"
}

fk_route_check() {
	local q addr="" how="" verdict=direct tr rule="" ob="" ac="" sec="" s isip=0 caught=0 arg="$1" source="" err wh=
	case "$arg" in *'|'*) source="${arg#*|}"; arg="${arg%%|*}" ;; esac
	q="$(_zm_route_target "$arg")" || { echo '{"error":"введите домен (например, youtube.com) или IP-адрес"}'; return 1; }
	_fk_installed || { echo '{"error":"Forkozz не установлен"}'; return 1; }
	_fk_up || { printf '{"target":"%s","verdict":"off"}\n' "$(esc "$q")"; return 0; }
	local probe="" p name="$q" noaddr=0
	if printf '%s' "$q" | grep -Eq '^[0-9.]+$|:'; then addr="$q"; isip=1; else addr="$(_zm_resolve_any "$q")"; fi
	if [ -z "$addr" ] && [ "$isip" = 0 ] && [ -n "$(_zm_resolve4 openwrt.org)" ]; then
		noaddr=1
		for p in $ZM_ROUTE_PROBES; do
			case "$q" in "$p".*) continue ;; esac
			addr="$(_zm_resolve_any "$p.$q")"
			[ -n "$addr" ] && { probe="$p.$q"; name="$probe"; noaddr=0; break; }
		done
	fi
	case "$addr" in
		'') ;;
		2001:2::*|2001:2:0:*|fd00:ec3a:*) caught=1; how=fakeip ;;
		*:*) nft get element inet "$FK_NFT" netshift_subnets_v6 "{ $addr }" >/dev/null 2>&1 && { caught=1; how=subnet; } ;;
		*) _fk_fip_in "$addr" && { caught=1; how=fakeip; }
			[ "$caught" = 1 ] || for s in netshift_subnets netshift_discord_subnets; do
			nft get element inet "$FK_NFT" "$s" "{ $addr }" >/dev/null 2>&1 && { caught=1; how=subnet; break; }
		done ;;
	esac
	if _zm_tmo_ok; then tr="$(timeout 40 ucode "$FK_UC" route "$name" "$addr" "$source" 2>/dev/null)"
	else tr="$(_zm_tmo 40 _fk_uc route "$name" "$addr" "$source" 2>/dev/null)"; fi
	case "$tr" in
		'{'*)
			err="$(printf '%s' "$tr" | jsonfilter -e '@.error' 2>/dev/null)"
			[ -z "$err" ] || { printf '%s\n' "$tr"; return 1; }
			rule="$(printf '%s' "$tr" | jsonfilter -e '@.rule' 2>/dev/null)"
			ob="$(printf '%s' "$tr" | jsonfilter -e '@.outbound' 2>/dev/null)"
			ac="$(printf '%s' "$tr" | jsonfilter -e '@.action' 2>/dev/null)"
			sec="$(printf '%s' "$tr" | jsonfilter -e '@.section' 2>/dev/null)"
			wh="$(printf '%s' "$tr" | sed -n 's/.*"where": *\(\[.*\]\) *}[[:space:]]*$/\1/p' | head -n1)"
			;;
	esac
	case "$wh" in '['*']') ;; *) wh='[]' ;; esac
	case "$ac" in
		source_required) verdict=unknown ;;
		fallback_direct) verdict=direct ;;
		bypass) verdict=bypass ;;
		block) verdict=block ;;
		connection|outbound) [ "$caught" = 1 ] && verdict=proxy || verdict=direct ;;
		*) if [ -z "$addr" ]; then verdict=unknown; else verdict=direct; fi ;;
	esac
	[ -z "$addr" ] && [ "$isip" = 0 ] && { [ "$verdict" = proxy ] || [ "$ac" = connection ] || [ "$ac" = outbound ]; } && verdict=unknown
	[ "$verdict" = unknown ] && [ "$noaddr" = 1 ] && verdict=noaddr
	printf '{"target":"%s","verdict":"%s","how":"%s","addr":"%s","ip":%s,"rule":"%s","outbound":"%s","action":"%s","section":"%s","source":"%s","probe":"%s","where":%s}\n' \
		"$(esc "$q")" "$verdict" "$how" "$(esc "$addr")" "$([ "$isip" = 1 ] && echo true || echo false)" "$(esc "$rule")" "$(esc "$ob")" "$(esc "$ac")" "$(esc "$sec")" \
		"$(esc "$source")" "$(esc "$probe")" "$wh"
}

forkop_action() {
	local a="$1" arg="$2" b u
	_fk_foreign_err && return 1
	case "$a" in
		install|update|reinstall)
			b="$(_fk_blocker)"
			[ -n "$b" ] && { printf '{"error":"%s"}\n' "$(esc "$(_fk_blocker_text "$b")")"; return 1; }
			[ "$a" = reinstall ] && ! _fk_installed && { echo '{"error":"Forkozz не установлен"}'; return 1; }
			job_start forkop do_fk_install "$a" ;;
		remove)        job_start forkop do_fk_remove "$arg" ;;
		tunnels)       _fk_tunnels_json ;;
		start|stop|restart|apply) job_start forkop do_fk_service "$a" ;;
		route)         fk_route_check "$arg" ;;
		lists)         job_start forkop do_fk_lists ;;
		subs)          job_start forkop do_fk_subs ;;
		singbox|singbox_reinstall) job_start forkop do_fk_singbox "$arg" ;;
		singbox_remove)
			_fk_installed && { echo '{"error":"сначала удалите Forkozz — без sing-box он не работает"}'; return 1; }
			u="$(_fk_sb_users)"
			[ -n "$u" ] && { printf '{"error":"%s"}\n' "$(esc "sing-box нужен другим программам ($u) — удалять его нельзя")"; return 1; }
			job_start forkop do_fk_sb_remove ;;
		diag)
			b="$(_fk_ucj diag "$arg")" || { printf '%s\n' "$b"; return 1; }
			u="$(_fk_src_checks)"
			case "$b" in *'}') printf '%s,"extra":[%s]}\n' "${b%\}}" "$u" ;; *) printf '%s\n' "$b" ;; esac ;;
		src_fix)
			_job_running forkop && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			job_start forkop do_fk_src_fix ;;
		dns_fix)
			_fk_installed || { echo '{"error":"Forkozz не установлен"}'; return 1; }
			_job_running forkop && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			job_start forkop do_fk_dns_fix ;;
		tsc_clean)
			_tsc_installed && { echo '{"error":"Tailscale установлен — его настройки убираются только вместе с ним (страница «Удалённый доступ» → «Удалить»)"}'; return 1; }
			_job_running forkop && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			job_start forkop do_tsc_leftovers_clean ;;
		secstate)      _fk_ucj secstate "$([ "$arg" = probe ] && echo probe)" ;;
		servers)       _fk_ucj servers "$arg" ;;
		latency)       _fk_ucj latency "$arg" ;;
		latmode)       _fk_ucj latmode "$arg" ;;
		nodepol)       _fk_ucj nodepol "$arg" ;;
		rssnap)        fk_rs_set "$arg" ;;
		probe)
			case "$arg" in *'|'*) _fk_ucj probe "${arg%%|*}" "${arg#*|}" ;; *) _fk_ucj probe "" "$arg" ;; esac ;;
		home_forget)
			case "$arg" in *[!A-Za-z0-9_]*|'') echo '{"error":"неверное имя секции"}'; return 1 ;; esac
			rm -f "$ZM_STATE_DIR/fk.home.$arg"
			printf '{"ok":true}\n' ;;
		stats)         _fk_ucj stats ;;
		conns)         _fk_ucj conns ;;
		cfg)           forkop_config_get "$arg" ;;
		secdel)
			_fk_installed || { echo '{"error":"Forkozz не установлен"}'; return 1; }
			_job_running forkop && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			b="$(_fk_ucj secdel "$arg")" || { printf '%s\n' "$b"; return 1; }
			case "$b" in *'"ok": true'*|*'"ok":true'*) ;; *) printf '%s\n' "$b"; return 1 ;; esac
			if _fk_enabled && _fk_up; then job_start forkop do_fk_service restart
			else printf '{"ok":true,"saved":true}\n'; fi
			;;
		dns_test)      fk_dns_test "$arg" ;;
		hide)
			_fk_installed || { echo '{"error":"Forkozz не установлен"}'; return 1; }
			_job_running forkop && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			b="$(printf '%s' "$arg" | _fk_ucj hide)"
			case "$b" in *'"ok": true'*|*'"ok":true'*) ;; *) printf '%s\n' "$b"; return 1 ;; esac
			if _fk_enabled && _fk_up; then job_start forkop do_fk_service apply
			else printf '{"ok":true,"saved":true}\n'; fi
			;;
		rllearn)
			_fk_installed || { echo '{"error":"Forkozz не установлен"}'; return 1; }
			_job_running forkop && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			_fk_up || { echo '{"error":"Forkozz выключен — включите его, и серверы можно будет проверить"}'; return 1; }
			job_start forkop do_fk_rl_learn "$arg" ;;
		reality)
			_fk_installed || { echo '{"error":"Forkozz не установлен"}'; return 1; }
			_job_running forkop && { echo '{"error":"дождитесь окончания текущей операции"}'; return 1; }
			_fk_reality_patch
			_fk_rsinit_patch
			_fk_desync_patch
		_fk_fakeip_patch
			grep -q '^# ZM_REALITY 1$' /usr/bin/netshift 2>/dev/null || { echo '{"error":"эта версия Forkozz не даёт менять настройки REALITY — обновите Forkozz"}'; return 1; }
			b="$(printf '%s' "$arg" | _fk_ucj rlnode)"
			case "$b" in *'"ok": true'*|*'"ok":true'*) ;; *) printf '%s\n' "$b"; return 1 ;; esac
			if _fk_enabled && _fk_up; then job_start forkop do_fk_service apply
			else printf '{"ok":true,"saved":true}\n'; fi
			;;
		select)
			case "$arg" in *'|'*) _fk_ucj select "${arg%%|*}" "${arg#*|}" ;; *) _fk_ucj select "" "$arg" ;; esac ;;
		*) echo '{"error":"неизвестное действие"}' ;;
	esac
}

_tsc_ip_rules_left() {
	local f
	for f in -4 -6; do ip "$f" rule show 2>/dev/null | grep -qE 'lookup 52( |$)|fwmark 0x80000/0xff0000' && return 0; done
	return 1
}

_tsc_leftovers() {
	local z lz
	_tsc_installed && return 0
	uci -q get netshift.settings.source_network_interfaces | tr ' ' '\n' | grep -qx "$TSC_DEV" && echo "Forkozz ждёт трафик с $TSC_DEV"
	[ -f "$TSC_ON" ] && echo "панель считает удалённый доступ включённым"
	uci -q get "network.$TSC_NET" >/dev/null && echo "интерфейс «$TSC_NET» в сети"
	lz="$(_zm_lan_zone)"
	z="$(_zm_zone_sec "$lz" 2>/dev/null)" && case " $(uci -q get "firewall.$z.network") " in *" $TSC_NET "*) echo "«$TSC_NET» в зоне «$lz»" ;; esac
	uci -q get "firewall.$TSC_FW_RULE" >/dev/null && echo "правило firewall Allow-Tailscale"
	_tsc_nft_left && echo "правила Tailscale в firewall (ts-*)"
	_tsc_ip_rules_left && echo "правила маршрутизации Tailscale (таблица 52)"
	[ -f "$TSC_LS_PREV" ] && echo "изменённая настройка DNS роутера (localservice)"
	grep -qF "$TSC_CRON_TAG" "$CRON_FILE" 2>/dev/null && echo "сторож Tailscale в cron"
	return 0
}

_fk_src_bad() {
	local d
	[ "$1" = "$TSC_DEV" ] && ! _tsc_installed && { echo tsc; return 0; }
	[ -d "/sys/class/net/$1" ] || { echo miss; return 0; }
	case "$(cat "/sys/class/net/$1/type" 2>/dev/null)" in 1|'') ;; *) [ "$1" = "$TSC_DEV" ] || { echo tun; return 0; } ;; esac
	for d in $(uci -q show netshift 2>/dev/null | sed -n "s/^netshift\.[^.]*\.\(interface\|output_network_interface\)='\([^']*\)'$/\2/p"); do
		[ "$d" = "$1" ] && { echo out; return 0; }
	done
	return 1
}

_fk_src_checks() {
	local src d have="" bad="" sep="," k
	src="$(uci -q get netshift.settings.source_network_interfaces)"
	[ -n "$src" ] || src="br-lan"
	for d in $src; do
		if k="$(_fk_src_bad "$d")"; then
			case "$k" in miss) bad="$bad; $d — такого интерфейса нет" ;; tsc) bad="$bad; $d — остался от удалённого Tailscale" ;; *) bad="$bad; $d — это туннель, а не домашняя сеть: трафик пойдёт по кругу" ;; esac
		else have="$have $d"; fi
	done
	have="${have# }"; bad="${bad#; }"
	if [ -z "$bad" ]; then
		printf '{"verdict":"ok","what":"Откуда берёт трафик","why":"%s"}' "$(esc "$have")"
	else
		printf '{"verdict":"%s","what":"Откуда берёт трафик","why":"%s","fix":"src_fix"}' "$([ -z "$have" ] && echo fail || echo warn)" \
			"$(esc "${have:+$have; }лишнее: $bad")"
	fi
	local left
	left="$(_tsc_leftovers | tr '\n' ';' | sed 's/;$//; s/;/; /g')"
	[ -n "$left" ] && printf '%s{"verdict":"fail","what":"Остатки удалённого доступа (Tailscale)","why":"%s","fix":"tsc_clean"}' "$sep" "$(esc "$left")"
	return 0
}

do_fk_src_fix() {
	local src d keep=""
	echo "==> Проверяем, откуда Forkozz берёт трафик"
	uci -q get netshift.settings >/dev/null || { echo "ОШИБКА: настроек Forkozz нет"; return 1; }
	src="$(uci -q get netshift.settings.source_network_interfaces)"
	[ -n "$src" ] || src="br-lan"
	for d in $src; do
		if _fk_src_bad "$d" >/dev/null; then echo "   ✓ Убираем $d"; else keep="$keep $d"; fi
	done
	[ -n "$keep" ] || { keep=" br-lan"; echo "   ✓ Других сетей не осталось — возвращаем домашнюю сеть по умолчанию: br-lan"; }
	uci -q delete netshift.settings.source_network_interfaces
	for d in $keep; do uci add_list netshift.settings.source_network_interfaces="$d"; done
	uci commit netshift
	echo "   ✓ Источники трафика:$keep"
	if [ -x /etc/init.d/netshift ] && /etc/init.d/netshift enabled 2>/dev/null; then
		echo "==> Перезапускаем Forkozz"
		_zm_run 180 /etc/init.d/netshift restart >/dev/null 2>&1 || echo "!! Forkozz перезапустился с ошибкой — смотрите журнал"
	fi
	echo "==> Готово"
}

do_fk_dns_fix() {
	local v
	echo "==> Проверяем DNS роутера (dnsmasq)"
	if [ ! -x /usr/sbin/dnsmasq ] || [ ! -x /etc/init.d/dnsmasq ]; then
		echo "   ! dnsmasq не установлен — ставим обычный dnsmasq"
		_zm_resolv_upstream
		$UPDATE >&2
		$INSTALL dnsmasq >&2
		if [ ! -x /usr/sbin/dnsmasq ]; then
			echo "ОШИБКА: dnsmasq не установился — проверьте интернет на роутере и нажмите «Починить DNS» ещё раз"
			return 1
		fi
		rm -f /etc/config/dhcp-opkg /etc/config/dhcp.apk-new
	fi
	v="$(_zm_dnsmasq_variant)"
	echo "   → Перезапускаем ${v:-dnsmasq}"
	if ! _zm_dnsmasq_start; then
		echo "ОШИБКА: dnsmasq не запускается — посмотрите «Система → Журнал» (logread | grep dnsmasq) или перезагрузите роутер"
		return 1
	fi
	echo "   ✓ dnsmasq работает"
	if [ "$(uci -q get netshift.settings.dont_touch_dhcp)" = 1 ]; then
		echo "==> Включено «Не менять настройки DNS роутера» — Forkozz dnsmasq не трогает"
	elif [ -x /etc/init.d/netshift ] && /etc/init.d/netshift enabled 2>/dev/null; then
		echo "==> Перезапускаем Forkozz — он снова направит dnsmasq на себя"
		_zm_run 180 /etc/init.d/netshift restart >/dev/null 2>&1 || echo "!! Forkozz перезапустился с ошибкой — смотрите журнал"
		_fk_fwd_sync
	fi
	if [ "$(uci -q get 'dhcp.@dnsmasq[0].netshift_configured')" = 1 ] || [ "$(uci -q get netshift.settings.dont_touch_dhcp)" = 1 ]; then
		echo "==> Готово: DNS роутера работает"
	else
		echo "==> dnsmasq работает, но Forkozz не направил его на себя — нажмите «Проверить» через минуту, при повторе перезапустите Forkozz"
	fi
}

do_tsc_leftovers_clean() {
	local f p
	echo "==> Ищем остатки удалённого доступа (Tailscale)"
	_tsc_installed && { echo "ОШИБКА: Tailscale установлен — удалите его на странице «Удалённый доступ»"; return 1; }
	_tsc_leftovers | sed 's/^/   · /'
	if uci -q get netshift.settings.source_network_interfaces | tr ' ' '\n' | grep -qx "$TSC_DEV"; then
		uci -q del_list netshift.settings.source_network_interfaces="$TSC_DEV"
		uci -q get netshift.settings.source_network_interfaces >/dev/null || uci add_list netshift.settings.source_network_interfaces="br-lan"
		uci commit netshift
		echo "   ✓ Forkozz: $TSC_DEV убран из источников трафика"
	fi
	rm -f "$TSC_DIR/forkozz.own"
	for f in -4 -6; do
		for p in $(ip "$f" rule show 2>/dev/null | grep -E 'lookup 52( |$)|fwmark 0x80000/0xff0000' | sed -n 's/^\([0-9]*\):.*/\1/p'); do
			ip "$f" rule del pref "$p" 2>/dev/null
		done
		ip "$f" route flush table 52 >/dev/null 2>&1
	done
	_tsc_ip_rules_left || echo "   ✓ Правила маршрутизации Tailscale убраны"
	_tsc_unsetup
	rm -rf "$TSC_DIR"
	if [ -n "$(_tsc_leftovers)" ]; then
		echo "!! Осталось:"; _tsc_leftovers | sed 's/^/   · /'
		return 1
	fi
	echo "==> Готово: остатков нет"
}

SI_OUT="$JOBS_DIR/sysinfo.json"

_si_clean() { printf '%s' "$1" | tr '\t\r' '  ' | tr -d '\000-\010\013\014\016-\037'; }

_si_mask() {
	printf '%s' "$1" | awk '
		BEGIN {
			n = split("1.1.1.1 1.0.0.1 8.8.8.8 8.8.4.4 9.9.9.9 149.112.112.112 77.88.8.8 77.88.8.1 77.88.8.88 77.88.8.2 77.88.8.7 77.88.8.3 76.76.2.0 76.76.10.0 86.54.11.100 86.54.11.200 94.140.14.14 94.140.15.15 208.67.222.222 208.67.220.220 127.0.0.1 0.0.0.0", w, " ")
			for (i = 1; i <= n; i++) ok[w[i]] = 1
		}
		{
			o = ""; t = $0
			gsub("(vless|vmess|trojan|ss|ssr|hysteria2?|tuic|wireguard|socks5?|https?)://[^ ]*(@|token=|key=|sub/|[?][^ ]*=)[^ ]*", "(ссылка скрыта)", t)
			while (match(t, /[0-9]+[.][0-9]+[.][0-9]+[.][0-9]+/)) {
				ip = substr(t, RSTART, RLENGTH)
				o = o substr(t, 1, RSTART - 1) ((ip in ok) ? ip : "x.x.x.x")
				t = substr(t, RSTART + RLENGTH)
			}
			o = o t
			gsub(/[A-Za-z0-9._%+-]+@[A-Za-z0-9-]+[.][A-Za-z0-9.-]*[A-Za-z]/, "(почта скрыта)", o)
			printf "%s%s", (NR > 1 ? "\n" : ""), o
		}'
}

_si_row() {
	printf '%s["%s","%s","%s"]' "$SI_SEP" "$(esc "$(_si_mask "$(_si_clean "$1")")")" "$(esc "$(_si_mask "$(_si_clean "$2")")")" "$3"
	SI_SEP=","
}
_si_sec() { printf ',{"title":"%s","rows":[' "$(esc "$1")"; SI_SEP=""; }
_si_end() { printf ']}'; }
_si_j() { jsonfilter -s "$1" -e "$2" 2>/dev/null; }
_si_jl() { jsonfilter -s "$1" -e "$2" 2>/dev/null | grep . | tr '\n' ',' | sed 's/,$//; s/,/, /g'; }
_si_yes() { case "$1" in true|1|on|yes) echo да ;; *) echo нет ;; esac; }
SI_DOH_INIT="/etc/init.d/https-dns-proxy"
_si_every() {
	case "$1" in
		''|off|0) echo нет ;;
		m[0-9]*) echo "каждые ${1#m} мин" ;;
		h1) echo "каждый час" ;;
		h[0-9]*) echo "каждые ${1#h} ч" ;;
		d[0-9]*) echo "раз в сутки в ${1#d}:00" ;;
		*) echo "$1" ;;
	esac
}
_si_st_exit() {
	case "$1" in
		warp) echo WARP ;; vpn) echo VPN по подписке ;;
		iface) v="$(_si_j "$2" '@.main_tun.name')"; echo "туннель${v:+ $v}" ;;
		none|'') echo не подключён ;; *) echo "$1" ;;
	esac
}
_si_mirror() {
	local h how="" ts="" w="" n
	h="$(_mirror_host)"; n="$(_mirror_name)"
	if [ "$h" != downloads.openwrt.org ] && [ -s "$ZM_MIRROR_STATE" ] && [ "$(cut -f1 "$ZM_MIRROR_STATE")" = "$h" ]; then
		how="$(cut -f3 "$ZM_MIRROR_STATE")"; ts="$(cut -f2 "$ZM_MIRROR_STATE" | tr -cd 0-9)"
	fi
	[ -n "$ts" ] && w="$(date -d "@$ts" '+%d.%m %H:%M' 2>/dev/null)"
	case "$how" in
		auto) w=" · выбрано автоматически${w:+ $w}" ;; pick) w=" · подобрано${w:+ $w}" ;; manual) w=" · выбрано вручную${w:+ $w}" ;; *) w="" ;;
	esac
	_si_row "Зеркало OpenWrt" "$n$([ -n "$h" ] && [ "$h" != "$n" ] && echo " ($h)")$w" "$([ "$how" = auto ] && echo warn)"
}
_si_autoupd() {
	local p=нет c=нет pause="" l ts nm fr to res note
	_au_on panel && p=да
	_au_on comp && c=да
	{ [ "$(_ver_mode)" != day ] || [ -f "$WATCH_OFF" ]; } && pause=" · на паузе: нужен «Раз в день» и «Фоновые проверки»"
	_si_row "Автообновление панели" "$p$([ "$p" = да ] && echo "$pause")" "$([ "$p" = да ] && [ -n "$pause" ] && echo warn)"
	_si_row "Автообновление компонентов" "$c$([ "$c" = да ] && echo "$pause")" "$([ "$c" = да ] && [ -n "$pause" ] && echo warn)"
	_au_live && _si_row "Автообновление сейчас" "идёт: $(cat "$AU_LOCK/cur" 2>/dev/null)" warn
	l="$(tail -n 1 "$AU_LOG" 2>/dev/null)"
	[ -n "$l" ] || return 0
	ts="$(printf '%s' "$l" | cut -f2)"; nm="$(printf '%s' "$l" | cut -f3)"; fr="$(printf '%s' "$l" | cut -f4)"
	to="$(printf '%s' "$l" | cut -f5)"; res="$(printf '%s' "$l" | cut -f6)"; note="$(printf '%s' "$l" | cut -f7)"
	case "$res" in ok) res=успешно ;; fail) res="ошибка${note:+ — $note}" ;; wait) res=ставится ;; esac
	_si_row "Последнее автообновление" "$ts · $nm ${fr:-?} → ${to:-?} · $res" "$(case "$res" in успешно) echo ok ;; ошибка*) echo bad ;; esac)"
}
_si_autobest() {
	local t l at m b bo bt co cn r k
	t="$(_za_time)"
	if [ -z "$t" ]; then _si_row "Автоподбор стратегии" "выключен" ""
	else _si_row "Автоподбор стратегии" "в $t · $(case "$(_za_mode)" in v) echo стратегии v ;; flowseal) echo Flowseal ;; youtube) echo только YouTube ;; *) echo "стратегии v и Flowseal" ;; esac)$(_za_yt && echo ' · и YouTube')" ""
	fi
	l="$(tail -n 1 "$ZA_LOG" 2>/dev/null)"
	[ -n "$l" ] || return 0
	IFS='|' read -r at m b bo bt co cn r k <<SI_ZA_EOF
$l
SI_ZA_EOF
	at="$(date -d "@$(printf '%s' "$at" | tr -cd 0-9)" '+%d.%m %H:%M' 2>/dev/null)"
	case "$r" in
		applied) r="применена $b — $bo из $bt (было $co)" ;; kept) r="оставлена ${cn:-текущая} — $co из $bt; лучшая $b — $bo" ;;
		close) r="оставлена ${cn:-текущая} — разница в пределах погрешности" ;; nochange) r="пропущен — «Не изменять стратегию»" ;;
		yoff) r="пропущен — YouTube выключен" ;; ctrl) r="пропущен — без Zapret открылось $co из $bt, похоже, трафик идёт через VPN" ;;
		none) r="лучшую определить не удалось" ;; *) r="ошибка теста" ;;
	esac
	_si_row "Последний автоподбор" "${at:+$at · }$([ "$k" = yt ] && echo 'YouTube · ')$r" "$(case "$r" in применена*) echo ok ;; ошибка*) echo bad ;; *ctrl*|*VPN*) echo warn ;; esac)"
}
_si_run() { if [ "$1" = true ]; then _si_row "${2:-Состояние}" работает ok; else _si_row "${2:-Состояние}" остановлен bad; fi; }
_si_pkgver() {
	if [ "$PKG" = apk ]; then apk list -I "$1" 2>/dev/null | awk -v p="$1" 'index($1, p "-") == 1 { v = substr($1, length(p) + 2); sub(/-r[0-9]+$/, "", v); print v; exit }'
	else _opkg_ver "$1" | sed -E 's/-r?[0-9]+$//'; fi
}

_si_memory() {
	local mt ma mf mc mb sw sf z top
	set -- $(awk '/^MemTotal:/ {t=$2} /^MemAvailable:/ {a=$2} /^MemFree:/ {f=$2} /^Cached:/ {c=$2} /^Buffers:/ {b=$2} /^SwapTotal:/ {s=$2} /^SwapFree:/ {sf=$2}
		END {print int(t/1024), int(a/1024), int(f/1024), int(c/1024), int(b/1024), int(s/1024), int(sf/1024)}' /proc/meminfo)
	mt="$1"; ma="$2"; mf="$3"; mc="$4"; mb="$5"; sw="$6"; sf="$7"
	_si_sec "Память"
	_si_row "Всего" "$mt МБ" ""
	_si_row "Занято" "$((mt - ma)) МБ ($(( (mt - ma) * 100 / (mt ? mt : 1) ))%)" "$([ $(( (mt - ma) * 100 / (mt ? mt : 1) )) -ge 85 ] && echo bad || { [ $(( (mt - ma) * 100 / (mt ? mt : 1) )) -ge 70 ] && echo warn; })"
	_si_row "Доступно" "$ma МБ" ""
	_si_row "Свободно совсем" "$mf МБ" ""
	_si_row "Кеш и буферы" "$((mc + mb)) МБ" ""
	if [ "${sw:-0}" -gt 0 ]; then _si_row "Подкачка" "занято $((sw - sf)) МБ из $sw МБ" ""; else _si_row "Подкачка" "нет" ""; fi
	z="$(cat /sys/block/zram0/disksize 2>/dev/null)"; [ -n "$z" ] && [ "$z" -gt 0 ] 2>/dev/null && _si_row "zram" "$((z / 1048576)) МБ" ""
	top="$(for f in /proc/[0-9]*/status; do awk '/^Name:/ {n=$2} /^VmRSS:/ {r=$2} END {if (r > 0) print r, n}' "$f" 2>/dev/null; done |
		awk '{s[$2] += $1} END {for (n in s) print s[n], n}' | sort -rn | head -n 6 | awk '{printf "%s%s %d МБ", (NR > 1 ? ", " : ""), $2, ($1 + 512) / 1024}')"
	[ -n "$top" ] && _si_row "Больше всех занимают" "$top" ""
	_si_end
}

_si_system() {
	local cpu n la t tz ntp
	cpu="$(sed -En 's/^(model name|cpu model|Hardware)[[:space:]]*:[[:space:]]*//p' /proc/cpuinfo 2>/dev/null | head -n1)"
	n="$(grep -c '^processor' /proc/cpuinfo 2>/dev/null)"
	la="$(cut -d' ' -f1-3 /proc/loadavg 2>/dev/null)"
	t="$(_cpu_temp 2>/dev/null)"
	tz="$(uci -q get system.@system[0].zonename)"; [ -n "$tz" ] || tz="$(uci -q get system.@system[0].timezone)"
	ntp="$(uci -q get system.ntp.enabled)"
	_si_sec "Система"
	[ -n "$cpu" ] && _si_row "Процессор" "$cpu" ""
	_si_row "Ядер" "${n:-1}" ""
	_si_row "Нагрузка (1/5/15 мин)" "${la:-—}" ""
	[ -n "$t" ] && _si_row "Температура" "$t °C" "$([ "${t%.*}" -ge 85 ] 2>/dev/null && echo bad || { [ "${t%.*}" -ge 70 ] 2>/dev/null && echo warn; })"
	_si_row "Время на роутере" "$(date '+%d.%m.%Y %H:%M')" ""
	_si_row "Часовой пояс" "${tz:-не задан}" ""
	_si_row "Синхронизация времени" "$([ "$ntp" = 0 ] && echo выключена || echo включена)" "$([ "$ntp" = 0 ] && echo warn)"
	_si_row "Пакеты" "$PKG" ""
	_si_row "Соединений" "$(cat /proc/sys/net/netfilter/nf_conntrack_count 2>/dev/null || echo —) из $(cat /proc/sys/net/netfilter/nf_conntrack_max 2>/dev/null || echo —)" ""
	_si_end
}

_si_net_more() {
	local proto v6 r band ch dis wl ifs ip fw dns
	proto="$(uci -q get network.wan.proto)"
	_si_row "Подключение к интернету" "${proto:-—}$(uci -q get network.wwan.proto >/dev/null 2>&1 && echo ' · есть wwan (Wi-Fi-клиент)')" ""
	v6="$(uci -q get network.wan6.proto)"
	_si_row "IPv6 у провайдера" "$([ -n "$v6" ] && [ "$(uci -q get network.wan6.disabled)" != 1 ] && echo "включён ($v6)" || echo выключен)" ""
	ifs="$(ip -o link show up 2>/dev/null | awk -F': ' '{print $2}' | sed 's/@.*//' | grep -vE '^(lo|ifb|gre|erspan|teql|ip6|sit|tun.?l|dummy)' | tr '\n' ' ')"
	[ -n "$ifs" ] && _si_row "Интерфейсы (включены)" "$ifs" ""
	for r in $(uci -q show wireless | sed -n "s/^wireless\.\([^.=]*\)=wifi-device$/\1/p"); do
		band="$(uci -q get "wireless.$r.band")"; ch="$(uci -q get "wireless.$r.channel")"; dis="$(uci -q get "wireless.$r.disabled")"
		wl="$(uci -q show wireless | grep -c "\.device='$r'")"
		_si_row "Wi-Fi $r" "$([ "$dis" = 1 ] && echo выключен || echo "${band:-?}, канал ${ch:-auto}, $(uci -q get "wireless.$r.htmode"), сетей: $wl")" ""
	done
	fw="$(uci -q show firewall | sed -n "s/^firewall\.\([^.=]*\)\.name='wan'$/\1/p" | head -n1)"
	[ -n "$fw" ] && _si_row "Вход из интернета" "$(uci -q get "firewall.$fw.input")" "$(case "$(uci -q get "firewall.$fw.input")" in REJECT|DROP) echo ok ;; *) echo bad ;; esac)"
	dns="$(uci -q get dhcp.@dnsmasq[0].server | wc -w)"
	_si_row "dnsmasq" "своих серверов: $dns, noresolv: $(_si_yes "$(uci -q get dhcp.@dnsmasq[0].noresolv)")" ""
}

_si_tg_ext() {
	local x v n
	for x in mtproto rust; do
		[ -f "$(_tg_auto_init "$x")" ] || continue
		v="$(_tg_tls_of "$x")"; n="$(_tg_fw_port "$x")"
		[ -n "$v" ] || [ -n "$n" ] || continue
		_si_row "TG WS Proxy $(_tg_title_of "$x")" "$([ -n "$v" ] && echo "FakeTLS ($v)" || echo "обычный ключ (dd)")$([ -n "$n" ] && echo " · порт $n открыт из интернета")" ""
	done
	return 0
}

_si_components() {
	local j v x s sec n
	_si_sec "Компоненты ZM"
	_si_row "Zapret Manager" "$ZM_VERSION" ""
	[ -f /etc/init.d/zapret ] && _si_row "Zapret" "$ZAPRET_VER · $(pgrep -f '/opt/zapre[t]/' >/dev/null && echo работает || echo остановлен)" "$(pgrep -f '/opt/zapre[t]/' >/dev/null && echo ok || echo bad)"
	[ -f /etc/init.d/zapret2 ] && _si_row "Zapret2" "$(_si_pkgver zapret2) · $(/etc/init.d/zapret2 status >/dev/null 2>&1 && echo работает || echo остановлен)" ""
	_st_installed 2>/dev/null && _si_row "Steer" "установлен" ""
	_fk_installed && _si_row "$(_fk_name)" "$(_fk_up && echo работает || echo выключен)" "$(_fk_up && echo ok)"
	[ -x /usr/bin/bytetube ] && _si_row "ByeTube" "установлен" ""
	{ [ -f /etc/init.d/tg-ws-proxy ] || [ -f "$TG_INIT_GO" ] || [ -f "$TG_INIT_RS" ]; } && _si_row "TG WS Proxy" "установлен" ""
	_si_tg_ext
	[ -x /etc/init.d/tgws ] && _si_row "sTGWS" "установлен" ""
	[ -x "$MIHOMO_BIN" ] && _si_row "Mixomo" "установлен" ""
	_ab_on && _si_row "Блокировка рекламы" "включена" ok
	[ -x "$SI_DOH_INIT" ] && _si_row "DNS over HTTPS" "установлен" ""
	_awg_installed 2>/dev/null && _si_row "AmneziaWG" "установлен" ""
	_tsc_installed && _si_row "Tailscale" "$(_tsc_vnum "$(_tsc_ver)")" ""
	_term_installed && _si_row "Терминал (ttyd)" "$(_term_version)" ""
	[ -x /usr/bin/htop ] && _si_row "htop" "установлен" ""
	_si_end

	echo "==> Смотрим компоненты ZM" >&2

	if [ -f /etc/init.d/zapret2 ]; then
		_si_sec "Zapret2"
		_si_row "Версия" "$(_si_pkgver zapret2)" ""
		_si_run "$(/etc/init.d/zapret2 status >/dev/null 2>&1 && echo true || echo false)"
		_si_row "Автозапуск" "$(ls /etc/rc.d/S*zapret2 >/dev/null 2>&1 && echo да || echo нет)" ""
		_si_end
	fi

	if _st_installed 2>/dev/null; then
		j="$(steer_status 2>/dev/null)"
		_si_sec "Steer"
		_si_row "Версия" "$(_si_j "$j" '@.version')" ""
		_si_run "$(_si_j "$j" '@.steer_running')"
		[ "$(_si_j "$j" '@.stopped')" = true ] && _si_row "Остановлен вручную" "да" warn
		v="$(_si_j "$j" '@.exit')"; x="$(_si_j "$j" '@.exit_want')"
		_si_row "Выход" "$(_si_st_exit "$v" "$j")$([ -n "$x" ] && [ "$x" != "$v" ] && echo " · выбран: $(_si_st_exit "$x" "$j")")" "$([ "$v" = none ] || [ -z "$v" ] && echo warn)"
		[ -n "$(_si_j "$j" '@.main_tun.name')" ] && _si_row "Туннель основной секции" "$(_si_j "$j" '@.main_tun.name')$([ -z "$(_si_j "$j" '@.main_tun.kind')" ] && echo " · не найден")" "$([ -z "$(_si_j "$j" '@.main_tun.kind')" ] && echo warn)"
		_si_row "WARP" "$([ "$(_si_j "$j" '@.warp_on')" = true ] && echo "включён, $([ "$(_si_j "$j" '@.warp_up')" = true ] && echo поднят || echo не поднят), режим $(_si_j "$j" '@.warp_mode'), точка $(_si_j "$j" '@.warp_colo')" || echo выключен)" "$([ "$(_si_j "$j" '@.warp_on')" = true ] && { [ "$(_si_j "$j" '@.warp_up')" = true ] && echo ok || echo bad; })"
		_si_row "VPN по подписке" "$([ "$(_si_j "$j" '@.has_sub')" = true ] && echo "есть, $([ "$(_si_j "$j" '@.vpn_up')" = true ] && echo поднят || echo не поднят)" || echo нет)" ""
		_si_row "Туннелей" "$(_si_j "$j" '@.tunnels[*]' | grep -c .)" ""
		_si_row "Каналов" "$(_si_j "$j" '@.channels')" ""
		_si_row "Сервисы" "$(_si_jl "$j" '@.services[@.on=true].name')" ""
		_si_row "Устройств с отдельными правилами" "$(_si_j "$j" '@.devices[*]' | grep -c .)" ""
		_si_row "DNS" "$([ "$(_si_j "$j" '@.dnsmode')" = router ] && echo через роутер || echo через туннель) · DoH $(_si_j "$j" '@.doh_mode')" ""
		_si_row "Если туннель упал" "$([ "$(_si_j "$j" '@.onfail')" = drop ] && echo без интернета || echo напрямую)" ""
		_si_row "Списки сервисов через VPN" "$(_si_yes "$(_si_j "$j" '@.lists_via')")" ""
		_si_row "Подписка через VPN" "$(_si_yes "$(_si_j "$j" '@.sub_via')")" ""
		_si_row "Автоперезапуск" "$(_si_every "$(_si_j "$j" '@.autorestart')")" ""
		_si_end
	fi

	if _fk_installed; then
		j="$(forkop_status 2>/dev/null)"
		_si_sec "$(_fk_name)"
		_si_row "Версия" "$(_si_j "$j" '@.version')" ""
		_si_row "sing-box" "$(_si_j "$j" '@.singbox')$( v="$(_si_j "$j" '@.singbox_pkg')"; [ -n "$v" ] && printf ' · %s' "$(_fk_sb_name "$v")")" ""
		_si_run "$(_fk_up && echo true || echo false)"
		_si_row "Автозапуск" "$(_si_yes "$(_si_j "$j" '@.enabled')")" ""
		[ "$(_si_j "$j" '@.foreign')" = true ] && _si_row "Поставлен не панелью" "да" warn
		v="$(_si_j "$j" '@.blocker_text')"; [ -n "$v" ] && _si_row "Мешает" "$v" bad
		_si_row "DNS" "$(uci -q get netshift.settings.dns_type) · $(uci -q get netshift.settings.dns_server)" ""
		_si_row "Откуда берёт трафик" "$(uci -q get netshift.settings.source_network_interfaces)" ""
		_si_row "QUIC" "$(case "$(uci -q get netshift.settings.disable_quic)" in 1) echo отклоняется в туннеле ;; all) echo отклоняется везде ;; *) echo не трогаем ;; esac)" ""
		_si_row "IPv6" "$(_si_yes "$(uci -q get netshift.settings.enable_ipv6)")" ""
		_si_row "Блокировать DoH" "$(_si_yes "$(uci -q get netshift.settings.block_doh)")" ""
		_si_row "Обновление списков" "$(uci -q get netshift.settings.update_interval)" ""
		case "$(uci -q get netshift.settings.dns_pool_mode)" in
			fallback) _si_row "Список DNS" "резерв внутри sing-box" "" ;;
			race) _si_row "Список DNS" "параллельно внутри sing-box" "" ;;
		esac
		if command -v logread >/dev/null 2>&1; then
			if logread -e sing-box 2>/dev/null | grep -qE 'panic:|fatal error:|SIGSEGV|SIGABRT'; then _si_row "Падения sing-box" "есть в журнале — подробности в отчёте Forkozz" warn
			else _si_row "Падения sing-box" "в журнале нет" ok; fi
		fi
		if [ -f /etc/init.d/zapret ] || [ -f /etc/init.d/zapret2 ]; then
			if nft list chain inet NetShiftTable mangle_output 2>/dev/null | grep -q 'meta mark & 0x[0-9a-f]* != 0x00000000 .*return'; then _si_row "Пакеты Zapret мимо Forkozz" "да" ok
			elif _fk_up; then _si_row "Пакеты Zapret мимо Forkozz" "нет — перезапустите Forkozz" warn; fi
		fi
		case "$(uci -q get netshift.settings.zm_ru)" in
			yandex) _si_row "Российские сайты (DNS)" "Яндекс DNS, мимо $(_fk_name)" "" ;;
			isp) _si_row "Российские сайты (DNS)" "DNS провайдера: $(uci -q get netshift.settings.zm_ru_ips | sed 's/ /, /g')" "" ;;
		esac
		x="$(_fk_fip_file)"
		if [ -n "$x" ] && [ "$x" != "$FK_FIP_DEF" ]; then
			if _fk_fip_stale; then _si_row "Пул Fake IP" "$x — ещё не применён, перезапустите $(_fk_name)" warn
			else _si_row "Пул Fake IP" "$x" ""; fi
		fi
		x="$(_fk_uc rlinfo 2>/dev/null)"
		v="$(_si_j "$x" '@.total')"
		if [ -n "$v" ] && [ "$v" -gt 0 ] 2>/dev/null; then
			_si_row "Серверы REALITY" "$v · с ключом X25519MLKEM768: $(_si_j "$x" '@.key') · отпечатки: $(_si_j "$x" '@.fps')" ""
			s="$(_si_j "$x" '@.learned_on')$(_si_j "$x" '@.learned_off')"
			case "$s" in ''|*[!0-9]*|00) ;; *) _si_row "Ключ подобран" "с ключом: $(_si_j "$x" '@.learned_on') · без ключа: $(_si_j "$x" '@.learned_off')" "" ;; esac
			if [ "$(_si_j "$x" '@.hook')" != true ]; then _si_row "Совместимость REALITY" "не подключена к движку — настройки панели не действуют" warn
			elif [ "$(_si_j "$x" '@.core')" = true ]; then _si_row "Ключ X25519MLKEM768" "sing-box умеет отправлять" ok
			else _si_row "Ключ X25519MLKEM768" "sing-box не умеет — нужен расширенный 2.7.2 и новее" ""; fi
		fi
		for sec in $(uci -q show netshift | sed -n "s/^netshift\.\([^.=]*\)=section$/\1/p"); do
			x="$(uci -q get "netshift.$sec.connection_type")"
			v="$(uci -q get "netshift.$sec.proxy_config_type")"
			n="$(uci -q get "netshift.$sec.community_lists")"
			_si_row "Секция $sec" "${x:-?}$([ -n "$v" ] && echo " · $v")$([ "$(uci -q get "netshift.$sec.global_proxy")" = 1 ] && echo ' · весь трафик')$([ -n "$n" ] && echo " · списки: $n")$(_fk_rl_si "$sec")" ""
		done
		_si_end
	fi

	if [ -x /usr/bin/bytetube ]; then
		j="$(/usr/bin/bytetube status 2>/dev/null)"
		_si_sec "ByeTube"
		_si_row "Включён" "$(_si_yes "$(_si_j "$j" '@.enabled')")" ""
		_si_row "ByeDPI" "$(_si_yes "$(_si_j "$j" '@.byedpi')")" "$([ "$(_si_j "$j" '@.byedpi')" = true ] && echo ok || echo bad)"
		_si_row "hev-socks5-tunnel" "$(_si_yes "$(_si_j "$j" '@.hev')")" "$([ "$(_si_j "$j" '@.hev')" = true ] && echo ok || echo bad)"
		_si_end
	fi

	if [ -f /etc/init.d/tg-ws-proxy ] || [ -f "$TG_INIT_GO" ] || [ -f "$TG_INIT_RS" ] || [ -x /etc/init.d/tgws ]; then
		j="$(tg_status 2>/dev/null)"
		_si_sec "Telegram"
		for x in mtproto:MTProto socks5:SOCKS5 rust:Rust; do
			v="${x%%:*}"
			[ "$(_si_j "$j" "@.$v")" = installed ] || continue
			_si_row "${x#*:}" "$(_si_j "$j" "@.${v}_version") · $([ "$(_si_j "$j" "@.${v}_running")" = true ] && echo работает || echo остановлен) · перезапуск: $(_si_every "$(_si_j "$j" "@.auto.$v")")" "$([ "$(_si_j "$j" "@.${v}_running")" = true ] && echo ok || echo bad)"
		done
		[ "$(_si_j "$j" '@.rust')" = installed ] && _si_row "Rust: порт" "$(_si_j "$j" '@.rust_port')" ""
		if [ -x /etc/init.d/tgws ]; then
			x="$(tgws_status 2>/dev/null)"
			_si_row "sTGWS" "$(_si_j "$x" '@.version') · $([ "$(_si_j "$x" '@.running')" = true ] && echo работает || echo остановлен) · перезапуск: $(_si_every "$(_si_j "$j" '@.auto.tgws')")" "$([ "$(_si_j "$x" '@.running')" = true ] && echo ok || echo bad)"
		fi
		_si_row "Присмотр за прокси" "$(_si_yes "$(_si_j "$j" '@.auto.watch')")" ""
		_si_end
	fi

	if [ -x "$MIHOMO_BIN" ]; then
		j="$(mixomo_status 2>/dev/null)"
		_si_sec "Mixomo"
		_si_row "Mihomo" "$(_si_j "$j" '@.mihomo_version') · $([ "$(_si_j "$j" '@.mihomo_running')" = true ] && echo работает || echo остановлен)" "$([ "$(_si_j "$j" '@.mihomo_running')" = true ] && echo ok || echo bad)"
		[ "$(_si_j "$j" '@.magitrickle')" = installed ] && _si_row "MagiTrickle" "$(_si_j "$j" '@.magitrickle_version') · $([ "$(_si_j "$j" '@.magitrickle_running')" = true ] && echo работает || echo остановлен) · список: $(_si_j "$j" '@.magitrickle_list')" ""
		[ "$(_si_j "$j" '@.hev')" = installed ] && _si_row "hev-socks5-tunnel" "$(_si_j "$j" '@.hev_version') · $([ "$(_si_j "$j" '@.hev_running')" = true ] && echo работает || echo остановлен)" ""
		_si_row "Подписка" "$([ -n "$(_si_j "$j" '@.subscription')" ] && [ "$(_si_j "$j" '@.subscription')" != false ] && echo есть || echo нет)" ""
		_si_row "Автоперезапуск" "$(_si_every "$(_si_j "$j" '@.autorestart')")" ""
		_si_end
	fi

	j="$(hosts_status 2>/dev/null)"
	n="$(_si_j "$j" '@.items[@.enabled=true].id' | grep -c .)"
	if [ "$n" -gt 0 ] || [ -n "$(_si_j "$j" '@.geohide')" ]; then
		_si_sec "Hosts"
		_si_row "Включено наборов" "$n" ""
		[ "$n" -gt 0 ] && _si_row "Наборы" "$(_si_jl "$j" '@.items[@.enabled=true].id')" ""
		_si_row "Список GeoHide" "$(_si_j "$j" '@.geohide' | sed 's/^$/нет/')" ""
		_si_end
	fi

	if _ab_on; then
		j="$(adblock_status 2>/dev/null)"
		_si_sec "Блокировка рекламы"
		_si_row "Применена" "$(_si_yes "$(_si_j "$j" '@.applied')")" "$([ "$(_si_j "$j" '@.applied')" = true ] && echo ok || echo bad)"
		_si_row "Список" "$(_si_j "$j" '@.list')" ""
		_si_row "Доменов" "$(_si_j "$j" '@.count')" ""
		_si_row "Автообновление" "$(_si_yes "$(_si_j "$j" '@.auto')")" ""
		_si_row "Блокировать DoH браузеров" "$(_si_yes "$(_si_j "$j" '@.doh')")" ""
		if [ "$(_si_j "$j" '@.stats')" = true ]; then
			_si_row "Статистика запросов" "включена$(_ab_stats_applied && echo ', работает' || echo ', dnsmasq её не подхватил')" "$(_ab_stats_applied || echo warn)"
			v="$(_ab_lf_files | tr '\n' ' ' | sed 's/ $//')"; [ -s "$AB_LF" ] && _si_row "Журнал dnsmasq" "на время статистики ведёт панель$([ -n "$v" ] && echo ", прежний вернётся: $v")" ""
		else
			v="$(_ab_stats_block)"; _si_row "Статистика запросов" "выключена$([ -n "$v" ] && echo " · не включится: log-facility задан в $v")" ""
		fi
		_si_row "Занимает в памяти" "$(( $(_si_j "$j" '@.ram_kb' | grep -o '^[0-9]*' | sed 's/^$/0/') / 1024 )) МБ" ""
		v="$(_si_j "$j" '@.err')"; [ -n "$v" ] && _si_row "Последняя ошибка" "$v" bad
		_si_end
	fi

	if [ -x "$SI_DOH_INIT" ]; then
		j="$(doh_status 2>/dev/null)"
		_si_sec "DNS over HTTPS"
		_si_run "$(_si_j "$j" '@.running')"
		_si_row "Провайдеры" "$(_si_jl "$j" '@.resolvers[*].provider')" ""
		_si_row "Серверы" "$(_si_jl "$j" '@.resolvers[*].url')" ""
		_si_row "Перехват DNS устройств" "$(_si_yes "$(_si_j "$j" '@.force_dns')") ($(_si_j "$j" '@.force_mode'))" ""
		_si_row "Запасной DNS при сбое" "$(_si_yes "$(_si_j "$j" '@.failover.on')")" ""
		_si_end
	fi

	if _awg_installed 2>/dev/null; then
		_si_sec "AmneziaWG"
		_si_row "Модуль ядра" "$(_awg_kmod_ver)" ""
		_si_row "awg-tools" "$(_si_pkgver amneziawg-tools)" ""
		n=0; v=""
		for x in $(_awg_ifaces); do n=$((n + 1)); v="$v $x($([ "$(cat "/sys/class/net/$x/operstate" 2>/dev/null)" = down ] || [ ! -d "/sys/class/net/$x" ] && echo выкл || echo вкл))"; done
		_si_row "Туннели" "$([ "$n" -gt 0 ] && echo "$n:$v" || echo нет)" ""
		_si_end
	fi

	if _tsc_installed; then
		j="$(tsc_status 2>/dev/null)"
		_si_sec "Tailscale"
		_si_row "Версия" "$(_si_j "$j" '@.version') · $(_si_j "$j" '@.source' | sed 's/^$/неизвестно откуда/')" ""
		_si_run "$(_si_j "$j" '@.running')" "Служба"
		_si_row "Вход" "$(_si_j "$j" '@.state')" "$([ "$(_si_j "$j" '@.state')" = Running ] && echo ok || echo warn)"
		_si_row "Сервер" "$(case "$(_si_j "$j" '@.server_kind')" in routerich) echo Routerich ;; custom) echo свой сервер ;; *) echo Tailscale ;; esac)" ""
		_si_row "Выход в интернет" "$([ "$(_si_j "$j" '@.exit_want')" = true ] && { [ "$(_si_j "$j" '@.exit_ok')" = true ] && echo одобрен || echo ждёт одобрения; } || echo выключен)" ""
		_si_row "Доступ к домашней сети" "$([ "$(_si_j "$j" '@.lan_want')" = true ] && { [ "$(_si_j "$j" '@.lan_ok')" = true ] && echo одобрен || echo ждёт одобрения; } || echo выключен)" ""
		_si_row "Настройки Tailscale" "$([ "$(_si_j "$j" '@.prefs_ok')" = false ] && echo сбились || echo в порядке)" "$([ "$(_si_j "$j" '@.prefs_ok')" = false ] && echo bad || echo ok)"
		v="$(_si_j "$j" '@.key_expiry')"; _si_row "Вход роутера" "$([ -n "$v" ] && echo "до ${v%%T*}" || echo бессрочный)" ""
		_si_row "Forkozz для телефона" "$(_si_yes "$(_si_j "$j" '@.fk_ok')")" ""
		v="$(_si_j "$j" '@.term_mode')"; [ -n "$v" ] && _si_row "Терминал через Tailscale" "$([ "$v" = all ] || [ "$v" = ts ] && echo открывается || echo только дома)" ""
		_si_row "Страница в LuCI" "$(_si_yes "$(_si_j "$j" '@.luci_app')")" ""
		_si_end
	fi

	if _term_installed; then
		_si_sec "Терминал"
		_si_run "$(_term_running && echo true || echo false)"
		_si_row "Где открывается" "$(case "$(_term_mode)" in all) echo дома и через Tailscale ;; ts) echo только Tailscale ;; other) echo "интерфейс $(_term_iface)" ;; *) echo только дома ;; esac)" ""
		_si_row "Порт" "$(_term_port)" ""
		_si_end
	fi

	_si_sec "Панель Zapret Manager"
	_si_row "Версия" "$ZM_VERSION" ""
	_si_row "Фоновые проверки" "$([ -f "$WATCH_OFF" ] && echo выключены || echo включены)" "$([ -f "$WATCH_OFF" ] && echo warn)"
	_si_row "Поиск обновлений" "$(case "$(_ver_mode)" in day) [ "$(_ver_every)" = 24 ] && echo "раз в сутки, в $(_ver_time)" || echo "каждые $(_ver_every) ч, с $(_ver_time)"; _ver_bg || echo " (фоновые проверки выключены)" ;; open) echo при открытии ;; *) echo по кнопке ;; esac | tr -d '\n')" ""
	_si_row "Ставить найденное" "$([ "$(_ver_every)" != 24 ] && [ "$(_au_when)" = now ] && echo "сразу после проверки" || echo "в $(_ver_time)")" ""
	_si_autoupd
	v="$(cat "$ZM_STATE_DIR/ui.theme" 2>/dev/null)"; _si_row "Тема Web UI" "${v:-авто}" ""
	v="$(ui_nav_get)"; [ -n "$v" ] && _si_row "Скрыто в меню" "$v" ""
	_si_row "Задания cron панели" "$(grep -c 'zapret-manager\|zm-' "$CRON_FILE" 2>/dev/null)" ""
	_si_end
}


_si_ping() {
	local t
	t="$(ping "$1" -c 1 -W 2 google.com 2>/dev/null | sed -n 's/.*time=\([0-9.]*\).*/\1/p' | head -n1)"
	if [ -z "$t" ] && [ "$1" = -6 ] && t="$(_zm_v6_ms $ZM_V6_ADDRS)"; then
		_si_row "$2" "работает, $t мс; DNS роутера IPv6-адреса сайтов не отдаёт" ok
		return
	fi
	[ -n "$t" ] && _si_row "$2" "работает, $t мс" ok || _si_row "$2" "нет связи" bad
}

_si_sites() {
	local list="$1" res="$2" i=0 n e name url
	: > "$res"
	while IFS= read -r e; do
		[ -n "$e" ] || continue
		i=$((i + 1))
		name="${e%%|*}"; url="${e#*|}"
		(
			if curl -sL --connect-timeout 3 --max-time 5 --speed-time 3 --speed-limit 1 --range 0-65535 -A "Mozilla/5.0 (Windows NT 10.0; Win64; x64) curl/8.0" -o /dev/null "$url" >/dev/null 2>&1; then
				echo "$i|$name|1" >> "$res"
			else
				echo "$i|$name|0" >> "$res"
			fi
		) &
		[ $((i % 10)) = 0 ] && wait
	done < "$list"
	wait
}

do_sysinfo() {
	local rel arch model kern up d h m mt mf ft fu fa tt tu sw hw fix t prov rate st zv zs zr tcp udp opt hosts pk sites fkr ok=0 all=0 name v list="$JOBS_DIR/sysinfo.urls" res="$JOBS_DIR/sysinfo.res" out="$SI_OUT.tmp"
	echo "==> Собираем данные о роутере"
	rel="$(. /etc/openwrt_release 2>/dev/null; echo "$DISTRIB_RELEASE")"
	arch="$(. /etc/openwrt_release 2>/dev/null; echo "$DISTRIB_ARCH")"
	model="$(cat /tmp/sysinfo/model 2>/dev/null)"
	[ -n "$model" ] || model="$(jsonfilter -s "$(ubus call system board 2>/dev/null)" -e '@.model' 2>/dev/null)"
	kern="$(uname -r)"
	up="$(cut -d. -f1 /proc/uptime 2>/dev/null)"; up="${up:-0}"
	d=$((up / 86400)); h=$((up % 86400 / 3600)); m=$((up % 3600 / 60))
	mt="$(awk '/^MemTotal:/ {print int($2 / 1024)}' /proc/meminfo)"
	mf="$(awk '/^MemAvailable:/ {print int($2 / 1024)}' /proc/meminfo)"
	fa="$(df -k /overlay 2>/dev/null | awk 'NR==2 {print $2, $3, $4}')"
	[ -n "$fa" ] || fa="$(df -k / 2>/dev/null | awk 'NR==2 {print $2, $3, $4}')"
	set -- $fa; ft="$1"; fu="$2"
	set -- $(df -k /tmp 2>/dev/null | awk 'NR==2 {print $2, $3}'); tt="$1"; tu="$2"
	sw="$(uci -q get firewall.@defaults[0].flow_offloading)"
	hw="$(uci -q get firewall.@defaults[0].flow_offloading_hw)"
	fix="$(_flow_offloading_fix_applied)"

	{
		printf '{"ts":"%s","sections":[' "$(date '+%d.%m.%Y %H:%M')"
		SI_SEP=""
		printf '{"title":"Роутер","rows":['
		_si_row "Модель" "${model:-—}" ""
		_si_row "OpenWrt" "${rel:-—}" ""
		_si_row "Архитектура" "${arch:-—}" ""
		_si_row "Ядро" "$kern" ""
		_si_row "Работает" "$([ "$d" -gt 0 ] && printf '%s д ' "$d")$(printf '%d ч %02d мин' "$h" "$m")" ""
		[ -n "$ft" ] && _si_row "Флеш" "занято $((fu / 1024)) МБ из $((ft / 1024)) МБ" ""
		[ -n "$tt" ] && _si_row "/tmp" "занято $((tu / 1024)) МБ из $((tt / 1024)) МБ" ""
		_si_mirror
		printf ']}'
		_si_memory
		_si_system
	} > "$out"

	echo "==> Проверяем сеть"
	prov="$(curl -fsSL --connect-timeout 3 --max-time 5 https://ipinfo.io/org 2>/dev/null | sed -E 's/^AS[0-9]+ ?//; s/\b(OJSC|PJSC|JSC|LLC|Inc\.?|Ltd\.?)\b//g; s/[.,]//g; s/  +/ /g; s/^ +| +$//g')"
	rate="$(curl -fsS --connect-timeout 3 --max-time 5 https://api.github.com/rate_limit 2>/dev/null | grep -o '"remaining":[[:space:]]*[0-9]*' | head -n1 | grep -o '[0-9]*$')"
	{
		SI_SEP=""
		printf ',{"title":"Сеть","rows":['
		[ -n "$prov" ] && _si_row "Провайдер" "$prov" ""
		_si_ping -4 "Google по IPv4"
		_si_ping -6 "Google по IPv6"
		if [ -n "$rate" ]; then
			[ "$rate" -gt 0 ] && _si_row "GitHub API" "работает, лимит $rate" ok || _si_row "GitHub API" "лимит исчерпан" bad
		else
			_si_row "GitHub API" "недоступен" bad
		fi
		if [ "$hw" = 1 ] && [ "$sw" = 1 ]; then _si_row "Flow Offloading" "аппаратный" warn
		elif [ "$sw" = 1 ]; then _si_row "Flow Offloading" "программный" warn
		else _si_row "Flow Offloading" "выключен" ok; fi
		[ "$fix" = true ] && _si_row "Поправка для Zapret" "применена" ok || _si_row "Поправка для Zapret" "не применена$([ -f "$FT_ZAPRET_OFF" ] && echo ' (отключена вручную)')" "$([ "$sw" = 1 ] && echo bad)"
		stl_present && { _ft_steer_applied && _si_row "Поправка для Steer" "применена — соединения Steer не выгружаются" ok || _si_row "Поправка для Steer" "не применена$([ -f "$FT_STEER_OFF" ] && echo ' (отключена вручную)') — соединения Steer выгружаются" "$([ "$sw" = 1 ] && echo bad)"; }
		_si_row "Блокировка QUIC" "$([ "$(_quic_blocked)" = true ] && echo "включена (UDP 80 и 443)" || echo выключена)" ""
		if /etc/init.d/https-dns-proxy running >/dev/null 2>&1 && [ -f /etc/config/https-dns-proxy ]; then
			sed -n "s/^[[:space:]]*option resolver_url '\([^']*\)'.*/\1/p" /etc/config/https-dns-proxy | while IFS= read -r v; do _si_row "DNS over HTTPS" "$v" ""; SI_SEP=","; done
		fi
		_si_net_more
		printf ']}'
	} >> "$out"

	fkr=""
	if _fk_installed && ! _fk_foreign && grep -q '^support_report)' /usr/bin/netshift 2>/dev/null; then
		echo "==> Собираем отчёт Forkozz"
		if fkr="$(_zm_run 60 /usr/bin/netshift support_report 2>/dev/null)" && printf '%s\n' "$fkr" | head -n 1 | grep -q 'support report'; then
			fkr="$(printf '%s\n' "$fkr" | head -c 150000 | sed 's/NetShift/Forkozz/g')"
		else
			fkr=""
			echo "   · отчёт Forkozz собрать не удалось — остальное собрано"
		fi
	fi
	echo "==> Смотрим Zapret"
	st="$(status)"
	zv="$(jsonfilter -s "$st" -e '@.zapret_version' 2>/dev/null)"
	zr="$(jsonfilter -s "$st" -e '@.zapret_running' 2>/dev/null)"
	zs="$(jsonfilter -s "$st" -e '@.strategy' 2>/dev/null)"
	{
		SI_SEP=""
		printf ',{"title":"Zapret","rows":['
		if [ -f /etc/init.d/zapret ]; then
			_si_row "Состояние" "$([ "$zr" = true ] && echo запущен || echo остановлен)" "$([ "$zr" = true ] && echo ok || echo bad)"
			_si_row "Версия" "${zv:-—}" ""
			_si_row "Стратегия" "${zs:-—}" ""
			tcp="$(sed -n "s/^[[:space:]]*option NFQWS_PORTS_TCP[[:space:]]*'\(.*\)'.*/\1/p" "$CONF" | head -n1)"
			udp="$(sed -n "s/^[[:space:]]*option NFQWS_PORTS_UDP[[:space:]]*'\(.*\)'.*/\1/p" "$CONF" | head -n1)"
			_si_row "Порты TCP" "${tcp:-—}" ""
			_si_row "Порты UDP" "${udp:-—}" ""
			_si_row "Порты из стратегии" "$([ -f "$ZP_MANUAL" ] && echo "нет, заданы вручную" || echo "да, сверяются при перезапуске")" ""
			_si_row "IPv6 в Zapret" "$([ "$(_ipv6_enabled_in_zapret)" = true ] && echo включён || echo выключен)" ""
			_si_row "Автозапуск" "$(ls /etc/rc.d/S*zapret >/dev/null 2>&1 && echo да || echo нет)" "$(ls /etc/rc.d/S*zapret >/dev/null 2>&1 || echo bad)"
			_si_row "Режим списков" "$(if [ "$(jsonfilter -s "$st" -e '@.rkn_on' 2>/dev/null)" = true ]; then echo "только списки РКН ($(jsonfilter -s "$st" -e '@.rkn_count' 2>/dev/null) доменов)"; elif [ "$(jsonfilter -s "$st" -e '@.ulist_on' 2>/dev/null)" = true ]; then echo "только свой список ($(jsonfilter -s "$st" -e '@.ulist_count' 2>/dev/null))"; else echo "все сайты, кроме исключений"; fi)" ""
			_si_row "QUIC для YouTube" "$(_si_yes "$(jsonfilter -s "$st" -e '@.quic_yt' 2>/dev/null)")" ""
			_si_row "wssize" "$(_si_yes "$(jsonfilter -s "$st" -e '@.wssize' 2>/dev/null)")" ""
			_si_row "--ip-id=zero для YouTube" "$(_si_yes "$(jsonfilter -s "$st" -e '@.ipid' 2>/dev/null)")" ""
			_si_row "Режим эксперта" "$(_si_yes "$(jsonfilter -s "$st" -e '@.expert' 2>/dev/null)")" ""
			v="$(jsonfilter -s "$st" -e '@.flowseal' 2>/dev/null)"; [ -n "$v" ] && _si_row "Стратегия Flowseal" "$v" ""
			_si_row "Исключений" "$(grep -c . /opt/zapret/ipset/zapret-hosts-user-exclude.txt 2>/dev/null || echo 0)" ""
			_si_autobest
		else
			_si_row "Состояние" "не установлен" ""
		fi
		printf ']}'
		_si_components
		printf ']'
		opt=""
		[ -f "$CONF" ] && opt="$(uci -q get zapret.config.NFQWS_OPT 2>/dev/null)"
		printf ',"strategy":"%s"' "$(esc_ml "$(_si_clean "$opt")")"
		printf ',"fk_report":"%s"' "$(esc_ml "$(_si_mask "$(_si_clean "$fkr")")")"
		hosts=""
		if [ -f "$HOSTS_FILE" ] && ! grep -qE 'geohide\.ru|mafioznik|dns\.malw\.link' "$HOSTS_FILE"; then
			hosts="$(grep '^#' "$HOSTS_FILE" | cut -c2- | sed 's/^[[:space:]]*//' | grep -v '^$' | while IFS= read -r v; do printf '"%s",' "$(esc "$(_si_clean "$v")")"; done)"
		fi
		printf ',"hosts":[%s]' "${hosts%,}"
		pk="$(_si_user_pkgs)"
		printf ',"packages":[%s]' "$(printf '%s\n' "$pk" | grep -v '^$' | while IFS= read -r v; do printf '"%s",' "$(esc "$v")"; done | sed 's/,$//')"
	} >> "$out"

	_test_prepare_urls "$list"
	all="$(grep -c '|' "$list")"
	echo "==> Проверяем доступность сайтов: $all"
	_zm_wait "" _si_sites "$list" "$res"
	ok="$(grep -c '|1$' "$res")"
	{
		printf ',"sites_ok":%s,"sites_total":%s,"sites":[' "${ok:-0}" "${all:-0}"
		sort -t'|' -k1,1n "$res" | awk -F'|' "$ZM_JESC_AWK"'{ printf "%s{\"name\":\"%s\",\"ok\":%s}", (n++ ? "," : ""), jesc($2), ($3 == 1 ? "true" : "false") }'
		printf ']}\n'
	} >> "$out"
	rm -f "$list" "$res"
	mv "$out" "$SI_OUT"
	echo "==> Готово: сайты открываются $ok из $all"
}

_si_user_pkgs() {
	local t0
	if [ "$PKG" = apk ]; then
		if [ -s /rom/etc/apk/world ]; then
			sed 's/[<>=~].*//' /rom/etc/apk/world | sort -u > "$JOBS_DIR/si.rom"
			sed 's/[<>=~].*//' /etc/apk/world 2>/dev/null | sort -u | grep -vxF -f "$JOBS_DIR/si.rom"
		else
			sed 's/[<>=~].*//' /etc/apk/world 2>/dev/null | sort -u
		fi
	elif [ -s /rom/usr/lib/opkg/status ]; then
		awk '/^Package:/ {p = $2} /^Status: install user/ {print p}' /rom/usr/lib/opkg/status | sort -u > "$JOBS_DIR/si.rom"
		awk '/^Package:/ {p = $2} /^Status: install user/ {print p}' /usr/lib/opkg/status 2>/dev/null | sort -u | grep -vxF -f "$JOBS_DIR/si.rom"
	else
		t0="$(awk '/^Installed-Time:/ {print $2}' /usr/lib/opkg/status 2>/dev/null | sort -n | head -n1)"
		awk -v t0="${t0:-0}" '/^Package:/ {p = $2; u = 0} /^Status: install user/ {u = 1} /^Installed-Time:/ { if (u && $2 > t0 + 600) print p }' /usr/lib/opkg/status 2>/dev/null | sort -u
	fi
	rm -f "$JOBS_DIR/si.rom"
}

sysinfo_run() {
	job_start sysinfo do_sysinfo
}

sysinfo_get() {
	[ -s "$SI_OUT" ] && cat "$SI_OUT" || echo '{"sections":[]}'
}

AB_DIR="$ZM_STATE_DIR/adblock"
AB_SET="$AB_DIR/settings"
AB_ALLOW="$AB_DIR/allow.txt"
AB_BLOCK="$AB_DIR/block.txt"
AB_NAME="zm-adblock.conf"
AB_CRON_TAG="# zm-adblock"
AB_FREE="$AB_DIR/free.txt"
AB_FREE_PORT=53535
AB_FREE_CONF="/var/etc/zm-adblock-free.conf"
AB_FREE_PID="/var/run/zm-adblock-free.pid"
AB_FREE_NFT="zm_adblock_free"
AB_STATS_CONF="zm-adblock-stats.conf"
AB_STATS_LOG="/var/run/dnsmasq/zm-queries.log"
AB_STATS_DIR="/tmp/zm-adblock-stats"
AB_STATS_CRON="# zm-abstats"
AB_STATS_ALL="$AB_DIR/stats-all.txt"
_ab_devmap() {
	{
		printf 'R\t127.0.0.1\nR\t::1\n'
		ip -o addr show | awk '{ a = $4; sub(/\/.*/, "", a); if (a != "") printf "R\t%s\n", a }'
		awk 'NR > 1 && $4 ~ /^([0-9a-fA-F]{2}:){5}[0-9a-fA-F]{2}$/ && $4 != "00:00:00:00:00:00" { printf "M\t%s\t%s\n", $1, tolower($4) }' /proc/net/arp
		ip neigh show | awk '{ for (i = 2; i < NF; i++) if ($i == "lladdr") { printf "M\t%s\t%s\n", $1, tolower($(i + 1)); break } }'
		awk '$2 ~ /^([0-9a-fA-F]{2}:){5}[0-9a-fA-F]{2}$/ && $3 != "" { m = tolower($2); printf "M\t%s\t%s\nF\t%s\t%s\n", $3, m, m, $3; if ($4 != "" && $4 != "*") printf "N\t%s\t%s\n", m, $4 }' /tmp/dhcp.leases
		uci -q -X show dhcp | awk -F= '{ split($1, p, "."); v = $2; gsub("\047", "", v) }
			p[3] == "name" { nm[p[2]] = v } p[3] == "mac" { mc[p[2]] = tolower(v) }
			END { for (k in nm) if (k in mc) { n = split(mc[k], a, " "); for (i = 1; i <= n; i++) printf "N\t%s\t%s\n", a[i], nm[k] } }'
		awk '$1 !~ /^#/ && $1 ~ /:/ && NF >= 2 { n = $NF; sub(/\..*/, "", n); if (n != "") printf "H\t%s\t%s\n", $1, n }' /tmp/hosts/odhcpd
	} 2>/dev/null
}
AB_KEY_AWK='
function abmap(f,   l, a) { while ((getline l < f) > 0) { split(l, a, "\t"); if (a[1] == "R") R[a[2]] = 1; else if (a[1] == "M") M[a[2]] = a[3]; else if (a[1] == "F") F4[a[2]] = a[3]; else if (a[1] == "N") N[a[2]] = a[3]; else if (a[1] == "H") H[a[2]] = a[3] } close(f) }
function abkey(k) { if (k == "r" || k ~ /^[mn]:/) return k; if (k in R) return "r"; if (k in M) return "m:" M[k]; if (k in H) return "n:" H[k]; return k }
'
AB_URL_GH="${GH_RAW}/hagezi/dns-blocklists/main/dnsmasq"
AB_URL_CDN="https://cdn.jsdelivr.net/gh/hagezi/dns-blocklists@latest/dnsmasq"
AB_ALLOW_DEFAULT='# Переходы по рекламе в поиске Яндекса
yabs.yandex.ru
redirect.appmetrica.yandex.com
trk.mail.ru
s.click.aliexpress.com'

_ab_say() { echo "==> $*"; }
_ab_get() {
	local v
	v="$(_kv_last "$AB_SET" "$1")"
	echo "${v:-$2}"
}
_ab_put() {
	local k v tmp="$AB_SET.zm-new.$$"
	mkdir -p "$AB_DIR"
	[ -f "$AB_SET" ] || : > "$AB_SET"
	cp -f "$AB_SET" "$tmp"
	while [ $# -ge 2 ]; do
		k="$1"; v="$2"; shift 2
		grep -v "^$k=" "$tmp" > "$tmp.2" 2>/dev/null; mv -f "$tmp.2" "$tmp"
		echo "$k=$v" >> "$tmp"
	done
	mv -f "$tmp" "$AB_SET"
}
_ab_file() {
	case "$1" in
		light) echo light.txt ;; multi) echo multi.txt ;; pro) echo pro.txt ;;
		proplus) echo pro.plus.txt ;; ultimate) echo ultimate.txt ;;
		tif) echo tif.mini.txt ;; doh) echo doh.txt ;; *) return 1 ;;
	esac
}
_ab_title() {
	case "$1" in
		light) echo Light ;; multi) echo Multi ;; pro) echo Pro ;; proplus) echo "Pro++" ;;
		ultimate) echo Ultimate ;; tif) echo "TIF mini (фишинг)" ;; doh) echo "чужих DoH-серверов" ;; *) echo "$1" ;;
	esac
}
_ab_min() {
	case "$1" in
		light) echo 20000 ;; multi|pro|proplus|ultimate) echo 60000 ;; tif) echo 80000 ;; doh) echo 1000 ;;
	esac
}
_ab_gz() { command -v gzip >/dev/null 2>&1; }
_ab_src() { if [ -s "$AB_DIR/src/$1.gz" ]; then echo "$AB_DIR/src/$1.gz"; elif [ -s "$AB_DIR/src/$1.txt" ]; then echo "$AB_DIR/src/$1.txt"; else return 1; fi; }
_ab_cat() {
	local f
	f="$(_ab_src "$1")" || return 1
	case "$f" in *.gz) gzip -dc "$f" ;; *) cat "$f" ;; esac
}
_ab_num() { echo "${1:-0}" | awk '{ s = $1; o = ""; while (length(s) > 3) { o = " " substr(s, length(s) - 2) o; s = substr(s, 1, length(s) - 3) } print s o }'; }
_ab_dom() { echo "$(_ab_num "$1") $(echo "${1:-0}" | awk '{ n = $1 % 100; m = $1 % 10; print (n >= 11 && n <= 14) ? "доменов" : (m == 1 ? "домен" : (m >= 2 && m <= 4 ? "домена" : "доменов")) }')"; }
_ab_on() { [ "$(_ab_get on 0)" = 1 ]; }
_ab_ids() {
	local ids
	ids="$(_ab_get list pro)"
	[ "$(_ab_get tif 0)" = 1 ] && ids="$ids tif"
	[ "$(_ab_get doh 0)" = 1 ] && ids="$ids doh"
	echo "$ids"
}
_ab_dirs() {
	local d
	d="$(sed -n 's/^conf-dir=\([^,]*\).*/\1/p' /var/etc/dnsmasq.conf.* 2>/dev/null | sort -u)"
	echo "${d:-/tmp/dnsmasq.d}"
}
_ab_applied() {
	local d n=0
	for d in $(_ab_dirs); do [ -s "$d/$AB_NAME" ] || return 1; n=1; done
	[ "$n" = 1 ]
}
_ab_dns_rss() {
	local p t=0 v
	for p in $(pidof dnsmasq 2>/dev/null); do
		v="$(awk '/^VmRSS:/ { print $2 }' "/proc/$p/status" 2>/dev/null)"
		t=$((t + ${v:-0}))
	done
	echo "$t"
}
_ab_dns_alive() { pidof dnsmasq >/dev/null 2>&1 && { nslookup localhost 127.0.0.1 >/dev/null 2>&1 || nslookup openwrt.org 127.0.0.1 >/dev/null 2>&1; }; }

_ab_doh_router_hosts() {
	local i=0 u
	while u="$(uci -q get "https-dns-proxy.@https-dns-proxy[$i].resolver_url")"; do
		printf '%s\n' "$u" | sed -n 's#^[a-z]*://\([^/:]*\).*#\1#p'
		i=$((i + 1))
	done
}
_ab_own_hosts() {
	_ab_doh_router_hosts
	_ab_dns_hosts
	_ab_tg_hosts
	_ab_never
}
