const B4_SUBNETS = { adobe: true, anthropic: true, apple: true, blizzard: true, bungie: true, ccp: true, electronicarts: true,
	epicgames: true, google: true, nintendo: true, play2go: true, riot: true, roblox: true, sony: true, taketwo: true,
	ubisoft: true, valve: true, wargaming: true };
const PKG_LOCAL_DIR = "/usr/share/zm-redbtn/svc/";
const V2F_RAW = "https://raw.githubusercontent.com/v2fly/domain-list-community/master/data";
const PKG_LISTS = {
	"svc_v2meta.lst": V2F_RAW + "/meta",
	"svc_threads.lst": V2F_RAW + "/threads",
	"svc_oculus.lst": V2F_RAW + "/oculus",
	"svc_instagram.lst": V2F_RAW + "/instagram",
	"svc_instagram_extra.lst": PKG_LOCAL_DIR + "instagram_extra.lst",
	"svc_facebook.lst": V2F_RAW + "/facebook",
	"svc_messenger.lst": V2F_RAW + "/messenger",
	"svc_whatsapp.lst": V2F_RAW + "/whatsapp",
	"svc_whatsapp_extra.lst": PKG_LOCAL_DIR + "whatsapp_extra.lst",
	"meta.lst": ITD_RAW + "/Subnets/IPv4/meta.lst"
};
const SCHEMES = /^(vless|vmess|trojan|ss|socks4|socks4a|socks5|hysteria2|hy2):\/\/[^ \t\r\n]+$/i;
const SCHEMES_NAIVE = /^naive\+(https|quic):\/\/[^ \t\r\n@]+@[^ \t\r\n]+$/i;
const BYPASS = "zm_bypass";
const SUB_IVS = [ "30m", "1h", "3h", "6h", "12h", "1d" ];
const LIST_IVS = [ "1h", "3h", "12h", "1d", "3d" ];
const LINK_KEYS = [ "proxy_string", "selector_proxy_links", "urltest_proxy_links", "selector_proxy_links_text", "urltest_proxy_links_text" ];

function s(v) { return v == null ? "" : "" + v; }

function pkg_local(v) {
	v = s(v);
	return index(v, PKG_LOCAL_DIR) == 0 && !!match(v, /^\/[A-Za-z0-9_\/.-]+\.lst$/) && index(v, "..") < 0;
}

function ml(v) { return type(v) == "string" && (index(v, "\n") >= 0 || index(v, "\r") >= 0); }

function out(v) { print(sprintf("%J", v), "\n"); }

function fail(msg) { out({ error: msg }); exit(1); }

function arr(v) {
	if (v == null) return [];
	if (type(v) == "array") return filter(map(v, (x) => trim(s(x))), (x) => x != "");
	let t = trim(s(v));
	return t == "" ? [] : [ t ];
}

function words(v) {
	let r = [];
	for (let x in arr(v))
		for (let w in split(x, /[ \t\r\n]+/))
			if (w != "") push(r, w);
	return r;
}

function lines(v) {
	let r = [];
	for (let x in (type(v) == "array" ? v : [ v ]))
		for (let l in split(s(x), /[\r\n]+/)) {
			l = trim(l);
			if (l != "" && !match(l, /^(#|\/\/)/)) push(r, l);
		}
	return r;
}

function tokens(v) {
	let r = [];
	for (let l in lines(v))
		for (let w in split(replace(l, /[ \t]+(#|\/\/).*$/, ""), /[ \t,;]+/))
			if (w != "") push(r, w);
	return r;
}

function uniq(list) {
	let seen = {}, r = [];
	for (let x in list)
		if (!seen[x]) { seen[x] = true; push(r, x); }
	return r;
}

function rawlist(v) {
	if (v == null) return [];
	if (type(v) != "array") v = [ v ];
	return filter(map(v, (x) => s(x)), (x) => x != "");
}

function sh(cmd) {
	let p = fs.popen(cmd + " 2>/dev/null", "r");
	if (!p) return "";
	let d = p.read("all");
	p.close();
	return s(d);
}

let GML = null;
function gml_env() {
	if (GML == null) {
		GML = "";
		let mi = s(fs.readfile("/proc/meminfo")), mm = match(mi, /MemTotal:[ \t]*([0-9]+)/);
		if (mm) {
			let mb = int(int(mm[1]) / 8192);
			GML = "GOMEMLIMIT=" + (mb < 16 ? 16 : mb > 128 ? 128 : mb) + "MiB ";
		}
	}
	return GML;
}

function jcmd(cmd) {
	let t = trim(sh(cmd));
	if (t == "") return null;
	try { return json(t); } catch (e) {}
	let i = rindex(t, "\n{");
	if (i >= 0) try { return json(substr(t, i + 1)); } catch (e) {}
	return null;
}

function q(v) { return "'" + replace(s(v), /'/g, "'\\''") + "'"; }

function cursor() {
	let dir = getenv("ZM_FK_CONFDIR");
	let c = dir ? uci.cursor(dir) : uci.cursor();
	c.load(CFG);
	return c;
}

function sections(c, t) {
	let r = [];
	c.foreach(CFG, t, (x) => { push(r, x); });
	return r;
}

function services_list() {
	let txt = s(fs.readfile(NS_LIB + "/constants.sh"));
	let m = match(txt, /\nCOMMUNITY_SERVICES="([^"]*)"/);
	let l = m ? filter(split(trim(m[1]), /[ \t]+/), (x) => match(x, /^[a-z0-9_]+$/)) : [];
	return length(l) ? l : SERVICES_BASE;
}


function latest_url(u) {
	return replace(s(u), /^(https:\/\/github\.com\/[^\/]+\/[^\/]+\/releases\/)download\/[^\/]+\//, "$1latest/download/");
}

function b4_name(u) {
	let m = match(s(u), /^https:\/\/(github\.com\/greeg0ry\/b4geoip-forkop\/releases\/(latest\/download|download\/[^\/]+)|raw\.githubusercontent\.com\/greeg0ry\/b4geoip-forkop\/(refs\/heads\/)?main\/srs)\/([a-z0-9_-]+)\.srs$/i);
	return m ? lc(m[4]) : null;
}

function b4_ref(n) {
	return { k: B4_DOMAINS[n] ? "s" : B4_SUBNETS[n] ? "n" : "r", u: B4_RAW + n + ".srs" };
}

function refs_fix(r) {
	let o = { c: r.c || [], s: [], r: [], n: [], l: r.l || [] };
	for (let k in [ "s", "r", "n" ]) for (let u in (r[k] || [])) {
		let b = b4_name(u), x = b ? b4_ref(b) : { k, u };
		push(o[x.k], x.u);
	}
	o.s = uniq(o.s); o.r = uniq(o.r); o.n = uniq(o.n);
	return o;
}

function kind_hint(u) {
	u = lc(s(u));
	for (let w in [ "geosite", "domain", "adguard", "filter" ]) if (index(u, w) >= 0) return "domains";
	for (let w in [ "geoip", "subnet", "cidr" ]) if (index(u, w) >= 0) return "subnets";
	return "unknown";
}

function itd_name(u) {
	let m = match(s(u), /allow-domains\/.*\/([A-Za-z0-9_]+)\.srs$/);
	return m ? lc(m[1]) : null;
}

function itd_plain(n) {
	let t = [ "l:" + ITD_RAW + "/Services/" + n + ".lst" ];
	if (ITD_SUBNETS[n]) push(t, "l:" + ITD_RAW + "/Subnets/IPv4/" + n + ".lst");
	return t;
}

function set_tokens(set, known) {
	if (known[set]) return [ "c:" + set ];
	if (EXTRA_SRS[set]) return [ "s:" + EXTRA_SRS[set] ];
	return itd_plain(set);
}

function idx_tokens(e, known) {
	let n = itd_name(e.url);
	if (n && known[n]) return [ "c:" + n ];
	if (e.fmt == "lst") return [ "l:" + e.url ];
	if (n) return itd_plain(n);
	let b4 = b4_name(e.url);
	if (b4) { let x = b4_ref(b4); return [ x.k + ":" + x.u ]; }
	let u = latest_url(e.url);
	if (e.kind == "d") return [ "s:" + u ];
	if (kind_hint(u) == "domains") return [];
	return [ "r:" + u ];
}

function catalog_items(known_list) {
	let known = {}, items = [], seen = {}, idx = {};
	for (let k in known_list) known[k] = true;
	for (let l in split(s(fs.readfile(RB_CONF)), "\n")) {
		if (l == "" || substr(l, 0, 1) == "#") continue;
		let f = split(l, "|"), id = f[0], t = [];
		if (!id || id == "custom" || seen[id]) continue;
		if (s(f[2]) + s(f[3]) + s(f[7]) == "") continue;
		if (id == "github") t = set_tokens("github", known);
		else if (s(f[7]) == "") {
			for (let fl in [ ...split(s(f[2]), ","), ...split(s(f[3]), ",") ])
				if (PKG_LISTS[fl]) push(t, "l:" + PKG_LISTS[fl]);
		}
		else for (let set in split(s(f[7]), ",")) {
			if (set == "") continue;
			t = [ ...t, ...set_tokens(set, known) ];
		}
		if (!length(t)) continue;
		seen[id] = true;
		push(items, { id, name: s(f[1]) || id, group: "", targets: uniq(t) });
	}
	if (fs.access(ST_DIR + "/catalog.off")) return items;
	for (let l in split(s(fs.readfile(ST_DIR + "/catalog.idx")), "\n")) {
		let f = split(l, "|");
		if (length(f) >= 3 && f[0] != "" && match(f[2], /^https:\/\//))
			idx[f[0]] = { fmt: f[1], url: f[2], kind: s(f[3]) };
	}
	let covered = {};
	for (let it in items) for (let tk in it.targets) covered[tk] = true;
	for (let l in split(s(fs.readfile(ST_DIR + "/services.remote")), "\n")) {
		let f = split(l, "|"), id = f[0], grp = s(f[8]), t = [], cat = false;
		if (!id || seen[id] || grp == "" || grp == "Свои списки каталога") continue;
		if (CAT_SKIP[replace(id, /^c_/, "")]) continue;
		for (let k in split(s(f[7]), ",")) if (idx[k]) {
			t = [ ...t, ...idx_tokens(idx[k], known) ];
			if (idx[k].kind == "s") cat = true;
		}
		if (!length(t)) continue;
		let itd = index(id, "c_itdoginfo_") == 0 || index(lc(grp), "itdoginfo") == 0;
		if (itd) {
			let own = true;
			for (let tk in t) if (!covered[tk]) own = false;
			if (own) continue;
		}
		seen[id] = true;
		push(items, { id, name: s(f[1]) || id, group: itd ? "" : grp, cat: itd && cat, targets: uniq(t) });
	}
	return items;
}

function cat_meta() {
	try { let j = json(s(getenv("ZM_FK_CAT"))); return type(j) == "object" ? j : null; } catch (e) { return null; }
}


function link_name(l) {
	if (match(l, /^vmess:\/\//i)) {
		let d = null, b = replace(replace(trim(substr(split(l, "#")[0], 8)), /-/g, "+"), /_/g, "/");
		while (length(b) % 4) b += "=";
		try { d = json(b64dec(b)); } catch (e) { d = null; }
		if (type(d) == "object" && s(d.ps) != "") return s(d.ps);
	}
	let i = index(l, "#");
	if (i < 0) return "";
	let t = replace(substr(l, i + 1), /\+/g, " ");
	return replace(t, /%([0-9A-Fa-f]{2})/g, (all, h) => chr(hex(h)));
}

function link_host(l) {
	let m = match(split(l, "#")[0], /^[a-z0-9]+:\/\/([^@\/?#]*@)?(\[[^\]]+\]|[^:\/?#]+)(:([0-9]+))?/i);
	return m ? m[2] + (m[4] ? ":" + m[4] : "") : "";
}


const CYR_UP = split("А Б В Г Д Е Ё Ж З И Й К Л М Н О П Р С Т У Ф Х Ц Ч Ш Щ Ъ Ы Ь Э Ю Я", " ");
const CYR_LO = split("а б в г д е ё ж з и й к л м н о п р с т у ф х ц ч ш щ ъ ы ь э ю я", " ");

function fold(v) {
	v = lc(s(v));
	for (let k = 0; k < length(CYR_UP); k++) v = replace(v, CYR_UP[k], CYR_LO[k]);
	return v;
}

function unfold_up(v) {
	v = uc(s(v));
	for (let k = 0; k < length(CYR_LO); k++) v = replace(v, CYR_LO[k], CYR_UP[k]);
	return v;
}

function cap_first(v) {
	v = s(v);
	if (v == "") return v;
	let b = ord(v, 0), n = b >= 0xf0 ? 4 : b >= 0xe0 ? 3 : b >= 0xc0 ? 2 : 1;
	return unfold_up(substr(v, 0, n)) + substr(v, n);
}

function excl_list(v) {
	let res = [], seen = {};
	for (let x in split(s(v), /[|,]/)) {
		x = fold(trim(x));
		if (x == "" || seen[x]) continue;
		seen[x] = true;
		push(res, x);
	}
	return res;
}

function excl_vars(m) { return { m: excl_list(m.zm_exclude), h: rawlist(m.zm_hide) }; }

function excl_any(f) { return length(f.m) > 0 || length(f.h) > 0; }

function excl_hit(name, f) {
	name = s(name);
	if (index(f.h, name) >= 0) return true;
	name = fold(name);
	for (let x in f.m) if (x != "" && index(name, x) >= 0) return true;
	return false;
}

function filter_keywords(f) {
	let r = [];
	for (let x in f.m) r = [ ...r, x, cap_first(x), unfold_up(x) ];
	return uniq([ ...r, ...f.h ]);
}


function is_conn(x) {
	let t = s(x.connection_type);
	return x[".name"] != BYPASS && (t == "proxy" || t == "vpn");
}

function pick(c) {
	let all = sections(c, "section"), sec = null;
	for (let x in all)
		if (x[".name"] == "main" && is_conn(x)) sec = "main";
	if (!sec)
		for (let x in all)
			if (is_conn(x)) { sec = x[".name"]; break; }
	if (!sec) sec = "main";
	let extra = [], conns = [];
	for (let x in all) {
		if (x[".name"] == BYPASS) continue;
		if (is_conn(x)) { if (x[".name"] != sec) push(conns, x[".name"]); continue; }
		push(extra, { name: x[".name"], label: s(x.zm_label || x[".name"]), action: s(x.connection_type), enabled: s(x.disabled) != "1" });
	}
	return { sec, extra, conns };
}

function sec_links(m) {
	let l = rawlist(m.zm_links);
	if (length(l)) return l;
	for (let k in LINK_KEYS) {
		let v = k == "proxy_string" ? arr(m[k]) : (index(k, "_text") >= 0 ? lines(m[k]) : words(m[k]));
		if (length(v)) return v;
	}
	return [];
}

function visible_links(m, f) {
	return filter(sec_links(m), (l) => !excl_hit(link_name(l), f));
}

function sec_mode(m) {
	if (s(m.connection_type) == "vpn") return "iface";
	let t = s(m.proxy_config_type || "url");
	if (t == "subscription") return "sub";
	if (t == "outbound") return "json";
	return "links";
}

function sub_urls(m) {
	return uniq(words(m.subscription_url));
}

function domain_lines(m) {
	let t = s(m.user_domain_list_type || "disabled");
	if (t == "text") return uniq(tokens(m.user_domains_text));
	if (t == "dynamic") return uniq(words(m.user_domains));
	return [];
}

function subnet_lines(m) {
	let t = s(m.user_subnet_list_type || "disabled");
	if (t == "text") return uniq(tokens(m.user_subnets_text));
	if (t == "dynamic") return uniq(words(m.user_subnets));
	return [];
}

function own_off(m) { return s(m.zm_own_off) == "1"; }

function own_view(m, typed) {
	if (!own_off(m)) return { on: true, domains: domain_lines(m), subnets: subnet_lines(m), lists: typed };
	return { on: false, domains: uniq(tokens(m.zm_own_domains)), subnets: uniq(tokens(m.zm_own_subnets)), lists: uniq([ ...typed, ...rawlist(m.zm_own_lists) ]) };
}

function device_ips(m) {
	return uniq(words(m.zm_rule_source_ips));
}

function all_ips(m) {
	return uniq(words(m.fully_routed_ips));
}

function url_ext(u) {
	let m = match(lc(replace(s(u), /[?#].*$/, "")), /\.([a-z0-9]+)$/);
	return m ? m[1] : "";
}

function is_rs(u) { let e = url_ext(u); return e == "srs" || e == "json"; }

function sec_refs(m) {
	let r = { c: uniq(words(m.community_lists)), s: [], r: [], n: [], l: [] }, zr = rawlist(m.zm_refs);
	if (length(zr)) {
		for (let t in zr) {
			let k = substr(t, 0, 1), v = substr(t, 2);
			if (substr(t, 1, 1) == ":" && r[k] && k != "c" && v != "") push(r[k], v);
		}
	} else {
		let d = uniq(words(m.remote_domain_lists)), sn = uniq(words(m.remote_subnet_lists));
		for (let u in d) {
			if (!is_rs(u)) push(r.l, u);
			else if (index(sn, u) >= 0) push(r.r, u);
			else push(r.s, u);
		}
		for (let u in sn) if (index(d, u) < 0) push(is_rs(u) ? r.n : r.l, u);
		for (let u in [ ...words(m.local_domain_lists), ...words(m.local_subnet_lists) ]) push(r.l, u);
	}
	r.l = uniq(r.l);
	return refs_fix(r);
}

function sec_configured(m) {
	let mode = sec_mode(m);
	if (mode == "iface") return s(m.interface) != "";
	if (mode == "sub") return length(sub_urls(m)) > 0;
	if (mode == "json") return s(m.outbound_json) != "";
	return length(sec_links(m)) > 0;
}

function sec_label(m, main) {
	let l = trim(s(m.zm_label));
	return l != "" ? l : main ? "Основная" : s(m[".name"]);
}

function sec_summary(c, sec, main) {
	let m = c.get_all(CFG, sec) || {}, mode = sec_mode(m), rf = sec_refs(m);
	return {
		name: sec, main, label: sec_label(m, main), enabled: main || s(m.disabled) != "1", mode,
		iface: s(m.interface), links: length(sec_links(m)),
		refs: { c: rf.c, s: rf.s, r: rf.r, n: rf.n }, lists: rf.l,
		domains: length(domain_lines(m)), subnets: length(subnet_lines(m)), own_off: own_off(m),
		full: device_ips(m), all: all_ips(m)
	};
}

function sec_list(c, p) {
	let r = [];
	for (let x in sections(c, "section")) {
		let n = x[".name"];
		if (n == p.sec) push(r, sec_summary(c, n, true));
		else if (index(p.conns, n) >= 0) push(r, sec_summary(c, n, false));
	}
	return r;
}

function bypass_info(c) {
	let m = c.get_all(CFG, BYPASS) || {};
	return { domains: domain_lines(m), subnets: subnet_lines(m) };
}

function legacy_bypass_info(c) {
	let r = [];
	c.foreach(CFG, "section", (m) => {
		if (m[".name"] == BYPASS || s(m.connection_type) != "exclusion") return;
		push(r, {
			name: m[".name"], label: sec_label(m, false), enabled: s(m.disabled) != "1",
			domains: domain_lines(m), subnets: subnet_lines(m),
			community: rawlist(m.community_lists),
			lists: uniq([ ...rawlist(m.local_domain_lists), ...rawlist(m.local_subnet_lists),
				...rawlist(m.remote_domain_lists), ...rawlist(m.remote_subnet_lists) ])
		});
	});
	return r;
}

function devices() {
	let r = [], seen = {};
	for (let l in split(s(fs.readfile(LEASES)), "\n")) {
		let f = split(trim(l), /[ \t]+/);
		if (length(f) < 4 || !match(f[2], /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/) || seen[f[2]]) continue;
		seen[f[2]] = true;
		push(r, { ip: f[2], mac: lc(f[1]), name: f[3] == "*" ? "" : f[3] });
	}
	return sort(r, (a, b) => {
		let x = map(split(a.ip, "."), (v) => int(v)), y = map(split(b.ip, "."), (v) => int(v));
		for (let i = 0; i < 4; i++) if (x[i] != y[i]) return x[i] - y[i];
		return 0;
	});
}

const TUN_LABEL = { amneziawg: "AmneziaWG", wireguard: "WireGuard", pptp: "PPTP", l2tp: "L2TP", sstp: "SSTP", openvpn: "OpenVPN" };
function tunnels() {
	let r = [], seen = {}, byDev = {}, want = [];
	try {
		let c = uci.cursor();
		c.load("network");
		c.foreach("network", "interface", (x) => {
			let n = x[".name"], p = s(x.proto), d = "";
			if (p == "pptp" || p == "l2tp" || p == "sstp") d = p + "-" + n;
			else if (p == "amneziawg" || p == "wireguard") d = n;
			else if (p == "openvpn" || p == "none") { d = s(x.device || x.ifname); if (match(d, /^@/)) d = ""; }
			if (d == "" || n == "tailscale" || match(n, /^zmwarp[0-9]*$/)) return;
			byDev[d] = { net: n, proto: p };
			if (p != "none" && p != "openvpn") push(want, d);
		});
	} catch (e) {}
	for (let n in (fs.lsdir(NETDIR) || [])) {
		if (n == "lo" || match(n, /^(sit|ip6tnl|gre|erspan|teql|ifb|dummy|bond)/)) continue;
		let t = trim(s(fs.readfile(NETDIR + "/" + n + "/type"))), b = byDev[n];
		if (t == "512" ? !(b && (b.proto == "pptp" || b.proto == "l2tp" || b.proto == "sstp")) : t != "65534") continue;
		let st = trim(s(fs.readfile(NETDIR + "/" + n + "/operstate"))), steer = !!match(n, /^zmwarp[0-9]*$/);
		seen[n] = true;
		push(r, { name: n, up: st != "down", steer, net: b ? b.net : "",
			kind: steer ? "AmneziaWG" : b && TUN_LABEL[b.proto] ? TUN_LABEL[b.proto] : match(n, /^tailscale/) ? "Tailscale" : "туннель" });
	}
	for (let d in want) {
		if (seen[d] || !match(d, /^[A-Za-z0-9_.-]{1,15}$/)) continue;
		let b = byDev[d];
		push(r, { name: d, up: false, steer: false, net: b.net, kind: TUN_LABEL[b.proto] || "туннель", down: true });
	}
	return sort(r, (a, b) => a.name < b.name ? -1 : a.name > b.name ? 1 : 0);
}

function dns_info(st) {
	let t = s(st.dns_type || "udp");
	let sv = rawlist(st.zm_dns_servers), bs = rawlist(st.zm_bootstrap), cur = s(st.dns_server), bcur = s(st.bootstrap_dns_server);
	if (!length(sv)) sv = cur != "" ? [ cur ] : [ "9.9.9.9" ];
	if (!length(bs)) bs = bcur != "" ? [ bcur ] : [ "9.9.9.9" ];
	let active = index(sv, cur), bactive = index(bs, bcur);
	if (active < 0) active = 0;
	if (bactive < 0) bactive = 0;
	let pool = index([ "fallback", "race" ], s(st.dns_pool_mode)) >= 0 && length(sv) > 1 ? s(st.dns_pool_mode) : "";
	return { type: t, server: sv[0], bootstrap: bs[0], servers: sv, bootstraps: bs, active, bactive,
		detour: s(st.dns_via_outbound) == "1", failover: length(sv) > 1, pool };
}


function valid_ip(v) {
	if (ml(v)) return false;
	let m = match(v, /^([0-9]+)\.([0-9]+)\.([0-9]+)\.([0-9]+)(\/([0-9]+))?$/);
	if (!m) return false;
	for (let i = 1; i <= 4; i++) if (int(m[i]) > 255) return false;
	return m[6] == null || int(m[6]) <= 32;
}

function ip4n(a) {
	let m = match(s(a), /^([0-9]+)\.([0-9]+)\.([0-9]+)\.([0-9]+)$/);
	return m ? ((int(m[1]) * 256 + int(m[2])) * 256 + int(m[3])) * 256 + int(m[4]) : null;
}

function cidr_hit(ip, cidrs) {
	let n = ip4n(ip);
	if (n == null) return false;
	for (let c in (type(cidrs) == "array" ? cidrs : [ cidrs ])) {
		let p = split(s(c), "/"), b = ip4n(p[0]), bits = length(p) > 1 ? int(p[1]) : 32;
		if (b == null || bits < 0 || bits > 32) continue;
		let div = 1;
		for (let i = bits; i < 32; i++) div *= 2;
		if (int(n / div) == int(b / div)) return true;
	}
	return false;
}

function device_ip_overlap(a, b) {
	return cidr_hit(split(a, "/")[0], [ b ]) || cidr_hit(split(b, "/")[0], [ a ]);
}

function device_scopes_overlap(a, b) {
	if (!length(a) || !length(b)) return true;
	for (let x in a) for (let y in b) if (device_ip_overlap(x, y)) return true;
	return false;
}

function dns_value_ok(t, v) {
	if (v == "" || ml(v) || match(v, /[ \t@|,;'"<>]/)) return false;
	if (t == "udp") return valid_ip(replace(v, /:[0-9]+$/, "")) && index(v, "/") < 0;
	if (t == "dot") return !match(v, /^[a-z]+:\/\//i) && index(v, "/") < 0 && !!match(v, /^[A-Za-z0-9.-]+(:[0-9]+)?$/) && !!match(v, /\./);
	if (match(v, /^https:\/\//i)) return !!match(v, /^https:\/\/[A-Za-z0-9.-]+\.[A-Za-z0-9-]+(:[0-9]+)?(\/[^ ]*)?$/i);
	return !!match(v, /^[A-Za-z0-9.-]+\.[A-Za-z0-9-]+(:[0-9]+)?(\/[^ ]*)?$/);
}

function dns_norm(t, v) {
	if (t == "doh" && !match(v, /^https:\/\//i)) return index(v, "/") >= 0 ? "https://" + v : "https://" + v + "/dns-query";
	return v;
}

function non_ascii(v) {
	for (let i = 0; i < length(v); i++) if (ord(v, i) > 127) return true;
	return false;
}

let PFX = null;
function prefix_ok() {
	if (PFX == null) PFX = index(s(fs.readfile(NS_LIB + "/helpers.sh")), "domain_rule_normalize() {") >= 0;
	return PFX;
}

function norm_domain(v) {
	v = trim(s(v));
	if (prefix_ok()) {
		let pm = match(v, /^(full|keyword|regexp?):(.*)$/i);
		if (pm) {
			let k = lc(pm[1]) == "regexp" ? "regex" : lc(pm[1]);
			return k + ":" + (k == "regex" ? trim(pm[2]) : replace(lc(trim(pm[2])), /^\*\./, ""));
		}
	}
	v = lc(v);
	let m = match(v, /^full:(.+)$/);
	if (m) v = m[1];
	v = replace(v, /^\*\./, "");
	return v;
}

function domain_err(raw) {
	let v = norm_domain(raw), pm = prefix_ok() ? match(v, /^(full|keyword|regex):(.*)$/) : null;
	if (pm && pm[1] == "keyword") return match(pm[2], /^[a-z0-9._-]+$/) ? null : "«" + raw + "»: после keyword: нужна часть имени — латинские буквы, цифры, точки и дефисы";
	if (pm && pm[1] == "regex") return pm[2] != "" && length(pm[2]) <= 256 && !match(pm[2], /[ \t,;]/) ? null : "«" + raw + "»: после regex: нужно регулярное выражение без пробелов, запятых и точек с запятой";
	if (pm) v = pm[2];
	else if (match(lc(s(raw)), /^(keyword|regex|regexp|domain_keyword|domain_regex):/))
		return "«" + raw + "»: " + (prefix_ok() ? "пишите keyword: или regex:" : "keyword: и regex: понимает движок Forkozz 0.9.11 и новее — обновите Forkozz или впишите домен целиком, например example.com");
	if (non_ascii(v))
		return "«" + raw + "»: русские домены пишите в punycode — например, xn--h1alffa9f.xn--p1ai вместо россия.рф";
	if (!match(replace(v, /^\./, ""), /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)+$/))
		return "это не похоже на домен: " + raw;
	return null;
}

function valid_url(v) { return !ml(v) && !!match(v, /^https?:\/\/[^ \t\/]+(\/[^ \t]*)?$/i); }

function set_list(c, sec, key, list) {
	if (length(list)) c.set(CFG, sec, key, list);
	else c.delete(CFG, sec, key);
}

function write_device_lists(c, sec, full, excl, all) {
	set_list(c, sec, "zm_rule_source_ips", full);
	set_list(c, sec, "fully_routed_ips", all || []);
	if (!c.get(CFG, "settings")) c.set(CFG, "settings", "settings");
	set_list(c, "settings", "routing_excluded_ips", excl);
}

function patch_device_engine() {
	let script = s(fs.readfile(BIN)), marker = "# ZM_SECTION_DEVICE_RULES";
	let original = script;
	let start = index(script, "configure_routing_for_section_lists() {\n");
	let end = start >= 0 ? index(substr(script, start), "\n}\n") : -1;
	if (start < 0 || end < 0) fail("эта версия движка не поддерживает фильтр устройств — настройки не изменены");
	let body = substr(script, start, end + 2);
	let anchor = '    if [ -n "$community_lists" ]; then\n';
	if (length(split(body, anchor)) != 2) fail("не удалось найти правило секции в движке — настройки не изменены");
	let patch = '    # ZM_SECTION_DEVICE_RULES\n' +
		'    local zm_rule_source_ips\n' +
		'    config_get zm_rule_source_ips "$section" "zm_rule_source_ips"\n' +
		'    if [ -n "$zm_rule_source_ips" ]; then\n' +
		'        config_list_foreach "$section" "zm_rule_source_ips" include_source_ip_in_routing_handler "$route_rule_tag"\n' +
		'    fi\n';
	let updated = index(body, marker) >= 0 ? body : replace(body, anchor, patch + anchor);
	if (index(updated, "# ZM_SECTION_DIRECT_FALLBACK") < 0) {
		let unavailable = '            if subscription_outbound_is_unavailable "$section"; then\n';
		let route = '                outbound_tag=$(get_outbound_tag_by_section "$section")\n';
		if (length(split(updated, unavailable)) != 2 || length(split(updated, route)) != 2)
			fail("эта версия движка не поддерживает резервный прямой выход — настройки не изменены");
		updated = replace(updated, '    local section="$1"\n', '    local section="$1"\n' +
			'    # ZM_SECTION_DIRECT_FALLBACK\n' +
			'    local zm_direct_fallback\n' +
			'    config_get_bool zm_direct_fallback "$section" "zm_direct_fallback" 0\n');
		updated = replace(updated, unavailable, '            if subscription_outbound_is_unavailable "$section" && [ "$zm_direct_fallback" -ne 1 ]; then\n');
		updated = replace(updated, route, route + '                [ "$zm_direct_fallback" -eq 1 ] && [ "$section_connection_type" = proxy ] && outbound_tag="$section-zm-fallback-out"\n');
	}
	script = substr(script, 0, start) + updated + substr(script, start + length(body));
	if (index(script, "# ZM_SERVICE_EXTRA") < 0) {
		let hs = index(script, "configure_community_list_handler() {\n"), he = hs >= 0 ? index(substr(script, hs), "\n}\n") : -1;
		let tail = '    patch_section_dns_rule_set "$ruleset_tag"\n';
		if (hs >= 0 && he > 0 && length(split(substr(script, hs, he + 1), tail)) == 2) {
			let hb = substr(script, hs, he + 1);
			script = substr(script, 0, hs) + replace(hb, tail, tail +
				'    # ZM_SERVICE_EXTRA\n' +
				'    local zm_extra="/usr/share/zm-redbtn/svc/${tag}_extra.lst"\n' +
				'    if [ -s "$zm_extra" ]; then\n' +
				'        rm -f "$TMP_RULESET_FOLDER/$(get_ruleset_tag "$section" "zm_$tag" "domains").json"\n' +
				'        prepare_source_ruleset "$section" "zm_$tag" "domains" "$route_rule_tag" &&\n' +
				'            import_plain_domain_list_to_local_source_ruleset_chunked "$zm_extra" "$ruleset_filepath"\n' +
				'    fi\n') + substr(script, hs + he + 1);
		}
	}
	if (index(script, "# ZM_DIRECT_FALLBACK_CONFIG") < 0) {
		let save = "sing_box_save_config() {\n";
		if (length(split(script, save)) != 2) fail("не удалось найти сборку конфига движка — настройки не изменены");
		let uc = "/opt/zapret-manager-luci/netshift.uc";
		script = replace(script, save, save + '    # ZM_DIRECT_FALLBACK_CONFIG\n' +
			'    if uci -q show netshift | grep -q "\\.zm_direct_fallback=\'1\'$"; then\n' +
			'        config="$(printf \'%s\' "$config" | jq -c --argjson feeds "${ZM_PRIORITY_FEEDS_JSON:-null}" \'._zm_priority_feeds = $feeds\' | ucode ' + q(uc) + ' fallback_config)" || {\n' +
			'            log "Failed to configure section fallback. Aborted." "fatal"\n' +
			'            exit 1\n' +
			'        }\n' +
		'    fi\n');
	}
	let old_guard = '    if uci -q show netshift | grep -q "\\.zm_direct_fallback=\'1\'$"; then\n';
	let new_guard = '    if uci -q show netshift | grep -qE "\\.(zm_direct_fallback|zm_sub_priority)=\'1\'$"; then\n';
	script = replace(script, old_guard, new_guard);
	let old_call = '        config="$(printf \'%s\' "$config" | ucode \'/opt/zapret-manager-luci/netshift.uc\' fallback_config)" || {\n';
	let new_call = '        config="$(printf \'%s\' "$config" | jq -c --argjson feeds "${ZM_PRIORITY_FEEDS_JSON:-null}" \'._zm_priority_feeds = $feeds\' | ucode \'/opt/zapret-manager-luci/netshift.uc\' fallback_config)" || {\n';
	script = replace(script, old_call, new_call);
	script = replace(script, new_guard, '    if uci -q show netshift | grep -qE "\\.(zm_direct_fallback|zm_sub_priority|zm_auto_ping)=\'1\'$"; then\n');
	script = replace(script, '    if uci -q show netshift | grep -qE "\\.(zm_direct_fallback|zm_sub_priority|zm_auto_ping)=\'1\'$"; then\n',
		'    if uci -q show netshift | grep -qE "\\.(zm_direct_fallback|zm_sub_priority|zm_auto_ping|zm_bt_src)=\'1\'$"; then\n');
	if (index(script, "# ZM_SUBSCRIPTION_PRIORITY_FEEDS") < 0) {
		let feed_anchor = '                subscription_outbound_feeds_json="$SUBSCRIPTION_OUTBOUND_FEEDS_JSON"\n';
		let reset_anchor = "sing_box_configure_outbounds() {\n";
		if (length(split(script, feed_anchor)) != 2 || length(split(script, reset_anchor)) != 2) fail("эта версия движка не поддерживает порядок подписок — настройки не изменены");
		script = replace(script, reset_anchor, reset_anchor + '    ZM_PRIORITY_FEEDS_JSON="{}"\n');
		script = replace(script, feed_anchor, feed_anchor +
			'                # ZM_SUBSCRIPTION_PRIORITY_FEEDS\n' +
			'                local zm_sub_priority zm_priority_feeds\n' +
			'                config_get_bool zm_sub_priority "$section" "zm_sub_priority" 0\n' +
			'                if [ "$zm_sub_priority" -eq 1 ]; then\n' +
			'                    zm_priority_feeds="$(sing_box_build_subscription_feed_groups "$subscription_outbound_tags_json" "${subscription_outbound_feeds_json:-[]}" "${subscription_feed_names_json:-[]}")"\n' +
			'                    ZM_PRIORITY_FEEDS_JSON="$(printf \'%s\' "$ZM_PRIORITY_FEEDS_JSON" | jq -c --arg sec "$section" --argjson feeds "$zm_priority_feeds" \' .[$sec] = $feeds\')" || exit 1\n' +
			'                fi\n');
	}
	if (script == original) return false;
	let tmp = BIN + ".zm-devices";
	if (fs.writefile(tmp, script) == null) fail("не удалось записать правила секций в движок");
	if (system("sh -n " + q(tmp) + " && chmod 0755 " + q(tmp)) != 0) {
		fs.unlink(tmp);
		fail("правка движка не прошла проверку синтаксиса — настройки не изменены");
	}
	if (!fs.rename(tmp, BIN)) fail("не удалось заменить файл движка");
	return true;
}


function b4_migrate() {
	let c = cursor(), ch = false;
	for (let x in sections(c, "section")) {
		let n = x[".name"], zr = rawlist(x.zm_refs), d = rawlist(x.remote_domain_lists), sn = rawlist(x.remote_subnet_lists);
		let zr2 = [], d2 = [], sn2 = [];
		for (let t in zr) {
			let k = substr(t, 0, 1), b = substr(t, 1, 1) == ":" && index([ "s", "r", "n" ], k) >= 0 ? b4_name(substr(t, 2)) : null;
			if (b) { let y = b4_ref(b); push(zr2, y.k + ":" + y.u); } else push(zr2, t);
		}
		for (let u in d) {
			let b = b4_name(u), y = b ? b4_ref(b) : null;
			if (!y) push(d2, u); else push(y.k == "n" ? sn2 : d2, y.u);
		}
		for (let u in sn) {
			let b = b4_name(u), y = b ? b4_ref(b) : null;
			if (!y) push(sn2, u); else push(y.k == "s" ? d2 : sn2, y.u);
		}
		zr2 = uniq(zr2); d2 = uniq(d2); sn2 = uniq(sn2);
		if (join("\n", zr2) == join("\n", zr) && join("\n", d2) == join("\n", d) && join("\n", sn2) == join("\n", sn)) continue;
		if (length(zr)) set_list(c, n, "zm_refs", zr2);
		set_list(c, n, "remote_domain_lists", d2);
		set_list(c, n, "remote_subnet_lists", sn2);
		ch = true;
	}
	if (ch) { c.save(CFG); c.commit(CFG); }
	return ch;
}

function cmd_device_setup() {
	let eng = patch_device_engine(), lists = b4_migrate();
	out({ ok: true, changed: eng || lists, lists });
}

function del_keys(c, sec, keys) { for (let k in keys) c.delete(CFG, sec, k); }

function apply_servers(c, sec) {
	let m = c.get_all(CFG, sec) || {}, mode = sec_mode(m), f = excl_vars(m);
	if (mode == "links") {
		let vis = visible_links(m, f);
		del_keys(c, sec, LINK_KEYS);
		if (length(vis) == 1) {
			c.set(CFG, sec, "proxy_config_type", "selector");
			c.set(CFG, sec, "selector_proxy_links", vis);
		} else if (length(vis) > 1) {
			c.set(CFG, sec, "proxy_config_type", "urltest");
			c.set(CFG, sec, "urltest_proxy_links", vis);
		}
		c.delete(CFG, sec, "subscription_filter_exclude_keywords");
		return length(vis);
	}
	if (mode == "sub") {
		let kw = filter_keywords(f);
		set_list(c, sec, "subscription_filter_exclude_keywords", kw);
	}
	return -1;
}

function set_lists(c, sec, rf, services, domains, subnets) {
	set_list(c, sec, "community_lists", services);
	let zr = [];
	for (let k in [ "s", "r", "n", "l" ]) for (let v in (rf[k] || [])) push(zr, k + ":" + v);
	set_list(c, sec, "zm_refs", zr);
	let rl = filter(rf.l, (u) => !pkg_local(u)), ll = filter(rf.l, (u) => pkg_local(u));
	set_list(c, sec, "remote_domain_lists", uniq([ ...rf.s, ...rf.r, ...rl ]));
	set_list(c, sec, "remote_subnet_lists", uniq([ ...rf.r, ...(rf.n || []), ...rl ]));
	del_keys(c, sec, [ "local_domain_lists", "local_subnet_lists", "user_domains", "user_subnets" ]);
	set_list(c, sec, "local_domain_lists", uniq(ll));
	if (length(domains)) {
		c.set(CFG, sec, "user_domain_list_type", "text");
		c.set(CFG, sec, "user_domains_text", join("\n", domains));
	} else {
		c.set(CFG, sec, "user_domain_list_type", "disabled");
		c.delete(CFG, sec, "user_domains_text");
	}
	if (length(subnets)) {
		c.set(CFG, sec, "user_subnet_list_type", "text");
		c.set(CFG, sec, "user_subnets_text", join("\n", subnets));
	} else {
		c.set(CFG, sec, "user_subnet_list_type", "disabled");
		c.delete(CFG, sec, "user_subnets_text");
	}
}

function parse_domains(v) {
	let r = [];
	for (let x in uniq(tokens(v))) {
		let e = domain_err(x);
		if (e) fail(e);
		push(r, norm_domain(x));
	}
	return uniq(r);
}


const SUB_FMTS = [ "auto", "xray", "singbox" ];
const SUB_GROUPS = [ "off", "country", "prefix" ];
const UT_IVS = [ "30s", "1m", "3m", "5m" ];
const UT_URL_DEF = "https://www.gstatic.com/generate_204";
const LOG_LEVELS = [ "trace", "debug", "info", "warn", "error", "fatal", "panic" ];
const SUB_MAX = 10;

function flag(v) { return s(v) == "1"; }

function num_in(v, lo, hi) {
	v = trim(s(v));
	if (ml(v) || !match(v, /^[0-9]{1,6}$/)) return null;
	v = int(v);
	return v >= lo && v <= hi ? v : null;
}

function kw_list(v) {
	let r = [];
	for (let x in arr(v))
		for (let w in split(s(x), /[|\r\n]+/)) {
			w = trim(w);
			if (w != "" && index(r, w) < 0) push(r, w);
		}
	return r;
}

const RL_FPS = [ "chrome", "firefox", "safari", "edge", "ios", "random", "randomized" ];
const RL_XKEY = { "": true, chrome: true, firefox: true, safari: true, random: true, randomized: true };
const RL_HP_RE = /^(\[[0-9A-Fa-f:.]+\]|[^ \t\r\n\[\]'"\\`$:]+):[0-9]{1,5}$/;
const RL_MAX = 300;
const RL_CORE_CACHE = getenv("ZM_FK_RLCORE") || "/tmp/zm-fk-rlcore";
const RL_LEARN = getenv("ZM_FK_RLLEARN") || STATE + "/fk.rl.learn.json";
const RL_ALT = getenv("ZM_FK_RLALT") || "/tmp/zm-fk-rlalt.json";
const RL_ALT_PFX = "zm-rlalt-";
const RL_LEARN_MAX = 2000;

function rl_jread(f) {
	let j = null;
	try { j = json(s(fs.readfile(f))); } catch (e) { j = null; }
	return type(j) == "object" ? j : {};
}

function rl_fp(v) { v = s(v); return v == "sub" || index(RL_FPS, v) >= 0 ? v : "auto"; }

function rl_mk(v) { v = s(v); return v == "on" || v == "off" ? v : "auto"; }

function rl_hp(host, port) {
	host = s(host);
	return (index(host, ":") >= 0 ? "[" + host + "]" : host) + ":" + int(port || 0);
}

function rl_nodes(m) {
	let r = {}, l = rawlist(m.zm_rl_node);
	for (let i = 0; i < length(l); i++) {
		let p = split(trim(l[i]), /[ \t]+/);
		if (length(p) != 3 || !match(p[0], RL_HP_RE)) continue;
		let fp = index(RL_FPS, p[1]) >= 0 ? p[1] : "", mk = p[2] == "on" || p[2] == "off" ? p[2] : "";
		if (fp != "" || mk != "") r[p[0]] = { fp, mk };
	}
	return r;
}

function rl_core() {
	let st = fs.stat(getenv("ZM_FK_SBBIN") || "/usr/bin/sing-box"), key = st ? st.mtime + "-" + st.size : "", now = time();
	if (key != "") {
		let c = split(trim(s(fs.readfile(RL_CORE_CACHE))), " ");
		if (length(c) == 3 && c[0] == key && (c[1] == "1" || c[1] == "0") && now - int(c[2]) < 86400 && now >= int(c[2])) return c[1] == "1";
	}
	let m = match(sh("sing-box version"), /-extended-([0-9]+)\.([0-9]+)\.([0-9]+)/), ok = false;
	if (m) {
		let a = int(m[1]), b = int(m[2]), d = int(m[3]);
		ok = a > 2 || (a == 2 && (b > 7 || (b == 7 && d >= 2)));
	}
	if (key != "") fs.writefile(RL_CORE_CACHE, key + " " + (ok ? "1" : "0") + " " + now + "\n");
	return ok;
}

function rl_on(o) {
	return type(o) == "object" && type(o.tls) == "object" && type(o.tls.reality) == "object" && o.tls.reality.enabled === true && type(o.tls.utls) == "object";
}

function rl_secmap(j, c) {
	let by = {}, own = {}, obs = j.outbounds, secs = sections(c, "section");
	for (let i = 0; i < length(obs); i++)
		if (type(obs[i]) == "object" && s(obs[i].tag) != "") by[s(obs[i].tag)] = obs[i];
	for (let k = 0; k < length(secs); k++) {
		let n = secs[k][".name"], q = [];
		for (let t in by) if (index(t, n + "-") == 0) push(q, t);
		for (let i = 0; i < length(q); i++) {
			let t = q[i], m = by[t].outbounds;
			if (own[t] != null) continue;
			own[t] = n;
			if (type(m) == "array")
				for (let x = 0; x < length(m); x++) if (by[s(m[x])] && own[s(m[x])] == null) push(q, s(m[x]));
		}
	}
	return own;
}

function rl_plan(o, fp, mk, core, lk) {
	let fp0 = s(o.tls.utls.fingerprint), cur = o.tls.reality.support_x25519mlkem768;
	let f = fp == "auto" || fp == "sub" ? fp0 : fp, want = false, need = false;
	if (mk == "on") want = true;
	else if (mk == "off") want = false;
	else if (cur === false) want = false;
	else if (lk != null) want = !!lk;
	else want = cur === true;
	if (want && !(cur === true && fp0 == "chrome" && f == "chrome") && !core()) { want = false; need = true; }
	if (want) f = "chrome";
	return { fp: f, key: want, need };
}

function rl_apply(o, p) {
	let u = o.tls.utls, r = o.tls.reality, ch = false;
	if (p.fp != "" && s(u.fingerprint) != p.fp) { u.fingerprint = p.fp; u.enabled = true; ch = true; }
	if (p.key && r.support_x25519mlkem768 !== true) { r.support_x25519mlkem768 = true; ch = true; }
	if (!p.key && r.support_x25519mlkem768 === true) { delete r.support_x25519mlkem768; ch = true; }
	return ch;
}

function rl_pol(c, sec, cache) {
	if (cache[sec] == null) {
		let m = sec != "" ? c.get_all(CFG, sec) || {} : {};
		cache[sec] = { fp: rl_fp(m.zm_rl_fp), mk: rl_mk(m.zm_rl_mk), nodes: rl_nodes(m) };
	}
	return cache[sec];
}

function rl_conf() {
	let raw = s(fs.readfile(SB_CONF)), j = null;
	if (index(raw, "\"reality\"") < 0) return null;
	try { j = json(raw); } catch (e) { j = null; }
	return type(j) == "object" && type(j.outbounds) == "array" ? j : null;
}

function cmd_reality(src, dst) {
	let raw = s(fs.readfile(src)), j = null;
	if (s(dst) == "" || index(raw, "\"reality\"") < 0) exit(1);
	try { j = json(raw); } catch (e) { j = null; }
	if (type(j) != "object" || type(j.outbounds) != "array") exit(1);
	let n0 = length(j.outbounds), list = [];
	j.outbounds = filter(j.outbounds, (o) => type(o) != "object" || index(s(o.tag), RL_ALT_PFX) != 0);
	let obs = j.outbounds, dropped = length(obs) != n0;
	for (let i = 0; i < length(obs); i++) if (rl_on(obs[i])) push(list, obs[i]);
	if (!length(list)) {
		try { fs.unlink(RL_ALT); } catch (e) {}
		if (dropped && fs.writefile(dst, sprintf("%J", j)) != null) exit(0);
		exit(1);
	}
	let env = s(getenv("ZM_RL_CORE")), cv = env == "1" ? true : env == "0" ? false : null;
	let core = () => { if (cv == null) cv = rl_core(); return cv; };
	let c = cursor(), own = rl_secmap(j, c), cache = {}, ln = rl_jread(RL_LEARN), alts = {}, extra = [], nk = 0, nf = 0, nn = 0, na = 0, ch = dropped;
	for (let i = 0; i < length(list); i++) {
		let o = list[i], p = rl_pol(c, s(own[s(o.tag)]), cache), hp = rl_hp(o.server, o.server_port), ov = p.nodes[hp] || {};
		let fp = s(ov.fp) || p.fp, mk = s(ov.mk) || p.mk, l = type(ln[hp]) == "object" ? ln[hp] : null;
		let fp0 = s(o.tls.utls.fingerprint), x = rl_plan(o, fp, mk, core, l ? !!int(l.k) : null);
		let auto = mk == "auto" && o.tls.reality.support_x25519mlkem768 !== false, a = null;
		if (auto && length(extra) < RL_MAX && core()) a = json(sprintf("%J", o));
		if (rl_apply(o, x)) { ch = true; if (x.fp != fp0) nf++; }
		if (a) {
			let ak = !x.key, af = ak ? "chrome" : (fp == "auto" || fp == "sub" ? fp0 : fp);
			rl_apply(a, { fp: af, key: ak });
			a.tag = RL_ALT_PFX + (length(extra) + 1);
			push(extra, a);
			alts[a.tag] = { tag: s(o.tag), hp, key: ak };
			na++;
		}
		if (x.key) nk++;
		if (x.need) nn++;
	}
	for (let i = 0; i < length(extra); i++) push(j.outbounds, extra[i]);
	if (length(extra)) ch = true;
	print("REALITY (Zapret Manager): X25519MLKEM768 key share on " + nk + " of " + length(list) + " server(s)" + (nf ? ", fingerprint changed on " + nf : "") +
		(nn ? "; " + nn + " server(s) need sing-box-extended 2.7.2 or newer for the key share" : "") + (na ? "; test variants for " + na : ""), "\n");
	if (!ch) { try { fs.unlink(RL_ALT); } catch (e) {} exit(1); }
	if (fs.writefile(dst, sprintf("%J", j)) == null) exit(1);
	if (length(extra)) fs.writefile(RL_ALT, sprintf("%J", alts));
	else try { fs.unlink(RL_ALT); } catch (e) {}
	exit(0);
}

function rl_view(sec) {
	let j = rl_conf();
	if (!j) return null;
	let m = cursor().get_all(CFG, sec) || {}, nodes = rl_nodes(m), ln = rl_jread(RL_LEARN), alts = rl_jread(RL_ALT), hasalt = {}, r = {}, n = 0, obs = j.outbounds;
	for (let a in alts) if (type(alts[a]) == "object") hasalt[s(alts[a].tag)] = true;
	for (let i = 0; i < length(obs); i++) {
		let o = obs[i];
		if (!rl_on(o) || index(s(o.tag), RL_ALT_PFX) == 0) continue;
		let hp = rl_hp(o.server, o.server_port), ov = nodes[hp] || {}, l = type(ln[hp]) == "object" ? ln[hp] : null;
		r[s(o.tag)] = { hp, fp: s(o.tls.utls.fingerprint), key: o.tls.reality.support_x25519mlkem768 === true, ofp: s(ov.fp), omk: s(ov.mk),
			learned: l ? (int(l.k) ? "on" : "off") : "", alt: !!hasalt[s(o.tag)] };
		n++;
	}
	if (!n) return null;
	return { fp: rl_fp(m.zm_rl_fp), mk: rl_mk(m.zm_rl_mk), core: rl_core(), nodes: r, own: length(keys(nodes)) };
}

function cmd_rlnode(sec) {
	let d = null;
	try { d = json(s(fs.stdin.read("all"))); } catch (e) { d = null; }
	if (type(d) != "object") fail("пустой запрос");
	let c = cursor();
	if (d.sec != null && s(d.sec) != "") {
		let p = pick(c);
		sec = s(d.sec);
		if (sec != p.sec && index(p.conns, sec) < 0) fail("такой секции нет");
	}
	if (c.get(CFG, sec) != "section") fail("Forkozz ещё не настроен");
	let m = c.get_all(CFG, sec) || {};
	if (sec_mode(m) == "iface") fail("у туннеля нет серверов REALITY");
	let nodes = d.reset ? {} : rl_nodes(m);
	if (!d.reset) {
		let hps = type(d.hps) == "array" ? d.hps : [ d.hp ];
		let fp = d.fp == null ? null : s(d.fp), mk = d.mk == null ? null : s(d.mk);
		if (!length(hps) || length(hps) > RL_MAX) fail("не выбран сервер");
		if (fp != null && fp != "" && index(RL_FPS, fp) < 0) fail("неизвестный отпечаток");
		if (mk != null && mk != "" && mk != "on" && mk != "off") fail("неизвестное значение ключа");
		for (let i = 0; i < length(hps); i++) {
			let hp = s(hps[i]), o = null;
			if (!match(hp, RL_HP_RE)) fail("неверный адрес сервера");
			o = nodes[hp] || { fp: "", mk: "" };
			if (fp != null) o.fp = fp;
			if (mk != null) o.mk = mk;
			if (o.fp == "" && o.mk == "") delete nodes[hp];
			else nodes[hp] = o;
		}
	}
	let l = [];
	for (let hp in nodes) push(l, hp + " " + (nodes[hp].fp || "sec") + " " + (nodes[hp].mk || "sec"));
	if (length(l) > RL_MAX) fail("слишком много серверов со своими настройками — сбросьте лишние");
	l = sort(l);
	if (length(l)) c.set(CFG, sec, "zm_rl_node", l);
	else c.delete(CFG, sec, "zm_rl_node");
	c.save(CFG);
	c.commit(CFG);
	out({ ok: true, own: length(l) });
}

function cmd_rlinfo() {
	let j = rl_conf(), c = cursor(), n = 0, k = 0, fps = {}, secs = [], obs = j ? j.outbounds : [];
	for (let i = 0; i < length(obs); i++) {
		let o = obs[i];
		if (!rl_on(o) || index(s(o.tag), RL_ALT_PFX) == 0) continue;
		n++;
		if (o.tls.reality.support_x25519mlkem768 === true) k++;
		let f = s(o.tls.utls.fingerprint) || "-";
		fps[f] = int(fps[f] || 0) + 1;
	}
	let ss = sections(c, "section");
	for (let i = 0; i < length(ss); i++) {
		let m = ss[i], fp = rl_fp(m.zm_rl_fp), mk = rl_mk(m.zm_rl_mk), own = length(keys(rl_nodes(m)));
		if (fp != "auto" || mk != "auto" || own) push(secs, { name: m[".name"], fp, mk, own });
	}
	let ln = rl_jread(RL_LEARN), lon = 0, loff = 0;
	for (let h in ln) if (type(ln[h]) == "object") { if (int(ln[h].k)) lon++; else loff++; }
	out({ total: n, key: k, fps: join(", ", map(sort(keys(fps)), (f) => f + " " + fps[f])), core: n ? rl_core() : null, hook: index(s(fs.readfile(BIN)), "\n# ZM_REALITY 1\n") >= 0, secs,
		learned_on: lon, learned_off: loff, alts: length(keys(rl_jread(RL_ALT))) });
}

function sec_ext(m) {
	return {
		sub_fmt: index(SUB_FMTS, s(m.subscription_format_preference)) >= 0 ? s(m.subscription_format_preference) : "auto",
		sub_priority: flag(m.zm_sub_priority),
		ping_auto: flag(m.zm_auto_ping) && !flag(m.zm_sub_priority),
		sub_group: index(SUB_GROUPS, s(m.subscription_group_mode)) >= 0 ? s(m.subscription_group_mode) : (flag(m.group_by_countries) ? "country" : "off"),
		sub_plen: s(num_in(m.subscription_group_prefix_len, 1, 16) || 2),
		sub_incl: join(" | ", kw_list(m.subscription_filter_include_keywords)),
		sub_insecure: flag(m.subscription_insecure),
		sub_ua: s(m.subscription_user_agent),
		sub_hwid: s(m.subscription_hwid),
		sub_os: s(m.subscription_device_os),
		sub_osv: s(m.subscription_os_version),
		sub_model: s(m.subscription_device_model),
		ut_iv: index(UT_IVS, s(m.urltest_check_interval)) >= 0 ? s(m.urltest_check_interval) : "3m",
		ut_tol: s(num_in(m.urltest_tolerance, 0, 10000) ?? 50),
		ut_url: s(m.urltest_testing_url) || UT_URL_DEF,
		ut_guard: flag(m.zm_ut_guard),
		direct_fallback: flag(m.zm_direct_fallback) || flag(m.failover_direct),
		uot: flag(m.enable_udp_over_tcp),
		mixed: flag(m.mixed_proxy_enabled),
		mixed_port: s(num_in(m.mixed_proxy_port, 1, 65535) || 2080),
		real_ip: flag(m.resolve_real_ip_for_routing),
		dres_on: flag(m.domain_resolver_enabled),
		dres_type: index([ "udp", "dot", "doh" ], s(m.domain_resolver_dns_type)) >= 0 ? s(m.domain_resolver_dns_type) : "udp",
		dres_server: s(m.domain_resolver_dns_server),
		rl_fp: rl_fp(m.zm_rl_fp),
		rl_mk: rl_mk(m.zm_rl_mk)
	};
}

function fwd_view(v) {
	let m = match(s(v), /^\/([^\/]+)\/(.+)$/);
	return m ? m[1] + " " + m[2] : s(v);
}

const RU_ZONES = [ "ru", "su", "xn--p1ai" ];
const RU_YANDEX = [ "77.88.8.8", "77.88.8.1" ];
const FIP_DEF = "198.18.0.0/15";

function fwd_zone(e) {
	let m = match(s(e), /^\/([^\/]+)\//);
	return m ? m[1] : "";
}

function isp_dns() {
	for (let f in [ "/tmp/resolv.conf.d/resolv.conf.auto", "/tmp/resolv.conf.auto" ]) {
		let t = s(fs.readfile(f)), r = [];
		if (t == "") continue;
		for (let l in split(t, "\n")) {
			let m = match(l, /^[ \t]*nameserver[ \t]+([0-9]+\.[0-9]+\.[0-9]+\.[0-9]+)[ \t]*$/);
			if (m && valid_ip(m[1]) && !match(m[1], /^(127\.|0\.)/) && index(r, m[1]) < 0) push(r, m[1]);
		}
		return slice(r, 0, 4);
	}
	return [];
}

function fip_norm(v) {
	let m = match(trim(s(v)), /^([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})\.([0-9]{1,3})\/([0-9]{1,2})$/);
	if (!m) return null;
	let ip = 0, oc = [];
	for (let i = 1; i <= 4; i++) {
		let o = int(m[i]);
		if (o > 255) return null;
		push(oc, o);
		ip = ip * 256 + o;
	}
	let b = int(m[5]), size = 1;
	if (b < 15 || b > 20) return null;
	for (let i = b; i < 32; i++) size *= 2;
	let lo = 198 * 16777216 + 18 * 65536;
	if (ip % size != 0 || ip < lo || ip + size > lo + 393216) return null;
	return join(".", oc) + "/" + b;
}

function set_ext(st) {
	let src = uniq(words(st.source_network_interfaces));
	let ru = index([ "yandex", "isp" ], s(st.zm_ru)) >= 0 ? s(st.zm_ru) : "off";
	return {
		dns_ttl: s(num_in(st.dns_rewrite_ttl, 0, 86400) ?? 60),
		dns_ecs: s(st.dns_client_subnet),
		src_ifs: length(src) ? src : [ "br-lan" ],
		out_if: flag(st.enable_output_network_interface) ? s(st.output_network_interface) : "",
		badwan: flag(st.enable_badwan_interface_monitoring),
		badwan_ifs: uniq(words(st.badwan_monitored_interfaces)),
		badwan_delay: s(num_in(st.badwan_reload_delay, 0, 600000) ?? 2000),
		ipv6: flag(st.enable_ipv6),
		no_dhcp: flag(st.dont_touch_dhcp),
		excl_ntp: flag(st.exclude_ntp),
		wifi_call: flag(st.wifi_calling_direct),
		excl_bt: flag(st.exclude_bittorrent),
		bt_ports: s(st.zm_bt_ports),
		block_doh: flag(st.block_doh),
		kill: flag(st.block_leaks),
		hijack: flag(st.dns_hijack),
		quic_all: s(st.disable_quic) == "all",
		ecs_auto: flag(st.dns_client_subnet_auto),
		fwd: join("\n", map(filter(rawlist(st.dns_forward), (e) => ru == "off" || index(RU_ZONES, fwd_zone(e)) < 0), fwd_view)),
		ru,
		fakeip: fip_norm(st.zm_fakeip4) ?? "",
		p_dt: s(st.direct_tcp_ports),
		p_du: s(st.direct_udp_ports),
		p_pt: s(st.proxy_only_tcp_ports),
		p_pu: s(st.proxy_only_udp_ports),
		log_level: s(st.zm_log) == "1" && index(LOG_LEVELS, s(st.log_level)) >= 0 ? s(st.log_level) : "panic",
		yacd: flag(st.enable_yacd),
		yacd_wan: flag(st.enable_yacd_wan_access),
		yacd_secret: s(st.yacd_secret_key)
	};
}

function first_addr(v) {
	for (let x in arr(v)) {
		let m = match(s(x), /^([0-9]+\.[0-9]+\.[0-9]+\.[0-9]+)/);
		if (m) return m[1];
	}
	return "";
}

function net_info(c) {
	let nets = [], devnet = {}, netproto = {};
	try { c.load("network"); } catch (e) {}
	try {
		c.foreach("network", "interface", (x) => {
			let n = x[".name"], proto = s(x.proto), dev = s(x.device || x.ifname);
			if (dev != "" && !match(dev, /^@/) && !devnet[dev]) devnet[dev] = n;
			if (proto == "pppoe" || proto == "pppoa") dev = proto + "-" + n;
			if (match(dev, /^@/)) dev = "";
			if (dev != "" && !devnet[dev]) devnet[dev] = n;
			netproto[n] = proto;
			push(nets, { name: n, proto, dev });
		});
	} catch (e) {}
	let lan = "";
	try { lan = first_addr(c.get("network", "lan", "ipaddr")); } catch (e) {}
	let devs = [];
	for (let n in (fs.lsdir(NETDIR) || [])) {
		if (n == "lo" || match(n, /^(sit|ip6tnl|ip6gre|gre|gretap|erspan|teql|ifb|dummy|bonding_masters|wlan-|mon)/)) continue;
		let p = NETDIR + "/" + n, t = trim(s(fs.readfile(p + "/type")));
		let kind = fs.stat(p + "/wireless") || fs.stat(p + "/phy80211") ? "wifi"
			: fs.stat(p + "/bridge") ? "bridge"
			: t == "512" ? "ppp"
			: t == "65534" || t == "776" ? "tun"
			: t == "1" ? "eth" : "";
		if (kind == "") continue;
		let st = trim(s(fs.readfile(p + "/operstate")));
		let dn = devnet[n] || (netproto[n] != null ? n : "");
		push(devs, { name: n, kind, up: st != "down", net: dn, proto: dn != "" ? s(netproto[dn]) : "" });
	}
	devs = sort(devs, (a, b) => a.name < b.name ? -1 : a.name > b.name ? 1 : 0);
	return { lan_ip: lan, nets, devs };
}

function valid_ip6(v) {
	if (ml(v)) return false;
	let m = match(v, /^([0-9A-Fa-f:]+)(\/([0-9]+))?$/);
	return !!(m && index(m[1], ":") >= 0 && (m[3] == null || int(m[3]) <= 128));
}

function valid_dev(v) { return !ml(v) && !!match(v, /^[A-Za-z0-9_.@-]{1,15}$/); }

function set_opt(c, sec, key, v, def) {
	if (v == null || v == def) c.delete(CFG, sec, key);
	else c.set(CFG, sec, key, type(v) == "array" ? v : s(v));
}

function set_flag(c, sec, key, on) {
	if (on) c.set(CFG, sec, key, "1"); else c.delete(CFG, sec, key);
}

function write_sec_ext(c, sec, mode, x) {
	const SUB_KEYS = [ "subscription_format_preference", "zm_subfmt_auto", "zm_subfmt_url", "zm_subfmt_man", "zm_subfmt_chk", "subscription_insecure", "subscription_user_agent", "subscription_group_mode", "subscription_group_prefix_len", "group_by_countries", "subscription_filter_include_keywords", "zm_sub_priority",
		"subscription_hwid", "subscription_device_os", "subscription_os_version", "subscription_device_model" ];
	const UT_KEYS = [ "urltest_check_interval", "urltest_tolerance", "urltest_testing_url" ];
	const DRES_KEYS = [ "domain_resolver_dns_type", "domain_resolver_dns_server" ];
	let cur = sec_ext(c.get_all(CFG, sec) || {});
	if (type(x) != "object") x = cur;

	if (mode == "sub") {
		let fmt = s(x.sub_fmt), grp = s(x.sub_group), ua = trim(s(x.sub_ua)), inc = kw_list(x.sub_incl);
		if (index(SUB_FMTS, fmt) < 0) fmt = "auto";
		if (index(SUB_GROUPS, grp) < 0) grp = "off";
		if (length(ua) > 200 || match(ua, /[\r\n\t'"\\`$]/) || non_ascii(ua)) fail("User-Agent — одна строка латиницей до 200 символов, без кавычек");
		if (length(inc) > 40) fail("слов для отбора серверов можно указать не больше 40");
		let plen = num_in(x.sub_plen, 1, 16);
		if (grp == "prefix" && plen == null) fail("длина префикса для групп — число от 1 до 16");
		if (fmt != s(cur.sub_fmt)) {
			c.delete(CFG, sec, "zm_subfmt_auto");
			if (fmt != "auto") c.set(CFG, sec, "zm_subfmt_man", join(" ", rawlist(c.get(CFG, sec, "subscription_url"))));
			else del_keys(c, sec, [ "zm_subfmt_man", "zm_subfmt_chk" ]);
		}
		set_opt(c, sec, "subscription_format_preference", fmt, "auto");
		set_flag(c, sec, "zm_sub_priority", !!x.sub_priority);
		set_flag(c, sec, "subscription_insecure", !!x.sub_insecure);
		set_opt(c, sec, "subscription_user_agent", ua, "");
		for (let kv in [ [ "sub_hwid", "subscription_hwid", "HWID", 128 ], [ "sub_os", "subscription_device_os", "ОС устройства", 40 ],
				[ "sub_osv", "subscription_os_version", "версия ОС", 40 ], [ "sub_model", "subscription_device_model", "модель устройства", 80 ] ]) {
			let v = trim(s(x[kv[0]]));
			if (length(v) > kv[3] || match(v, /[\r\n\t'"\\`$]/) || non_ascii(v)) fail(kv[2] + " для подписки — одна строка латиницей до " + kv[3] + " символов, без кавычек");
			set_opt(c, sec, kv[1], v, "");
		}
		c.delete(CFG, sec, "group_by_countries");
		set_opt(c, sec, "subscription_group_mode", grp, "off");
		set_opt(c, sec, "subscription_group_prefix_len", grp == "prefix" ? s(plen) : null, "2");
		set_list(c, sec, "subscription_filter_include_keywords", inc);
	}
	else del_keys(c, sec, SUB_KEYS);

	if (mode != "iface") {
		let iv = s(x.ut_iv), url = trim(s(x.ut_url)), tol = num_in(x.ut_tol, 0, 10000);
		if (index(UT_IVS, iv) < 0) iv = "3m";
		if (tol == null) fail("допуск автовыбора — число миллисекунд от 0 до 10000");
		if (url == "") url = UT_URL_DEF;
		if (!valid_url(url) || match(url, /['"\\`$]/)) fail("адрес для проверки серверов должен быть ссылкой http(s)://…");
		set_opt(c, sec, "urltest_check_interval", iv, "3m");
		set_opt(c, sec, "urltest_tolerance", s(tol), "50");
		set_opt(c, sec, "urltest_testing_url", url, UT_URL_DEF);
		c.set(CFG, sec, "enable_udp_over_tcp", x.uot ? "1" : "0");
		set_flag(c, sec, "zm_direct_fallback", !!x.direct_fallback);
		c.delete(CFG, sec, "failover_direct");
		set_flag(c, sec, "zm_auto_ping", !!x.ping_auto && !(mode == "sub" && x.sub_priority));
		set_flag(c, sec, "zm_ut_guard", !!x.ut_guard && !x.ping_auto);
		set_opt(c, sec, "zm_rl_fp", rl_fp(x.rl_fp), "auto");
		set_opt(c, sec, "zm_rl_mk", rl_mk(x.rl_mk), "auto");
		del_keys(c, sec, [ "domain_resolver_enabled", ...DRES_KEYS ]);
	} else {
		del_keys(c, sec, [ ...UT_KEYS, "enable_udp_over_tcp", "zm_direct_fallback", "zm_ut_guard", "zm_auto_ping", "zm_rl_fp", "zm_rl_mk", "zm_rl_node" ]);
		if (x.dres_on) {
			let t = s(x.dres_type), v = trim(s(x.dres_server));
			if (index([ "udp", "dot", "doh" ], t) < 0) fail("неизвестный тип DNS для туннеля");
			if (!dns_value_ok(t, v))
				fail(t == "udp" ? "DNS туннеля: нужен IP-адрес, например 1.1.1.1" : t == "dot" ? "DNS туннеля: нужен адрес без https://, например one.one.one.one" : "DNS туннеля: нужен адрес сервера или ссылка https://…");
			c.set(CFG, sec, "domain_resolver_enabled", "1");
			c.set(CFG, sec, "domain_resolver_dns_type", t);
			c.set(CFG, sec, "domain_resolver_dns_server", dns_norm(t, v));
		} else {
			c.set(CFG, sec, "domain_resolver_enabled", "0");
			del_keys(c, sec, DRES_KEYS);
		}
	}

	if (x.mixed) {
		let port = num_in(x.mixed_port, 1024, 65535);
		if (port == null) fail("порт локального прокси — число от 1024 до 65535");
		if (port == 9090 || port == 5353) fail("порт " + port + " занят службами роутера — выберите другой, например 2080");
		for (let o in sections(c, "section")) {
			let n = o[".name"];
			if (n == sec || !is_conn(o) || s(o.disabled) == "1" || !flag(o.mixed_proxy_enabled)) continue;
			if ((num_in(o.mixed_proxy_port, 1, 65535) || 2080) == port)
				fail("порт " + port + " уже занят локальным прокси секции «" + sec_label(o, false) + "» — выберите другой");
		}
		c.set(CFG, sec, "mixed_proxy_enabled", "1");
		c.set(CFG, sec, "mixed_proxy_port", s(port));
	} else del_keys(c, sec, [ "mixed_proxy_enabled", "mixed_proxy_port" ]);
	set_flag(c, sec, "resolve_real_ip_for_routing", !!x.real_ip);
}

function fwd_list(v) {
	let r = [], seen = {};
	for (let l in lines(v)) {
		let zone, srv, m = match(l, /^\/([^\/]+)\/(.+)$/);
		if (m) { zone = m[1]; srv = m[2]; }
		else {
			let f = split(l, /[ \t]+/);
			if (length(f) != 2) fail("пересылка DNS по зонам: строка «" + substr(l, 0, 60) + "» — нужно «зона сервер», например «ru 77.88.8.8»");
			zone = f[0]; srv = f[1];
		}
		zone = lc(replace(trim(zone), /^\./, ""));
		srv = trim(srv);
		if (ml(zone) || length(zone) > 253 || !match(zone, /^[a-z0-9]([a-z0-9-]*[a-z0-9])?(\.[a-z0-9]([a-z0-9-]*[a-z0-9])?)*$/))
			fail("пересылка DNS по зонам: «" + substr(zone, 0, 60) + "» не похоже на зону, например ru или example.com");
		let pm = match(srv, /^(.+)#([0-9]{1,5})$/), addr = pm ? pm[1] : srv;
		if (pm && (int(pm[2]) < 1 || int(pm[2]) > 65535)) fail("пересылка DNS по зонам: неверный порт в «" + srv + "»");
		if ((!valid_ip(addr) && !valid_ip6(addr)) || index(addr, "/") >= 0) fail("пересылка DNS по зонам: «" + substr(srv, 0, 60) + "» — нужен IP-адрес DNS-сервера, например 77.88.8.8");
		if (match(addr, /^127\.0\.0\.4[0-9]$/)) fail("пересылка DNS по зонам: адрес " + addr + " занят самим Forkozz");
		let e = "/" + zone + "/" + srv;
		if (seen[zone]) fail("пересылка DNS по зонам: зона " + zone + " указана дважды");
		seen[zone] = true;
		push(r, e);
	}
	if (length(r) > 32) fail("пересылка DNS по зонам: не больше 32 строк");
	return r;
}

function port_list(v, what) {
	let r = [];
	for (let p in split(trim(s(v)), /[ \t,;]+/)) {
		if (p == "") continue;
		let m = match(p, /^([0-9]{1,5})(-([0-9]{1,5}))?$/), a = m ? int(m[1]) : 0, b = m && m[3] != null ? int(m[3]) : a;
		if (!m || a < 1 || b > 65535 || b < a) fail(what + ": «" + substr(p, 0, 20) + "» — нужен порт от 1 до 65535 или диапазон, например 22 или 6881-6889");
		push(r, a == b ? s(a) : a + "-" + b);
	}
	r = uniq(r);
	if (length(r) > 24) fail(what + ": не больше 24 портов и диапазонов");
	return join(",", r);
}

function sb_version() {
	let m = match(sh("sing-box version 2>/dev/null"), /version v?([0-9]+\.[0-9]+(\.[0-9]+)?)/);
	return m ? m[1] : "";
}

function sb_at_least(a, b) {
	let m = match(sb_version(), /^([0-9]+)\.([0-9]+)/);
	return !!m && (int(m[1]) > a || (int(m[1]) == a && int(m[2]) >= b));
}

function pool_entry(t, v) {
	if (t == "udp") return "udp://" + v;
	if (t == "dot") return "dot://" + v;
	return "doh://" + replace(v, /^https:\/\//i, "");
}

function engine_caps() {
	let b = s(fs.readfile(BIN)), fc = s(fs.readfile(NS_LIB + "/sing_box_config_facade.sh"));
	return {
		naive: !!fs.access(NS_LIB + "/naive.sh"),
		kill: !!fs.access(NS_LIB + "/kill_switch.sh"),
		fwd: !!fs.access(NS_LIB + "/dnsforward.sh"),
		ecs_auto: !!fs.access(NS_LIB + "/ecs.sh"),
		hijack: index(b, "nft_add_dns_hijack() {") >= 0,
		ports: index(b, "sing_box_configure_port_rules() {") >= 0,
		quic_all: index(b, "disable_quic_mode() {") >= 0,
		prefixes: prefix_ok(),
		tuic: index(fc, "\n    tuic)") >= 0,
		anytls: index(fc, "\n    anytls)") >= 0,
		wifi_call: index(b, "wifi_calling_direct") >= 0,
		dns_pool: index(b, "sing_box_configure_dns_pool") >= 0 && sb_at_least(1, 14),
		sb_ver: sb_version(),
		sub_id: index(s(fs.readfile(NS_LIB + "/helpers.sh")), "load_subscription_client_identity()") >= 0,
		reality: index(b, "\n# ZM_REALITY 1\n") >= 0,
		fakeip: index(s(fs.readfile(NS_LIB + "/constants.sh")), "\nSB_FAKEIP_INET4_RANGE=") >= 0,
		rl_core: rl_core()
	};
}

function write_set_ext(c, g) {
	if (type(g) != "object") return;
	const S = "settings";
	let ttl = num_in(g.dns_ttl, 0, 86400);
	if (ttl == null) fail("время жизни DNS-записей — число секунд от 0 до 86400");
	let ecs = trim(s(g.dns_ecs));
	if (ecs != "" && !valid_ip(ecs) && !valid_ip6(ecs)) fail("EDNS Client Subnet — IP-адрес или подсеть, например 203.0.113.0/24");
	c.set(CFG, S, "dns_rewrite_ttl", s(ttl));
	set_opt(c, S, "dns_client_subnet", ecs, "");

	let src = filter(uniq(words(g.src_ifs)), (v) => v != "");
	for (let v in src) if (!valid_dev(v)) fail("неверное имя интерфейса: " + v);
	if (!length(src)) fail("выберите хотя бы одну сеть, из которой Forkozz принимает трафик");
	if (length(src) > 8) fail("сетей-источников можно выбрать не больше 8");
	c.set(CFG, S, "source_network_interfaces", src);

	let oi = trim(s(g.out_if));
	if (oi != "") {
		if (!valid_dev(oi)) fail("неверное имя интерфейса для выхода: " + oi);
		if (index(src, oi) >= 0) fail("один и тот же интерфейс не может быть и источником, и выходом: " + oi);
		c.set(CFG, S, "enable_output_network_interface", "1");
		c.set(CFG, S, "output_network_interface", oi);
	} else {
		c.set(CFG, S, "enable_output_network_interface", "0");
		c.delete(CFG, S, "output_network_interface");
	}

	if (g.badwan) {
		let bw = filter(uniq(words(g.badwan_ifs)), (v) => v != "");
		for (let v in bw) if (ml(v) || !match(v, /^[A-Za-z0-9_]{1,32}$/) || v == "lan" || v == "loopback") fail("эту сеть следить нельзя: " + v);
		if (!length(bw)) fail("выберите, за какими подключениями к интернету следить");
		let dl = num_in(g.badwan_delay, 0, 600000);
		if (dl == null) fail("задержка перезапуска — число миллисекунд, например 2000");
		c.set(CFG, S, "enable_badwan_interface_monitoring", "1");
		c.set(CFG, S, "badwan_monitored_interfaces", bw);
		c.set(CFG, S, "badwan_reload_delay", s(dl));
	} else {
		c.set(CFG, S, "enable_badwan_interface_monitoring", "0");
		del_keys(c, S, [ "badwan_monitored_interfaces", "badwan_reload_delay" ]);
	}

	for (let kv in [ [ "ipv6", "enable_ipv6" ], [ "no_dhcp", "dont_touch_dhcp" ], [ "excl_ntp", "exclude_ntp" ], [ "excl_bt", "exclude_bittorrent" ], [ "block_doh", "block_doh" ] ])
		c.set(CFG, S, kv[1], g[kv[0]] ? "1" : "0");
	set_flag(c, S, "wifi_calling_direct", !!g.wifi_call);
	let btl = [];
	for (let p in split(replace(trim(s(g.bt_ports)), /[ \t;]+/g, ","), ",")) {
		if (p == "") continue;
		let m = match(p, /^([0-9]{1,5})(-([0-9]{1,5}))?$/), a = m ? +m[1] : 0, b = m && m[3] != null ? +m[3] : a;
		if (!m || a < 1024 || b > 65535 || b < a) fail("порт торрент-клиента — число от 1024 до 65535 или диапазон, например 51413 или 6881-6889");
		push(btl, a == b ? s(a) : a + "-" + b);
	}
	btl = uniq(btl);
	if (length(btl) > 8) fail("портов торрент-клиента — не больше 8");
	set_opt(c, S, "zm_bt_ports", join(",", btl), "");
	set_opt(c, S, "zm_bt_src", g.excl_bt && length(btl) ? "1" : "", "");
	if (g.kill != null) set_flag(c, S, "block_leaks", !!g.kill);
	if (g.hijack != null) set_flag(c, S, "dns_hijack", !!g.hijack);
	if (g.quic_all) c.set(CFG, S, "disable_quic", "all");
	if (g.ecs_auto != null) set_flag(c, S, "dns_client_subnet_auto", !!g.ecs_auto);
	if (g.fwd != null || g.ru != null) {
		let ru = index([ "yandex", "isp" ], s(g.ru)) >= 0 ? s(g.ru) : "off", rips = [];
		let old = s(c.get(CFG, S, "zm_ru"));
		let fl = g.fwd != null ? fwd_list(g.fwd) : filter(rawlist(c.get(CFG, S, "dns_forward")), (e) => (old != "yandex" && old != "isp") || index(RU_ZONES, fwd_zone(e)) < 0);
		if (ru != "off" && !fs.access(NS_LIB + "/dnsforward.sh")) fail("эта версия Forkozz не умеет отдельный DNS для российских сайтов — обновите Forkozz");
		if (ru == "yandex") rips = RU_YANDEX;
		if (ru == "isp") {
			rips = isp_dns();
			if (!length(rips)) fail("провайдер не выдал роутеру адреса DNS — для российских сайтов выберите Яндекс DNS");
		}
		if (ru != "off") {
			fl = filter(fl, (e) => index(RU_ZONES, fwd_zone(e)) < 0);
			for (let z in RU_ZONES) for (let ip in rips) push(fl, "/" + z + "/" + ip);
			c.set(CFG, S, "zm_ru", ru);
			c.set(CFG, S, "zm_ru_ips", rips);
		} else {
			c.delete(CFG, S, "zm_ru");
			c.delete(CFG, S, "zm_ru_ips");
		}
		if (length(fl)) c.set(CFG, S, "dns_forward", fl); else c.delete(CFG, S, "dns_forward");
	}
	if (g.fakeip != null) {
		let f = trim(s(g.fakeip));
		if (f == "" || f == FIP_DEF) c.delete(CFG, S, "zm_fakeip4");
		else {
			let n = fip_norm(f);
			if (n == null) fail("пул Fake IP — подсеть 198.18.0.0–198.23.255.255 размером от /15 до /20, например 198.20.0.0/15");
			if (n == FIP_DEF) c.delete(CFG, S, "zm_fakeip4"); else c.set(CFG, S, "zm_fakeip4", n);
		}
	}
	for (let kv in [ [ "p_dt", "direct_tcp_ports", "Порты TCP напрямую" ], [ "p_du", "direct_udp_ports", "Порты UDP напрямую" ],
			[ "p_pt", "proxy_only_tcp_ports", "Порты TCP через VPN" ], [ "p_pu", "proxy_only_udp_ports", "Порты UDP через VPN" ] ]) {
		if (g[kv[0]] == null) continue;
		let pv = port_list(g[kv[0]], kv[2]);
		if (pv != "") c.set(CFG, S, kv[1], pv); else c.delete(CFG, S, kv[1]);
	}
	let lv = s(g.log_level);
	c.set(CFG, S, "log_level", index(LOG_LEVELS, lv) >= 0 ? lv : "panic");
	c.set(CFG, S, "zm_log", "1");

	if (g.yacd) {
		c.set(CFG, S, "enable_yacd", "1");
		if (g.yacd_wan) {
			let k = trim(s(g.yacd_secret));
			if (length(k) < 8 || length(k) > 64 || ml(k) || !match(k, /^[A-Za-z0-9._~+=-]+$/)) fail("для доступа из интернета задайте ключ панели: 8–64 латинских букв, цифр или ._-~+=");
			c.set(CFG, S, "enable_yacd_wan_access", "1");
			c.set(CFG, S, "yacd_secret_key", k);
		} else {
			c.set(CFG, S, "enable_yacd_wan_access", "0");
			c.delete(CFG, S, "yacd_secret_key");
		}
	} else {
		c.set(CFG, S, "enable_yacd", "0");
		c.set(CFG, S, "enable_yacd_wan_access", "0");
		c.delete(CFG, S, "yacd_secret_key");
	}
}


const RS_DIR = getenv("ZM_FK_RSDIR") || "/opt/zapret-manager-luci/fk-rs";
const RS_MAX_FILE = 2097152;
const RS_SB_BINS = [ getenv("ZM_FK_SBBIN") || "/usr/bin/sing-box", "/usr/libexec/sing-box-core" ];

function rs_fmt(r) {
	let f = s(r.format);
	if (f == "binary" || f == "source") return f;
	let e = url_ext(r.url);
	return e == "srs" ? "binary" : e == "json" ? "source" : "";
}

function rs_ver_ok(v) {
	let m = match(s(v), /^v?([0-9]+)\.([0-9]+)/);
	return !!m && (int(m[1]) > 1 || (int(m[1]) == 1 && int(m[2]) >= 14));
}

function rs_snaps() {
	let r = {};
	for (let f in (fs.lsdir(RS_DIR) || [])) {
		let m = match(f, /^([0-9a-f]{32})\.url$/);
		if (!m) continue;
		let t = split(s(fs.readfile(RS_DIR + "/" + f)), "\n"), url = trim(s(t[0])), fmt = trim(s(t[1]));
		if (!match(url, /^https?:\/\/[^ \t]+$/) || (fmt != "binary" && fmt != "source")) continue;
		let p = RS_DIR + "/" + m[1] + (fmt == "binary" ? ".srs" : ".json"), st = fs.stat(p);
		if (!st || st.type != "file" || st.size <= 0 || st.size > RS_MAX_FILE) continue;
		r[url + "\n" + fmt] = { path: p, size: st.size, mtime: st.mtime };
	}
	return r;
}

function rs_remote(conf) {
	let r = [], rt = type(conf) == "object" && type(conf.route) == "object" ? conf.route : null;
	for (let x in (rt && type(rt.rule_set) == "array" ? rt.rule_set : [])) {
		if (type(x) != "object" || s(x.type) != "remote" || type(x.tag) != "string" || x.tag == "") continue;
		if (!match(s(x.url), /^https?:\/\/[^ \t]+$/) || rs_fmt(x) == "") continue;
		push(r, x);
	}
	return r;
}

function rs_ident(ver) {
	let p = [ s(ver) ];
	for (let b in RS_SB_BINS) {
		let st = fs.stat(b);
		if (st) push(p, b + ":" + st.size + ":" + st.mtime);
	}
	return join("|", p);
}

function rs_cap_read(id) {
	let t = split(trim(s(fs.readfile(RS_DIR + "/cap"))), "\t");
	return length(t) == 2 && t[0] == id && (t[1] == "yes" || t[1] == "no") ? t[1] : "";
}

function cmd_rs_cap(id, v) {
	if (s(id) == "" || (v != "yes" && v != "no")) exit(1);
	if (rs_cap_read(id) == v) exit(0);
	try { fs.mkdir(RS_DIR); } catch (e) {}
	let tmp = RS_DIR + "/cap.zmn";
	if (fs.writefile(tmp, id + "\t" + v + "\n") == null || !fs.rename(tmp, RS_DIR + "/cap")) { try { fs.unlink(tmp); } catch (e) {} exit(1); }
	exit(0);
}

function cmd_rs_initial(inp, outp) {
	if (s(inp) == "" || s(outp) == "") exit(1);
	let ver = trim(s(getenv("ZM_SB_VER")));
	if (!rs_ver_ok(ver)) {
		let m = match(sh("sing-box version"), /version v?([0-9][^ \t\r\n]*)/);
		ver = m ? m[1] : "";
	}
	if (!rs_ver_ok(ver)) exit(3);
	let id = rs_ident(ver), cap = rs_cap_read(id);
	if (cap == "no") exit(3);
	let conf = null;
	try { conf = json(s(fs.readfile(inp))); } catch (e) { exit(1); }
	let snaps = rs_snaps(), pm = {}, n = 0;
	if (!length(keys(snaps))) exit(3);
	for (let x in rs_remote(conf)) {
		if (x.initial_path != null) continue;
		let sn = snaps[s(x.url) + "\n" + rs_fmt(x)];
		if (sn && pm[x.tag] == null) { pm[x.tag] = sn.path; n++; }
	}
	if (!n) exit(3);
	if (fs.writefile(outp, sprintf("%J", pm)) == null) exit(1);
	if (cap == "yes") exit(0);
	print(id, "\n");
	exit(4);
}

function cmd_rs_plan() {
	let conf = null, seen = {}, px = "";
	try { conf = json(s(fs.readfile(SB_CONF))); } catch (e) { conf = null; }
	if (type(conf) != "object") exit(1);
	for (let ib in (type(conf.inbounds) == "array" ? conf.inbounds : []))
		if (type(ib) == "object" && s(ib.tag) == "service-mixed-in" && s(ib.type) == "mixed" && int(ib.listen_port) > 0)
			px = (s(ib.listen) != "" ? s(ib.listen) : "127.0.0.1") + ":" + int(ib.listen_port);
	if (px != "") print("P\t", px, "\n");
	for (let x in rs_remote(conf)) {
		let fmt = rs_fmt(x), k = s(x.url) + "\n" + fmt;
		if (seen[k]) continue;
		seen[k] = true;
		let via = s(x.download_detour) != "" || (type(x.http_client) == "object" && s(x.http_client.detour) != "") ? "p" : "d";
		print("R\t", fmt, "\t", via, "\t", s(x.url), "\n");
	}
	exit(0);
}

function rs_info() {
	let st = cursor().get_all(CFG, "settings") || {}, n = 0, bytes = 0, at = 0;
	let sn = rs_snaps();
	for (let k in keys(sn)) { let v = sn[k]; n++; bytes += v.size; if (v.mtime > at) at = v.mtime; }
	let t = split(trim(s(fs.readfile(RS_DIR + "/cap"))), "\t");
	return { on: s(st.zm_rs_snap) != "0", n, bytes, at, cap: length(t) == 2 && t[1] == "no" && t[0] == rs_ident(split(t[0], "|")[0]) ? "no" : "" };
}

function cmd_get(want) {
	let c = cursor(), p = pick(c), sec = p.sec, main = p.sec;
	want = s(want);
	if (want != "" && want != main && index(p.conns, want) >= 0) sec = want;
	let m = c.get_all(CFG, sec) || {}, st = c.get_all(CFG, "settings") || {}, mm = c.get_all(CFG, main) || {};
	let mode = sec_mode(m), rf = sec_refs(m), subs = sub_urls(m);
	out({
		sec,
		main,
		is_main: sec == main,
		main_exists: mm[".type"] != null && sec_configured(mm),
		label: sec_label(m, sec == main),
		enabled: sec == main || s(m.disabled) != "1",
		sections: sec_list(c, p),
		bypass: bypass_info(c),
		legacy_bypass: legacy_bypass_info(c),
		exists: m[".type"] != null && sec_configured(m),
		mode: mode == "json" ? "links" : mode,
		links: sec_links(m),
		sub: length(subs) ? subs[0] : "",
		subs,
		sub_interval: s(m.subscription_update_interval || "1h"),
		iface: s(m.interface),
		fastest: true,
		exclude: s(m.zm_exclude),
		hide_names: rawlist(m.zm_hide),
		jsons: mode == "json" ? 1 : 0,
		refs: { c: rf.c, s: rf.s, r: rf.r, n: rf.n },
		catalog: { items: catalog_items(services_list()), meta: cat_meta() },
		own_on: !own_off(m),
		domains: own_view(m, rf.l).domains,
		subnets: own_view(m, rf.l).subnets,
		lists: own_view(m, rf.l).lists,
		full: device_ips(m),
		all: all_ips(m),
		excl: uniq(words(st.routing_excluded_ips)),
		extra: p.extra,
		dns: dns_info(st),
		quic_off: index([ "1", "all", "tunneled", "true", "yes", "on" ], s(st.disable_quic)) >= 0,
		caps: engine_caps(),
		list_interval: s(st.update_interval || "1d"),
		list_update: true,
		lists_via: s(st.download_lists_via_proxy) == "1",
		devices: devices(),
		tunnels: tunnels(),
		x: sec_ext(m),
		g: set_ext(st),
		isp_dns: isp_dns(),
		net: net_info(c),
		rs: rs_info()
	});
}

function cmd_set() {
	let raw = fs.stdin.read("all"), d;
	try { d = json(s(raw)); } catch (e) { fail("не удалось прочитать настройки"); }
	if (type(d) != "object") fail("пустые настройки");
	let c = cursor(), p0 = pick(c), sec = s(d.sec) || p0.sec, created = false;
	if (sec == "new") {
		if (c.get(CFG, p0.sec) != "section" || !sec_configured(c.get_all(CFG, p0.sec))) fail("сначала настройте основную секцию");
		if (length(p0.conns) >= 8) fail("секций можно сделать не больше 9");
		let i = 1;
		while (c.get(CFG, "zm_s" + i) != null) i++;
		sec = "zm_s" + i;
		created = true;
	}
	if (ml(sec) || !match(sec, /^[A-Za-z0-9_]+$/) || sec == BYPASS || sec == "settings") fail("неверное имя секции");
	let st = c.get(CFG, sec);
	if (st != null && st != "section") fail("неверное имя секции");
	if (st != null && !is_conn(c.get_all(CFG, sec)) && s(c.get(CFG, sec, "connection_type")) != "") fail("эту секцию Forkozz не редактирует");
	let is_main = sec == p0.sec, mainsec = p0.sec;
	if (!is_main && (c.get(CFG, mainsec) != "section" || !sec_configured(c.get_all(CFG, mainsec)))) fail("сначала настройте основную секцию");
	let label = trim(s(d.label));
	if (match(label, /[\r\n\t]/) || length(label) > 60) fail("название секции — одна строка до 60 символов");
	if (!is_main && label == "") fail("дайте секции название");
	if (label != "")
		for (let x in sec_list(c, p0))
			if (x.name != sec && fold(x.label) == fold(label)) fail("секция «" + label + "» уже есть — выберите другое название");
	let mode = s(d.mode);
	if (index([ "links", "sub", "iface" ], mode) < 0) fail("неизвестный способ подключения");

	let links = [];
	for (let l in lines(d.links))
		for (let w in split(l, /[ \t]+/)) {
			if (w == "") continue;
			if (!length(links) || match(w, /^[A-Za-z0-9+]+:\/\//)) push(links, w);
			else links[length(links) - 1] += "%20" + w;
		}
	links = uniq(links);
	let naive_ok = !!fs.access(NS_LIB + "/naive.sh"), ec = engine_caps();
	let more = (ec.tuic ? ", tuic" : "") + (ec.anytls ? ", anytls" : "");
	for (let x in links)
		if (!match(x, SCHEMES) && !(naive_ok && match(x, SCHEMES_NAIVE)) && !(ec.tuic && match(x, /^tuic:\/\/[^ \t\r\n]+$/i)) && !(ec.anytls && match(x, /^anytls:\/\/[^ \t\r\n]+$/i)))
			fail(match(x, /^naive\+/i) ? (naive_ok ? "ссылке NaiveProxy нужны логин и пароль: naive+https://логин:пароль@сервер" : "NaiveProxy работает с движком Forkozz 0.9.11 и новее — обновите Forkozz") : match(x, /^(tuic|http|https|anytls|wireguard|hysteria):\/\//i) ? "Forkozz не поддерживает такие ссылки: " + substr(x, 0, 40) + " — подойдут vless, vmess, trojan, ss, socks5, hysteria2" + (naive_ok ? ", naive" : "") + more : "ссылка не поддерживается: " + substr(x, 0, 40));
	let subs = uniq(lines(type(d.subs) == "array" && length(d.subs) ? d.subs : d.sub)), iface = trim(s(d.iface));
	if (mode == "links" && !length(links)) fail("добавьте хотя бы одну ссылку на сервер");
	if (mode == "sub") {
		if (!length(subs)) fail("вставьте ссылку на подписку");
		if (length(subs) > SUB_MAX) fail("подписок в одной секции можно указать не больше " + SUB_MAX);
		for (let u in subs) if (!valid_url(u) || match(u, /['"\\`]/)) fail("ссылка на подписку должна начинаться с https:// — ошибка в «" + substr(u, 0, 60) + "»");
	}
	if (mode == "iface" && !valid_dev(iface)) fail("выберите сетевой интерфейс");

	let known = services_list(), refs = type(d.refs) == "object" ? d.refs : {};
	let services = filter(uniq(words(refs.c)), (x) => index(known, x) >= 0);
	let rsets = uniq(words(refs.s)), rsubs = uniq(words(refs.r)), rnets = uniq(words(refs.n)), rplain = uniq(words(refs.l));
	for (let x in uniq(words(refs.c))) if (index(known, x) < 0 && EXTRA_SRS[x]) push(rsets, EXTRA_SRS[x]);
	let rfx = refs_fix({ s: rsets, r: rsubs, n: rnets });
	rsets = rfx.s; rsubs = rfx.r; rnets = rfx.n;
	for (let x in [ ...rsets, ...rsubs, ...rnets ])
		if (!match(x, /^https?:\/\/[^ \t]+$/i)) fail("неверная ссылка на набор правил: " + substr(x, 0, 60));
	for (let x in rplain)
		if (!valid_url(x) && !pkg_local(x)) fail("неверная ссылка на список: " + substr(x, 0, 60));
	let domains = parse_domains(d.domains);
	let subnets = uniq(tokens(d.subnets));
	for (let x in subnets) if (!valid_ip(x)) fail("это не похоже на IP или подсеть: " + x);
	let lists = uniq(tokens(d.lists));
	for (let x in lists) if (!valid_url(x) && !pkg_local(x)) fail("внешний список должен быть ссылкой https://…: " + x);
	let own_on = d.own_on == null ? !own_off(c.get_all(CFG, sec) || {}) : !!d.own_on;
	let keep = { domains, subnets, lists };
	if (!own_on) { domains = []; subnets = []; lists = []; }
	lists = uniq([ ...lists, ...rplain ]);
	let full = d.full == null ? device_ips(c.get_all(CFG, sec) || {}) : uniq(tokens(d.full));
	let excl = d.excl == null ? uniq(words(c.get(CFG, "settings", "routing_excluded_ips"))) : uniq(tokens(d.excl));
	let all = d.all == null ? all_ips(c.get_all(CFG, sec) || {}) : uniq(tokens(d.all));
	for (let x in [ ...full, ...excl, ...all ]) if (!valid_ip(x)) fail("неверный адрес устройства: " + x);
	if (length(all) > 64) fail("устройств с полным трафиком через VPN можно выбрать не больше 64");
	if (!length(all) && !length(services) && !length(rsets) && !length(rsubs) && !length(rnets) && !length(domains) && !length(subnets) && !length(lists) && (length(full) || created || !sec_configured(c.get_all(CFG, sec) || {})))
		fail(!own_on && (length(keep.domains) || length(keep.subnets) || length(keep.lists))
			? "«Свой список» выключен, а других сервисов в секции нет — включите его или выберите сервис"
			: "выберите для секции хотя бы один сервис, домен или адрес — устройства только ограничивают её правила");

	for (let x in sections(c, "section")) {
		let n = x[".name"];
		if (n == sec || !is_conn(x) || (n != p0.sec && index(p0.conns, n) < 0)) continue;
		for (let v in all) for (let w in all_ips(x)) if (device_ip_overlap(v, w))
			fail("устройство " + v + " уже целиком идёт через секцию «" + sec_label(x, n == p0.sec) + "» — весь трафик устройства можно отдать только одной секции");
		if (!device_scopes_overlap(full, device_ips(x))) continue;
		let other = sec_label(x, n == p0.sec), orf = sec_refs(x);
		for (let v in services) if (index(words(x.community_lists), v) >= 0) fail("список «" + v + "» уже идёт через секцию «" + other + "» — один список можно включить только в одной секции");
		for (let v in [ ...rsets, ...rsubs, ...rnets ]) if (index([ ...orf.s, ...orf.r, ...orf.n ], v) >= 0) fail("набор правил уже идёт через секцию «" + other + "»: " + substr(v, 0, 60));
		let od = domain_lines(x);
		for (let v in domains) if (index(od, v) >= 0) fail("домен " + v + " уже есть в секции «" + other + "» — оставьте его в одной секции");
		let os = subnet_lines(x);
		for (let v in subnets) if (index(os, v) >= 0) fail("адрес " + v + " уже есть в секции «" + other + "» — оставьте его в одной секции");
	}

	let bp = type(d.bypass) == "object" ? d.bypass : null, bdom = [], bsub = [];
	if (bp) {
		for (let x in uniq(tokens(bp.domains))) {
			let e = domain_err(x);
			if (e) fail("в исключениях " + e);
			push(bdom, norm_domain(x));
		}
		bdom = uniq(bdom);
		bsub = uniq(tokens(bp.subnets));
		for (let x in bsub) if (!valid_ip(x)) fail("в исключениях это не похоже на IP или подсеть: " + x);
		if (length(bdom) + length(bsub) > 2000) fail("исключений слишком много — не больше 2000 строк");
	}

	let xstr = trim(s(d.exclude));
	if (mode == "iface") xstr = "";
	if (match(xstr, /[\r\n]/) || length(xstr) > 1600) fail("маркеры — одной строкой через |, не длиннее 1600 символов");
	let xv = { m: excl_list(xstr), h: mode == "iface" ? [] : rawlist(c.get(CFG, sec, "zm_hide")) };
	if (length(xv.m) > 40) fail("маркеров можно указать не больше 40");
	if (!length(xv.m)) xstr = "";
	if (mode == "links" && excl_any(xv) && !length(filter(links, (l) => !excl_hit(link_name(l), xv))))
		fail("под эти маркеры попадают все серверы — тогда Forkozz работать не сможет. Уберите лишние маркеры");

	if (!c.get(CFG, sec)) c.set(CFG, sec, "section");
	if (label != "") c.set(CFG, sec, "zm_label", label);
	if (is_main || d.enabled !== false) c.delete(CFG, sec, "disabled"); else c.set(CFG, sec, "disabled", "1");
	c.delete(CFG, sec, "global_proxy");

	del_keys(c, sec, [ ...LINK_KEYS, "outbound_json", "subscription_url", "interface", "subscription_filter_exclude_keywords", "subscription_filter_include_keywords" ]);
	if (mode == "iface") {
		c.set(CFG, sec, "connection_type", "vpn");
		c.delete(CFG, sec, "proxy_config_type");
		c.set(CFG, sec, "interface", iface);
		del_keys(c, sec, [ "zm_links", "zm_exclude", "zm_hide", "subscription_update_interval" ]);
	} else {
		c.set(CFG, sec, "connection_type", "proxy");
		if (xstr != "") c.set(CFG, sec, "zm_exclude", xstr); else c.delete(CFG, sec, "zm_exclude");
		if (mode == "links") {
			c.set(CFG, sec, "proxy_config_type", "urltest");
			c.set(CFG, sec, "zm_links", links);
			c.delete(CFG, sec, "subscription_update_interval");
		} else {
			c.set(CFG, sec, "proxy_config_type", "subscription");
			c.set(CFG, sec, "subscription_url", subs);
			let iv = s(d.sub_interval);
			if (index(SUB_IVS, iv) < 0) iv = "1h";
			c.set(CFG, sec, "subscription_update_interval", iv);
			c.delete(CFG, sec, "zm_links");
		}
		apply_servers(c, sec);
	}
	write_sec_ext(c, sec, mode, d.x);

	set_lists(c, sec, { s: rsets, r: rsubs, n: rnets, l: lists }, services, domains, subnets);
	if (own_on || !(length(keep.domains) || length(keep.subnets) || length(keep.lists))) {
		del_keys(c, sec, [ "zm_own_off", "zm_own_domains", "zm_own_subnets", "zm_own_lists" ]);
	} else {
		c.set(CFG, sec, "zm_own_off", "1");
		if (length(keep.domains)) c.set(CFG, sec, "zm_own_domains", join("\n", keep.domains)); else c.delete(CFG, sec, "zm_own_domains");
		if (length(keep.subnets)) c.set(CFG, sec, "zm_own_subnets", join("\n", keep.subnets)); else c.delete(CFG, sec, "zm_own_subnets");
		set_list(c, sec, "zm_own_lists", keep.lists);
	}
	write_device_lists(c, sec, full, excl, all);

	if (bp) {
		if (length(bdom) || length(bsub)) {
			if (c.get(CFG, BYPASS) == null) c.set(CFG, BYPASS, "section");
			c.set(CFG, BYPASS, "zm_label", "Исключения");
			c.set(CFG, BYPASS, "connection_type", "exclusion");
			c.delete(CFG, BYPASS, "disabled");
			set_lists(c, BYPASS, { s: [], r: [], n: [], l: [] }, [], bdom, bsub);
			c.delete(CFG, BYPASS, "zm_refs");
			c.reorder(CFG, BYPASS, 1);
		}
		else if (c.get(CFG, BYPASS) != null) c.delete(CFG, BYPASS);
	}

	if (!c.get(CFG, "settings")) c.set(CFG, "settings", "settings");
	let dns = type(d.dns) == "object" ? d.dns : null;
	if (dns) {
		let t = s(dns.type);
		if (index([ "udp", "dot", "doh" ], t) < 0) fail("неизвестный тип DNS");
		let list = type(dns.servers) == "array" && length(dns.servers) ? dns.servers : [ dns.server ];
		let blist = type(dns.bootstraps) == "array" && length(dns.bootstraps) ? dns.bootstraps : [ dns.bootstrap ];
		let svs = [], bss = [], seen = {};
		for (let x in list) {
			x = trim(s(x));
			if (x == "" || seen[x]) continue;
			seen[x] = true;
			if (!dns_value_ok(t, x))
				fail(t == "udp" ? "для UDP нужен IP-адрес DNS, например 9.9.9.9 (ошибка в «" + x + "»)"
					: t == "dot" ? "для DoT нужен адрес сервера без https://, например dns.quad9.net (ошибка в «" + x + "»)"
					: "для DoH нужен адрес сервера или ссылка https://… (ошибка в «" + x + "»)");
			push(svs, dns_norm(t, x));
		}
		svs = uniq(svs);
		if (!length(svs)) fail("укажите хотя бы один DNS-сервер");
		if (length(svs) > 8) fail("DNS-серверов можно указать не больше 8");
		seen = {};
		for (let x in blist) {
			x = trim(s(x));
			if (x == "" || seen[x]) continue;
			seen[x] = true;
			if (!valid_ip(x) || index(x, "/") >= 0) fail("Bootstrap DNS — только IPv4-адреса, например 77.88.8.8 (ошибка в «" + x + "»)");
			push(bss, x);
		}
		if (!length(bss)) push(bss, "9.9.9.9");
		if (length(bss) > 4) bss = slice(bss, 0, 4);
		c.set(CFG, "settings", "dns_type", t);
		c.set(CFG, "settings", "dns_server", svs[0]);
		c.set(CFG, "settings", "bootstrap_dns_server", bss[0]);
		c.set(CFG, "settings", "zm_dns_servers", svs);
		c.set(CFG, "settings", "zm_bootstrap", bss);
		let pool = dns.pool != null ? s(dns.pool) : s(c.get(CFG, "settings", "dns_pool_mode"));
		if (index([ "fallback", "race" ], pool) >= 0 && length(svs) > 1) {
			c.set(CFG, "settings", "dns_pool_mode", pool);
			c.set(CFG, "settings", "dns_pool_server", map(slice(svs, 1), (x) => pool_entry(t, x)));
		} else {
			c.delete(CFG, "settings", "dns_pool_mode");
			c.delete(CFG, "settings", "dns_pool_server");
		}
		if (dns.detour != null) {
			c.set(CFG, "settings", "dns_via_outbound", dns.detour ? "1" : "0");
			if (dns.detour) c.set(CFG, "settings", "dns_outbound_section", mainsec);
			else c.delete(CFG, "settings", "dns_outbound_section");
		}
	}
	if (d.quic_off != null) c.set(CFG, "settings", "disable_quic", d.quic_off ? "1" : "0");
	if (d.lists_via != null) {
		c.set(CFG, "settings", "download_lists_via_proxy", d.lists_via ? "1" : "0");
		if (d.lists_via) c.set(CFG, "settings", "download_lists_via_proxy_section", mainsec);
		else c.delete(CFG, "settings", "download_lists_via_proxy_section");
	}
	if (index(LIST_IVS, s(d.list_interval)) >= 0) c.set(CFG, "settings", "update_interval", s(d.list_interval));
	write_set_ext(c, d.g);

	c.save(CFG);
	c.commit(CFG);
	out({ ok: true, sec, created });
}


function group_tag(sec) { return sec + "-out"; }
function fallback_tag(sec) { return sec + "-zm-fallback-out"; }
function priority_tag(sec) { return sec + "-zm-priority-out"; }
function priority_manual_file(sec) { return "/tmp/zm-fk-priority-manual." + sec; }
function ping_tag(sec) { return sec + "-zm-ping-out"; }
function ping_manual_file(sec) { return "/tmp/zm-fk-ping-manual." + sec; }
function ping_state_file(sec) { return "/tmp/zm-fk-ping-state." + sec; }
function ping_on(m) { return flag(m.zm_auto_ping) && !flag(m.zm_sub_priority) && s(m.connection_type) == "proxy" && !flag(m.disabled); }

function cmd_fallback_config() {
	let conf = null;
	try { conf = json(s(fs.stdin.read("all"))); } catch (e) {}
	if (type(conf) != "object" || type(conf.outbounds) != "array") fail("не удалось прочитать конфиг sing-box");
	let c = cursor(), obs = {};
	for (let ob in conf.outbounds) obs[s(ob.tag)] = ob;
	let meta = conf._zm_priority_feeds || {};
	delete conf._zm_priority_feeds;
	for (let m in sections(c, "section")) {
		if (!flag(m.zm_sub_priority) || sec_mode(m) != "sub" || flag(m.disabled)) continue;
		let sec = m[".name"], original = obs[group_tag(sec)], feeds = meta[sec], groups = [];
		if (!original) continue;
		if (s(original.type) != "selector" || type(feeds) != "array" || !length(feeds)) fail("не удалось определить принадлежность серверов к подпискам секции " + sec);
		for (let i = 0; i < length(feeds); i++) {
			let feed = feeds[i], tags = uniq(arr(feed.tags));
			if (!length(tags)) continue;
			for (let t in tags) if (!obs[t] || type(obs[t].outbounds) == "array") fail("не найден сервер подписки: " + t);
			let tag = sec + "-zm-priority-feed-" + (i + 1) + ": " + s(feed.name);
			if (obs[tag]) fail("имя группы подписки уже занято: " + tag);
			let ob = { type: "selector", tag, outbounds: tags, default: tags[0], interrupt_exist_connections: true };
			push(conf.outbounds, ob); obs[tag] = ob; push(groups, tag);
		}
		let tag = priority_tag(sec);
		if (!length(groups) || obs[tag]) fail("не удалось собрать порядок подписок секции " + sec);
		let ob = { type: "selector", tag, outbounds: groups, default: groups[0], interrupt_exist_connections: true };
		push(conf.outbounds, ob); obs[tag] = ob;
		original.outbounds = [ tag, ...original.outbounds ];
		original.default = tag;
	}
	for (let m in sections(c, "section")) {
		if (!ping_on(m)) continue;
		let sec = m[".name"], original = obs[group_tag(sec)], tag = ping_tag(sec);
		if (!original || s(original.type) != "selector") continue;
		let todo = [ group_tag(sec) ], seen = {}, leaves = [];
		for (let i = 0; i < length(todo); i++) {
			let t = todo[i], ob = obs[t];
			if (seen[t] || !ob) continue;
			seen[t] = true;
			if (type(ob.outbounds) == "array") { for (let child in ob.outbounds) push(todo, child); }
			else if (index([ "direct", "reject", "block", "dns" ], s(ob.type)) < 0) push(leaves, t);
		}
		leaves = uniq(leaves);
		if (length(leaves) < 2) continue;
		if (obs[tag]) fail("имя группы автовыбора по пингу уже занято: " + tag);
		let ob = { type: "selector", tag, outbounds: leaves, default: leaves[0], interrupt_exist_connections: true };
		push(conf.outbounds, ob); obs[tag] = ob;
		original.outbounds = [ tag, ...original.outbounds ];
		original.default = tag;
	}
	for (let m in sections(c, "section")) {
		if (!flag(m.zm_direct_fallback) || s(m.connection_type) != "proxy" || flag(m.disabled)) continue;
		let sec = m[".name"], original = group_tag(sec), tag = fallback_tag(sec);
		if (!obs["direct-out"] || s(obs["direct-out"].type) != "direct") fail("в конфиге нет прямого выхода");
		if (obs[tag]) fail("имя резервного выхода уже занято: " + tag);
		let todo = obs[original] ? [ original ] : [], seen = {}, leaves = [];
		for (let i = 0; i < length(todo); i++) {
			let t = todo[i], ob = obs[t];
			if (seen[t] || !ob) continue;
			seen[t] = true;
			if (type(ob.outbounds) == "array") { for (let child in ob.outbounds) push(todo, child); }
			else if (index([ "direct", "reject", "block", "dns" ], s(ob.type)) < 0) push(leaves, t);
		}
		push(conf.outbounds, { type: "selector", tag, outbounds: obs[original] ? uniq([ original, ...leaves, "direct-out" ]) : [ "direct-out" ],
			default: obs[original] ? original : "direct-out", interrupt_exist_connections: true });
		for (let dns in (conf.dns && type(conf.dns.servers) == "array" ? conf.dns.servers : []))
			if (s(dns.detour) == original) dns.detour = tag;
	}
	let st = c.get_all(CFG, "settings") || {};
	if (flag(st.exclude_bittorrent) && s(st.zm_bt_src) == "1" && type(conf.route) == "object" && type(conf.route.rules) == "array") {
		let rules = conf.route.rules, at = -1, ports = [], ranges = [];
		for (let i = 0; i < length(rules) && at < 0; i++) {
			let p = rules[i].protocol;
			if (p == "bittorrent" || (type(p) == "array" && index(p, "bittorrent") >= 0)) at = i;
		}
		for (let p in split(s(st.zm_bt_ports), ",")) {
			if (match(p, /^[0-9]+-[0-9]+$/)) push(ranges, replace(p, "-", ":"));
			else if (match(p, /^[0-9]+$/)) push(ports, +p);
		}
		if (at >= 0 && length(ports) + length(ranges)) {
			let bt = rules[at], mk = (pk, rk) => {
				let r = { inbound: bt.inbound, network: [ "tcp", "udp" ] };
				if (length(ports)) r[pk] = ports;
				if (length(ranges)) r[rk] = ranges;
				if (bt.action != null) r.action = bt.action;
				if (bt.outbound != null) r.outbound = bt.outbound;
				return r;
			};
			splice(rules, at + 1, 0, mk("source_port", "source_port_range"), mk("port", "port_range"));
		}
	}
	out(conf);
}

function fallback_info(sec, px) {
	let g = px ? px[fallback_tag(sec)] : null;
	let now = g ? s(g.now) : "";
	return { enabled: !!g, direct: now == "direct-out", override: now != "" && now != "direct-out" && now != group_tag(sec) ? now : "" };
}

function auto_tag(sec, px, g) {
	let tags = g && type(g.all) == "array" ? g.all : [];
	let priority = priority_tag(sec);
	if (index(tags, priority) >= 0 && px[priority] && lc(s(px[priority].type)) == "selector") return priority;
	let pingt = ping_tag(sec);
	if (index(tags, pingt) >= 0 && px[pingt] && lc(s(px[pingt].type)) == "selector") return pingt;
	let tag = sec + "-urltest-out";
	let valid = (t) => index(tags, t) >= 0 && px[t] && lc(s(px[t].type)) == "urltest";
	if (valid(tag)) return tag;
	let conf = null;
	try { conf = json(s(fs.readfile(SB_CONF))); } catch (e) {}
	for (let ob in (conf && type(conf.outbounds) == "array" ? conf.outbounds : []))
		if (ob.tag == group_tag(sec) && valid(s(ob.default))) return s(ob.default);
	for (let t in tags) if (valid(t)) return t;
	return null;
}

function proxy_now(px, tag) {
	let seen = {};
	while (px[tag] && index([ "urltest", "selector" ], lc(s(px[tag].type))) >= 0 && !seen[tag]) {
		seen[tag] = true;
		let next = s(px[tag].now);
		if (next == "") break;
		tag = next;
	}
	return tag;
}

function sec_names(c, sec) {
	let m = c.get_all(CFG, sec) || {}, names = {};
	if (sec_mode(m) == "links") {
		let vis = visible_links(m, excl_vars(m));
		for (let i = 0; i < length(vis); i++) {
			let n = link_name(vis[i]);
			names[sec + "-" + (i + 1) + "-out"] = n != "" ? n : link_host(vis[i]) || ("сервер " + (i + 1));
		}
	}
	names[sec + "-urltest-out"] = "Авто";
	names[priority_tag(sec)] = "Авто · порядок подписок";
	names[ping_tag(sec)] = "Авто · по пингу";
	return names;
}

function node_info(px, names, t) {
	let p = px[t] || {}, h = type(p.history) == "array" && length(p.history) ? p.history[length(p.history) - 1] : null;
	let feed = match(t, /-zm-priority-feed-[0-9]+: (.*)$/);
	return { name: s(names[t] || (feed ? "Подписка: " + feed[1] : t)), country: "", type: s(p.type), now: s(p.now || ""), delay: h ? int(h.delay || 0) : -1,
		members: (lc(s(p.type)) == "urltest" || index(t, "-zm-priority-") >= 0 || index(t, "-zm-ping-") >= 0) && type(p.all) == "array" ? p.all : null };
}

function b64any(v) {
	let b = replace(replace(trim(s(v)), /-/g, "+"), /_/g, "/");
	while (length(b) % 4) b += "=";
	let r = null;
	try { r = b64dec(b); } catch (e) { r = null; }
	return r;
}

function sub_cache_path(sec) { return STATE + "/fk.sub." + sec + ".json"; }

const NS_SUBS = "/etc/netshift/subscriptions";

function url_base(u) { return split(s(u), "#")[0]; }

function url_md5(u) {
	let h = trim(sh("printf %s " + q(url_base(u)) + " | md5sum"));
	let m = match(h, /^([0-9a-f]{32})/);
	return m ? m[1] : "";
}

function sub_raw_names(sec, m) {
	let out = [], seen = {};
	for (let u in sub_urls(m)) {
		let j = null, h = url_md5(u);
		for (let f in [ h != "" ? NS_SUBS + "/" + sec + "." + h + ".json" : null, NS_SUBS + "/" + sec + ".json" ]) {
			if (!f) continue;
			try { j = json(s(fs.readfile(f))); } catch (e) { j = null; }
			if (type(j) == "object") break;
		}
		if (type(j) != "object" || type(j.outbounds) != "array") continue;
		for (let ob in j.outbounds) {
			if (type(ob) != "object" || index([ "selector", "urltest", "direct", "dns", "block" ], s(ob.type)) >= 0) continue;
			let n = s(ob.remark || ob.tag);
			if (n != "" && !seen[n]) { seen[n] = true; push(out, n); }
		}
	}
	return out;
}

function name_set(list) { let r = {}; for (let n in list) r[n] = true; return r; }

function sub_disp(t, raw, px, own) {
	if (raw && length(keys(raw))) {
		if (raw[t]) return t;
		let m = match(t, /^(.+)-([0-9]+)$/);
		return m && raw[m[1]] ? m[1] : t;
	}
	let m = match(t, /^(.+)-([0-9]+)$/);
	return m && px && px[m[1]] && own && !own[m[1]] ? m[1] : t;
}

function excl_sub_hit(name, f) {
	name = fold(name);
	for (let x in f.m) if (x != "" && index(name, x) >= 0) return true;
	for (let h in f.h) { h = fold(h); if (h != "" && index(name, h) >= 0) return true; }
	return false;
}

function utf8_cut(v, n) {
	if (length(v) <= n) return v;
	let i = n;
	while (i > 0 && (ord(v, i) & 0xC0) == 0x80) i--;
	return substr(v, 0, i);
}

function sub_hdr_txt(v, n, nl) {
	v = trim(s(v));
	let bm = match(v, /^base64:(.*)$/);
	if (bm) v = s(b64any(bm[1]));
	if (!nl) return utf8_cut(trim(replace(v, /[[:cntrl:]]+/g, " ")), n);
	let ls = filter(map(split(replace(v, /\r\n?/g, "\n"), "\n"), (x) => trim(replace(x, /[[:cntrl:]]+/g, " "))), (x) => x != "");
	return utf8_cut(join("\n", slice(ls, 0, 8)), n);
}

function sub_hdr_url(v) {
	v = trim(s(v));
	return length(v) <= 300 && match(v, /^https?:\/\/[^ \t"'<>\\`]+$/i) ? v : "";
}

function sub_hdr_num(v) {
	let m = match(trim(s(v)), /^([0-9]{1,15})(\.[0-9]+)?$/);
	return m ? int(m[1]) : null;
}

function ns_info_path(sec, h) {
	for (let f in [ h != "" ? NS_SUBS + "/" + sec + "." + h + ".info.json" : null, NS_SUBS + "/" + sec + ".info.json" ])
		if (f && fs.access(f)) return f;
	return null;
}

function ns_info(sec, h) {
	let f = ns_info_path(sec, h);
	if (!f) return null;
	let j = null, st = fs.stat(f);
	try { j = json(s(fs.readfile(f))); } catch (e) { j = null; }
	if (type(j) != "object") return null;
	let up = j.upload, down = j.download, has = up != null || down != null || j.total != null || j.expire != null;
	return {
		title: sub_hdr_txt(j.title, 120),
		used: has ? int(up || 0) + int(down || 0) : null,
		total: int(j.total || 0) > 0 ? int(j.total) : null,
		unlimited: has && !(int(j.total || 0) > 0),
		expire: int(j.expire || 0) > 0 ? int(j.expire) : null,
		at: st ? st.mtime : 0
	};
}

function ns_hwid() {
	let h = trim(sh(". " + q(NS_LIB + "/helpers.sh") + " >/dev/null 2>&1 && command -v generate_hwid >/dev/null 2>&1 && generate_hwid"));
	return length(h) <= 128 && match(h, /^[A-Za-z0-9._:-]+$/) ? h : "";
}

function sub_ident(sec, m, h) {
	let opt = (k) => trim(replace(s(m["subscription_" + k]), /[\r\n]+/g, ""));
	let ua = opt("user_agent");
	if (ua == "") for (let f in [ h != "" ? NS_SUBS + "/" + sec + "." + h + ".user_agent" : null, NS_SUBS + "/" + sec + ".user_agent" ]) {
		if (!f || !fs.access(f)) continue;
		try { ua = trim(replace(s(fs.readfile(f)), /[\r\n]+/g, "")); } catch (e) { ua = ""; }
		if (ua != "") break;
	}
	if (ua == "") { let v = sb_version(); ua = "singbox/" + (v != "" ? v : "1.12.0"); }
	let model = opt("device_model");
	if (model == "") model = trim(s(fs.readfile("/tmp/sysinfo/model"))) || "OpenWrt Router";
	let osv = opt("os_version");
	if (osv == "") osv = trim(sh("uname -r"));
	return { ua, hwid: opt("hwid") || ns_hwid(), os: opt("device_os") || "OpenWrt Linux", osv, model, insecure: flag(m.subscription_insecure) };
}

function sub_headers(u, id) {
	let cmd = "curl -sS -L --max-redirs 5 -m 12 -b '' -D - -o /dev/null -A " + q(id.ua);
	if (id.hwid != "") cmd += " -H " + q("X-HWID: " + id.hwid);
	cmd += " -H " + q("X-Device-OS: " + id.os) + " -H " + q("X-Device-Model: " + id.model) + " -H " + q("X-Ver-OS: " + id.osv);
	cmd += " -H 'Accept-Language: ru-RU,en,*' -H 'X-Device-Locale: EN'";
	if (id.insecure) cmd += " -k";
	let hd = {}, code = 0;
	for (let l in split(sh(cmd + " " + q(url_base(u))), /\r?\n/)) {
		let st = match(l, /^HTTP\/[0-9.]+[ \t]+([0-9]{3})/);
		if (st) { code = int(st[1]); hd = {}; continue; }
		let mm = match(l, /^([A-Za-z0-9-]+):[ \t]*(.*)$/);
		if (mm) hd[lc(mm[1])] = trim(mm[2]);
	}
	return code >= 200 && code < 300 ? hd : null;
}

function cmd_subinfo(sec) {
	let c = cursor(), m = c.get_all(CFG, sec) || {}, urls = sub_urls(m);
	if (!length(urls)) { out({ ok: false }); return; }
	let h = url_md5(urls[0]), id = sub_ident(sec, m, h), hd = sub_headers(urls[0], id) || {};
	let info = { title: "", used: null, total: null, unlimited: false, expire: null, refill: null, announce: "", announce_url: "", support: "", web: "", at: time(), hash: h, src: "" };
	let ui = s(hd["subscription-userinfo"]);
	if (ui != "") {
		let up = 0, down = 0, has = false;
		for (let kv in split(ui, ";")) {
			let p = match(trim(kv), /^([a-z]+)[ \t]*=[ \t]*([0-9]+)/);
			if (!p) continue;
			has = true;
			if (p[1] == "upload") up = int(p[2]);
			else if (p[1] == "download") down = int(p[2]);
			else if (p[1] == "total") info.total = int(p[2]);
			else if (p[1] == "expire") info.expire = int(p[2]) > 0 ? int(p[2]) : null;
		}
		if (has) {
			info.used = up + down;
			if (!(info.total > 0)) { info.total = null; info.unlimited = true; }
			info.src = "panel";
		}
	}
	info.title = sub_hdr_txt(hd["profile-title"], 120);
	info.announce = sub_hdr_txt(hd["announce"], 500, true);
	info.announce_url = sub_hdr_url(hd["announce-url"]);
	info.support = sub_hdr_url(hd["support-url"]);
	info.web = sub_hdr_url(hd["profile-web-page-url"]);
	let rf = sub_hdr_num(hd["subscription-refill-date"]);
	info.refill = rf != null && rf > 0 ? rf : null;
	try { fs.mkdir(STATE); } catch (e) {}
	let f = sub_cache_path(sec);
	fs.writefile(f + ".tmp", sprintf("%J", info));
	fs.rename(f + ".tmp", f);
	out({ ok: true });
}


function sub_feed(sec) {
	let upd = 0, ua = "";
	for (let f in (fs.lsdir(NS_SUBS) || [])) {
		if (f != sec + ".json" && index(f, sec + ".") != 0) continue;
		if (match(f, /\.json$/)) {
			let st = fs.stat(NS_SUBS + "/" + f);
			if (st && st.mtime > upd) upd = st.mtime;
		} else if (match(f, /\.user_agent$/) && ua == "") {
			try { ua = trim(s(fs.readfile(NS_SUBS + "/" + f))); } catch (e) { ua = ""; }
		}
	}
	let fmt = ua == "" ? "" : match(ua, /^sing-?box/i) ? "sing-box" : match(ua, /^(happ|v2ray)/i) ? "Xray (Happ)" : match(ua, /clash/i) ? "Clash" : match(ua, /hiddify/i) ? "Hiddify" : ua;
	return { updated: upd > 0 ? upd : null, fmt };
}

function sub_info(sec) {
	let j = null, u = sub_urls(cursor().get_all(CFG, sec) || {})[0], h = u ? url_md5(u) : "";
	try { j = json(s(fs.readfile(sub_cache_path(sec)))); } catch (e) { j = null; }
	if (type(j) == "object" && s(j.hash) != h) j = null;
	let ns = u ? ns_info(sec, h) : null;
	let ttl = ns ? 21600 : 1800;
	if (u && (type(j) != "object" || time() - int(j.at || 0) > ttl || time() < int(j.at || 0))) {
		let lk = "/tmp/zm-fk-subinfo." + sec, ls = fs.stat(lk);
		if (!ls || time() - int(ls.mtime) > 60 || time() < int(ls.mtime)) {
			fs.writefile(lk, "");
			system("(ucode " + q(sourcepath()) + " subinfo " + q(sec) + " >/dev/null 2>&1 &)");
		}
	}
	let fd = sub_feed(sec);
	if (type(j) != "object") j = {};
	let r = { title: s(j.title), used: j.used, total: j.total, unlimited: !!j.unlimited, expire: j.expire, refill: j.refill,
		announce: s(j.announce), announce_url: s(j.announce_url), support: s(j.support), web: s(j.web), updated: fd.updated, fmt: fd.fmt };
	if (ns && (j.used == null || s(j.src) != "panel" || int(ns.at) > int(j.at || 0))) {
		if (ns.used != null) { r.used = ns.used; r.total = ns.total; r.unlimited = ns.unlimited; }
		if (ns.expire != null) r.expire = ns.expire;
		if (ns.title != "") r.title = ns.title;
	}
	if (r.title == "" && ns && ns.title != "") r.title = ns.title;
	return r;
}

const FELL_FILE = getenv("ZM_FK_FELL") || STATE + "/fk.fell";

function fell_file(sec) {
	let c = cursor();
	return sec == "" || sec == pick(c).sec ? FELL_FILE : FELL_FILE + "." + sec;
}

function lat_path(sec) { return STATE + "/fk.lat." + sec + ".json"; }
const LAT_MODE_FILE = STATE + "/fk.latmode";
function lat_mode() { return trim(s(fs.readfile(LAT_MODE_FILE))) == "real" ? "real" : "fast"; }
function cmd_latmode(v) {
	if (v == "real") { try { fs.mkdir(STATE); } catch (e) {} if (fs.writefile(LAT_MODE_FILE, "real\n") == null) fail("не удалось сохранить настройку"); }
	else if (v == "fast") { try { fs.unlink(LAT_MODE_FILE); } catch (e) {} }
	else if (v != "") fail("неизвестный способ проверки");
	out({ ok: true, mode: lat_mode() });
}
const NODE_POL_FILE = STATE + "/fk.nodepol";
function node_pol() { let v = trim(s(fs.readfile(NODE_POL_FILE))); return v == "switch" || v == "hold" ? v : "back"; }
function home_path(sec) { return STATE + "/fk.home." + sec; }
function home_read(sec) {
	let j = null;
	try { j = json(s(fs.readfile(home_path(sec)))); } catch (e) { j = null; }
	return type(j) == "object" && s(j.tag) != "" ? j : null;
}
function home_drop(sec) { try { fs.unlink(home_path(sec)); } catch (e) {} }
function cmd_nodepol(v) {
	if (v == "switch" || v == "hold") {
		try { fs.mkdir(STATE); } catch (e) {}
		if (fs.writefile(NODE_POL_FILE, v + "\n") == null) fail("не удалось сохранить настройку");
		for (let f in (fs.lsdir(STATE) || [])) if (substr(f, 0, 8) == "fk.home.") try { fs.unlink(STATE + "/" + f); } catch (e) {}
	}
	else if (v == "back") { try { fs.unlink(NODE_POL_FILE); } catch (e) {} }
	else if (v != "") fail("неизвестная настройка");
	out({ ok: true, pol: node_pol() });
}

function lat_read(sec) {
	let j = null;
	try { j = json(s(fs.readfile(lat_path(sec)))); } catch (e) { j = null; }
	return type(j) == "object" ? j : null;
}
function lat_running(l) { return !!(l && l.running && time() - int(l.at || 0) < 300); }

function proxies() {
	let j = jcmd(BIN + " clash_api get_proxies");
	return j && type(j.proxies) == "object" ? j.proxies : null;
}

function cmd_servers(sec) {
	let px = proxies();
	if (!px) fail("sing-box не отвечает — Forkozz выключен или ещё запускается");
	let g = px[group_tag(sec)];
	let fallback = fallback_info(sec, px);
	if ((!g || type(g.all) != "array") && !fallback.direct) fail("список серверов ещё не готов — примените настройки");
	if (!g || type(g.all) != "array") g = { all: [], now: "" };
	let c = cursor(), xm = c.get_all(CFG, sec) || {}, xv = excl_vars(xm), names = sec_names(c, sec);
	let nodes = {};
	let pending = slice(g.all, 0);
	for (let i = 0; i < length(pending); i++) {
		let t = pending[i];
		if (nodes[t]) continue;
		nodes[t] = node_info(px, names, t);
		for (let m in (nodes[t].members || [])) if (!nodes[m]) push(pending, m);
	}
	let fell = "";
	try { fell = trim(s(fs.readfile(fell_file(sec)))); } catch (e) { fell = ""; }
	let lat = lat_read(sec), lrun = lat_running(lat);
	if (lat && (lrun || time() - int(lat.at || 0) < 900)) {
		let dl = type(lat.delays) == "object" ? lat.delays : {}, rl = type(lat.real) == "object" ? lat.real : {};
		let bl = {}, rp = {};
		for (let t in (type(lat.blocked) == "array" ? lat.blocked : [])) bl[t] = true;
		for (let t in (type(lat.rpending) == "array" ? lat.rpending : [])) rp[t] = true;
		for (let t in (type(lat.tested) == "array" ? lat.tested : [])) if (nodes[t]) {
			nodes[t].delay = int(dl[t] || 0);
			if (rl[t] != null) { nodes[t].tcp = nodes[t].delay; nodes[t].delay = int(rl[t] || 0); }
			if (bl[t]) { nodes[t].tcp = int(dl[t] || 0); nodes[t].delay = 0; nodes[t].blocked = true; }
			if (lrun && rp[t]) { nodes[t].tcp = int(dl[t] || 0); nodes[t].rpend = true; }
		}
		if (lrun) for (let t in (type(lat.pending) == "array" ? lat.pending : [])) if (nodes[t]) nodes[t].delay = -2;
	}
	let sub_hidden = null;
	if (sec_mode(xm) == "sub") {
		let rawl = sub_raw_names(sec, xm), raw = name_set(rawl), own = name_set(filter(keys(nodes), (t) => !nodes[t].members));
		for (let t in keys(nodes)) if (!nodes[t].members && names[t] == null) nodes[t].name = sub_disp(t, raw, px, own);
		let fixed = [], ch = false;
		for (let h in xv.h) {
			let n = (!raw[h] && px[h]) ? sub_disp(h, raw, px, own) : h;
			if (n != h) ch = true;
			if (index(fixed, n) < 0) push(fixed, n);
		}
		if (ch) {
			c.set(CFG, sec, "zm_hide", fixed);
			apply_servers(c, sec);
			c.save(CFG);
			c.commit(CFG);
			xv = excl_vars(c.get_all(CFG, sec) || {});
		}
		if (length(rawl) && excl_any(xv)) sub_hidden = filter(rawl, (n) => excl_sub_hit(n, xv));
	}
	let home = node_pol() == "back" ? home_read(sec) : null, rl = rl_view(sec);
	if (rl) {
		let rn = {};
		for (let t in rl.nodes) if (nodes[t]) rn[t] = rl.nodes[t];
		rl.nodes = rn;
		if (!length(keys(rn))) rl = null;
	}
	out({ group: group_tag(sec), reality: rl, auto_tag: auto_tag(sec, px, g), now: fallback.override || s(g.now), list: g.all, nodes, sub: sec_mode(xm) == "sub" ? sub_info(sec) : null,
		hidden: length(xv.h), exclude: s(xm.zm_exclude), hide_names: xv.h, sub_hidden, fell, fallback, priority: flag(xm.zm_sub_priority), ping: ping_on(xm), lat_mode: lat_mode(), lat: lat ? { running: lrun, at: int(lat.at || 0), error: s(lat.error), mode: s(lat.mode) } : null,
		home: home ? s(home.name || home.tag) : "", home_tag: home ? s(home.tag) : "", node_pol: node_pol() });
}

const LAT_URLS = [ "https://www.gstatic.com/generate_204", "http://cp.cloudflare.com/generate_204",
	"https://www.google.com/generate_204", "http://connectivitycheck.gstatic.com/generate_204" ];
const LAT_PAR = 4;
let LAT_SEQ = 0;

function clash_ep() {
	let j = null;
	try { j = json(s(fs.readfile(SB_CONF))); } catch (e) { j = null; }
	let ca = j && type(j.experimental) == "object" && type(j.experimental.clash_api) == "object" ? j.experimental.clash_api : null;
	let ec = ca ? s(ca.external_controller) : "";
	if (ec == "") return null;
	let m = match(ec, /^(.*):([0-9]+)$/);
	let host = m ? m[1] : "127.0.0.1", port = m ? m[2] : "9090";
	if (host == "" || host == "0.0.0.0" || host == "::" || host == "[::]") host = "127.0.0.1";
	return { base: "http://" + host + ":" + port, secret: s(ca.secret) };
}

function urlenc(v) {
	let o = "", str = s(v);
	for (let i = 0; i < length(str); i++) {
		let b = ord(str, i), c = chr(b);
		o += match(c, /^[A-Za-z0-9_.~-]$/) ? c : sprintf("%%%02X", b);
	}
	return o;
}

function lat_cmd(ep, tag, url, ms) {
	return "curl -s --noproxy '*' --max-time " + (int(ms / 1000) + 3) + (ep.secret != "" ? " -H " + q("Authorization: Bearer " + ep.secret) : "") +
		" -G --data-urlencode " + q("url=" + url) + " --data-urlencode " + q("timeout=" + ms) +
		" " + q(ep.base + "/proxies/" + urlenc(tag) + "/delay");
}

function lat_parse(raw) {
	let j = null;
	try { j = json(trim(s(raw))); } catch (e) { j = null; }
	return type(j) == "object" ? int(j.delay || 0) : 0;
}

function lat_batch(ep, tags, url, ms) {
	let res = {};
	let dir = "/tmp/zm-fk-lat." + s(fs.readlink("/proc/self")) + "." + (++LAT_SEQ);
	if (fs.mkdir(dir) == null) fail("не удалось создать временную папку для проверки серверов");
	for (let i = 0; i < length(tags); i += LAT_PAR) {
		let part = slice(tags, i, i + LAT_PAR), cmd = "";
		for (let k = 0; k < length(part); k++)
			cmd += "(" + lat_cmd(ep, part[k], url, ms) + " > " + q(dir + "/" + k) + " 2>/dev/null) & ";
		sh(cmd + "wait");
		for (let k = 0; k < length(part); k++) {
			let d = 0;
			try { d = lat_parse(fs.readfile(dir + "/" + k)); } catch (e) { d = 0; }
			if (d > 0) res[part[k]] = d;
		}
	}
	sh("rm -rf " + q(dir));
	return res;
}

const UDP_TYPES = { hysteria: true, hysteria2: true, tuic: true, wireguard: true, awg: true, quic: true };

function node_addrs() {
	let j = null, r = {};
	try { j = json(s(fs.readfile(SB_CONF))); } catch (e) { j = null; }
	if (!j || type(j.outbounds) != "array") return r;
	for (let o in j.outbounds) {
		if (type(o) != "object" || s(o.tag) == "" || s(o.server) == "" || int(o.server_port || 0) <= 0) continue;
		if (UDP_TYPES[lc(s(o.type))]) continue;
		r[s(o.tag)] = { host: s(o.server), port: int(o.server_port) };
	}
	return r;
}

function tcp_cmd(a, to) {
	let h = index(a.host, ":") >= 0 ? "[" + a.host + "]" : a.host;
	return "curl -s -o /dev/null --noproxy '*' --connect-timeout " + to + " --max-time " + to + " -w '%{time_connect} %{time_namelookup}' " + q("http://" + h + ":" + a.port + "/");
}

function tcp_parse(raw) {
	let f = split(trim(s(raw)), " ");
	if (length(f) < 2) return 0;
	let c = +f[0], n = +f[1];
	if (!(c > 0)) return 0;
	let ms = int((c - (n > 0 && n < c ? n : 0)) * 1000 + 0.5);
	return ms < 1 ? 1 : ms;
}

const TCP_PAR = 10;
let TCP_SEQ = 0;

function tcp_chunk(addrs, part, to) {
	let res = {}, dir = STATE + "/tcp.tmp." + s(fs.readlink("/proc/self")) + "." + (++TCP_SEQ), cmd = "";
	try { fs.mkdir(STATE); } catch (e) {}
	try { fs.mkdir(dir); } catch (e) {}
	for (let k = 0; k < length(part); k++) {
		let c = tcp_cmd(addrs[part[k]], to), f = q(dir + "/" + k);
		cmd += "(" + c + " > " + f + ".a) 2>/dev/null & (" + c + " > " + f + ".b) 2>/dev/null & ";
	}
	sh(cmd + "wait");
	for (let k = 0; k < length(part); k++) {
		let a = 0, b = 0;
		try { a = tcp_parse(fs.readfile(dir + "/" + k + ".a")); } catch (e) { a = 0; }
		try { b = tcp_parse(fs.readfile(dir + "/" + k + ".b")); } catch (e) { b = 0; }
		let best = (a > 0 && b > 0) ? (a < b ? a : b) : (a > 0 ? a : b);
		if (best > 0) res[part[k]] = best;
	}
	sh("rm -rf " + q(dir));
	return res;
}

function probe_ms(tag, ms, passes) {
	let ep = clash_ep();
	if (ep && sh("command -v curl") != "") {
		for (let i = 0; i < (passes || 3); i++) {
			let d = lat_parse(sh(lat_cmd(ep, tag, LAT_URLS[i % length(LAT_URLS)], ms + i * 1500)));
			if (d > 0) return d;
		}
		return 0;
	}
	let l = jcmd(BIN + " clash_api get_proxy_latency " + q(tag) + " " + ms);
	return type(l) == "object" ? int(l.delay || 0) : 0;
}

function proxy_alive(tag) {
	return probe_ms(tag, 6000, 3) > 0;
}

function vpn_members(px, tag) {
	let todo = [ tag ], seen = {}, leaves = [];
	for (let i = 0; i < length(todo); i++) {
		let t = todo[i], p = px[t];
		if (seen[t] || !p) continue;
		seen[t] = true;
		if (type(p.all) == "array") { for (let child in p.all) push(todo, child); }
		else if (index([ "direct", "reject", "block", "dns" ], lc(s(p.type))) < 0) push(leaves, t);
	}
	return leaves;
}

function select_proxy(group, tag) {
	let r = jcmd(BIN + " clash_api set_group_proxy " + q(group) + " " + q(tag));
	if (type(r) != "object" || r.error || r.success === false) return false;
	let px = proxies();
	return !!(px && px[group] && s(px[group].now) == tag);
}

function priority_active(sec, m, px) {
	let g = px ? px[group_tag(sec)] : null;
	if (!flag(m.zm_sub_priority) || sec_mode(m) != "sub" || !g || !px[priority_tag(sec)]) return false;
	let manual = trim(s(fs.readfile(priority_manual_file(sec))));
	return s(g.now) == priority_tag(sec) || manual == "" || manual != s(g.now);
}

function ping_active(sec, m, px) {
	let g = px ? px[group_tag(sec)] : null;
	if (!ping_on(m) || !g || !px[ping_tag(sec)]) return false;
	let manual = trim(s(fs.readfile(ping_manual_file(sec))));
	return s(g.now) == ping_tag(sec) || manual == "" || manual != s(g.now);
}

function node_alive(ep, tag, urls) {
	for (let url in urls) if (lat_batch(ep, [ tag ], url, 5000)[tag] > 0) return true;
	return false;
}

function ping_pick(sec, px, ep, urls, snapshot, tol) {
	let pt = ping_tag(sec), p = px[pt];
	if (!p || type(p.all) != "array" || !length(p.all)) return { ok: true, changed: false };
	let cur = s(p.now), st = null;
	try { st = json(s(fs.readfile(ping_state_file(sec)))); } catch (e) { st = null; }
	let cur_ok = cur != "" && node_alive(ep, cur, urls);
	if (cur_ok && type(st) == "object" && s(st.tag) == cur && time() - int(st.at || 0) < 900) return { ok: true, changed: false };

	let addrs = node_addrs(), delays = {}, tcp = filter(p.all, (t) => !!addrs[t]), other = filter(p.all, (t) => !addrs[t]);
	for (let i = 0; i < length(tcp); i += TCP_PAR) {
		if (snapshot != s(fs.readfile(SB_CONF))) return null;
		let r = tcp_chunk(addrs, slice(tcp, i, i + TCP_PAR), 3);
		for (let t in keys(r)) delays[t] = r[t];
	}
	if (length(other)) {
		let r = lat_batch(ep, other, urls[0], 5000);
		for (let t in keys(r)) delays[t] = r[t];
	}
	let real = {};
	if (lat_mode() == "real") {
		let cand = slice(sort(filter(tcp, (t) => delays[t] > 0), (a, b) => delays[a] - delays[b]), 0, 12);
		if (cur != "" && delays[cur] > 0 && index(cand, cur) < 0 && addrs[cur]) push(cand, cur);
		if (length(cand)) {
			if (snapshot != s(fs.readfile(SB_CONF))) return null;
			let r = lat_batch(ep, cand, urls[0], 5000);
			for (let t in cand) real[t] = r[t] ? r[t] : 0;
		}
	}
	let score = (t) => real[t] != null ? (real[t] > 0 ? real[t] : 0) : (delays[t] > 0 ? (length(keys(real)) && addrs[t] ? 100000 + delays[t] : delays[t]) : 0);
	let ranked = sort(filter(keys(delays), (t) => score(t) > 0), (a, b) => score(a) - score(b)), best = "";
	for (let t in keys(real)) if (real[t] == 0 && delays[t] > 0) push(ranked, t);
	for (let i = 0; i < length(ranked) && i < 6; i++) {
		if (snapshot != s(fs.readfile(SB_CONF))) return null;
		if (ranked[i] == cur ? cur_ok : (real[ranked[i]] > 0 || node_alive(ep, ranked[i], urls))) { best = ranked[i]; break; }
	}
	let target = cur;
	if (!cur_ok) target = best;
	else if (best != "" && best != cur && score(cur) > 0 && score(best) > 0 && score(cur) > score(best) + tol) target = best;
	if (target == "") return { ok: true, changed: false, dead: true };
	if (target != cur) {
		if (snapshot != s(fs.readfile(SB_CONF)) || !select_proxy(pt, target)) return null;
		let names = sec_names(cursor(), sec);
		system("logger -t zapret-manager " + q("Forkozz: авто по пингу — " + (cur_ok ? "нашёлся сервер быстрее" : "сервер не отвечает") + ", секция " + sec + " переключена на самый быстрый из рабочих"));
		if (!cur_ok) try { fs.writefile(fell_file(sec), s(names[cur] || cur) + "\n"); } catch (e) {}
	}
	fs.writefile(ping_state_file(sec), sprintf("%J", { tag: target, at: time() }));
	return { ok: true, changed: false, switched: target != cur };
}

function priority_probe(sec, px, ep, urls, snapshot, tolerance) {
	let p = px[priority_tag(sec)];
	if (!p || type(p.all) != "array") return null;
	for (let feed in p.all) {
		let group = px[feed];
		if (!group || type(group.all) != "array" || !length(group.all)) return null;
		let delays = {};
		for (let url in urls) {
			for (let i = 0; i < length(group.all); i += LAT_PAR) {
				if (snapshot != s(fs.readfile(SB_CONF))) return null;
				let r = lat_batch(ep, slice(group.all, i, i + LAT_PAR), url, 5000);
				for (let t in keys(r)) delays[t] = r[t];
			}
			if (length(keys(delays))) break;
		}
		let best = "";
		for (let t in group.all) if (delays[t] > 0 && (best == "" || delays[t] < delays[best])) best = t;
		if (best == "") continue;
		let current = s(group.now);
		if (delays[current] > 0 && delays[current] <= delays[best] + tolerance) best = current;
		return { feed, node: best };
	}
	return { feed: "", node: "" };
}

const FW_STATE = getenv("ZM_FK_FWSTATE") || "/tmp/zm-fk-fallst.";
const FW_BAD_N = 2;

function fw_get(sec) {
	let j = null;
	try { j = json(s(fs.readfile(FW_STATE + sec))); } catch (e) { j = null; }
	if (type(j) != "object") j = {};
	return { bad: int(j.bad || 0), good: int(j.good || 0), since: int(j.since || 0), flips: type(j.flips) == "array" ? j.flips : [] };
}

function fw_put(sec, st) {
	let now = time();
	st.flips = filter(st.flips, (t) => now - int(t) < 1800 && int(t) <= now);
	fs.writefile(FW_STATE + sec, sprintf("%J", st));
}

function wan_alive() {
	if (getenv("ZM_FK_WAN") != null) return getenv("ZM_FK_WAN") == "1";
	return trim(sh("for h in 77.88.8.8 8.8.8.8 1.1.1.1; do ping -4 -c 1 -W 2 $h >/dev/null 2>&1 && { echo y; exit 0; }; done; curl -s -o /dev/null --noproxy '*' --connect-timeout 3 --max-time 5 http://1.1.1.1/ >/dev/null 2>&1 && echo y")) == "y";
}

function fw_down(sec) {
	let st = fw_get(sec);
	st.good = 0;
	if (!wan_alive()) { fw_put(sec, st); return { wan_down: true }; }
	st.bad = st.bad + 1;
	fw_put(sec, st);
	return st.bad < FW_BAD_N ? { pending: true } : null;
}

function fw_back(sec) {
	let st = fw_get(sec), now = time(), flips = length(filter(st.flips, (t) => now - int(t) < 1800));
	let need = flips >= 4 ? 4 : 2, dwell = flips >= 4 ? 600 : 120;
	st.bad = 0;
	st.good = st.good + 1;
	fw_put(sec, st);
	return st.good >= need && (st.since <= 0 || now < st.since || now - st.since >= dwell);
}

function fw_out(r, x) {
	for (let k in x) r[k] = x[k];
	return r;
}

function fw_mark(sec) {
	let st = fw_get(sec), now = time();
	st.bad = 0; st.good = 0; st.since = now;
	push(st.flips, now);
	fw_put(sec, st);
}

function fw_calm(sec, direct) {
	let st = fw_get(sec);
	if (direct ? st.good == 0 : st.bad == 0) return;
	if (direct) st.good = 0; else st.bad = 0;
	fw_put(sec, st);
}

function cmd_fallwatch(sec) {
	let lock = "/tmp/zm-fk-fallback." + sec + ".lock";
	if (fs.access(lock)) fs.writefile(lock + "/pid", s(fs.readlink("/proc/self")));
	let c = cursor(), m = c.get_all(CFG, sec) || {};
	let allow_direct = flag(m.zm_direct_fallback), pingm = ping_on(m);
	if ((!allow_direct && !flag(m.zm_sub_priority) && !pingm) || flag(m.disabled) || s(m.connection_type) != "proxy") { out({ ok: true }); return; }
	let snapshot = s(fs.readfile(SB_CONF)), px = proxies(), wrapper = px ? px[fallback_tag(sec)] : null;
	let g = px ? px[group_tag(sec)] : null;
	let priority = priority_active(sec, m, px), pingact = !priority && pingm && ping_active(sec, m, px);
	if (!priority && !pingact && !allow_direct) { out({ ok: true, manual: !!g }); return; }
	if ((priority && s(g.now) != priority_tag(sec)) || (pingact && s(g.now) != ping_tag(sec))) {
		if (!select_proxy(group_tag(sec), priority ? priority_tag(sec) : ping_tag(sec))) { out({ ok: false }); return; }
		px = proxies(); g = px ? px[group_tag(sec)] : null;
		if (!g) { out({ ok: false }); return; }
	}
	if (allow_direct && (!wrapper || type(wrapper.all) != "array")) { out({ ok: false }); return; }
	let tags = vpn_members(px, group_tag(sec)), ep = clash_ep();
	if (!ep || sh("command -v curl") == "") { out({ ok: false }); return; }
	if (!length(tags)) { out({ ok: true, direct: !!(wrapper && s(wrapper.now) == "direct-out"), empty: true }); return; }
	let current = fallback_info(sec, px).override || proxy_now(px, s(g.now)), order = index(tags, current) >= 0 ? uniq([ current, ...tags ]) : tags;
	let urls = uniq([ sec_ext(m).ut_url, "https://www.cloudflare.com/cdn-cgi/trace" ]), healthy = "";
	if (pingact) {
		let r = ping_pick(sec, px, ep, urls, snapshot, int(sec_ext(m).ut_tol));
		if (r == null) { out({ ok: false }); return; }
		if (!allow_direct) { out({ ok: true, ping: true, changed: false }); return; }
		px = proxies(); g = px ? px[group_tag(sec)] : null;
		if (!g) { out({ ok: false }); return; }
	}
	if (priority) {
		let chosen = priority_probe(sec, px, ep, urls, snapshot, int(sec_ext(m).ut_tol));
		c = cursor(); m = c.get_all(CFG, sec) || {}; px = proxies();
		if (!chosen || flag(m.disabled) || flag(m.zm_direct_fallback) != allow_direct || snapshot != s(fs.readfile(SB_CONF)) || !priority_active(sec, m, px)) { out({ ok: false }); return; }
		let before = proxy_now(px, group_tag(sec)), direct = fallback_info(sec, px).direct;
		let ensure = (group, tag) => s(px[group] && px[group].now) == tag || select_proxy(group, tag);
		if (chosen.feed != "") {
			if (!ensure(chosen.feed, chosen.node) || !ensure(priority_tag(sec), chosen.feed) || !ensure(group_tag(sec), priority_tag(sec))) { out({ ok: false }); return; }
			if (allow_direct && direct && !fw_back(sec)) { out({ ok: true, priority: true, direct: true, recovering: true, changed: false }); return; }
			if (allow_direct && !ensure(fallback_tag(sec), group_tag(sec))) { out({ ok: false }); return; }
			if (allow_direct && direct) fw_mark(sec);
			else if (allow_direct) fw_calm(sec, false);
			out({ ok: true, priority: true, direct: false, changed: direct || before != chosen.node });
		} else {
			if (!ensure(group_tag(sec), priority_tag(sec))) { out({ ok: false }); return; }
			if (allow_direct && direct) fw_calm(sec, true);
			if (allow_direct && !direct) {
				let hold = fw_down(sec);
				if (hold) { out(fw_out({ ok: true, priority: true, direct: false, changed: false }, hold)); return; }
			}
			let changed = allow_direct && !direct && select_proxy(fallback_tag(sec), "direct-out");
			if (changed) fw_mark(sec);
			out({ ok: !allow_direct || direct || changed, priority: true, direct: allow_direct, changed });
		}
		return;
	}
	for (let url in urls) {
		for (let i = 0; i < length(order); i += LAT_PAR) {
			if (snapshot != s(fs.readfile(SB_CONF))) { out({ ok: false }); return; }
			let part = slice(order, i, i + LAT_PAR), delays = lat_batch(ep, part, url, 5000);
			for (let t in part) if (delays[t] > 0) { healthy = t; break; }
			if (healthy != "") break;
		}
		if (healthy != "") break;
	}
	c = cursor();
	m = c.get_all(CFG, sec) || {};
	px = proxies();
	wrapper = px ? px[fallback_tag(sec)] : null;
	g = px ? px[group_tag(sec)] : null;
	if (!flag(m.zm_direct_fallback) || flag(m.disabled) || snapshot != s(fs.readfile(SB_CONF)) || !wrapper || !g || priority_active(sec, m, px)) { out({ ok: false }); return; }
	if (healthy == "") {
		if (s(wrapper.now) == "direct-out") { fw_calm(sec, true); out({ ok: true, direct: true }); return; }
		let hold = fw_down(sec);
		if (hold) { out(fw_out({ ok: true, direct: false, changed: false }, hold)); return; }
		let changed = select_proxy(fallback_tag(sec), "direct-out");
		if (changed) fw_mark(sec);
		out({ ok: changed, changed, direct: true });
		return;
	}
	let selected = s(g.now), target = group_tag(sec), was_direct = s(wrapper.now) == "direct-out";
	if (was_direct && !fw_back(sec)) { out({ ok: true, direct: true, recovering: true, changed: false }); return; }
	if (!was_direct) fw_calm(sec, false);
	if (proxy_now(px, selected) != healthy && !proxy_alive(selected)) {
		let auto = auto_tag(sec, px, g);
		let pickt = auto && proxy_alive(auto) ? auto : index(g.all, healthy) >= 0 ? healthy : "";
		if (pickt != "") {
			if (!select_proxy(group_tag(sec), pickt)) { out({ ok: false }); return; }
		} else target = healthy;
	}
	if (s(wrapper.now) == target) { out({ ok: true, direct: false }); return; }
	if (snapshot != s(fs.readfile(SB_CONF))) { out({ ok: false }); return; }
	let changed = select_proxy(fallback_tag(sec), target);
	if (changed && was_direct) fw_mark(sec);
	out({ ok: changed, changed: changed && was_direct, direct: false });
}

function api_get(ep, path, tmo, params) {
	let cmd = "curl -s --noproxy '*' --max-time " + int(tmo) + (ep.secret != "" ? " -H " + q("Authorization: Bearer " + ep.secret) : "");
	if (params) { cmd += " -G"; for (let k in params) cmd += " --data-urlencode " + q(k + "=" + params[k]); }
	let j = null;
	try { j = json(trim(sh(cmd + " " + q(ep.base + path)))); } catch (e) { j = null; }
	return type(j) == "object" ? j : null;
}

function api_proxies(ep) {
	let j = api_get(ep, "/proxies", 6);
	return j && type(j.proxies) == "object" ? j.proxies : null;
}

function guard_alive(ep, tag, url) {
	let tries = [ [ url, 3000 ], [ "http://cp.cloudflare.com/generate_204", 4000 ] ];
	for (let t in tries) {
		let j = api_get(ep, "/proxies/" + urlenc(tag) + "/delay", int(t[1] / 1000) + 2, { url: t[0], timeout: t[1] });
		if (j && int(j.delay || 0) > 0) return true;
	}
	return false;
}

function cmd_guard() {
	let c = cursor(), ep = null, px = null, events = [];
	for (let x in sections(c, "section")) {
		let sec = x[".name"];
		if (!flag(x.zm_ut_guard) || flag(x.disabled) || flag(x.zm_sub_priority) || s(x.connection_type) != "proxy") continue;
		if (!ep) {
			ep = clash_ep();
			if (!ep || sh("command -v curl") == "") { out({ ok: false }); return; }
			px = api_proxies(ep);
			if (!px) { out({ ok: false }); return; }
		}
		let g = px[group_tag(sec)], auto = g ? s(g.now) : "";
		if (auto == "" || !px[auto] || lc(s(px[auto].type)) != "urltest") continue;
		let leaf = proxy_now(px, auto);
		if (leaf == "" || leaf == auto) continue;
		let url = sec_ext(x).ut_url;
		if (guard_alive(ep, leaf, url)) continue;
		api_get(ep, "/group/" + urlenc(auto) + "/delay", 14, { url, timeout: 5000 });
		let px2 = api_proxies(ep), to = px2 ? proxy_now(px2, auto) : leaf, names = sec_names(c, sec);
		let nm = (t) => s(names[t] || (px[t] && px[t].name) || t), label = trim(s(x.zm_label)) || sec;
		let ev = { sec, label, from: nm(leaf), to: to != leaf && to != auto ? nm(to) : "" };
		push(events, ev);
		sh("logger -t zapret-manager " + q("Forkozz" + (trim(s(x.zm_label)) != "" ? " («" + label + "»)" : "") + ": сервер «" + ev.from + "» перестал отвечать — " +
			(ev.to != "" ? "переключились на «" + ev.to + "»" : "другие серверы тоже не ответили, ждём")));
	}
	out({ ok: true, events });
}

function cmd_heal(sec, act) {
	let hc = cursor(), hm = hc.get_all(CFG, sec) || {};
	if (s(hm.connection_type) != "proxy" || s(hm.disabled) == "1") { out({ ok: true, manual: false, dead: false }); return; }
	let px = proxies(), g = px ? px[group_tag(sec)] : null;
	if (!g || type(g.all) != "array" || s(g.now) == "") { out({ ok: false }); return; }
	let now = s(g.now), names = sec_names(hc, sec);
	if (px[now] && lc(s(px[now].type)) == "urltest") { out({ ok: true, manual: false, dead: false }); return; }
	if (proxy_alive(now)) { out({ ok: true, manual: true, dead: false }); return; }
	let nm = (t) => s(names[t] || t);
	if (act != "switch") { out({ ok: true, manual: true, dead: true, name: nm(now), hold: node_pol() == "hold" }); return; }
	if (node_pol() == "hold") { out({ ok: true, manual: true, dead: true, changed: false, hold: true, name: nm(now) }); return; }
	let pickt = auto_tag(sec, px, g);
	if (!pickt)
		for (let t in g.all) {
			if (t == now) continue;
			if (proxy_alive(t)) { pickt = t; break; }
		}
	if (!pickt) { out({ ok: true, manual: true, dead: true, changed: false, name: nm(now) }); return; }
	let r = jcmd(BIN + " clash_api set_group_proxy " + q(group_tag(sec)) + " " + q(pickt));
	if (type(r) == "object" && (r.error || r.success === false)) { out({ ok: false, manual: true, dead: true, changed: false, name: nm(now) }); return; }
	try { fs.writefile(fell_file(sec), nm(now) + "\n"); } catch (e) {}
	if (node_pol() == "back") { try { fs.mkdir(STATE); } catch (e) {} try { fs.writefile(home_path(sec), sprintf("%J", { tag: now, name: nm(now), next: time() + 600 })); } catch (e) {} }
	else home_drop(sec);
	out({ ok: true, manual: true, dead: true, changed: true, back: node_pol() == "back", name: nm(now), to: px[pickt] && lc(s(px[pickt].type)) == "urltest" ? "" : nm(pickt) });
}

function cmd_latency(sec) {
	if (!proxies()) fail("sing-box не отвечает — Forkozz выключен или ещё запускается");
	if (!lat_running(lat_read(sec))) {
		try { fs.mkdir(STATE); } catch (e) {}
		fs.writefile(lat_path(sec), sprintf("%J", { at: time(), running: true }));
		system("(ucode " + q(sourcepath()) + " latwork " + q(sec) + " >/dev/null 2>&1 &)");
	}
	out({ ok: true, started: true });
}

function latwork(sec) {
	let px = proxies(), g = px ? px[group_tag(sec)] : null, seen = {}, order = [], groups = [];
	function add(t) {
		if (seen[t]) return;
		seen[t] = true;
		let p = px[t];
		if (p && type(p.all) == "array") {
			for (let m in p.all) add(m);
			push(groups, t);
		} else push(order, t);
	}
	if (g && type(g.all) == "array") for (let t in g.all) add(t);
	let mode = lat_mode();
	let delays = {}, done = {}, err = g ? "" : "группа серверов секции ещё не готова — примените настройки";
	let real = {}, blocked = [], rpending = [];
	let eff = (m) => real[m] != null ? real[m] : (index(blocked, m) >= 0 ? 0 : delays[m]);
	let save = (running) => {
		for (let t in groups) {
			let best = 0, all = true;
			for (let m in px[t].all) { if (!done[m]) all = false; else { let d = eff(m); if (d > 0 && (!best || d < best)) best = d; } }
			if (best > 0) delays[t] = best;
			if (all || best > 0) done[t] = true;
		}
		fs.writefile(lat_path(sec), sprintf("%J", { at: time(), running, mode, tested: keys(done), pending: filter([ ...order, ...groups ], (t) => !done[t]), delays, real, blocked, rpending, error: err }));
	};
	if (!g) { save(false); return; }
	if (sh("command -v curl") == "") { err = "на роутере нет curl — задержку проверить нечем"; save(false); return; }
	save(true);

	let addrs = node_addrs(), tcp = filter(order, (t) => !!addrs[t]), other = filter(order, (t) => !addrs[t]);
	let fails = [];
	for (let i = 0; i < length(tcp); i += TCP_PAR) {
		let part = slice(tcp, i, i + TCP_PAR), r = tcp_chunk(addrs, part, 3);
		for (let t in part) { if (r[t]) { delays[t] = r[t]; done[t] = true; } else push(fails, t); }
		save(true);
	}
	for (let i = 0; i < length(fails); i += TCP_PAR) {
		let part = slice(fails, i, i + TCP_PAR), r = tcp_chunk(addrs, part, 6);
		for (let t in part) { if (r[t]) delays[t] = r[t]; done[t] = true; }
		save(true);
	}
	let ep = clash_ep();
	if (length(other) && ep) {
		let r = lat_batch(ep, other, LAT_URLS[0], 5000);
		for (let t in other) { if (r[t]) delays[t] = r[t]; done[t] = true; }
	}
	for (let t in other) done[t] = true;
	if (mode == "real" && ep) {
		let cand = sort(filter(tcp, (t) => delays[t] > 0), (a, b) => delays[a] - delays[b]);
		rpending = slice(cand, 0);
		save(true);
		let again = [];
		for (let i = 0; i < length(cand); i += LAT_PAR) {
			let part = slice(cand, i, i + LAT_PAR), r = lat_batch(ep, part, LAT_URLS[0], 5000);
			for (let t in part) { if (r[t]) real[t] = r[t]; else push(again, t); }
			rpending = filter(rpending, (t) => index(part, t) < 0 || index(again, t) >= 0);
			save(true);
		}
		for (let i = 0; i < length(again); i += LAT_PAR) {
			let part = slice(again, i, i + LAT_PAR), r = lat_batch(ep, part, LAT_URLS[1], 7000);
			for (let t in part) { if (r[t]) real[t] = r[t]; else push(blocked, t); }
			rpending = filter(rpending, (t) => index(part, t) < 0);
			save(true);
		}
		rpending = [];
	}
	let alive = 0;
	for (let t in order) if (eff(t) > 0) alive++;
	if (!alive && length(order)) err = length(blocked) ? "порты серверов открываются, но трафик ни через один не идёт — похоже, их блокирует провайдер" : "ни один сервер не ответил — проверьте интернет на роутере";
	save(false);
}

function cmd_latwork(sec) {
	try { latwork(sec); }
	catch (e) {
		try { fs.writefile(lat_path(sec), sprintf("%J", { at: time(), running: false, tested: [], delays: {}, error: "проверка прервалась: " + s(e.message || e) })); } catch (x) {}
	}
}

function do_select(sec, tag) {
	if (s(tag) == "") return "не выбран сервер";
	let sm = cursor().get_all(CFG, sec) || {}, priority = flag(sm.zm_sub_priority), pingm = ping_on(sm);
	if (priority || pingm) {
		let px = proxies(), g = px ? px[group_tag(sec)] : null;
		if (!g || type(g.all) != "array" || index(g.all, tag) < 0) return "этого сервера нет в секции";
		let auto = priority ? priority_tag(sec) : ping_tag(sec), mf = priority ? priority_manual_file(sec) : ping_manual_file(sec);
		if (tag == auto) { try { fs.unlink(mf); } catch (e) {} }
		else if (fs.writefile(mf, s(tag)) == null) return "не удалось сохранить ручной выбор сервера";
	}
	let j = jcmd(BIN + " clash_api set_group_proxy " + q(group_tag(sec)) + " " + q(tag));
	if (type(j) != "object" || j.error || j.success === false) return s((j && (j.message || j.error)) || "сервер не переключился");
	let px = proxies();
	let fallback = fallback_info(sec, px);
	if ((fallback.direct || fallback.override != "") && !select_proxy(fallback_tag(sec), group_tag(sec))) return "сервер выбран, но резервный выход секции не переключился";
	if ((priority && tag == priority_tag(sec)) || (pingm && tag == ping_tag(sec))) system("(sh /opt/zapret-manager-luci/backend.sh forkop_priority_watch " + q(sec) + " >/dev/null 2>&1 &)");
	try { fs.unlink(fell_file(sec)); } catch (e) {}
	home_drop(sec);
	return "";
}

function cmd_select(sec, tag) {
	let e = do_select(sec, tag);
	if (e != "") fail(e);
	out({ ok: true });
}

function cmd_probe(sec, tag) {
	if (s(tag) == "") fail("не выбран сервер");
	let px = proxies();
	if (!px) fail("sing-box не отвечает — Forkozz выключен или ещё запускается");
	if (!px[tag]) fail("такого сервера нет — обновите список");
	let d = probe_ms(tag, 5000, 2), tcp = 0;
	if (d <= 0) {
		let addrs = node_addrs();
		if (addrs[tag] && sh("command -v curl") != "") tcp = int(tcp_chunk(addrs, [ tag ], 3)[tag] || 0);
	}
	out({ ok: true, alive: d > 0, delay: d, tcp });
}

function cmd_home(sec) {
	let h = home_read(sec);
	if (!h) { out({ ok: true, home: false }); return; }
	if (node_pol() != "back") { home_drop(sec); out({ ok: true, home: false }); return; }
	let px = proxies(), g = px ? px[group_tag(sec)] : null;
	if (!g || type(g.all) != "array") { out({ ok: false }); return; }
	if (index(g.all, h.tag) < 0) { home_drop(sec); out({ ok: true, home: false, gone: true }); return; }
	if (s(g.now) == h.tag) { home_drop(sec); out({ ok: true, home: false }); return; }
	if (time() < int(h.next || 0)) { out({ ok: true, home: true, wait: true }); return; }
	h.next = time() + 600;
	if (!proxy_alive(h.tag)) { try { fs.writefile(home_path(sec), sprintf("%J", h)); } catch (e) {} out({ ok: true, home: true, alive: false }); return; }
	let e = do_select(sec, h.tag);
	if (e != "") { try { fs.writefile(home_path(sec), sprintf("%J", h)); } catch (x) {} out({ ok: false, home: true, error: e }); return; }
	let label = trim(s((cursor().get_all(CFG, sec) || {}).zm_label));
	system("logger -t zapret-manager " + q("Forkozz" + (label != "" ? " («" + label + "»)" : "") + ": сервер «" + s(h.name || h.tag) + "» снова отвечает — вернулись на него"));
	out({ ok: true, home: false, back: true, name: s(h.name || h.tag) });
}

function cmd_hide(sec) {
	let raw = fs.stdin.read("all"), d;
	try { d = json(s(raw)); } catch (e) { fail("не удалось прочитать список"); }
	if (type(d) != "object") fail("пустой запрос");
	let c = cursor();
	if (d.sec != null && s(d.sec) != "") {
		let p = pick(c);
		sec = s(d.sec);
		if (sec != p.sec && index(p.conns, sec) < 0) fail("такой секции нет");
	}
	if (c.get(CFG, sec) != "section") fail("Forkozz ещё не настроен");
	let m = c.get_all(CFG, sec) || {}, mode = sec_mode(m);
	if (mode == "iface") fail("у туннеля нет серверов");
	let names = [];
	if (d.reset) {
		c.delete(CFG, sec, "zm_hide");
		c.delete(CFG, sec, "zm_exclude");
	} else {
		let seen = {};
		for (let n in (type(d.names) == "array" ? d.names : [])) {
			n = s(n);
			if (n == "" || length(n) > 400 || match(n, /[\r\n]/) || seen[n]) continue;
			seen[n] = true;
			push(names, n);
		}
		if (length(names) > 300) fail("слишком много серверов");
		let xstr = null;
		if (d.markers != null) {
			xstr = trim(s(d.markers));
			if (match(xstr, /[\r\n]/) || length(xstr) > 1600) fail("слишком длинный список фраз");
			if (!length(excl_list(xstr))) xstr = "";
		}
		if (mode == "sub") {
			let px0 = proxies(), raw = name_set(sub_raw_names(sec, m)), own = px0 ? name_set(vpn_members(px0, group_tag(sec))) : {}, nn = [];
			for (let n in names) { n = sub_disp(n, raw, px0, own); if (index(nn, n) < 0) push(nn, n); }
			names = nn;
		}
		let f = { m: excl_list(xstr != null ? xstr : m.zm_exclude), h: names };
		if (mode == "links") {
			if (!length(filter(sec_links(m), (l) => !excl_hit(link_name(l), f)))) fail("нельзя скрыть все серверы — тогда Forkozz работать не сможет");
		} else {
			let px = proxies(), g = px ? px[group_tag(sec)] : null;
			if (g && type(g.all) == "array") {
				let real = vpn_members(px, group_tag(sec)), raw = name_set(sub_raw_names(sec, m)), own = name_set(real);
				if (length(real) && !length(filter(real, (t) => !excl_sub_hit(sub_disp(t, raw, px, own), f)))) fail("нельзя скрыть все серверы — тогда Forkozz работать не сможет");
			}
		}
		let hm = home_read(sec), hn = hm ? s(hm.name || hm.tag) : "", fl = "";
		if (hn != "" && (mode == "links" ? excl_hit(hn, f) : excl_sub_hit(hn, f))) home_drop(sec);
		try { fl = trim(s(fs.readfile(fell_file(sec)))); } catch (e) { fl = ""; }
		if (fl != "" && (mode == "links" ? excl_hit(fl, f) : excl_sub_hit(fl, f))) try { fs.unlink(fell_file(sec)); } catch (e) {}
		if (length(names)) c.set(CFG, sec, "zm_hide", names); else c.delete(CFG, sec, "zm_hide");
		if (xstr != null) {
			if (xstr != "") c.set(CFG, sec, "zm_exclude", xstr); else c.delete(CFG, sec, "zm_exclude");
		}
	}
	apply_servers(c, sec);
	c.save(CFG);
	c.commit(CFG);
	out({ ok: true, hidden: length(names) });
}

function nn_ru(n, one, few, many) {
	let a = n % 10, h = n % 100;
	return n + " " + (a == 1 && h != 11 ? one : a >= 2 && a <= 4 && (h < 12 || h > 14) ? few : many);
}

function cmd_secdel(sec) {
	let c = cursor(), p = pick(c);
	if (sec == "" || sec == p.sec) fail("основную секцию удалить нельзя");
	if (index(p.conns, sec) < 0) fail("такой секции нет");
	c.delete(CFG, sec);
	for (let k in [ "dns_outbound_section", "download_lists_via_proxy_section" ])
		if (s(c.get(CFG, "settings", k)) == sec) c.set(CFG, "settings", k, p.sec);
	c.save(CFG);
	c.commit(CFG);
	try { fs.unlink(sub_cache_path(sec)); } catch (e) {}
	out({ ok: true });
}

function cmd_secnames() {
	let p = pick(cursor());
	print(join("\n", [ p.sec, ...p.conns ]), "\n");
}

function mlkem_link(l) {
	return !!match(s(l), /[?&]security=reality([&#]|$)/) && !!match(s(l), /[?&]support-x25519mlkem768=(true|1)([&#]|$)/);
}
function mlkem_core_ok() { return rl_core(); }

const DNS_IN = "127.0.0.42";
function dm_first() {
	let dir = getenv("ZM_FK_CONFDIR"), c = dir ? uci.cursor(dir) : uci.cursor(), r = null;
	c.load("dhcp");
	c.foreach("dhcp", "dnsmasq", (x) => { if (r == null) r = x; });
	return r || {};
}

function cmd_diag() {
	let checks = [];
	function add(v, what, why) { push(checks, { verdict: v, what, why: why || "" }); }
	let en = length(filter(fs.lsdir("/etc/rc.d") || [], (f) => !!match(f, /^S[0-9]+netshift$/))) > 0;
	let nft = sh("nft list table inet " + NFT_TABLE + " >/dev/null 2>&1 && echo y") != "";
	let sbr = sh("pidof sing-box sing-box-core") != "";
	add(nft ? "ok" : "fail", "Служба Forkozz", nft ? "запущена" + (en ? " и включена в автозапуск" : ", но не в автозапуске") : "не запущена — нажмите «Включить»");
	add(sbr ? "ok" : "fail", "sing-box", sbr ? "работает" : "не работает — посмотрите журнал ниже");
	let sb = jcmd(BIN + " get_sing_box_status") || {};
	let ks0 = cursor().get_all(CFG, "settings") || {};
	let dm = fs.access("/usr/sbin/dnsmasq") && fs.access("/etc/init.d/dnsmasq"), dmr = dm && sh("pidof dnsmasq") != "";
	let dsv = rawlist(dm_first().server), dmain = filter(dsv, (x) => index(x, "/") != 0), dzone = filter(dsv, (x) => index(x, "/") == 0);
	let dok = int(sb.dns_configured) == 1 || (length(dmain) == 1 && dmain[0] == DNS_IN);
	let ru = index([ "yandex", "isp" ], s(ks0.zm_ru)) >= 0 ? s(ks0.zm_ru) : "", rz = filter(dzone, (x) => index(RU_ZONES, fwd_zone(x)) >= 0);
	if (!dm) push(checks, { verdict: "fail", what: "DNS роутера", why: "dnsmasq не установлен — у роутера нет DNS, а устройства не получают адреса по DHCP", fix: "dns_fix" });
	else if (!dmr) push(checks, { verdict: "fail", what: "DNS роутера", why: "dnsmasq не запущен — сайты по именам не открываются", fix: "dns_fix" });
	else if (dok && ru != "" && !length(rz) && !flag(ks0.dont_touch_dhcp)) push(checks, { verdict: "warn", what: "DNS роутера", why: "запросы идут через Forkozz, но российские сайты пока не переключены на " + (ru == "yandex" ? "Яндекс DNS" : "DNS провайдера"), fix: "dns_fix" });
	else if (dok) add("ok", "DNS роутера", "запросы идут через Forkozz" + (ru == "yandex" && length(rz) ? ", российские сайты — через Яндекс DNS" : ru == "isp" && length(rz) ? ", российские сайты — через DNS провайдера" : ""));
	else if (flag(ks0.dont_touch_dhcp)) add("warn", "DNS роутера", "включено «Не менять настройки DNS роутера» — направьте dnsmasq на 127.0.0.42 вручную, иначе сайты по доменам пойдут мимо Forkozz");
	else push(checks, { verdict: "fail", what: "DNS роутера", why: "dnsmasq не направлен на Forkozz — сайты по доменам идут мимо него", fix: "dns_fix" });
	let fk = jcmd(BIN + " check_fakeip") || {};
	add(fk.fakeip ? "ok" : "warn", "FakeIP", fk.fakeip ? "работает (" + s(fk.IP) + ")" : "тестовый домен не получил адрес FakeIP");
	if (sbr) {
		let c = cursor(), list = filter(sec_list(c, pick(c)), (x) => x.enabled), many = length(list) > 1;
		for (let x in list) {
			let ms = probe_ms(group_tag(x.name), 5000, 3), what = many ? "Секция «" + x.label + "»" : "Подключение к серверу";
			let dead = x.mode == "iface" ? "туннель " + x.iface + " не отвечает — проверьте его " + (match(x.iface, /^(pptp|l2tp|sstp)-/) ? "в Сеть → Интерфейсы" : "на вкладке AmneziaWG или в Сеть → Интерфейсы") : "сервер не отвечает — проверьте ссылку или выберите другой сервер";
			if (ms <= 0 && x.mode == "links" && length(filter(sec_links(c.get_all(CFG, x.name) || {}), mlkem_link)) && !mlkem_core_ok())
				dead = "сервер на Xray 26.9.8+ пускает только с ключом X25519MLKEM768, а его отправляет лишь расширенный sing-box 2.7.2 или новее";
			add(ms > 0 ? (ms < 1500 ? "ok" : "warn") : "fail", what, ms > 0 ? "отвечает за " + ms + " мс" : dead);
		}
		let bp = bypass_info(c), bn = length(bp.domains) + length(bp.subnets);
		if (bn) add("ok", "Исключения", nn_ru(bn, "строка", "строки", "строк") + " — идут напрямую, мимо всех секций");
	}
	let ks = cursor().get_all(CFG, "settings") || {};
	if (flag(ks.block_leaks) && fs.access(NS_LIB + "/kill_switch.sh")) {
		let gd = sh("nft list table inet NetShiftGuard >/dev/null 2>&1 && echo y") != "";
		add(gd ? "ok" : "warn", "Защита от утечек", gd ? "включена — без VPN трафик выбранных сервисов не уйдёт напрямую" : "включена в настройках, но ещё не работает — перезапустите Forkozz");
	}
	out({ checks });
}


function hs_age(dev) {
	for (let tool in [ "awg", "wg" ]) {
		let o = sh(tool + " show " + q(dev) + " latest-handshakes 2>/dev/null");
		if (o == "") continue;
		let mx = 0;
		for (let l in split(o, "\n")) {
			let f = split(trim(l), /[ \t]+/);
			if (length(f) >= 2 && int(f[1]) > mx) mx = int(f[1]);
		}
		return mx > 0 ? time() - mx : -1;
	}
	return null;
}

function cmd_secstate(probe) {
	let c = cursor(), p = pick(c), px = proxies(), r = [];
	for (let x in sec_list(c, p)) {
		let e = { name: x.name, label: x.label, main: x.main, enabled: x.enabled, mode: x.mode, iface: x.iface,
			state: "", server: "", delay: -1, auto: false, count: 0, hs: null, up: null, sub: "" };
		if (x.mode == "iface") {
			let ex = !!fs.access(NETDIR + "/" + x.iface);
			e.up = ex && trim(s(fs.readfile(NETDIR + "/" + x.iface + "/operstate"))) != "down";
			e.hs = ex ? hs_age(x.iface) : null;
		}
		if (!x.enabled) e.state = "off";
		else if (!px) e.state = "stopped";
		else if (x.mode == "iface") e.state = !e.up ? "bad" : e.hs == null || (e.hs >= 0 && e.hs < 180) ? "ok" : "bad";
		else {
			let g = px[group_tag(x.name)];
			if (!g || type(g.all) != "array") e.state = "wait";
			else {
				let names = sec_names(c, x.name), now = fallback_info(x.name, px).override || s(g.now), cur = now;
				if (px[now] && (lc(s(px[now].type)) == "urltest" || now == priority_tag(x.name) || now == ping_tag(x.name))) { e.auto = true; cur = proxy_now(px, now); }
				e.count = length(vpn_members(px, group_tag(x.name)));
				let ni = node_info(px, names, cur);
				e.server = cur != "" ? ni.name : "";
				e.delay = ni.delay;
				e.state = ni.delay > 0 ? "ok" : "unknown";
				if (x.mode == "sub") { let si = sub_info(x.name); e.sub = s(si.title); }
			}
			if (fallback_info(x.name, px).direct) { e.state = "direct"; e.server = "Напрямую"; e.delay = -1; e.fallback_direct = true; }
		}
		if (probe && px && e.state != "off" && e.state != "wait") {
			let ms = probe_ms(fallback_info(x.name, px).enabled ? fallback_tag(x.name) : group_tag(x.name), 4000, 2);
			e.probed = true;
			e.state = e.fallback_direct ? "direct" : ms > 0 ? "ok" : "bad";
			if (ms > 0) e.delay = ms;
		}
		push(r, e);
	}
	out({ running: !!px, sections: r });
}


function as_arr(v) { return v == null ? [] : type(v) == "array" ? v : [ v ]; }

function dom_hit(host, r) {
	for (let d in as_arr(r.domain)) if (host == lc(d)) return true;
	for (let d in as_arr(r.domain_suffix)) {
		d = lc(replace(s(d), /^\./, ""));
		if (host == d || (length(host) > length(d) && substr(host, length(host) - length(d) - 1) == "." + d)) return true;
	}
	for (let d in as_arr(r.domain_keyword)) if (index(host, lc(d)) >= 0) return true;
	for (let d in as_arr(r.domain_regex)) { try { if (match(host, regexp(s(d)))) return true; } catch (e) {} }
	return false;
}

function rs_file(rs) {
	if (s(rs.type) == "local") return { path: s(rs.path), fmt: s(rs.format || "source") };
	if (s(rs.type) != "remote" || s(rs.url) == "") return null;
	let name = RS_CACHE + "/" + replace(s(rs.tag), /[^A-Za-z0-9_.-]/g, "_") + (s(rs.format) == "binary" ? ".srs" : ".json");
	let st = fs.stat(name);
	if (!st || time() - st.mtime > 86400) {
		try { fs.mkdir(RS_CACHE); } catch (e) {}
		sh("curl -sSL -m 25 -o " + q(name + ".tmp") + " " + q(rs.url) + " && mv -f " + q(name + ".tmp") + " " + q(name));
		st = fs.stat(name);
	}
	return st ? { path: name, fmt: s(rs.format || "binary") } : null;
}

function rs_hit(tag, target, sets) {
	let rs = sets[tag];
	if (!rs) return false;
	let f = rs_file(rs);
	if (!f) return false;
	let r = sh(gml_env() + "sing-box rule-set match -f " + q(f.fmt) + " " + q(f.path) + " " + q(target) + " 2>&1 | cat");
	return !!match(r, /(^|\n)[^\n]*match rules/);
}

function rule_hit(r, host, ip, sets, source) {
	if (r.protocol != null || r.port != null || r.inbound == null && r.outbound == null) return false;
	if (r.type == "logical") return false;
	if (r.source_ip_cidr != null && source != "" && !cidr_hit(source, as_arr(r.source_ip_cidr))) return false;
	let has = false;
	if (host != "" && (r.domain != null || r.domain_suffix != null || r.domain_keyword != null || r.domain_regex != null)) {
		has = true;
		if (dom_hit(host, r)) return true;
	}
	if (ip != "" && r.ip_cidr != null) { has = true; if (cidr_hit(ip, as_arr(r.ip_cidr))) return true; }
	for (let t in as_arr(r.rule_set)) {
		has = true;
		if (host != "" && rs_hit(t, host, sets)) return true;
		if (ip != "" && rs_hit(t, ip, sets)) return true;
	}
	return !has && r.source_ip_cidr != null;
}

let WHERE_T0 = 0;
function where_time() { return time() - WHERE_T0 < 15; }

function dom_under(h, d) { return d != "" && (h == d || (length(h) > length(d) && substr(h, length(h) - length(d) - 1) == "." + d)); }

function ref_base(u) {
	let b = replace(replace(s(u), /[?#].*$/, ""), /^.*\//, "");
	return b != "" ? b : s(u);
}

function cache_tag(u) {
	let n = replace(replace(s(u), /^https?:\/\//, ""), /[^A-Za-z0-9_.-]/g, "_");
	return length(n) > 120 ? substr(n, length(n) - 120) : n;
}

function plain_cache(u, fetch) {
	if (substr(s(u), 0, 1) == "/") return fs.access(u) ? u : null;
	let name = RS_CACHE + "/l_" + cache_tag(u), st = fs.stat(name);
	if (fetch && where_time() && (!st || time() - st.mtime > 86400)) {
		try { fs.mkdir(RS_CACHE); } catch (e) {}
		sh("curl -sSL -m 8 -o " + q(name + ".tmp") + " " + q(u) + " && mv -f " + q(name + ".tmp") + " " + q(name));
		st = fs.stat(name);
	}
	return st ? name : null;
}

function plain_hit(path, host, ip) {
	let best = null, bw = -1;
	for (let l in split(s(fs.readfile(path)), "\n")) {
		l = lc(trim(replace(l, /[#;].*$/, "")));
		if (l == "" || match(l, /[ \t]/) || substr(l, 0, 8) == "include:") continue;
		if (match(l, /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+(\/[0-9]+)?$/)) {
			if (ip != "" && cidr_hit(ip, l)) {
				let b = index(l, "/") >= 0 ? int(split(l, "/")[1]) : 32;
				if (100 + b > bw) { best = l; bw = 100 + b; }
			}
			continue;
		}
		if (host == "") continue;
		let w = l, hit = false;
		if (substr(l, 0, 5) == "full:") { w = substr(l, 5); hit = host == w; }
		else if (substr(l, 0, 8) == "keyword:") { w = substr(l, 8); hit = w != "" && index(host, w) >= 0; }
		else if (match(l, /^(regexp|regex|re):/)) {
			w = replace(l, /^[a-z]+:/, "");
			try { hit = !!match(host, regexp(w)); } catch (e) { hit = false; }
			w = "";
		}
		else { w = replace(replace(l, /^domain:/, ""), /^(\*\.|\.)/, ""); hit = dom_under(host, w); }
		if (hit && length(w) > bw) { best = l; bw = length(w); }
	}
	return best;
}

function srs_hit(rs, host, ip, fetch) {
	let name = RS_CACHE + "/" + replace(s(rs.tag), /[^A-Za-z0-9_.-]/g, "_") + (s(rs.format) == "binary" ? ".srs" : ".json");
	let st = fs.stat(name);
	if (fetch && where_time() && s(rs.url) != "" && (!st || time() - st.mtime > 86400)) {
		try { fs.mkdir(RS_CACHE); } catch (e) {}
		sh("curl -sSL -m 8 -o " + q(name + ".tmp") + " " + q(rs.url) + " && mv -f " + q(name + ".tmp") + " " + q(name));
		st = fs.stat(name);
	}
	let f = st ? { path: name, fmt: s(rs.format || "binary") } : null;
	if (!f) return false;
	for (let t in [ host, ip ]) {
		if (t == "") continue;
		let r = sh(gml_env() + "sing-box rule-set match -f " + q(f.fmt) + " " + q(f.path) + " " + q(t) + " 2>&1 | cat");
		if (match(r, /(^|\n)[^\n]*match rules/)) return true;
	}
	return false;
}

function url_rs(u) {
	return { type: "remote", tag: "u_" + cache_tag(u), url: u, format: url_ext(u) == "json" ? "source" : "binary" };
}

function where_scan(host, ip, win) {
	let out = [];
	if (host == "" && ip == "") return out;
	if (!WHERE_T0) WHERE_T0 = time();
	let c = cursor(), p = pick(c), used = {}, names = {}, items = [];
	try { items = catalog_items(services_list()); } catch (e) { items = []; }
	for (let it in items) for (let t in it.targets) if (names[t] == null) names[t] = it.name;
	let won = false;
	for (let x in sections(c, "section")) {
		let n = x[".name"], byp = n == BYPASS;
		if (!byp && !is_conn(x)) continue;
		let on = byp || n == p.sec || s(x.disabled) != "1", rf = sec_refs(x);
		let st = byp ? "x" : on ? "on" : "dis", label = byp ? "" : sec_label(x, n == p.sec);
		let add = (name, list, entry) => {
			let e = { state: st, sec: label, name, list, entry: entry ?? "", win: false };
			if (!won && on && n == win) { e.win = true; won = true; }
			push(out, e);
		};
		let own = byp ? "Исключения" : "Свой список";
		if (host != "") for (let d in domain_lines(x)) if (dom_under(host, lc(replace(s(d), /^(\*\.|\.)/, "")))) { add(own, "свои домены", d); break; }
		if (ip != "") for (let sn in subnet_lines(x)) if (cidr_hit(ip, sn)) { add(own, "свои IP и подсети", sn); break; }
		for (let cn in rf.c) {
			used["c:" + cn] = true;
			if (srs_hit({ type: "remote", tag: n + "-" + cn + "-community-ruleset", url: SRS_MAIN + "/" + cn + ".srs", format: "binary" }, host, ip, on))
				add(names["c:" + cn] ?? cn, cn + ".srs", "");
			else {
				let xf = plain_cache(PKG_LOCAL_DIR + cn + "_extra.lst", false), xe = xf ? plain_hit(xf, host, ip) : null;
				if (xe != null) add(names["c:" + cn] ?? cn, cn + "_extra.lst", xe);
			}
		}
		for (let k in [ "s", "r", "n" ]) for (let u in rf[k]) {
			used[k + ":" + u] = true;
			if (srs_hit(url_rs(u), host, ip, on)) add(names[k + ":" + u] ?? ref_base(u), ref_base(u), "");
		}
		for (let u in rf.l) {
			used["l:" + u] = true;
			let f = plain_cache(u, on), e = f ? plain_hit(f, host, ip) : null;
			if (e != null) add(names["l:" + u] ?? ref_base(u), ref_base(u), e);
		}
	}
	for (let it in items) {
		let hit = null;
		for (let t in it.targets) {
			if (used[t]) continue;
			let k = substr(t, 0, 1), v = substr(t, 2);
			if (k == "l") {
				let f = plain_cache(v, false), e = f ? plain_hit(f, host, ip) : null;
				if (e != null) { hit = { list: ref_base(v), entry: e }; break; }
			} else if (k == "c") {
				if (srs_hit({ type: "remote", tag: "zmw-" + v + "-community-ruleset", url: SRS_MAIN + "/" + v + ".srs", format: "binary" }, host, ip, false)) { hit = { list: v + ".srs", entry: "" }; break; }
			} else if (k == "s" || k == "r" || k == "n") {
				if (srs_hit(url_rs(v), host, ip, false)) { hit = { list: ref_base(v), entry: "" }; break; }
			}
		}
		if (hit) push(out, { state: "off", sec: "", name: it.name, list: hit.list, entry: hit.entry, win: false });
		if (length(out) >= 40) break;
	}
	return out;
}

function fip_pool() {
	let m = match(s(fs.readfile(NS_LIB + "/constants.sh")), /SB_FAKEIP_INET4_RANGE="([0-9.]+\/[0-9]+)"/);
	return m ? m[1] : FIP_DEF;
}

function fip_hit(a) {
	let n = ip4n(a), p = split(fip_pool(), "/"), b = ip4n(p[0]), w = int(p[1]), size = 1;
	if (n == null || b == null || !(w >= 1 && w <= 32)) return false;
	for (let i = w; i < 32; i++) size *= 2;
	return n >= b && n < b + size;
}

function cmd_route(target, addr, source) {
	WHERE_T0 = time();
	source = trim(s(source));
	if (source != "" && ip4n(source) == null) fail("укажите IPv4-адрес устройства, например 192.168.1.100");
	let cfgj = null;
	try { cfgj = json(s(fs.readfile(SB_CONF))); } catch (e) { cfgj = null; }
	if (type(cfgj) != "object" || type(cfgj.route) != "object") {
		let t = lc(s(target)), v4 = !!match(t, /^[0-9.]+$/);
		out({ action: "", outbound: "", section: "", rule: "", where: where_scan(v4 || index(t, ":") >= 0 ? "" : t, v4 ? t : (ip4n(addr) != null && !fip_hit(addr) ? s(addr) : ""), "") });
		return;
	}
	target = lc(s(target));
	let isip = !!match(target, /^[0-9.]+$/) || index(target, ":") >= 0;
	let host = isip ? "" : target, ip = isip ? target : (ip4n(addr) != null && !fip_hit(addr) ? s(addr) : "");
	if (isip && fip_hit(target)) ip = "";
	let fin = (o) => { o.where = where_scan(host, ip, o.action == "bypass" ? BYPASS : s(o.section)); out(o); };
	let sets = {};
	for (let rs in as_arr(cfgj.route.rule_set)) sets[s(rs.tag)] = rs;
	let c = cursor(), p = pick(c), labels = {};
	for (let x in sec_list(c, p)) { labels[group_tag(x.name)] = x; labels[fallback_tag(x.name)] = x; }
	let px = proxies();
	for (let r in as_arr(cfgj.route.rules)) {
		if (type(r) != "object" || index([ "route", "reject" ], s(r.action || "route")) < 0) continue;
		if (r.domain == "ip.podkop.fyi" || r.domain == "fakeip.podkop.fyi") continue;
		if (!rule_hit(r, host, ip, sets, source)) continue;
		if (r.source_ip_cidr != null && source == "") {
			fin({ action: "source_required", outbound: "", section: "", rule: "" });
			return;
		}
		if (s(r.action) == "reject") {
			let bs = null;
			for (let rt in as_arr(r.rule_set))
				for (let k in keys(labels)) {
					let x = labels[k];
					if (!bs && index(s(rt), x.name + "-") == 0) bs = x;
				}
			fin({ action: "block", outbound: "", section: bs ? bs.name : "", rule: bs ? bs.label : "" });
			return;
		}
		let ob = s(r.outbound);
		if (ob == "direct-out") { fin({ action: "bypass", outbound: ob, section: BYPASS, rule: "Исключения" }); return; }
		let x = labels[ob];
		if (x && ob == fallback_tag(x.name) && fallback_info(x.name, px).direct) {
			fin({ action: "fallback_direct", outbound: "direct-out", section: x.name, rule: x.label });
			return;
		}
		fin({ action: x ? "connection" : "outbound", outbound: ob, section: x ? x.name : "", rule: x ? x.label : ob });
		return;
	}
	fin({ action: "direct", outbound: "direct-out", section: "", rule: "" });
}

function sb_rss() {
	let pid = trim(split(trim(sh("pidof sing-box sing-box-core")), " ")[0] || "");
	if (!match(pid, /^[0-9]+$/)) return null;
	let m = match(s(fs.readfile("/proc/" + pid + "/status")), /VmRSS:[ \t]*([0-9]+)/);
	return m ? int(m[1]) * 1024 : null;
}

function cmd_stats() {
	let ep = clash_ep();
	if (!ep) { out({ ok: false }); return; }
	let auth = ep.secret != "" ? " -H " + q("Authorization: Bearer " + ep.secret) : "";
	let j = jcmd("curl -s --noproxy '*' -m 3" + auth + " " + q(ep.base + "/connections"));
	if (type(j) != "object" || j.downloadTotal == null) { out({ ok: false }); return; }
	out({ ok: true, at: time(), down: int(j.downloadTotal || 0), up: int(j.uploadTotal || 0),
		conns: type(j.connections) == "array" ? length(j.connections) : 0,
		mem: int(j.memory || 0) > 0 ? int(j.memory) : sb_rss() });
}

function cmd_dnsvpn() {
	let ep = clash_ep();
	if (!ep) { out({ error: "у sing-box не включён API — перезапустите Forkozz" }); return; }
	let c = cursor(), st = c.get_all(CFG, "settings") || {}, p = pick(c), sec = s(st.dns_outbound_section);
	if (sec == "" || c.get(CFG, sec) != "section" || !is_conn(c.get_all(CFG, sec) || {})) sec = p.sec;
	if (!sec) { out({ error: "нет секции с подключением" }); return; }
	let urls = filter(map(split(s(fs.stdin.read("all")), "\n"), (x) => trim(x)), (x) => !!match(x, /^https:\/\/[^ \t'"\\`$]+$/));
	if (length(urls) > 16) urls = slice(urls, 0, 16);
	let tag = group_tag(sec), dir = "/tmp/zm-fk-dnsvpn." + s(fs.readlink("/proc/self")), cmd = "";
	if (fs.mkdir(dir) == null) { out({ error: "не удалось создать временную папку" }); return; }
	for (let k = 0; k < length(urls); k++)
		cmd += "(" + lat_cmd(ep, tag, urls[k], 5000) + " > " + q(dir + "/" + k) + " 2>/dev/null) & ";
	sh(cmd + "wait");
	let res = [];
	for (let k = 0; k < length(urls); k++) {
		let d = 0;
		try { d = lat_parse(fs.readfile(dir + "/" + k)); } catch (e) { d = 0; }
		push(res, { url: urls[k], ms: d });
	}
	sh("rm -rf " + q(dir));
	out({ sec, results: res });
}

function cmd_conns() {
	let ep = clash_ep();
	if (!ep) { out({ error: "у sing-box не включён API соединений — перезапустите Forkozz" }); return; }
	let auth = ep.secret != "" ? " -H " + q("Authorization: Bearer " + ep.secret) : "";
	let j = jcmd("curl -s --noproxy '*' -m 4" + auth + " " + q(ep.base + "/connections"));
	if (type(j) != "object") { out({ error: "sing-box не отдал список соединений" }); return; }
	let c = cursor(), labels = {}, names = {};
	for (let x in sec_list(c, pick(c))) labels[x.name] = x.label;
	for (let d in devices()) if (d.name != "") names[d.ip] = d.name;
	let list = [];
	for (let k in (type(j.connections) == "array" ? j.connections : [])) {
		let m = type(k.metadata) == "object" ? k.metadata : {}, ch = type(k.chains) == "array" ? k.chains : [];
		let tag = s(ch[length(ch) - 1]), leaf = s(ch[0]), out_l = "";
		if (tag == "direct-out" || tag == "direct" || tag == "") out_l = "";
		else {
			let sn = replace(replace(replace(replace(tag, /-zm-fallback-out$/, ""), /-zm-priority-out$/, ""), /-zm-ping-out$/, ""), /-out$/, "");
			out_l = labels[sn] != null ? labels[sn] : sn;
		}
		push(list, { src: s(m.sourceIP), dev: names[s(m.sourceIP)] || "", dst: s(m.destinationIP), dport: s(m.destinationPort), host: s(m.host),
			proto: s(m.network), out: out_l, node: leaf != tag ? leaf : "", rule: s(k.rule), up: int(k.upload || 0), down: int(k.download || 0), start: s(k.start) });
	}
	list = sort(list, (a, b) => a.start > b.start ? -1 : (a.start < b.start ? 1 : 0));
	let total = length(list);
	if (total > 400) list = slice(list, 0, 400);
	out({ conns: list, total, truncated: total > 400 });
}

function rl_lat(ep, tags) {
	let ok = lat_batch(ep, tags, LAT_URLS[0], 5000), again = filter(tags, (x) => !ok[x]);
	if (length(again)) {
		let b = lat_batch(ep, again, LAT_URLS[1], 6000);
		for (let x in b) ok[x] = b[x];
	}
	return ok;
}

function cmd_rllearn() {
	let d = null;
	try { d = json(s(fs.stdin.read("all"))); } catch (e) { d = null; }
	if (type(d) != "object") d = {};
	let ep = clash_ep();
	if (!ep) fail("у sing-box не включён API — перезапустите Forkozz");
	let px = proxies();
	if (!px) fail("sing-box не отвечает — Forkozz выключен или ещё запускается");
	let alts = rl_jread(RL_ALT), ln = rl_jread(RL_LEARN), now = time(), force = !!d.force, only = null, seen = {}, pairs = [];
	let max = int(d.max || 0) > 0 ? int(d.max) : RL_MAX;
	if (type(d.hps) == "array") { only = {}; for (let i = 0; i < length(d.hps); i++) only[s(d.hps[i])] = true; }
	for (let a in alts) {
		let x = alts[a];
		if (type(x) != "object" || !px[a] || !px[s(x.tag)] || seen[s(x.hp)]) continue;
		if (only && !only[s(x.hp)]) continue;
		let l = ln[s(x.hp)];
		if (!force && !only && type(l) == "object" && now - int(l.at || 0) < 7 * 86400 && now >= int(l.at || 0)) continue;
		seen[s(x.hp)] = true;
		push(pairs, { alt: a, tag: s(x.tag), hp: s(x.hp), key: !!x.key });
	}
	if (length(pairs) > max) pairs = slice(pairs, 0, max);
	let cur = length(pairs) ? rl_lat(ep, map(pairs, (p) => p.tag)) : {};
	let miss = filter(pairs, (p) => !cur[p.tag]);
	let alt = length(miss) ? rl_lat(ep, map(miss, (p) => p.alt)) : {};
	let works = 0, dead = 0, list = [];
	for (let i = 0; i < length(pairs); i++) {
		let p = pairs[i];
		if (cur[p.tag]) { ln[p.hp] = { k: p.key ? 0 : 1, at: now }; works++; }
		else if (alt[p.alt]) { ln[p.hp] = { k: p.key ? 1 : 0, at: now }; push(list, { name: p.tag, hp: p.hp, key: p.key, ms: alt[p.alt] }); }
		else dead++;
	}
	let hs = keys(ln);
	if (length(hs) > RL_LEARN_MAX) {
		hs = sort(hs, (a, b) => int((ln[a] || {}).at) - int((ln[b] || {}).at));
		for (let i = 0; i < length(hs) - RL_LEARN_MAX; i++) delete ln[hs[i]];
	}
	if (length(pairs)) {
		try { fs.mkdir(STATE); } catch (e) {}
		if (fs.writefile(RL_LEARN, sprintf("%J", ln)) == null) fail("не удалось сохранить результаты проверки");
	}
	out({ ok: true, alts: length(keys(alts)), tested: length(pairs), works, dead, changed: length(list), list });
}

let mode = ARGV[0] || "";
let sec = ARGV[1] || "";
if (mode == "reality") { cmd_reality(ARGV[1], ARGV[2]); exit(1); }
if (mode == "rs_initial") cmd_rs_initial(ARGV[1], ARGV[2]);
if (mode == "rs_cap") cmd_rs_cap(ARGV[1], ARGV[2]);
if (mode == "rs_plan") cmd_rs_plan();
if (mode != "route" && sec != "" && (ml(sec) || !match(sec, /^[A-Za-z0-9_]+$/))) fail("неверное имя секции");
if (sec == "" && index([ "get", "set", "secdel", "route", "diag", "secnames", "secstate", "stats", "conns", "dnsvpn", "fallback_config", "guard", "latmode", "nodepol", "rlinfo", "rllearn" ], mode) < 0) sec = pick(cursor()).sec;

if (mode == "device_setup") cmd_device_setup();
else if (mode == "fallback_config") cmd_fallback_config();
else if (mode == "fallwatch") cmd_fallwatch(sec);
else if (mode == "get") cmd_get(sec);
else if (mode == "set") cmd_set();
else if (mode == "secdel") cmd_secdel(sec);
else if (mode == "secnames") cmd_secnames();
else if (mode == "servers") cmd_servers(sec);
else if (mode == "latency") cmd_latency(sec);
else if (mode == "latwork") cmd_latwork(sec);
else if (mode == "latmode") cmd_latmode(sec);
else if (mode == "nodepol") cmd_nodepol(sec);
else if (mode == "probe") cmd_probe(sec, ARGV[2]);
else if (mode == "home") cmd_home(sec);
else if (mode == "select") cmd_select(sec, ARGV[2]);
else if (mode == "heal") cmd_heal(sec, ARGV[2] || "");
else if (mode == "guard") cmd_guard();
else if (mode == "hide") cmd_hide(sec);
else if (mode == "rlnode") cmd_rlnode(sec);
else if (mode == "rlinfo") cmd_rlinfo();
else if (mode == "rllearn") cmd_rllearn();
else if (mode == "diag") cmd_diag();
else if (mode == "secstate") cmd_secstate(sec == "probe");
else if (mode == "subinfo") cmd_subinfo(sec);
else if (mode == "stats") cmd_stats();
else if (mode == "conns") cmd_conns();
else if (mode == "dnsvpn") cmd_dnsvpn();
else if (mode == "route") cmd_route(ARGV[1], ARGV[2], ARGV[3]);
else fail("неизвестная команда");
ZM_INSTALLER_EOF
chmod 0644 '/opt/zapret-manager-luci/netshift.uc'
cat > '/opt/zapret-manager-luci/b64.uc' << 'ZM_INSTALLER_EOF'
import { open } from 'fs';
let a = ARGV;
if (a[0] == 'enc') {
	let f = open(a[1], 'r');
	if (!f) exit(1);
	if (+a[2] > 0) f.seek(+a[2]);
	let d = f.read(+a[3]);
	f.close();
	print(d ? b64enc(d) : '');
} else if (a[0] == 'dec') {
	let f = open(a[1], 'r');
	if (!f) exit(1);
	let s = f.read('all');
	f.close();
	let d = b64dec(replace(s ?? '', /[\r\n ]/g, ''));
	if (d == null) exit(1);
	let o = open(a[2], 'w');
	if (!o) exit(1);
	o.write(d);
	o.close();
} else exit(2);
ZM_INSTALLER_EOF
chmod 0644 '/opt/zapret-manager-luci/b64.uc'

