			arrow.className = 'zm-log-arrow';
			arrow.textContent = m[1] + ' ';
			div.appendChild(arrow);
			var msgSpan = document.createElement('span');
			var msg = m[2];
			if (/ОШИБКА|error|не удалось/i.test(msg)) msgSpan.className = 'zm-log-msg-error';
			else if (/Готово|успешно|примен[её]н|установлен|удал[её]н|сгенерирован|сохран[её]н|переключ[её]н|обновл[её]н|заверш[её]н/i.test(msg) && !/(^|[\s(«])не\s+(примен[её]н|установлен|удал[её]н|сгенерирован|сохран[её]н|переключ[её]н|обновл[её]н|заверш[её]н)/i.test(msg)) msgSpan.className = 'zm-log-msg-ok';
			else msgSpan.className = 'zm-log-msg-info';
			msgSpan.textContent = msg;
			div.appendChild(msgSpan);
		} else if (/^\s*Подождите/.test(line)) {
			div.className = 'zm-log-wait';
			div.textContent = line.replace(/^\s+/, '');
		} else if (/^\s*(ОШИБКА|\[FAIL\])/.test(line)) {
			div.className = 'zm-log-msg-error';
			div.textContent = line;
		} else if (/^\s*\[ OK \]/.test(line)) {
			div.className = 'zm-log-step zm-log-step-ok';
			div.textContent = line;
		} else if (/^\s*✓/.test(line)) {
			div.className = 'zm-log-step zm-log-step-ok';
			div.textContent = line;
		} else if (/^\s*✗/.test(line)) {
			div.className = 'zm-log-step zm-log-step-bad';
			div.textContent = line;
		} else if (/^\s*[→↻]/.test(line)) {
			div.className = 'zm-log-step';
			div.textContent = line;
		} else if (/^\s+!/.test(line)) {
			div.className = 'zm-log-msg-warn';
			div.textContent = line;
		} else if (/^!!/.test(line)) {
			div.className = 'zm-log-msg-warn';
			div.textContent = line;
		} else {
			div.className = 'zm-log-code';
