function editorBar(ta, o) {
	var orig = ta.value, busy = false;
	var bar = saveBar({ saveLabel: o.saveLabel, text: o.text, onCancel: function() {
		if (o.onCancel) { o.onCancel(); return; }
		ta.value = orig;
		sync();
	}, onSave: function() {
