		function applyPick(only) {
			if (busy) return;
			if (typeof only !== 'string') only = '';
			var steps = [];
			var bw = bootWant();
			if (!only && bootChanged()) steps.push(function() {
				logLines.push('   → ' + (bw ? 'Ставим Bootstrap DNS: ' + bw.split(',').join(', ') : 'Возвращаем Bootstrap DNS в режим «Авто»'));
				return zm.dohBootstrapSet(bw).then(function(res) {
					if (res.error) throw new Error(res.error);
					logLines.push('   ✓ Bootstrap DNS: ' + (res.bootstrap ? res.bootstrap.split(',').join(', ') : 'авто'));
				});
			});
			if ((!only || only === 'prov') && pickProv && pickProv !== curMain()) steps.push(function() {
				var id = pickProv;
				if (id === cur() && data.running && (data.failover || {}).mode === 'backup') {
					logLines.push('   → Делаем ' + label(id) + ' основным — DNS уже идёт через него, перезапуск не нужен');
					zm.renderLog(logEl, logLines.join('\n'));
					return zm.dohSet(id).then(function(res) {
						if (res.error) throw new Error(res.error);
						logLines.push('   ✓ ' + label(id) + ' теперь основной');
					});
				}
				logLines.push('   → Проверяем, отвечает ли ' + label(id));
				zm.renderLog(logEl, logLines.join('\n'));
				return probeOne(id).then(function(r) {
					if (!r.ok && r.why === 'tlsblock' && data.zapret_doh === 'on') logLines.push('   · Соединение обрывает провайдер — пропускаем сервер через «Обход блокировки DoH» Zapret');
					else if (!r.ok) throw new Error(label(id) + ' не отвечает: ' + r.err + '. Настройки не меняли');
					else logLines.push('   ✓ Отвечает за ' + r.ms + ' мс');
					logLines.push('   → Переключаем DNS на ' + label(id) + ' и перезапускаем https-dns-proxy');
					zm.renderLog(logEl, logLines.join('\n'));
					return zm.dohSet(id);
				}).then(function(res) {
					if (res.error) throw new Error(res.error);
					logLines.push(res.stopped ? '   ✓ ' + label(id) + ' выбран — DoH остановлен, DNS пойдёт через этот сервер после «Запустить»' : '   ✓ ' + label(id) + ' применён — DNS на роутере отвечает');
					if (res.boot_note) logLines.push('   · Bootstrap DNS: ' + res.boot_note);
