				var c = pickCanary !== null ? pickCanary : curCanary(), r = pickRu || curRu();
				if (c !== curCanary()) logLines.push('   → ' + (c ? 'Включаем' : 'Выключаем') + ' «Не давать браузерам свой DNS»');
				if (r !== curRu()) logLines.push('   → Российские сайты: ' + RU_TEXT[r]);
