		function fixAct(action, mode, okText) {
			return zm.awgAction(action, mode).then(function(res) {
				if (!res || res.error) { zm.toast((res && res.error) || 'Роутер не ответил', 'error'); return; }
				if (okText) zm.toast(okText, 'info');
				refresh();
