		function loadCustom() {
			var gen = secGen;
			customLoading = true;
			renderCustom();
			stC('list_get', 'custom').then(function(res) {
				if (gen !== secGen) return;
				customLoading = false;
				if (res.error) { customData = null; renderCustom(); zm.toast(res.error, 'error'); return; }
				customData = res;
				customDraft = null;
				customDirty = false;
				renderCustom();
			}).catch(function() { if (gen !== secGen) return; customLoading = false; renderCustom(); });
		}

		function saveCustom(action, arg, okText) {
			if (busy) { zm.toast('Дождитесь окончания текущей операции', 'warning'); return; }
			stC(action, arg).then(function(res) {
				if (res.error) { zm.toast(res.error, 'error'); return; }
				customDraft = null;
				customDirty = false;
				if (res.saved) {
					zm.toast(okText + (res.count ? ' (' + res.count + ')' : ''), 'info');
					loadCustom();
					refresh();
					return;
				}
				zm.toast(okText + ' — применяем правила', 'info');
				lastAction = 'domlist';
				data.running = true;
				data.phase = 'rules';
				follow();
				loadCustom();
			}).catch(function() { zm.toast('Роутер не ответил', 'error'); });
		}

		function saveOn(v) {
