			zm.steerAction(action, arg).then(function(res) {
				if (res.error) { zm.toast(res.error, 'error'); return; }
				exclDraft = null;
				exclDirty = false;
				if (res.saved) {
					zm.toast(okText + (res.count ? ' (' + res.count + ')' : ''), 'info');
					loadExcl();
					refresh();
					return;
				}
				zm.toast(okText + ' — применяем правила', 'info');
				lastAction = 'excl';
