					else log.push('   ✓ ' + lbl(id) + (res.enabled ? ' включён' : ' выключен'));
					next();
				}).catch(function() { failed++; log.push('   ✗ ' + lbl(id) + ': роутер не ответил'); next(); });
			})();
		}

		renderGrid(data.items);
