						: what === 'userlist' ? (on ? 'Стратегия работает только по вашему списку' : 'Стратегия снова работает для всех сайтов, кроме исключений')
						: (on ? 'Блок --wssize добавлен' : 'Блок --wssize убран'), 'info');
