					if (mode !== 'current') rows.sort(function(a, b) { return b.ok - a.ok; });
					var tot = rows.length ? rows[0].tot : (d.control ? d.control.tot : 0), w = 10;
					rows.forEach(function(r) { w = Math.max(w, String(r.name).length); });
