					if (mode === 'custom_dom' && status.custom_domains) kv('Сайты', status.custom_domains);
					L.push('');
					if (d.control) { kv('Без Zapret', d.control.ok + ' / ' + d.control.tot + ' (' + pct(d.control) + ')'); L.push(''); }
					L.push(resPad('№', 4) + resPad('Стратегия', w) + 'Открылось');
