				saveBar.appendChild(E('span', { 'class': 'zm-savebar-text' }, txt));
				saveBar.appendChild(E('div', { 'class': 'zm-savebar-btns' }, btns));
			}
			saveBar.style.display = '';
			zm.dock(saveBar, true);
		}


