					else if (rs.n) rsNow = 'Сохранено ' + nn(rs.n, 'список', 'списка', 'списков') + ', ' + (rs.bytes < 1048576 ? Math.max(1, Math.round(rs.bytes / 1024)) + ' КБ' : (rs.bytes / 1048576).toFixed(1).replace('.', ',') + ' МБ') +
						(rs.at ? ', обновлены ' + new Date(rs.at * 1000).toLocaleDateString('ru-RU', { day: 'numeric', month: 'long' }) : '') + '.';
					else rsNow = 'Копии появятся через несколько минут после запуска Forkozz.';
				}
				miscCard.appendChild(sw(rs.on, 'Хранить копии списков на роутере', 'После перезагрузки sing-box сразу запустится с сохранёнными списками, даже если GitHub недоступен, а свежие скачает сам. Занимает обычно десятки КБ.' + (rsNow ? ' ' + rsNow : ''), function() {
					if (rs.busy) return;
					rs.busy = true;
					var on = !rs.on;
					zm.forkopAction('rssnap', on ? 'on' : 'off').then(function(res) {
						rs.busy = false;
						if (!res || res.error) { zm.toast((res && res.error) || 'Не удалось сохранить настройку', 'error'); return; }
						rs.on = !!res.on;
						if (!rs.on) { rs.n = 0; rs.bytes = 0; rs.at = 0; rs.cap = ''; }
						zm.toast(rs.on ? 'Копии списков включены — появятся через несколько минут' : 'Копии списков выключены и удалены', 'info');
						renderSet();
					}).catch(function() { rs.busy = false; });
				}));
			}
			var extra = (cfg && cfg.extra) || [];
			if (extra.length) miscCard.appendChild(E('p', { 'class': 'zm-hint' }, 'Есть ещё ' + nn(extra.length, 'секция', 'секции', 'секций') + ', созданных раньше (' + extra.map(function(x) { return x.label; }).join(', ') + '). Они работают как прежде.'));

			sbCard.innerHTML = '';
			sbCard.appendChild(E('h3', {}, 'sing-box'));
			var sv = st.singbox_pkg, vars = SB_VARS.filter(function(x) { return x.id !== 'lite' || st.sb_lite !== 'arch' || sv === 'lite'; }), has = !!st.singbox;
			var curVar = vars.some(function(x) { return x.id === sv; }) ? sv : '';
			var restartNote = st.enabled ? 'Forkozz перезапустится — на полминуты выбранные сервисы пойдут напрямую.\n' : '';
			sbCard.appendChild(row('Версия', has ? E('span', {}, [ E('b', {}, SB_NAMES[sv] || 'установлен вручную'), ' · ' + st.singbox ]) : E('span', {}, 'не установлен')));
			if (has && sv === 'extended') sbCard.appendChild(E('p', { 'class': 'zm-hint zm-ab-warn' }, 'Сборку sing-box-extended (shtorm-7) панель больше не ставит и не обновляет. Выберите «Расширенный облегчённый» — те же протоколы, а места нужно в 3 раза меньше.'));
			var sbSeg = seg(vars, curVar, function(v) {
				var it = vars.filter(function(x) { return x.id === v; })[0];
				if (v === 'lite' && st.sb_lite === 'engine') { zm.toast('Этот движок Forkozz ещё не умеет ставить облегчённый расширенный sing-box — сначала обновите Forkozz', 'warning', 8000); return; }
				return zm.ask((has ? 'Заменить sing-box на ' : 'Установить ') + it.label.toLowerCase() + (has ? '' : ' sing-box') + '?\n\n' + it.warn + restartNote + (has ? 'Если новый sing-box не установится, останется прежний.' : '')).then(function(ok) { if (!ok) return; act('singbox', v); });
			});
			sbSeg.classList.add('zm-seg-wrap');
			sbCard.appendChild(row('Вариант', sbSeg));
			if (has && curVar) {
				var cur = vars.filter(function(x) { return x.id === curVar; })[0];
				sbCard.appendChild(E('div', { 'class': 'zm-actions' }, [ E('button', { 'class': 'cbi-button', 'disabled': busy ? '' : null, 'click': function() {
					return zm.ask('Переустановить ' + cur.label.toLowerCase() + ' sing-box?\n\n' + (curVar === 'lite' ? 'Скачается свежая сборка с GitHub (около 10–17 МБ).\n' : 'Пакет скачается из репозитория OpenWrt заново.\n') + restartNote + 'Если не установится, останется прежний.').then(function(ok) { if (!ok) return; act('singbox_reinstall', curVar); });
				} }, curVar === 'lite' ? 'Переустановить (обновить сборку)' : 'Переустановить') ]));
			}
			sbCard.appendChild(E('div', { 'class': 'zm-kv' }, vars.map(function(x) {
				return row(x.label, E('span', { 'class': 'zm-hint', 'style': 'margin:0' }, x.hint));
			})));
			sbCard.appendChild(row('Журнал', seg(LOG_LV, LOG_LV.some(function(x) { return x.id === draft.log_level; }) ? draft.log_level : '', function(v) { set('log_level', v); })));
			sbCard.appendChild(hint('Сколько sing-box пишет в системный журнал. По умолчанию выключен — меньше нагрузки на память и флеш роутера; ошибки запуска Forkozz всё равно видно. «Подробный» и «Отладка» — чтобы разобраться с проблемой, потом верните «Выключен».'));
		}

		function runDiag(quiet) {
			if (diagBusy) return;
			diagBusy = true;
			renderCheck();
			if (!quiet) zm.toast('Проверяем…', 'warning');
			zm.forkopAction('diag', '').then(function(res) {
				diagBusy = false;
				diag = res && !res.error ? res : null;
				if (res && res.error && !quiet) zm.toast(res.error, 'error');
				renderCheck();
				if (!quiet) zm.toast('Проверка закончена', 'info');
			}).catch(function() { diagBusy = false; renderCheck(); });
		}

		function renderCheck() {
			renderRoute();
			checkCard.innerHTML = '';
			var show = st.installed && configured() && st.enabled && !busy;
			checkCard.style.display = show ? '' : 'none';
			if (!show) return;
			checkCard.appendChild(E('h3', {}, 'Проверка'));
			checkCard.appendChild(E('p', { 'class': 'zm-hint' }, 'Роутер проверит службу, sing-box, DNS и сервер каждой секции.'));
			if (diag && diag.checks) {
				var allChecks = diag.checks.concat(diag.extra || []);
				var fails = allChecks.filter(function(c) { return c.verdict === 'fail'; }).length, warns = allChecks.filter(function(c) { return c.verdict === 'warn'; }).length;
				checkCard.appendChild(chkRow(E('span', { 'class': 'zm-label' }, 'Итог'), fails ? badge('zm-bad', 'есть поломка') : warns ? badge('zm-warn', 'работает, есть замечания') : badge('zm-ok', 'всё в порядке')));
				var CLS = { ok: 'zm-ok', warn: 'zm-warn', fail: 'zm-bad' }, TXT = { ok: 'ок', warn: 'внимание', fail: 'ошибка' };
				var FIX_TEXT = { tsc_clean: 'Убрать остатки', src_fix: 'Убрать лишнее и перезапустить', dns_fix: 'Починить DNS' };
				allChecks.forEach(function(c) {
					if (!CLS[c.verdict]) return;
					checkCard.appendChild(chkRow(badge(CLS[c.verdict], TXT[c.verdict]), E('span', {}, [ String(c.what || '') + (c.why ? ' — ' + c.why : ''),
						FIX_TEXT[c.fix] ? E('div', { 'style': 'margin-top:6px' }, [ E('button', { 'class': 'cbi-button cbi-button-action', 'disabled': busy ? '' : null, 'click': function() { act(c.fix); } }, FIX_TEXT[c.fix]) ]) : '' ])));
				});
			}
			checkCard.appendChild(E('div', { 'class': 'zm-actions' }, [
				E('button', { 'class': 'cbi-button', 'disabled': diagBusy ? '' : null, 'click': function() { runDiag(false); } }, diagBusy ? 'Проверяем…' : 'Проверить'),
				E('button', { 'class': 'cbi-button' + (connKind === 'conns' ? ' cbi-button-action' : ''), 'disabled': connBusy ? '' : null, 'click': function() { loadConns('conns'); } }, 'Соединения'),
				E('button', { 'class': 'cbi-button' + (connKind === 'sites' ? ' cbi-button-action' : ''), 'disabled': connBusy ? '' : null, 'click': function() { loadConns('sites'); } }, 'Сайты сейчас'),
				connKind ? E('button', { 'class': 'cbi-button', 'click': function() { connKind = null; connRes = null; renderCheck(); } }, 'Скрыть') : ''
			]));
			if (!connKind) return;
			checkCard.appendChild(E('p', { 'class': 'zm-hint' }, connKind === 'conns'
				? 'Что прямо сейчас идёт через sing-box: устройство, адрес назначения и секция (или «напрямую»). Список берётся из памяти роутера в момент нажатия, никуда не сохраняется и не отправляется.'
				: 'Сайты, с которыми устройства соединены прямо сейчас, и через какую секцию они идут. Берутся из текущих соединений sing-box, никуда не сохраняются.'));
			if (connBusy || !connRes) { checkCard.appendChild(E('p', { 'class': 'zm-hint' }, 'Загружаем…')); return; }
			if (connRes.error) { checkCard.appendChild(E('p', { 'class': 'zm-hint' }, '⚠ ' + connRes.error)); return; }
			var LIMIT = 200, lines = [], total = 0, conns = connRes.conns || [];
			function outBadge(o) { return badge(o ? 'zm-ok' : 'zm-off', o ? o : 'напрямую'); }
			if (connKind === 'conns') {
				var agg = {}, keys = [];
				conns.forEach(function(c) {
					var k = [ c.src, c.host || c.dst, c.dport, c.proto, c.out ].join('|');
					if (!agg[k]) { agg[k] = { c: c, n: 0 }; keys.push(k); }
					agg[k].n++;
				});
				total = keys.length;
				keys.slice(0, LIMIT).forEach(function(k) {
					var a = agg[k], c = a.c, dst = c.host || c.dst, v6 = !c.host && String(c.dst).indexOf(':') >= 0;
					lines.push([ outBadge(c.out), (c.dev ? c.dev + ' (' + c.src + ')' : String(c.src)) + ' → ' + (c.dport ? (v6 ? '[' + dst + ']' : dst) + ':' + c.dport : dst) + ' · ' + String(c.proto || '') + (a.n > 1 ? ' · ×' + a.n : '') ]);
				});
				if (!total) checkCard.appendChild(E('p', { 'class': 'zm-hint' }, 'Соединений сейчас нет. Откройте на устройстве выбранный сервис и нажмите «Соединения» ещё раз.'));
				else checkCard.appendChild(row('Соединений', E('span', {}, String(connRes.total || conns.length) + (connRes.truncated ? ' · показана часть' : ''))));
			} else {
				var sites = {}, order = [];
				conns.forEach(function(c) {
					var h = c.host || c.dst;
					if (!h) return;
					var k = h + '|' + (c.out || '');
					if (!sites[k]) { sites[k] = { h: h, out: c.out, n: 0, dev: {} }; order.push(k); }
					sites[k].n++;
					sites[k].dev[c.dev || c.src] = true;
				});
				order.sort(function(a, b) { return (sites[a].out ? 0 : 1) - (sites[b].out ? 0 : 1) || (sites[a].h < sites[b].h ? -1 : sites[a].h > sites[b].h ? 1 : 0); });
				total = order.length;
				order.slice(0, LIMIT).forEach(function(k) {
					var x = sites[k], dv = Object.keys(x.dev);
					lines.push([ outBadge(x.out), x.h + ' · ' + (dv.length > 2 ? dv.length + ' устройства' : dv.join(', ')) + (x.n > 1 ? ' · ×' + x.n : '') ]);
				});
				if (!total) checkCard.appendChild(E('p', { 'class': 'zm-hint' }, 'Сейчас ни один сайт не открыт. Откройте на устройстве любой сайт и нажмите «Сайты сейчас» ещё раз.'));
			}
			if (lines.length) {
				var box = E('div', { 'style': 'max-height:340px; overflow:auto; margin-top:8px; padding:4px 12px; border:1px solid rgba(127,127,127,.2); border-radius:10px' });
				lines.forEach(function(l) {
					box.appendChild(E('div', { 'class': 'zm-row', 'style': 'flex-wrap:nowrap; align-items:flex-start' }, [ l[0], E('span', { 'style': 'min-width:0; overflow-wrap:anywhere; font-family:ui-monospace,SFMono-Regular,Menlo,Consolas,monospace; font-size:12px' }, [ l[1] ]) ]));
				});
				checkCard.appendChild(box);
				if (total > LIMIT) checkCard.appendChild(E('p', { 'class': 'zm-hint' }, 'Показаны первые ' + LIMIT + ' из ' + total + '.'));
			}
		}

		function loadConns(kind) {
			if (connBusy) return;
			connKind = kind; connRes = null; connBusy = true;
			renderCheck();
			zm.forkopAction('conns', '').then(function(res) {
				connBusy = false; connRes = res || { error: 'Роутер не ответил' };
				renderCheck();
			}).catch(function() { connBusy = false; connRes = { error: 'Роутер не ответил' }; renderCheck(); });
		}

		function routeVerdict(r) {
			var sl = secs(), rs = sl.filter(function(s) { return s.name === r.section; })[0] || (sl.length === 1 ? sl[0] : null);
			var lines = [], via = rs ? (rs.mode === 'iface' ? 'интерфейс ' + (rs.iface || '') : 'VPN') : 'VPN';
			if (r.action === 'source_required') return { tone: 'warn', cls: 'zm-warn', label: 'нужен IP устройства', title: 'маршрут зависит от устройства', note: 'Укажите IP устройства над полем сайта и повторите проверку.' };
			if (r.source) lines.push([ 'Устройство', r.source ]);
			var wh = (r.where || []).map(function(x) { var y = {}; for (var k in x) y[k] = x[k]; if (sl.length < 2 && y.state === 'on') y.sec = ''; return y; });
			var whl = zm.routeWhere(wh, { tags: { x: 'исключение', on: 'действует', dis: 'секция выключена', off: 'сервис не выбран' } });
			var offSvc = wh.filter(function(x) { return x.state === 'off'; }).map(function(x) { return x.name; }).filter(function(n, i, a) { return n && a.indexOf(n) === i; });
			if (r.verdict === 'bypass') {
				if (whl) lines.push([ 'Списки', whl ]);
				return { tone: 'warn', cls: 'zm-warn', label: 'напрямую · исключение', title: 'адрес в исключениях — идёт мимо VPN', lines: lines,
					note: 'Проверьте вкладки «Исключения» и «Устройства → Мимо Forkozz». Чтобы запрос снова шёл через VPN, уберите соответствующее исключение и сохраните.' };
			}
			if (r.verdict === 'off') return { tone: 'off', cls: 'zm-off', label: 'Forkozz не работает', title: 'запрос пойдёт напрямую', note: 'Запустите Forkozz и проверьте ещё раз.' };
			if (r.probe) lines.push([ 'Проверен', [ E('b', {}, r.probe), ' — у самого ' + r.target + ' нет адреса, а правило списка действует и на поддомены' ] ]);
			if (r.addr && !r.ip) lines.push([ 'Адрес', r.how === 'fakeip' ? [ r.addr, ' (подменный — домен есть в списках Forkozz)' ] : r.addr ]);
			if (r.how === 'subnet') lines.push([ 'Совпадение', 'адрес входит в подсети Forkozz' ]);
			if (sl.length > 1 && rs) lines.push([ 'Секция', rs.label ]);
			else if (r.rule) lines.push([ 'Правило', r.rule ]);
			if (whl) lines.push([ 'Списки', whl ]);
			if (r.action === 'fallback_direct') return { tone: 'warn', cls: 'zm-warn', label: 'напрямую · VPN недоступны', title: 'сработал резервный прямой выход секции', lines: lines,
				note: 'Forkozz продолжает проверять VPN раз в 2 минуты и вернёт секцию через рабочий сервер после восстановления.' };
			if (r.verdict === 'proxy') {
				if (rs) lines.push([ 'Выход', secConn(rs) ]);
				else if (r.outbound) lines.push([ 'Выход', r.outbound ]);
				if (servers && cfg && rs && rs.name === cfg.sec && cfg.mode !== 'iface') { try { var S = srvState(); if (S.curTag) lines.push([ 'Сервер сейчас', nodeName(S.cur) ]); } catch (e) {} }
				return { tone: 'ok', cls: 'zm-ok', label: rs && rs.mode === 'iface' ? 'через ' + (/^zmwarp/.test(rs.iface || '') ? 'WARP' : 'интерфейс') : 'через VPN', title: 'идёт через ' + (rs && sl.length > 1 ? '«' + rs.label + '» · ' : '') + via, lines: lines };
			}
			if (r.verdict === 'block') {
				return { tone: 'bad', cls: 'zm-bad', label: 'заблокировано', title: rs ? 'секция «' + rs.label + '» сейчас без рабочего подключения' : 'правило блокирует этот адрес', lines: lines,
					note: rs ? 'Пока подписка или серверы секции не загрузятся, её сайты блокируются, а не уходят напрямую. Проверьте ссылку на подписку и нажмите «Обновить серверы подписки».' : 'Так работает блокировка DoH или секция-блокировщик.' };
			}
			if (r.verdict === 'direct' && (r.action === 'connection' || r.action === 'outbound')) {
				return { tone: 'warn', cls: 'zm-warn', label: 'напрямую', title: 'по правилам идёт через ' + (rs ? '«' + rs.label + '»' : 'VPN') + ', но устройство получило настоящий адрес', lines: lines,
					note: r.ip ? 'Адреса из списков попадают в файрвол после загрузки списков — нажмите «Обновить списки сейчас» на вкладке «Сервисы».' : 'Устройство помнит старый адрес сайта: очистите DNS-кэш, перезапустите браузер или подождите пару минут.' };
			}
			if (r.verdict === 'direct') {
				if (r.outbound && r.outbound !== 'direct' && r.outbound !== 'direct-out') lines.push([ 'По настройкам', r.outbound ]);
				return { tone: 'warn', cls: 'zm-warn', label: 'напрямую', title: 'Forkozz этот адрес не трогает', lines: lines,
					note: offSvc.length ? 'Адрес есть в списке ' + (offSvc.length > 1 ? 'сервисов ' : 'сервиса ') + offSvc.map(function(n) { return '«' + n + '»'; }).join(', ') + ' — выберите его в секции на вкладке «Сервисы», чтобы он шёл через VPN.'
						: r.ip ? 'Чтобы IP шёл через VPN, добавьте его подсеть на вкладке «Сервисы».' : 'Чтобы сайт шёл через VPN, включите его сервис или добавьте домен на вкладке «Сервисы». Если домен уже в списке — устройство могло запомнить старый адрес: очистите DNS-кэш или подождите пару минут.' };
			}
			if (r.verdict === 'noaddr') {
				var onAny = wh.some(function(x) { return x.state === 'on'; });
				return { tone: onAny ? 'ok' : 'warn', cls: onAny ? 'zm-ok' : 'zm-warn', label: 'у имени нет адреса', title: onAny ? 'домен в списке — его поддомены пойдут через VPN' : 'по самому имени никто не ходит', lines: lines,
					note: 'DNS роутера работает, но у «' + r.target + '» нет собственного IP-адреса: сайты и приложения ходят на его поддомены (например, static.' + r.target + '). Введите поддомен, чтобы увидеть путь.' };
			}
			return { tone: 'bad', cls: 'zm-bad', label: 'не удалось определить', title: 'роутер не смог узнать адрес домена', lines: lines, note: 'Проверьте, что DNS роутера работает (кнопка «Проверить» выше).' };
		}

		function routeByDev() {
			return routeNeed || ((cfg && cfg.excl) || []).length > 0 || ((cfg && cfg.sections) || []).some(function(x) {
				return !!x && x.enabled && ((x.full || []).length > 0 || (x.all || []).length > 0);
			});
		}

		function renderRoute() {
			var show = st.installed && configured() && st.enabled && !busy;
			routeCard.style.display = show ? '' : 'none';
			if (!show) return;
			if (!routeBox) routeBox = zm.routeCheck({
				call: function(v) {
					return zm.forkopAction('route', v + '|' + (routeDev ? routeSource.trim() : '')).then(function(r) {
						if (r && r.action === 'source_required' && !routeDev) { routeNeed = true; setTimeout(renderRoute, 0); }
						return r;
					});
				},
				verdict: routeVerdict
			});
			var byDev = routeByDev();
			if (routeBox.parentNode === routeCard && byDev === routeDev) return;
			if (routeDev && !byDev) routeBox.reset();
			routeDev = byDev;
			routeCard.innerHTML = '';
			routeCard.appendChild(E('h3', {}, 'Куда пойдёт запрос'));
			routeCard.appendChild(E('p', { 'class': 'zm-hint' }, byDev
				? 'Введите сайт или IP-адрес назначения. Часть правил действует только для выбранных устройств — укажите также IP устройства, с которого идёт запрос.'
				: 'Введите сайт или IP-адрес назначения.'));
			if (byDev) {
				var sourceInput = E('input', { 'type': 'text', 'class': 'cbi-input-text', 'placeholder': '192.168.1.100', 'value': routeSource });
				sourceInput.addEventListener('input', function() { routeSource = sourceInput.value; routeBox.reset(); });
				routeCard.appendChild(row('IP устройства', sourceInput));
			}
			routeCard.appendChild(routeBox);
		}

		function renderPanes() {
			renderConn();
			renderServers();
			renderSvc();
			renderByp();
			renderDev();
			renderSet();
			renderMain();
			renderSaveBar();
		}

		function renderAll() {
			renderMain();
			renderTabs();
			renderSections();
			renderPanes();
			renderCheck();
		}

		panes.conn.appendChild(connCard);
		panes.conn.appendChild(srvCard);
		panes.conn.appendChild(checkCard);
		panes.conn.appendChild(routeCard);
		panes.svc.appendChild(svcCard);
		panes.svc.appendChild(ownCard);
		panes.dev.appendChild(allCard);
		panes.dev.appendChild(fullCard);
		panes.dev.appendChild(exclCard);
		panes.set.appendChild(dnsCard);
		panes.set.appendChild(netCard);
		panes.set.appendChild(miscCard);
		panes.set.appendChild(sbCard);
		panes.set.appendChild(panelCard);
		panes.byp.appendChild(bypCard);
		[ mainCard, hostsWarn, logEl, secCard, tabBar, panes.conn, panes.svc, panes.byp, panes.dev, panes.set, saveBar ].forEach(function(n) { wrap.appendChild(n); });

		syncAreas();
		renderAll();
		if (st.busy) { lastAct = ''; follow(); }
		else {
			if (st.running && secLive()) loadServers();
			loadSecState(!!st.running);
		}
		return wrap;
	}
